            return "boundary_hazard_decision";
        case ColdPathDiagnosticBucket::CacheKeyProgram:
            return "cache_key_program";
        case ColdPathDiagnosticBucket::CacheKeyVaoLayout:
            return "cache_key_vao_layout";
        case ColdPathDiagnosticBucket::CacheKeyFbo:
            return "cache_key_fbo";
        case ColdPathDiagnosticBucket::CacheKeyBindings:
            return "cache_key_bindings";
        case ColdPathDiagnosticBucket::CacheKeyFixedState:
            return "cache_key_fixed_state";
        case ColdPathDiagnosticBucket::CacheKeyOther:
            return "cache_key_other";
        case ColdPathDiagnosticBucket::ProgramVaoFboFp64Sidecars:
            return "program_vao_fbo_fp64_sidecars";
        case ColdPathDiagnosticBucket::ProgramVaoFboPrimitiveCounters:
            return "program_vao_fbo_primitive_counters";
        case ColdPathDiagnosticBucket::ProgramVaoFboFrontendVaoSource:
            return "program_vao_fbo_frontend_vao_source";
        case ColdPathDiagnosticBucket::ProgramVaoFboVaoSource:
            return "program_vao_fbo_vao_source";
        case ColdPathDiagnosticBucket::ProgramVaoFboGenericAttributes:
            return "program_vao_fbo_generic_attributes";
        case ColdPathDiagnosticBucket::ProgramVaoFboBoundFbo:
            return "program_vao_fbo_bound_fbo";
        case ColdPathDiagnosticBucket::ProgramVaoFboLayoutCache:
            return "program_vao_fbo_layout_cache";
        case ColdPathDiagnosticBucket::ProgramVaoFboLayoutApply:
            return "program_vao_fbo_layout_apply";
        case ColdPathDiagnosticBucket::SnapshotEstimate:
            return "snapshot_estimate";
        case ColdPathDiagnosticBucket::Count:
            break;
    }
    return "unknown";
}

static void coldPathHashU64(std::uint64_t& hash, std::uint64_t value) {
    hash ^= value;
    hash *= 1099511628211ull;
}

static void coldPathHashPointer(std::uint64_t& hash, const void* ptr) {
    coldPathHashU64(
        hash,
        static_cast<std::uint64_t>(
            reinterpret_cast<std::uintptr_t>(ptr)));
}

static bool mslUsesArgumentBuffer(const std::string& msl) {
    return msl.find("spvDescriptorSetBuffer") != std::string::npos;
}

static bool mslUsesArgumentBuffer(const std::string* msl) {
    return msl != nullptr && mslUsesArgumentBuffer(*msl);
}

static void refreshProgramMslArgumentBufferMetadata(GLProgramObject& program) {
    program.vertexMslUsesArgumentBuffer =
        mslUsesArgumentBuffer(program.vertexMSL);
    program.fragmentMslUsesArgumentBuffer =
        mslUsesArgumentBuffer(program.fragmentMSL);
    program.gsPassThroughVertexMslUsesArgumentBuffer =
        mslUsesArgumentBuffer(program.gsPassThroughVertexMSL);
    program.gsPassThroughFragmentMslUsesArgumentBuffer =
        mslUsesArgumentBuffer(program.gsPassThroughFragmentMSL);
}

static void assignTranslatedDrawProgramMsl(TranslatedDrawInfo& tdi,
                                           const GLProgramObject& program) {
    tdi.vertexMSL = &program.vertexMSL;
    tdi.fragmentMSL = &program.fragmentMSL;
    tdi.vertexMslUsesArgumentBuffer =
        program.vertexMslUsesArgumentBuffer;
    tdi.fragmentMslUsesArgumentBuffer =
        program.fragmentMslUsesArgumentBuffer;
}

struct ColdPathDiagnosticProfile {
    bool enabled = std::getenv("APPGL_7G_COLD_PATH_PROFILE") != nullptr;
    std::array<ColdPathDiagnosticBucketStats,
               static_cast<std::size_t>(ColdPathDiagnosticBucket::Count)>
        buckets{};

    std::uint64_t draws = 0;
    std::uint64_t phase2Candidates = 0;
    std::uint64_t phase2PlanHits = 0;
    std::uint64_t phase2PlanMisses = 0;
    std::uint64_t phase2PlanRejects = 0;
    std::uint64_t phase2PlanForceMisses = 0;
    std::uint64_t phase2MemoLookups = 0;
    std::uint64_t phase2MemoSupported = 0;
    std::uint64_t phase2MemoHits = 0;
    std::uint64_t phase2MemoMisses = 0;
    std::uint64_t programFingerprintLookups = 0;
    std::uint64_t programFingerprintHits = 0;
    std::uint64_t programFingerprintMisses = 0;
    std::uint64_t programFingerprintFallbacks = 0;
    std::uint64_t preflightSnapshots = 0;
    std::uint64_t preflightGenericPrepared = 0;
    std::uint64_t preflightGenericUnprepared = 0;
    std::uint64_t snapshotSamples = 0;
    std::uint64_t snapshotBytes = 0;
    std::uint64_t maxSnapshotBytes = 0;
    std::uint64_t mergeBytes = 0;
    std::uint64_t maxMergeBytes = 0;
    std::uint64_t phase2KeyRepeats = 0;
    std::uint64_t programRepeats = 0;
    std::uint64_t vaoFboRepeats = 0;
    std::uint64_t programVaoFboRepeats = 0;
    std::uint64_t boundaryRepeats = 0;
    std::uint64_t saturatedSurfaces = 0;

    std::unordered_set<std::uint64_t> phase2Keys;
    std::unordered_set<std::uint64_t> programKeys;
    std::unordered_set<std::uint64_t> vaoFboKeys;
    std::unordered_set<std::uint64_t> programVaoFboKeys;
    std::unordered_set<std::uint64_t> boundaryKeys;

    static constexpr std::size_t kMaxTrackedKeys = 1u << 20;

    void record(ColdPathDiagnosticBucket bucket, double us) {
        if (!enabled) {
            return;
        }
        auto& stats = buckets[static_cast<std::size_t>(bucket)];
        ++stats.count;
        stats.totalUs += us;
    }

    void record(ColdPathDiagnosticBucket bucket,
                GLDrawProfileTimePoint start,
                GLDrawProfileTimePoint end) {
        record(bucket, glDrawProfileElapsedUs(start, end));
    }

    void recordRepeat(std::unordered_set<std::uint64_t>& surface,
                      std::uint64_t key,
                      std::uint64_t& repeats) {
        if (!enabled) {
            return;
        }
        auto found = surface.find(key);
        if (found != surface.end()) {
            ++repeats;
            return;
        }
        if (surface.size() >= kMaxTrackedKeys) {
            ++saturatedSurfaces;
            return;
        }
        surface.insert(key);
    }

    void recordPreflight(bool hasPreflight, bool genericPrepared) {
        if (!enabled || !hasPreflight) {
            return;
        }
        ++preflightSnapshots;
        if (genericPrepared) {
            ++preflightGenericPrepared;
        } else {
            ++preflightGenericUnprepared;
        }
    }

    void recordDrawKeys(const TranslatedDrawInfo& tdi,
                        GLuint vaoName,
                        std::uint32_t vaoGeneration,
                        GLuint drawFboName) {
        if (!enabled) {
            return;
        }
        ++draws;

        std::uint64_t programKey = 1469598103934665603ull;
        coldPathHashU64(programKey, tdi.program);
        coldPathHashU64(programKey, tdi.pipelineEmulationFragmentProgram);
        coldPathHashPointer(programKey, tdi.vertexMSL);
        coldPathHashPointer(programKey, tdi.fragmentMSL);
        recordRepeat(programKeys, programKey, programRepeats);

        std::uint64_t vaoFboKey = 1469598103934665603ull;
        coldPathHashU64(vaoFboKey, vaoName);
        coldPathHashU64(vaoFboKey, vaoGeneration);
        coldPathHashU64(vaoFboKey, drawFboName);
        recordRepeat(vaoFboKeys, vaoFboKey, vaoFboRepeats);

        std::uint64_t programVaoFboKey = programKey;
        coldPathHashU64(programVaoFboKey, vaoName);
        coldPathHashU64(programVaoFboKey, vaoGeneration);
        coldPathHashU64(programVaoFboKey, drawFboName);
        recordRepeat(programVaoFboKeys,
                     programVaoFboKey,
                     programVaoFboRepeats);
    }

    void recordBoundaryKey(const AppGLSubmissionGroup& group,
                           GLuint drawFboName) {
        if (!enabled) {
            return;
        }
        std::uint64_t key = 1469598103934665603ull;
        coldPathHashU64(key, drawFboName);
        coldPathHashU64(key, static_cast<std::uint64_t>(group.kind));
        coldPathHashU64(key, static_cast<std::uint64_t>(group.primaryReason));
        coldPathHashU64(key, group.declared ? 1u : 0u);
        coldPathHashU64(key, group.argumentBuffersEnabled ? 1u : 0u);
        coldPathHashU64(key, group.approximateFallbackDisallowed ? 1u : 0u);
        coldPathHashU64(key, group.subgroupCount);
        coldPathHashU64(key, group.readCount);
        coldPathHashU64(key, group.writeCount);
        coldPathHashU64(key, group.transientCount);
        for (std::uint8_t i = 0; i < group.subgroupCount; ++i) {
            coldPathHashU64(
                key, static_cast<std::uint64_t>(group.subgroups[i].kind));
            coldPathHashU64(
                key, static_cast<std::uint64_t>(group.subgroups[i].reason));
        }
        for (std::uint8_t i = 0; i < group.readCount; ++i) {
            coldPathHashU64(
                key, static_cast<std::uint64_t>(group.reads[i].kind));
            coldPathHashU64(key, group.reads[i].name);
            coldPathHashU64(key, group.reads[i].producerBits);
        }
        for (std::uint8_t i = 0; i < group.writeCount; ++i) {
            coldPathHashU64(
                key, static_cast<std::uint64_t>(group.writes[i].kind));
            coldPathHashU64(key, group.writes[i].name);
            coldPathHashU64(key, group.writes[i].producerBits);
        }
        for (std::uint8_t i = 0; i < group.transientCount; ++i) {
            coldPathHashU64(
                key, static_cast<std::uint64_t>(group.transients[i].kind));
            coldPathHashU64(
                key, static_cast<std::uint64_t>(group.transients[i].ordering));
            coldPathHashU64(
                key, static_cast<std::uint64_t>(group.transients[i].reason));
            coldPathHashU64(key, group.transients[i].slot);
            coldPathHashU64(key, group.transients[i].bytes);
        }
        recordRepeat(boundaryKeys, key, boundaryRepeats);
    }

    void recordPhase2Key(std::uint64_t key) {
        if (!enabled) {
            return;
        }
        ++phase2Candidates;
        recordRepeat(phase2Keys, key, phase2KeyRepeats);
    }

    void recordPhase2Decision(const char* decision) {
        if (!enabled || decision == nullptr) {
            return;
        }
        if (std::strcmp(decision, "hit") == 0) {
            ++phase2PlanHits;
        } else if (std::strcmp(decision, "miss") == 0) {
            ++phase2PlanMisses;
        } else if (std::strcmp(decision, "reject") == 0) {
            ++phase2PlanRejects;
        }
    }

    void recordPhase2ForceMiss() {
        if (enabled) {
            ++phase2PlanForceMisses;
        }
    }

    void recordMemo(bool supported, bool hit) {
        if (!enabled) {
            return;
        }
        ++phase2MemoLookups;
        if (supported) {
            ++phase2MemoSupported;
        }
        if (hit) {
            ++phase2MemoHits;
        } else {
            ++phase2MemoMisses;
        }
    }

    void recordProgramFingerprint(bool eligible, bool hit) {
        if (!enabled) {
            return;
        }
        if (!eligible) {
            ++programFingerprintFallbacks;
            return;
        }
        ++programFingerprintLookups;
        if (hit) {
            ++programFingerprintHits;
        } else {
            ++programFingerprintMisses;
        }
    }

    void recordSnapshotEstimate(const TranslatedDrawInfo& tdi) {
        if (!enabled) {
            return;
        }
        const auto estimateStart = glDrawProfileNow();
        std::size_t bytes = sizeof(TranslatedDrawInfo);
        bytes +=
            tdi.vertexAttributeLayouts.size() *
            sizeof(TranslatedDrawInfo::VertexAttributeLayout);
        for (const auto& extra : tdi.extraVertexBuffers) {
            bytes += sizeof(TranslatedDrawInfo::ExtraVertexBuffer);
            bytes +=
                extra.attributes.size() *
                sizeof(TranslatedDrawInfo::VertexAttributeLayout);
            bytes += extra.ownedData.size();
        }
        bytes += tdi.fragmentTextures.size() *
                 sizeof(TranslatedDrawInfo::TextureBinding);
        bytes += tdi.vertexTextures.size() *
                 sizeof(TranslatedDrawInfo::TextureBinding);
        bytes += tdi.uboBindings.size() *
                 sizeof(TranslatedDrawInfo::UBOBinding);
        bytes += tdi.ssboBindings.size() *
                 sizeof(TranslatedDrawInfo::SSBOBinding);
        bytes += tdi.atomicCounterBindings.size() *
                 sizeof(TranslatedDrawInfo::AtomicCounterBinding);
        bytes += tdi.sampledTextureNames.size() * sizeof(GLuint);
        bytes += tdi.readImageTextureNames.size() * sizeof(GLuint);
        bytes += tdi.writtenImageTextureNames.size() * sizeof(GLuint);
        bytes += tdi.vertexUniformSize + tdi.fragmentUniformSize;

        const AppGLSubmissionGroup& group = tdi.submissionGroup;
        std::size_t estimatedMergeBytes = sizeof(AppGLSubmissionGroup);
        estimatedMergeBytes +=
            static_cast<std::size_t>(group.readCount + group.writeCount) *
            sizeof(AppGLSubmissionResourceAccess);
        estimatedMergeBytes +=
            static_cast<std::size_t>(group.transientCount) *
            sizeof(AppGLSubmissionTransient);

        ++snapshotSamples;
        snapshotBytes += static_cast<std::uint64_t>(bytes);
        maxSnapshotBytes =
            std::max<std::uint64_t>(maxSnapshotBytes, bytes);
        mergeBytes += static_cast<std::uint64_t>(estimatedMergeBytes);
        maxMergeBytes =
            std::max<std::uint64_t>(maxMergeBytes, estimatedMergeBytes);
        record(ColdPathDiagnosticBucket::SnapshotEstimate,
               estimateStart,
               glDrawProfileNow());
    }

    void dumpRepeat(const char* surface,
                    std::uint64_t samples,
                    std::size_t unique,
                    std::uint64_t repeats) const {
        if (samples == 0 && unique == 0) {
            return;
        }
        const double repeatRate = samples > 0
            ? (static_cast<double>(repeats) * 100.0) /
                  static_cast<double>(samples)
            : 0.0;
        std::fprintf(stderr,
            "[APPGL_7G_COLD_PATH_PROFILE] repeat surface=%s "
            "samples=%llu unique=%llu repeats=%llu repeat_rate_pct=%.2f\n",
            surface,
            static_cast<unsigned long long>(samples),
            static_cast<unsigned long long>(unique),
            static_cast<unsigned long long>(repeats),
            repeatRate);
    }

    void dump() const {
        if (!enabled) {
            return;
        }
        double totalUs = 0.0;
        std::uint64_t samples = 0;
        for (const auto& bucket : buckets) {
            totalUs += bucket.totalUs;
            samples += bucket.count;
        }
        const double avgSnapshotBytes = snapshotSamples > 0
            ? static_cast<double>(snapshotBytes) /
                  static_cast<double>(snapshotSamples)
            : 0.0;
        const double avgMergeBytes = snapshotSamples > 0
            ? static_cast<double>(mergeBytes) /
                  static_cast<double>(snapshotSamples)
            : 0.0;
        std::fprintf(stderr,
            "[APPGL_7G_COLD_PATH_PROFILE] summary draws=%llu "
            "timed_samples=%llu total_us=%.3f phase2_candidates=%llu "
            "phase2_cache_hits=%llu phase2_cache_misses=%llu "
            "phase2_cache_rejects=%llu phase2_force_misses=%llu "
            "snapshot_samples=%llu avg_snapshot_bytes=%.1f "
            "max_snapshot_bytes=%llu avg_merge_bytes=%.1f "
            "max_merge_bytes=%llu saturated_surfaces=%llu\n",
            static_cast<unsigned long long>(draws),
            static_cast<unsigned long long>(samples),
            totalUs,
            static_cast<unsigned long long>(phase2Candidates),
            static_cast<unsigned long long>(phase2PlanHits),
            static_cast<unsigned long long>(phase2PlanMisses),
            static_cast<unsigned long long>(phase2PlanRejects),
            static_cast<unsigned long long>(phase2PlanForceMisses),
            static_cast<unsigned long long>(snapshotSamples),
            avgSnapshotBytes,
            static_cast<unsigned long long>(maxSnapshotBytes),
            avgMergeBytes,
            static_cast<unsigned long long>(maxMergeBytes),
            static_cast<unsigned long long>(saturatedSurfaces));
        const double denom = draws > 0 ? static_cast<double>(draws) : 1.0;
        for (std::size_t i = 0;
             i < static_cast<std::size_t>(ColdPathDiagnosticBucket::Count);
             ++i) {
            const auto& bucket = buckets[i];
            if (bucket.count == 0) {
                continue;
            }
            const auto bucketId = static_cast<ColdPathDiagnosticBucket>(i);
            std::fprintf(stderr,
                "[APPGL_7G_COLD_PATH_PROFILE] component=%s count=%llu "
                "total_us=%.3f avg_us=%.3f avg_per_draw_us=%.3f\n",
                coldPathDiagnosticBucketName(bucketId),
                static_cast<unsigned long long>(bucket.count),
                bucket.totalUs,
                bucket.totalUs / static_cast<double>(bucket.count),
                bucket.totalUs / denom);
        }
        dumpRepeat("phase2_key",
                   phase2Candidates,
                   phase2Keys.size(),
                   phase2KeyRepeats);
        dumpRepeat("program",
                   draws,
                   programKeys.size(),
                   programRepeats);
        dumpRepeat("vao_fbo",
                   draws,
                   vaoFboKeys.size(),
                   vaoFboRepeats);
        dumpRepeat("program_vao_fbo",
                   draws,
                   programVaoFboKeys.size(),
                   programVaoFboRepeats);
        dumpRepeat("boundary",
                   draws,
                   boundaryKeys.size(),
                   boundaryRepeats);
        const double memoHitRate = phase2MemoLookups > 0
            ? (static_cast<double>(phase2MemoHits) * 100.0) /
                  static_cast<double>(phase2MemoLookups)
            : 0.0;
        std::fprintf(stderr,
            "[APPGL_7G_COLD_PATH_PROFILE] memo lookups=%llu "
            "supported=%llu hits=%llu misses=%llu hit_rate_pct=%.2f\n",
            static_cast<unsigned long long>(phase2MemoLookups),
            static_cast<unsigned long long>(phase2MemoSupported),
            static_cast<unsigned long long>(phase2MemoHits),
            static_cast<unsigned long long>(phase2MemoMisses),
            memoHitRate);
        const double fingerprintHitRate = programFingerprintLookups > 0
            ? (static_cast<double>(programFingerprintHits) * 100.0) /
                  static_cast<double>(programFingerprintLookups)
            : 0.0;
        std::fprintf(stderr,
            "[APPGL_7G_COLD_PATH_PROFILE] fingerprint surface=program "
            "lookups=%llu hits=%llu misses=%llu fallbacks=%llu "
            "hit_rate_pct=%.2f\n",
            static_cast<unsigned long long>(programFingerprintLookups),
            static_cast<unsigned long long>(programFingerprintHits),
            static_cast<unsigned long long>(programFingerprintMisses),
            static_cast<unsigned long long>(programFingerprintFallbacks),
            fingerprintHitRate);
        std::fprintf(stderr,
            "[APPGL_7G_COLD_PATH_PROFILE] preflight snapshots=%llu "
            "generic_prepared=%llu generic_unprepared=%llu\n",
            static_cast<unsigned long long>(preflightSnapshots),
            static_cast<unsigned long long>(preflightGenericPrepared),
            static_cast<unsigned long long>(preflightGenericUnprepared));
        std::fflush(stderr);
    }
};

class ColdPathDiagnosticScope {
public:
    ColdPathDiagnosticScope(ColdPathDiagnosticProfile* profile,
                            ColdPathDiagnosticBucket bucket)
        : profile_(profile != nullptr && profile->enabled ? profile : nullptr),
          bucket_(bucket) {
        if (profile_ != nullptr) {
            start_ = glDrawProfileNow();
        }
    }

    ColdPathDiagnosticScope(const ColdPathDiagnosticScope&) = delete;
    ColdPathDiagnosticScope& operator=(const ColdPathDiagnosticScope&) =
        delete;

    ~ColdPathDiagnosticScope() {
        if (profile_ != nullptr) {
            profile_->record(bucket_, start_, glDrawProfileNow());
        }
    }

private:
    ColdPathDiagnosticProfile* profile_ = nullptr;
    ColdPathDiagnosticBucket bucket_ = ColdPathDiagnosticBucket::Count;
    GLDrawProfileTimePoint start_{};
};

enum class Phase2PlanRejectReason : std::size_t {
    MissingProgram,
    MissingShader,
    MissingReflection,
    ProgramPipelineOrSubroutineState,
    SideEffect,
    KeyCapacity,
    Count,
};

static const char* phase2PlanRejectReasonName(Phase2PlanRejectReason reason) {
    switch (reason) {
        case Phase2PlanRejectReason::MissingProgram: return "missing_program";
        case Phase2PlanRejectReason::MissingShader: return "missing_shader";
        case Phase2PlanRejectReason::MissingReflection: return "missing_reflection";
        case Phase2PlanRejectReason::ProgramPipelineOrSubroutineState: return "program_pipeline_or_subroutine_state";
        case Phase2PlanRejectReason::SideEffect: return "side_effect";
        case Phase2PlanRejectReason::KeyCapacity: return "key_capacity";
        case Phase2PlanRejectReason::Count: break;
    }
    return "unknown";
}

static bool phase2PlanProfileEnabled() {
    return std::getenv("APPGL_PHASE2_PLAN_PROFILE") != nullptr ||
           std::getenv("APPGL_PHASE2_PLAN_KEY_PROFILE") != nullptr;
}

static bool phase2TranslatedDrawPlanCacheEnabled() {
    return std::getenv("APPGL_PHASE2_PLAN_DISABLE") == nullptr;
}

static bool phase2TranslatedDrawPlanForceMiss() {
    return std::getenv("APPGL_PHASE2_PLAN_FORCE_MISS") != nullptr;
}

static bool phase2TranslatedDrawPlanTraceEnabled() {
    return std::getenv("APPGL_PHASE2_PLAN_TRACE") != nullptr;
}

static bool phase2FixedStateSegmentShadowEnabled() {
    static const bool enabled =
        std::getenv("APPGL_PHASE2_FIXED_STATE_SEGMENT_SHADOW") != nullptr;
    return enabled;
}

static bool phase2BindingShapeSegmentShadowEnabled() {
    static const bool enabled =
        std::getenv("APPGL_PHASE2_BINDING_SEGMENT_SHADOW") != nullptr;
    return enabled;
}

static bool phase2VaoLayoutSegmentShadowEnabled() {
    static const bool enabled =
        std::getenv("APPGL_PHASE2_VAO_LAYOUT_SEGMENT_SHADOW") != nullptr;
    return enabled;
}

static constexpr std::uint64_t kPhase2PlanHashOffset = 1469598103934665603ull;
static constexpr std::uint64_t kPhase2PlanHashPrime = 1099511628211ull;
static constexpr std::uint64_t kPhase2PlanVaoLayoutRuntimeCacheIndex =
    std::numeric_limits<std::uint64_t>::max();

static void phase2PlanHashByte(std::uint64_t& hash, std::uint8_t byte) {
    hash ^= byte;
    hash *= kPhase2PlanHashPrime;
}

static void phase2PlanHashU64(std::uint64_t& hash, std::uint64_t value) {
    for (int i = 0; i < 8; ++i) {
        phase2PlanHashByte(
            hash, static_cast<std::uint8_t>((value >> (i * 8)) & 0xFFu));
    }
}

static void phase2PlanHashBool(std::uint64_t& hash, bool value) {
    phase2PlanHashU64(hash, value ? 1ull : 0ull);
}

static std::uint32_t phase2PlanFloatBits(float value) {
    std::uint32_t bits = 0;
    std::memcpy(&bits, &value, sizeof(bits));
    return bits;
}

static void phase2PlanHashFloat(std::uint64_t& hash, float value) {
    phase2PlanHashU64(hash, phase2PlanFloatBits(value));
}

static void phase2PlanHashPointer(std::uint64_t& hash, const void* pointer) {
    phase2PlanHashU64(hash,
        static_cast<std::uint64_t>(reinterpret_cast<std::uintptr_t>(pointer)));
}

static void phase2PlanHashShaderIdentity(
    std::uint64_t& hash,
    const std::string* source)
{
    phase2PlanHashPointer(hash, source);
    phase2PlanHashU64(hash, source != nullptr ? source->size() : 0u);
    phase2PlanHashPointer(
        hash, source != nullptr && !source->empty() ? source->data() : nullptr);
}

static void phase2PlanHashResourceBindingShape(
    std::uint64_t& hash,
    const ShaderReflection::ResourceBinding& binding)
{
    phase2PlanHashU64(hash, binding.glBinding);
    phase2PlanHashU64(hash, static_cast<std::uint64_t>(binding.uniformLocation));
    phase2PlanHashU64(hash, binding.glType);
    phase2PlanHashU64(hash, binding.arraySize);
    phase2PlanHashU64(hash, binding.metalBinding);
    phase2PlanHashU64(hash, binding.byteSize);
    phase2PlanHashBool(hash, binding.hasInstanceName);
    phase2PlanHashU64(hash, binding.blockArraySize);
    phase2PlanHashBool(hash, binding.hasExplicitBinding);
    phase2PlanHashBool(hash, binding.active);
    phase2PlanHashBool(hash, binding.multisampleStorageImage);
    phase2PlanHashBool(hash, binding.multisampleStorageImageArray);
    phase2PlanHashU64(hash, binding.storageImageTarget);
    phase2PlanHashU64(hash, binding.metalAtomicBufferBinding);
    phase2PlanHashBool(hash, binding.sparseStorageImageRead);
    phase2PlanHashBool(hash, binding.sparseStorageImageWrite);
    phase2PlanHashBool(hash, binding.containsFp64);
    phase2PlanHashU64(hash, binding.members.size());
    for (const auto& member : binding.members) {
        phase2PlanHashU64(hash, member.offset);
        phase2PlanHashU64(hash, member.size);
        phase2PlanHashU64(hash, member.type);
        phase2PlanHashBool(hash, member.isRowMajor);
        phase2PlanHashU64(hash, member.arraySize);
        phase2PlanHashBool(hash, member.isArray);
        phase2PlanHashU64(hash, static_cast<std::uint64_t>(member.arrayStride));
        phase2PlanHashU64(hash, static_cast<std::uint64_t>(member.matrixStride));
        phase2PlanHashU64(hash, static_cast<std::uint64_t>(member.topLevelArraySize));
        phase2PlanHashU64(hash, static_cast<std::uint64_t>(member.topLevelArrayStride));
        phase2PlanHashBool(hash, member.containsFp64);
    }
}

static void phase2PlanHashReflectionShape(
    std::uint64_t& hash,
    const ShaderReflection* reflection)
{
    phase2PlanHashPointer(hash, reflection);
    if (reflection == nullptr) {
        return;
    }

    phase2PlanHashU64(hash, reflection->vertexInputs.size());
    for (const auto& input : reflection->vertexInputs) {
        phase2PlanHashU64(hash, input.location);
        phase2PlanHashU64(hash, input.sourceLocation);
        phase2PlanHashU64(hash, input.type);
        phase2PlanHashBool(hash, input.containsFp64);
    }

    auto hashBindings = [&](const auto& bindings) {
        phase2PlanHashU64(hash, bindings.size());
        for (const auto& binding : bindings) {
            phase2PlanHashResourceBindingShape(hash, binding);
        }
    };
    hashBindings(reflection->uniformBlocks);
    hashBindings(reflection->sampledTextures);
    hashBindings(reflection->storageBuffers);
    hashBindings(reflection->storageImages);
    phase2PlanHashBool(hash, reflection->usesPointSize);
    phase2PlanHashBool(hash, reflection->usesFragmentShadingRateBuiltins);
    phase2PlanHashBool(hash, reflection->usesFp64);
    phase2PlanHashBool(hash, reflection->fp64TranslationActive);
}

struct Phase2ProgramStructuralFingerprint {
    bool valid = false;
    std::uint64_t programSegmentHash = 0;
};

static void phase2PlanInvalidateProgramStructuralFingerprint(
    GLProgramObject& program)
{
    program.phase2ProgramStructuralFingerprintValid = false;
    program.phase2ProgramStructuralFingerprintProgram = 0;
    program.phase2ProgramStructuralFingerprintGeneration = 0;
    program.phase2ProgramStructuralFingerprint = 0;
}

static std::uint64_t phase2PlanBuildProgramStructuralFingerprint(
    GLuint programName,
    const GLProgramObject& program)
{
    std::uint64_t hash = kPhase2PlanHashOffset;
    phase2PlanHashU64(hash, 0x4150474C50324B31ull); // "APGLP2K1"
    phase2PlanHashU64(hash, programName);
    phase2PlanHashU64(hash, 0u);
    phase2PlanHashShaderIdentity(hash, &program.vertexMSL);
    phase2PlanHashShaderIdentity(hash, &program.fragmentMSL);
    phase2PlanHashReflectionShape(hash, &program.vertexReflection);
    phase2PlanHashReflectionShape(hash, &program.fragmentReflection);
    return hash;
}

static Phase2ProgramStructuralFingerprint
phase2PlanProgramStructuralFingerprintForDraw(
    const TranslatedDrawInfo& tdi,
    GLObjectStore* objects,
    ColdPathDiagnosticProfile* coldProfile)
{
    auto fallback = [&]() {
        if (coldProfile != nullptr) {
            coldProfile->recordProgramFingerprint(/*eligible=*/false,
                                                  /*hit=*/false);
        }
        return Phase2ProgramStructuralFingerprint{};
    };

    if (objects == nullptr || tdi.rasterizerDiscard ||
        tdi.pipelineEmulationFragmentProgram != 0) {
        return fallback();
    }

    GLProgramObject* program = objects->programs().get(tdi.program);
    if (program == nullptr || !program->linked || program->separableLinked) {
        return fallback();
    }
    if (tdi.vertexMSL != &program->vertexMSL ||
        tdi.fragmentMSL != &program->fragmentMSL ||
        tdi.vertexReflection != &program->vertexReflection ||
        tdi.fragmentReflection != &program->fragmentReflection) {
        return fallback();
    }

    const bool hit =
        program->phase2ProgramStructuralFingerprintValid &&
        program->phase2ProgramStructuralFingerprintProgram == tdi.program &&
        program->phase2ProgramStructuralFingerprintGeneration ==
            program->executableGeneration;
    if (!hit) {
        program->phase2ProgramStructuralFingerprint =
            phase2PlanBuildProgramStructuralFingerprint(tdi.program, *program);
        program->phase2ProgramStructuralFingerprintProgram = tdi.program;
        program->phase2ProgramStructuralFingerprintGeneration =
            program->executableGeneration;
        program->phase2ProgramStructuralFingerprintValid = true;
    }
    if (coldProfile != nullptr) {
        coldProfile->recordProgramFingerprint(/*eligible=*/true, hit);
    }

    Phase2ProgramStructuralFingerprint fingerprint;
    fingerprint.valid = true;
    fingerprint.programSegmentHash =
        program->phase2ProgramStructuralFingerprint;
    return fingerprint;
}

static void phase2PlanHashVertexLayout(
    std::uint64_t& hash,
    const TranslatedDrawInfo::VertexAttributeLayout& layout)
{
    phase2PlanHashU64(hash, layout.location);
    phase2PlanHashU64(hash, layout.offset);
    phase2PlanHashU64(hash, layout.glType);
    phase2PlanHashU64(hash, static_cast<std::uint64_t>(layout.glComponentCount));
    phase2PlanHashBool(hash, layout.glNormalized != GL_FALSE);
    phase2PlanHashBool(hash, layout.glIsInteger);
}

static void phase2PlanHashCachedVertexLayoutAsTranslated(
    std::uint64_t& hash,
    const GLVertexArrayCachedAttributeLayout& layout,
    std::size_t baseOffset = 0)
{
    phase2PlanHashU64(hash, layout.location);
    phase2PlanHashU64(hash, layout.offset - baseOffset);
    phase2PlanHashU64(hash, layout.glType);
    phase2PlanHashU64(
        hash, static_cast<std::uint64_t>(layout.glComponentCount));
    phase2PlanHashBool(hash, layout.glNormalized != GL_FALSE);
    phase2PlanHashBool(hash, layout.glIsInteger);
}

static void phase2PlanHashVaoLayoutSegmentFields(
    std::uint64_t& hash,
    const TranslatedDrawInfo& tdi,
    std::uint64_t cacheIndex)
{
    phase2PlanHashU64(hash, 0x4150474C5032564Cull); // "APGLP2VL"
    phase2PlanHashU64(hash, cacheIndex);
    phase2PlanHashU64(hash, tdi.vertexStride);
    phase2PlanHashU64(hash, tdi.vertexAttributeLayouts.size());
    for (const auto& layout : tdi.vertexAttributeLayouts) {
        phase2PlanHashVertexLayout(hash, layout);
    }
    phase2PlanHashU64(hash, tdi.extraVertexBuffers.size());
    for (const auto& extra : tdi.extraVertexBuffers) {
        phase2PlanHashU64(hash, extra.stride);
        phase2PlanHashU64(hash, extra.divisor);
        phase2PlanHashBool(hash, extra.constantStep);
        phase2PlanHashU64(hash, extra.attributes.size());
        for (const auto& layout : extra.attributes) {
            phase2PlanHashVertexLayout(hash, layout);
        }
    }
}

static std::uint64_t phase2PlanBuildVaoLayoutSegmentHash(
    const TranslatedDrawInfo& tdi,
    std::uint64_t cacheIndex)
{
    std::uint64_t hash = kPhase2PlanHashOffset;
    phase2PlanHashVaoLayoutSegmentFields(hash, tdi, cacheIndex);
    return hash;
}

static std::uint64_t phase2PlanBuildCachedVaoLayoutFingerprint(
    const GLVertexArrayCachedLayout& cache,
    std::uint64_t cacheIndex)
{
    std::uint64_t hash = kPhase2PlanHashOffset;
    phase2PlanHashU64(hash, 0x4150474C5032564Cull); // "APGLP2VL"
    phase2PlanHashU64(hash, cacheIndex);
    phase2PlanHashU64(hash, cache.primaryStride);
    phase2PlanHashU64(hash, cache.primaryAttributes.size());
    for (const auto& layout : cache.primaryAttributes) {
        phase2PlanHashCachedVertexLayoutAsTranslated(
            hash, layout, cache.primaryBaseOffset);
    }
    phase2PlanHashU64(hash, cache.extraGroups.size());
    for (const auto& group : cache.extraGroups) {
        phase2PlanHashU64(hash, group.stride);
        phase2PlanHashU64(hash, group.divisor);
        phase2PlanHashBool(hash, false);
        phase2PlanHashU64(hash, group.attributes.size());
        for (const auto& layout : group.attributes) {
            phase2PlanHashCachedVertexLayoutAsTranslated(hash, layout);
        }
    }
    return hash;
}

static void phase2PlanLogVaoLayoutSegmentNamespaceOnce()
{
    if (!phase2VaoLayoutSegmentShadowEnabled()) {
        return;
    }
    static bool logged = false;
    if (logged) {
        return;
    }
    logged = true;
    std::fprintf(
        stderr,
        "[APPGL_PHASE2_VAO_LAYOUT_SEGMENT_SHADOW] "
        "final key namespace changed intentionally; "
        "checking vao-layout segment coverage\n");
}

static void phase2PlanAssertVaoLayoutSegmentCoverage(
    const TranslatedDrawInfo& tdi,
    const char* site,
    std::uint64_t segmentHash)
{
    if (!phase2VaoLayoutSegmentShadowEnabled()) {
        return;
    }
    phase2PlanLogVaoLayoutSegmentNamespaceOnce();
    const std::uint64_t reference =
        phase2PlanBuildVaoLayoutSegmentHash(
            tdi, tdi.phase2VaoLayoutSegmentCacheIndex);
    if (segmentHash == reference) {
        return;
    }
    std::fprintf(
        stderr,
        "[APPGL_PHASE2_VAO_LAYOUT_SEGMENT_SHADOW] "
        "vao-layout segment coverage mismatch site=%s stored=0x%016llx "
        "reference=0x%016llx cache_index=%llu "
        "final_key_namespace=changed_intentionally\n",
        site != nullptr ? site : "unknown",
        static_cast<unsigned long long>(segmentHash),
        static_cast<unsigned long long>(reference),
        static_cast<unsigned long long>(
            tdi.phase2VaoLayoutSegmentCacheIndex));
    std::abort();
}

static void phase2PlanInvalidateVaoLayoutSegmentHash(TranslatedDrawInfo& tdi)
{
    tdi.phase2VaoLayoutSegmentHashValid = false;
    tdi.phase2VaoLayoutSegmentHash = 0;
    tdi.phase2VaoLayoutSegmentCacheIndex =
        kPhase2PlanVaoLayoutRuntimeCacheIndex;
}

static void phase2PlanRefreshVaoLayoutSegmentHash(
    TranslatedDrawInfo& tdi,
    const char* site,
    std::uint64_t cacheIndex = kPhase2PlanVaoLayoutRuntimeCacheIndex)
{
    tdi.phase2VaoLayoutSegmentCacheIndex = cacheIndex;
    tdi.phase2VaoLayoutSegmentHash =
        phase2PlanBuildVaoLayoutSegmentHash(tdi, cacheIndex);
    tdi.phase2VaoLayoutSegmentHashValid = true;
    phase2PlanAssertVaoLayoutSegmentCoverage(
        tdi, site, tdi.phase2VaoLayoutSegmentHash);
}

static void phase2PlanSetVaoLayoutSegmentHashFromCache(
    TranslatedDrawInfo& tdi,
    const GLVertexArrayCachedLayout& cache,
    const char* site)
{
    if (!cache.phase2LayoutFingerprintValid) {
        phase2PlanInvalidateVaoLayoutSegmentHash(tdi);
        return;
    }
    tdi.phase2VaoLayoutSegmentCacheIndex =
        cache.phase2LayoutFingerprintCacheIndex;
    tdi.phase2VaoLayoutSegmentHash = cache.phase2LayoutFingerprint;
    tdi.phase2VaoLayoutSegmentHashValid = true;
    phase2PlanAssertVaoLayoutSegmentCoverage(
        tdi, site, tdi.phase2VaoLayoutSegmentHash);
}

static void phase2PlanEnsureVaoLayoutSegmentHash(TranslatedDrawInfo& tdi,
                                                 const char* site)
{
    if (!tdi.phase2VaoLayoutSegmentHashValid) {
        phase2PlanRefreshVaoLayoutSegmentHash(tdi, site);
        return;
    }
    phase2PlanAssertVaoLayoutSegmentCoverage(
        tdi, site, tdi.phase2VaoLayoutSegmentHash);
}

static std::uint64_t phase2PlanVaoLayoutSegmentHashForKey(
    const TranslatedDrawInfo& tdi)
{
    if (tdi.phase2VaoLayoutSegmentHashValid) {
        phase2PlanAssertVaoLayoutSegmentCoverage(
            tdi, "key", tdi.phase2VaoLayoutSegmentHash);
        return tdi.phase2VaoLayoutSegmentHash;
    }
    const std::uint64_t fallback =
        phase2PlanBuildVaoLayoutSegmentHash(
            tdi, kPhase2PlanVaoLayoutRuntimeCacheIndex);
    if (phase2VaoLayoutSegmentShadowEnabled()) {
        phase2PlanLogVaoLayoutSegmentNamespaceOnce();
        std::fprintf(
            stderr,
            "[APPGL_PHASE2_VAO_LAYOUT_SEGMENT_SHADOW] "
            "vao-layout segment missing before key site=key "
            "fallback=0x%016llx final_key_namespace=changed_intentionally\n",
            static_cast<unsigned long long>(fallback));
        std::abort();
    }
    return fallback;
}

static void phase2PlanHashTextureBindings(
    std::uint64_t& hash,
    const std::vector<TranslatedDrawInfo::TextureBinding>& bindings)
{
    phase2PlanHashU64(hash, bindings.size());
    for (const auto& binding : bindings) {
        phase2PlanHashU64(hash, binding.metalSlot);
        phase2PlanHashBool(hash, binding.textureBufferBackingMetalBuffer != nullptr);
        phase2PlanHashBool(hash, binding.imageAtomicMetalBuffer != nullptr);
        phase2PlanHashU64(hash, binding.imageAtomicBufferSlot);
        phase2PlanHashU64(hash, binding.reductionMode);
        phase2PlanHashU64(hash, binding.borderClampMask);
    }
}

template <typename Binding>
static void phase2PlanHashBufferBindings(
    std::uint64_t& hash,
    const std::vector<Binding>& bindings)
{
    phase2PlanHashU64(hash, bindings.size());
    for (const auto& binding : bindings) {
        phase2PlanHashU64(hash, binding.metalSlot);
        phase2PlanHashBool(hash, binding.metalBuffer != nullptr);
        phase2PlanHashBool(hash, binding.isVertex);
        phase2PlanHashBool(hash, binding.isFragment);
    }
}

static std::uint64_t phase2PlanBuildBindingShapeSegmentHash(
    const TranslatedDrawInfo& tdi)
{
    std::uint64_t hash = kPhase2PlanHashOffset;
    phase2PlanHashU64(hash, 0x4150474C50324253ull); // "APGLP2BS"
    phase2PlanHashU64(hash, tdi.vertexUniformSize);
    phase2PlanHashU64(hash, tdi.fragmentUniformSize);
    phase2PlanHashTextureBindings(hash, tdi.fragmentTextures);
    phase2PlanHashTextureBindings(hash, tdi.vertexTextures);
    phase2PlanHashBufferBindings(hash, tdi.uboBindings);
    phase2PlanHashBufferBindings(hash, tdi.ssboBindings);
    phase2PlanHashBufferBindings(hash, tdi.atomicCounterBindings);
    phase2PlanHashU64(hash, tdi.sampledTextureNames.size());
    phase2PlanHashU64(hash, tdi.readImageTextureNames.size());
    phase2PlanHashU64(hash, tdi.writtenImageTextureNames.size());
    return hash;
}

static std::uint64_t phase2PlanBuildBindingShapeReferenceSegmentHash(
    const TranslatedDrawInfo& tdi)
{
    std::uint64_t hash = kPhase2PlanHashOffset;
    phase2PlanHashU64(hash, 0x4150474C50324253ull); // "APGLP2BS"
    phase2PlanHashU64(hash, tdi.vertexUniformSize);
    phase2PlanHashU64(hash, tdi.fragmentUniformSize);

    phase2PlanHashU64(hash, tdi.fragmentTextures.size());
    for (const auto& binding : tdi.fragmentTextures) {
        phase2PlanHashU64(hash, binding.metalSlot);
        phase2PlanHashBool(
            hash, binding.textureBufferBackingMetalBuffer != nullptr);
        phase2PlanHashBool(hash, binding.imageAtomicMetalBuffer != nullptr);
        phase2PlanHashU64(hash, binding.imageAtomicBufferSlot);
        phase2PlanHashU64(hash, binding.reductionMode);
        phase2PlanHashU64(hash, binding.borderClampMask);
    }
    phase2PlanHashU64(hash, tdi.vertexTextures.size());
    for (const auto& binding : tdi.vertexTextures) {
        phase2PlanHashU64(hash, binding.metalSlot);
        phase2PlanHashBool(
            hash, binding.textureBufferBackingMetalBuffer != nullptr);
        phase2PlanHashBool(hash, binding.imageAtomicMetalBuffer != nullptr);
        phase2PlanHashU64(hash, binding.imageAtomicBufferSlot);
        phase2PlanHashU64(hash, binding.reductionMode);
        phase2PlanHashU64(hash, binding.borderClampMask);
    }

    phase2PlanHashU64(hash, tdi.uboBindings.size());
    for (const auto& ubo : tdi.uboBindings) {
        phase2PlanHashU64(hash, ubo.metalSlot);
        phase2PlanHashBool(hash, ubo.metalBuffer != nullptr);
        phase2PlanHashBool(hash, ubo.isVertex);
        phase2PlanHashBool(hash, ubo.isFragment);
    }
    phase2PlanHashU64(hash, tdi.ssboBindings.size());
    for (const auto& ssbo : tdi.ssboBindings) {
        phase2PlanHashU64(hash, ssbo.metalSlot);
        phase2PlanHashBool(hash, ssbo.metalBuffer != nullptr);
        phase2PlanHashBool(hash, ssbo.isVertex);
        phase2PlanHashBool(hash, ssbo.isFragment);
    }
    phase2PlanHashU64(hash, tdi.atomicCounterBindings.size());
    for (const auto& atomic : tdi.atomicCounterBindings) {
        phase2PlanHashU64(hash, atomic.metalSlot);
        phase2PlanHashBool(hash, atomic.metalBuffer != nullptr);
        phase2PlanHashBool(hash, atomic.isVertex);
        phase2PlanHashBool(hash, atomic.isFragment);
    }
    phase2PlanHashU64(hash, tdi.sampledTextureNames.size());
    phase2PlanHashU64(hash, tdi.readImageTextureNames.size());
    phase2PlanHashU64(hash, tdi.writtenImageTextureNames.size());
    return hash;
}

