        auto uniformStencilValue =
            [](const std::uint8_t* pixels,
               GLsizei width,
               GLsizei height,
               std::uint8_t& value) {
            if (pixels == nullptr || width <= 0 || height <= 0) {
                return false;
            }
            const std::size_t count =
                static_cast<std::size_t>(width) *
                static_cast<std::size_t>(height);
            value = pixels[0];
            for (std::size_t i = 1; i < count; ++i) {
                if (pixels[i] != value) {
                    return false;
                }
            }
