            const GLFramebufferAttachment* srcAttachment = framebufferAttachment(*readFb, GL_STENCIL_ATTACHMENT);
            const GLFramebufferAttachment* dstAttachment = framebufferAttachment(*drawFb, GL_STENCIL_ATTACHMENT);
            if (srcAttachment != nullptr && dstAttachment != nullptr) {
                if (tryMetalExactDepthStencilBlit(
                        *srcAttachment, *dstAttachment,
                        GL_STENCIL_BUFFER_BIT)) {
                    metalCopiedStencil = true;
                }
            }
            if (srcAttachment != nullptr && dstAttachment != nullptr &&
                !metalCopiedStencil) {
                std::vector<std::uint8_t> srcStage(
                    static_cast<std::size_t>(copyWidth) *
                    static_cast<std::size_t>(copyHeight));
                if (!readStencilAttachmentPixels(*srcAttachment, srcX, srcY,
                                                  copyWidth, copyHeight,
                                                  srcStage.data())) {
                    return false;
                }
                const std::uint8_t* stagePtr = srcStage.data();
                std::vector<std::uint8_t> dstStage;
                if (needsScale) {
                    dstStage.resize(static_cast<std::size_t>(dstWidth) *
                                    static_cast<std::size_t>(dstHeight));
                    for (GLsizei dy = 0; dy < dstHeight; ++dy) {
                        for (GLsizei dx = 0; dx < dstWidth; ++dx) {
                            GLsizei sx = 0, sy = 0;
                            sampleSrcIndex(dx, dy, sx, sy);
                            dstStage[static_cast<std::size_t>(dy) *
                                     static_cast<std::size_t>(dstWidth) +
                                     static_cast<std::size_t>(dx)] =
                                srcStage[static_cast<std::size_t>(sy) *
                                         static_cast<std::size_t>(copyWidth) +
                                         static_cast<std::size_t>(sx)];
                        }
                    }
                    stagePtr = dstStage.data();
                }
                if (!writeWindow.empty) {
                    std::vector<std::uint8_t> clippedStencil;
                    const std::uint8_t* writeStencil =
                        copyStencilWindow(stagePtr, clippedStencil);
                    if (!writeStencilAttachmentPixels(*dstAttachment,
                                                       writeWindow.x, writeWindow.y,
                                                       writeWindow.width,
                                                       writeWindow.height,
                                                       writeStencil)) {
                        return false;
                    }
                    markFramebufferAttachmentWrite(*dstAttachment,
                                                   kProducerCopyWrite |
                                                   kProducerFboDepthStencilWrite);
                }
            }
        }

        return true;
    }

    bool readFramebufferPixels(GLenum format, GLint x, GLint y, GLsizei width, GLsizei height, void* pixels) const {
        const GLuint framebufferName = state->boundReadFramebuffer();
        const GLFramebufferObject* framebuffer = objects->framebuffers().get(framebufferName);
        if (framebufferName == 0 || framebuffer == nullptr || !framebuffer->instantiated || framebufferStatus(*framebuffer) != GL_FRAMEBUFFER_COMPLETE) {
            return false;
        }

        if (format == GL_RGBA) {
            if (framebuffer->readBuffer == GL_NONE) {
                return false;
            }
            const GLFramebufferAttachment* attachment = framebufferAttachment(*framebuffer, framebuffer->readBuffer);
            return attachment != nullptr && readColorAttachmentPixels(*attachment, x, y, width, height, pixels);
        }
        if (format == GL_DEPTH_COMPONENT) {
            const GLFramebufferAttachment* attachment = framebufferAttachment(*framebuffer, GL_DEPTH_ATTACHMENT);
            return attachment != nullptr && readDepthAttachmentPixels(*attachment, x, y, width, height, pixels);
        }
        if (format == GL_STENCIL_INDEX) {
            const GLFramebufferAttachment* attachment = framebufferAttachment(*framebuffer, GL_STENCIL_ATTACHMENT);
            return attachment != nullptr && readStencilAttachmentPixels(*attachment, x, y, width, height, pixels);
        }
        return false;
    }

    // ── Native-format FBO color readback ──
    // Reads the Metal texture backing a color attachment in its native pixel
    // format and converts to the GL format/type requested by glReadPixels.
    // Returns true on success, false if the attachment cannot be read natively
    // (caller should fall back to the RGBA8 path).
    bool readFBOColorNative(GLint x, GLint y, GLsizei width, GLsizei height,
                            GLenum format, GLenum type, void* pixels) const {
        const GLuint fbName = state->boundReadFramebuffer();
        const GLFramebufferObject* fb = objects->framebuffers().get(fbName);
        if (fbName == 0 || fb == nullptr) return false;

        const GLFramebufferAttachment* att = framebufferAttachment(*fb, fb->readBuffer);
        if (att == nullptr) return false;
        drainFramebufferAttachmentProducer(*att);

        id<MTLTexture> metalTex = nil;
        GLsizei sourceWidth = 0, sourceHeight = 0;
        NSUInteger metalMipLevel = 0;
        NSUInteger metalSlice = 0;
        // For 3D textures, `attachment.layer` is a Z coordinate into the
        // region, not a Metal slice. Track separately so the
        // getBytes: call below can use MTLRegionMake3D with Z.
        bool is3DTextureSrc = false;
        NSUInteger depthSlice3D = 0;

        // FBO readback orientation is separate from texture-image
        // readback. Renderbuffers are always FBO producers; texture
        // attachments opt in via wasFramebufferRenderedTo, with the older
        // wasViewportRenderedTo marker still honored for routed GS/cull
        // producers.
        bool sourceNeedsFboYFlip = true;  // renderbuffers default to FBO-produced
        if (att->kind == GLFramebufferAttachment::Kind::Renderbuffer) {
            const GLRenderbufferObject* rb = objects->renderbuffers().get(att->object);
            if (!rb || !rb->storageDefined || rb->metalTexture == nullptr) return false;
            metalTex = (__bridge id<MTLTexture>)rb->metalTexture;
            sourceWidth = rb->width;
            sourceHeight = rb->height;
            sourceNeedsFboYFlip = rb->framebufferReadbackYFlip;
        } else if (att->kind == GLFramebufferAttachment::Kind::Texture) {
            const GLTextureObject* tex = objects->textures().get(att->object);
            if (!tex || tex->metalTexture == nullptr) return false;
            metalTex = (__bridge id<MTLTexture>)tex->metalTexture;
            metalMipLevel = static_cast<NSUInteger>(att->level);
            if (tex->target == GL_TEXTURE_3D) {
                is3DTextureSrc = true;
                depthSlice3D = static_cast<NSUInteger>(std::max<GLint>(att->layer, 0));
                metalSlice = 0;
            } else {
                metalSlice = static_cast<NSUInteger>(att->layer);
            }
            sourceWidth = static_cast<GLsizei>(metalTex.width >> metalMipLevel);
            sourceHeight = static_cast<GLsizei>(metalTex.height >> metalMipLevel);
            if (sourceWidth < 1) sourceWidth = 1;
            if (sourceHeight < 1) sourceHeight = 1;
            sourceNeedsFboYFlip =
                tex->wasFramebufferRenderedTo ||
                tex->wasViewportRenderedTo;
        } else {
            return false;
        }

        if (metalTex == nil) return false;

        // MSAA source textures can't be read via `getBytes:` — Metal
        // aborts with a SIGSEGV inside AGX. `readColorAttachmentPixels`
        // (the fallback RGBA8 path) already has an explicit
        // MultisampleResolve step that handles this case, so return
        // false here to let the caller (glReadPixels) retry through
        // the RGBA8 fallback. Without this, the full CTS cold sweep
        // crashes at `framebuffer_blit.multisampled_to_single_sampled_*`
        // after ~865 tests and loses the remaining ~18,000-test body.
        if (metalTex.sampleCount > 1) return false;

        // Determine source bytes-per-pixel from the Metal pixel format.
        MTLPixelFormat pf = metalTex.pixelFormat;
        NSUInteger srcBpp = 0;
        NSUInteger srcComponents = 0;
        enum class SrcType { Float32, Float16, UNorm8, SNorm8, UNorm16, SNorm16, UInt8, SInt8, UInt16, SInt16, UInt32, SInt32, Packed };
        SrcType srcType = SrcType::UNorm8;

        switch (pf) {
            case MTLPixelFormatR32Float:       srcBpp = 4;  srcComponents = 1; srcType = SrcType::Float32; break;
            case MTLPixelFormatRG32Float:      srcBpp = 8;  srcComponents = 2; srcType = SrcType::Float32; break;
            case MTLPixelFormatRGBA32Float:    srcBpp = 16; srcComponents = 4; srcType = SrcType::Float32; break;
            case MTLPixelFormatR16Float:       srcBpp = 2;  srcComponents = 1; srcType = SrcType::Float16; break;
            case MTLPixelFormatRG16Float:      srcBpp = 4;  srcComponents = 2; srcType = SrcType::Float16; break;
            case MTLPixelFormatRGBA16Float:    srcBpp = 8;  srcComponents = 4; srcType = SrcType::Float16; break;
            case MTLPixelFormatR8Unorm:        srcBpp = 1;  srcComponents = 1; srcType = SrcType::UNorm8; break;
            case MTLPixelFormatRG8Unorm:       srcBpp = 2;  srcComponents = 2; srcType = SrcType::UNorm8; break;
            case MTLPixelFormatRGBA8Unorm:     srcBpp = 4;  srcComponents = 4; srcType = SrcType::UNorm8; break;
            case MTLPixelFormatBGRA8Unorm:     srcBpp = 4;  srcComponents = 4; srcType = SrcType::UNorm8; break;
            case MTLPixelFormatR8Snorm:        srcBpp = 1;  srcComponents = 1; srcType = SrcType::SNorm8; break;
            case MTLPixelFormatRG8Snorm:       srcBpp = 2;  srcComponents = 2; srcType = SrcType::SNorm8; break;
            case MTLPixelFormatRGBA8Snorm:     srcBpp = 4;  srcComponents = 4; srcType = SrcType::SNorm8; break;
            case MTLPixelFormatR16Unorm:       srcBpp = 2;  srcComponents = 1; srcType = SrcType::UNorm16; break;
            case MTLPixelFormatRG16Unorm:      srcBpp = 4;  srcComponents = 2; srcType = SrcType::UNorm16; break;
            case MTLPixelFormatRGBA16Unorm:    srcBpp = 8;  srcComponents = 4; srcType = SrcType::UNorm16; break;
            case MTLPixelFormatR16Snorm:       srcBpp = 2;  srcComponents = 1; srcType = SrcType::SNorm16; break;
            case MTLPixelFormatRG16Snorm:      srcBpp = 4;  srcComponents = 2; srcType = SrcType::SNorm16; break;
            case MTLPixelFormatRGBA16Snorm:    srcBpp = 8;  srcComponents = 4; srcType = SrcType::SNorm16; break;
            case MTLPixelFormatR8Uint:         srcBpp = 1;  srcComponents = 1; srcType = SrcType::UInt8; break;
            case MTLPixelFormatRG8Uint:        srcBpp = 2;  srcComponents = 2; srcType = SrcType::UInt8; break;
            case MTLPixelFormatRGBA8Uint:      srcBpp = 4;  srcComponents = 4; srcType = SrcType::UInt8; break;
            case MTLPixelFormatR8Sint:         srcBpp = 1;  srcComponents = 1; srcType = SrcType::SInt8; break;
            case MTLPixelFormatRG8Sint:        srcBpp = 2;  srcComponents = 2; srcType = SrcType::SInt8; break;
            case MTLPixelFormatRGBA8Sint:      srcBpp = 4;  srcComponents = 4; srcType = SrcType::SInt8; break;
            case MTLPixelFormatR16Uint:        srcBpp = 2;  srcComponents = 1; srcType = SrcType::UInt16; break;
            case MTLPixelFormatRG16Uint:       srcBpp = 4;  srcComponents = 2; srcType = SrcType::UInt16; break;
            case MTLPixelFormatRGBA16Uint:     srcBpp = 8;  srcComponents = 4; srcType = SrcType::UInt16; break;
            case MTLPixelFormatR16Sint:        srcBpp = 2;  srcComponents = 1; srcType = SrcType::SInt16; break;
            case MTLPixelFormatRG16Sint:       srcBpp = 4;  srcComponents = 2; srcType = SrcType::SInt16; break;
            case MTLPixelFormatRGBA16Sint:     srcBpp = 8;  srcComponents = 4; srcType = SrcType::SInt16; break;
            case MTLPixelFormatR32Uint:        srcBpp = 4;  srcComponents = 1; srcType = SrcType::UInt32; break;
            case MTLPixelFormatRG32Uint:       srcBpp = 8;  srcComponents = 2; srcType = SrcType::UInt32; break;
            case MTLPixelFormatRGBA32Uint:     srcBpp = 16; srcComponents = 4; srcType = SrcType::UInt32; break;
            case MTLPixelFormatR32Sint:        srcBpp = 4;  srcComponents = 1; srcType = SrcType::SInt32; break;
            case MTLPixelFormatRG32Sint:       srcBpp = 8;  srcComponents = 2; srcType = SrcType::SInt32; break;
            case MTLPixelFormatRGBA32Sint:     srcBpp = 16; srcComponents = 4; srcType = SrcType::SInt32; break;
            // Packed Metal formats — 4 bytes per pixel, 3 or 4
            // components packed into that width. Decoded via the
            // Packed SrcType branch in readSrcComponent below.
            case MTLPixelFormatRGB10A2Unorm:   srcBpp = 4; srcComponents = 4; srcType = SrcType::Packed; break;
            case MTLPixelFormatRGB10A2Uint:    srcBpp = 4; srcComponents = 4; srcType = SrcType::Packed; break;
            case MTLPixelFormatRG11B10Float:   srcBpp = 4; srcComponents = 3; srcType = SrcType::Packed; break;
            case MTLPixelFormatRGB9E5Float:    srcBpp = 4; srcComponents = 3; srcType = SrcType::Packed; break;
            default:
                return false; // Unsupported format — fall back to RGBA8
        }

        // Read the full mip level from the Metal texture.
        const NSUInteger bytesPerRow = static_cast<NSUInteger>(sourceWidth) * srcBpp;
        const std::size_t totalBytes = static_cast<std::size_t>(sourceWidth) * static_cast<std::size_t>(sourceHeight) * srcBpp;
        std::vector<std::uint8_t> raw(totalBytes);
        MTLRegion region = is3DTextureSrc
            ? MTLRegionMake3D(0, 0, depthSlice3D,
                static_cast<NSUInteger>(sourceWidth),
                static_cast<NSUInteger>(sourceHeight), 1)
            : MTLRegionMake2D(0, 0,
                static_cast<NSUInteger>(sourceWidth),
                static_cast<NSUInteger>(sourceHeight));
        [metalTex getBytes:raw.data()
               bytesPerRow:bytesPerRow
             bytesPerImage:0
                fromRegion:region
               mipmapLevel:metalMipLevel
                     slice:metalSlice];

        // Helper: read one source component as a double.
        auto readSrcComponent = [&](const std::uint8_t* srcPixel, NSUInteger comp) -> double {
            switch (srcType) {
                case SrcType::Float32: {
                    float v; std::memcpy(&v, srcPixel + comp * 4, 4); return static_cast<double>(v);
                }
                case SrcType::Float16: {
                    std::uint16_t h; std::memcpy(&h, srcPixel + comp * 2, 2);
                    // Decode half-float
                    std::uint32_t sign = (h >> 15) & 1;
                    std::uint32_t exp = (h >> 10) & 0x1F;
                    std::uint32_t mant = h & 0x3FF;
                    float result;
                    if (exp == 0) {
                        result = std::ldexp(static_cast<float>(mant), -24);
                    } else if (exp == 31) {
                        result = mant ? NAN : INFINITY;
                    } else {
                        result = std::ldexp(static_cast<float>(mant + 1024), static_cast<int>(exp) - 25);
                    }
                    return sign ? -result : result;
                }
                case SrcType::UNorm8:  return srcPixel[comp] / 255.0;
                case SrcType::SNorm8:  return std::max(static_cast<double>(reinterpret_cast<const std::int8_t*>(srcPixel)[comp]) / 127.0, -1.0);
                case SrcType::UNorm16: { std::uint16_t v; std::memcpy(&v, srcPixel + comp * 2, 2); return v / 65535.0; }
                case SrcType::SNorm16: { std::int16_t v; std::memcpy(&v, srcPixel + comp * 2, 2); return std::max(static_cast<double>(v) / 32767.0, -1.0); }
                case SrcType::UInt8:   return static_cast<double>(srcPixel[comp]);
                case SrcType::SInt8:   return static_cast<double>(reinterpret_cast<const std::int8_t*>(srcPixel)[comp]);
                case SrcType::UInt16:  { std::uint16_t v; std::memcpy(&v, srcPixel + comp * 2, 2); return static_cast<double>(v); }
                case SrcType::SInt16:  { std::int16_t v; std::memcpy(&v, srcPixel + comp * 2, 2); return static_cast<double>(v); }
                case SrcType::UInt32:  { std::uint32_t v; std::memcpy(&v, srcPixel + comp * 4, 4); return static_cast<double>(v); }
                case SrcType::SInt32:  { std::int32_t v; std::memcpy(&v, srcPixel + comp * 4, 4); return static_cast<double>(v); }
                case SrcType::Packed: {
                    // All packed formats currently supported here occupy
                    // 4 bytes (RGB10A2Unorm / RGB10A2Uint / RG11B10F /
                    // RGB9E5).
                    // Branch on Metal pixel format to extract.
                    std::uint32_t word;
                    std::memcpy(&word, srcPixel, 4);
                    if (pf == MTLPixelFormatRGB10A2Unorm) {
                        // Unsigned-normalized: 10+10+10+2 bits.
                        const std::uint32_t raw =
                            comp == 3
                                ? ((word >> 30) & 0x003u)
                                : ((word >> (comp * 10)) & 0x3FFu);
                        const std::uint32_t maxv = comp == 3 ? 3u : 1023u;
                        return static_cast<double>(raw) / static_cast<double>(maxv);
                    }
                    if (pf == MTLPixelFormatRGB10A2Uint) {
                        const std::uint32_t raw =
                            comp == 3
                                ? ((word >> 30) & 0x003u)
                                : ((word >> (comp * 10)) & 0x3FFu);
                        return static_cast<double>(raw);
                    }
                    if (pf == MTLPixelFormatRG11B10Float) {
                        // R: bits [0..10] (11-bit float, no sign)
                        // G: bits [11..21]
                        // B: bits [22..31] (10-bit float, no sign)
                        auto decode11 = [](std::uint32_t f) -> float {
                            if (f == 0) return 0.0f;
                            const std::uint32_t exp = (f >> 6) & 0x1F;
                            const std::uint32_t mant = f & 0x3F;
                            if (exp == 0) return std::ldexp(static_cast<float>(mant), -20);
                            if (exp == 31) return mant ? NAN : INFINITY;
                            return std::ldexp(static_cast<float>(mant + 64),
                                              static_cast<int>(exp) - 21);
                        };
                        auto decode10 = [](std::uint32_t f) -> float {
                            if (f == 0) return 0.0f;
                            const std::uint32_t exp = (f >> 5) & 0x1F;
                            const std::uint32_t mant = f & 0x1F;
                            if (exp == 0) return std::ldexp(static_cast<float>(mant), -19);
                            if (exp == 31) return mant ? NAN : INFINITY;
                            return std::ldexp(static_cast<float>(mant + 32),
                                              static_cast<int>(exp) - 20);
                        };
                        if (comp == 0) return decode11(word & 0x7FFu);
                        if (comp == 1) return decode11((word >> 11) & 0x7FFu);
                        if (comp == 2) return decode10((word >> 22) & 0x3FFu);
                        return 0.0;
                    }
                    if (pf == MTLPixelFormatRGB9E5Float) {
                        double r = 0.0, g = 0.0, b = 0.0;
                        unpackUF_5_9_9_9_REV(word, r, g, b);
                        if (comp == 0) return r;
                        if (comp == 1) return g;
                        if (comp == 2) return b;
                        return 0.0;
                    }
                    return 0.0;
                }
                default: return 0.0;
            }
        };

        // Determine destination component count from GL format.
        const bool isBGRA = (pf == MTLPixelFormatBGRA8Unorm);
        const std::size_t dstComponents = componentCountForFormat(format);
        const std::size_t dstBpc = bytesPerComponent(type);
        const bool typeIsPacked = isPackedPixelType(type);
        if (dstComponents == 0) return false;
        if (!typeIsPacked && dstBpc == 0) return false;
        // Bytes per pixel for packed types (bytesPerComponent returns 0).
        const std::size_t dstPackedBpp = typeIsPacked ? bytesPerPixel(format, type) : 0;
        const std::size_t dstPixelBytes = typeIsPacked
            ? dstPackedBpp : (dstComponents * dstBpc);

        // Respect GL PACK state for destination row layout. CTS
        // packed_pixels.rectangle uses PACK_ALIGNMENT=4 with 7-wide R8
        // output — row stride is 8, not 7. Writing tightly packed
        // caused column-shifts in the caller's buffer (the padding
        // byte collided with the next row's pixel 0).
        const auto& packStore = state->pixelStore();
        const bool packSwapBytes = (packStore.packSwapBytes == GL_TRUE);
        const std::size_t dstRowStridePixels = packStore.packRowLength > 0
            ? static_cast<std::size_t>(packStore.packRowLength)
            : static_cast<std::size_t>(width);
        const std::size_t dstRowBytes = alignByteCount(
            dstRowStridePixels * dstPixelBytes, packStore.packAlignment);
        const std::size_t dstSkipBytes =
            static_cast<std::size_t>(packStore.packSkipRows)   * dstRowBytes +
            static_cast<std::size_t>(packStore.packSkipPixels) * dstPixelBytes;

        // Is the destination format swizzled (BGR/BGRA components)? Packed
        // encoders need component-index remapping: `vals[]` is in RGBA
        // order from the source read, but format=GL_BGR expects components
        // encoded as (B, G, R) from the "first to last" packing position.
        const bool formatIsBGR = (format == GL_BGR || format == GL_BGR_INTEGER);
        const bool formatIsBGRA = (format == GL_BGRA || format == GL_BGRA_INTEGER);

        // Single-channel non-red formats: GREEN / BLUE / ALPHA (and their
        // _INTEGER variants) sample a specific RGBA source channel rather
        // than channel 0. Without this, `readPixels(format=GREEN, type=*)`
        // would silently return the R channel in slot 0 — CTS's gradient
        // compare flags that as a mismatch.
        const bool formatIsGreen = (format == GL_GREEN || format == GL_GREEN_INTEGER);
        const bool formatIsBlue  = (format == GL_BLUE  || format == GL_BLUE_INTEGER);
        const bool formatIsAlpha = (format == GL_ALPHA);
        // Helper: return the `i`-th GL component (per format's component
        // order) drawn from `vals[]` (which is in RGBA order). Used by
        // the packed-type encoders below.
        auto getComponent = [&](const double* vals4, int glCompIndex) -> double {
            if (formatIsBGR) {
                // BGR packing: slot 0 → B (vals[2]), slot 1 → G, slot 2 → R
                static const int map[3] = {2, 1, 0};
                return glCompIndex < 3 ? vals4[map[glCompIndex]] : 1.0;
            } else if (formatIsBGRA) {
                static const int map[4] = {2, 1, 0, 3};
                return glCompIndex < 4 ? vals4[map[glCompIndex]] : 1.0;
            } else if (formatIsGreen) {
                return glCompIndex == 0 ? vals4[1] : 0.0;
            } else if (formatIsBlue) {
                return glCompIndex == 0 ? vals4[2] : 0.0;
            } else if (formatIsAlpha) {
                return glCompIndex == 0 ? vals4[3] : 0.0;
            }
            return vals4[glCompIndex];
        };

        const bool srcIsIntegerForPacked =
            srcType == SrcType::UInt8  || srcType == SrcType::SInt8  ||
            srcType == SrcType::UInt16 || srcType == SrcType::SInt16 ||
            srcType == SrcType::UInt32 || srcType == SrcType::SInt32 ||
            (srcType == SrcType::Packed && pf == MTLPixelFormatRGB10A2Uint);
        auto packBits = [&](double v, std::uint32_t maxVal) -> std::uint32_t {
            return packReadbackBits(v, maxVal, srcIsIntegerForPacked);
        };

        auto* dest = static_cast<std::uint8_t*>(pixels);

        // Native-format FBO readback uses the framebuffer marker for
        // ordinary draw/clear producers, while still honoring the legacy
        // viewport marker for routed GS/cull producers. glGetTexImage
        // remains governed only by wasViewportRenderedTo.
        const bool yFlipNativeReadback =
            sourceNeedsFboYFlip &&
            (state->clipOrigin() != GL_UPPER_LEFT);
        for (GLsizei row = 0; row < height; ++row) {
            for (GLsizei col = 0; col < width; ++col) {
                const GLint srcX = x + col;
                const GLint glY = y + row;
                // RC-A02: OpenGL row 0 = bottom → Metal row 0 = top.
                const GLint srcY = yFlipNativeReadback ? (sourceHeight - 1 - glY) : glY;

                // Destination byte offset honours PACK_ALIGNMENT,
                // PACK_ROW_LENGTH, and PACK_SKIP_{ROWS,PIXELS}.
                const std::size_t dstByteOffset = dstSkipBytes
                    + static_cast<std::size_t>(row) * dstRowBytes
                    + static_cast<std::size_t>(col) * dstPixelBytes;
                std::uint8_t* dstPixelBase = dest + dstByteOffset;

                if (srcX < 0 || srcY < 0 || srcX >= sourceWidth || srcY >= sourceHeight) {
                    std::memset(dstPixelBase, 0, dstPixelBytes);
                    continue;
                }

                const std::uint8_t* srcPixel = raw.data() +
                    (static_cast<std::size_t>(srcY) * sourceWidth + srcX) * srcBpp;

                // Read source components as doubles.  Pad missing components
                // with 0.0 for RGB, 1.0 for alpha.
                double vals[4] = {0.0, 0.0, 0.0, 1.0};
                for (NSUInteger c = 0; c < srcComponents && c < 4; ++c) {
                    NSUInteger readComp = c;
                    if (isBGRA) {
                        // Swizzle BGRA → RGBA
                        if (c == 0) readComp = 2;
                        else if (c == 2) readComp = 0;
                    }
                    vals[c] = readSrcComponent(srcPixel, readComp);
                }

                // Packed-type encoding: one packed word per pixel rather
                // than per-component. GL 4.6 §8.4.4.4 + Table 8.8 define
                // the bit layout per (format, type) pair. Components are
                // drawn from `vals[]` in format order via getComponent.
                if (typeIsPacked) {
                    auto d = [&](int i) { return getComponent(vals, i); };
                    std::uint8_t* dstPtr = dstPixelBase;
                    switch (type) {
                        case GL_UNSIGNED_BYTE_3_3_2: {
                            // MSB → LSB: R(3) G(3) B(2)
                            const std::uint32_t r = packBits(d(0), 7);
                            const std::uint32_t g = packBits(d(1), 7);
                            const std::uint32_t b = packBits(d(2), 3);
                            dstPtr[0] = static_cast<std::uint8_t>((r << 5) | (g << 2) | b);
                            break;
                        }
                        case GL_UNSIGNED_BYTE_2_3_3_REV: {
                            // MSB → LSB: B(2) G(3) R(3) — reversed order
                            const std::uint32_t r = packBits(d(0), 7);
                            const std::uint32_t g = packBits(d(1), 7);
                            const std::uint32_t b = packBits(d(2), 3);
                            dstPtr[0] = static_cast<std::uint8_t>((b << 6) | (g << 3) | r);
                            break;
                        }
                        case GL_UNSIGNED_SHORT_5_6_5: {
                            const std::uint32_t r = packBits(d(0), 31);
                            const std::uint32_t g = packBits(d(1), 63);
                            const std::uint32_t b = packBits(d(2), 31);
                            std::uint16_t v16 = static_cast<std::uint16_t>((r << 11) | (g << 5) | b);
                            std::memcpy(dstPtr, &v16, 2);
                            break;
                        }
                        case GL_UNSIGNED_SHORT_5_6_5_REV: {
                            const std::uint32_t r = packBits(d(0), 31);
                            const std::uint32_t g = packBits(d(1), 63);
                            const std::uint32_t b = packBits(d(2), 31);
                            std::uint16_t v16 = static_cast<std::uint16_t>((b << 11) | (g << 5) | r);
                            std::memcpy(dstPtr, &v16, 2);
                            break;
                        }
                        case GL_UNSIGNED_SHORT_4_4_4_4: {
                            const std::uint32_t r = packBits(d(0), 15);
                            const std::uint32_t g = packBits(d(1), 15);
                            const std::uint32_t b = packBits(d(2), 15);
                            const std::uint32_t a = packBits(d(3), 15);
                            std::uint16_t v16 = static_cast<std::uint16_t>((r << 12) | (g << 8) | (b << 4) | a);
                            std::memcpy(dstPtr, &v16, 2);
                            break;
                        }
                        case GL_UNSIGNED_SHORT_4_4_4_4_REV: {
                            const std::uint32_t r = packBits(d(0), 15);
                            const std::uint32_t g = packBits(d(1), 15);
                            const std::uint32_t b = packBits(d(2), 15);
                            const std::uint32_t a = packBits(d(3), 15);
                            std::uint16_t v16 = static_cast<std::uint16_t>((a << 12) | (b << 8) | (g << 4) | r);
                            std::memcpy(dstPtr, &v16, 2);
                            break;
                        }
                        case GL_UNSIGNED_SHORT_5_5_5_1: {
                            const std::uint32_t r = packBits(d(0), 31);
                            const std::uint32_t g = packBits(d(1), 31);
                            const std::uint32_t b = packBits(d(2), 31);
                            const std::uint32_t a = packBits(d(3), 1);
                            std::uint16_t v16 = static_cast<std::uint16_t>((r << 11) | (g << 6) | (b << 1) | a);
                            std::memcpy(dstPtr, &v16, 2);
                            break;
                        }
                        case GL_UNSIGNED_SHORT_1_5_5_5_REV: {
                            const std::uint32_t r = packBits(d(0), 31);
                            const std::uint32_t g = packBits(d(1), 31);
                            const std::uint32_t b = packBits(d(2), 31);
                            const std::uint32_t a = packBits(d(3), 1);
                            std::uint16_t v16 = static_cast<std::uint16_t>((a << 15) | (b << 10) | (g << 5) | r);
                            std::memcpy(dstPtr, &v16, 2);
                            break;
                        }
                        case GL_UNSIGNED_INT_8_8_8_8: {
                            const std::uint32_t r = packBits(d(0), 255);
                            const std::uint32_t g = packBits(d(1), 255);
                            const std::uint32_t b = packBits(d(2), 255);
                            const std::uint32_t a = packBits(d(3), 255);
                            std::uint32_t v32 = (r << 24) | (g << 16) | (b << 8) | a;
                            std::memcpy(dstPtr, &v32, 4);
                            break;
                        }
                        case GL_UNSIGNED_INT_8_8_8_8_REV: {
                            const std::uint32_t r = packBits(d(0), 255);
                            const std::uint32_t g = packBits(d(1), 255);
                            const std::uint32_t b = packBits(d(2), 255);
                            const std::uint32_t a = packBits(d(3), 255);
                            std::uint32_t v32 = (a << 24) | (b << 16) | (g << 8) | r;
                            std::memcpy(dstPtr, &v32, 4);
                            break;
                        }
                        case GL_UNSIGNED_INT_10_10_10_2: {
                            const std::uint32_t r = packBits(d(0), 1023);
                            const std::uint32_t g = packBits(d(1), 1023);
                            const std::uint32_t b = packBits(d(2), 1023);
                            const std::uint32_t a = packBits(d(3), 3);
                            std::uint32_t v32 = (r << 22) | (g << 12) | (b << 2) | a;
                            std::memcpy(dstPtr, &v32, 4);
                            break;
                        }
                        case GL_UNSIGNED_INT_2_10_10_10_REV: {
                            const std::uint32_t r = packBits(d(0), 1023);
                            const std::uint32_t g = packBits(d(1), 1023);
                            const std::uint32_t b = packBits(d(2), 1023);
                            const std::uint32_t a = packBits(d(3), 3);
                            std::uint32_t v32 = (a << 30) | (b << 20) | (g << 10) | r;
                            std::memcpy(dstPtr, &v32, 4);
                            break;
                        }
                        case GL_UNSIGNED_INT_10F_11F_11F_REV: {
                            std::uint32_t v32 = packUF_10F11F11F_REV(d(0), d(1), d(2));
                            std::memcpy(dstPtr, &v32, 4);
                            break;
                        }
                        case GL_UNSIGNED_INT_5_9_9_9_REV: {
                            std::uint32_t v32 = packUF_5_9_9_9_REV(d(0), d(1), d(2));
                            std::memcpy(dstPtr, &v32, 4);
                            break;
                        }
                        default: {
                            // Unhandled packed type: zero the destination
                            // so we don't leak undefined memory. Tail
                            // remaining (24_8, 32F_24_8_REV) are depth-
                            // stencil formats — a separate encoder path.
                            std::memset(dstPtr, 0, dstPackedBpp);
                            break;
                        }
                    }
                    if (packSwapBytes) {
                        swapPixelStoreBytes(dstPtr, dstPackedBpp);
                    }
                    continue;
                }

                // Write to destination in the requested format/type.
                // Component c goes to dstPixelBase + c * dstBpc.
                //
                // Source-color conversion semantics (GL 4.6 §18.2.3,
                // Table 18.1): vals[] carries the source data in one
                // of two representations depending on srcType:
                //   - Float/normalized (Float32/Float16/UNorm*/SNorm*
                //     plus packed float/unorm formats):
                //     vals[c] is a float in [-1,1] or [0,1].
                //   - Integer (UInt*/SInt* / RGB10A2Uint): vals[c] is
                //     the raw signed or unsigned integer value.
                // The destination type (uint/int/float) then selects
                // whether we scale or cast directly.
                const bool srcIsNormalized =
                    (srcType == SrcType::Float32 || srcType == SrcType::Float16 ||
                     srcType == SrcType::UNorm8 || srcType == SrcType::SNorm8 ||
                     srcType == SrcType::UNorm16 || srcType == SrcType::SNorm16 ||
                     (srcType == SrcType::Packed && pf != MTLPixelFormatRGB10A2Uint));
                for (std::size_t dc = 0; dc < dstComponents; ++dc) {
                    // BGR/BGRA formats swizzle component order at write time.
                    // Previously scalars wrote vals[dc] (always RGBA order)
                    // which silently dropped the swizzle — output[GL_BGR,
                    // GL_UNSIGNED_BYTE] on a RED source ended up with the
                    // R value in slot 0 (thinking it was B) and 0s at slot 2
                    // (thinking it was R).  `getComponent` handles BGR/BGRA.
                    double v = getComponent(vals, static_cast<int>(dc));
                    std::uint8_t* dstP = dstPixelBase + dc * dstBpc;
                    switch (type) {
                        case GL_FLOAT: {
                            float fv = static_cast<float>(v);
                            std::memcpy(dstP, &fv, 4);
                            break;
                        }
                        case GL_HALF_FLOAT: {
                            float fv = static_cast<float>(v);
                            std::uint32_t fbits; std::memcpy(&fbits, &fv, 4);
                            std::uint32_t sign = (fbits >> 16) & 0x8000;
                            std::int32_t exp = ((fbits >> 23) & 0xFF) - 127 + 15;
                            std::uint32_t mant = (fbits >> 13) & 0x3FF;
                            std::uint16_t half;
                            if (exp <= 0) half = static_cast<std::uint16_t>(sign);
                            else if (exp >= 31) half = static_cast<std::uint16_t>(sign | 0x7C00);
                            else half = static_cast<std::uint16_t>(sign | (exp << 10) | mant);
                            std::memcpy(dstP, &half, 2);
                            break;
                        }
                        case GL_UNSIGNED_BYTE: {
                            // Normalized src: v * 255. Integer src: clamped cast.
                            double scaled = srcIsNormalized ? (v * 255.0 + 0.5) : v;
                            auto bv = static_cast<std::uint8_t>(
                                std::max(0.0, std::min(255.0, scaled)));
                            dstP[0] = bv;
                            break;
                        }
                        case GL_BYTE: {
                            double scaled = srcIsNormalized ? (v * 127.0) : v;
                            if (scaled >= 0) scaled += 0.5; else scaled -= 0.5;
                            auto sv = static_cast<std::int8_t>(
                                std::max(-128.0, std::min(127.0, scaled)));
                            std::memcpy(dstP, &sv, 1);
                            break;
                        }
                        case GL_UNSIGNED_SHORT: {
                            double scaled = srcIsNormalized ? (v * 65535.0 + 0.5) : v;
                            auto sv = static_cast<std::uint16_t>(
                                std::max(0.0, std::min(65535.0, scaled)));
                            std::memcpy(dstP, &sv, 2);
                            break;
                        }
                        case GL_SHORT: {
                            double scaled = srcIsNormalized ? (v * 32767.0) : v;
                            if (scaled >= 0) scaled += 0.5; else scaled -= 0.5;
                            auto sv = static_cast<std::int16_t>(
                                std::max(-32768.0, std::min(32767.0, scaled)));
                            std::memcpy(dstP, &sv, 2);
                            break;
                        }
                        case GL_UNSIGNED_INT: {
                            double scaled = srcIsNormalized
                                ? (v * 4294967295.0 + 0.5) : v;
                            auto uv = static_cast<std::uint32_t>(
                                std::max(0.0, std::min(4294967295.0, scaled)));
                            std::memcpy(dstP, &uv, 4);
                            break;
                        }
                        case GL_INT: {
                            double scaled = srcIsNormalized ? (v * 2147483647.0) : v;
                            if (scaled >= 0) scaled += 0.5; else scaled -= 0.5;
                            auto iv = static_cast<std::int32_t>(
                                std::max(-2147483648.0, std::min(2147483647.0, scaled)));
                            std::memcpy(dstP, &iv, 4);
                            break;
                        }
                        default:
                            dstP[0] = static_cast<std::uint8_t>(
                                std::max(0.0, std::min(255.0, v)));
                            break;
                    }
                    if (packSwapBytes) {
                        swapPixelStoreBytes(dstP, dstBpc);
                    }
                }
            }
        }
        return true;
    }

    // GL 4.6 §2.3.3 / ARB_conditional_render_inverted — decide whether
    // the current draw or compute dispatch should be skipped. Called
    // after basic validation; returns true when the conditional-render
    // predicate orders the command discarded.
    //
    // Non-inverted modes skip when the query result is zero (nothing
    // passed → no occlusion). Inverted modes skip when the result is
    // non-zero. WAIT vs NO_WAIT differ only in whether the driver may
    // silently proceed with stale data — we always have a flushed
    // result since our queries are CPU-credited synchronously.
    bool shouldSkipDrawForConditionalRender() const {
        if (conditionalRenderMode == 0) return false;
        const auto* q = objects->queries().get(conditionalRenderQueryId);
        if (q == nullptr) return false;
        const bool resultPositive = (q->result > 0);
        switch (conditionalRenderMode) {
            case GL_QUERY_WAIT:
            case GL_QUERY_NO_WAIT:
            case GL_QUERY_BY_REGION_WAIT:
            case GL_QUERY_BY_REGION_NO_WAIT:
                return !resultPositive;   // skip when result == 0
            case GL_QUERY_WAIT_INVERTED:
            case GL_QUERY_NO_WAIT_INVERTED:
            case GL_QUERY_BY_REGION_WAIT_INVERTED:
            case GL_QUERY_BY_REGION_NO_WAIT_INVERTED:
                return resultPositive;    // skip when result > 0
            default:
                return false;
        }
    }

    // GL 4.6 §4.2 — when a program without a GS is drawn, the
    // non-GS PRIMITIVES_GENERATED counter still advances by the
    // primitive count of the draw (strip topologies are counted
    // post-decomposition; the primitive count is `vertexCount /
    // verts-per-primitive-list-form`). TRANSFORM_FEEDBACK_PRIMI-
    // TIVES_WRITTEN advances by the same amount when transform
    // feedback is active. GS-emulated draws get these counters via
    // writeGsXfbAndCheckDiscard instead — do NOT double-count.
    //
    // CTS `direct_state_access.queries_functional` draws a 4-vertex
    // TRIANGLE_STRIP with no GS and expects PRIMITIVES_GENERATED=2
    // and TRANSFORM_FEEDBACK_PRIMITIVES_WRITTEN=2 after EndQuery.
    void updatePrimitiveCountersForNonGsDraw(GLenum mode,
                                             GLsizei vertexCount,
                                             GLsizei instanceCount,
                                             GLsizei restartSkipCount = 0);
    void updateSubmittedPipelineStatsForNonGsDraw(GLenum mode,
                                                  GLsizei vertexCount,
                                                  GLsizei instanceCount,
                                                  GLsizei restartSkipCount = 0);
    bool estimateCurrentVertexWindowDepth(float& outDepth) const;

    // Scan a client-side or PBO-backed index buffer for occurrences
    // of the current GL_PRIMITIVE_RESTART_INDEX. Returns 0 when
    // primitive-restart is disabled. CTS
    // `pipeline_statistics_query_tests_ARB.functional_primitives_
    // vertices_submitted_and_clipping_input_output_primitives` asserts
    // that GL_VERTICES_SUBMITTED skips restart sentinels.
    GLsizei countRestartIndices(GLenum type, const void* indices,
                                GLsizei count) const;
    void compactRestartIndicesForPatchTess(GLenum type,
                                           std::vector<std::uint32_t>& indices) const;

    // CPU GS emulation — write TF varyings into bound TF buffers
    // when transform feedback is active. Returns true iff the
    // current draw should be skipped (rasterizer discard was on).
    // Used by both drawArrays and drawElements after
    // `emulateGeometryDraw` succeeds.
    bool writeGsXfbAndCheckDiscard(GLProgramObject& program,
                                   const appgl::EmulatedDraw& ed);
    // CKPT162 (Sprint 14 Day 9): flush captured imageStore() writes
    // from the GS interpreter to bound Metal textures via
    // replaceRegion:. Called from writeGsXfbAndCheckDiscard prior to
    // the rasterizer-discard / TF-capture branches so the destination
    // images carry GS-emitted data on either path.
    void flushPendingImageWritesForStage(
        const std::vector<appgl::PendingImageWrite>& writes,
        const ShaderReflection* reflection,
        const std::vector<std::uint32_t>& spirv,
        GLProgramObject& program,
        GLenum stageFilter = 0,
        std::vector<GLuint>* touchedTextures = nullptr);
    // Synthesise a pass-through VS and encode the expanded vertex
    // buffer through the normal translated-draw encoder. Shared by
    // drawArrays and drawElements — the expanded buffer is already
    // flat (no indexing), so the encode is identical regardless of
    // which draw call invoked the emulator. Returns true on
    // successful encode; false lets the caller fall back to the
    // legacy no-GS path.
    bool encodeEmulatedGsDraw(GLProgramObject& program, GLuint programName,
                              const appgl::EmulatedDraw& ed,
                              AppGLSubmissionGroupKind fallbackSubgroupKind =
                                  AppGLSubmissionGroupKind::None);

    // Sprint 17 Day 7+ Bank-Group-H Path B Component D-γ — render the
    // VS+FS program against a CPU-cull-prepass-filtered original-vertex
    // index list. Mirrors the drawElements translated-pipeline path
    // (TranslatedDrawInfo + frameGraph->encodeTranslatedDraw) using
    // `filteredIndices` as a UINT32 client-side index array. Caller
    // (drawArrays / drawElements Component B branch) has already run
    // emulateVsCullPrepass and confirmed `program.needsCullDistancePrepass`
    // + line/triangle topology + non-empty filtered indices. Returns
    // true on successful encode, false on any precondition mismatch
    // OR encoder failure (caller falls through to legacy translated
    // path on false to preserve correctness).
    bool dispatchCullFilteredDraw(GLProgramObject& program,
                                  GLVertexArrayObject& vao,
                                  GLuint programName,
                                  GLenum mode,
                                  const std::vector<std::uint32_t>& filteredIndices);

    // Sprint 17 Day 7+ Bank-Group-H Path B Phase 3 day 4 — wrapper around
    // `frameGraph->encodeTranslatedDraw` that marks the bound draw FBO's
    // colour-texture attachments when the caller opted into readback Y-unflip
    // via TranslatedDrawInfo::markColorAttachmentReadbackFlip.
    bool encodeTranslatedDrawAndMarkFbo(
        TranslatedDrawInfo& tdi,
        const TranslatedDrawPreflightSnapshot* preflight = nullptr);

    // Metal-native tessellation draw path (Phase 2 of the metal-tess
    // project). When the program has been identified as a tess program
    // with a successful link-time pipeline probe, this path takes over
    // from the CPU interpreter. Populates a MetalTessDrawInfo from the
    // current GL state + bound FBO + program cache, then forwards to
    // MetalFrameGraph::encodeMetalTessellationDraw. Returns true on
    // success; false lets the caller fall through to the CPU tess
    // interpreter path.
    //
    // `instanceCount` defaults to 1 and `baseInstance` to 0 for
    // non-instanced variants; drawElements siblings can call the same
    // helper with their specific counts. `elementIndices` is
    // non-null only when the caller is routing a drawElements variant
    // through this helper (Phase 2 accepts both for uniformity even
    // though neither path is feature-rich yet — indexed tess support
    // lands later).
    bool tryMetalTessellationDraw(GLProgramObject& program,
                                   GLuint programName,
                                   GLenum mode,
                                   GLsizei count,
                                   GLint first,
                                   GLsizei instanceCount = 1,
                                   GLuint baseInstance = 0);

    // Sprint 3 Step 2 Phase 2 [metal-mesh-GS]: try the mesh-shader
    // path for tier=MeshShader programs. Returns true on successful
    // encode + commit, false on any precondition / encode failure
    // (caller falls through to CPU GS interpreter). Default-on post
    // Phase 2 close (CKPT17) — Path G + Path H verification cleared
    // the regression and locked in `gl_pointsize_value` +1 conversion
    // gain. The prior APPGL_ENABLE_MESH_GS env-gate is removed.
    bool tryMetalMeshGSDraw(GLProgramObject& program,
                            GLuint programName,
                            GLenum mode,
                            GLsizei count,
                            GLint first);

    // β [metal-tess-TF] — synthesise a Metal-tess-ready combined
    // GLProgramObject from the bound program-pipeline's separable
    // VS+TCS+TES+FS programs, mirror the link-time tess probe across
    // them, and cache the result on the pipeline. Returns:
    //   - the cached/freshly-built synthetic program when the pipeline
    //     has tess separable programs and the probe succeeds.
    //   - nullptr when the pipeline lacks tess (no TCS+TES separable
    //     pair), the probe failed, or required SPIR-V wasn't preserved
    //     on the separable programs.
    // Idempotent across calls with the same stage-program-name
    // snapshot. Re-runs the translation + probe when any stage program
    // is swapped via useProgramStages (detected by snapshot mismatch).
    GLProgramObject* ensurePipelineTessSynthesizedProgram(
        GLProgramPipelineObject& ppo);

    // Phase 3B.5 [metal-tess-TF]: after the Metal tess encoder runs the
    // TES-as-compute dispatch, walk the resulting per-vertex output
    // bytes and deposit them into the bound GL_TRANSFORM_FEEDBACK_BUFFER
    // per the program's TF-varying layout. Also bumps
    // PRIMITIVES_GENERATED / TRANSFORM_FEEDBACK_PRIMITIVES_WRITTEN
    // counters + respects GL 4.6 §13.2 primitive-fit truncation.
    void writeTessTFAndUpdateCounters(
        GLProgramObject& program,
        const std::uint8_t* tesOutBytes,
        std::uint32_t totalVerts,
        std::size_t perVertexSlotBytes,
        GLenum topology);

    // Sprint 15 Q3-Option-B Phase 3a [metal-tf-vs]: TF writer + counter
    // bump for the VS-as-compute path. Sister of
    // `writeTessTFAndUpdateCounters` — uses `program.vsTfOutputLayout`
    // + `program.vsTfResolvedSources` (populated at link time) to copy
    // per-vertex bytes from the VS-as-compute Metal dispatch output
    // buffer into the bound GL_TRANSFORM_FEEDBACK_BUFFER. Called from
    // drawArrays / drawElements VS-only-TF gate when the GPU dispatch
    // succeeds.
    void writeVsTfFromComputeOutput(
        GLProgramObject& program,
        const std::uint8_t* vsOutBytes,
        std::uint32_t totalVerts,
        std::size_t perVertexSlotBytes,
        GLenum topology);

    // Resolve the program the GS emulator should read from, handling
    // the separable-pipeline case. When `currentProgramName` is
    // non-zero (user called glUseProgram), returns that program
    // unchanged. When it's zero but a pipeline is bound AND the
    // pipeline's geometry stage has `geometryEmulated == true`, this
    // synthesises a merged view by copying the pipeline's VS
    // program's vertexSpirv + FS program's fragmentMSL onto the GS
    // program so emulateGeometryDraw / encodeEmulatedGsDraw can read
    // them through the usual GLProgramObject API. `outProgramName`
    // receives the GS program name on the pipeline path. Returns
    // nullptr when no emulation program is available.
    // Used by CTS `geometry_shader.api.createShaderProgramv` which
    // builds VS+GS+FS as three separable programs joined via a
    // pipeline — the GS program has a link-time-detected emulation-
    // subset body but no sibling VS/FS SPIR-V of its own.
    GLProgramObject* resolvePipelineEmulationProgram(
        GLuint currentProgramName, GLuint& outProgramName);

    // GL 4.6 §7.4 — program pipelines route VS / FS stages through
    // separable programs, each created via glCreateShaderProgramv or
    // glProgramParameteri(GL_PROGRAM_SEPARABLE, TRUE). When no regular
    // program is bound (glUseProgram(0) + active pipeline), the VS
    // lives on `ppo->vertexProgram` and the FS on `ppo->fragmentProgram`.
    // The translated-draw path assumes VS+FS reflection/MSL live on a
    // single program object, so this helper splices the pipeline's FS
    // onto the pipeline's VS program as the effective draw container.
    // CTS `vertex_attrib_binding.basic-usage` (+ ~25 VAB tests) uses
    // this pattern.
    //
    // Idempotent — the splice happens on every draw so a stage swap
    // via useProgramStages between draws is reflected immediately.
    // Returns nullptr when no program/pipeline is active, or when the
    // pipeline's VS is missing or unlinked.
    GLProgramObject* resolveDrawProgram(GLuint& programName);

    bool validateCurrentProgramPipelineForDraw() const;

    void encodePendingWork() {
        if (!pendingClear || frameGraph == nullptr) {
            return;
        }

        frameGraph->resizeDrawable(drawableSurfaceWidth(), drawableSurfaceHeight());
        frameGraph->encodeDefaultFramebufferClear(
            pendingMask,
            state->clearState().color[0],
            state->clearState().color[1],
            state->clearState().color[2],
            state->clearState().color[3],
            state->clearState().depth,
            state->clearState().stencil
        );
        pendingMask = 0;
        pendingClear = false;
    }

    void presentPendingWork() {
        encodePendingWork();
        if (frameGraph != nullptr) {
            frameGraph->present(AppGLCommandReason::PresentPendingWork);
        }
        markR5Boundary();
    }

    bool finishPendingWork() {
        encodePendingWork();
        const bool completed = frameGraph == nullptr ? true : frameGraph->finish();
        if (completed) {
            markR5Boundary();
        }
        return completed;
    }

    bool debugMessageEnabled(const DebugMessageRecord& message) const {
        for (auto cursor = debugControlRules.rbegin(); cursor != debugControlRules.rend(); ++cursor) {
            if (debugRuleMatches(*cursor, message)) {
                return cursor->enabled;
            }
        }
        return true;
    }

    void enqueueDebugMessage(DebugMessageRecord message) {
        if (!debugMessageEnabled(message)) {
            return;
        }
        message.message = trimDebugMessage(message.message);
        debugMessages.push_back(message);
        while (debugMessages.size() > kMaxDebugMessages) {
            debugMessages.pop_front();
        }

        if (debugCallback != nullptr) {
            debugCallback(
                message.source,
                message.type,
                message.id,
                message.severity,
                static_cast<GLsizei>(message.message.size()),
                message.message.c_str(),
                debugUserParam
            );
        }
    }

    MetalCommandBufferLease makeCommandBuffer(NSString* label) const {
        return commandSubmission != nullptr
            ? commandSubmission->makeCommandBuffer(label)
            : MetalCommandBufferLease{};
    }

    MetalCommandBufferLease makeCommandBuffer(AppGLCommandReason reason) const {
        return commandSubmission != nullptr
            ? commandSubmission->makeCommandBuffer(reason)
            : MetalCommandBufferLease{};
    }

    AppGLCommandSubmissionDebugCounters commandSubmissionDebugCounters() const {
        return commandSubmission != nullptr
            ? commandSubmission->debugCounters()
            : AppGLCommandSubmissionDebugCounters{};
    }

    void touchR5Residency(MetalR5ResidencyTouchKind kind) noexcept {
        recordMetalR5ResidencyTouch(r5Touches, kind);
    }

    std::uint64_t nextR5ResourceUseSerial() noexcept {
        return ++r5ResourceUseSerial;
    }

    void touchR5TextureView(GLTextureObject& texture) noexcept {
        texture.r5TextureViewLastUseSerial = nextR5ResourceUseSerial();
        texture.r5TextureViewLastUseBoundarySerial = r5BoundarySerial;
    }

    void touchR5PrimaryTexture(GLTextureObject& texture) noexcept {
        texture.r5PrimaryTextureLastUseSerial = nextR5ResourceUseSerial();
        texture.r5PrimaryTextureLastUseBoundarySerial = r5BoundarySerial;
    }

    bool restoreR5PrimaryTextureIfNeeded(GLTextureObject& texture,
                                         GLuint textureName) {
        if (!texture.r5PrimaryTextureEvicted) {
            if (texture.viewSourceTexture == 0 &&
                texture.metalTexture != nullptr) {
                touchR5PrimaryTexture(texture);
            }
            return true;
        }
        if (texture.viewSourceTexture != 0) {
            texture.r5PrimaryTextureEvicted = false;
            return true;
        }
        if (texture.metalTexture != nullptr) {
            texture.r5PrimaryTextureEvicted = false;
            touchR5PrimaryTexture(texture);
            return true;
        }

        if (replaceMetalTexture(texture, textureName) &&
            texture.metalTexture != nullptr) {
            texture.r5PrimaryTextureEvicted = false;
            ++r5Eviction.primaryReconstructions;
            touchR5PrimaryTexture(texture);
            return true;
        }

        ++r5Eviction.primaryReconstructionFailures;
        ++r5Eviction.reconstructionFailures;
        texture.r5PrimaryTextureEvicted = true;
        return false;
    }

    void noteR5TextureViewRebuilt(GLTextureObject& texture) noexcept {
        if (!texture.r5TextureViewEvicted) {
            return;
        }
        ++r5Eviction.textureViewRebuildsAfterR5Evict;
        texture.r5TextureViewEvicted = false;
    }

    void touchR5SwizzledTextureView(GLTextureObject& texture) noexcept {
        texture.r5SwizzledViewLastUseSerial = nextR5ResourceUseSerial();
        texture.r5SwizzledViewLastUseBoundarySerial = r5BoundarySerial;
    }

    void noteR5SwizzledViewRebuilt(GLTextureObject& texture) noexcept {
        if (!texture.r5SwizzledViewEvicted) {
            return;
        }
        ++r5Eviction.swizzledViewRebuildsAfterR5Evict;
        texture.r5SwizzledViewEvicted = false;
    }

    void touchR5ExpandedIndexCache(GLBufferObject& buffer) noexcept {
        buffer.r5ExpandedIndexLastUseSerial = nextR5ResourceUseSerial();
        buffer.r5ExpandedIndexLastUseBoundarySerial = r5BoundarySerial;
    }

    void noteR5ExpandedIndexCacheRebuilt(GLBufferObject& buffer) noexcept {
        if (!buffer.r5ExpandedIndexEvicted) {
            return;
        }
        ++r5Eviction.expandedIndexRebuildsAfterR5Evict;
        buffer.r5ExpandedIndexEvicted = false;
    }

    void markR5Boundary() {
        ++r5BoundarySerial;
        maybeRunPressureEvictionPass();
        emitR5PressureOOMIfPending();
    }

    bool r5TextureRecordLastUseMatches(const GLTextureObject& texture,
                                       const ResourceResidencyRecord& record,
                                       bool swizzled) const noexcept {
        const std::uint64_t serial = swizzled
            ? texture.r5SwizzledViewLastUseSerial
            : texture.r5TextureViewLastUseSerial;
        const std::uint64_t boundary = swizzled
            ? texture.r5SwizzledViewLastUseBoundarySerial
            : texture.r5TextureViewLastUseBoundarySerial;
        return serial == record.lastUseCommandSerial &&
               boundary == record.lastUseFrame;
    }

    bool r5PrimaryTextureRecordLastUseMatches(
        const GLTextureObject& texture,
        const ResourceResidencyRecord& record) const noexcept {
        return texture.r5PrimaryTextureLastUseSerial ==
                   record.lastUseCommandSerial &&
               texture.r5PrimaryTextureLastUseBoundarySerial ==
                   record.lastUseFrame;
    }

    bool r5ExpandedIndexRecordMatches(const GLBufferObject& buffer,
                                      const ResourceResidencyRecord& record) const noexcept {
        return buffer.r5ExpandedIndexLastUseSerial ==
                   record.lastUseCommandSerial &&
               buffer.r5ExpandedIndexLastUseBoundarySerial ==
                   record.lastUseFrame &&
               static_cast<std::uint64_t>(buffer.indexExpansionGeneration) ==
                   record.recipeId &&
               static_cast<std::uint64_t>(buffer.cachedExpansionGeneration) ==
                   record.sourceGeneration &&
               buffer.cachedExpansionGeneration ==
                   buffer.indexExpansionGeneration;
    }

    bool r5PressureRetentionAllowsRecord(
        const ResourceResidencyRecord& record,
        const R5EvictionRequest& request) const noexcept {
        if (request.reason != R5EvictionReason::Pressure ||
            request.minIdleBoundaryAge == 0) {
            return true;
        }
        if (r5BoundarySerial <= record.lastUseFrame) {
            return false;
        }
        return r5BoundarySerial - record.lastUseFrame >=
            request.minIdleBoundaryAge;
    }

    bool hasOutstandingCommandBuffers() const noexcept {
        return commandSubmission != nullptr &&
               commandSubmission->hasOutstandingCommandBuffers();
    }

    bool r5PrimaryTextureHasDependentView(GLuint textureName) const {
        if (textureName == 0 || objects == nullptr) {
            return false;
        }
        bool hasDependentView = false;
        objects->textures().forEach(
            [&](GLuint, const GLTextureObject& candidate) {
                if (candidate.viewSourceTexture == textureName) {
                    hasDependentView = true;
                }
            });
        return hasDependentView;
    }

    bool evictReconstructablePrimaryTexture(
        GLTextureObject& texture,
        const ResourceResidencyRecord& record) {
        if (record.authority !=
            MetalResidencyAuthorityClass::Reconstructable) {
            ++r5Eviction.authoritativePrimaryEvictAttempts;
            r5Eviction.evictedPrimaryAuthoritativeBytes += record.metalBytes;
            return false;
        }
        if (texture.viewSourceTexture != 0 ||
            texture.metalTexture == nullptr ||
            texture.r5PrimaryTextureEvicted) {
            return false;
        }
        if (r5PrimaryTextureAuthority(
                texture,
                r5PrimaryTextureMirrorsValid(texture),
                r5PrimaryTextureHasDependentView(record.glName)) !=
            MetalResidencyAuthorityClass::Reconstructable) {
            ++r5Eviction.authoritativePrimaryEvictAttempts;
            r5Eviction.evictedPrimaryAuthoritativeBytes += record.metalBytes;
            return false;
        }

        ++r5Eviction.primaryTextureReleaseAttempts;
        releaseRetainedMetalObject(texture.metalSwizzledView);
        texture.metalSwizzledView = nullptr;
        texture.swizzleDirty = true;
        releaseRetainedMetalObject(texture.metalSamplingProxy);
        texture.metalSamplingProxy = nullptr;
        releaseRetainedMetalObject(texture.metalTexture);
        texture.metalTexture = nullptr;
        texture.instantiated = false;
        texture.r5PrimaryTextureLastUseSerial = 0;
        texture.r5PrimaryTextureLastUseBoundarySerial = 0;
        texture.r5PrimaryTextureEvicted = true;

        ++r5Eviction.primaryTextureReleaseSuccesses;
        ++r5Eviction.selectedRecords;
        ++r5Eviction.reconstructablePrimariesEvicted;
        r5Eviction.evictedPrimaryReconstructableBytes += record.metalBytes;
        return true;
    }

    std::vector<R5EvictionCandidate> selectR5DerivedCacheEvictionCandidates(
        const MetalResourceInventory& selection,
        const R5EvictionRequest& request) {
        std::vector<R5EvictionCandidate> selected;
        selected.reserve(std::min<std::size_t>(
            selection.r5OrderingCandidates.size(),
            request.budgetRecords == 0
                ? selection.r5OrderingCandidates.size()
                : static_cast<std::size_t>(request.budgetRecords)));

        r5Eviction.candidatesSeen +=
            static_cast<std::uint64_t>(selection.r5OrderingCandidates.size());

        for (const ResourceResidencyRecord& record :
             selection.r5OrderingCandidates) {
            if (request.budgetRecords != 0 &&
                selected.size() >= request.budgetRecords) {
                ++r5Eviction.budgetSkippedRecords;
                continue;
            }
            if (!metalR5LastUseKnown(record)) {
                ++r5Eviction.unknownLastUseSkipped;
                continue;
            }
            if (!r5PressureRetentionAllowsRecord(record, request)) {
                ++r5Eviction.policyRetentionSkippedRecords;
                if (request.memoryClass == MetalMemoryPressureClass::High) {
                    ++r5Eviction.highMemoryRetentionSkippedRecords;
                }
                continue;
            }

            const MetalR5EvictionScope scope =
                metalR5EvictionScopeForRecord(record);
            if (scope == MetalR5EvictionScope::None ||
                !r5EvictionBucketAllowed(record, request.bucketAllowlist)) {
                ++r5Eviction.scopeSkipped;
                continue;
            }
            ++r5Eviction.eligibleSeen;

            if (scope == MetalR5EvictionScope::PrimaryTexture) {
                if (objects == nullptr) {
                    ++r5Eviction.objectMissingSkipped;
                    continue;
                }
                GLTextureObject* texture =
                    objects->textures().get(record.glName);
                if (texture == nullptr) {
                    ++r5Eviction.objectMissingSkipped;
                    continue;
                }
                if (texture->viewSourceTexture != 0 ||
                    texture->metalTexture == nullptr ||
                    texture->r5PrimaryTextureEvicted) {
                    ++r5Eviction.handleMissingSkipped;
                    continue;
                }
                if (!r5PrimaryTextureRecordLastUseMatches(*texture,
                                                          record)) {
                    ++r5Eviction.lastUseMismatchSkipped;
                    continue;
                }
                selected.push_back({record, kR5EvictionBucketPrimaryTexture});
                continue;
            }

            if (scope == MetalR5EvictionScope::TextureView) {
                if (objects == nullptr) {
                    ++r5Eviction.objectMissingSkipped;
                    continue;
                }
                GLTextureObject* texture =
                    objects->textures().get(record.glName);
                if (texture == nullptr) {
                    ++r5Eviction.objectMissingSkipped;
                    continue;
                }

                if (record.diagnosticBucketId ==
                    kMetalR5DiagnosticBucketTextureView) {
                    if (texture->metalSamplingProxy != nullptr) {
                        ++r5Eviction.samplingProxySkipped;
                        continue;
                    }
                    if (texture->viewSourceTexture == 0 ||
                        texture->metalTexture == nullptr) {
                        ++r5Eviction.handleMissingSkipped;
                        continue;
                    }
                    if (!r5TextureRecordLastUseMatches(*texture, record,
                                                       false)) {
                        ++r5Eviction.lastUseMismatchSkipped;
                        continue;
                    }
                    selected.push_back({record, kR5EvictionBucketTextureView});
                    continue;
                }

                if (record.diagnosticBucketId ==
                    kMetalR5DiagnosticBucketSwizzledTextureView) {
                    if (texture->metalSwizzledView == nullptr) {
                        ++r5Eviction.handleMissingSkipped;
                        continue;
                    }
                    if (!r5TextureRecordLastUseMatches(*texture, record,
                                                       true)) {
                        ++r5Eviction.lastUseMismatchSkipped;
                        continue;
                    }
                    selected.push_back(
                        {record, kR5EvictionBucketSwizzledTextureView});
                    continue;
                }

                ++r5Eviction.scopeSkipped;
                continue;
            }

            if (scope == MetalR5EvictionScope::ExpandedIndexCache) {
                if (objects == nullptr) {
                    ++r5Eviction.objectMissingSkipped;
                    continue;
                }
                GLBufferObject* buffer = objects->buffers().get(record.glName);
                if (buffer == nullptr) {
                    ++r5Eviction.objectMissingSkipped;
                    continue;
                }
                if (buffer->cachedExpandedIndices.empty()) {
                    ++r5Eviction.handleMissingSkipped;
                    continue;
                }
                if (!r5ExpandedIndexRecordMatches(*buffer, record)) {
                    ++r5Eviction.generationMismatchSkipped;
                    continue;
                }
                selected.push_back(
                    {record, kR5EvictionBucketExpandedIndexCache});
                continue;
            }
        }

        return selected;
    }

    std::uint64_t mutateR5DerivedCacheEvictionCandidates(
        const std::vector<R5EvictionCandidate>& selected,
        const R5EvictionRequest&) {
        std::uint64_t mutated = 0;
        for (const R5EvictionCandidate& candidate : selected) {
            const ResourceResidencyRecord& record = candidate.record;
            if (candidate.bucket == kR5EvictionBucketTextureView) {
                if (objects == nullptr) {
                    continue;
                }
                GLTextureObject* texture =
                    objects->textures().get(record.glName);
                if (texture == nullptr || texture->metalTexture == nullptr) {
                    continue;
                }

                ++r5Eviction.textureViewBaseReleaseAttempts;
                releaseRetainedMetalObject(texture->metalTexture);
                texture->metalTexture = nullptr;
                texture->instantiated = false;
                texture->r5TextureViewLastUseSerial = 0;
                texture->r5TextureViewLastUseBoundarySerial = 0;
                texture->r5TextureViewEvicted = true;
                ++r5Eviction.textureViewBaseReleaseSuccesses;
                ++r5Eviction.selectedRecords;
                ++r5Eviction.recordsEvictedTextureView;
                ++mutated;
                r5Eviction.reclaimedMetalViewBytes += record.metalBytes;
                continue;
            }

            if (candidate.bucket == kR5EvictionBucketSwizzledTextureView) {
                if (objects == nullptr) {
                    continue;
                }
                GLTextureObject* texture =
                    objects->textures().get(record.glName);
                if (texture == nullptr ||
                    texture->metalSwizzledView == nullptr) {
                    continue;
                }

                ++r5Eviction.swizzledViewReleaseAttempts;
                releaseRetainedMetalObject(texture->metalSwizzledView);
                texture->metalSwizzledView = nullptr;
                texture->swizzleDirty = true;
                texture->r5SwizzledViewLastUseSerial = 0;
                texture->r5SwizzledViewLastUseBoundarySerial = 0;
                texture->r5SwizzledViewEvicted = true;
                ++r5Eviction.swizzledViewReleaseSuccesses;
                ++r5Eviction.selectedRecords;
                ++r5Eviction.recordsEvictedSwizzledTextureView;
                ++mutated;
                r5Eviction.reclaimedMetalViewBytes += record.metalBytes;
                continue;
            }

            if (candidate.bucket == kR5EvictionBucketPrimaryTexture) {
                if (objects == nullptr) {
                    continue;
                }
                GLTextureObject* texture =
                    objects->textures().get(record.glName);
                if (texture == nullptr) {
                    continue;
                }
                if (evictReconstructablePrimaryTexture(*texture, record)) {
                    ++mutated;
                }
                continue;
            }

            if (candidate.bucket == kR5EvictionBucketExpandedIndexCache) {
                if (objects == nullptr) {
                    continue;
                }
                GLBufferObject* buffer = objects->buffers().get(record.glName);
                if (buffer == nullptr ||
                    buffer->cachedExpandedIndices.empty()) {
                    continue;
                }

                ++r5Eviction.expandedIndexClearAttempts;
                std::vector<std::uint8_t>().swap(buffer->cachedExpandedIndices);
                buffer->cachedExpansionGeneration = 0;
                buffer->r5ExpandedIndexLastUseSerial = 0;
                buffer->r5ExpandedIndexLastUseBoundarySerial = 0;
                buffer->r5ExpandedIndexEvicted = true;
                ++r5Eviction.expandedIndexClearSuccesses;
                ++r5Eviction.selectedRecords;
                ++r5Eviction.recordsEvictedExpandedIndexCache;
                ++mutated;
                r5Eviction.reclaimedHostCacheBytes += record.hostBytes;
                continue;
            }
        }
        return mutated;
    }

    void recordR5PressureRequest(MetalMemoryPressureState level) noexcept {
        r5Eviction.pressureLevelAtEvict = metalMemoryPressureStateValue(level);
        switch (level) {
        case MetalMemoryPressureState::Soft:
            ++r5Eviction.softPressureRequests;
            break;
        case MetalMemoryPressureState::Hard:
            ++r5Eviction.hardPressureRequests;
            break;
        case MetalMemoryPressureState::Critical:
            ++r5Eviction.criticalPressureRequests;
            break;
        case MetalMemoryPressureState::Idle:
            break;
        }
    }

    void recordR5PressurePolicy(const R5EvictionRequest& request) noexcept {
        r5Eviction.pressureMemoryClassAtEvict =
            metalMemoryPressureClassValue(request.memoryClass);
        r5Eviction.pressurePolicySoftBudget =
            request.policySoftBudgetRecords;
        r5Eviction.pressurePolicyHardBudget =
            request.policyHardBudgetRecords;
        r5Eviction.pressurePolicyCriticalBudget =
            request.policyCriticalBudgetRecords;
        r5Eviction.pressurePolicyMinIdleBoundaryAge =
            request.minIdleBoundaryAge;
        switch (request.memoryClass) {
        case MetalMemoryPressureClass::Low:
            ++r5Eviction.lowMemoryPolicyPasses;
            break;
        case MetalMemoryPressureClass::High:
            ++r5Eviction.highMemoryPolicyPasses;
            break;
        case MetalMemoryPressureClass::Mid:
        case MetalMemoryPressureClass::Unknown:
            ++r5Eviction.midMemoryPolicyPasses;
            break;
        }
    }

    bool r5CriticalPressureStillActive(
        const MetalResourceInventory& inventory) {
        const auto snapshot =
            Runtime::shared().sampleMemoryPressure(inventory.pressure);
        return metalMemoryPressureStateFromValue(snapshot.state) ==
            MetalMemoryPressureState::Critical;
    }

    void maybeLatchR5CriticalPressureOOM(
        const R5EvictionRequest& request,
        const MetalResourceInventory& pre,
        const MetalResourceInventory& post,
        std::size_t selectedCount,
        std::uint64_t mutated) {
        if (request.reason != R5EvictionReason::Pressure ||
            request.pressureLevel != MetalMemoryPressureState::Critical ||
            !r5CriticalPressureStillActive(post)) {
            return;
        }

        const std::uint64_t deviceBytesFreed =
            pre.deviceAllocatedBytes > post.deviceAllocatedBytes
                ? pre.deviceAllocatedBytes - post.deviceAllocatedBytes
                : 0;
        const bool noCandidates = selectedCount == 0;
        const bool noRelief = mutated == 0 && deviceBytesFreed == 0;
        const bool budgetExhausted = request.budgetRecords != 0 &&
            selectedCount >= request.budgetRecords;
        if (!noRelief) {
            return;
        }

        r5PressureOOMPending = true;
        ++r5Eviction.criticalPressureExhaustionLatches;
        ++r5Eviction.criticalPressureStillCriticalLatches;
        if (noCandidates) {
            ++r5Eviction.criticalPressureNoCandidateLatches;
        }
        if (noRelief) {
            ++r5Eviction.criticalPressureNoReliefLatches;
        }
        if (budgetExhausted) {
            ++r5Eviction.criticalPressureBudgetExhaustedLatches;
        }
    }

    void emitR5PressureOOMIfPending() {
        if (!r5PressureOOMPending || owner == nullptr) {
            return;
        }
        r5PressureOOMPending = false;
        ++r5Eviction.criticalPressureOOMErrors;
        owner->pushError(
            GL_OUT_OF_MEMORY,
            "R5PressureEviction",
            "Critical memory-pressure eviction exhausted reconstructable "
            "R5 candidates without relieving pressure.");
    }

    std::uint64_t evictR5DerivedCaches(const R5EvictionRequest& request) {
        if (r5EvictionInProgress) {
            return 0;
        }
        r5EvictionInProgress = true;
        struct EvictionProgressGuard {
            bool& value;
            ~EvictionProgressGuard() { value = false; }
        } guard{r5EvictionInProgress};

        if (request.reason == R5EvictionReason::Test) {
            ++r5Eviction.explicitTriggerRequests;
        } else {
            ++r5Eviction.passesTriggered;
            recordR5PressureRequest(request.pressureLevel);
            recordR5PressurePolicy(request);
        }
        r5Eviction.lastBudget = request.budgetRecords;
        const bool enabled = request.reason == R5EvictionReason::Pressure
            ? Runtime::shared().r5EvictionEnabledCached()
            : Runtime::shared().refreshR5EvictionEnabled();
        r5Eviction.enabled = enabled ? 1 : 0;
        if (r5Eviction.enabled == 0) {
            ++r5Eviction.passSkippedDisabled;
            return 0;
        }

        ++r5Eviction.passAttempts;
        const MetalResourceInventory pre = owner != nullptr
            ? owner->metalResourceInventory()
            : MetalResourceInventory{};
        r5Eviction.lastPreTextureViewCount = pre.textureViewCount;
        r5Eviction.lastPreTextureViewBytes = pre.textureViewBytes;
        r5Eviction.lastPreExpandedIndexBuffers = pre.expandedIndexBuffers;
        r5Eviction.lastPreExpandedIndexBytes = pre.expandedIndexBytes;

        if (request.reason == R5EvictionReason::Test) {
            ++r5Eviction.drainRequests;
            if (!finishPendingWork()) {
                ++r5Eviction.drainFailures;
                return 0;
            }
        }

        const MetalResourceInventory selection = owner != nullptr
            ? owner->metalResourceInventory()
            : MetalResourceInventory{};
        const std::vector<R5EvictionCandidate> selected =
            selectR5DerivedCacheEvictionCandidates(selection, request);

        if (request.reason == R5EvictionReason::Pressure &&
            hasOutstandingCommandBuffers()) {
            if (selected.empty()) {
                ++r5Eviction.passSkippedPressure;
                return 0;
            }
            ++r5Eviction.drainRequests;
            if (!finishPendingWork()) {
                ++r5Eviction.drainFailures;
                r5Eviction.candidatesGatedInFlight +=
                    static_cast<std::uint64_t>(selected.size());
                ++r5Eviction.passSkippedPressure;
                return 0;
            }
        }

        const std::uint64_t mutated =
            mutateR5DerivedCacheEvictionCandidates(selected, request);
        r5Eviction.mutatedRecords += mutated;
        ++r5Eviction.passCompleted;

        const MetalResourceInventory post = owner != nullptr
            ? owner->metalResourceInventory()
            : MetalResourceInventory{};
        r5Eviction.lastPostTextureViewCount = post.textureViewCount;
        r5Eviction.lastPostTextureViewBytes = post.textureViewBytes;
        r5Eviction.lastPostExpandedIndexBuffers = post.expandedIndexBuffers;
        r5Eviction.lastPostExpandedIndexBytes = post.expandedIndexBytes;
        if (pre.deviceAllocatedBytes > post.deviceAllocatedBytes) {
            const std::uint64_t freed =
                pre.deviceAllocatedBytes - post.deviceAllocatedBytes;
            r5Eviction.deviceBytesFreed +=
                freed;
            if (request.reason == R5EvictionReason::Pressure &&
                request.memoryClass == MetalMemoryPressureClass::High) {
                r5Eviction.highMemoryDeviceBytesFreed += freed;
                if (request.pressureLevel ==
                    MetalMemoryPressureState::Critical) {
                    ++r5Eviction.highMemoryCriticalReliefPasses;
                }
            }
        }
        maybeLatchR5CriticalPressureOOM(request,
                                        pre,
                                        post,
                                        selected.size(),
                                        mutated);
        return mutated;
    }

    void maybeRunPressureEvictionPass() {
        if (r5EvictionInProgress || !r5EvictionEnabled()) {
            return;
        }
        const MetalResourceInventory inventory = owner != nullptr
            ? owner->metalResourceInventory()
            : MetalResourceInventory{};
        const auto snapshot =
            Runtime::shared().sampleMemoryPressureForR5Boundary(
                inventory.pressure);
        const MetalMemoryPressureState sampledLevel =
            metalMemoryPressureStateFromValue(snapshot.state);
        const MetalMemoryPressureState pendingLevel =
            metalMemoryPressureStateFromValue(
                snapshot.inputs.pendingPressurePeak);
        const R5PressureEvictionPolicy pressurePolicy =
            r5PressureEvictionPolicyForSnapshot(snapshot);
        const MetalMemoryPressureState level =
            r5MaxPressureLevel(sampledLevel, pendingLevel);
        const bool consumedPendingPressure =
            pendingLevel != MetalMemoryPressureState::Idle;
        if (consumedPendingPressure) {
            ++r5Eviction.pendingPressureBoundaryConsumes;
            r5Eviction.pendingPressurePeakAtBoundary =
                metalMemoryPressureStateValue(pendingLevel);
        }
        if (level == MetalMemoryPressureState::Idle) {
            lastR5PressureEvictionLevel = MetalMemoryPressureState::Idle;
            return;
        }
        if (level == lastR5PressureEvictionLevel &&
            !consumedPendingPressure) {
            ++r5Eviction.passesSkippedHysteresis;
            return;
        }

        R5EvictionRequest request;
        request.reason = R5EvictionReason::Pressure;
        request.pressureLevel = level;
        request.memoryClass = pressurePolicy.memoryClass;
        request.minIdleBoundaryAge =
            r5PressureRetentionAgeForLevel(level, pressurePolicy);
        request.policySoftBudgetRecords = pressurePolicy.softBudgetRecords;
        request.policyHardBudgetRecords = pressurePolicy.hardBudgetRecords;
        request.policyCriticalBudgetRecords =
            pressurePolicy.criticalBudgetRecords;
        request.budgetRecords =
            r5PressureBudgetForLevel(level, pressurePolicy);
        request.bucketAllowlist = pressurePolicy.bucketAllowlist;
        const std::uint64_t skippedPressureBefore =
            r5Eviction.passSkippedPressure;
        const std::uint64_t retentionSkippedBefore =
            r5Eviction.policyRetentionSkippedRecords;
        const std::uint64_t mutatedRecordsBefore = r5Eviction.mutatedRecords;
        evictR5DerivedCaches(request);
        const bool skippedInFlight =
            r5Eviction.passSkippedPressure != skippedPressureBefore;
        const bool deferredByRetention =
            r5Eviction.mutatedRecords == mutatedRecordsBefore &&
            r5Eviction.policyRetentionSkippedRecords != retentionSkippedBefore;
        if (!skippedInFlight && !deferredByRetention) {
            lastR5PressureEvictionLevel = level;
        }
    }

    std::uint64_t evictR5DerivedCachesForTesting(std::uint64_t budget) {
        R5EvictionRequest request;
        request.reason = R5EvictionReason::Test;
        request.budgetRecords = budget;
        request.bucketAllowlist = kR5EvictionBucketAll;
        return evictR5DerivedCaches(request);
    }

    CAMetalLayer* layer = nil;
    id<MTLDevice> device = nil;
    id<MTLCommandQueue> commandQueue = nil;
    std::unique_ptr<MetalCommandSubmission> commandSubmission;
    std::unique_ptr<MetalFrameGraph> frameGraph;
    std::unique_ptr<GLCapabilities> capabilities;
    std::unique_ptr<GLObjectStore> objects;
    std::unique_ptr<GLStateTracker> state;
    GLDrawPathProfile drawPathProfile;
    SerialDeferredRecordProfile serialDeferredRecordProfile;
    mutable GLDrawDetailProfile drawDetailProfile;
    mutable ColdPathDiagnosticProfile coldPathProfile;
    Phase2PlanKeyProfile phase2PlanKeyProfile;
    MetalR5ResidencyTouchSummary r5Touches;
    MetalR5EvictionSummary r5Eviction;
    std::uint64_t r5ResourceUseSerial = 0;
    std::uint64_t r5BoundarySerial = 0;
    MetalMemoryPressureState lastR5PressureEvictionLevel =
        MetalMemoryPressureState::Idle;
    bool r5EvictionInProgress = false;
    bool r5PressureOOMPending = false;
    std::unordered_map<std::uint64_t, TranslatedDrawPlan> translatedDrawPlanCache;
    Phase2PlanKeyMemo translatedDrawPlanKeyMemo;
    std::uint64_t translatedDrawPlanGeneration = 0;
    std::unordered_map<NSUInteger, void*> incompleteSampledColorTextures;
    // Slice-B [A]: sparse-buffer MDI can expose stale sampler recipe metadata
    // when the persistent recipe is reused. Bypass it only while decomposing
    // that draw shape; ordinary draws keep Slice-B's hot-path cache.
    bool samplerRecipeCacheBypassForSparseMdi = false;

    // Phase 8X Group 4d follow-up⁸ — one-shot-per-key dedup sets for the
    // sampler-resolution / sampler-build diagnostic logs. Both fire at
    // most once per key per process so the hot draw path stays quiet
    // after the first draw that exercises each program / texture. The
    // existing follow-up³ fall-through instrumentation and follow-up⁴
    // pipeline-build error surfacing both use identical one-shot dedup
    // patterns; these sit next to them for the sampler path. See
    // `resolveSamplerBindings` and `rebuildTextureSamplerState`.
    std::unordered_set<GLuint> loggedSamplerResolvePrograms;
    std::unordered_set<GLuint> loggedSamplerBuildTextures;
    // Phase 8X Group 4d follow-up¹⁰/¹¹ — dedup state for the RGBA8
    // upload-bytes fingerprint log emitted from `replaceMetalTexture`.
    //
    // Follow-up¹⁰ shape was `std::unordered_set<GLuint>` — one log per
    // GL texture name per process. BAR's followup¹⁰ verification
    // revealed that's too narrow: Recoil allocates with
    // `glTexImage2D(w,h,NULL)` (or a 1×1 placeholder) and then calls
    // `glTexImage2D(real w, real h, real bytes)` to reupload — the
    // second call reaches `replaceMetalTexture` but the texName was
    // already in the set, so the fingerprint never re-fires and we
    // miss the real glyph payload entirely.
    //
    // Follow-up¹¹ widens the key to `(width, height, rgba8Bytes)` so
    // the fingerprint re-fires whenever any of those change. That
    // catches both the `NULL → real` allocation pattern and the
    // `1×1 → N×M` reallocation pattern described in §Primary of
    // `docs/phase-8x-group-4d-followup10-verification.md`. The log
    // line includes a `reFire=...` field naming which component
    // changed so BAR can tell a realloc from a first upload at a
    // glance.
    struct UploadFingerprintKey {
        GLsizei width = 0;
        GLsizei height = 0;
        std::size_t rgba8Bytes = 0;
    };
    std::unordered_map<GLuint, UploadFingerprintKey> loggedUploadTextures;
    // Phase 8X Group 4d follow-up¹¹ — §Secondary per-subregion dedup
    // for the `texSubImage` fingerprint log. Keyed on
    // `(texName, xoffset, yoffset, width, height)` so each distinct
    // updated rectangle on a given texture fires at most once.
    // Recoil's glyph cache streams per-glyph sub-images into a single
    // atlas texture; this keeps the log from flooding while still
    // capturing the first update at every distinct offset.
    struct SubImageRegionKey {
        GLuint texName = 0;
        GLint xoffset = 0;
        GLint yoffset = 0;
        GLsizei width = 0;
        GLsizei height = 0;
        bool operator==(const SubImageRegionKey& other) const {
            return texName == other.texName
                && xoffset == other.xoffset
                && yoffset == other.yoffset
                && width == other.width
                && height == other.height;
        }
    };
    struct SubImageRegionKeyHash {
        std::size_t operator()(const SubImageRegionKey& k) const noexcept {
            // Simple FNV-1a of the five fields as raw bytes. Not
            // cryptographic, just needs to spread well for an
            // unordered_set bucket count in the low thousands (one
            // entry per distinct sub-image rect per texture).
            std::uint64_t h = 0xcbf29ce484222325ull;
            auto mix = [&h](std::uint32_t v) {
                for (int i = 0; i < 4; ++i) {
                    h ^= static_cast<std::uint8_t>(v >> (i * 8));
                    h *= 0x100000001b3ull;
                }
            };
            mix(k.texName);
            mix(static_cast<std::uint32_t>(k.xoffset));
            mix(static_cast<std::uint32_t>(k.yoffset));
            mix(static_cast<std::uint32_t>(k.width));
            mix(static_cast<std::uint32_t>(k.height));
            return static_cast<std::size_t>(h);
        }
    };
    std::unordered_set<SubImageRegionKey, SubImageRegionKeyHash> loggedSubImageRegions;
    // Per-context fixed-function matrix mirror. Compat-profile matrix
    // entry points (defined in src/runtime/AppGLMatrixOverrides.cpp)
    // route through this member, and the draw path reads from it to
    // populate the synthesized `appgl_*` shader uniforms produced by
    // the compat-shader rewriter (src/shader/CompatShaderRewrite.h).
    MatrixStateMirror matrixState;
    GLbitfield pendingMask = GL_COLOR_BUFFER_BIT;
    bool pendingClear = true;
    std::vector<std::uint8_t> defaultFramebufferRGBA8;
    GLsizei defaultFramebufferShadowWidth = 0;
    GLsizei defaultFramebufferShadowHeight = 0;
    bool defaultFramebufferShadowValid = false;
    GLint viewportX = 0;
    GLint viewportY = 0;
    GLsizei viewportWidth = 1280;
    GLsizei viewportHeight = 720;

    // RC-A02: compute the minimum drawable size that covers the viewport
    // extent (offset + dimensions).  Used by draw paths and setViewport.
    GLsizei drawableSurfaceWidth() const {
        return static_cast<GLsizei>(std::max(0, viewportX)) + viewportWidth;
    }
    GLsizei drawableSurfaceHeight() const {
        return static_cast<GLsizei>(std::max(0, viewportY)) + viewportHeight;
    }

    void invalidateDefaultFramebufferShadow() {
        defaultFramebufferShadowValid = false;
    }

    void ensureDefaultFramebufferShadow() {
        const GLsizei width = std::max<GLsizei>(drawableSurfaceWidth(), 1);
        const GLsizei height = std::max<GLsizei>(drawableSurfaceHeight(), 1);
        const std::size_t byteCount =
            static_cast<std::size_t>(width) *
            static_cast<std::size_t>(height) * 4u;
        if (defaultFramebufferShadowWidth != width ||
            defaultFramebufferShadowHeight != height ||
            defaultFramebufferRGBA8.size() != byteCount) {
            defaultFramebufferRGBA8.assign(byteCount, 0);
            defaultFramebufferShadowWidth = width;
            defaultFramebufferShadowHeight = height;
        }
        defaultFramebufferShadowValid = true;
    }

    void applyDefaultFramebufferColorClear() {
        ensureDefaultFramebufferShadow();
        const std::uint8_t rgba[4] = {
            normalizedByte(state->clearState().color[0]),
            normalizedByte(state->clearState().color[1]),
            normalizedByte(state->clearState().color[2]),
            normalizedByte(state->clearState().color[3]),
        };

        GLsizei minX = 0;
        GLsizei maxX = defaultFramebufferShadowWidth;
        GLsizei minY = 0;
        GLsizei maxY = defaultFramebufferShadowHeight;
        if (state->isEnabled(GL_SCISSOR_TEST)) {
            const GLScissorState& s = state->scissor();
            minX = std::max<GLsizei>(0, s.x);
            maxX = std::min<GLsizei>(defaultFramebufferShadowWidth,
                                     s.x + s.width);
            minY = std::max<GLsizei>(0, s.y);
            maxY = std::min<GLsizei>(defaultFramebufferShadowHeight,
                                     s.y + s.height);
        }
        if (minX >= maxX || minY >= maxY) {
            return;
        }

        const GLBlendState& blend = state->blendState();
        for (GLsizei y = minY; y < maxY; ++y) {
            for (GLsizei x = minX; x < maxX; ++x) {
                const std::size_t offset =
                    (static_cast<std::size_t>(y) *
                     static_cast<std::size_t>(defaultFramebufferShadowWidth) +
                     static_cast<std::size_t>(x)) * 4u;
                for (int c = 0; c < 4; ++c) {
                    if (blend.colorMask[c] != GL_FALSE) {
                        defaultFramebufferRGBA8[offset + static_cast<std::size_t>(c)] =
                            rgba[c];
                    }
                }
            }
        }
    }

    bool copyDefaultFramebufferShadowPixels(
        GLint x,
        GLint y,
        GLsizei width,
        GLsizei height,
        void* outPixels
    ) const {
        if (!defaultFramebufferShadowValid || outPixels == nullptr ||
            width < 0 || height < 0) {
            return false;
        }
        auto* bytes = static_cast<std::uint8_t*>(outPixels);
        for (GLsizei row = 0; row < height; ++row) {
            for (GLsizei col = 0; col < width; ++col) {
                const GLint srcX = x + col;
                const GLint srcY = y + row;
                const std::size_t dstOffset =
                    static_cast<std::size_t>(row * width + col) * 4u;
                if (srcX < 0 || srcY < 0 ||
                    srcX >= defaultFramebufferShadowWidth ||
                    srcY >= defaultFramebufferShadowHeight) {
                    std::memset(bytes + dstOffset, 0, 4);
                    continue;
                }
                const std::size_t srcOffset =
                    (static_cast<std::size_t>(srcY) *
                     static_cast<std::size_t>(defaultFramebufferShadowWidth) +
                     static_cast<std::size_t>(srcX)) * 4u;
                std::memcpy(bytes + dstOffset,
                            defaultFramebufferRGBA8.data() + srcOffset, 4);
            }
        }
        return true;
    }

    GLDEBUGPROC debugCallback = nullptr;
    const void* debugUserParam = nullptr;
    std::deque<DebugMessageRecord> debugMessages;
    std::vector<DebugControlRule> debugControlRules;
    std::vector<DebugMessageRecord> debugGroupStack;
    std::unordered_map<std::uint64_t, std::string> objectLabels;
    std::unordered_map<const void*, std::string> pointerLabels;
    std::deque<GLenum> errors;
    // Transform feedback active state (CTS api_errors_test).
    // Sprint 8 #9-B (CKPT85): the global transformFeedbackActive /
    // transformFeedbackPaused flags are now the LEGACY mirror used only
    // for the implicit default TF object (id=0). When a non-zero TF
    // object is bound, the per-object `tf->active` / `tf->paused`
    // fields are the source of truth — see GLContext::is*() getters.
    // Use isTfActiveOnBoundImpl() / isTfPausedOnBoundImpl() helpers
    // below from inside Impl methods to consult the right-per-object
    // state.
    bool transformFeedbackActive = false;
    bool transformFeedbackPaused = false;
    GLenum transformFeedbackPrimitiveMode = GL_POINTS;
    GLuint boundTransformFeedbackId = 0;
    std::array<GLsizei, GLTransformFeedbackObject::kMaxTransformFeedbackStreams> defaultTransformFeedbackCapturedVertexCount{};
    std::array<std::uint32_t, kTrackedQueryTargetCount> activeQueryTargetCounts{};
    std::uint64_t activeQueryTargetMask = 0;

    // CKPT85 helpers — Impl methods can't call the public GLContext
    // getters directly without a back-pointer dance, so these inlines
    // duplicate the lookup. Default TF object (id=0) falls back to
    // the legacy global flag; non-zero IDs read the per-object field.
    bool isTfActiveOnBoundImpl() const;
    bool isTfPausedOnBoundImpl() const;

    // GL 3.0 / GL 4.5 ARB_conditional_render_inverted — `glBeginConditional-
    // Render(id, mode)` makes subsequent draws conditional on the named
    // occlusion query's result. When active, drawArrays/drawElements inspect
    // the query and skip when the predicate matches. `mode`:
    //   GL_QUERY_WAIT / GL_QUERY_BY_REGION_WAIT / GL_QUERY_NO_WAIT /
    //   GL_QUERY_BY_REGION_NO_WAIT → skip draw when query result == 0
    //   GL_QUERY_*_INVERTED variants                   → skip draw when > 0
    // The BY_REGION variants differ from non-region only in whether the
    // query's scissor is considered; on AppGL (no screen-space region
    // query) the same skip logic applies.
    GLuint conditionalRenderQueryId = 0;
    GLenum conditionalRenderMode = 0;  // 0 = no conditional render active
    bool occlusionApproxDepthKnown = true;
    float occlusionApproxDepth = 1.0f;

    // Persistent "default VAO" — lazy-allocated stand-alone object
    // returned by currentVertexArrayOrDefault() when no user VAO is
    // bound. Real drivers expose an implicit default VAO at context
    // init; CTS tests (e.g. `get_uniform_tests`) rely on that
    // behaviour by calling glEnableVertexAttribArray without first
    // binding a VAO. The object lives on Impl so glGenVertexArrays
    // still issues fresh names starting at 1.
    GLVertexArrayObject defaultVertexArray;
    bool defaultVertexArrayReady = false;
    struct Fp64GraphicsSidecarSync {
        GLBufferObject* buffer = nullptr;
        const ShaderReflection::ResourceBinding* binding = nullptr;
        GLBufferObject::Fp64TransportSidecar* sidecar = nullptr;
    };
    std::vector<Fp64GraphicsSidecarSync> pendingFp64GraphicsSsboSidecars;
    // Per-context immediate double vertex attribute values (GL 4.1 glVertexAttribL*).
    // Indexed by attribute slot; each stores 4 doubles (default {0,0,0,1}).
    // Mirrors GL_MAX_VERTEX_ATTRIBS / GLObjectStore construction above.
    // CTS vertex_attrib_64bit exercises constant L-attributes across every
    // reported slot, so this shadow must cover all advertised attributes.
    static constexpr std::size_t kMaxImmediateDoubleAttribs = 32;
    std::array<std::array<GLdouble, 4>, kMaxImmediateDoubleAttribs> immediateDoubleAttribs{};
    std::array<std::array<GLint, 4>, kMaxImmediateDoubleAttribs> immediateIntAttribs{};
    std::array<std::array<GLuint, 4>, kMaxImmediateDoubleAttribs> immediateUIntAttribs{};
    std::array<GLVertexAttributeState::ImmediateKind, kMaxImmediateDoubleAttribs> immediateAttribKinds{};

    // Phase 8X Group 4d follow-up¹⁷ — compat-profile immediate-mode
    // capture state.
    //
    // When `glBegin(mode)` fires we flip `active = true`, record the
    // primitive mode, and start accumulating vertices into `vertices`.
    // `glColor*` and `glTexCoord*` update the per-vertex registers
    // without emitting; `glVertex*` pushes one interleaved
    // `{pos[4], color[4], texcoord[2]}` tuple into the buffer using the
    // current registers. `glEnd` expands `GL_QUADS` to triangles
    // CPU-side (Metal core has no quads primitive), resolves the
    // currently-bound unit-0 GL_TEXTURE_2D for the textured-vs-untextured
    // pipeline choice, and hands the buffer off to
    // `MetalFrameGraph::encodeImmediateModeDraw`.
    //
    // The capture buffer reuses this struct across calls (we only
    // `clear()` the vector on `beginImmediate`) so per-batch allocations
    // stay amortized. The 40-byte vertex matches the vertex descriptor
    // set up in `MetalFrameGraph::ensureImmediateModePipeline`.
    struct ImmediateModeVertex {
        float position[4];
        float color[4];
        float texcoord[2];
    };
    static_assert(sizeof(ImmediateModeVertex) == 40,
                  "ImmediateModeVertex must be 40 bytes to match the vertex descriptor in MetalFrameGraph::ensureImmediateModePipeline");
    struct ImmediateModeCapture {
        bool active = false;
        GLenum mode = 0;
        float currentColor[4] = {1.0f, 1.0f, 1.0f, 1.0f};
        float currentTexcoord[2] = {0.0f, 0.0f};
        std::vector<ImmediateModeVertex> vertices;
    };
    ImmediateModeCapture immediate;
    // GL 4.2 — image load/store unit bindings.
    struct ImageBinding {
        GLuint texture = 0;
        GLint level = 0;
        GLboolean layered = GL_FALSE;
        GLint layer = 0;
        GLenum access = GL_READ_ONLY;
        // GL 4.6 §8.26 Table 23.43 — initial value is GL_R8 per spec.
        // CTS `shader_image_load_store.basic-api-bind` verifies this.
        GLenum format = GL_R8;
        // Sprint 18 Bucket 3 native storage image binding format:
        // extend CKPT119's mip-level view cache to include the
        // glBindImageTexture image format. GL image bindings may legally
        // reinterpret a same-size texture (for example GL_R32I storage
        // viewed as RG16F/RGBA8/SNORM), while SPIRV-Cross emits the MSL
        // texture element type from the image uniform format. Without a
        // PixelFormatView-backed Metal view, native VS/FS/compute paths
        // bind the base R32Sint texture into float storage-image slots.
        void* metalLevelView = nullptr;
        GLuint cachedViewTexture = 0;  // texture name the view was created from
        GLint cachedViewLevel = -1;    // level the view was created for
        GLenum cachedViewFormat = 0;   // image binding format used for the view
        GLboolean cachedViewLayered = GL_TRUE;
        GLint cachedViewLayer = 0;
        GLenum cachedViewTarget = 0;
        // Metal cannot view one 3D depth slice as texture2d, so
        // non-layered image2D bindings of texture3D use a 2D sidecar.
        void* layer3DSidecarTexture = nullptr;
        GLuint layer3DSidecarSourceTexture = 0;
        GLint layer3DSidecarLevel = -1;
        GLint layer3DSidecarLayer = 0;
        GLenum layer3DSidecarFormat = 0;
        bool layer3DSidecarDirty = false;
        void* sparseSidecarLevelView = nullptr;
        GLuint sparseCachedViewTexture = 0;
        GLint sparseCachedViewLevel = -1;
        GLenum sparseCachedViewFormat = 0;
        GLboolean sparseCachedViewLayered = GL_TRUE;
        GLint sparseCachedViewLayer = 0;
        GLenum sparseCachedViewTarget = 0;
        void* sparseCachedViewBase = nullptr;

        void invalidateMetalView() {
            if (metalLevelView != nullptr) {
                releaseRetainedMetalObject(metalLevelView);
            }
            if (sparseSidecarLevelView != nullptr) {
                releaseRetainedMetalObject(sparseSidecarLevelView);
            }
            if (layer3DSidecarTexture != nullptr) {
                releaseRetainedMetalObject(layer3DSidecarTexture);
            }
            metalLevelView = nullptr;
            cachedViewTexture = 0;
            cachedViewLevel = -1;
            cachedViewFormat = 0;
            cachedViewLayered = GL_TRUE;
            cachedViewLayer = 0;
            cachedViewTarget = 0;
            layer3DSidecarTexture = nullptr;
            layer3DSidecarSourceTexture = 0;
            layer3DSidecarLevel = -1;
            layer3DSidecarLayer = 0;
            layer3DSidecarFormat = 0;
            layer3DSidecarDirty = false;
            sparseSidecarLevelView = nullptr;
            sparseCachedViewTexture = 0;
            sparseCachedViewLevel = -1;
            sparseCachedViewFormat = 0;
            sparseCachedViewLayered = GL_TRUE;
            sparseCachedViewLayer = 0;
            sparseCachedViewTarget = 0;
            sparseCachedViewBase = nullptr;
        }
    };

    void flushImageBinding3DLayerSidecar(ImageBinding& ib) {
        if (!ib.layer3DSidecarDirty ||
            ib.layer3DSidecarTexture == nullptr ||
            ib.layer3DSidecarSourceTexture == 0 ||
            objects == nullptr) {
            return;
        }
        if (frameGraph != nullptr) {
            frameGraph->flushForReadback();
        }
        GLTextureObject* texObj =
            objects->textures().get(ib.layer3DSidecarSourceTexture);
        id<MTLTexture> srcTex = texObj != nullptr
            ? (__bridge id<MTLTexture>)texObj->metalTexture
            : nil;
        id<MTLTexture> sidecar =
            (__bridge id<MTLTexture>)ib.layer3DSidecarTexture;
        if (srcTex == nil || sidecar == nil ||
            srcTex.textureType != MTLTextureType3D ||
            ib.layer3DSidecarLevel < 0 ||
            static_cast<NSUInteger>(ib.layer3DSidecarLevel) >=
                srcTex.mipmapLevelCount) {
            ib.layer3DSidecarDirty = false;
            return;
        }

        const NSUInteger mip =
            static_cast<NSUInteger>(ib.layer3DSidecarLevel);
        const NSUInteger width = std::max<NSUInteger>(srcTex.width >> mip, 1);
        const NSUInteger height = std::max<NSUInteger>(srcTex.height >> mip, 1);
        const NSUInteger depth = std::max<NSUInteger>(srcTex.depth >> mip, 1);
        if (ib.layer3DSidecarLayer < 0 ||
            static_cast<NSUInteger>(ib.layer3DSidecarLayer) >= depth ||
            sidecar.width != width ||
            sidecar.height != height) {
            ib.layer3DSidecarDirty = false;
            return;
        }
        const auto fmtInfo = nativeFormatInfo(sidecar.pixelFormat);
        if (fmtInfo.bytesPerPixel <= 0) {
            ib.layer3DSidecarDirty = false;
            return;
        }
        const NSUInteger bytesPerRow =
            width * static_cast<NSUInteger>(fmtInfo.bytesPerPixel);
        const std::size_t imageBytes =
            static_cast<std::size_t>(bytesPerRow) *
            static_cast<std::size_t>(height);
        std::vector<std::uint8_t> bytes(imageBytes);
        @try {
            MTLRegion srcRegion = MTLRegionMake2D(0, 0, width, height);
            [sidecar getBytes:bytes.data()
                  bytesPerRow:bytesPerRow
                   fromRegion:srcRegion
                  mipmapLevel:0];
            MTLRegion dstRegion = MTLRegionMake3D(
                0, 0, static_cast<NSUInteger>(ib.layer3DSidecarLayer),
                width, height, 1);
            [srcTex replaceRegion:dstRegion
                       mipmapLevel:mip
                         withBytes:bytes.data()
                       bytesPerRow:bytesPerRow];
            ib.layer3DSidecarDirty = false;
        } @catch (NSException*) {
        }
    }

    void* resolveImage3DLayerSidecarTexture(ImageBinding& ib,
                                            GLTextureObject* texObj,
                                            GLenum shaderTarget) {
        if (texObj == nullptr ||
            texObj->metalTexture == nullptr ||
            texObj->target != GL_TEXTURE_3D ||
            ib.layered != GL_FALSE ||
            (shaderTarget != GL_TEXTURE_2D &&
             shaderTarget != GL_TEXTURE_RECTANGLE)) {
            return nullptr;
        }
        id<MTLTexture> srcTex = (__bridge id<MTLTexture>)texObj->metalTexture;
        if (srcTex == nil ||
            srcTex.textureType != MTLTextureType3D ||
            ib.level < 0 ||
            static_cast<NSUInteger>(ib.level) >= srcTex.mipmapLevelCount) {
            return nullptr;
        }
        const NSUInteger mip = static_cast<NSUInteger>(ib.level);
        const NSUInteger width = std::max<NSUInteger>(srcTex.width >> mip, 1);
        const NSUInteger height = std::max<NSUInteger>(srcTex.height >> mip, 1);
        const NSUInteger depth = std::max<NSUInteger>(srcTex.depth >> mip, 1);
        if (ib.layer < 0 || static_cast<NSUInteger>(ib.layer) >= depth) {
            return nullptr;
        }
        const MTLPixelFormat imagePixelFormat = metalRenderbufferFormat(ib.format);
        if (imagePixelFormat == MTLPixelFormatInvalid ||
            imagePixelFormat != srcTex.pixelFormat) {
            return nullptr;
        }

        const bool cacheHit =
            ib.layer3DSidecarTexture != nullptr &&
            ib.layer3DSidecarSourceTexture == ib.texture &&
            ib.layer3DSidecarLevel == ib.level &&
            ib.layer3DSidecarLayer == ib.layer &&
            ib.layer3DSidecarFormat == ib.format;
        if (!cacheHit) {
            flushImageBinding3DLayerSidecar(ib);
            if (ib.layer3DSidecarTexture != nullptr) {
                releaseRetainedMetalObject(ib.layer3DSidecarTexture);
            }
            ib.layer3DSidecarTexture = nullptr;
            ib.layer3DSidecarSourceTexture = 0;
            ib.layer3DSidecarLevel = -1;
            ib.layer3DSidecarLayer = 0;
            ib.layer3DSidecarFormat = 0;
            ib.layer3DSidecarDirty = false;

            MTLTextureDescriptor* desc =
                [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:imagePixelFormat
                                                                    width:width
                                                                   height:height
                                                                mipmapped:NO];
            desc.usage = MTLTextureUsageShaderRead | MTLTextureUsageShaderWrite;
            desc.storageMode = MTLStorageModeShared;
            id<MTLTexture> sidecar = [device newTextureWithDescriptor:desc];
            if (sidecar == nil) {
                return nullptr;
            }

            const auto fmtInfo = nativeFormatInfo(imagePixelFormat);
            if (fmtInfo.bytesPerPixel <= 0) {
                [sidecar release];
                return nullptr;
            }
            const NSUInteger bytesPerRow =
                width * static_cast<NSUInteger>(fmtInfo.bytesPerPixel);
            const std::size_t imageBytes =
                static_cast<std::size_t>(bytesPerRow) *
                static_cast<std::size_t>(height);
            std::vector<std::uint8_t> bytes(imageBytes);
            @try {
                MTLRegion srcRegion = MTLRegionMake3D(
                    0, 0, static_cast<NSUInteger>(ib.layer), width, height, 1);
                [srcTex getBytes:bytes.data()
                      bytesPerRow:bytesPerRow
                    bytesPerImage:bytesPerRow * height
                       fromRegion:srcRegion
                      mipmapLevel:mip
                            slice:0];
                MTLRegion dstRegion = MTLRegionMake2D(0, 0, width, height);
                [sidecar replaceRegion:dstRegion
                            mipmapLevel:0
                              withBytes:bytes.data()
                            bytesPerRow:bytesPerRow];
            } @catch (NSException*) {
                [sidecar release];
                return nullptr;
            }

            ib.layer3DSidecarTexture = transferRetainedMetalObject(sidecar);
            ib.layer3DSidecarSourceTexture = ib.texture;
            ib.layer3DSidecarLevel = ib.level;
            ib.layer3DSidecarLayer = ib.layer;
            ib.layer3DSidecarFormat = ib.format;
        }

        if (ib.access != GL_READ_ONLY) {
            ib.layer3DSidecarDirty = true;
        }
        return ib.layer3DSidecarTexture;
    }

    void flushImageBinding3DLayerSidecars() {
        for (auto& ib : imageBindings) {
            flushImageBinding3DLayerSidecar(ib);
        }
    }

    // CKPT119 wrapper: type-aware adapter for resolveImageMetalTextureImpl
    // that takes ImageBinding directly. Defined after ImageBinding so
    // the type is in scope.
    void* resolveImageMetalTexture(ImageBinding& ib,
                                   GLTextureObject* texObj,
                                   GLenum shaderTarget) {
        if (texObj != nullptr && texObj->viewSourceTexture == 0) {
            (void)restoreR5PrimaryTextureIfNeeded(*texObj, ib.texture);
        }
        if (void* sidecar =
                resolveImage3DLayerSidecarTexture(ib, texObj, shaderTarget)) {
            return sidecar;
        }
        return resolveImageMetalTextureImpl(texObj, ib.texture, ib.level,
                                            ib.format,
                                            ib.layered, ib.layer,
                                            shaderTarget,
                                            ib.metalLevelView,
                                            ib.cachedViewTexture,
                                            ib.cachedViewLevel,
                                            ib.cachedViewFormat,
                                            ib.cachedViewLayered,
                                            ib.cachedViewLayer,
                                            ib.cachedViewTarget);
    }

    static NSUInteger imageAtomicSliceCount(id<MTLTexture> tex) {
        if (tex == nil) return 1;
        switch (tex.textureType) {
            case MTLTextureType1DArray:
            case MTLTextureType2DArray:
            case MTLTextureType2DMultisampleArray:
                return std::max<NSUInteger>(tex.arrayLength, 1);
            case MTLTextureTypeCube:
                return 6;
            case MTLTextureTypeCubeArray:
                return 6 * std::max<NSUInteger>(tex.arrayLength, 1);
            default:
                return 1;
        }
    }

    static std::size_t imageAtomicSidecarByteSize(id<MTLTexture> tex) {
        if (tex == nil || tex.width == 0) return 0;
        const NSUInteger width = std::max<NSUInteger>(tex.width, 1);
        const NSUInteger height = std::max<NSUInteger>(tex.height, 1);
        const NSUInteger depth = tex.textureType == MTLTextureType3D
            ? std::max<NSUInteger>(tex.depth, 1)
            : imageAtomicSliceCount(tex);
        return static_cast<std::size_t>(width * height * depth * 4u);
    }

    void* ensureTextureImageAtomicBuffer(GLTextureObject& texObj) {
        if (device == nil || texObj.metalTexture == nullptr) return nullptr;
        id<MTLTexture> tex = (__bridge id<MTLTexture>)texObj.metalTexture;
        const std::size_t requiredBytes = imageAtomicSidecarByteSize(tex);
        if (requiredBytes == 0) return nullptr;
        if (texObj.imageAtomicBuffer != nullptr &&
            texObj.imageAtomicBufferSize >= requiredBytes) {
            return texObj.imageAtomicBuffer;
        }
        releaseRetainedMetalObject(texObj.imageAtomicBuffer);
        texObj.imageAtomicBuffer = nullptr;
        texObj.imageAtomicBufferSize = 0;
        texObj.imageAtomicBufferDirtyToTexture = false;

        id<MTLBuffer> buffer =
            [device newBufferWithLength:requiredBytes
                                options:MTLResourceStorageModeShared];
        if (buffer == nil) return nullptr;
        std::memset([buffer contents], 0, requiredBytes);

        @try {
            if (tex.storageMode != MTLStorageModePrivate && tex.width > 0) {
                const NSUInteger width = std::max<NSUInteger>(tex.width, 1);
                const NSUInteger height = std::max<NSUInteger>(tex.height, 1);
                const NSUInteger rowBytes = width * 4u;
                const NSUInteger imageBytes = rowBytes * height;
                std::uint8_t* dst = static_cast<std::uint8_t*>([buffer contents]);
                if (tex.textureType == MTLTextureType3D) {
                    MTLRegion region = MTLRegionMake3D(
                        0, 0, 0, width, height, std::max<NSUInteger>(tex.depth, 1));
                    [tex getBytes:dst
                       bytesPerRow:rowBytes
                     bytesPerImage:imageBytes
                        fromRegion:region
                       mipmapLevel:0
                             slice:0];
                } else {
                    const NSUInteger slices = imageAtomicSliceCount(tex);
                    MTLRegion region = MTLRegionMake2D(0, 0, width, height);
                    for (NSUInteger slice = 0; slice < slices; ++slice) {
                        [tex getBytes:dst + slice * imageBytes
                           bytesPerRow:rowBytes
                         bytesPerImage:imageBytes
                            fromRegion:region
                           mipmapLevel:0
                                 slice:slice];
                    }
                }
            }
        } @catch (NSException*) {
            std::memset([buffer contents], 0, requiredBytes);
        }

        texObj.imageAtomicBuffer = transferRetainedMetalObject(buffer);
        texObj.imageAtomicBufferSize = requiredBytes;
        return texObj.imageAtomicBuffer;
    }

    void flushTextureImageAtomicSidecars() {
        if (objects == nullptr) return;
        objects->textures().forEach([&](GLuint, GLTextureObject& texObj) {
            if (!texObj.imageAtomicBufferDirtyToTexture ||
                texObj.imageAtomicBuffer == nullptr ||
                texObj.metalTexture == nullptr ||
                texObj.target == GL_TEXTURE_BUFFER) {
                return;
            }
            id<MTLBuffer> buffer = (__bridge id<MTLBuffer>)texObj.imageAtomicBuffer;
            id<MTLTexture> tex = (__bridge id<MTLTexture>)texObj.metalTexture;
            if (buffer == nil || tex == nil || [buffer contents] == nullptr) return;
            const std::size_t requiredBytes = imageAtomicSidecarByteSize(tex);
            if (requiredBytes == 0 || buffer.length < requiredBytes) return;

            const NSUInteger width = std::max<NSUInteger>(tex.width, 1);
            const NSUInteger height = std::max<NSUInteger>(tex.height, 1);
            const NSUInteger rowBytes = width * 4u;
            const NSUInteger imageBytes = rowBytes * height;
            const std::uint8_t* src =
                static_cast<const std::uint8_t*>([buffer contents]);
            @try {
                if (tex.textureType == MTLTextureType3D) {
                    MTLRegion region = MTLRegionMake3D(
                        0, 0, 0, width, height, std::max<NSUInteger>(tex.depth, 1));
                    [tex replaceRegion:region
                            mipmapLevel:0
                                  slice:0
                              withBytes:src
                            bytesPerRow:rowBytes
                          bytesPerImage:imageBytes];
                } else {
                    const NSUInteger slices = imageAtomicSliceCount(tex);
                    MTLRegion region = MTLRegionMake2D(0, 0, width, height);
                    for (NSUInteger slice = 0; slice < slices; ++slice) {
                        [tex replaceRegion:region
                                mipmapLevel:0
                                      slice:slice
                                  withBytes:src + slice * imageBytes
                                bytesPerRow:rowBytes
                              bytesPerImage:imageBytes];
                    }
                }
                texObj.imageAtomicBufferDirtyToTexture = false;
            } @catch (NSException*) {
            }
        });
    }

    void* resolveSparseSidecarImageMetalTexture(
        ImageBinding& ib,
        GLTextureObject* texObj,
        const extensions::sparse_texture::SparseStorageImageSidecarInfo& sidecarInfo)
    {
        if (sidecarInfo.metalTexture == nullptr) {
            return nullptr;
        }
        if (ib.sparseCachedViewBase != nullptr &&
            ib.sparseCachedViewBase != sidecarInfo.metalTexture) {
            if (ib.sparseSidecarLevelView != nullptr) {
                releaseRetainedMetalObject(ib.sparseSidecarLevelView);
            }
            ib.sparseSidecarLevelView = nullptr;
            ib.sparseCachedViewTexture = 0;
            ib.sparseCachedViewLevel = -1;
            ib.sparseCachedViewFormat = 0;
            ib.sparseCachedViewBase = nullptr;
        }
        void* result = resolveImageMetalTextureImpl(
            texObj, ib.texture, ib.level, ib.format,
            ib.layered, ib.layer, sidecarInfo.target,
            ib.sparseSidecarLevelView,
            ib.sparseCachedViewTexture,
            ib.sparseCachedViewLevel,
            ib.sparseCachedViewFormat,
            ib.sparseCachedViewLayered,
            ib.sparseCachedViewLayer,
            ib.sparseCachedViewTarget,
            sidecarInfo.metalTexture);
        if (ib.sparseSidecarLevelView != nullptr) {
            ib.sparseCachedViewBase = sidecarInfo.metalTexture;
        }
        return result;
    }

    bool imageBindingLevelAvailable(const ImageBinding& ib,
                                    const GLTextureObject* texObj) const {
        if (texObj == nullptr || texObj->metalTexture == nullptr ||
            ib.texture == 0 || ib.level < 0) {
            return false;
        }
        if (texObj->target == GL_TEXTURE_BUFFER) {
            return ib.level == 0;
        }
        const auto levelIt = texObj->levels.find(ib.level);
        if (levelIt == texObj->levels.end() || !levelIt->second.defined) {
            if (!texObj->desc.immutable) {
                return false;
            }
            const GLsizei declaredLevels = std::max<GLsizei>(texObj->desc.levels, 1);
            if (ib.level >= declaredLevels) {
                return false;
            }
        }
        id<MTLTexture> baseTex = (__bridge id<MTLTexture>)texObj->metalTexture;
        return baseTex != nil &&
               static_cast<NSUInteger>(ib.level) < baseTex.mipmapLevelCount;
    }
    static constexpr std::size_t kMaxImageUnits = 16;
    std::array<ImageBinding, kMaxImageUnits> imageBindings{};

    GLContext* owner = nullptr;
    std::string vendorString = "AppGL";
    std::string rendererString = "AppGL on Metal";
    // Declarative GL version strings. glGetString(GL_VERSION) returns the
    // claimed version (a compile-time constant — see
    // CoverageStore::claimedVersion) rather than the coverage-derived
    // highest-fully-implemented version, so a cold-boot context with no
    // smoke tests run still advertises the full AppGL surface as "4.6 AppGL
    // core" rather than the "4.6 AppGL bootstrap" fallback the walker used
    // to return. Engines such as Recoil parse "M.m" via sscanf and fall
    // back to a GL3 codepath if they see a 3.x string, so both the version
    // string and the shading-language-version string must reflect what the
    // translator is actually capable of accepting.
    std::string versionString = "4.6 AppGL core";
    std::string shadingLanguageVersion = "4.60";
};

GLContext::GLContext(void* layer)
    : impl_(std::make_unique<Impl>(this, layer, 1280, 720, false)) {
    Runtime::shared().registerContext(this);
    ExtensionContext extensionContext(*this);
    extensions::ExtensionRegistry::initializeAll(extensionContext);
}

GLContext::GLContext(GLsizei offscreenWidth, GLsizei offscreenHeight)
    : impl_(std::make_unique<Impl>(this, nullptr, offscreenWidth, offscreenHeight, true)) {
    Runtime::shared().registerContext(this);
    ExtensionContext extensionContext(*this);
    extensions::ExtensionRegistry::initializeAll(extensionContext);
}

GLContext::~GLContext() {
    Runtime::shared().unregisterContext(this);
    impl_.reset();
    ExtensionContext extensionContext(*this);
    extensions::fp64::destroyContextBindingState(extensionContext);
    extensions::fragment_shading_rate::destroyContext(extensionContext);
    extensions::sparse_texture::destroyContext(extensionContext);
}

