        return false;
    }
    UniformSlotRef ref = resolveUniformSlot(object, location);
    if (ref.slot == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    GLProgramUniformValue* value = ref.slot;
    const std::size_t components = uniformTypeComponentCount(ref.type ? ref.type : value->type);
    const std::size_t offset = static_cast<std::size_t>(ref.elementIndex) * components;
    if (!value->doubles.empty()) {
        const std::size_t avail = value->doubles.size() > offset
            ? std::min(components, value->doubles.size() - offset) : 0;
        for (std::size_t i = 0; i < avail; ++i) {
            params[i] = roundFp64UniformToGLuint(value->doubles[offset + i]);
        }
    } else if (!value->uints.empty()) {
        const std::size_t avail = value->uints.size() > offset
            ? std::min(components, value->uints.size() - offset) : 0;
        if (avail > 0) {
            std::memcpy(params, value->uints.data() + offset, avail * sizeof(GLuint));
        }
    } else if (!value->ints.empty()) {
        const std::size_t avail = value->ints.size() > offset
            ? std::min(components, value->ints.size() - offset) : 0;
        for (std::size_t i = 0; i < avail; ++i) {
            params[i] = static_cast<GLuint>(value->ints[offset + i]);
        }
    } else if (!value->floats.empty()) {
        const std::size_t avail = value->floats.size() > offset
            ? std::min(components, value->floats.size() - offset) : 0;
        for (std::size_t i = 0; i < avail; ++i) {
            params[i] = static_cast<GLuint>(value->floats[offset + i]);
        }
    }
    return true;
}

// GL 4.6 §7.6.1 — Sampler / image uniform validation shared by the
// in-context (glUniform*) and DSA (glProgramUniform*) paths.
// Returns `true` iff validation failed (caller should bail after
// pushError). `element` + `vectorSize` + first int slot of `values`
// are checked against the uniform's declared `utype`.
static bool sampleOrImageUniformValidationFailed(
    GLContext* ctx, GLenum utype, GLContext::UniformElementType element,
    GLint vectorSize, const void* values, bool rejectImageUnitUpdate)
{
    auto isSamplerOrImage = [](GLenum t) {
        switch (t) {
            case GL_SAMPLER_1D: case GL_SAMPLER_2D: case GL_SAMPLER_3D:
            case GL_SAMPLER_CUBE: case GL_SAMPLER_1D_ARRAY:
            case GL_SAMPLER_2D_ARRAY: case GL_SAMPLER_1D_SHADOW:
            case GL_SAMPLER_2D_SHADOW: case GL_SAMPLER_1D_ARRAY_SHADOW:
            case GL_SAMPLER_2D_ARRAY_SHADOW: case GL_SAMPLER_CUBE_SHADOW:
            case GL_SAMPLER_2D_RECT: case GL_SAMPLER_2D_RECT_SHADOW:
            case GL_SAMPLER_BUFFER: case GL_SAMPLER_2D_MULTISAMPLE:
            case GL_SAMPLER_2D_MULTISAMPLE_ARRAY:
            case GL_SAMPLER_CUBE_MAP_ARRAY:
            case GL_SAMPLER_CUBE_MAP_ARRAY_SHADOW:
            case GL_INT_SAMPLER_1D: case GL_INT_SAMPLER_2D:
            case GL_INT_SAMPLER_3D: case GL_INT_SAMPLER_CUBE:
            case GL_INT_SAMPLER_1D_ARRAY: case GL_INT_SAMPLER_2D_ARRAY:
            case GL_INT_SAMPLER_2D_RECT: case GL_INT_SAMPLER_BUFFER:
            case GL_INT_SAMPLER_2D_MULTISAMPLE:
            case GL_INT_SAMPLER_2D_MULTISAMPLE_ARRAY:
            case GL_INT_SAMPLER_CUBE_MAP_ARRAY:
            case GL_UNSIGNED_INT_SAMPLER_1D:
            case GL_UNSIGNED_INT_SAMPLER_2D:
            case GL_UNSIGNED_INT_SAMPLER_3D:
            case GL_UNSIGNED_INT_SAMPLER_CUBE:
            case GL_UNSIGNED_INT_SAMPLER_1D_ARRAY:
            case GL_UNSIGNED_INT_SAMPLER_2D_ARRAY:
            case GL_UNSIGNED_INT_SAMPLER_2D_RECT:
            case GL_UNSIGNED_INT_SAMPLER_BUFFER:
            case GL_UNSIGNED_INT_SAMPLER_2D_MULTISAMPLE:
            case GL_UNSIGNED_INT_SAMPLER_2D_MULTISAMPLE_ARRAY:
            case GL_UNSIGNED_INT_SAMPLER_CUBE_MAP_ARRAY:
            case GL_IMAGE_1D: case GL_IMAGE_2D: case GL_IMAGE_3D:
            case GL_IMAGE_2D_RECT: case GL_IMAGE_CUBE:
            case GL_IMAGE_BUFFER: case GL_IMAGE_1D_ARRAY:
            case GL_IMAGE_2D_ARRAY: case GL_IMAGE_CUBE_MAP_ARRAY:
            case GL_IMAGE_2D_MULTISAMPLE:
            case GL_IMAGE_2D_MULTISAMPLE_ARRAY:
            case GL_INT_IMAGE_1D: case GL_INT_IMAGE_2D:
            case GL_INT_IMAGE_3D: case GL_INT_IMAGE_2D_RECT:
            case GL_INT_IMAGE_CUBE: case GL_INT_IMAGE_BUFFER:
            case GL_INT_IMAGE_1D_ARRAY: case GL_INT_IMAGE_2D_ARRAY:
            case GL_INT_IMAGE_CUBE_MAP_ARRAY:
            case GL_INT_IMAGE_2D_MULTISAMPLE:
            case GL_INT_IMAGE_2D_MULTISAMPLE_ARRAY:
            case GL_UNSIGNED_INT_IMAGE_1D:
            case GL_UNSIGNED_INT_IMAGE_2D:
            case GL_UNSIGNED_INT_IMAGE_3D:
            case GL_UNSIGNED_INT_IMAGE_2D_RECT:
            case GL_UNSIGNED_INT_IMAGE_CUBE:
            case GL_UNSIGNED_INT_IMAGE_BUFFER:
            case GL_UNSIGNED_INT_IMAGE_1D_ARRAY:
            case GL_UNSIGNED_INT_IMAGE_2D_ARRAY:
            case GL_UNSIGNED_INT_IMAGE_CUBE_MAP_ARRAY:
            case GL_UNSIGNED_INT_IMAGE_2D_MULTISAMPLE:
            case GL_UNSIGNED_INT_IMAGE_2D_MULTISAMPLE_ARRAY:
                return true;
            default:
                return false;
        }
    };
    if (!isSamplerOrImage(utype)) return false;
    auto isImageType = [](GLenum t) {
        switch (t) {
            case GL_IMAGE_1D: case GL_IMAGE_2D: case GL_IMAGE_3D:
            case GL_IMAGE_2D_RECT: case GL_IMAGE_CUBE:
            case GL_IMAGE_BUFFER: case GL_IMAGE_1D_ARRAY:
            case GL_IMAGE_2D_ARRAY: case GL_IMAGE_CUBE_MAP_ARRAY:
            case GL_IMAGE_2D_MULTISAMPLE:
            case GL_IMAGE_2D_MULTISAMPLE_ARRAY:
            case GL_INT_IMAGE_1D: case GL_INT_IMAGE_2D:
            case GL_INT_IMAGE_3D: case GL_INT_IMAGE_2D_RECT:
            case GL_INT_IMAGE_CUBE: case GL_INT_IMAGE_BUFFER:
            case GL_INT_IMAGE_1D_ARRAY: case GL_INT_IMAGE_2D_ARRAY:
            case GL_INT_IMAGE_CUBE_MAP_ARRAY:
            case GL_INT_IMAGE_2D_MULTISAMPLE:
            case GL_INT_IMAGE_2D_MULTISAMPLE_ARRAY:
            case GL_UNSIGNED_INT_IMAGE_1D:
            case GL_UNSIGNED_INT_IMAGE_2D:
            case GL_UNSIGNED_INT_IMAGE_3D:
            case GL_UNSIGNED_INT_IMAGE_2D_RECT:
            case GL_UNSIGNED_INT_IMAGE_CUBE:
            case GL_UNSIGNED_INT_IMAGE_BUFFER:
            case GL_UNSIGNED_INT_IMAGE_1D_ARRAY:
            case GL_UNSIGNED_INT_IMAGE_2D_ARRAY:
            case GL_UNSIGNED_INT_IMAGE_CUBE_MAP_ARRAY:
            case GL_UNSIGNED_INT_IMAGE_2D_MULTISAMPLE:
            case GL_UNSIGNED_INT_IMAGE_2D_MULTISAMPLE_ARRAY:
                return true;
            default:
                return false;
        }
    };
    const bool isImage = isImageType(utype);
    if (isImage && rejectImageUnitUpdate) {
        ctx->pushError(GL_INVALID_OPERATION);
        return true;
    }
    if (element != GLContext::UniformElementType::Int || vectorSize != 1) {
        ctx->pushError(GL_INVALID_OPERATION);
        return true;
    }
    const GLint v = *static_cast<const GLint*>(values);
    if (v < 0) {
        ctx->pushError(GL_INVALID_VALUE);
        return true;
    }
    GLint maxUnit = 0;
    if (isImage) {
        ctx->capabilities().queryInteger(GL_MAX_IMAGE_UNITS, &maxUnit);
    } else {
        ctx->capabilities().queryInteger(
            GL_MAX_COMBINED_TEXTURE_IMAGE_UNITS, &maxUnit);
    }
    if (maxUnit > 0 && v >= maxUnit) {
        ctx->pushError(GL_INVALID_VALUE);
        return true;
    }
    return false;
}

bool GLContext::setUniformScalarVector(GLint location, UniformElementType element, GLint vectorSize, GLsizei count, const void* values) {
    if (location < 0) {
        return true;  // -1 silently no-ops per spec.
    }
    if (count < 0 || vectorSize < 1 || vectorSize > 4) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // GL 4.6 §7.3: glUniform* targets the current program; if no
    // current program but a pipeline is bound, target the pipeline's
    // active-shader-program (set by glActiveShaderProgram). CTS
    // `sepshaderobjs.ProgUniformAPI` exercises this fallback.
    GLuint targetProgram = impl_->state->currentProgram();
    if (targetProgram == 0) {
        const GLuint pipelineName = impl_->state->currentProgramPipeline();
        if (pipelineName != 0) {
            GLProgramPipelineObject* ppo = impl_->objects->programPipelines().get(pipelineName);
            if (ppo != nullptr) {
                targetProgram = ppo->activeShaderProgram;
            }
        }
    }
    GLProgramObject* object = impl_->objects->programs().get(targetProgram);
    if (object == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    UniformSlotRef ref = resolveUniformSlot(object, location);
    if (ref.slot == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    GLProgramUniformValue* slot = ref.slot;

    if (sampleOrImageUniformValidationFailed(this, ref.type,
            element, vectorSize, values, ref.rejectEsImageUnitUpdate)) {
        return false;
    }

    // Clamp count so writes don't overflow the declared array. GL spec: the
    // effective update is min(count, arraySize - elementIndex).
    const GLint remaining = std::max<GLint>(ref.arraySize - ref.elementIndex, 1);
    const GLsizei effCount = std::min<GLsizei>(std::max<GLsizei>(count, 1), remaining);
    const std::size_t components = static_cast<std::size_t>(vectorSize);
    const std::size_t writeCount = components * static_cast<std::size_t>(effCount);
    const std::size_t fullCount  = components * static_cast<std::size_t>(std::max<GLint>(ref.arraySize, 1));
    const std::size_t writeOffset = components * static_cast<std::size_t>(ref.elementIndex);

    auto writeInto = [&](auto& dstVec, auto& otherA, auto& otherB, const auto* src) {
        using T = typename std::remove_reference<decltype(dstVec)>::type::value_type;
        // Size the destination to hold the full array; preserve existing
        // values where possible so per-element writes don't wipe siblings.
        if (dstVec.size() < fullCount) {
            dstVec.resize(fullCount, T{});
        }
        std::memcpy(dstVec.data() + writeOffset, src, writeCount * sizeof(T));
        otherA.clear();
        otherB.clear();
    };

    switch (element) {
        case UniformElementType::Float:
            writeInto(slot->floats, slot->ints, slot->uints, static_cast<const GLfloat*>(values));
            break;
        case UniformElementType::Int:
            writeInto(slot->ints, slot->floats, slot->uints, static_cast<const GLint*>(values));
            break;
        case UniformElementType::UnsignedInt:
            writeInto(slot->uints, slot->floats, slot->ints, static_cast<const GLuint*>(values));
            break;
    }
    slot->doubles.clear();
    slot->df64TransportWords.clear();
    object->markUniformsDirty();
    return true;
}

bool GLContext::setUniformMatrix(GLint location, GLint rows, GLint cols, GLsizei count, GLboolean transpose, const GLfloat* values) {
    if (location < 0) {
        return true;
    }
    if (count < 0 || rows < 2 || rows > 4 || cols < 2 || cols > 4 || values == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // §7.3 active-shader-program fallback — same as setUniformScalarVector.
    GLuint currentProgram = impl_->state->currentProgram();
    if (currentProgram == 0) {
        const GLuint pipelineName = impl_->state->currentProgramPipeline();
        if (pipelineName != 0) {
            GLProgramPipelineObject* ppo = impl_->objects->programPipelines().get(pipelineName);
            if (ppo != nullptr) currentProgram = ppo->activeShaderProgram;
        }
    }
    GLProgramObject* object = impl_->objects->programs().get(currentProgram);
    if (object == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    GLProgramUniformValue* slot = lookupUniformValue(object, location);
    if (slot == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    const std::size_t elements = static_cast<std::size_t>(rows) * static_cast<std::size_t>(cols) *
                                 static_cast<std::size_t>(std::max<GLsizei>(count, 1));
    slot->floats.assign(elements, 0.0f);
    if (transpose == GL_FALSE) {
        std::memcpy(slot->floats.data(), values, elements * sizeof(GLfloat));
    } else {
        const std::size_t matrixElements = static_cast<std::size_t>(rows) * static_cast<std::size_t>(cols);
        for (GLsizei m = 0; m < std::max<GLsizei>(count, 1); ++m) {
            for (GLint r = 0; r < rows; ++r) {
                for (GLint c = 0; c < cols; ++c) {
                    const std::size_t srcIndex = static_cast<std::size_t>(m) * matrixElements +
                                                 static_cast<std::size_t>(r) * static_cast<std::size_t>(cols) +
                                                 static_cast<std::size_t>(c);
                    const std::size_t dstIndex = static_cast<std::size_t>(m) * matrixElements +
                                                 static_cast<std::size_t>(c) * static_cast<std::size_t>(rows) +
                                                 static_cast<std::size_t>(r);
                    slot->floats[dstIndex] = values[srcIndex];
                }
            }
        }
    }
    slot->ints.clear();
    slot->uints.clear();
    slot->doubles.clear();
    slot->df64TransportWords.clear();
    object->markUniformsDirty();
    return true;
}

static void assignDf64TransportWords(GLProgramUniformValue& slot,
                                     const GLdouble* values,
                                     std::size_t count) {
    slot.df64TransportWords.resize(count * 2u);
    for (std::size_t i = 0; i < count; ++i) {
        const auto words =
            extensions::fp64::encodeDoubleToDf64Transport(values[i]);
        slot.df64TransportWords[i * 2u] = words.hi;
        slot.df64TransportWords[i * 2u + 1u] = words.lo;
    }
}

static GLint doubleUniformVectorWidth(GLenum type) {
    switch (type) {
        case GL_DOUBLE:      return 1;
        case GL_DOUBLE_VEC2: return 2;
        case GL_DOUBLE_VEC3: return 3;
        case GL_DOUBLE_VEC4: return 4;
        default:             return 0;
    }
}

static bool doubleUniformMatrixShape(GLenum type, GLint& cols, GLint& rows) {
    switch (type) {
        case GL_DOUBLE_MAT2:   cols = 2; rows = 2; return true;
        case GL_DOUBLE_MAT3:   cols = 3; rows = 3; return true;
        case GL_DOUBLE_MAT4:   cols = 4; rows = 4; return true;
        case GL_DOUBLE_MAT2x3: cols = 2; rows = 3; return true;
        case GL_DOUBLE_MAT3x2: cols = 3; rows = 2; return true;
        case GL_DOUBLE_MAT2x4: cols = 2; rows = 4; return true;
        case GL_DOUBLE_MAT4x2: cols = 4; rows = 2; return true;
        case GL_DOUBLE_MAT3x4: cols = 3; rows = 4; return true;
        case GL_DOUBLE_MAT4x3: cols = 4; rows = 3; return true;
        default: return false;
    }
}

static bool uniformWriteCountFits(const UniformSlotRef& ref, GLsizei count) {
    const GLint remaining = std::max<GLint>(ref.arraySize - ref.elementIndex, 1);
    return count <= remaining;
}

static void writeDoubleUniformSlot(GLProgramUniformValue& slot,
                                   GLint arraySize,
                                   GLint elementIndex,
                                   GLint vectorSize,
                                   GLsizei count,
                                   const GLdouble* values) {
    const GLint remaining = std::max<GLint>(arraySize - elementIndex, 1);
    const GLsizei effCount = std::min<GLsizei>(std::max<GLsizei>(count, 1), remaining);
    const std::size_t components = static_cast<std::size_t>(vectorSize);
    const std::size_t writeCount = components * static_cast<std::size_t>(effCount);
    const std::size_t fullCount = components * static_cast<std::size_t>(std::max<GLint>(arraySize, 1));
    const std::size_t writeOffset = components * static_cast<std::size_t>(elementIndex);

    if (slot.doubles.size() < fullCount) {
        slot.doubles.resize(fullCount, 0.0);
    }
    std::memcpy(slot.doubles.data() + writeOffset, values, writeCount * sizeof(GLdouble));

    slot.floats.resize(fullCount);
    for (std::size_t i = 0; i < fullCount; ++i) {
        slot.floats[i] = static_cast<GLfloat>(slot.doubles[i]);
    }

    assignDf64TransportWords(slot, slot.doubles.data(), slot.doubles.size());
    slot.ints.clear();
    slot.uints.clear();
}

bool GLContext::setUniformDouble(GLint location, GLint vectorSize, GLsizei count, const GLdouble* values) {
    if (location < 0) {
        return true;
    }
    if (count < 0 || vectorSize < 1 || vectorSize > 4 || values == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // §7.3 active-shader-program fallback.
    GLuint currentProgram = impl_->state->currentProgram();
    if (currentProgram == 0) {
        const GLuint pipelineName = impl_->state->currentProgramPipeline();
        if (pipelineName != 0) {
            GLProgramPipelineObject* ppo = impl_->objects->programPipelines().get(pipelineName);
            if (ppo != nullptr) currentProgram = ppo->activeShaderProgram;
        }
    }
    GLProgramObject* object = impl_->objects->programs().get(currentProgram);
    if (object == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    UniformSlotRef ref = resolveUniformSlot(object, location);
    if (ref.slot == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (doubleUniformVectorWidth(ref.type) != vectorSize ||
        !uniformWriteCountFits(ref, count)) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    writeDoubleUniformSlot(*ref.slot,
                           ref.arraySize,
                           ref.elementIndex,
                           vectorSize,
                           count,
                           values);
    object->markUniformsDirty();
    return true;
}

bool GLContext::setUniformDoubleMatrix(GLint location, GLint rows, GLint cols, GLsizei count, GLboolean transpose, const GLdouble* values) {
    if (location < 0) {
        return true;
    }
    if (count < 0 || rows < 2 || rows > 4 || cols < 2 || cols > 4 || values == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // §7.3 active-shader-program fallback.
    GLuint currentProgram = impl_->state->currentProgram();
    if (currentProgram == 0) {
        const GLuint pipelineName = impl_->state->currentProgramPipeline();
        if (pipelineName != 0) {
            GLProgramPipelineObject* ppo = impl_->objects->programPipelines().get(pipelineName);
            if (ppo != nullptr) currentProgram = ppo->activeShaderProgram;
        }
    }
    GLProgramObject* object = impl_->objects->programs().get(currentProgram);
    if (object == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    UniformSlotRef ref = resolveUniformSlot(object, location);
    if (ref.slot == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    GLint expectedCols = 0;
    GLint expectedRows = 0;
    if (!doubleUniformMatrixShape(ref.type, expectedCols, expectedRows) ||
        rows != expectedCols || cols != expectedRows ||
        !uniformWriteCountFits(ref, count)) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    GLProgramUniformValue* slot = ref.slot;
    const GLint remaining = std::max<GLint>(ref.arraySize - ref.elementIndex, 1);
    const GLsizei effCount = std::min<GLsizei>(std::max<GLsizei>(count, 1), remaining);
    const std::size_t matrixElements = static_cast<std::size_t>(rows) * static_cast<std::size_t>(cols);
    const std::size_t elements = matrixElements * static_cast<std::size_t>(effCount);
    const std::size_t fullCount = matrixElements * static_cast<std::size_t>(std::max<GLint>(ref.arraySize, 1));
    const std::size_t writeOffset = matrixElements * static_cast<std::size_t>(ref.elementIndex);
    if (slot->doubles.size() < fullCount) {
        slot->doubles.resize(fullCount, 0.0);
    }
    if (transpose == GL_FALSE) {
        for (std::size_t i = 0; i < elements; ++i) {
            slot->doubles[writeOffset + i] = values[i];
        }
    } else {
        for (GLsizei m = 0; m < effCount; ++m) {
            for (GLint r = 0; r < rows; ++r) {
                for (GLint c = 0; c < cols; ++c) {
                    const std::size_t srcIndex = static_cast<std::size_t>(m) * matrixElements +
                                                 static_cast<std::size_t>(r) * static_cast<std::size_t>(cols) +
                                                 static_cast<std::size_t>(c);
                    const std::size_t dstIndex = writeOffset + static_cast<std::size_t>(m) * matrixElements +
                                                 static_cast<std::size_t>(c) * static_cast<std::size_t>(rows) +
                                                 static_cast<std::size_t>(r);
                    slot->doubles[dstIndex] = values[srcIndex];
                }
            }
        }
    }
    slot->floats.resize(fullCount);
    for (std::size_t i = 0; i < fullCount; ++i) {
        slot->floats[i] = static_cast<GLfloat>(slot->doubles[i]);
    }
    assignDf64TransportWords(*slot, slot->doubles.data(), slot->doubles.size());
    slot->ints.clear();
    slot->uints.clear();
    object->markUniformsDirty();
    return true;
}

// --- GL 4.1: glProgramUniform* family — explicit program handle variants ---

GLProgramObject* GLContext::validateProgramUniformTarget(GLuint program) {
    auto pushTargetError = [&](GLenum error) {
        if (std::find(impl_->errors.begin(), impl_->errors.end(), error) ==
            impl_->errors.end()) {
            pushError(error);
        }
    };
    GLProgramObject* object = impl_->objects->programs().get(program);
    if (object == nullptr || object->deleteRequested) {
        pushTargetError(GL_INVALID_VALUE);
        return nullptr;
    }
    if (!object->linked) {
        pushTargetError(GL_INVALID_OPERATION);
        return nullptr;
    }
    return object;
}

bool GLContext::setUniformScalarVectorForProgram(GLuint program, GLint location, UniformElementType element, GLint vectorSize, GLsizei count, const void* values) {
    // GL 4.6 §7.6.1 — error codes for glProgramUniform*. Validate the
    // PROGRAM argument BEFORE checking location, because "not a valid
    // program" and "not linked" fire regardless of location (including
    // location=-1 which would otherwise be a silent no-op).
    //   - program not a program name returned from glCreateProgram → INVALID_VALUE
    //   - program marked for deletion → INVALID_VALUE
    //   - program not linked → INVALID_OPERATION
    // CTS `sepshaderobjs.ProgUniformAPI` exercises both paths with a
    // cached location=-1 from an unlinked-program glGetUniformLocation.
    GLProgramObject* object = validateProgramUniformTarget(program);
    if (object == nullptr) return false;
    if (location < 0) return true;
    if (count < 0 || vectorSize < 1 || vectorSize > 4) { pushError(GL_INVALID_VALUE); return false; }
    UniformSlotRef ref = resolveUniformSlot(object, location);
    if (ref.slot == nullptr) { pushError(GL_INVALID_OPERATION); return false; }
    if (sampleOrImageUniformValidationFailed(this, ref.type,
            element, vectorSize, values, ref.rejectEsImageUnitUpdate)) {
        return false;
    }
    GLProgramUniformValue* slot = ref.slot;
    const GLint remaining = std::max<GLint>(ref.arraySize - ref.elementIndex, 1);
    const GLsizei effCount = std::min<GLsizei>(std::max<GLsizei>(count, 1), remaining);
    const std::size_t components = static_cast<std::size_t>(vectorSize);
    const std::size_t writeCount = components * static_cast<std::size_t>(effCount);
    const std::size_t fullCount  = components * static_cast<std::size_t>(std::max<GLint>(ref.arraySize, 1));
    const std::size_t writeOffset = components * static_cast<std::size_t>(ref.elementIndex);
    auto writeInto = [&](auto& dstVec, auto& otherA, auto& otherB, const auto* src) {
        using T = typename std::remove_reference<decltype(dstVec)>::type::value_type;
        if (dstVec.size() < fullCount) dstVec.resize(fullCount, T{});
        std::memcpy(dstVec.data() + writeOffset, src, writeCount * sizeof(T));
        otherA.clear(); otherB.clear();
    };
    switch (element) {
        case UniformElementType::Float:
            writeInto(slot->floats, slot->ints, slot->uints, static_cast<const GLfloat*>(values)); break;
        case UniformElementType::Int:
            writeInto(slot->ints, slot->floats, slot->uints, static_cast<const GLint*>(values)); break;
        case UniformElementType::UnsignedInt:
            writeInto(slot->uints, slot->floats, slot->ints, static_cast<const GLuint*>(values)); break;
    }
    slot->doubles.clear();
    slot->df64TransportWords.clear();
    object->markUniformsDirty();
    return true;
}

bool GLContext::setUniformMatrixForProgram(GLuint program, GLint location, GLint rows, GLint cols, GLsizei count, GLboolean transpose, const GLfloat* values) {
    GLProgramObject* object = validateProgramUniformTarget(program);
    if (object == nullptr) return false;
    if (location < 0) return true;
    if (count < 0 || rows < 2 || rows > 4 || cols < 2 || cols > 4 || values == nullptr) { pushError(GL_INVALID_VALUE); return false; }
    GLProgramUniformValue* slot = lookupUniformValue(object, location);
    if (slot == nullptr) { pushError(GL_INVALID_OPERATION); return false; }
    const std::size_t elements = static_cast<std::size_t>(rows) * static_cast<std::size_t>(cols) * static_cast<std::size_t>(std::max<GLsizei>(count, 1));
    slot->floats.assign(elements, 0.0f);
    if (transpose == GL_FALSE) {
        std::memcpy(slot->floats.data(), values, elements * sizeof(GLfloat));
    } else {
        const std::size_t matrixElements = static_cast<std::size_t>(rows) * static_cast<std::size_t>(cols);
        for (GLsizei m = 0; m < std::max<GLsizei>(count, 1); ++m) {
            for (GLint r = 0; r < rows; ++r) {
                for (GLint c = 0; c < cols; ++c) {
                    const std::size_t srcIndex = static_cast<std::size_t>(m) * matrixElements + static_cast<std::size_t>(r) * static_cast<std::size_t>(cols) + static_cast<std::size_t>(c);
                    const std::size_t dstIndex = static_cast<std::size_t>(m) * matrixElements + static_cast<std::size_t>(c) * static_cast<std::size_t>(rows) + static_cast<std::size_t>(r);
                    slot->floats[dstIndex] = values[srcIndex];
                }
            }
        }
    }
    slot->ints.clear(); slot->uints.clear();
    slot->doubles.clear(); slot->df64TransportWords.clear();
    object->markUniformsDirty();
    return true;
}

bool GLContext::setUniformDoubleForProgram(GLuint program, GLint location, GLint vectorSize, GLsizei count, const GLdouble* values) {
    GLProgramObject* object = validateProgramUniformTarget(program);
    if (object == nullptr) return false;
    if (location < 0) return true;
    if (count < 0 || vectorSize < 1 || vectorSize > 4 || values == nullptr) { pushError(GL_INVALID_VALUE); return false; }
    UniformSlotRef ref = resolveUniformSlot(object, location);
    if (ref.slot == nullptr) { pushError(GL_INVALID_OPERATION); return false; }
    if (doubleUniformVectorWidth(ref.type) != vectorSize ||
        !uniformWriteCountFits(ref, count)) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    writeDoubleUniformSlot(*ref.slot,
                           ref.arraySize,
                           ref.elementIndex,
                           vectorSize,
                           count,
                           values);
    object->markUniformsDirty();
    return true;
}

bool GLContext::setUniformDoubleMatrixForProgram(GLuint program, GLint location, GLint rows, GLint cols, GLsizei count, GLboolean transpose, const GLdouble* values) {
    GLProgramObject* object = validateProgramUniformTarget(program);
    if (object == nullptr) return false;
    if (location < 0) return true;
    if (count < 0 || rows < 2 || rows > 4 || cols < 2 || cols > 4 || values == nullptr) { pushError(GL_INVALID_VALUE); return false; }
    UniformSlotRef ref = resolveUniformSlot(object, location);
    if (ref.slot == nullptr) { pushError(GL_INVALID_OPERATION); return false; }
    GLint expectedCols = 0;
    GLint expectedRows = 0;
    if (!doubleUniformMatrixShape(ref.type, expectedCols, expectedRows) ||
        rows != expectedCols || cols != expectedRows ||
        !uniformWriteCountFits(ref, count)) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    GLProgramUniformValue* slot = ref.slot;
    const GLint remaining = std::max<GLint>(ref.arraySize - ref.elementIndex, 1);
    const GLsizei effCount = std::min<GLsizei>(std::max<GLsizei>(count, 1), remaining);
    const std::size_t matrixElements = static_cast<std::size_t>(rows) * static_cast<std::size_t>(cols);
    const std::size_t elements = matrixElements * static_cast<std::size_t>(effCount);
    const std::size_t fullCount = matrixElements * static_cast<std::size_t>(std::max<GLint>(ref.arraySize, 1));
    const std::size_t writeOffset = matrixElements * static_cast<std::size_t>(ref.elementIndex);
    if (slot->doubles.size() < fullCount) {
        slot->doubles.resize(fullCount, 0.0);
    }
    if (transpose == GL_FALSE) {
        for (std::size_t i = 0; i < elements; ++i) { slot->doubles[writeOffset + i] = values[i]; }
    } else {
        for (GLsizei m = 0; m < effCount; ++m) {
            for (GLint r = 0; r < rows; ++r) {
                for (GLint c = 0; c < cols; ++c) {
                    const std::size_t srcIndex = static_cast<std::size_t>(m) * matrixElements + static_cast<std::size_t>(r) * static_cast<std::size_t>(cols) + static_cast<std::size_t>(c);
                    const std::size_t dstIndex = writeOffset + static_cast<std::size_t>(m) * matrixElements + static_cast<std::size_t>(c) * static_cast<std::size_t>(rows) + static_cast<std::size_t>(r);
                    slot->doubles[dstIndex] = values[srcIndex];
                }
            }
        }
    }
    slot->floats.resize(fullCount);
    for (std::size_t i = 0; i < fullCount; ++i) { slot->floats[i] = static_cast<GLfloat>(slot->doubles[i]); }
    assignDf64TransportWords(*slot, slot->doubles.data(), slot->doubles.size());
    slot->ints.clear(); slot->uints.clear();
    object->markUniformsDirty();
    return true;
}

bool GLContext::getUniformdv(GLuint program, GLint location, GLdouble* params) {
    GLProgramObject* object = impl_->objects->programs().get(program);
    if (object == nullptr || params == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    UniformSlotRef ref = resolveUniformSlot(object, location);
    if (ref.slot == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    GLProgramUniformValue* value = ref.slot;
    const std::size_t components = uniformTypeComponentCount(ref.type ? ref.type : value->type);
    const std::size_t offset = static_cast<std::size_t>(ref.elementIndex) * components;
    // Prefer the lossless double shadow if available.
    if (!value->doubles.empty()) {
        const std::size_t avail = value->doubles.size() > offset
            ? std::min(components, value->doubles.size() - offset) : 0;
        if (avail > 0) {
            std::memcpy(params, value->doubles.data() + offset, avail * sizeof(GLdouble));
        }
    } else if (!value->floats.empty()) {
        const std::size_t avail = value->floats.size() > offset
            ? std::min(components, value->floats.size() - offset) : 0;
        for (std::size_t i = 0; i < avail; ++i) {
            params[i] = static_cast<GLdouble>(value->floats[offset + i]);
        }
    } else if (!value->ints.empty()) {
        const std::size_t avail = value->ints.size() > offset
            ? std::min(components, value->ints.size() - offset) : 0;
        for (std::size_t i = 0; i < avail; ++i) {
            params[i] = static_cast<GLdouble>(value->ints[offset + i]);
        }
    } else if (!value->uints.empty()) {
        const std::size_t avail = value->uints.size() > offset
            ? std::min(components, value->uints.size() - offset) : 0;
        for (std::size_t i = 0; i < avail; ++i) {
            params[i] = static_cast<GLdouble>(value->uints[offset + i]);
        }
    }
    return true;
}

namespace {

// Build a correctly-laid-out uniform buffer for one shader stage by matching
// SPIRV-Cross struct members (with their std140 offsets/sizes) against the
// program's named GL uniform values.  Handles the mat3 column-padding case
// (GL stores 9 floats; Metal/std140 stores 3 columns × 4 floats = 12).
//
static const ShaderReflection::ResourceBinding* defaultUniformBlock(
    const ShaderReflection& reflection)
{
    for (const auto& block : reflection.uniformBlocks) {
        if (block.name == "_DefaultUniforms") {
            return &block;
        }
    }
    return nullptr;
}

bool defaultUniformBlockContainsFp64(const ShaderReflection& reflection) {
    const auto* block = defaultUniformBlock(reflection);
    return block != nullptr && block->containsFp64;
}

bool reflectionNeedsFp64BindingShim(const ShaderReflection& reflection) {
    return reflection.fp64TranslationActive && reflection.usesFp64;
}

bool tessellationProgramUsesFp64(const GLProgramObject& program) {
    return program.tessControlReflection.usesFp64 ||
           program.tessControlReflection.fp64TranslationActive ||
           program.tessVertexAsComputeReflection.usesFp64 ||
           program.tessVertexAsComputeReflection.fp64TranslationActive ||
           program.tessEvalAsComputeReflection.usesFp64 ||
           program.tessEvalAsComputeReflection.fp64TranslationActive;
}

bool resourceNeedsFp64BindingShim(const ShaderReflection& reflection,
                                  const ShaderReflection::ResourceBinding& binding) {
    return reflectionNeedsFp64BindingShim(reflection) && binding.containsFp64;
}

static bool uniformMatrixShape(GLenum type, int& cols, int& rows, bool& isFp64) {
    isFp64 = false;
    switch (type) {
        case GL_FLOAT_MAT2: cols = 2; rows = 2; return true;
        case GL_FLOAT_MAT3: cols = 3; rows = 3; return true;
        case GL_FLOAT_MAT4: cols = 4; rows = 4; return true;
        case GL_FLOAT_MAT2x3: cols = 2; rows = 3; return true;
        case GL_FLOAT_MAT3x2: cols = 3; rows = 2; return true;
        case GL_FLOAT_MAT2x4: cols = 2; rows = 4; return true;
        case GL_FLOAT_MAT4x2: cols = 4; rows = 2; return true;
        case GL_FLOAT_MAT3x4: cols = 3; rows = 4; return true;
        case GL_FLOAT_MAT4x3: cols = 4; rows = 3; return true;
        case GL_DOUBLE_MAT2: cols = 2; rows = 2; isFp64 = true; return true;
        case GL_DOUBLE_MAT3: cols = 3; rows = 3; isFp64 = true; return true;
        case GL_DOUBLE_MAT4: cols = 4; rows = 4; isFp64 = true; return true;
        case GL_DOUBLE_MAT2x3: cols = 2; rows = 3; isFp64 = true; return true;
        case GL_DOUBLE_MAT3x2: cols = 3; rows = 2; isFp64 = true; return true;
        case GL_DOUBLE_MAT2x4: cols = 2; rows = 4; isFp64 = true; return true;
        case GL_DOUBLE_MAT4x2: cols = 4; rows = 2; isFp64 = true; return true;
        case GL_DOUBLE_MAT3x4: cols = 3; rows = 4; isFp64 = true; return true;
        case GL_DOUBLE_MAT4x3: cols = 4; rows = 3; isFp64 = true; return true;
        default: return false;
    }
}

static std::size_t uniformScalarBytes(GLenum type) {
    switch (type) {
        case GL_DOUBLE:
        case GL_DOUBLE_VEC2:
        case GL_DOUBLE_VEC3:
        case GL_DOUBLE_VEC4:
        case GL_DOUBLE_MAT2:
        case GL_DOUBLE_MAT3:
        case GL_DOUBLE_MAT4:
        case GL_DOUBLE_MAT2x3:
        case GL_DOUBLE_MAT3x2:
        case GL_DOUBLE_MAT2x4:
        case GL_DOUBLE_MAT4x2:
        case GL_DOUBLE_MAT3x4:
        case GL_DOUBLE_MAT4x3:
            return sizeof(GLdouble);
        default:
            return sizeof(GLfloat);
    }
}

static std::size_t uniformComponentCountForPacking(GLenum type) {
    return uniformTypeComponentCount(type);
}

static bool uniformLayoutNamesMatch(const std::string& uniformName,
                                    const std::string& memberName) {
    if (uniformName == memberName) return true;
    constexpr std::size_t kArrayZeroSuffixLen = 3;
    auto hasArrayZeroSuffix = [](const std::string& name) {
        return name.size() >= kArrayZeroSuffixLen &&
            name.compare(name.size() - kArrayZeroSuffixLen,
                         kArrayZeroSuffixLen,
                         "[0]") == 0;
    };
    if (hasArrayZeroSuffix(uniformName) &&
        uniformName.size() == memberName.size() + kArrayZeroSuffixLen &&
        uniformName.compare(0, memberName.size(), memberName) == 0) {
        return true;
    }
    if (hasArrayZeroSuffix(memberName) &&
        memberName.size() == uniformName.size() + kArrayZeroSuffixLen &&
        memberName.compare(0, uniformName.size(), uniformName) == 0) {
        return true;
    }
    return false;
}

static void hashCombine(std::size_t& seed, std::size_t value) {
    seed ^= value + 0x9e3779b97f4a7c15ull + (seed << 6u) + (seed >> 2u);
}

std::size_t hashFp64ResourceLayout(const ShaderReflection::ResourceBinding& binding,
                                   GLintptr sourceOffset,
                                   GLsizeiptr sourceSize) {
    std::size_t seed = 1469598103934665603ull;
    hashCombine(seed, std::hash<std::string>{}(binding.name));
    hashCombine(seed, static_cast<std::size_t>(sourceOffset));
    hashCombine(seed, static_cast<std::size_t>(sourceSize));
    hashCombine(seed, binding.members.size());
    for (const auto& member : binding.members) {
        if (!member.containsFp64) continue;
        hashCombine(seed, std::hash<std::string>{}(member.name));
        hashCombine(seed, member.offset);
        hashCombine(seed, member.size);
        hashCombine(seed, static_cast<std::size_t>(member.type));
        hashCombine(seed, static_cast<std::size_t>(member.arraySize));
        hashCombine(seed, static_cast<std::size_t>(member.arrayStride));
        hashCombine(seed, static_cast<std::size_t>(member.matrixStride));
        hashCombine(seed, member.isRowMajor ? 1u : 0u);
    }
    return seed;
}

static bool canonicalizeDf64Component(std::uint8_t* ptr,
                                      Fp64TransportDirection direction) {
    if (direction == Fp64TransportDirection::HostDoubleToDf64Words) {
        GLdouble value = 0.0;
        std::memcpy(&value, ptr, sizeof(value));
        const auto words = extensions::fp64::encodeDoubleToDf64Transport(value);
        std::memcpy(ptr, &words.hi, sizeof(words.hi));
        std::memcpy(ptr + sizeof(words.hi), &words.lo, sizeof(words.lo));
        return true;
    }

    extensions::fp64::Df64TransportWords words;
    std::memcpy(&words.hi, ptr, sizeof(words.hi));
    std::memcpy(&words.lo, ptr + sizeof(words.hi), sizeof(words.lo));
    const GLdouble value = extensions::fp64::decodeDf64TransportToDouble(words);
    std::memcpy(ptr, &value, sizeof(value));
    return true;
}

bool canonicalizeFp64ResourceBytes(std::uint8_t* bytes,
                                   std::size_t byteCount,
                                   const ShaderReflection::ResourceBinding& binding,
                                   Fp64TransportDirection direction) {
    if (bytes == nullptr || byteCount == 0 || !binding.containsFp64) {
        return false;
    }

    bool changed = false;
    for (const auto& member : binding.members) {
        if (!member.containsFp64 || member.offset >= byteCount) continue;

        int cols = 0;
        int rows = 0;
        bool isFp64Matrix = false;
        const bool isMatrix = uniformMatrixShape(member.type, cols, rows, isFp64Matrix);
        const std::size_t scalarBytes = uniformScalarBytes(member.type);
        if (scalarBytes != sizeof(GLdouble) || (isMatrix && !isFp64Matrix)) {
            continue;
        }

        const std::size_t arrayStride =
            member.arrayStride > 0 ? static_cast<std::size_t>(member.arrayStride) : 0u;
        std::size_t arrayCount = member.isArray && member.arraySize > 0
            ? static_cast<std::size_t>(member.arraySize) : 1u;
        if (member.isArray && member.arraySize == 0 && arrayStride > 0) {
            arrayCount = (byteCount - member.offset) / arrayStride;
        }

        if (isMatrix) {
            const int majorCount = member.isRowMajor ? rows : cols;
            const int minorCount = member.isRowMajor ? cols : rows;
            const std::size_t matrixStride = member.matrixStride > 0
                ? static_cast<std::size_t>(member.matrixStride)
                : static_cast<std::size_t>(minorCount) * scalarBytes;
            const std::size_t matrixBytes =
                static_cast<std::size_t>(majorCount - 1) * matrixStride +
                static_cast<std::size_t>(minorCount) * scalarBytes;
            const std::size_t elementStride =
                member.isArray && arrayStride > 0 ? arrayStride : matrixBytes;
            for (std::size_t arrayIndex = 0; arrayIndex < arrayCount; ++arrayIndex) {
                const std::size_t base = member.offset + arrayIndex * elementStride;
                for (int major = 0; major < majorCount; ++major) {
                    for (int minor = 0; minor < minorCount; ++minor) {
                        const std::size_t componentOffset =
                            base + static_cast<std::size_t>(major) * matrixStride +
                            static_cast<std::size_t>(minor) * scalarBytes;
                        if (componentOffset + sizeof(GLdouble) > byteCount) {
                            continue;
                        }
                        changed |= canonicalizeDf64Component(bytes + componentOffset, direction);
                    }
                }
            }
            continue;
        }

        const std::size_t components = uniformComponentCountForPacking(member.type);
        const std::size_t elementBytes = components * scalarBytes;
        const std::size_t elementStride =
            member.isArray && arrayStride > 0 ? arrayStride : elementBytes;
        for (std::size_t arrayIndex = 0; arrayIndex < arrayCount; ++arrayIndex) {
            const std::size_t base = member.offset + arrayIndex * elementStride;
            for (std::size_t component = 0; component < components; ++component) {
                const std::size_t componentOffset = base + component * scalarBytes;
                if (componentOffset + sizeof(GLdouble) > byteCount) {
                    continue;
                }
                changed |= canonicalizeDf64Component(bytes + componentOffset, direction);
            }
        }
    }
    return changed;
}

// ── OPT-7: precomputed uniform layout ──
// computeStageUniformLayout() runs once per program per stage, mapping each
// push-constant struct member to its GL uniform location.  This eliminates
// the O(N*M) string comparison from the per-draw packing path.
static void computeStageUniformLayout(
    std::vector<GLProgramObject::UniformLayoutEntry>& layout,
    const ShaderReflection& reflection,
    const std::vector<GLProgramUniformInfo>& uniforms)
{
    layout.clear();
    const auto* defaultBlock = defaultUniformBlock(reflection);
    if (defaultBlock == nullptr) return;
    const auto& block = *defaultBlock;
    if (block.byteSize == 0) return;

    layout.reserve(block.members.size());
    for (const auto& member : block.members) {
        GLProgramObject::UniformLayoutEntry entry;
        entry.memberOffset = member.offset;
        entry.copyBytes = member.size;
        entry.location = -1;
        entry.memberType = member.type;
        entry.containsFp64 = member.containsFp64;
        // Matrix column-padding: GL stores glUniformMatrix payloads in a
        // tight column-major sequence. SPIR-V/MSL block layout may align
        // each column to a larger stride. Use the reflected matrix stride
        // when present so FP64 df64 words follow the same route as floats.
        int matrixCols = 0;
        int matrixRows = 0;
        bool matrixIsFp64 = false;
        if (uniformMatrixShape(member.type, matrixCols, matrixRows, matrixIsFp64)) {
            entry.matPaddedCols = member.isRowMajor ? matrixRows : matrixCols;
            entry.matPaddedRows = member.isRowMajor ? matrixCols : matrixRows;
            entry.matPaddedScalarBytes = matrixIsFp64 ? sizeof(GLdouble) : sizeof(GLfloat);
            const std::size_t tightBytes =
                static_cast<std::size_t>(entry.matPaddedCols) *
                static_cast<std::size_t>(entry.matPaddedRows) *
                entry.matPaddedScalarBytes;
            entry.matPaddedStrideBytes = member.matrixStride > 0
                ? static_cast<std::size_t>(member.matrixStride)
                : static_cast<std::size_t>(entry.matPaddedRows) *
                      entry.matPaddedScalarBytes;
            if (member.size <= tightBytes ||
                entry.matPaddedStrideBytes <=
                    static_cast<std::size_t>(entry.matPaddedRows) *
                        entry.matPaddedScalarBytes) {
                entry.matPaddedCols = 0;
                entry.matPaddedRows = 0;
            }
        }

        // Array uniforms need per-element unpadding in std140 layout:
        // GL stores a float[3] as 12 packed bytes; std140 stores it as
        // 48 bytes (3 elements × 16-byte stride, only 4 used per). We
        // cache the stride and per-element GL byte count so the hot
        // packing loop iterates element-wise when arrayCount > 0.
        // KHR-GL46.explicit_uniform_location.uniform-loc-arrays-*
        // exercises this — declares `uniform float u0[3]` at location N
        // and expects each glUniform1f(N+i, …) to land at u0[i].
        if (member.arraySize > 1 && member.size > 0 && entry.matPaddedCols == 0) {
            entry.arrayCount = member.arraySize;
            entry.arrayStride = member.arrayStride > 0
                ? static_cast<std::size_t>(member.arrayStride)
                : member.size / member.arraySize;
            entry.glElementBytes =
                uniformComponentCountForPacking(member.type) *
                uniformScalarBytes(member.type);
        }

        // One-time name lookup: find the GL uniform location for this member.
        for (const auto& u : uniforms) {
            if (uniformLayoutNamesMatch(u.name, member.name)) {
                entry.location = u.location;
                break;
            }
        }
        layout.push_back(entry);
    }
}

static const std::vector<GLProgramUniformInfo>& uniformsForEmulationStage(
    const GLProgramObject& program,
    int stageIndex)
{
    if (stageIndex >= 0 && stageIndex < 6 &&
        program.pipelineEmulationStageUniformsValid[static_cast<std::size_t>(stageIndex)]) {
        return program.pipelineEmulationStageUniforms[static_cast<std::size_t>(stageIndex)];
    }
    return program.uniforms;
}

static const std::unordered_map<GLint, GLProgramUniformValue>& uniformValuesForEmulationStage(
    const GLProgramObject& program,
    int stageIndex)
{
    if (stageIndex >= 0 && stageIndex < 6 &&
        program.pipelineEmulationStageUniformsValid[static_cast<std::size_t>(stageIndex)]) {
        return program.pipelineEmulationStageUniformValues[static_cast<std::size_t>(stageIndex)];
    }
    return program.uniformValues;
}

// The output is written into |outBuffer|, which is resized via assign().
// Callers should pass a thread-local vector so that the allocation persists
// across draw calls — after the first frame this is a zero-alloc operation.
//
// OPT-7: uses the precomputed layout to avoid per-draw string comparisons.
// The layout maps struct members directly to uniform locations.
// Push synthesized fixed-function matrix uniform values into the
// program's uniformValues map so the next buildStageUniformBuffer
// pack picks them up. Reads from the per-context MatrixStateMirror
// and writes only the slots that the link-time scan found in
// programObject->synthesizedMatrixSlots — slots whose original
// (compat-profile) shader source did not reference the corresponding
// gl_* identifier stay at -1 and get skipped. When no slots are set
// at all (the typical case for core-profile programs), this returns
// in O(1) and the per-draw cost is a single bool check.
template <typename T>
static bool replaceVectorIfChanged(std::vector<T>& dst,
                                   const T* src,
                                   std::size_t count) {
    if (dst.size() == count && (count == 0 || std::equal(dst.begin(), dst.end(), src))) {
        return false;
    }
    dst.assign(src, src + count);
    return true;
}

static bool assignSynthesizedUniformFloats(GLProgramUniformValue& value,
                                           GLenum type,
                                           GLint arraySize,
                                           const GLfloat* data,
                                           std::size_t count) {
    bool changed = value.type != type ||
                   value.arraySize != arraySize ||
                   !value.ints.empty() ||
                   !value.uints.empty() ||
                   !value.doubles.empty() ||
                   !value.df64TransportWords.empty();
    changed |= replaceVectorIfChanged(value.floats, data, count);
    value.type = type;
    value.arraySize = arraySize;
    value.ints.clear();
    value.uints.clear();
    value.doubles.clear();
    value.df64TransportWords.clear();
    return changed;
}

static bool assignSynthesizedUniformInts(GLProgramUniformValue& value,
                                         GLenum type,
                                         GLint arraySize,
                                         const GLint* data,
                                         std::size_t count) {
    bool changed = value.type != type ||
                   value.arraySize != arraySize ||
                   !value.floats.empty() ||
                   !value.uints.empty() ||
                   !value.doubles.empty() ||
                   !value.df64TransportWords.empty();
    changed |= replaceVectorIfChanged(value.ints, data, count);
    value.type = type;
    value.arraySize = arraySize;
    value.floats.clear();
    value.uints.clear();
    value.doubles.clear();
    value.df64TransportWords.clear();
    return changed;
}

static bool pushSynthesizedMatrixUniforms(
    GLProgramObject& program,
    const MatrixStateMirror& matrixState,
    GLuint drawID = 0,
    GLint baseVertex = 0,
    GLuint baseInstance = 0)
{
    bool changed = false;
    if (program.shaderDrawIDUniformLocation >= 0) {
        auto& value = program.uniformValues[program.shaderDrawIDUniformLocation];
        const GLint drawIDValue = static_cast<GLint>(drawID);
        changed |= assignSynthesizedUniformInts(
            value, GL_INT, 1, &drawIDValue, 1);
    }
    if (program.shaderBaseVertexUniformLocation >= 0) {
        auto& value = program.uniformValues[program.shaderBaseVertexUniformLocation];
        const GLint baseVertexValue = baseVertex;
        changed |= assignSynthesizedUniformInts(
            value, GL_INT, 1, &baseVertexValue, 1);
    }
    if (program.shaderBaseInstanceUniformLocation >= 0) {
        auto& value = program.uniformValues[program.shaderBaseInstanceUniformLocation];
        const GLint baseInstanceValue = static_cast<GLint>(baseInstance);
        changed |= assignSynthesizedUniformInts(
            value, GL_INT, 1, &baseInstanceValue, 1);
    }

    const auto& slots = program.synthesizedMatrixSlots;
    if (!slots.hasAny()) {
        return changed;
    }

    auto storeMat4 = [&](GLint loc, const Matrix4& matrix) {
        if (loc < 0) return;
        auto& value = program.uniformValues[loc];
        changed |= assignSynthesizedUniformFloats(
            value, GL_FLOAT_MAT4, 1, matrix.m.data(), matrix.m.size());
    };
    auto storeMat3 = [&](GLint loc, const Matrix4& matrix) {
        if (loc < 0) return;
        // GL stores mat3 as 9 packed floats (3 columns × 3 rows). The
        // GPU side uses 3 vec4 columns; buildStageUniformBuffer's
        // matrix-column-padding path (matPaddedCols / matPaddedRows)
        // repacks 9 → 12 floats when the layout entry is flagged. We
        // store the 9-float canonical form here.
        std::array<GLfloat, 9> packed = {};
        for (int col = 0; col < 3; ++col) {
            for (int row = 0; row < 3; ++row) {
                packed[static_cast<std::size_t>(col * 3 + row)] =
                    matrix.m[static_cast<std::size_t>(col * 4 + row)];
            }
        }
        auto& value = program.uniformValues[loc];
        changed |= assignSynthesizedUniformFloats(
            value, GL_FLOAT_MAT3, 1, packed.data(), packed.size());
    };

    if (slots.modelView >= 0) {
        storeMat4(slots.modelView, matrixState.modelView());
    }
    if (slots.projection >= 0) {
        storeMat4(slots.projection, matrixState.projection());
    }
    if (slots.modelViewProjection >= 0) {
        storeMat4(slots.modelViewProjection, matrixState.modelViewProjection());
    }
    if (slots.modelViewInverse >= 0) {
        storeMat4(slots.modelViewInverse, matrixState.modelViewInverse());
    }
    if (slots.projectionInverse >= 0) {
        storeMat4(slots.projectionInverse, matrixState.projectionInverse());
    }
    if (slots.modelViewProjectionInverse >= 0) {
        storeMat4(slots.modelViewProjectionInverse,
                  matrixState.modelViewProjectionInverse());
    }
    if (slots.normal >= 0) {
        storeMat3(slots.normal, matrixState.normalMatrix());
    }
    if (slots.texture >= 0) {
        // Texture matrix is `mat4 appgl_TextureMatrix[N]`. The link
        // pass treats it as a single uniform whose value buffer holds
        // N * 16 packed floats. Fill all N entries from the per-unit
        // texture stack tops; unused units come back as identity from
        // MatrixStateMirror::textureMatrix() so the GPU-side array is
        // always fully populated.
        std::array<GLfloat, kSynthesizedTextureMatrixCount * 16> packed = {};
        for (unsigned int i = 0; i < kSynthesizedTextureMatrixCount; ++i) {
            const Matrix4 m = matrixState.textureMatrix(i);
            std::memcpy(packed.data() + i * 16,
                        m.m.data(),
                        16 * sizeof(float));
        }
        auto& value = program.uniformValues[slots.texture];
        changed |= assignSynthesizedUniformFloats(
            value,
            GL_FLOAT_MAT4,
            static_cast<GLint>(kSynthesizedTextureMatrixCount),
            packed.data(),
            packed.size());
    }
    return changed;
}

static void buildStageUniformBuffer(
    std::vector<std::uint8_t>& outBuffer,
    const ShaderReflection& reflection,
    const std::unordered_map<GLint, GLProgramUniformValue>& uniformValues,
    const std::vector<GLProgramObject::UniformLayoutEntry>& layout)
{
    outBuffer.clear();
    const auto* defaultBlock = defaultUniformBlock(reflection);
    if (defaultBlock == nullptr) return;
    const auto& block = *defaultBlock;
    if (block.byteSize == 0) return;

    const std::size_t paddedSize = (block.byteSize + 15u) & ~std::size_t(15u);
    outBuffer.assign(paddedSize, 0);

    for (const auto& entry : layout) {
        if (entry.location < 0) continue;

        auto it = uniformValues.find(entry.location);
        if (it == uniformValues.end()) continue;
        const auto& val = it->second;

        // Determine which data vector to use based on what's populated.
        const void* srcData = nullptr;
        std::size_t srcBytes = 0;
        if (entry.containsFp64 && !val.df64TransportWords.empty()) {
            srcData = val.df64TransportWords.data();
            srcBytes = val.df64TransportWords.size() * sizeof(std::uint32_t);
        } else if (!val.floats.empty()) {
            srcData = val.floats.data();
            srcBytes = val.floats.size() * sizeof(GLfloat);
        } else if (!val.ints.empty()) {
            srcData = val.ints.data();
            srcBytes = val.ints.size() * sizeof(GLint);
        } else if (!val.uints.empty()) {
            srcData = val.uints.data();
            srcBytes = val.uints.size() * sizeof(GLuint);
        } else {
            continue;
        }

        std::uint8_t* dst = outBuffer.data() + entry.memberOffset;

        // Matrix column-padding: GL packs matrix data as `cols*rows`
        // tight components; MSL/std140 may align each column to a larger
        // stride. This path also handles df64 transport words because each
        // lowered double component still occupies 8 bytes.
        if (entry.matPaddedCols > 0 && entry.matPaddedRows > 0) {
            const std::size_t columnBytes =
                static_cast<std::size_t>(entry.matPaddedRows) *
                entry.matPaddedScalarBytes;
            const std::size_t needed = static_cast<std::size_t>(
                entry.matPaddedCols) * columnBytes;
            if (srcBytes >= needed) {
                const int cols = entry.matPaddedCols;
                const auto* srcBytesPtr = static_cast<const std::uint8_t*>(srcData);
                for (int col = 0; col < cols; ++col) {
                    std::memcpy(
                        dst + static_cast<std::size_t>(col) *
                            entry.matPaddedStrideBytes,
                        srcBytesPtr + static_cast<std::size_t>(col) * columnBytes,
                        columnBytes);
                }
                continue;
            }
        }

        // Array element unpadding: GL stores element [k] at byte offset
        // k * glElementBytes (tight); std140 places it at k * arrayStride
        // (>= 16). Loop per element, memcpy the GL-packed element into
        // its std140 slot, leave padding bytes zero. Applies to arrays
        // of scalars (float arr[N], int arr[N]) and vec3 arrays which
        // have slightly-wasted but still padded layout.
        if (entry.arrayCount > 0 && entry.arrayStride > entry.glElementBytes) {
            const std::size_t perEl = entry.glElementBytes;
            const std::size_t stride = entry.arrayStride;
            const auto* srcBytesPtr = static_cast<const std::uint8_t*>(srcData);
            for (std::uint32_t k = 0; k < entry.arrayCount; ++k) {
                const std::size_t srcOff = static_cast<std::size_t>(k) * perEl;
                const std::size_t dstOff = static_cast<std::size_t>(k) * stride;
                if (srcOff + perEl > srcBytes) break;
                std::memcpy(dst + dstOff, srcBytesPtr + srcOff, perEl);
            }
            continue;
        }

        std::memcpy(dst, srcData, std::min(srcBytes, entry.copyBytes));
    }
}

static void prepareTranslatedDrawUniformBuffers(
    GLProgramObject& program,
    GLuint programName,
    const MatrixStateMirror& matrixState,
    GLuint drawID,
    TranslatedDrawInfo& tdi,
    const char* path)
{
    if (!program.uniformLayoutComputed) {
        computeStageUniformLayout(program.vertexUniformLayout,
            program.vertexReflection, program.uniforms);
        computeStageUniformLayout(program.fragmentUniformLayout,
            program.fragmentReflection, program.uniforms);
        program.uniformLayoutComputed = true;
        program.invalidateUniformBufferCache();
    }

    if (pushSynthesizedMatrixUniforms(
            program, matrixState, drawID,
            tdi.shaderBaseVertex, tdi.baseInstance)) {
        program.markUniformsDirty();
    }

    const bool rebuilt = program.isUniformBufferDirty();
    if (rebuilt) {
        buildStageUniformBuffer(program.cachedVertexUniformBuffer,
            program.vertexReflection, program.uniformValues,
            program.vertexUniformLayout);
        buildStageUniformBuffer(program.cachedFragmentUniformBuffer,
            program.fragmentReflection, program.uniformValues,
            program.fragmentUniformLayout);
        program.markUniformBufferClean();
    }

    tdi.vertexUniformData = program.cachedVertexUniformBuffer.data();
    tdi.vertexUniformSize = program.cachedVertexUniformBuffer.size();
    tdi.fragmentUniformData = program.cachedFragmentUniformBuffer.data();
    tdi.fragmentUniformSize = program.cachedFragmentUniformBuffer.size();

    APPGL_LOG(DRAW, @"[GL:uniform-rebuild] path=%s program=%u rebuilt=%d gen=%llu"
                    @" vertexBytes=%zu fragmentBytes=%zu",
              path,
              programName,
              rebuilt ? 1 : 0,
              static_cast<unsigned long long>(program.uniformValueGeneration),
              program.cachedVertexUniformBuffer.size(),
              program.cachedFragmentUniformBuffer.size());
}

static void logStateResolveCostClass(const char* path,
                                     GLuint programName,
                                     GLuint vaoName,
                                     const TranslatedDrawInfo& tdi,
                                     std::size_t vaoAttributeCount,
                                     bool vaoLayoutCacheHit = false)
{
    APPGL_LOG(DRAW, @"[GL:state-resolve] path=%s program=%u vao=%u"
                    @" vaoAttrs=%zu primaryAttrs=%zu extraBuffers=%zu"
                    @" vaoLayoutCacheHit=%d",
              path,
              programName,
              vaoName,
              vaoAttributeCount,
              tdi.vertexAttributeLayouts.size(),
              tdi.extraVertexBuffers.size(),
              vaoLayoutCacheHit ? 1 : 0);
}

static void logIndexExpansionCostClass(const char* path,
                                       GLuint elementBufferName,
                                       GLenum inputType,
                                       GLenum outputType,
                                       GLsizei count,
                                       std::size_t expandedBytes,
                                       bool cacheHit,
                                       std::uint32_t generation)
{
    APPGL_LOG(DRAW, @"[GL:expansion] path=%s elementBuffer=%u"
                    @" inputType=0x%x outputType=0x%x count=%d"
                    @" expandedBytes=%zu cacheHit=%d generation=%u",
              path,
              elementBufferName,
              inputType,
              outputType,
              count,
              expandedBytes,
              cacheHit ? 1 : 0,
              generation);
}

static void resetReusableTranslatedDrawInfo(TranslatedDrawInfo& tdi)
{
    auto vertexAttributeLayouts = std::move(tdi.vertexAttributeLayouts);
    auto extraVertexBuffers = std::move(tdi.extraVertexBuffers);
    auto fragmentTextures = std::move(tdi.fragmentTextures);
    auto vertexTextures = std::move(tdi.vertexTextures);
    auto uboBindings = std::move(tdi.uboBindings);
    auto ssboBindings = std::move(tdi.ssboBindings);
    auto atomicCounterBindings = std::move(tdi.atomicCounterBindings);
    auto sampledTextureNames = std::move(tdi.sampledTextureNames);
    auto readImageTextureNames = std::move(tdi.readImageTextureNames);
    auto writtenImageTextureNames = std::move(tdi.writtenImageTextureNames);

    vertexAttributeLayouts.clear();
    extraVertexBuffers.clear();
    fragmentTextures.clear();
    vertexTextures.clear();
    uboBindings.clear();
    ssboBindings.clear();
    atomicCounterBindings.clear();
    sampledTextureNames.clear();
    readImageTextureNames.clear();
    writtenImageTextureNames.clear();

    tdi = TranslatedDrawInfo{};
    tdi.vertexAttributeLayouts = std::move(vertexAttributeLayouts);
    tdi.extraVertexBuffers = std::move(extraVertexBuffers);
    tdi.fragmentTextures = std::move(fragmentTextures);
    tdi.vertexTextures = std::move(vertexTextures);
    tdi.uboBindings = std::move(uboBindings);
    tdi.ssboBindings = std::move(ssboBindings);
    tdi.atomicCounterBindings = std::move(atomicCounterBindings);
    tdi.sampledTextureNames = std::move(sampledTextureNames);
    tdi.readImageTextureNames = std::move(readImageTextureNames);
    tdi.writtenImageTextureNames = std::move(writtenImageTextureNames);
}

static TranslatedDrawInfo& reusableTranslatedDrawInfo()
{
    thread_local TranslatedDrawInfo tdi;
    resetReusableTranslatedDrawInfo(tdi);
    return tdi;
}

// Phase A Group 7 — MVP draw path. Until the GLSL→MSL translator is wired up,
// the runtime supports one hand-written "solid color" pipeline: a single
// vec3 position attribute at location 0 plus a vec4 uniform named "uColor".
// Anything outside that envelope is rejected here so the caller can emit a
// debug message and bail cleanly instead of producing garbage pixels.
// Resolve the effective VBO name, stride, and byte offset for a vertex
// attribute, handling both classic (glVertexAttribPointer) and separated
// (GL 4.3/4.5 glVertexAttribFormat + glVertexArrayVertexBuffer) formats.
struct ResolvedVertexAttrib {
    GLuint bufferName = 0;
    std::size_t stride = 0;
    std::size_t offset = 0;
};

static ResolvedVertexAttrib resolveVertexAttrib(
    const GLVertexAttributeState& attr,
    const GLVertexArrayObject& vao)
{
    auto attributeScalarBytes = [](GLenum type) -> std::size_t {
        switch (type) {
            case GL_BYTE:
            case GL_UNSIGNED_BYTE:
                return 1;
            case GL_SHORT:
            case GL_UNSIGNED_SHORT:
            case GL_HALF_FLOAT:
                return 2;
            case GL_DOUBLE:
                return 8;
            default:
                return 4;
        }
    };
    ResolvedVertexAttrib r;
    // GL 4.3 separated vertex format: attribute[i].bindingIndex = i by
    // default (see `GLObjectStore::initializeVertexArray`), and
    // `glBindVertexBuffer(s)` writes buffer/offset/stride to
    // `bindingPoints[N]` independently. An attribute can reach that
    // binding state WITHOUT a prior `glVertexAttribFormat` — the
    // default per-attribute format (size=4, type=GL_FLOAT,
    // relativeOffset=0) is always in effect. So we take the
    // binding-point path whenever a bound buffer is present there,
    // even when `useSeparatedFormat` is still false.
    //
    // Without this fallback, `multi_bind.draw_bind_vertex_buffers`
    // and similar "bindVertexBuffers + default-format-draw" tests
    // read zeros from every attribute — `attr.buffer` is 0
    // (VertexAttribPointer was never called), so the legacy branch
    // returned bufferName=0 and Metal fetched nothing.
    const bool hasSeparatedBinding =
        (attr.bindingIndex < vao.bindingPoints.size()) &&
        (vao.bindingPoints[attr.bindingIndex].buffer != 0);
    if (attr.useSeparatedFormat || hasSeparatedBinding) {
        if (attr.bindingIndex < vao.bindingPoints.size()) {
            const auto& bp = vao.bindingPoints[attr.bindingIndex];
            r.bufferName = bp.buffer;
            r.stride = bp.stride > 0
                ? static_cast<std::size_t>(bp.stride)
                : attributeScalarBytes(attr.type) *
                    static_cast<std::size_t>(attr.size);
            r.offset = static_cast<std::size_t>(bp.offset)
                     + static_cast<std::size_t>(attr.relativeOffset);
            return r;
        }
    }
    r.bufferName = attr.buffer;
    r.stride = attr.stride > 0
        ? static_cast<std::size_t>(attr.stride)
        : attributeScalarBytes(attr.type) *
            static_cast<std::size_t>(attr.size);
    r.offset = static_cast<std::size_t>(attr.pointer);
    return r;
}

struct SolidColorDrawSetup {
    bool ok = false;
    MetalDrawInfo info;
    GLVertexArrayObject* vertexArray = nullptr;
    GLProgramObject* program = nullptr;
    const std::uint8_t* positionShadow = nullptr;
    std::size_t positionShadowSize = 0;
};

// Phase 8X Group 4d follow-up¹⁴ — common pipeline state plumbing for
// the translated-draw path. Centralises the depth/cull/front-face/
// wireframe/blend reads so every draw entry point captures the same
// snapshot without drifting. The blend fields come directly from
// `GLStateTracker::blendState()` — the getter already returns the RGB
// vs. alpha split, so we just mirror it into the TDI substruct and
// separately ask `isEnabled(GL_BLEND)` for the enable bit (which lives
// in `enabledCaps_`, not the blend struct itself).
static void populateTranslatedDrawFixedFunctionState(
    TranslatedDrawInfo& tdi, GLStateTracker& state, GLenum fragmentShadingRate,
    GLContext* context = nullptr)
{
    tdi.depthTestEnabled = state.isEnabled(GL_DEPTH_TEST);
    tdi.depthFunc = state.depthState().func;
    tdi.depthWriteMask = (state.depthState().writeMask != GL_FALSE);
    // Sprint 7 Phase 1 #11 (CKPT57): mirror GL stencil state into the
    // TDI so depthStencilStateForDraw can configure Metal's per-face
    // stencil descriptors. Without this, GL stencil-test+ops were
    // silently dropped at draw time (Metal default = Always + Keep,
    // which masquerades as "stencil-test always passes" but never
    // writes back, breaking primitive_coverage and any other test
    // that depends on stencil correctness).
    {
        const auto& gs = state.stencilState();
        tdi.stencilTestEnabled = state.isEnabled(GL_STENCIL_TEST);
        tdi.stencilFrontFunc = gs.front.func;
        tdi.stencilFrontRef = gs.front.ref;
        tdi.stencilFrontValueMask = gs.front.valueMask;
        tdi.stencilFrontFail = gs.front.fail;
        tdi.stencilFrontDepthFail = gs.front.depthFail;
        tdi.stencilFrontDepthPass = gs.front.depthPass;
        tdi.stencilFrontWriteMask = gs.front.writeMask;
        tdi.stencilBackFunc = gs.back.func;
        tdi.stencilBackRef = gs.back.ref;
        tdi.stencilBackValueMask = gs.back.valueMask;
        tdi.stencilBackFail = gs.back.fail;
        tdi.stencilBackDepthFail = gs.back.depthFail;
        tdi.stencilBackDepthPass = gs.back.depthPass;
        tdi.stencilBackWriteMask = gs.back.writeMask;
    }
    tdi.cullFaceEnabled = state.isEnabled(GL_CULL_FACE);
    tdi.cullFaceMode = state.rasterState().cullFaceMode;
    tdi.frontFace = state.rasterState().frontFace;
    tdi.wireframe = (state.rasterState().polygonFillMode == GL_LINE);
    tdi.sampleMask =
        state.isEnabled(GL_SAMPLE_MASK)
            ? static_cast<std::uint32_t>(state.sampleMask(0))
            : 0xFFFFFFFFu;
    tdi.rasterizerDiscard = state.isEnabled(GL_RASTERIZER_DISCARD);
    // Phase 6-1d: sample-shading snapshot. The Metal side uses this
    // to force per-sample FS invocation when the bound attachment
    // is MS; until that plumbing lands (6-1e+), the state is merely
    // captured so the correct values are available when we need them.
    tdi.sampleShadingEnabled = state.isEnabled(GL_SAMPLE_SHADING);
    tdi.minSampleShading = state.blendState().minSampleShading;
    tdi.fragmentShadingRate = fragmentShadingRate;
    if (context != nullptr) {
        populateFragmentShadingRateShaderState(*context, tdi);
    }

    // GL 4.6 §14.6.5 — polygon offset enabled under GL_POLYGON_OFFSET_FILL
    // (relevant for triangle rasterization) plus LINE / POINT variants.
    // If any of the three is enabled, thread factor/units/clamp into the
    // draw info so the render encoder applies depth bias before the draw.
    const bool anyOffsetEnabled = state.isEnabled(GL_POLYGON_OFFSET_FILL) ||
                                  state.isEnabled(GL_POLYGON_OFFSET_LINE) ||
                                  state.isEnabled(GL_POLYGON_OFFSET_POINT);
    tdi.polygonOffsetEnabled = anyOffsetEnabled;
    tdi.polygonOffsetFactor = state.rasterState().polygonOffsetFactor;
    tdi.polygonOffsetUnits = state.rasterState().polygonOffsetUnits;
    tdi.polygonOffsetClamp = state.rasterState().polygonOffsetClamp;

    const auto& gl = state.blendState();
    tdi.blend.enabled = state.isEnabled(GL_BLEND);
    tdi.blend.srcRGB = gl.srcRGB;
    tdi.blend.dstRGB = gl.dstRGB;
    tdi.blend.srcAlpha = gl.srcAlpha;
    tdi.blend.dstAlpha = gl.dstAlpha;
    tdi.blend.equationRGB = gl.equationRGB;
    tdi.blend.equationAlpha = gl.equationAlpha;
    tdi.blend.colorMaskR = (gl.colorMask[0] != GL_FALSE);
    tdi.blend.colorMaskG = (gl.colorMask[1] != GL_FALSE);
    tdi.blend.colorMaskB = (gl.colorMask[2] != GL_FALSE);
    tdi.blend.colorMaskA = (gl.colorMask[3] != GL_FALSE);

    // RC-A02: viewport state.
    const auto& vp = state.viewport();
    tdi.viewportX = vp.x;
    tdi.viewportY = vp.y;
    tdi.viewportWidth = vp.width;
    tdi.viewportHeight = vp.height;
    const auto& dr = state.depthRange();
    tdi.depthRangeNear = dr.nearValue;
    tdi.depthRangeFar = dr.farValue;
    // Sprint 17 Day 3+ BONUS-1 [clip_control]: snapshot the
    // current `glClipControl` origin into TranslatedDrawInfo so
    // MetalFrameGraph's viewport-Y-flip can gate on it
    // (`GL_UPPER_LEFT` → no flip, `GL_LOWER_LEFT` → flip as before).
    tdi.clipOrigin = state.clipOrigin();
    // Sprint 15 Q3-Option-B Day 8 [metal-viewport-array]: populate
    // per-index viewport array (GL 4.1 ARB_viewport_array). Bind
    // multi-viewport at the encoder when ANY indexed slot diverges
    // from slot 0 (i.e. the app has called glViewportIndexed* or
    // glViewportArrayv to set per-index state). Otherwise count=0 to
    // preserve the single-viewport encoder path.
    //
    // Sprint 16 Day 19 (CKPT228): also bind the array when only the
    // *scissor* array diverges (`glScissorIndexed*` /
    // `glScissorArrayv`). CTS `viewport_array.scissor` /
    // `viewport_array.scissor_clear` set 16 per-index scissor rects
    // but never touch glViewportArrayv — every indexed viewport
    // stays at slot 0's value, so the prior viewport-only divergence
    // check stayed false, the encoder used the single-viewport
    // single-scissor path, and Metal applied the same default
    // scissor to every fragment regardless of the per-vertex
    // `gl_ViewportIndex` the GS emitted. Detecting scissor divergence
    // routes the draw through `setViewports:count:N` +
    // `setScissorRects:count:N` even when viewport[1..N-1] match
    // slot 0, which is what the scissor tests need.
    {
        appgl::GLStateTracker::IndexedViewportEntry vparr[
            appgl::TranslatedDrawInfo::kMaxDrawViewports];
        std::size_t got = 0;
        state.getViewportArray(vparr,
            appgl::TranslatedDrawInfo::kMaxDrawViewports, &got);
        appgl::GLStateTracker::IndexedScissorEntry scarr_pre[
            appgl::TranslatedDrawInfo::kMaxDrawViewports];
        std::size_t scgot_pre = 0;
        state.getScissorArray(scarr_pre,
            appgl::TranslatedDrawInfo::kMaxDrawViewports, &scgot_pre);
        bool anyDiverge = false;
        for (std::size_t i = 1; i < got; ++i) {
            if (vparr[i].x != vparr[0].x ||
                vparr[i].y != vparr[0].y ||
                vparr[i].width != vparr[0].width ||
                vparr[i].height != vparr[0].height ||
                vparr[i].depthNear != vparr[0].depthNear ||
                vparr[i].depthFar != vparr[0].depthFar) {
                anyDiverge = true;
                break;
            }
        }
        if (!anyDiverge) {
            for (std::size_t i = 1; i < scgot_pre; ++i) {
                if (scarr_pre[i].x != scarr_pre[0].x ||
                    scarr_pre[i].y != scarr_pre[0].y ||
                    scarr_pre[i].width != scarr_pre[0].width ||
                    scarr_pre[i].height != scarr_pre[0].height ||
                    scarr_pre[i].enabled != scarr_pre[0].enabled) {
                    anyDiverge = true;
                    break;
                }
            }
        }
        if (anyDiverge) {
            for (std::size_t i = 0; i < got; ++i) {
                tdi.viewportArray[i].originX = vparr[i].x;
                tdi.viewportArray[i].originY = vparr[i].y;
                tdi.viewportArray[i].width = vparr[i].width;
                tdi.viewportArray[i].height = vparr[i].height;
                tdi.viewportArray[i].depthNear = vparr[i].depthNear;
                tdi.viewportArray[i].depthFar = vparr[i].depthFar;
            }
            tdi.viewportArrayCount = got;
            // Sprint 16 Day 3 [viewport_array]: pair the indexed scissor
            // array. When viewport array is bound, Metal requires a
            // matching scissor count (otherwise viewports 1..N-1 see
            // an undefined scissor and clip every fragment).
            appgl::GLStateTracker::IndexedScissorEntry scarr[
                appgl::TranslatedDrawInfo::kMaxDrawViewports];
            std::size_t scgot = 0;
            state.getScissorArray(scarr,
                appgl::TranslatedDrawInfo::kMaxDrawViewports, &scgot);
            const std::size_t cap = std::min(got, scgot);
            for (std::size_t i = 0; i < cap; ++i) {
                tdi.scissorArray[i].x = scarr[i].x;
                tdi.scissorArray[i].y = scarr[i].y;
                tdi.scissorArray[i].width = scarr[i].width;
                tdi.scissorArray[i].height = scarr[i].height;
                tdi.scissorArray[i].enabled = scarr[i].enabled;
            }
        }
    }

    // GL 4.6 §14.5.1 — scissor state.
    tdi.scissorTestEnabled = state.isEnabled(GL_SCISSOR_TEST);
    const auto& sc = state.scissor();
    tdi.scissorX = sc.x;
    tdi.scissorY = sc.y;
    tdi.scissorWidth = sc.width;
    tdi.scissorHeight = sc.height;
    phase2PlanRefreshFixedStateSegmentHash(tdi, "populate_fixed_function_state");
}

static constexpr std::size_t kPlainVaoLayoutCacheIndex = 0;
static constexpr std::size_t kDivisorAwareVaoLayoutCacheIndex = 1;
static constexpr std::size_t kIndexedDivisorAwareVaoLayoutCacheIndex = 2;
static constexpr std::size_t kPlainNoMinVaoLayoutCacheIndex = 3;

static GLuint effectiveVertexAttribDivisor(
    const GLVertexAttributeState& attr,
    const GLVertexArrayObject& vao)
{
    return attr.useSeparatedFormat
        ? (attr.bindingIndex < vao.bindingPoints.size()
            ? vao.bindingPoints[attr.bindingIndex].divisor
            : attr.divisor)
        : attr.divisor;
}

static GLVertexArrayCachedAttributeLayout makeCachedVertexAttributeLayout(
    GLuint location,
    const GLVertexAttributeState& attr,
    const ResolvedVertexAttrib& resolved,
    GLuint divisor)
{
    GLVertexArrayCachedAttributeLayout layout;
    layout.location = location;
    layout.bufferName = resolved.bufferName;
    layout.stride = resolved.stride;
    layout.offset = resolved.offset;
    layout.divisor = divisor;
    layout.glType = attr.type;
    layout.glComponentCount = attr.size;
    layout.glNormalized = attr.normalized;
    layout.glIsInteger = attr.integer;
    return layout;
}

static GLVertexArrayCachedLayout buildVertexArrayCachedLayout(
    const GLVertexArrayObject& vao,
    std::uint64_t cacheIndex,
    bool divisorAware,
    bool forceAttributeZeroPrimary,
    bool minimizePrimaryBaseOffset)
{
    GLVertexArrayCachedLayout cache;
    cache.valid = true;
    cache.generation = vao.attribGeneration;
    if (vao.attributes.empty()) {
        cache.phase2LayoutFingerprintCacheIndex = cacheIndex;
        cache.phase2LayoutFingerprint =
            phase2PlanBuildCachedVaoLayoutFingerprint(cache, cacheIndex);
        cache.phase2LayoutFingerprintValid = true;
        return cache;
    }

    std::size_t primaryIdx = 0;
    bool foundEnabledAttrib = false;
    for (std::size_t ai = 0; ai < vao.attributes.size(); ++ai) {
        if (vao.attributes[ai].enabled) {
            if (!forceAttributeZeroPrimary) {
                primaryIdx = ai;
            }
            foundEnabledAttrib = true;
            break;
        }
    }

    const auto& primaryAttr = vao.attributes[primaryIdx];
    const auto primaryResolved = resolveVertexAttrib(primaryAttr, vao);
    cache.hasEnabledAttributes = foundEnabledAttrib;
    cache.primaryAttributeIndex = primaryIdx;
    cache.primaryBufferName = primaryResolved.bufferName;
    cache.primaryStride = primaryResolved.stride;
    cache.primaryBaseOffset = primaryResolved.offset;

    if (!foundEnabledAttrib) {
        cache.phase2LayoutFingerprintCacheIndex = cacheIndex;
        cache.phase2LayoutFingerprint =
            phase2PlanBuildCachedVaoLayoutFingerprint(cache, cacheIndex);
        cache.phase2LayoutFingerprintValid = true;
        return cache;
    }

    if (minimizePrimaryBaseOffset) {
        for (std::size_t ai = 0; ai < vao.attributes.size(); ++ai) {
            const auto& attr = vao.attributes[ai];
            if (!attr.enabled) continue;
            const auto attrRes = resolveVertexAttrib(attr, vao);
            const GLuint attrDivisor = effectiveVertexAttribDivisor(attr, vao);
            if (attrRes.bufferName == cache.primaryBufferName &&
                attrRes.stride == cache.primaryStride &&
                (!divisorAware || attrDivisor == 0)) {
                cache.primaryBaseOffset =
                    std::min(cache.primaryBaseOffset, attrRes.offset);
            }
        }
    }

    for (std::size_t ai = 0; ai < vao.attributes.size(); ++ai) {
        const auto& attr = vao.attributes[ai];
        if (!attr.enabled) continue;

        const auto attrRes = resolveVertexAttrib(attr, vao);
        const GLuint attrDivisor = effectiveVertexAttribDivisor(attr, vao);
        auto layout = makeCachedVertexAttributeLayout(
            static_cast<GLuint>(ai), attr, attrRes, attrDivisor);

        if (attrRes.bufferName == cache.primaryBufferName &&
            attrRes.stride == cache.primaryStride &&
            (!divisorAware || attrDivisor == 0)) {
            cache.primaryAttributes.push_back(layout);
            continue;
        }

        const GLuint groupDivisor = divisorAware ? attrDivisor : 0;
        auto groupIt = std::find_if(
            cache.extraGroups.begin(), cache.extraGroups.end(),
            [&](const GLVertexArrayCachedLayoutGroup& group) {
                return group.bufferName == attrRes.bufferName &&
                       group.stride == attrRes.stride &&
                       group.divisor == groupDivisor;
            });
        if (groupIt == cache.extraGroups.end()) {
            GLVertexArrayCachedLayoutGroup group;
            group.bufferName = attrRes.bufferName;
            group.stride = attrRes.stride;
            group.divisor = groupDivisor;
            cache.extraGroups.push_back(std::move(group));
            groupIt = std::prev(cache.extraGroups.end());
        }
        groupIt->attributes.push_back(std::move(layout));
    }

    cache.phase2LayoutFingerprintCacheIndex = cacheIndex;
    cache.phase2LayoutFingerprint =
        phase2PlanBuildCachedVaoLayoutFingerprint(cache, cacheIndex);
    cache.phase2LayoutFingerprintValid = true;
    return cache;
}

static const GLVertexArrayCachedLayout& cachedVertexArrayLayout(
    GLVertexArrayObject& vao,
    bool divisorAware,
    bool* cacheHit = nullptr,
    bool forceAttributeZeroPrimary = false,
    bool minimizePrimaryBaseOffset = true,
    ColdPathDiagnosticProfile* coldProfile = nullptr)
{
    ColdPathDiagnosticScope coldScope(
        coldProfile, ColdPathDiagnosticBucket::ProgramVaoFboLayoutCache);
    std::size_t index = kPlainVaoLayoutCacheIndex;
    if (divisorAware && forceAttributeZeroPrimary) {
        index = kIndexedDivisorAwareVaoLayoutCacheIndex;
    } else if (!divisorAware && !minimizePrimaryBaseOffset) {
        index = kPlainNoMinVaoLayoutCacheIndex;
    } else if (divisorAware) {
        index = kDivisorAwareVaoLayoutCacheIndex;
    }
    auto& cache = vao.cachedLayouts[index];
    const bool hit = cache.valid && cache.generation == vao.attribGeneration;
    if (!hit) {
        cache = buildVertexArrayCachedLayout(
            vao, index, divisorAware, forceAttributeZeroPrimary,
            minimizePrimaryBaseOffset);
    }
    if (cacheHit != nullptr) {
        *cacheHit = hit;
    }
    return cache;
}

static TranslatedDrawInfo::VertexAttributeLayout makeTranslatedLayout(
    const GLVertexArrayCachedAttributeLayout& cached)
{
    TranslatedDrawInfo::VertexAttributeLayout layout;
    layout.location = cached.location;
    layout.offset = cached.offset;
    layout.glType = cached.glType;
    layout.glComponentCount = cached.glComponentCount;
    layout.glNormalized = cached.glNormalized;
    layout.glIsInteger = cached.glIsInteger;
    return layout;
}

static void applyCachedVertexArrayLayout(
    const GLVertexArrayCachedLayout& cache,
    GLObjectStore& objects,
    TranslatedDrawInfo& tdi,
    GLint first,
    bool offsetExtraBuffersByFirst,
    bool keepEmptyExtraBufferGroups,
    ColdPathDiagnosticProfile* coldProfile = nullptr)
{
    ColdPathDiagnosticScope coldScope(
        coldProfile, ColdPathDiagnosticBucket::ProgramVaoFboLayoutApply);
    const bool tdiLayoutWasEmpty =
        tdi.vertexAttributeLayouts.empty() && tdi.extraVertexBuffers.empty();
    bool skippedExtraGroup = false;
    tdi.vertexAttributeLayouts.reserve(
        tdi.vertexAttributeLayouts.size() + cache.primaryAttributes.size());
    tdi.extraVertexBuffers.reserve(
        tdi.extraVertexBuffers.size() + cache.extraGroups.size());

    for (const auto& cached : cache.primaryAttributes) {
        auto layout = makeTranslatedLayout(cached);
        layout.offset = cached.offset - cache.primaryBaseOffset;
        tdi.vertexAttributeLayouts.push_back(layout);
    }

    for (const auto& group : cache.extraGroups) {
        GLBufferObject* extraVbo = group.bufferName != 0
            ? objects.buffers().get(group.bufferName)
            : nullptr;
        const bool hasExtraBytes =
            extraVbo != nullptr && !extraVbo->shadowBytes.empty();
        if (!keepEmptyExtraBufferGroups && !hasExtraBytes) {
            skippedExtraGroup = true;
            continue;
        }

        TranslatedDrawInfo::ExtraVertexBuffer evb;
        evb.stride = group.stride;
        evb.divisor = group.divisor;
        if (hasExtraBytes) {
            evb.data = extraVbo->shadowBytes.data();
            evb.byteCount = extraVbo->shadowBytes.size();
            evb.metalBuffer = extraVbo->metalBuffer;
            evb.metalBufferOffset = offsetExtraBuffersByFirst
                && group.divisor == 0
                ? static_cast<std::size_t>(first) * group.stride
                : 0;
            evb.glBuffer = group.bufferName;
        }
        evb.attributes.reserve(group.attributes.size());
        for (const auto& cachedAttr : group.attributes) {
            evb.attributes.push_back(makeTranslatedLayout(cachedAttr));
        }
        tdi.extraVertexBuffers.push_back(std::move(evb));
    }
    if (tdiLayoutWasEmpty && !skippedExtraGroup) {
        phase2PlanSetVaoLayoutSegmentHashFromCache(
            tdi, cache, "apply_cached_vao_layout");
    } else {
        phase2PlanInvalidateVaoLayoutSegmentHash(tdi);
    }
}

static bool programUsesDrawArrayVertexBaseBuiltins(
    const GLProgramObject& program)
{
    for (const auto& input : program.resourceInputs) {
        if (input.name == "gl_VertexID" ||
            input.name == "gl_BaseVertex") {
            return true;
        }
    }
    return false;
}

static bool programUsesResourceInput(const GLProgramObject& program,
                                     std::string_view name)
{
    for (const auto& input : program.resourceInputs) {
        if (input.name == name) {
            return true;
        }
    }
    return false;
}

static bool shaderSourceUsesToken(const std::string& source, const char* token)
{
    std::size_t pos = 0;
    while ((pos = source.find(token, pos)) != std::string::npos) {
        if (tokenAt(source, pos, token)) {
            return true;
        }
        pos += std::strlen(token);
    }
    return false;
}

static bool programAttachedShaderSourceUsesToken(
    const GLProgramObject& program,
    GLObjectStore& objects,
    const char* token)
{
    for (GLuint shaderId : program.attachedShaders) {
        const GLShaderObject* shader = objects.shaders().get(shaderId);
        if (shader != nullptr &&
            shaderSourceUsesToken(shader->source, token)) {
            return true;
        }
    }
    return false;
}

static bool programUsesDrawOrPrimitiveIDDependency(
    const GLProgramObject& program,
    GLObjectStore& objects)
{
    return program.shaderDrawIDUniformLocation >= 0 ||
           programUsesResourceInput(program, "gl_DrawID") ||
           programUsesResourceInput(program, "gl_DrawIDARB") ||
           programUsesResourceInput(program, "gl_PrimitiveID") ||
           programUsesResourceInput(program, "gl_PrimitiveIDIn") ||
           programAttachedShaderSourceUsesToken(program, objects, "gl_DrawID") ||
           programAttachedShaderSourceUsesToken(program, objects, "gl_DrawIDARB") ||
           programAttachedShaderSourceUsesToken(program, objects, "gl_PrimitiveID") ||
           programAttachedShaderSourceUsesToken(program, objects, "gl_PrimitiveIDIn");
}

static bool isCoalescibleArrayPrimitiveMode(GLenum mode)
{
    return mode == GL_POINTS ||
           mode == GL_LINES ||
           mode == GL_TRIANGLES;
}

static GLint shaderVertexInputComponentCount(GLenum type) {
    switch (type) {
        case GL_FLOAT:
        case GL_INT:
        case GL_UNSIGNED_INT:
        case GL_DOUBLE:
            return 1;
        case GL_FLOAT_VEC2:
        case GL_INT_VEC2:
        case GL_UNSIGNED_INT_VEC2:
        case GL_DOUBLE_VEC2:
            return 2;
        case GL_FLOAT_VEC3:
        case GL_INT_VEC3:
        case GL_UNSIGNED_INT_VEC3:
        case GL_DOUBLE_VEC3:
            return 3;
        case GL_FLOAT_VEC4:
        case GL_INT_VEC4:
        case GL_UNSIGNED_INT_VEC4:
        case GL_DOUBLE_VEC4:
            return 4;
        default:
            return 4;
    }
}

static bool shaderVertexInputIsSignedInteger(GLenum type) {
    return type == GL_INT ||
           type == GL_INT_VEC2 ||
           type == GL_INT_VEC3 ||
           type == GL_INT_VEC4;
}

static bool shaderVertexInputIsUnsignedInteger(GLenum type) {
    return type == GL_UNSIGNED_INT ||
           type == GL_UNSIGNED_INT_VEC2 ||
           type == GL_UNSIGNED_INT_VEC3 ||
           type == GL_UNSIGNED_INT_VEC4;
}

static bool translatedDrawHasVertexLayoutAt(
    const TranslatedDrawInfo& tdi,
    GLuint location)
{
    for (const auto& layout : tdi.vertexAttributeLayouts) {
        if (layout.location == location) return true;
    }
    for (const auto& evb : tdi.extraVertexBuffers) {
        for (const auto& layout : evb.attributes) {
            if (layout.location == location) return true;
        }
    }
    return false;
}

static void appendCurrentGenericVertexAttributes(
    TranslatedDrawInfo& tdi,
    const GLVertexArrayObject* vao,
    ColdPathDiagnosticProfile* coldProfile = nullptr)
{
    ColdPathDiagnosticScope coldScope(
        coldProfile, ColdPathDiagnosticBucket::ProgramVaoFboGenericAttributes);
    bool appended = false;
    if (tdi.vertexReflection == nullptr || vao == nullptr) {
        return;
    }

    TranslatedDrawInfo::ExtraVertexBuffer* currentBuffer = nullptr;
    for (const auto& input : tdi.vertexReflection->vertexInputs) {
        if (input.sourceLocation >= vao->attributes.size()) {
            continue;
        }

        const auto& attr = vao->attributes[input.sourceLocation];
        if (attr.enabled || input.containsFp64) {
            continue;
        }
        if (translatedDrawHasVertexLayoutAt(tdi, input.location)) {
            continue;
        }

        if (currentBuffer == nullptr) {
            tdi.extraVertexBuffers.emplace_back();
            currentBuffer = &tdi.extraVertexBuffers.back();
            currentBuffer->constantStep = true;
            currentBuffer->stride = 16;
            currentBuffer->divisor = 0;
        }

        const std::size_t alignedOffset =
            (currentBuffer->ownedData.size() + 15u) & ~std::size_t(15u);
        currentBuffer->ownedData.resize(alignedOffset + 16u, 0u);

        TranslatedDrawInfo::VertexAttributeLayout layout;
        layout.location = input.location;
        layout.offset = alignedOffset;
        layout.glComponentCount =
            std::max<GLint>(1, std::min<GLint>(4, shaderVertexInputComponentCount(input.type)));
        layout.glNormalized = GL_FALSE;

        std::uint8_t* dst = currentBuffer->ownedData.data() + alignedOffset;
        if (shaderVertexInputIsSignedInteger(input.type)) {
            layout.glType = GL_INT;
            layout.glIsInteger = true;
            auto* values = reinterpret_cast<GLint*>(dst);
            for (int i = 0; i < 4; ++i) {
                values[i] = attr.immediateInt[i];
            }
        } else if (shaderVertexInputIsUnsignedInteger(input.type)) {
            layout.glType = GL_UNSIGNED_INT;
            layout.glIsInteger = true;
            auto* values = reinterpret_cast<GLuint*>(dst);
            for (int i = 0; i < 4; ++i) {
                values[i] = attr.immediateUInt[i];
            }
        } else {
            layout.glType = GL_FLOAT;
            layout.glIsInteger = false;
            auto* values = reinterpret_cast<float*>(dst);
            for (int i = 0; i < 4; ++i) {
                values[i] = static_cast<float>(attr.immediateDouble[i]);
            }
        }
        currentBuffer->attributes.push_back(layout);
        currentBuffer->byteCount = currentBuffer->ownedData.size();
        currentBuffer->stride = currentBuffer->byteCount;
        appended = true;
    }
    if (appended) {
        phase2PlanInvalidateVaoLayoutSegmentHash(tdi);
    }
}

SolidColorDrawSetup buildSolidColorDrawSetup(GLStateTracker& state,
                                             GLObjectStore& objects,
                                             GLenum mode,
                                             const char* debugLabel,
                                             GLenum fragmentShadingRate) {
    SolidColorDrawSetup setup;

    if (mode != GL_TRIANGLES && mode != GL_TRIANGLE_STRIP && mode != GL_TRIANGLE_FAN) {
        return setup;
    }

    const GLuint vaoName = state.boundVertexArray();
    if (vaoName == 0) {
        return setup;
    }
    GLVertexArrayObject* vao = objects.vertexArrays().get(vaoName);
    if (vao == nullptr) {
        return setup;
    }
    if (vao->attributes.empty()) {
        objects.initializeVertexArray(*vao);
        if (vao->attributes.empty()) {
            return setup;
        }
    }

    const GLuint programName = state.currentProgram();
    if (programName == 0) {
        return setup;
    }
    GLProgramObject* program = objects.programs().get(programName);
    if (program == nullptr || !program->linked) {
        return setup;
    }

    const auto& positionAttr = vao->attributes[0];
    if (!positionAttr.enabled || positionAttr.type != GL_FLOAT || positionAttr.size != 3) {
        return setup;
    }
    // Resolve through binding point for GL 4.3+ separated vertex format,
    // falling back to legacy attribute fields for classic glVertexAttribPointer.
    ResolvedVertexAttrib resolved = resolveVertexAttrib(positionAttr, *vao);
    if (resolved.bufferName == 0) {
        return setup;
    }
    GLBufferObject* vbo = objects.buffers().get(resolved.bufferName);
    if (vbo == nullptr || vbo->shadowBytes.empty()) {
        return setup;
    }
    const std::size_t positionStride = resolved.stride;
    if (resolved.offset > vbo->shadowBytes.size()) {
        return setup;
    }

    setup.info.mode = mode;
    setup.info.positions = vbo->shadowBytes.data() + resolved.offset;
    setup.info.positionByteCount = vbo->shadowBytes.size() - resolved.offset;
    setup.info.positionStride = positionStride;
    setup.info.positionComponents = 3;
    setup.positionShadow = vbo->shadowBytes.data();
    setup.positionShadowSize = vbo->shadowBytes.size();

    // Default to opaque white, then override from the "uColor" uniform if the
    // linked program has one. This mirrors what the hand-written fragment
    // shader expects at fragment buffer index 0.
    setup.info.uniformColor[0] = 1.0f;
    setup.info.uniformColor[1] = 1.0f;
    setup.info.uniformColor[2] = 1.0f;
    setup.info.uniformColor[3] = 1.0f;
    for (const auto& uniform : program->uniforms) {
        if (uniform.name == "uColor" && uniform.type == GL_FLOAT_VEC4 && uniform.location >= 0) {
            auto it = program->uniformValues.find(uniform.location);
            if (it != program->uniformValues.end() && it->second.floats.size() >= 4) {
                setup.info.uniformColor[0] = it->second.floats[0];
                setup.info.uniformColor[1] = it->second.floats[1];
                setup.info.uniformColor[2] = it->second.floats[2];
                setup.info.uniformColor[3] = it->second.floats[3];
            }
            break;
        }
    }

    setup.info.depthTestEnabled = state.isEnabled(GL_DEPTH_TEST);
    setup.info.depthFunc = state.depthState().func;
    setup.info.depthWriteMask = (state.depthState().writeMask != GL_FALSE);
    setup.info.cullFaceEnabled = state.isEnabled(GL_CULL_FACE);
    setup.info.cullFaceMode = state.rasterState().cullFaceMode;
    setup.info.frontFace = state.rasterState().frontFace;
    setup.info.wireframe = (state.rasterState().polygonFillMode == GL_LINE);
    setup.info.sampleMask =
        state.isEnabled(GL_SAMPLE_MASK)
            ? static_cast<std::uint32_t>(state.sampleMask(0))
            : 0xFFFFFFFFu;
    setup.info.fragmentShadingRate = fragmentShadingRate;
    // Sprint 7 Phase 1 #11 (CKPT57): stencil state for solid-color path.
    {
        const auto& gs = state.stencilState();
        setup.info.stencilTestEnabled = state.isEnabled(GL_STENCIL_TEST);
        setup.info.stencilFrontFunc = gs.front.func;
        setup.info.stencilFrontRef = gs.front.ref;
        setup.info.stencilFrontValueMask = gs.front.valueMask;
        setup.info.stencilFrontFail = gs.front.fail;
        setup.info.stencilFrontDepthFail = gs.front.depthFail;
        setup.info.stencilFrontDepthPass = gs.front.depthPass;
        setup.info.stencilFrontWriteMask = gs.front.writeMask;
        setup.info.stencilBackFunc = gs.back.func;
        setup.info.stencilBackRef = gs.back.ref;
        setup.info.stencilBackValueMask = gs.back.valueMask;
        setup.info.stencilBackFail = gs.back.fail;
        setup.info.stencilBackDepthFail = gs.back.depthFail;
        setup.info.stencilBackDepthPass = gs.back.depthPass;
        setup.info.stencilBackWriteMask = gs.back.writeMask;
    }
    if (debugLabel != nullptr) {
        setup.info.debugLabel = debugLabel;
    }

    setup.vertexArray = vao;
    setup.program = program;
    setup.ok = true;
    return setup;
}

}  // namespace

namespace {
// GL 4.6 §11.3.1: when the program has a geometry shader, the draw
// call's primitive mode must match the GS's input primitive type.
// Returns false + GL_INVALID_OPERATION pushed by the caller when the
// mode is incompatible. Programs without a GS always return true
// (mode validation for those lives in the standard draw-mode check).
bool isDrawModeCompatibleWithGs(GLenum drawMode, GLenum gsInputTopo) {
    switch (gsInputTopo) {
        case GL_POINTS:
            return drawMode == GL_POINTS;
        case GL_LINES:
            return drawMode == GL_LINES || drawMode == GL_LINE_STRIP ||
                   drawMode == GL_LINE_LOOP;
        case GL_LINES_ADJACENCY:
            return drawMode == GL_LINES_ADJACENCY ||
                   drawMode == GL_LINE_STRIP_ADJACENCY;
        case GL_TRIANGLES:
            return drawMode == GL_TRIANGLES || drawMode == GL_TRIANGLE_STRIP ||
                   drawMode == GL_TRIANGLE_FAN;
        case GL_TRIANGLES_ADJACENCY:
            return drawMode == GL_TRIANGLES_ADJACENCY ||
                   drawMode == GL_TRIANGLE_STRIP_ADJACENCY;
        default:
            return true;   // unknown GS topology: don't reject
    }
}

bool dcr4eDrawModeUsesAdjacency(GLenum mode) {
    switch (mode) {
        case GL_LINES_ADJACENCY:
        case GL_LINE_STRIP_ADJACENCY:
        case GL_TRIANGLES_ADJACENCY:
        case GL_TRIANGLE_STRIP_ADJACENCY:
            return true;
        default:
            return false;
    }
}

bool dcr4eGeometrySpirvUsesStreams(const std::vector<std::uint32_t>& spirv) {
    constexpr std::uint16_t kOpDecorate = 71;
    constexpr std::uint16_t kOpMemberDecorate = 72;
    constexpr std::uint16_t kOpEmitStreamVertex = 220;
    constexpr std::uint16_t kOpEndStreamPrimitive = 221;
    constexpr std::uint32_t kDecorationStream = 29;
    for (std::size_t i = spirv.size() >= 5 ? 5u : 0u; i < spirv.size();) {
        const std::uint32_t word = spirv[i];
        const std::uint16_t op = static_cast<std::uint16_t>(word & 0xFFFFu);
        const std::uint16_t wc = static_cast<std::uint16_t>(word >> 16);
        if (wc == 0 || i + wc > spirv.size()) {
            break;
        }
        if (op == kOpEmitStreamVertex || op == kOpEndStreamPrimitive) {
            return true;
        }
        if (op == kOpDecorate && wc >= 3 && spirv[i + 2] == kDecorationStream) {
            return true;
        }
        if (op == kOpMemberDecorate && wc >= 4 && spirv[i + 3] == kDecorationStream) {
            return true;
        }
        i += wc;
    }
    return false;
}

bool dcr4eRequiresExactCpuGsNoLegacyFallback(
    const GLProgramObject* program,
    GLenum mode,
    bool transformFeedbackActive) {
    if (program == nullptr || !program->geometryEmulated) {
        return false;
    }
    return transformFeedbackActive ||
           dcr4eDrawModeUsesAdjacency(mode) ||
           dcr4eGeometrySpirvUsesStreams(program->geometrySpirv);
}
}  // namespace

// Defined after the anonymous namespace with populateTranslatedDraw-
// FixedFunctionState / computeStageUniformLayout / buildStageUniform-
// Buffer so those helpers are visible.
GLProgramObject* GLContext::Impl::resolvePipelineEmulationProgram(
    GLuint currentProgramName, GLuint& outProgramName)
{
    auto clearPipelineEmulationUniforms = [](GLProgramObject* program) {
        if (program == nullptr) return;
        for (std::size_t stage = 0; stage < program->pipelineEmulationStageUniforms.size(); ++stage) {
            program->pipelineEmulationStageUniforms[stage].clear();
            program->pipelineEmulationStageUniformValues[stage].clear();
            program->pipelineEmulationStageUniformsValid[stage] = false;
        }
    };
    auto invalidateGsPassThroughFragmentCache = [](GLProgramObject* program) {
        if (program == nullptr) return;
        for (auto& entry : program->gsPassThroughPipelineStateCache) {
            if (entry.second != nullptr) {
                CFRelease(entry.second);
            }
        }
        program->gsPassThroughPipelineStateCache.clear();
        releaseRetainedMetalObject(program->gsPassThroughPipelineState);
        program->gsPassThroughPipelineState = nullptr;
        program->gsPassThroughPipelineColorFormat = 0;
        releaseRetainedMetalObject(program->gsPassThroughFragmentFunction);
        program->gsPassThroughFragmentFunction = nullptr;
        program->gsPassThroughFragmentMSL.clear();
        program->gsPassThroughFragmentMslUsesArgumentBuffer = false;
        program->gsPassThroughFragmentMSLActive = false;
        program->gsPassThroughFragmentMSLPrimIdLoc = 0;
    };
    // Fast path: a current program is bound (glUseProgram), use it
    // directly. Don't touch pipeline state even if a pipeline is
    // also bound — GL 4.6 §7.3 says the current program shadows
    // any pipeline binding.
    if (currentProgramName != 0) {
        outProgramName = currentProgramName;
        GLProgramObject* program = objects->programs().get(currentProgramName);
        clearPipelineEmulationUniforms(program);
        return program;
    }
    // No current program; check the pipeline for a GS program.
    const GLuint pipelineName = state->currentProgramPipeline();
    if (pipelineName == 0) return nullptr;
    GLProgramPipelineObject* ppo = objects->programPipelines().get(pipelineName);
    if (ppo == nullptr || ppo->geometryProgram == 0) return nullptr;
    GLProgramObject* gsProg = objects->programs().get(ppo->geometryProgram);
    if (gsProg == nullptr || !gsProg->geometryEmulated) return nullptr;
    clearPipelineEmulationUniforms(gsProg);
    auto setPipelineEmulationStageUniforms = [&](int stageIndex,
                                                 const GLProgramObject* source) {
        if (source == nullptr || stageIndex < 0 || stageIndex >= 6) return;
        const std::size_t stage = static_cast<std::size_t>(stageIndex);
        gsProg->pipelineEmulationStageUniforms[stage] = source->uniforms;
        gsProg->pipelineEmulationStageUniformValues[stage] = source->uniformValues;
        gsProg->pipelineEmulationStageUniformsValid[stage] = true;

        // resolveDrawProgram() may already have spliced the pipeline's
        // fragment uniforms onto the VS container. Subroutine dispatch
        // uniforms are intentionally named the same in every separable
        // stage, so recover each stage's dispatch value from its own
        // glUniformSubroutinesuiv selection state before CPU emulation
        // snapshots consume the uniforms.
        auto stripBracketZeroSuffix = [](const std::string& name) {
            if (name.size() >= 3 &&
                name.compare(name.size() - 3, 3, "[0]") == 0) {
                return name.substr(0, name.size() - 3);
            }
            return name;
        };
        auto dispatchKey = [](const std::string& baseName,
                              GLint element,
                              GLint elementCount) {
            if (elementCount <= 1) return baseName;
            return baseName + "_" + std::to_string(element);
        };
        const auto& subroutineUniforms =
            source->resourceSubroutineUniforms[stageIndex];
        const auto& selections =
            source->currentSubroutineSelections[stageIndex];
        for (const auto& uniform : subroutineUniforms) {
            if (uniform.location < 0) continue;
            const GLint elemCount = std::max<GLint>(1, uniform.arraySize);
            const std::string baseName = stripBracketZeroSuffix(uniform.name);
            for (GLint elem = 0; elem < elemCount; ++elem) {
                const GLint loc = uniform.location + elem;
                GLuint selected = uniform.activeVariables.empty()
                    ? 0u
                    : static_cast<GLuint>(uniform.activeVariables.front());
                if (loc >= 0 && static_cast<std::size_t>(loc) < selections.size()) {
                    selected = selections[static_cast<std::size_t>(loc)];
                }

                std::size_t typeLocal = 0;
                for (std::size_t k = 0; k < uniform.activeVariables.size(); ++k) {
                    if (uniform.activeVariables[k] == static_cast<GLint>(selected)) {
                        typeLocal = k;
                        break;
                    }
                }

                const std::string key = dispatchKey(baseName, elem, elemCount);
                const auto locIt =
                    source->subroutineDispatchUniformLocations.find(key);
                if (locIt == source->subroutineDispatchUniformLocations.end()) {
                    continue;
                }
                const GLint dispatchLoc = locIt->second;
                const std::string synthName = "_appgl_sub_" + key;
                auto& stageUniformInfos =
                    gsProg->pipelineEmulationStageUniforms[stage];
                const bool hasDispatchUniform = std::any_of(
                    stageUniformInfos.begin(), stageUniformInfos.end(),
                    [&](const GLProgramUniformInfo& info) {
                        return info.location == dispatchLoc &&
                               info.name == synthName;
                    });
                if (!hasDispatchUniform) {
                    GLProgramUniformInfo info;
                    info.name = synthName;
                    info.type = GL_UNSIGNED_INT;
                    info.arraySize = 1;
                    info.location = dispatchLoc;
                    stageUniformInfos.push_back(std::move(info));
                }

                auto& value =
                    gsProg->pipelineEmulationStageUniformValues[stage][dispatchLoc];
                value.type = GL_UNSIGNED_INT;
                value.arraySize = 1;
                value.uints.assign(1, static_cast<GLuint>(typeLocal));
                value.ints.clear();
                value.floats.clear();
                value.doubles.clear();
                value.df64TransportWords.clear();
            }
        }
    };
    // Copy the VS program's vertexSpirv onto the GS program so
    // emulateGeometryDraw's pre-pass runs against the pipeline's
    // actual VS. Idempotent when the same pipeline draws multiple
    // times — we overwrite to stay in sync even if the pipeline's
    // stages were swapped via useProgramStages between draws.
    GLProgramObject* vsProg = nullptr;
    if (ppo->vertexProgram != 0) {
        vsProg = objects->programs().get(ppo->vertexProgram);
        if (vsProg != nullptr) {
            gsProg->vertexSpirv = vsProg->vertexSpirv;
            gsProg->vertexSpirvEntryPoint = vsProg->vertexSpirvEntryPoint;
            gsProg->vertexSpirvSpecializationConstants =
                vsProg->vertexSpirvSpecializationConstants;
            gsProg->vertexReflection = vsProg->vertexReflection;
            // Carry the VS reflection so the GS/tess CPU emulators
            // see the pipeline vertex stage's actual resource layout.
            // Leaving vertexMSL alone: the GS emulator builds a synth
            // VS from the EmulatedDraw, not the VS's own MSL.
        }
    }
    // Copy the FS program's fragmentMSL + reflection for the
    // encoder's pipeline build. When absent (FS program missing
    // or not linked), encodeEmulatedGsDraw will fail and the draw
    // falls back — same behaviour as before this patch.
    GLProgramObject* fsProg = nullptr;
    if (ppo->fragmentProgram != 0) {
        fsProg = objects->programs().get(ppo->fragmentProgram);
        if (fsProg != nullptr) {
            const bool fragmentStageChanged =
                gsProg->pipelineEmulationFragmentProgram != ppo->fragmentProgram ||
                gsProg->fragmentMSL != fsProg->fragmentMSL;
            gsProg->fragmentMSL = fsProg->fragmentMSL;
            gsProg->fragmentMslUsesArgumentBuffer =
                fsProg->fragmentMslUsesArgumentBuffer;
            gsProg->fragmentReflection = fsProg->fragmentReflection;
            gsProg->pipelineEmulationFragmentProgram = ppo->fragmentProgram;
            if (fragmentStageChanged) {
                invalidateGsPassThroughFragmentCache(gsProg);
            }
        }
    } else if (gsProg->pipelineEmulationFragmentProgram != 0 || !gsProg->fragmentMSL.empty()) {
        gsProg->fragmentMSL.clear();
        gsProg->fragmentMslUsesArgumentBuffer = false;
        gsProg->fragmentReflection = ShaderReflection{};
        gsProg->pipelineEmulationFragmentProgram = 0;
        invalidateGsPassThroughFragmentCache(gsProg);
    }
    GLProgramObject* tcsProg = nullptr;
    GLProgramObject* tesProg = nullptr;
    bool hasPipelineTessellationStages = false;
    if (ppo->tessControlProgram != 0 && ppo->tessEvalProgram != 0) {
        tcsProg = objects->programs().get(ppo->tessControlProgram);
        tesProg = objects->programs().get(ppo->tessEvalProgram);
        if (tcsProg != nullptr && tesProg != nullptr) {
            const bool tcsSpirvChanged =
                gsProg->tessControlSpirv != tcsProg->tessControlSpirv;
            const bool tesSpirvChanged =
                gsProg->tessEvalSpirv != tesProg->tessEvalSpirv;
            gsProg->hasTessellation = true;
            gsProg->tessControlSpirv = tcsProg->tessControlSpirv;
            gsProg->tessEvalSpirv = tesProg->tessEvalSpirv;
            if (tcsSpirvChanged) {
                gsProg->tessControlParsedModule.reset();
            }
            if (tesSpirvChanged) {
                gsProg->tessEvalParsedModule.reset();
            }
            gsProg->tessControlReflection = tcsProg->tessControlReflection;
            gsProg->tessEvalAsComputeReflection = tesProg->tessEvalAsComputeReflection;
            gsProg->tessellationEmulated = tesProg->tessellationEmulated;
            gsProg->tessellationInterpreted = tesProg->tessellationInterpreted;
            gsProg->tessControlInterpreted = tcsProg->tessControlInterpreted;
            gsProg->tessControlOutputVertices = tcsProg->tessControlOutputVertices;
            gsProg->tessGenMode = tesProg->tessGenMode;
            gsProg->tessGenSpacing = tesProg->tessGenSpacing;
            gsProg->tessGenVertexOrder = tesProg->tessGenVertexOrder;
            gsProg->tessGenPointMode = tesProg->tessGenPointMode;
            gsProg->tessVaryings = tesProg->tessVaryings;
            for (int i = 0; i < 4; ++i) {
                gsProg->tessPositionMapping[i] = tesProg->tessPositionMapping[i];
                gsProg->tessPositionScale[i] = tesProg->tessPositionScale[i];
                gsProg->tessPositionOffset[i] = tesProg->tessPositionOffset[i];
                gsProg->tessPositionConstant[i] = tesProg->tessPositionConstant[i];
            }
            (void)appgl::detectTessellationEmulatable(*gsProg);
            hasPipelineTessellationStages = true;
        }
    }
    if (!hasPipelineTessellationStages) {
        gsProg->hasTessellation = false;
        gsProg->tessControlSpirv.clear();
        gsProg->tessEvalSpirv.clear();
        gsProg->tessControlParsedModule.reset();
        gsProg->tessEvalParsedModule.reset();
        gsProg->tessellationEmulated = false;
        gsProg->tessellationInterpreted = false;
        gsProg->tessControlInterpreted = false;
        gsProg->tessControlOutputVertices = 0;
        gsProg->tessVaryings.clear();
    }
    setPipelineEmulationStageUniforms(0, vsProg);
    setPipelineEmulationStageUniforms(1, tcsProg);
    setPipelineEmulationStageUniforms(2, tesProg);
    setPipelineEmulationStageUniforms(3, gsProg);
    setPipelineEmulationStageUniforms(4, fsProg);
    gsProg->uniformLayoutComputed = false;
    outProgramName = ppo->geometryProgram;
    return gsProg;
}

namespace {

constexpr GLbitfield kAppGLPipelineStageMask =
    GL_VERTEX_SHADER_BIT |
    GL_TESS_CONTROL_SHADER_BIT |
    GL_TESS_EVALUATION_SHADER_BIT |
    GL_GEOMETRY_SHADER_BIT |
    GL_FRAGMENT_SHADER_BIT |
    GL_COMPUTE_SHADER_BIT;

bool pipelineStageSelectionsMatchExecutables(
    GLObjectStore& objects,
    const GLProgramPipelineObject& ppo,
    bool requireLinkedSeparable) {
    std::array<std::pair<GLuint, GLbitfield>, 6> assigned{};
    std::size_t assignedCount = 0;
    auto addStage = [&](GLuint program, GLbitfield stageBit) {
        if (program == 0) {
            return;
        }
        for (std::size_t i = 0; i < assignedCount; ++i) {
            if (assigned[i].first == program) {
                assigned[i].second |= stageBit;
                return;
            }
        }
        if (assignedCount < assigned.size()) {
            assigned[assignedCount++] = {program, stageBit};
        }
    };

    addStage(ppo.vertexProgram, GL_VERTEX_SHADER_BIT);
    addStage(ppo.tessControlProgram, GL_TESS_CONTROL_SHADER_BIT);
    addStage(ppo.tessEvalProgram, GL_TESS_EVALUATION_SHADER_BIT);
    addStage(ppo.geometryProgram, GL_GEOMETRY_SHADER_BIT);
    addStage(ppo.fragmentProgram, GL_FRAGMENT_SHADER_BIT);
    addStage(ppo.computeProgram, GL_COMPUTE_SHADER_BIT);

    for (std::size_t i = 0; i < assignedCount; ++i) {
        const GLuint programName = assigned[i].first;
        const GLbitfield assignedStages = assigned[i].second;
        const GLProgramObject* program = objects.programs().get(programName);
        if (program == nullptr) {
            return false;
        }
        if (requireLinkedSeparable && (!program->linked || !program->separableLinked)) {
            return false;
        }
        const GLbitfield executableStages =
            program->linkedStageBits & kAppGLPipelineStageMask;
        if ((executableStages & ~assignedStages) != 0) {
            return false;
        }
    }
    return true;
}

} // namespace

bool GLContext::Impl::validateCurrentProgramPipelineForDraw() const {
    if (state == nullptr || objects == nullptr || state->currentProgram() != 0) {
        return true;
    }
    const GLuint pipelineName = state->currentProgramPipeline();
    if (pipelineName == 0) {
        return true;
    }
    const GLProgramPipelineObject* ppo =
        objects->programPipelines().get(pipelineName);
    if (ppo == nullptr) {
        return true;
    }
    if (!pipelineStageSelectionsMatchExecutables(*objects, *ppo, false)) {
        if (owner != nullptr) {
            owner->pushError(GL_INVALID_OPERATION);
        }
        return false;
    }
    return true;
}

GLProgramObject* GLContext::Impl::resolveDrawProgram(GLuint& programName) {
    // Fast path: a current program is bound (glUseProgram), use it
    // directly. GL 4.6 §7.3 says current program shadows any pipeline.
    if (programName != 0) {
        return objects->programs().get(programName);
    }
    // No current program — check for an active program pipeline and
    // synthesise a merged VS+FS container on the pipeline's VS.
    const GLuint pipelineName = state->currentProgramPipeline();
    if (pipelineName == 0) return nullptr;
    GLProgramPipelineObject* ppo = objects->programPipelines().get(pipelineName);
    if (ppo == nullptr || ppo->vertexProgram == 0) return nullptr;
    GLProgramObject* vsProg = objects->programs().get(ppo->vertexProgram);
    if (vsProg == nullptr || !vsProg->hasTranslatedPipeline) return nullptr;
    // Splice pipeline's FS MSL + reflection onto the VS container so
    // the downstream translated-draw path sees a single program with
    // both stages populated. Overwrite every call — cheap, keeps a
    // stage swap between draws in sync. The pipeline state cache is
    // keyed on the MSL contents so a real swap invalidates itself.
    auto clearPipelineFragmentAtomicCounters = [&]() {
        for (auto it = vsProg->resourceAtomicCounterBuffers.begin();
             it != vsProg->resourceAtomicCounterBuffers.end(); ) {
            it->referencedBy &= ~0x02u;
            if (it->referencedBy == 0) {
                it = vsProg->resourceAtomicCounterBuffers.erase(it);
            } else {
                ++it;
            }
        }
    };
    clearPipelineFragmentAtomicCounters();
    if (ppo->fragmentProgram != 0) {
        GLProgramObject* fsProg = objects->programs().get(ppo->fragmentProgram);
        if (fsProg != nullptr) {
            vsProg->fragmentMSL = fsProg->fragmentMSL;
            vsProg->fragmentMslUsesArgumentBuffer =
                fsProg->fragmentMslUsesArgumentBuffer;
            rewriteMslOutputLocationsForFragmentInputs(
                vsProg->vertexMSL, vsProg->fragmentMSL);
            vsProg->fragmentReflection = fsProg->fragmentReflection;
            for (const auto& fsUniform : fsProg->uniforms) {
                auto existing = std::find_if(
                    vsProg->uniforms.begin(), vsProg->uniforms.end(),
                    [&](const GLProgramUniformInfo& u) {
                        return u.name == fsUniform.name;
                    });
                if (existing != vsProg->uniforms.end()) {
                    *existing = fsUniform;
                } else {
                    vsProg->uniforms.push_back(fsUniform);
                }
                auto valueIt = fsProg->uniformValues.find(fsUniform.location);
                if (valueIt != fsProg->uniformValues.end()) {
                    vsProg->uniformValues[fsUniform.location] = valueIt->second;
                }
            }
            for (const auto& fsAc : fsProg->resourceAtomicCounterBuffers) {
                auto existing = std::find_if(
                    vsProg->resourceAtomicCounterBuffers.begin(),
                    vsProg->resourceAtomicCounterBuffers.end(),
                    [&](const GLProgramResourceEntry& entry) {
                        return entry.binding == fsAc.binding;
                    });
                if (existing != vsProg->resourceAtomicCounterBuffers.end()) {
                    existing->referencedBy |= (fsAc.referencedBy & 0x02u);
                    existing->offset = std::max(existing->offset, fsAc.offset);
                } else {
                    GLProgramResourceEntry merged = fsAc;
                    merged.referencedBy &= 0x02u;
                    if (merged.referencedBy != 0) {
                        vsProg->resourceAtomicCounterBuffers.push_back(
                            std::move(merged));
                    }
                }
            }
            // The translated-draw path caches uniform layouts on the
            // container program. If we merged a new FS shape we need
            // the layout recomputed, otherwise the vertex and fragment
            // uniform buffers get built from stale reflection.
            vsProg->uniformLayoutComputed = false;
        }
    } else {
        // No FS stage on the pipeline — clear the container's fragment
        // data so we don't accidentally render with a stale FS left
        // over from a previous pipeline that did have one.
        vsProg->fragmentMSL.clear();
        vsProg->fragmentMslUsesArgumentBuffer = false;
        vsProg->fragmentReflection = ShaderReflection{};
        vsProg->uniformLayoutComputed = false;
    }
    programName = ppo->vertexProgram;
    return vsProg;
}

GLProgramObject* GLContext::Impl::ensurePipelineTessSynthesizedProgram(
    GLProgramPipelineObject& ppo) {
    // β [metal-tess-TF] orchestrator. Mirrors the link-time tess flow
    // in linkProgram (~line 19101-19228) but sources SPIR-V from the
    // pipeline's separable VS+TCS+TES+FS programs and re-translates
    // with cross-stage info (siblingTesInputSpirv on TCS, force
    // VertexForTessellation on VS, force TessEvalAsCompute +
    // tesePatchVertices on TES). Step 2 lands translation only; the
    // probeTessellationPipeline call (which builds the Metal PSOs and
    // sets metalTessTier) lands in step 3, gated behind a
    // `frameGraph != nullptr` check there. Step-2-only return: a
    // synth program with all MSL strings set but metalTessTier still
    // None, so the caller's tier check fails and we fall through to
    // the existing CPU emulator path — same behaviour as today, just
    // with the translation step proven and instrumented.
    const GLuint vsName = ppo.vertexProgram;
    const GLuint tcsName = ppo.tessControlProgram;
    const GLuint tesName = ppo.tessEvalProgram;
    const GLuint fsName = ppo.fragmentProgram;

    if (tcsName == 0 || tesName == 0) {
        return nullptr;
    }

    const bool snapshotMatches =
        ppo.syntheticTessVsSnapshot == vsName &&
        ppo.syntheticTessTcsSnapshot == tcsName &&
        ppo.syntheticTessTesSnapshot == tesName &&
        ppo.syntheticTessFsSnapshot == fsName;
    if (snapshotMatches && ppo.syntheticTessProbeAttempted) {
        return ppo.syntheticTessProgram.get();
    }

    // Snapshot drift (or first visit). Release the previous synth's
    // retained Metal PSOs before reset — same fields linkProgram
    // releases on relink (~line 18594-18610). Without this, a
    // useProgramStages swap leaks one set of MTLComputePipelineStates
    // per swap.
    if (ppo.syntheticTessProgram != nullptr) {
        releaseProgramMetalResources(*ppo.syntheticTessProgram);
    }
    ppo.syntheticTessProgram.reset();
    ppo.syntheticTessVsSnapshot = vsName;
    ppo.syntheticTessTcsSnapshot = tcsName;
    ppo.syntheticTessTesSnapshot = tesName;
    ppo.syntheticTessFsSnapshot = fsName;
    ppo.syntheticTessProbeAttempted = true;

    GLProgramObject* vsProg = (vsName != 0) ? objects->programs().get(vsName) : nullptr;
    GLProgramObject* tcsProg = objects->programs().get(tcsName);
    GLProgramObject* tesProg = objects->programs().get(tesName);
    GLProgramObject* fsProg = (fsName != 0) ? objects->programs().get(fsName) : nullptr;

    if (tcsProg == nullptr || tesProg == nullptr) {
        if (detectorEnabled()) {
            std::fprintf(stderr,
                "APPGL_DETECTOR lift_pipe_synth abort_no_program "
                "tcs=%u(prog=%p) tes=%u(prog=%p)\n",
                tcsName, (void*)tcsProg, tesName, (void*)tesProg);
        }
        return nullptr;
    }
    if (tcsProg->tessControlSpirv.empty() || tesProg->tessEvalSpirv.empty()) {
        // Separable programs linked before β was introduced (or via a
        // path that didn't preserve SPIR-V). The translation can't
        // proceed; fall back to the CPU path.
        if (detectorEnabled()) {
            std::fprintf(stderr,
                "APPGL_DETECTOR lift_pipe_synth abort_no_spirv "
                "tcs=%u(words=%zu) tes=%u(words=%zu)\n",
                tcsName, tcsProg->tessControlSpirv.size(),
                tesName, tesProg->tessEvalSpirv.size());
        }
        return nullptr;
    }

    // Plumb TCS output_vertices into the TES-as-compute translation
    // (mirrors linkProgram's tcsOutputVertices extraction at
    // ~line 19186). Without this the emitted gl_in stride is 0 and
    // every patch collapses to the buffer origin.
    auto tcsModes = extractTessellationModes(
        tcsProg->tessControlSpirv.data(),
        tcsProg->tessControlSpirv.size());

    ShaderTranslator translator;
    BindingMap bindings;  // graphics-stage default; tess stages live in this layout
    bool fp64EmulationAvailable = false;
    if (owner != nullptr) {
        ExtensionContext fp64ExtensionContext(*owner);
        fp64EmulationAvailable =
            extensions::fp64::shaderTranslationSupported(fp64ExtensionContext);
    }

    auto synth = std::make_unique<GLProgramObject>();
    synth->hasTessellation = true;
    synth->tessControlOutputVertices = static_cast<GLint>(tcsModes.outputVertices);
    synth->tessGenMode = tesProg->tessGenMode;
    synth->tessGenSpacing = tesProg->tessGenSpacing;
    synth->tessGenVertexOrder = tesProg->tessGenVertexOrder;
    synth->tessGenPointMode = tesProg->tessGenPointMode;

    // 1) TCS — compile with siblingTesInputSpirv so SPIRV-Cross's
    //    helper-API closure walks TES's INPUT interface and
    //    add_msl_shader_outputs the matching slots on TCS's main0_out.
    //    Closes the per-CP buffer stride mismatch (Phase 7 / cluster A).
    {
        TranslatorOptions opts;
        opts.fp64EmulationAvailable = fp64EmulationAvailable;
        opts.forceTessellation = true;
        opts.siblingTesInputSpirv = tesProg->tessEvalSpirv.data();
        opts.siblingTesInputWordCount = tesProg->tessEvalSpirv.size();
        try {
            std::string log;
            synth->tessControlMSL = translator.spirvToMSL(
                tcsProg->tessControlSpirv.data(),
                tcsProg->tessControlSpirv.size(),
                bindings, &log, opts);
            synth->tessControlReflection = translator.reflect(
                tcsProg->tessControlSpirv.data(),
                tcsProg->tessControlSpirv.size(),
                bindings, nullptr, opts);
        } catch (...) {
            synth->tessControlMSL.clear();
        }
    }

    // 2) TES vertex form — kept for parity with the link-time path
    //    even though the post-isolines-patch compute-only flow only
    //    reads tessEvalAsComputeMSL.
    {
        TranslatorOptions opts;
        opts.fp64EmulationAvailable = fp64EmulationAvailable;
        opts.forceTessellation = true;
        // tc_barriers cluster: pad TES main0_in to mirror TCS main0_out
        // when TCS uses internal-output reads after barrier(). Without
        // this, per-CP buffer stride mismatches and TES reads at the
        // wrong offset.
        opts.siblingTcsOutputSpirv = tcsProg->tessControlSpirv.data();
        opts.siblingTcsOutputWordCount = tcsProg->tessControlSpirv.size();
        try {
            synth->tessEvalMSL = translator.spirvToMSL(
                tesProg->tessEvalSpirv.data(),
                tesProg->tessEvalSpirv.size(),
                bindings, nullptr, opts);
        } catch (...) {
            synth->tessEvalMSL.clear();
        }
    }

    // 3) VS-as-compute. Required for Phase3 — captures per-vertex VS
    //    output into a buffer the TCS dispatch reads via stage-input.
    //    Skipped if the separable VS didn't preserve SPIR-V (e.g. it
    //    was linked before β added the preservation in step 1a).
    if (vsProg != nullptr && !vsProg->vertexSpirv.empty()) {
        TranslatorOptions opts;
        opts.fp64EmulationAvailable = fp64EmulationAvailable;
        opts.forceVertexForTessellation = true;
        try {
            std::string log;
            synth->tessVertexAsComputeMSL = translator.spirvToMSL(
                vsProg->vertexSpirv.data(),
                vsProg->vertexSpirv.size(),
                bindings, &log, opts);
            synth->tessVertexAsComputeReflection = translator.reflect(
                vsProg->vertexSpirv.data(),
                vsProg->vertexSpirv.size(),
                bindings, nullptr, opts);
            // Strip the grid_size early-return — `dispatchThreads`
            // produces (0,0,0) for spvStageInputSize on macOS Apple
            // Silicon and the kernel would no-op every thread. Same
            // patch the link-time path applies (~line 19167).
            if (!synth->tessVertexAsComputeMSL.empty()) {
                std::string& mslRef = synth->tessVertexAsComputeMSL;
                const std::string needle =
                    "if (any(gl_GlobalInvocationID >= spvStageInputSize))\n"
                    "        return;";
                const std::size_t pos = mslRef.find(needle);
                if (pos != std::string::npos) {
                    mslRef.replace(pos, needle.size(),
                        "/* AppGL: grid_size early-return stripped */");
                }
            }
        } catch (...) {
            synth->tessVertexAsComputeMSL.clear();
        }
    }

    // 4) TES-as-compute with tesePatchVertices. The compute kernel
    //    consumes a domain-coord buffer + a per-CP VS-output buffer
    //    and writes its output into a TF-capture buffer.
    {
        TranslatorOptions opts;
        opts.fp64EmulationAvailable = fp64EmulationAvailable;
        opts.forceTessellation = true;
        opts.forceTessEvalAsCompute = true;
        opts.tesePatchVertices = static_cast<std::uint32_t>(tcsModes.outputVertices);
        // tc_barriers cluster: same per-CP stride alignment as the
        // vertex-form translation above — applies to compute form too.
        opts.siblingTcsOutputSpirv = tcsProg->tessControlSpirv.data();
        opts.siblingTcsOutputWordCount = tcsProg->tessControlSpirv.size();
        try {
            synth->tessEvalAsComputeMSL = translator.spirvToMSL(
                tesProg->tessEvalSpirv.data(),
                tesProg->tessEvalSpirv.size(),
                bindings, nullptr, opts);
            synth->tessEvalAsComputeReflection = translator.reflect(
                tesProg->tessEvalSpirv.data(),
                tesProg->tessEvalSpirv.size(),
                bindings, nullptr, opts);
            // Reflect the TES output struct layout for the TF writer.
            synth->tessEvalOutputLayout =
                translator.reflectStageOutputLayout(
                    tesProg->tessEvalSpirv.data(),
                    tesProg->tessEvalSpirv.size(),
                    opts);
        } catch (...) {
            synth->tessEvalAsComputeMSL.clear();
        }
    }

    // 5) FS + VS render-form MSL — copy from separable programs (already
    //    translated at separable-link time). Mirror the resolveDrawProgram
    //    pattern for non-tess pipeline-bound draws.
    if (fsProg != nullptr) {
        synth->fragmentMSL = fsProg->fragmentMSL;
        synth->fragmentMslUsesArgumentBuffer =
            fsProg->fragmentMslUsesArgumentBuffer;
        synth->fragmentReflection = fsProg->fragmentReflection;
    }
    if (vsProg != nullptr) {
        synth->vertexMSL = vsProg->vertexMSL;
        synth->vertexMslUsesArgumentBuffer =
            vsProg->vertexMslUsesArgumentBuffer;
        synth->vertexReflection = vsProg->vertexReflection;
    }

    // Carry SPIR-V onto the synth program so any downstream emulator
    // path that wants it (TessellationEmulator parsed-module cache,
    // CPU TF writer counter formulas) can find it without reaching
    // back across separable program boundaries.
    synth->vertexSpirv = vsProg ? vsProg->vertexSpirv : std::vector<std::uint32_t>{};
    synth->vertexSpirvEntryPoint =
        vsProg ? vsProg->vertexSpirvEntryPoint : std::string{};
    synth->vertexSpirvSpecializationConstants =
        vsProg ? vsProg->vertexSpirvSpecializationConstants
               : std::unordered_map<std::uint32_t, std::uint32_t>{};
    synth->tessControlSpirv = tcsProg->tessControlSpirv;
    synth->tessEvalSpirv = tesProg->tessEvalSpirv;
    synth->tessellationEmulated = tesProg->tessellationEmulated;
    synth->tessellationInterpreted = tesProg->tessellationInterpreted;
    synth->tessControlInterpreted = tcsProg->tessControlInterpreted;
    for (int i = 0; i < 4; ++i) {
        synth->tessPositionMapping[i] = tesProg->tessPositionMapping[i];
        synth->tessPositionScale[i] = tesProg->tessPositionScale[i];
        synth->tessPositionOffset[i] = tesProg->tessPositionOffset[i];
        synth->tessPositionConstant[i] = tesProg->tessPositionConstant[i];
    }
    synth->tessVaryings = tesProg->tessVaryings;
    (void)appgl::detectTessellationEmulatable(*synth);

    auto mergeStageUniforms = [&](const GLProgramObject* src) {
        if (src == nullptr) return;
        for (const auto& uniform : src->uniforms) {
            const auto sameName = [&](const GLProgramUniformInfo& existing) {
                return existing.name == uniform.name;
            };
            if (std::find_if(synth->uniforms.begin(), synth->uniforms.end(), sameName) ==
                synth->uniforms.end()) {
                synth->uniforms.push_back(uniform);
            }
        }
        for (const auto& entry : src->uniformValues) {
            synth->uniformValues.emplace(entry.first, entry.second);
        }
    };
    mergeStageUniforms(vsProg);
    mergeStageUniforms(tcsProg);
    mergeStageUniforms(tesProg);
    mergeStageUniforms(fsProg);

    // TF varying names live on the TES separable program (linked
    // there via glTransformFeedbackVaryings or in-shader xfb_buffer
    // qualifiers). The Metal TF writer reads this list to find each
    // varying inside the TES output struct.
    synth->transformFeedbackVaryingNames = tesProg->transformFeedbackVaryingNames;
    synth->transformFeedbackBufferMode = tesProg->transformFeedbackBufferMode;

    // Step 3 — run the same Metal tess probe linkProgram does, but
    // against the synthesised cross-stage MSL. Stash retained PSOs +
    // metalTessTier so the caller's gate (line ~23011) engages and
    // `tryMetalTessellationDraw` runs the encoder against this synth
    // program.
    bool probeOk = false;
    int probeVcOk = 0, probeTecOk = 0, probeRenderOk = 0;
    std::string probeDiag;
    if (frameGraph != nullptr &&
        !synth->tessControlMSL.empty() &&
        (!synth->tessEvalMSL.empty() ||
         !synth->tessEvalAsComputeMSL.empty()) &&
        !synth->fragmentMSL.empty()) {
        MetalFrameGraph::TessPipelineProbeResult probe =
            frameGraph->probeTessellationPipeline(
                synth->tessControlMSL,
                synth->tessEvalMSL,
                synth->fragmentMSL,
                synth->tessGenMode,
                synth->tessGenSpacing,
                synth->tessGenVertexOrder,
                synth->tessVertexAsComputeMSL,
                synth->tessEvalAsComputeMSL);
        probeVcOk = probe.vertexComputeOk ? 1 : 0;
        probeTecOk = probe.tessEvalComputeOk ? 1 : 0;
        probeRenderOk = probe.renderOk ? 1 : 0;
        probeDiag = probe.diagnostic;

        if (probe.vertexComputeOk) {
            synth->metalTessVertexPipelineState = probe.vertexComputePipelineState;
        }
        if (probe.tessEvalComputeOk) {
            synth->metalTessEvalComputePipelineState = probe.tessEvalComputePipelineState;
        }
        // Mirror linkProgram's tier classification (line ~19378). The
        // pipeline-bound tess path is always Phase3 — the test surface
        // (gl_MaxPatchVertices / data_pass_through / etc.) declares
        // VS-input, per-CP, or per-patch buffers that the Phase-2 code
        // path can't carry. Use the same handleability scan as
        // linkProgram.
        const bool needsPhase3 =
            probe.computeOk && (
                synth->tessControlMSL.find("spvIn [[buffer(") != std::string::npos ||
                synth->tessControlMSL.find("spvOut [[buffer(") != std::string::npos ||
                synth->tessControlMSL.find("spvPatchOut [[buffer(") != std::string::npos ||
                synth->tessEvalMSL.find("spvIn [[buffer(") != std::string::npos ||
                synth->tessEvalMSL.find("spvPatchIn [[buffer(") != std::string::npos);

        if (probe.computeOk && needsPhase3 && probe.vertexComputeOk) {
            synth->metalTessTier = GLProgramObject::MetalTessTier::Phase3;
            synth->metalTessControlPipelineState = probe.computePipelineState;
            probeOk = true;
        } else if (probe.computeOk && !needsPhase3) {
            synth->metalTessTier = GLProgramObject::MetalTessTier::Phase2;
            synth->metalTessControlPipelineState = probe.computePipelineState;
            probeOk = true;
        } else if (probe.computeOk) {
            // Phase3 needed but VS-compute PSO didn't build. Release
            // the orphan TCS PSO so we don't leak. Synth's
            // metalTessTier stays None → caller's gate fails → CPU
            // path runs (same as combined-program failure mode).
            releaseRetainedMetalObject(probe.computePipelineState);
        }
    } else if (detectorEnabled()) {
        std::fprintf(stderr,
            "APPGL_DETECTOR lift_pipe_synth probe_skipped "
            "frameGraph=%d tcsMSL=%d teMSL=%d teCompMSL=%d fsMSL=%d\n",
            frameGraph != nullptr ? 1 : 0,
            synth->tessControlMSL.empty() ? 0 : 1,
            synth->tessEvalMSL.empty() ? 0 : 1,
            synth->tessEvalAsComputeMSL.empty() ? 0 : 1,
            synth->fragmentMSL.empty() ? 0 : 1);
    }

    if (detectorEnabled()) {
        std::fprintf(stderr,
            "APPGL_DETECTOR lift_pipe_synth translate "
            "vs=%u tcs=%u tes=%u fs=%u "
            "msl_sizes=[v=%zu,tc=%zu,te=%zu,fs=%zu,vc=%zu,tec=%zu] "
            "tcs_outputVertices=%d tessGenMode=0x%04X "
            "outLayout_struct=%zu tfVaryings=%zu "
            "probe=[ok=%d vcOk=%d tecOk=%d renderOk=%d tier=%d] diag=\"%.120s\"\n",
            vsName, tcsName, tesName, fsName,
            synth->vertexMSL.size(),
            synth->tessControlMSL.size(),
            synth->tessEvalMSL.size(),
            synth->fragmentMSL.size(),
            synth->tessVertexAsComputeMSL.size(),
            synth->tessEvalAsComputeMSL.size(),
            (int)tcsModes.outputVertices,
            (unsigned)synth->tessGenMode,
            synth->tessEvalOutputLayout.structSize,
            synth->transformFeedbackVaryingNames.size(),
            probeOk ? 1 : 0,
            probeVcOk, probeTecOk, probeRenderOk,
            (int)synth->metalTessTier,
            probeDiag.c_str());
    }

    ppo.syntheticTessProgram = std::move(synth);
    return ppo.syntheticTessProgram.get();
}

static bool mslWritesRenderTargetArrayIndex(const std::string* msl) {
    return msl != nullptr &&
        msl->find("[[render_target_array_index]]") != std::string::npos;
}

static bool mslWritesViewportArrayIndex(const std::string* msl) {
    return msl != nullptr &&
        msl->find("[[viewport_array_index]]") != std::string::npos;
}

static std::unordered_map<std::string, std::uint32_t>
collectMslUserLocationsByName(const std::string& msl, const char* structName) {
    std::unordered_map<std::string, std::uint32_t> result;
    const std::string needle = std::string("struct ") + structName;
    const std::size_t structPos = msl.find(needle);
    if (structPos == std::string::npos) return result;
    const std::size_t bodyBegin = msl.find('{', structPos);
    const std::size_t bodyEnd = msl.find("};", bodyBegin);
    if (bodyBegin == std::string::npos || bodyEnd == std::string::npos) {
        return result;
    }
    std::size_t cursor = bodyBegin + 1;
    while (cursor < bodyEnd) {
        const std::size_t semi = msl.find(';', cursor);
        if (semi == std::string::npos || semi > bodyEnd) break;
        const std::string line = msl.substr(cursor, semi - cursor);
        cursor = semi + 1;
        const std::size_t userPos = line.find("[[user(locn");
        if (userPos == std::string::npos) continue;
        const std::size_t locBegin = userPos + std::strlen("[[user(locn");
        std::size_t locEnd = locBegin;
        while (locEnd < line.size() &&
               std::isdigit(static_cast<unsigned char>(line[locEnd]))) {
            ++locEnd;
        }
        if (locEnd == locBegin) continue;

        std::size_t nameEnd = userPos;
        while (nameEnd > 0 &&
               std::isspace(static_cast<unsigned char>(line[nameEnd - 1]))) {
            --nameEnd;
        }
        std::size_t nameBegin = nameEnd;
        while (nameBegin > 0) {
            const unsigned char ch =
                static_cast<unsigned char>(line[nameBegin - 1]);
            if (!(std::isalnum(ch) || ch == '_')) break;
            --nameBegin;
        }
        if (nameBegin == nameEnd) continue;

        result[line.substr(nameBegin, nameEnd - nameBegin)] =
            static_cast<std::uint32_t>(
                std::strtoul(line.c_str() + locBegin, nullptr, 10));
    }
    return result;
}

static void rewriteMslOutputLocationsForFragmentInputs(
    std::string& vertexMSL,
    const std::string& fragmentMSL) {
    const auto fsInputs =
        collectMslUserLocationsByName(fragmentMSL, "main0_in");
    if (fsInputs.empty()) return;

    std::unordered_set<std::uint32_t> fsInputLocations;
    std::uint32_t nextFree = 0;
    for (const auto& kv : fsInputs) {
        fsInputLocations.insert(kv.second);
        nextFree = std::max(nextFree, kv.second + 1u);
    }
    std::unordered_set<std::uint32_t> assignedLocations;
    auto allocateFreeLocation = [&]() {
        while (fsInputLocations.find(nextFree) != fsInputLocations.end() ||
               assignedLocations.find(nextFree) != assignedLocations.end()) {
            ++nextFree;
        }
        return nextFree++;
    };

    const std::size_t structPos = vertexMSL.find("struct main0_out");
    if (structPos == std::string::npos) return;
    const std::size_t bodyBegin = vertexMSL.find('{', structPos);
    std::size_t bodyEnd = vertexMSL.find("};", bodyBegin);
    if (bodyBegin == std::string::npos || bodyEnd == std::string::npos) {
        return;
    }

    auto parseUserLocationField = [](const std::string& text,
                                     std::size_t cursor,
                                     std::size_t semi,
                                     std::string& name,
                                     std::size_t& locBegin,
                                     std::size_t& locEnd,
                                     std::uint32_t& loc) -> bool {
        const std::size_t userPos = text.find("[[user(locn", cursor);
        if (userPos == std::string::npos || userPos > semi) {
            return false;
        }
        locBegin = userPos + std::strlen("[[user(locn");
        locEnd = locBegin;
        while (locEnd < text.size() &&
               std::isdigit(static_cast<unsigned char>(text[locEnd]))) {
            ++locEnd;
        }
        if (locEnd == locBegin) {
            return false;
        }

        std::size_t nameEnd = userPos;
        while (nameEnd > cursor &&
               std::isspace(static_cast<unsigned char>(text[nameEnd - 1]))) {
            --nameEnd;
        }
        std::size_t nameBegin = nameEnd;
        while (nameBegin > cursor) {
            const unsigned char ch =
                static_cast<unsigned char>(text[nameBegin - 1]);
            if (!(std::isalnum(ch) || ch == '_')) break;
            --nameBegin;
        }
        if (nameBegin == nameEnd) {
            return false;
        }

        name = text.substr(nameBegin, nameEnd - nameBegin);
        loc = static_cast<std::uint32_t>(
            std::strtoul(text.c_str() + locBegin, nullptr, 10));
        return true;
    };

    // Reserve exact VS->FS matches before relocating unmatched outputs.
    // Otherwise an earlier helper varying at the same old location can
    // steal the FS input's slot and create duplicate [[user(locnN)]]
    // attributes after the matched varying is rewritten later.
    std::size_t reserveCursor = bodyBegin + 1;
    while (reserveCursor < bodyEnd) {
        const std::size_t semi = vertexMSL.find(';', reserveCursor);
        if (semi == std::string::npos || semi > bodyEnd) break;
        std::string name;
        std::size_t locBegin = 0;
        std::size_t locEnd = 0;
        std::uint32_t oldLoc = 0;
        if (parseUserLocationField(vertexMSL, reserveCursor, semi,
                                   name, locBegin, locEnd, oldLoc)) {
            const auto locIt = fsInputs.find(name);
            if (locIt != fsInputs.end()) {
                assignedLocations.insert(locIt->second);
            }
        }
        reserveCursor = semi + 1;
    }

    std::size_t cursor = bodyBegin + 1;
    while (cursor < bodyEnd) {
        const std::size_t semi = vertexMSL.find(';', cursor);
        if (semi == std::string::npos || semi > bodyEnd) break;
        std::string name;
        std::size_t locBegin = 0;
        std::size_t locEnd = 0;
        std::uint32_t oldLoc = 0;
        if (!parseUserLocationField(vertexMSL, cursor, semi,
                                    name, locBegin, locEnd, oldLoc)) {
            cursor = semi + 1;
            continue;
        }

        const auto locIt = fsInputs.find(name);
        std::uint32_t newLoc = 0;
        if (locIt != fsInputs.end()) {
            newLoc = locIt->second;
        } else if (fsInputLocations.find(oldLoc) != fsInputLocations.end() &&
                   assignedLocations.find(oldLoc) == assignedLocations.end()) {
            // Preserve explicit-location interfaces whose VS/FS names differ
            // (for example layout(location=3) out o; / in i;).
            newLoc = oldLoc;
        } else {
            newLoc = allocateFreeLocation();
        }
        assignedLocations.insert(newLoc);
        const std::string replacement = std::to_string(newLoc);
        vertexMSL.replace(locBegin, locEnd - locBegin, replacement);
        const std::ptrdiff_t delta =
            static_cast<std::ptrdiff_t>(replacement.size()) -
            static_cast<std::ptrdiff_t>(locEnd - locBegin);
        const std::size_t adjustedSemi =
            static_cast<std::size_t>(static_cast<std::ptrdiff_t>(semi) + delta);
        bodyEnd =
            static_cast<std::size_t>(static_cast<std::ptrdiff_t>(bodyEnd) + delta);
        cursor = adjustedSemi + 1;
    }
}

bool GLContext::Impl::tryMetalTessellationDraw(GLProgramObject& program,
                                                GLuint programName,
                                                GLenum mode,
                                                GLsizei count,
                                                GLint first,
                                                GLsizei instanceCount,
                                                GLuint baseInstance)
{
    (void)first;
    if (mode != GL_PATCHES) return false;
    if (program.metalTessControlPipelineState == nullptr) return false;
    // Widened post-isolines-compute-bypass (SPIRV-Cross 095c99c): allow
    // empty `tessEvalMSL` (conventional render-vertex form) when the
    // as-compute form is present. Isolines TES emits valid kernel MSL
    // but no render form because Metal doesn't support isoline tess in
    // the render pipeline. The compute chain doesn't need the render
    // form — it dispatches TES-as-compute directly into the TF buffer.
    if (program.tessControlMSL.empty() ||
        (program.tessEvalMSL.empty() && program.tessEvalAsComputeMSL.empty()) ||
        program.fragmentMSL.empty()) {
        return false;
    }
    if (program.tessControlOutputVertices <= 0) return false;
    if (transformFeedbackActive &&
        (program.gsPresent || !program.geometrySpirv.empty())) {
        return false;
    }

    // Phase 3B.5 [metal-tess-TF]: transform feedback on tess draws
    // is wired when (a) the env flag is set, (b) the program has a
    // built TES-compute PSO, and (c) the TES output layout was
    // reflected. If those conditions hold, the Metal path runs the
    // full compute chain + deposits TF bytes on CPU. Otherwise we
    // defer to the CPU tessellation interpreter.
    // Phase 4 [metal-tess-TF]: isolines domain-gen is live, but the
    // invariance + vertex_spacing tests probe correctness beyond the
    // per-patch vertex count (symmetry around axis, exact fractional
    // spacing rounding, …). Our domain-gen isn't exact enough yet —
    // keep uniform-using programs on the CPU tessellator to preserve
    // 3B.5's wins until the tess correctness gap closes.
    const bool tcsUsesDefaultUniforms =
        program.tessControlMSL.find("_DefaultUniforms") != std::string::npos;
    const bool tessUsesUniforms =
        tcsUsesDefaultUniforms ||
        program.tessEvalAsComputeMSL.find("_DefaultUniforms") != std::string::npos ||
        program.tessVertexAsComputeMSL.find("_DefaultUniforms") != std::string::npos;
    // APPGL_LIFT_TESS_UNIFORM_GUARD is the paired default-on gate for
    // uniform-using tess programs. APPGL_LIFT_TESS_UNIFORM_GUARD=0
    // preserves the legacy CPU fallback for attribution.
    const bool liftUniformGuard = liftTessUniformGuardEnabled();
    const bool enableMetalTessTF = metalTessTFEnabled();
    const bool tessUsesFp64 = tessellationProgramUsesFp64(program);
    const bool tcsUsesFp64 = program.tessControlReflection.usesFp64;
    // CTS max_uniform_components lowers as a TCS FP64 reflection without
    // a `_DefaultUniforms` MSL marker. The Metal tessellation TF path does
    // not yet preserve those FP64 side-effect bytes, so keep only TCS-FP64
    // TF/discard captures on the CPU tessellator.
    const bool tessFp64TfFallback = tcsUsesFp64 &&
        (transformFeedbackActive || state->isEnabled(GL_RASTERIZER_DISCARD));
    const bool tessTFActive =
        transformFeedbackActive &&
        program.metalTessEvalComputePipelineState != nullptr &&
        program.tessEvalOutputLayout.structSize > 0 &&
        (liftUniformGuard || !tessUsesUniforms) &&
        !tessFp64TfFallback &&
        enableMetalTessTF;
    // Detector point B — gate-evaluation instrumentation paired with link
    // probe (A) and dispatch (C). Logs every reach of this gate plus the
    // tier classification + rasterizer-discard state so post-processors
    // can answer: "did the LIFT path actually engage, and if not, why?"
    if (detectorEnabled()) {
        std::fprintf(stderr,
            "APPGL_DETECTOR lift_gate prog=%u mode=0x%04X count=%d tier=%d "
            "tessUsesUniforms=%d tessUsesFp64=%d tcsUsesFp64=%d "
            "fp64Fallback=%d "
            "liftGuard=%d enableMetalTF=%d "
            "compPSO=%d tesOutSize=%zu tfActive=%d rasterDiscard=%d "
            "-> tessTFActive=%d\n",
            static_cast<unsigned int>(programName),
            static_cast<unsigned int>(mode),
            static_cast<int>(count),
            static_cast<int>(program.metalTessTier),
            tessUsesUniforms ? 1 : 0,
            tessUsesFp64 ? 1 : 0,
            tcsUsesFp64 ? 1 : 0,
            tessFp64TfFallback ? 1 : 0,
            liftUniformGuard ? 1 : 0,
            enableMetalTessTF ? 1 : 0,
            program.metalTessEvalComputePipelineState != nullptr ? 1 : 0,
            program.tessEvalOutputLayout.structSize,
            transformFeedbackActive ? 1 : 0,
            state->isEnabled(GL_RASTERIZER_DISCARD) ? 1 : 0,
            tessTFActive ? 1 : 0);
    }
    if (transformFeedbackActive && !tessTFActive) {
        return false;
    }
    if (!transformFeedbackActive &&
        !state->isEnabled(GL_RASTERIZER_DISCARD) &&
        program.tessEvalMSL.empty() &&
        !program.tessEvalAsComputeMSL.empty() &&
        program.tessGenMode == GL_ISOLINES &&
        program.tessGenPointMode == GL_TRUE &&
        !(program.metalTessEvalComputePipelineState != nullptr &&
          program.tessEvalOutputLayout.structSize > 0 &&
          enableMetalTessTF)) {
        return false;
    }
    // Rasterizer-discard is usually paired with TF. When the TF-
    // capture chain is wired, we still run it (the render pass
    // below is skipped naturally because the test is side-effect
    // only). When unwired, defer to CPU.
    //
    // Phase 5 probe: with APPGL_LIFT_TESS_UNIFORM_GUARD, the CTS
    // tess vertex-counter program's probe drawArrays (DISCARD on,
    // TF off, PRIMITIVES_GENERATED query active) needs to take the
    // same Metal compute chain so its count matches the subsequent
    // Metal TF-capture draw. Otherwise counter goes CPU, main goes
    // Metal, buffer sized by CPU count, Metal overflow = TF_WRITTEN
    // comes back 0.
    const bool keepMetalForDiscardProbe = liftUniformGuard &&
        program.metalTessEvalComputePipelineState != nullptr &&
        enableMetalTessTF &&
        !tessFp64TfFallback;
    if (state->isEnabled(GL_RASTERIZER_DISCARD) && !tessTFActive &&
        !keepMetalForDiscardProbe) {
        return false;
    }

    const GLint pv = state->tessellationState().patchVertices;
    if (pv <= 0 || count < pv) return false;
    const GLsizei patchCount = count / pv;
    if (patchCount <= 0) return false;

    MetalTessDrawInfo info;
    std::vector<GLuint> tessVertexBufferNames;
    std::vector<GLuint> tessSampledTextureNames;
    info.tessControlPipelineState = program.metalTessControlPipelineState;
    if (program.metalTessTier == GLProgramObject::MetalTessTier::Phase3) {
        info.vertexComputePipelineState = program.metalTessVertexPipelineState;
    }

    auto canUseZeroedVsForTfSemantics = [&]() -> bool {
        if (!transformFeedbackActive ||
            !state->isEnabled(GL_RASTERIZER_DISCARD) ||
            program.transformFeedbackVaryingNames.size() != 5) {
            return false;
        }
        static const char* kSemanticNames[] = {
            "te_tc_invocation_id",
            "te_tc_patch_vertices_in",
            "te_tc_primitive_id",
            "te_patch_vertices_in",
            "te_primitive_id",
        };
        for (const char* want : kSemanticNames) {
            const auto& names = program.transformFeedbackVaryingNames;
            if (std::find(names.begin(), names.end(), want) == names.end()) {
                return false;
            }
        }
        return true;
    };

    // T4I [metal-tess-TF]: when the VS-as-compute MSL declares
    // `[[stage_in]]`, build/cache the PSO from the bound VAO's
    // descriptor before encode. Per-program, per-VAO-hash cache so
    // VAO swaps don't pay the build cost twice.
    if (program.metalTessTier == GLProgramObject::MetalTessTier::Phase3 &&
        program.metalTessVertexNeedsDescriptor &&
        info.vertexComputePipelineState == nullptr) {
        const GLuint vaoName = state->boundVertexArray();
        GLVertexArrayObject* vao = objects->vertexArrays().get(vaoName);
        if (vao == nullptr) {
            return false;
        }
        appgl::MetalVertexDescriptorBuildResult buildResult =
            appgl::buildMetalStageInputOutputDescriptor(*vao);
        if (buildResult.descriptor == nullptr) {
            return false;
        }
        void* vsPSO = nullptr;
        bool useZeroedVsOutputs = false;
        auto cached = program.metalTessVertexPSOCache.find(buildResult.hash);
        if (cached != program.metalTessVertexPSOCache.end()) {
            vsPSO = cached->second;
        } else {
            std::string err;
            vsPSO = frameGraph->buildComputePipelineState(
                program.tessVertexAsComputeMSL, &err, nullptr,
                buildResult.descriptor);
            if (vsPSO != nullptr) {
                program.metalTessVertexPSOCache[buildResult.hash] = vsPSO;
            } else if (std::getenv("APPGL_TRACE_TESS")) {
                std::fprintf(stderr,
                    "[APPGL] T4I draw-time VS-compute PSO build failed: %s\n",
                    err.c_str());
            }
        }
        appgl::releaseMetalStageInputOutputDescriptor(buildResult.descriptor);
        if (vsPSO == nullptr) {
            if (canUseZeroedVsForTfSemantics()) {
                useZeroedVsOutputs = true;
                info.forcePhase3Buffers = true;
                if (std::getenv("APPGL_TRACE_TESS")) {
                    std::fprintf(stderr,
                        "[APPGL] T4I draw-time VS-compute PSO unavailable; "
                        "using zeroed VS outputs for TF semantic-only tess draw\n");
                }
            } else {
                return false;
            }
        }
        info.vertexComputePipelineState = vsPSO;
        // Resolve buffer bindings for the encoder.
        for (const auto& binding : buildResult.vertexBufferBindings) {
            if (useZeroedVsOutputs) {
                break;
            }
            if (binding.glBuffer != 0) {
                tessVertexBufferNames.push_back(binding.glBuffer);
            }
            GLBufferObject* vbo = objects->buffers().get(binding.glBuffer);
            if (vbo == nullptr || vbo->metalBuffer == nullptr) {
                if (std::getenv("APPGL_TRACE_TESS")) {
                    std::fprintf(stderr,
                        "[APPGL] T4I draw-time VBO resolve failed: glBuffer=%u\n",
                        binding.glBuffer);
                }
                return false;
            }
            MetalTessVertexBufferBinding ent;
            ent.metalBuffer = vbo->metalBuffer;
            ent.offset = 0;
            ent.metalSlot = binding.metalSlot;
            info.vertexComputeBufferBindings.push_back(ent);
        }
        if (std::getenv("APPGL_TRACE_TESS")) {
            std::fprintf(stderr,
                "[APPGL] T4I draw-time vsPSO=%p hash=%s bindings=%zu\n",
                vsPSO, buildResult.hash.c_str(),
                info.vertexComputeBufferBindings.size());
            for (const auto& b : info.vertexComputeBufferBindings) {
                std::fprintf(stderr,
                    "[APPGL] T4I   binding slot=%u buf=%p\n",
                    b.metalSlot, b.metalBuffer);
            }
        }
    }
    // Phase 3B.4 [metal-tess-TF]: forward the TES-as-compute PSO if
    // the link-time probe built one. The encoder only runs the
    // domain-gen + TES-compute dispatches when the default-on
    // `APPGL_ENABLE_METAL_TESS_TF` gate is enabled; with =0 the PSO
    // slot is ignored and the render path runs unchanged.
    info.tessEvalComputePipelineState =
        program.metalTessEvalComputePipelineState;
    if (program.tessEvalOutputLayout.structSize > 0) {
        info.tessEvalOutputStrideBytes =
            std::max<std::size_t>(256, program.tessEvalOutputLayout.structSize);
    }
    info.tessControlMSL = &program.tessControlMSL;
    info.tessVertexAsComputeMSL = &program.tessVertexAsComputeMSL;
    info.tessEvalAsComputeMSL = &program.tessEvalAsComputeMSL;
    info.tessEvalMSL = &program.tessEvalMSL;
    info.fragmentMSL = &program.fragmentMSL;
    info.patchCount = patchCount;
    info.patchVertices = pv;
    // Sprint 5 Phase 1 — synth TCS host-populate signal: snapshot
    // glPatchParameterfv state for the encoder to override synth TCS's
    // 1.0 defaults in factorBufFull.
    info.tessControlSynthesized = program.tessControlSynthesized;
    if (program.tessControlSynthesized) {
        const auto& tessState = state->tessellationState();
        for (int i = 0; i < 4; ++i)
            info.defaultOuterLevel[i] = tessState.defaultOuterLevel[i];
        for (int i = 0; i < 2; ++i)
            info.defaultInnerLevel[i] = tessState.defaultInnerLevel[i];
    }
    info.tessControlOutputVertices = program.tessControlOutputVertices;
    info.genMode = program.tessGenMode;
    info.genSpacing = program.tessGenSpacing;
    info.genVertexOrder = program.tessGenVertexOrder;
    info.pointMode = (program.tessGenPointMode == GL_TRUE);
    info.instanceCount = instanceCount > 0 ? instanceCount : 1;
    info.baseInstance = baseInstance;
    info.program = programName;

    auto resolveTessStageSamplerBindings =
        [&](const ShaderReflection& reflection,
            std::vector<TranslatedDrawInfo::TextureBinding>& outBindings) {
            TranslatedDrawInfo textureInfo;
            textureInfo.program = programName;
            textureInfo.vertexReflection = &reflection;
            resolveSamplerBindings(program, textureInfo);
            tessSampledTextureNames.insert(tessSampledTextureNames.end(),
                                           textureInfo.sampledTextureNames.begin(),
                                           textureInfo.sampledTextureNames.end());
            outBindings = std::move(textureInfo.vertexTextures);
        };
    resolveTessStageSamplerBindings(program.tessControlReflection,
        info.tessControlTextures);
    resolveTessStageSamplerBindings(program.tessVertexAsComputeReflection,
        info.tessVertexAsComputeTextures);
    {
        TranslatedDrawInfo textureInfo;
        textureInfo.program = programName;
        textureInfo.vertexReflection = &program.tessEvalAsComputeReflection;
        textureInfo.fragmentReflection = &program.fragmentReflection;
        resolveSamplerBindings(program, textureInfo);
        tessSampledTextureNames.insert(tessSampledTextureNames.end(),
                                       textureInfo.sampledTextureNames.begin(),
                                       textureInfo.sampledTextureNames.end());
        info.tessEvalTextures = std::move(textureInfo.vertexTextures);
        info.fragmentTextures = std::move(textureInfo.fragmentTextures);
    }

    // Phase 4 [metal-tess-TF]: pack default uniforms for each tess
    // compute stage so the TCS / VS-compute / TES-compute kernels
    // read glUniform* values. Layout is computed lazily once per
    // program. Only runs when the program actually references
    // _DefaultUniforms in its compute MSL — otherwise we skip the
    // per-draw pack cost.
    // Phase 5 path: when APPGL_LIFT_TESS_UNIFORM_GUARD is enabled
    // (default, with =0 opt-out), pack the default uniforms so the
    // Metal path feeds the right tess factors to
    // TCS/VS-compute/TES-compute.
    thread_local std::vector<std::uint8_t> tcsUniformScratch;
    thread_local std::vector<std::uint8_t> vsComputeUniformScratch;
    thread_local std::vector<std::uint8_t> tesComputeUniformScratch;
    thread_local std::vector<std::uint8_t> fragUniformScratch;
    if (program.fragmentUniformLayout.empty() &&
        !program.fragmentReflection.uniformBlocks.empty()) {
        computeStageUniformLayout(program.fragmentUniformLayout,
            program.fragmentReflection, program.uniforms);
    }
    if (!program.fragmentUniformLayout.empty()) {
        if (pushSynthesizedMatrixUniforms(program, matrixState)) {
            program.markUniformsDirty();
        }
        buildStageUniformBuffer(fragUniformScratch,
            program.fragmentReflection, program.uniformValues,
            program.fragmentUniformLayout);
        info.fragmentUniformData = fragUniformScratch.data();
        info.fragmentUniformSize = fragUniformScratch.size();
    }
    // Phase 5 probe: pack uniforms for ANY Metal-routed tess draw
    // when the uniform guard is enabled, not just TF-active ones. The CTS counter
    // probe is non-TF but still needs accurate tess factors or its
    // PRIMITIVES_GENERATED count won't match the subsequent TF
    // draws.
    const bool packUniformsForThisDraw = liftUniformGuard && tessUsesUniforms &&
        program.metalTessEvalComputePipelineState != nullptr &&
        program.tessEvalOutputLayout.structSize > 0 &&
        enableMetalTessTF;
    if (packUniformsForThisDraw) {
        if (program.tessControlUniformLayout.empty() &&
            !program.tessControlReflection.uniformBlocks.empty()) {
            computeStageUniformLayout(program.tessControlUniformLayout,
                program.tessControlReflection, program.uniforms);
        }
        if (program.tessVertexAsComputeUniformLayout.empty() &&
            !program.tessVertexAsComputeReflection.uniformBlocks.empty()) {
            computeStageUniformLayout(program.tessVertexAsComputeUniformLayout,
                program.tessVertexAsComputeReflection, program.uniforms);
        }
        if (program.tessEvalAsComputeUniformLayout.empty() &&
            !program.tessEvalAsComputeReflection.uniformBlocks.empty()) {
            computeStageUniformLayout(program.tessEvalAsComputeUniformLayout,
                program.tessEvalAsComputeReflection, program.uniforms);
        }
        if (!program.tessControlUniformLayout.empty()) {
            buildStageUniformBuffer(tcsUniformScratch,
                program.tessControlReflection, program.uniformValues,
                program.tessControlUniformLayout);
            info.tessControlUniformData = tcsUniformScratch.data();
            info.tessControlUniformSize = tcsUniformScratch.size();
            if (std::getenv("APPGL_DUMP_TESOUT")) {
                std::fprintf(stderr,
                    "APPGL_DETECTOR tcs_uniform_pack prog=%u size=%zu",
                    (unsigned)programName, tcsUniformScratch.size());
                const std::size_t kPrintBytes =
                    tcsUniformScratch.size() < 64u
                        ? tcsUniformScratch.size() : 64u;
                std::fprintf(stderr, " bytes=");
                for (std::size_t i = 0; i + 4 <= kPrintBytes; i += 4) {
                    float f;
                    std::memcpy(&f, tcsUniformScratch.data() + i, sizeof(f));
                    std::fprintf(stderr, "%.4f ", f);
                }
                std::fprintf(stderr, "\n");
            }
        }
        if (!program.tessVertexAsComputeUniformLayout.empty()) {
            buildStageUniformBuffer(vsComputeUniformScratch,
                program.tessVertexAsComputeReflection, program.uniformValues,
                program.tessVertexAsComputeUniformLayout);
            info.tessVertexAsComputeUniformData = vsComputeUniformScratch.data();
            info.tessVertexAsComputeUniformSize = vsComputeUniformScratch.size();
        }
        if (!program.tessEvalAsComputeUniformLayout.empty()) {
            buildStageUniformBuffer(tesComputeUniformScratch,
                program.tessEvalAsComputeReflection, program.uniformValues,
                program.tessEvalAsComputeUniformLayout);
            info.tessEvalAsComputeUniformData = tesComputeUniformScratch.data();
            info.tessEvalAsComputeUniformSize = tesComputeUniformScratch.size();
        }
    }

    // Fixed-function state snapshot (mirrors
    // populateTranslatedDrawFixedFunctionState but scoped to the
    // minimum Phase 2 needs).
    info.depthTestEnabled = state->isEnabled(GL_DEPTH_TEST);
    info.depthFunc = state->depthState().func;
    info.depthWriteMask = (state->depthState().writeMask != GL_FALSE);
    info.cullFaceEnabled = state->isEnabled(GL_CULL_FACE);
    info.cullFaceMode = state->rasterState().cullFaceMode;
    info.frontFace = state->rasterState().frontFace;
    info.wireframe = (state->rasterState().polygonFillMode == GL_LINE);
    info.sampleMask =
        state->isEnabled(GL_SAMPLE_MASK)
            ? static_cast<std::uint32_t>(state->sampleMask(0))
            : 0xFFFFFFFFu;
    // Sprint 7 Phase 1 #11 (CKPT57): tess Phase-2 render encoder
    // stencil state — required for primitive_coverage's two-phase
    // stencil-replace + stencil-notequal pattern. Same shape as the
    // translated-draw populator.
    {
        const auto& gs = state->stencilState();
        info.stencilTestEnabled = state->isEnabled(GL_STENCIL_TEST);
        info.stencilFrontFunc = gs.front.func;
        info.stencilFrontRef = gs.front.ref;
        info.stencilFrontValueMask = gs.front.valueMask;
        info.stencilFrontFail = gs.front.fail;
        info.stencilFrontDepthFail = gs.front.depthFail;
        info.stencilFrontDepthPass = gs.front.depthPass;
        info.stencilFrontWriteMask = gs.front.writeMask;
        info.stencilBackFunc = gs.back.func;
        info.stencilBackRef = gs.back.ref;
        info.stencilBackValueMask = gs.back.valueMask;
        info.stencilBackFail = gs.back.fail;
        info.stencilBackDepthFail = gs.back.depthFail;
        info.stencilBackDepthPass = gs.back.depthPass;
        info.stencilBackWriteMask = gs.back.writeMask;
    }

    const auto& vp = state->viewport();
    info.viewportX = vp.x;
    info.viewportY = vp.y;
    info.viewportWidth = vp.width;
    info.viewportHeight = vp.height;
    const auto& dr = state->depthRange();
    info.depthRangeNear = dr.nearValue;
    info.depthRangeFar = dr.farValue;
    info.clipOrigin = state->clipOrigin();

    {
        appgl::GLStateTracker::IndexedViewportEntry vparr[
            appgl::TranslatedDrawInfo::kMaxDrawViewports];
        std::size_t got = 0;
        state->getViewportArray(vparr,
            appgl::TranslatedDrawInfo::kMaxDrawViewports, &got);
        appgl::GLStateTracker::IndexedScissorEntry scarrPre[
            appgl::TranslatedDrawInfo::kMaxDrawViewports];
        std::size_t scgotPre = 0;
        state->getScissorArray(scarrPre,
            appgl::TranslatedDrawInfo::kMaxDrawViewports, &scgotPre);
        bool anyDiverge = false;
        for (std::size_t i = 1; i < got; ++i) {
            if (vparr[i].x != vparr[0].x ||
                vparr[i].y != vparr[0].y ||
                vparr[i].width != vparr[0].width ||
                vparr[i].height != vparr[0].height ||
                vparr[i].depthNear != vparr[0].depthNear ||
                vparr[i].depthFar != vparr[0].depthFar) {
                anyDiverge = true;
                break;
            }
        }
        if (!anyDiverge) {
            for (std::size_t i = 1; i < scgotPre; ++i) {
                if (scarrPre[i].x != scarrPre[0].x ||
                    scarrPre[i].y != scarrPre[0].y ||
                    scarrPre[i].width != scarrPre[0].width ||
                    scarrPre[i].height != scarrPre[0].height ||
                    scarrPre[i].enabled != scarrPre[0].enabled) {
                    anyDiverge = true;
                    break;
                }
            }
        }
        if (anyDiverge) {
            for (std::size_t i = 0; i < got; ++i) {
                info.viewportArray[i].originX = vparr[i].x;
                info.viewportArray[i].originY = vparr[i].y;
                info.viewportArray[i].width = vparr[i].width;
                info.viewportArray[i].height = vparr[i].height;
                info.viewportArray[i].depthNear = vparr[i].depthNear;
                info.viewportArray[i].depthFar = vparr[i].depthFar;
            }
            info.viewportArrayCount = got;
            appgl::GLStateTracker::IndexedScissorEntry scarr[
                appgl::TranslatedDrawInfo::kMaxDrawViewports];
            std::size_t scgot = 0;
            state->getScissorArray(scarr,
                appgl::TranslatedDrawInfo::kMaxDrawViewports, &scgot);
            const std::size_t cap = std::min(got, scgot);
            for (std::size_t i = 0; i < cap; ++i) {
                info.scissorArray[i].x = scarr[i].x;
                info.scissorArray[i].y = scarr[i].y;
                info.scissorArray[i].width = scarr[i].width;
                info.scissorArray[i].height = scarr[i].height;
                info.scissorArray[i].enabled = scarr[i].enabled;
            }
            info.scissorArrayCount = cap;
        }
    }

    info.scissorTestEnabled = state->isEnabled(GL_SCISSOR_TEST);
    const auto& sc = state->scissor();
    info.scissorX = sc.x;
    info.scissorY = sc.y;
    info.scissorWidth = sc.width;
    info.scissorHeight = sc.height;

    // FBO target resolution — reuse the same helper the translated
    // draw path uses. Phase 2 ignores MRT + layered + slice state
    // because winding.triangles_ccw draws to a single-attachment FBO.
    GLsizei fboW = 0, fboH = 0;
    void* fboDSTex = nullptr;
    std::uint32_t fboArrayLen = 0;
    void* fboColTex = resolveFBOColorTarget(
        fboW, fboH, fboDSTex, &fboArrayLen);
    if (fboColTex != nullptr || fboDSTex != nullptr) {
        info.fboColorTexture = fboColTex;
        info.fboDepthStencilTexture = fboDSTex;
        if (mslWritesRenderTargetArrayIndex(info.tessEvalMSL) &&
            fboColTex != nullptr) {
            info.fboColorArrayLength = fboArrayLen > 0 ? fboArrayLen : 1u;
        }
    }

    // Phase 3B.5 [metal-tess-TF]: when the Metal tess-TF path is
    // active and the program has a TES-compute PSO, wire the
    // encoder's out-params so we can walk the produced vertex
    // buffer + deposit TF bytes after the encode completes.
    std::uint32_t tfGeneratedVerts = 0;
    void* tfRetainedOutBuf = nullptr;
    // Keep the out-params wired for every draw with a TES-compute PSO.
    // MetalFrameGraph only runs the domain/TES-compute sidecar when it is
    // required for TF, point-mode replay, or active tess counter queries
    // (or when an explicit diagnostic env asks for optional output).
    // If TF is inactive, `writeTessTFAndUpdateCounters` still skips the
    // actual TF buffer write.
    const bool runTessTFWrite =
        program.metalTessEvalComputePipelineState != nullptr &&
        program.tessEvalOutputLayout.structSize > 0 &&
        enableMetalTessTF;
    bool tessCounterQueryActive = false;
    objects->queries().forEach([&](GLuint /*id*/, GLQueryObject& q) {
        if (!q.active) {
            return;
        }
        switch (q.target) {
            case GL_PRIMITIVES_GENERATED:
            case GL_TRANSFORM_FEEDBACK_PRIMITIVES_WRITTEN:
            case GL_TRANSFORM_FEEDBACK_OVERFLOW:
            case GL_TRANSFORM_FEEDBACK_STREAM_OVERFLOW:
                tessCounterQueryActive = true;
                break;
            default:
                break;
        }
    });
    info.tessEvalComputeRequired =
        tessTFActive ||
        (!state->isEnabled(GL_RASTERIZER_DISCARD) &&
         program.tessGenPointMode == GL_TRUE) ||
        tessCounterQueryActive;
    if (runTessTFWrite) {
        info.outGeneratedVertCount = &tfGeneratedVerts;
        info.outTesComputeOutBuf = &tfRetainedOutBuf;
    }
    // T4F bail-trace: log the runTessTFWrite inputs at the gate so we
    // can pinpoint where the pipeline-path main draw bails on its way
    // from lift_gate to writeTessTFAndUpdateCounters. For pipeline-
    // resolved program (resolveDrawProgram returns VS container), the
    // tess metadata fields may be null/empty — runTessTFWrite collapses
    // to false, encoder runs but writeTessTFAndUpdateCounters is never
    // called → TF buffer stays at zero-init.
    if (detectorEnabled()) {
        std::fprintf(stderr,
            "APPGL_DETECTOR lift_pre_encode prog=%u "
            "metalTessEvalComputePSO_present=%d tesOutSize=%zu "
            "enableMetalTF=%d -> runTessTFWrite=%d\n",
            (unsigned)programName,
            program.metalTessEvalComputePipelineState != nullptr ? 1 : 0,
            program.tessEvalOutputLayout.structSize,
            enableMetalTessTF ? 1 : 0,
            runTessTFWrite ? 1 : 0);
    }

    const bool tessWillRender =
        !state->isEnabled(GL_RASTERIZER_DISCARD) &&
        info.tessEvalMSL != nullptr &&
        !info.tessEvalMSL->empty() &&
        !(info.pointMode && runTessTFWrite);
    declareTessSubmissionGroup(info, tessVertexBufferNames,
                               tessSampledTextureNames, tessWillRender);

    const bool encodeOk = frameGraph->encodeMetalTessellationDraw(info);
    if (encodeOk && info.didRender && state->boundDrawFramebuffer() == 0) {
        invalidateDefaultFramebufferShadow();
    } else if (encodeOk && info.didRender) {
        if (GLFramebufferObject* fbo =
                objects->framebuffers().get(state->boundDrawFramebuffer())) {
            GpuResourceWriteSet producerWrites;
            appendFramebufferAttachmentWrites(producerWrites, *fbo);
            markGpuResourceWrites(producerWrites);
            const bool markViewportReadback =
                info.viewportArrayCount > 1 &&
                mslWritesViewportArrayIndex(info.tessEvalMSL) &&
                state->clipOrigin() == GL_LOWER_LEFT;
            for (const auto& kv : fbo->attachments) {
                if (!isColorAttachment(kv.first)) continue;
                if (kv.second.kind !=
                        GLFramebufferAttachment::Kind::Texture) continue;
                if (GLTextureObject* tex =
                        objects->textures().get(kv.second.object)) {
                    tex->wasFramebufferRenderedTo = true;
                    if (markViewportReadback) {
                        tex->wasViewportRenderedTo = true;
                    }
                }
            }
        }
    }

    if (detectorEnabled()) {
        std::fprintf(stderr,
            "APPGL_DETECTOR lift_post_encode prog=%u encodeOk=%d "
            "tfGeneratedVerts=%u tfRetainedOutBuf_present=%d "
            "-> writeTess_will_fire=%d\n",
            (unsigned)programName,
            encodeOk ? 1 : 0,
            (unsigned)tfGeneratedVerts,
            tfRetainedOutBuf != nullptr ? 1 : 0,
            (runTessTFWrite && tfGeneratedVerts > 0 && tfRetainedOutBuf != nullptr) ? 1 : 0);
    }

    if (runTessTFWrite && tfGeneratedVerts > 0 && tfRetainedOutBuf != nullptr) {
        id<MTLBuffer> tesOut =
            (id<MTLBuffer>)CFBridgingRelease(tfRetainedOutBuf);
        const std::uint8_t* bytes =
            static_cast<const std::uint8_t*>([tesOut contents]);
        // Per-vertex slot size = reflected struct size. The TES compute
        // kernel writes `spvOut[gl_GlobalInvocationID.x]` at this stride
        // (Metal lays out arrays of structs packed at `sizeof(main0_out)`).
        const std::size_t kTesComputeSlotBytes =
            program.tessEvalOutputLayout.structSize;
        // Topology from TES genMode: point_mode→GL_POINTS,
        // isolines→GL_LINES, else GL_TRIANGLES.
        GLenum topo = GL_TRIANGLES;
        if (program.tessGenPointMode == GL_TRUE) {
            topo = GL_POINTS;
        } else if (program.tessGenMode == GL_ISOLINES) {
            topo = GL_LINES;
        }
        writeTessTFAndUpdateCounters(program, bytes,
                                      tfGeneratedVerts,
                                      kTesComputeSlotBytes, topo);
	        if (encodeOk &&
	            !state->isEnabled(GL_RASTERIZER_DISCARD) &&
	            program.tessGenPointMode == GL_TRUE &&
	            topo == GL_POINTS) {
            const auto& layout = program.tessEvalOutputLayout;
            const StageOutputLayout::Member* positionMember = nullptr;
            const StageOutputLayout::Member* pointSizeMember = nullptr;
            struct ReplayVarying {
                const StageOutputLayout::Member* member = nullptr;
                std::uint32_t width = 0;
                std::uint8_t baseType = 0;
            };
            std::vector<ReplayVarying> replayVaryings;
            for (const auto& m : layout.members) {
                if (m.isBuiltIn && m.builtIn == spv::BuiltInPosition) {
                    positionMember = &m;
                } else if (m.isBuiltIn && m.builtIn == spv::BuiltInPointSize) {
                    pointSizeMember = &m;
                } else if (!m.isBuiltIn) {
                    const std::size_t bytesForGL =
                        m.glPackedBytes > 0 ? m.glPackedBytes : m.size;
                    if (bytesForGL > 0 && (bytesForGL % sizeof(float)) == 0) {
                        replayVaryings.push_back(
                            {&m, static_cast<std::uint32_t>(bytesForGL / sizeof(float)),
                             m.baseType});
                    }
                }
            }
            if (positionMember != nullptr) {
                bool replayHasPointSize = false;
                if (pointSizeMember != nullptr) {
                    for (std::uint32_t v = 0; v < tfGeneratedVerts; ++v) {
                        float pointSize = 0.0f;
                        std::memcpy(&pointSize,
                                    bytes + static_cast<std::size_t>(v) *
                                                kTesComputeSlotBytes +
                                                pointSizeMember->offset,
                                    sizeof(pointSize));
                        if (pointSize != 0.0f && std::isfinite(pointSize)) {
                            replayHasPointSize = true;
                            break;
                        }
                    }
                }
                appgl::EmulatedDraw replay;
                replay.ok = true;
                replay.topology = GL_POINTS;
                replay.vertexCount = tfGeneratedVerts;
                replay.hasPointSize = replayHasPointSize;
                replay.streamVertexCounts[0] = tfGeneratedVerts;
                std::size_t varyingFloats = 0;
                std::uint32_t nextLocation = 0;
                for (const ReplayVarying& rv : replayVaryings) {
                    replay.varyingNames.push_back(rv.member->name);
                    replay.varyingWidths.push_back(rv.width);
                    replay.varyingLocations.push_back(nextLocation);
                    replay.varyingInterp.push_back(0);
                    replay.varyingBaseType.push_back(rv.baseType);
                    replay.varyingScalarByteSize.push_back(sizeof(float));
                    replay.varyingStageSlotWidths.push_back(rv.width);
                    replay.varyingStageSlotLocations.push_back(nextLocation);
                    replay.varyingStageSlotInterp.push_back(0);
                    replay.varyingStageSlotBaseType.push_back(rv.baseType);
                    replay.varyingStageSlotScalarByteSize.push_back(sizeof(float));
                    varyingFloats += rv.width;
                    nextLocation += 1u;
                }
                replay.floatsPerVertex = 4u + varyingFloats +
                    (replay.hasPointSize ? 1u : 0u);
                replay.expandedVertexData.assign(
                    static_cast<std::size_t>(tfGeneratedVerts) *
                        replay.floatsPerVertex,
                    0.0f);
                for (std::uint32_t v = 0; v < tfGeneratedVerts; ++v) {
                    const std::uint8_t* src =
                        bytes + static_cast<std::size_t>(v) * kTesComputeSlotBytes;
                    float* dst = replay.expandedVertexData.data() +
                        static_cast<std::size_t>(v) * replay.floatsPerVertex;
                    std::memcpy(dst,
                                src + positionMember->offset,
                                sizeof(float) * 4);
                    std::size_t dstOff = 4;
                    for (const ReplayVarying& rv : replayVaryings) {
                        std::memcpy(dst + dstOff,
                                    src + rv.member->offset,
                                    static_cast<std::size_t>(rv.width) * sizeof(float));
                        dstOff += rv.width;
                    }
                    if (replay.hasPointSize) {
                        float pointSize = 1.0f;
                        if (pointSizeMember != nullptr) {
                            std::memcpy(&pointSize,
                                        src + pointSizeMember->offset,
                                        sizeof(pointSize));
                            if (pointSize == 0.0f || !std::isfinite(pointSize)) {
                                pointSize = 1.0f;
                            }
                        }
                        std::memcpy(dst + dstOff, &pointSize, sizeof(pointSize));
                    }
                }
                if (encodeEmulatedGsDraw(program, programName, replay)) {
                    return true;
                }
                return false;
            }
        }
        (void)tesOut;  // released by __bridge_transfer at scope exit
    }

    return encodeOk;
}

bool GLContext::Impl::tryMetalMeshGSDraw(GLProgramObject& program,
                                          GLuint programName,
                                          GLenum mode,
                                          GLsizei count,
                                          GLint first)
{
    (void)first;
    // MVP envelope guard. Phase 2 currently handles GL_POINTS draws
    // only — covers all 6 conversion-target failing tests
    // (gl_pointsize_value + 5 limits/api point-output cases). Lines
    // and triangles input land in a follow-up once point flow is
    // proven end-to-end.
    if (mode != GL_POINTS) return false;
    if (count <= 0) return false;
    if (program.metalGSTier != GLProgramObject::MetalGSTier::MeshShader) {
        return false;
    }
    void* meshVsComputePipelineState = program.metalGSVsComputePipelineState;
    std::vector<appgl::MetalTessVertexBufferBinding> meshVsBufferBindings;
    std::vector<GLuint> meshVsBufferNames;
    if ((meshVsComputePipelineState == nullptr &&
         !program.metalGSVsComputeNeedsDescriptor) ||
        program.metalGSMeshFunction == nullptr ||
        program.metalGSFragmentFunction == nullptr) {
        return false;
    }
    if (std::getenv("APPGL_TRACE_MESH_GS") != nullptr) {
        std::fprintf(stderr,
            "[MESH_GS] tryMetalMeshGSDraw enter: prog=%u mode=0x%X count=%d\n",
            programName, mode, count);
        std::fflush(stderr);
    }
    if (!program.geometryReflection.storageBuffers.empty() ||
        !program.fragmentReflection.storageBuffers.empty()) {
        if (std::getenv("APPGL_TRACE_MESH_GS") != nullptr) {
            std::fprintf(stderr,
                "[MESH_GS] reject native path: storage-buffer/atomic producers are not wired\n");
            std::fflush(stderr);
        }
        return false;
    }

    if (program.metalGSVsComputeNeedsDescriptor &&
        meshVsComputePipelineState == nullptr) {
        const GLuint vaoName = state->boundVertexArray();
        GLVertexArrayObject* vao = objects->vertexArrays().get(vaoName);
        if (vao == nullptr) {
            return false;
        }
        appgl::MetalVertexDescriptorBuildResult buildResult =
            appgl::buildMetalStageInputOutputDescriptor(*vao);
        if (buildResult.descriptor == nullptr) {
            return false;
        }
        auto cached = program.metalGSVsComputePSOCache.find(buildResult.hash);
        if (cached != program.metalGSVsComputePSOCache.end()) {
            meshVsComputePipelineState = cached->second;
        } else {
            std::string err;
            meshVsComputePipelineState = frameGraph->buildComputePipelineState(
                program.metalGSVsComputeMSL, &err, nullptr,
                buildResult.descriptor);
            if (meshVsComputePipelineState != nullptr) {
                program.metalGSVsComputePSOCache[buildResult.hash] =
                    meshVsComputePipelineState;
            } else if (std::getenv("APPGL_TRACE_MESH_GS") != nullptr) {
                std::fprintf(stderr,
                    "[MESH_GS] draw-time VS-compute PSO build failed: %s\n",
                    err.c_str());
            }
        }
        if (meshVsComputePipelineState != nullptr) {
            for (const auto& binding : buildResult.vertexBufferBindings) {
                GLBufferObject* vbo = objects->buffers().get(binding.glBuffer);
                if (vbo == nullptr || vbo->metalBuffer == nullptr) {
                    appgl::releaseMetalStageInputOutputDescriptor(
                        buildResult.descriptor);
                    return false;
                }
                appgl::MetalTessVertexBufferBinding ent;
                ent.metalBuffer = vbo->metalBuffer;
                ent.offset = 0;
                ent.metalSlot = binding.metalSlot;
                meshVsBufferBindings.push_back(ent);
                meshVsBufferNames.push_back(binding.glBuffer);
            }
        }
        appgl::releaseMetalStageInputOutputDescriptor(buildResult.descriptor);
        if (meshVsComputePipelineState == nullptr) {
            return false;
        }
    }

    // Resolve current FBO color + depth/stencil targets. Mirrors the
    // pattern used by encodeTranslatedDraw at the drawArrays call site.
    GLsizei fboW = 0, fboH = 0;
    void* fboDSTex = nullptr;
    std::uint32_t fboArrayLen = 0;
    void* fboColTex = resolveFBOColorTarget(fboW, fboH, fboDSTex, &fboArrayLen);
    if (fboColTex == nullptr) return false;

    appgl::MetalFrameGraph::MetalMeshGSDrawInfo info;
    info.vertexComputePipelineState = meshVsComputePipelineState;
    info.vertexComputeBufferBindings = std::move(meshVsBufferBindings);
    info.meshFunction = program.metalGSMeshFunction;
    info.fragmentFunction = program.metalGSFragmentFunction;
    info.meshPipelineStateInOut = &program.metalGSMeshPipelineState;
    info.vertexCount = static_cast<std::uint32_t>(count);
    info.primitiveCount = static_cast<std::uint32_t>(count);
    info.inputVerticesPerPrimitive = 1;
    info.outputTopologyMTLPrimitiveType = MTLPrimitiveTypePoint;
    info.vsOutputStrideBytes = 256;
    info.fboColorTexture = fboColTex;
    info.fboDepthStencilTexture = fboDSTex;
    info.fboWidth = static_cast<std::uint32_t>(fboW);
    info.fboHeight = static_cast<std::uint32_t>(fboH);
    info.fboColorArrayLength = fboArrayLen;

    // Per-stage default-uniform buffers. Compute the per-stage
    // layouts lazily (cached on the program) and write the current
    // uniform values through `buildStageUniformBuffer` — same path
    // the legacy translated-draw site uses (GLContext.mm:23992-23996).
    // For Phase-2 MVP the 6 conversion-target GS bodies don't
    // reference _DefaultUniforms (verified against the emitted mesh
    // MSL: no `constant _DefaultUniforms&` parameter), so meshUniform*
    // stays nullptr; if a future target does reference defaults from
    // the GS the same plumbing extends to the geometry stage.
    if (!program.uniformLayoutComputed) {
        computeStageUniformLayout(program.vertexUniformLayout,
            program.vertexReflection, program.uniforms);
        computeStageUniformLayout(program.fragmentUniformLayout,
            program.fragmentReflection, program.uniforms);
        program.uniformLayoutComputed = true;
    }
    thread_local std::vector<std::uint8_t> meshGsVtxUniformScratch;
    thread_local std::vector<std::uint8_t> meshGsFragUniformScratch;
    thread_local std::vector<std::uint8_t> meshGsGeomUniformScratch;
    thread_local std::vector<GLProgramObject::UniformLayoutEntry> meshGsGeomUniformLayout;
    if (pushSynthesizedMatrixUniforms(program, matrixState)) {
        program.markUniformsDirty();
    }
    computeStageUniformLayout(meshGsGeomUniformLayout,
        program.geometryReflection, program.uniforms);
    buildStageUniformBuffer(meshGsVtxUniformScratch,
        program.vertexReflection, program.uniformValues,
        program.vertexUniformLayout);
    buildStageUniformBuffer(meshGsFragUniformScratch,
        program.fragmentReflection, program.uniformValues,
        program.fragmentUniformLayout);
    buildStageUniformBuffer(meshGsGeomUniformScratch,
        program.geometryReflection, program.uniformValues,
        meshGsGeomUniformLayout);
    info.vsUniformData = meshGsVtxUniformScratch.data();
    info.vsUniformSize = meshGsVtxUniformScratch.size();
    info.fsUniformData = meshGsFragUniformScratch.data();
    info.fsUniformSize = meshGsFragUniformScratch.size();
    info.meshUniformData = meshGsGeomUniformScratch.data();
    info.meshUniformSize = meshGsGeomUniformScratch.size();

    TranslatedDrawInfo textureInfo;
    textureInfo.program = programName;
    textureInfo.fragmentReflection = &program.fragmentReflection;
    textureInfo.vertexReflection = &program.geometryReflection;
    resolveSamplerBindings(program, textureInfo);
    resolveImageBindings(program, textureInfo);
    info.meshTextures = std::move(textureInfo.vertexTextures);
    info.fragmentTextures = std::move(textureInfo.fragmentTextures);
    info.fragmentNeedsFragCoordParams =
        (program.fragmentMSL.find("_appgl_FragCoordParams") != std::string::npos);
    declareMeshGsSubmissionGroup(info, meshVsBufferNames, textureInfo);

    // GL render state — mirror encodeTranslatedDraw's tdi setup
    // (GLContext.mm:22172-22217) for the fields the mesh-render
    // encoder applies. Sourced from the same `state` (GLStateTracker)
    // accessor the legacy path uses.
    info.depthTestEnabled = state->isEnabled(GL_DEPTH_TEST);
    info.depthFunc = state->depthState().func;
    info.depthWriteMask = (state->depthState().writeMask != GL_FALSE);
    // Sprint 7 Phase 1 #11 (CKPT57): stencil state for mesh-GS path.
    {
        const auto& gs = state->stencilState();
        info.stencilTestEnabled = state->isEnabled(GL_STENCIL_TEST);
        info.stencilFrontFunc = gs.front.func;
        info.stencilFrontRef = gs.front.ref;
        info.stencilFrontValueMask = gs.front.valueMask;
        info.stencilFrontFail = gs.front.fail;
        info.stencilFrontDepthFail = gs.front.depthFail;
        info.stencilFrontDepthPass = gs.front.depthPass;
        info.stencilFrontWriteMask = gs.front.writeMask;
        info.stencilBackFunc = gs.back.func;
        info.stencilBackRef = gs.back.ref;
        info.stencilBackValueMask = gs.back.valueMask;
        info.stencilBackFail = gs.back.fail;
        info.stencilBackDepthFail = gs.back.depthFail;
        info.stencilBackDepthPass = gs.back.depthPass;
        info.stencilBackWriteMask = gs.back.writeMask;
    }
    info.cullFaceEnabled = state->isEnabled(GL_CULL_FACE);
    info.cullFaceMode = state->rasterState().cullFaceMode;
    info.frontFace = state->rasterState().frontFace;
    info.wireframe = (state->rasterState().polygonFillMode == GL_LINE);
    info.sampleMask =
        state->isEnabled(GL_SAMPLE_MASK)
            ? static_cast<std::uint32_t>(state->sampleMask(0))
            : 0xFFFFFFFFu;
    info.polygonOffsetEnabled =
        state->isEnabled(GL_POLYGON_OFFSET_FILL) ||
        state->isEnabled(GL_POLYGON_OFFSET_LINE) ||
        state->isEnabled(GL_POLYGON_OFFSET_POINT);
    info.polygonOffsetFactor = state->rasterState().polygonOffsetFactor;
    info.polygonOffsetUnits = state->rasterState().polygonOffsetUnits;
    info.polygonOffsetClamp = state->rasterState().polygonOffsetClamp;
    {
        const auto& vp = state->viewport();
        info.viewportX = vp.x;
        info.viewportY = vp.y;
        info.viewportWidth = vp.width;
        info.viewportHeight = vp.height;
    }
    {
        const auto& dr = state->depthRange();
        info.depthRangeNear = dr.nearValue;
        info.depthRangeFar = dr.farValue;
    }
    info.scissorTestEnabled = state->isEnabled(GL_SCISSOR_TEST);
    {
        const auto& sc = state->scissor();
        info.scissorX = sc.x;
        info.scissorY = sc.y;
        info.scissorWidth = sc.width;
        info.scissorHeight = sc.height;
    }
    // Sprint 17 Day 3+ BONUS-1 [clip_control]: snapshot
    // glClipControl origin for the mesh-GS path's viewport-Y-flip
    // gate. Sister to TranslatedDrawInfo's clipOrigin set in the
    // legacy path.
    info.clipOrigin = static_cast<std::uint32_t>(state->clipOrigin());

    const bool ok = frameGraph->encodeMetalMeshGSDraw(info);
    if (ok) {
        GpuResourceWriteSet producerWrites;
        const GLuint drawFboName = state->boundDrawFramebuffer();
        if (drawFboName != 0) {
            if (const GLFramebufferObject* drawFbo =
                    objects->framebuffers().get(drawFboName)) {
                appendFramebufferAttachmentWrites(producerWrites, *drawFbo);
            }
        }
        for (GLuint texName : textureInfo.writtenImageTextureNames) {
            producerWrites.push_back(
                {GpuResourceAccess::Kind::Texture, texName,
                 kProducerStorageImageWrite});
        }
        markGpuResourceWrites(producerWrites);
        if (drawFboName == 0) {
            invalidateDefaultFramebufferShadow();
        }
    }
    if (std::getenv("APPGL_TRACE_MESH_GS") != nullptr) {
        std::fprintf(stderr,
            "[MESH_GS] encodeMetalMeshGSDraw rc=%d diag=\"%s\"\n",
            ok ? 1 : 0, info.diagnostic.c_str());
        std::fflush(stderr);
    }
    return ok;
}

bool GLContext::Impl::encodeEmulatedGsDraw(GLProgramObject& program,
                                           GLuint programName,
                                           const appgl::EmulatedDraw& ed,
                                           AppGLSubmissionGroupKind fallbackSubgroupKind)
{
    if (APPGL_DCR_SENTINEL_HOOK("APPGL_DCR4E_FORCE_GS_RASTER_ENCODE_FAIL")) {
        return false;
    }
    // Resolve the FBO's layered-attachment state before we decide
    // whether the synth VS should emit `[[render_target_array_index]]`.
    // A GS that writes gl_Layer but targets a non-layered FBO
    // must NOT emit the render-target-array-index slot — Metal
    // rejects the combination of MSL writing that slot while
    // renderTargetArrayLength=0 and drops every fragment.
    GLsizei preFboW = 0, preFboH = 0;
    void* preFboDSTex = nullptr;
    std::uint32_t preFboArrayLen = 0;
    std::uint32_t preFboDSSlice = 0;
    std::uint32_t preFboDSLevel = 0;
    std::array<void*, 7> preExtraColTex = {};
    std::array<std::uint32_t, 8> preColorSlices = {};
    std::array<std::uint32_t, 8> preColorLevels = {};
    void* preFboColTex = resolveFBOColorTarget(
        preFboW, preFboH, preFboDSTex, &preFboArrayLen,
        &preExtraColTex, &preColorSlices, &preColorLevels,
        &preFboDSSlice, &preFboDSLevel);
    const GLuint preDrawFboName = state->boundDrawFramebuffer();
    const GLFramebufferObject* preDrawFbo =
        preDrawFboName != 0 ? objects->framebuffers().get(preDrawFboName) : nullptr;
    const bool preAttachmentlessFbo =
        preDrawFbo != nullptr &&
        preDrawFbo->attachments.empty() &&
        preDrawFbo->defaultWidth > 0 &&
        preDrawFbo->defaultHeight > 0;
    const std::uint32_t preAttachmentlessLayers =
        preAttachmentlessFbo
            ? static_cast<std::uint32_t>(
                  std::max<GLint>(preDrawFbo->defaultLayers, 0))
            : 0u;
    const bool fboIsLayered =
        (preFboColTex != nullptr && preFboArrayLen > 0) ||
        (preAttachmentlessFbo && preAttachmentlessLayers > 0);
    const bool routeLayer = ed.hasLayer && fboIsLayered;
    // Sprint 15 Day 10 [metal-viewport-array]: detect multi-viewport
    // binding (state divergence from slot 0). Originally env-gated on
    // `APPGL_ENABLE_METAL_VIEWPORT_INDEX` per CKPT181 because
    // unconditional emission regressed `viewport_array.provoking_vertex`.
    //
    // Sprint 16 Day 16 (CKPT225) traced the regression to the
    // 2-bug-cancellation phenomenon: provoking_vertex passed
    // pre-Sprint-16 with viewport routing OFF *because* the missing
    // Y-flip in `glGetTexImage` hid the wrong-viewport-region by
    // reading raw Metal-storage rows. With both bugs fixed together
    // (Day 17: re-enable viewport routing + Y-flip the readback in
    // `glGetTexImage`), the per-vertex `gl_ViewportIndex` actually
    // routes to the right rectangle and the readback agrees with
    // OpenGL Y-up convention.
    //
    // The state-divergence guard (only emit when at least one entry
    // 1..N differs from slot 0) stays in place — Metal pipelines that
    // never need multi-viewport stay on the cheap single-viewport
    // path.
    // Sprint 16 Day 19 (CKPT228) — also bind on scissor-array
    // divergence. CTS `viewport_array.scissor` /
    // `viewport_array.scissor_clear` set 16 per-index scissor rects
    // without ever calling glViewportArrayv, so the viewport-only
    // divergence check below stayed false. The encoder then took
    // the single-viewport / single-scissor path and dropped every
    // GS-emitted gl_ViewportIndex into slot 0. Mirroring the check
    // for scissor[1..N-1] vs scissor[0] routes those tests through
    // the array path so the `[[viewport_array_index]]` rasteriser
    // walk picks up the matching scissor rect.
    const bool routeViewportIndex = ed.hasViewportIndex &&
        [this]() -> bool {
            appgl::GLStateTracker::IndexedViewportEntry vparr[
                appgl::TranslatedDrawInfo::kMaxDrawViewports];
            std::size_t got = 0;
            this->state->getViewportArray(vparr,
                appgl::TranslatedDrawInfo::kMaxDrawViewports, &got);
            for (std::size_t i = 1; i < got; ++i) {
                if (vparr[i].x != vparr[0].x ||
                    vparr[i].y != vparr[0].y ||
                    vparr[i].width != vparr[0].width ||
                    vparr[i].height != vparr[0].height ||
                    vparr[i].depthNear != vparr[0].depthNear ||
                    vparr[i].depthFar != vparr[0].depthFar) {
                    return true;
                }
            }
            appgl::GLStateTracker::IndexedScissorEntry scarr[
                appgl::TranslatedDrawInfo::kMaxDrawViewports];
            std::size_t scgot = 0;
            this->state->getScissorArray(scarr,
                appgl::TranslatedDrawInfo::kMaxDrawViewports, &scgot);
            for (std::size_t i = 1; i < scgot; ++i) {
                if (scarr[i].x != scarr[0].x ||
                    scarr[i].y != scarr[0].y ||
                    scarr[i].width != scarr[0].width ||
                    scarr[i].height != scarr[0].height ||
                    scarr[i].enabled != scarr[0].enabled) {
                    return true;
                }
            }
            return false;
        }();

    // Sprint 17 Day 1 (CKPT236) [A.2 narrow gate]: mark the bound
    // draw-FBO's colour attachments as viewport-rendered-to ONLY
    // when this draw will engage the viewport-flipped Metal write
    // path (`routeViewportIndex == true`). Replaces the over-broad
    // binding-time set in `framebufferTexture` (Sprint 16 Day 17 /
    // CKPT226) — that set fired for DSA multisample storage and
    // texture_barrier tests that bind a texture as colour
    // attachment but never engage the viewport-flipped write,
    // causing 58 false-positive Y-flips on `glGetTexImage`
    // readback (CKPT236 bisect).
    //
    // Single-viewport draws (where `routeViewportIndex == false`)
    // do NOT set the flag here; their writes either don't happen
    // (DSA storage allocation), don't apply viewport flip
    // (texture_barrier render-to-self with single viewport), or
    // are otherwise opaque-byte-pattern preserved. The 4 +4
    // viewport_array DUAL-FIX wins all use multi-viewport draws,
    // so they DO engage `routeViewportIndex` and DO set the flag,
    // preserving the +4 wins via correct Y-flip on readback.
    // Sprint 17 Day 3+ BONUS-1 [clip_control]: also gate on
    // `state->clipOrigin() == GL_LOWER_LEFT`. The flag's contract is
    // "this texture has Y-flipped contents that need readback-unflip"
    // — but under `glClipControl(GL_UPPER_LEFT, _)` the viewport
    // descriptor's Y-flip is OFF (BONUS-1.2 gate at MetalFrameGraph
    // viewport-bind sites), so the texture's Metal storage is already
    // top-down and `glGetTexImage` should return it unflipped.
    // Setting the flag in that case would trigger a spurious readback
    // flip and corrupt the result on UPPER_LEFT draws.
    if (routeViewportIndex && state->clipOrigin() == GL_LOWER_LEFT) {
        const GLuint fboName = state->boundDrawFramebuffer();
        if (fboName != 0) {
            if (const GLFramebufferObject* fbo =
                    objects->framebuffers().get(fboName)) {
                for (const auto& kv : fbo->attachments) {
                    if (!isColorAttachment(kv.first)) continue;
                    if (kv.second.kind !=
                            GLFramebufferAttachment::Kind::Texture) continue;
                    if (GLTextureObject* mut =
                            objects->textures().get(kv.second.object)) {
                        mut->wasViewportRenderedTo = true;
                    }
                }
            }
        }
    }

    appgl::EmulatedDraw replayDraw = ed;
    auto remapGsVaryingLocationsFromFragmentMSL =
        [](appgl::EmulatedDraw& draw, const std::string& fragmentMSL) {
            if (draw.varyingNames.empty() || fragmentMSL.empty()) return;
            const std::size_t structPos = fragmentMSL.find("struct main0_in");
            if (structPos == std::string::npos) return;
            const std::size_t bodyBegin = fragmentMSL.find('{', structPos);
            const std::size_t bodyEnd = fragmentMSL.find("};", bodyBegin);
            if (bodyBegin == std::string::npos || bodyEnd == std::string::npos) return;

            std::unordered_map<std::string, std::uint32_t> fsInputLocations;
            std::size_t cursor = bodyBegin + 1;
            while (cursor < bodyEnd) {
                const std::size_t semi = fragmentMSL.find(';', cursor);
                if (semi == std::string::npos || semi > bodyEnd) break;
                const std::string line = fragmentMSL.substr(cursor, semi - cursor);
                cursor = semi + 1;

                const std::size_t userPos = line.find("[[user(locn");
                if (userPos == std::string::npos) continue;
                const std::size_t locBegin = userPos + std::strlen("[[user(locn");
                std::size_t locEnd = locBegin;
                while (locEnd < line.size() &&
                       line[locEnd] >= '0' && line[locEnd] <= '9') {
                    ++locEnd;
                }
                if (locEnd == locBegin) continue;

                std::size_t nameEnd = userPos;
                while (nameEnd > 0 &&
                       std::isspace(static_cast<unsigned char>(line[nameEnd - 1]))) {
                    --nameEnd;
                }
                std::size_t nameBegin = nameEnd;
                while (nameBegin > 0) {
                    const unsigned char ch =
                        static_cast<unsigned char>(line[nameBegin - 1]);
                    if (!(std::isalnum(ch) || ch == '_')) break;
                    --nameBegin;
                }
                if (nameBegin == nameEnd) continue;

                const std::string name = line.substr(nameBegin, nameEnd - nameBegin);
                const std::uint32_t loc = static_cast<std::uint32_t>(
                    std::strtoul(line.c_str() + locBegin, nullptr, 10));
                fsInputLocations[name] = loc;
            }
            const std::vector<std::uint32_t> originalVaryingLocations =
                draw.varyingLocations;
            const std::vector<std::uint32_t> originalStageSlotLocations =
                draw.varyingStageSlotLocations;
            std::unordered_set<std::uint32_t> fsLocations;
            for (const auto& kv : fsInputLocations) {
                fsLocations.insert(kv.second);
            }

            struct RemapEntry {
                std::size_t varyingIndex = 0;
                std::uint32_t oldLoc = 0;
                std::uint32_t newLoc = 0;
                std::uint32_t slotCount = 1;
                std::uint32_t stageSlotIndex = 0;
                bool assigned = false;
            };
            std::vector<RemapEntry> entries;
            entries.reserve(draw.varyingNames.size());

            std::uint32_t stageSlotIndex = 0;
            for (std::size_t i = 0; i < draw.varyingNames.size(); ++i) {
                const std::uint32_t oldLoc =
                    i < originalVaryingLocations.size() ? originalVaryingLocations[i] : 0u;
                std::uint32_t slotCount = 1;
                if (!originalStageSlotLocations.empty() &&
                    stageSlotIndex < originalStageSlotLocations.size()) {
                    const std::uint32_t nextOldLoc =
                        (i + 1 < originalVaryingLocations.size())
                            ? originalVaryingLocations[i + 1]
                            : ~0u;
                    slotCount = 0;
                    while (stageSlotIndex + slotCount <
                           originalStageSlotLocations.size()) {
                        const std::uint32_t slotOldLoc =
                            originalStageSlotLocations[stageSlotIndex + slotCount];
                        if (slotCount > 0 && slotOldLoc >= nextOldLoc) break;
                        if (nextOldLoc != ~0u && slotOldLoc >= nextOldLoc) break;
                        ++slotCount;
                    }
                    slotCount = std::max<std::uint32_t>(slotCount, 1u);
                }
                entries.push_back({i, oldLoc, oldLoc, slotCount, stageSlotIndex, false});
                stageSlotIndex += slotCount;
            }

            std::unordered_set<std::uint32_t> claimedLocations;
            auto rangeFreeIn = [](const std::unordered_set<std::uint32_t>& occupied,
                                  std::uint32_t loc,
                                  std::uint32_t count) -> bool {
                for (std::uint32_t slot = 0; slot < count; ++slot) {
                    if (occupied.find(loc + slot) != occupied.end()) {
                        return false;
                    }
                }
                return true;
            };
            auto markRange = [](std::unordered_set<std::uint32_t>& occupied,
                                std::uint32_t loc,
                                std::uint32_t count) {
                for (std::uint32_t slot = 0; slot < count; ++slot) {
                    occupied.insert(loc + slot);
                }
            };
            auto rangeFreeForExtra =
                [&](std::uint32_t loc, std::uint32_t count) -> bool {
                    return rangeFreeIn(fsLocations, loc, count) &&
                           rangeFreeIn(claimedLocations, loc, count);
                };

            // Exact names are authoritative. Block-member rewrites can
            // rename otherwise-linked varyings (`output_block_*` ->
            // `input_block_*`), so unmatched entries get a second chance
            // to keep an original FS location before extras are relocated.
            for (RemapEntry& entry : entries) {
                const auto locIt = fsInputLocations.find(
                    draw.varyingNames[entry.varyingIndex]);
                if (locIt == fsInputLocations.end()) continue;
                entry.newLoc = locIt->second;
                entry.assigned = true;
                markRange(claimedLocations, entry.newLoc, entry.slotCount);
            }
            for (RemapEntry& entry : entries) {
                if (entry.assigned) continue;
                if (fsLocations.find(entry.oldLoc) == fsLocations.end()) continue;
                if (!rangeFreeIn(claimedLocations, entry.oldLoc, entry.slotCount)) continue;
                entry.newLoc = entry.oldLoc;
                entry.assigned = true;
                markRange(claimedLocations, entry.newLoc, entry.slotCount);
            }
            std::uint32_t nextFreeLocation = 0;
            for (RemapEntry& entry : entries) {
                if (entry.assigned) continue;
                if (rangeFreeForExtra(entry.oldLoc, entry.slotCount)) {
                    entry.newLoc = entry.oldLoc;
                } else {
                    while (!rangeFreeForExtra(nextFreeLocation, entry.slotCount)) {
                        ++nextFreeLocation;
                    }
                    entry.newLoc = nextFreeLocation;
                }
                entry.assigned = true;
                markRange(claimedLocations, entry.newLoc, entry.slotCount);
            }

            bool changed = false;
            for (const RemapEntry& entry : entries) {
                if (entry.varyingIndex < draw.varyingLocations.size() &&
                    draw.varyingLocations[entry.varyingIndex] != entry.newLoc) {
                    draw.varyingLocations[entry.varyingIndex] = entry.newLoc;
                    changed = true;
                }
                for (std::uint32_t slot = 0;
                     slot < entry.slotCount &&
                     entry.stageSlotIndex + slot < draw.varyingStageSlotLocations.size();
                     ++slot) {
                    const std::uint32_t slotLoc = entry.newLoc + slot;
                    if (draw.varyingStageSlotLocations[entry.stageSlotIndex + slot] != slotLoc) {
                        draw.varyingStageSlotLocations[entry.stageSlotIndex + slot] = slotLoc;
                        changed = true;
                    }
                }
            }
            if (changed && draw.hasPrimitiveID) {
                std::uint32_t maxLoc = 0;
                const auto& locs = draw.varyingStageSlotLocations.empty()
                    ? draw.varyingLocations : draw.varyingStageSlotLocations;
                for (std::uint32_t loc : locs) maxLoc = std::max(maxLoc, loc);
                draw.primitiveIDLocation = locs.empty() ? 0u : (maxLoc + 1u);
            }
        };
    remapGsVaryingLocationsFromFragmentMSL(replayDraw, program.fragmentMSL);

    // Invalidate the cached synth VS when its layered-ness doesn't
    // match the current draw. Metal won't accept swapping the
    // `[[render_target_array_index]]` declaration on an existing
    // pipeline, so we rebuild from scratch. The pipeline cache
    // flushed too (same rebuild-on-next-draw path).
    if (!program.gsPassThroughVertexMSL.empty() &&
        (program.gsPassThroughVertexMSLLayered != routeLayer ||
         program.gsPassThroughVertexMSLViewportArray != routeViewportIndex)) {
        program.gsPassThroughVertexMSL.clear();
        program.gsPassThroughVertexMslUsesArgumentBuffer = false;
        for (auto& entry : program.gsPassThroughPipelineStateCache) {
            releaseRetainedMetalObject(entry.second);
        }
        program.gsPassThroughPipelineStateCache.clear();
        releaseRetainedMetalObject(program.gsPassThroughPipelineState);
        program.gsPassThroughPipelineState = nullptr;
        program.gsPassThroughPipelineColorFormat = 0;
        releaseRetainedMetalObject(program.gsPassThroughVertexFunction);
        program.gsPassThroughVertexFunction = nullptr;
        releaseRetainedMetalObject(program.gsPassThroughFragmentFunction);
        program.gsPassThroughFragmentFunction = nullptr;
        // Also invalidate the FS rewrite: its primitive-id input
        // location is derived from the synth-VS output layout; if
        // the VS rebuilds, the FS has to follow so MSL's
        // user(locnN) linkage stays in sync.
        program.gsPassThroughFragmentMSL.clear();
        program.gsPassThroughFragmentMslUsesArgumentBuffer = false;
        program.gsPassThroughFragmentMSLActive = false;
    }

    // Synthesise the pass-through VS once per program (cache on
    // the program object — the layout/widths/locations are fixed
    // at link time by the GS SPIR-V, which doesn't change draw-to-
    // draw). Matching reflection + attribute layout built from the
    // same `ed` so Metal's vertex descriptor picks the right formats.
    if (program.gsPassThroughVertexMSL.empty()) {
        program.gsPassThroughVertexMSL = appgl::synthesisePassThroughVertexMSL(
            replayDraw, routeLayer, routeViewportIndex);
        program.gsPassThroughVertexMslUsesArgumentBuffer =
            mslUsesArgumentBuffer(program.gsPassThroughVertexMSL);
        program.gsPassThroughVertexMSLLayered = routeLayer;
        program.gsPassThroughVertexMSLViewportArray = routeViewportIndex;
        if (std::getenv("APPGL_GS_DUMP_MSL") != nullptr) {
            std::fprintf(stderr, "\n[GS] synth VS MSL (routeLayer=%d hasLayer=%d clipLen=%u cullLen=%u):\n%s\n",
                (int)routeLayer, (int)replayDraw.hasLayer, replayDraw.clipDistanceLen, replayDraw.cullDistanceLen,
                program.gsPassThroughVertexMSL.c_str());
        }
        program.gsPassThroughReflection = ShaderReflection{};
        {
            ShaderReflection::VertexInput pos;
            pos.location = 0;
            pos.sourceLocation = pos.location;
            pos.type = GL_FLOAT_VEC4;
            pos.name = "vsin_position";
            program.gsPassThroughReflection.vertexInputs.push_back(pos);
        }
        const auto& stageSlotWidths = replayDraw.varyingStageSlotWidths.empty()
            ? replayDraw.varyingWidths : replayDraw.varyingStageSlotWidths;
        const auto& stageSlotBaseType = replayDraw.varyingStageSlotBaseType.empty()
            ? replayDraw.varyingBaseType : replayDraw.varyingStageSlotBaseType;
        for (std::size_t i = 0; i < stageSlotWidths.size(); ++i) {
            ShaderReflection::VertexInput vi;
            vi.location = static_cast<GLuint>(i + 1);
            vi.sourceLocation = vi.location;
            const std::uint8_t bt = (i < stageSlotBaseType.size())
                ? stageSlotBaseType[i] : 0;
            const std::uint32_t w = stageSlotWidths[i];
            if (bt == 1) {
                switch (w) {
                    case 1: vi.type = GL_INT;      break;
                    case 2: vi.type = GL_INT_VEC2; break;
                    case 3: vi.type = GL_INT_VEC3; break;
                    case 4: vi.type = GL_INT_VEC4; break;
                    default: vi.type = GL_INT;     break;
                }
            } else if (bt == 2) {
                switch (w) {
                    case 1: vi.type = GL_UNSIGNED_INT;      break;
                    case 2: vi.type = GL_UNSIGNED_INT_VEC2; break;
                    case 3: vi.type = GL_UNSIGNED_INT_VEC3; break;
                    case 4: vi.type = GL_UNSIGNED_INT_VEC4; break;
                    default: vi.type = GL_UNSIGNED_INT;     break;
                }
            } else {
                switch (w) {
                    case 1: vi.type = GL_FLOAT;      break;
                    case 2: vi.type = GL_FLOAT_VEC2; break;
                    case 3: vi.type = GL_FLOAT_VEC3; break;
                    case 4: vi.type = GL_FLOAT_VEC4; break;
                    default: vi.type = GL_FLOAT;     break;
                }
            }
            vi.name = "vsin_v" + std::to_string(i);
            program.gsPassThroughReflection.vertexInputs.push_back(vi);
        }
        // Clip + cull distance input attributes, one float per slot.
        // Stored immediately after the last user varying in the same
        // packed vertex buffer. Location indices (for reflection)
        // follow the varying block; Metal attribute indices are
        // allocated the same way in the synth VS MSL so these match.
        const GLuint clipBaseLoc =
            static_cast<GLuint>(stageSlotWidths.size() + 1);
        for (std::uint32_t i = 0; i < replayDraw.clipDistanceLen; ++i) {
            ShaderReflection::VertexInput vi;
            vi.location = clipBaseLoc + i;
            vi.sourceLocation = vi.location;
            vi.type = GL_FLOAT;
            vi.name = "vsin_clip" + std::to_string(i);
            program.gsPassThroughReflection.vertexInputs.push_back(vi);
        }
        const GLuint cullBaseLoc = clipBaseLoc + replayDraw.clipDistanceLen;
        for (std::uint32_t i = 0; i < replayDraw.cullDistanceLen; ++i) {
            ShaderReflection::VertexInput vi;
            vi.location = cullBaseLoc + i;
            vi.sourceLocation = vi.location;
            vi.type = GL_FLOAT;
            vi.name = "vsin_cull" + std::to_string(i);
            program.gsPassThroughReflection.vertexInputs.push_back(vi);
        }
        // Sprint 7 Phase 1 #6 (CKPT58): trailing per-vertex slots
        // (gl_Layer, gl_PointSize, gl_PrimitiveID) used to be exposed
        // as `[[attribute(N)]]` stage_in entries here, but Metal's
        // 31-attribute hardware cap made the synth-VS pipeline
        // silently drop the 32nd attribute when GS uses the GL spec-
        // floor MAX_GEOMETRY_OUTPUT_COMPONENTS = 128 (30 ivec4 varyings
        // + position + pointSize = 32 attributes). The synth-VS now
        // reads these slots directly from the packed buffer at slot 0
        // via `gs_packed[vid * stride + offset]`, which keeps the
        // per-vertex byte layout unchanged but saves up to 3 stage_in
        // attribute slots. We intentionally do NOT push reflection /
        // attribute-layout entries for them here.
        (void)cullBaseLoc;
    }

    TranslatedDrawInfo& tdi = reusableTranslatedDrawInfo();
    tdi.fallbackSubgroupKind =
        fallbackSubgroupKind != AppGLSubmissionGroupKind::None
            ? fallbackSubgroupKind
            : (program.gsPresent ? AppGLSubmissionGroupKind::CpuGsExpansion
                                 : AppGLSubmissionGroupKind::None);
    tdi.mode = replayDraw.topology;
    tdi.vertexCount = static_cast<GLsizei>(replayDraw.vertexCount);
    tdi.vertexData = replayDraw.expandedVertexData.data();
    tdi.vertexDataByteCount = replayDraw.expandedVertexData.size() * sizeof(float);
    tdi.vertexStride = replayDraw.floatsPerVertex * sizeof(float);

    {
        std::size_t offset = 0;
        {
            TranslatedDrawInfo::VertexAttributeLayout la;
            la.location = 0;
            la.offset = offset;
            la.glType = GL_FLOAT;
            la.glComponentCount = 4;
            tdi.vertexAttributeLayouts.push_back(la);
            offset += 4 * sizeof(float);
        }
        const auto& stageSlotWidths = replayDraw.varyingStageSlotWidths.empty()
            ? replayDraw.varyingWidths : replayDraw.varyingStageSlotWidths;
        const auto& stageSlotBaseType = replayDraw.varyingStageSlotBaseType.empty()
            ? replayDraw.varyingBaseType : replayDraw.varyingStageSlotBaseType;
        for (std::size_t i = 0; i < stageSlotWidths.size(); ++i) {
            TranslatedDrawInfo::VertexAttributeLayout la;
            la.location = static_cast<GLuint>(i + 1);
            la.offset = offset;
            const std::uint8_t bt = (i < stageSlotBaseType.size())
                ? stageSlotBaseType[i] : 0;
            if (bt == 1) {
                la.glType = GL_INT;
                la.glIsInteger = true;
            } else if (bt == 2) {
                la.glType = GL_UNSIGNED_INT;
                la.glIsInteger = true;
            } else {
                la.glType = GL_FLOAT;
            }
            la.glComponentCount = static_cast<GLint>(stageSlotWidths[i]);
            tdi.vertexAttributeLayouts.push_back(la);
            offset += stageSlotWidths[i] * sizeof(float);
        }
        // Clip / cull distance attribute layouts, in order, one float
        // per slot. They share the same packed buffer with the other
        // attributes; the encoder's vertex-descriptor builder reads
        // TranslatedDrawInfo::vertexAttributeLayouts to set up
        // MTLVertexDescriptor's per-attribute format + offset.
        const GLuint clipBaseLoc =
            static_cast<GLuint>(stageSlotWidths.size() + 1);
        for (std::uint32_t i = 0; i < replayDraw.clipDistanceLen; ++i) {
            TranslatedDrawInfo::VertexAttributeLayout la;
            la.location = clipBaseLoc + i;
            la.offset = offset;
            la.glType = GL_FLOAT;
            la.glComponentCount = 1;
            tdi.vertexAttributeLayouts.push_back(la);
            offset += sizeof(float);
        }
        const GLuint cullBaseLoc = clipBaseLoc + replayDraw.clipDistanceLen;
        for (std::uint32_t i = 0; i < replayDraw.cullDistanceLen; ++i) {
            TranslatedDrawInfo::VertexAttributeLayout la;
            la.location = cullBaseLoc + i;
            la.offset = offset;
            la.glType = GL_FLOAT;
            la.glComponentCount = 1;
            tdi.vertexAttributeLayouts.push_back(la);
            offset += sizeof(float);
        }
        // Sprint 7 Phase 1 #6 (CKPT58): no vertex attribute layouts
        // for the trailing gl_Layer / gl_PointSize / gl_PrimitiveID
        // slots — synth-VS reads them via direct buffer access. The
        // per-vertex stride must STILL include their bytes (the
        // packed buffer layout is unchanged), so advance `offset`
        // through the trailing slots without pushing layouts. This
        // keeps `tdi.vertexStride` matching the actual per-vertex
        // byte count and the manual buffer reads point at the right
        // position.
        if (replayDraw.hasLayer)        offset += sizeof(std::int32_t);
        if (replayDraw.hasPointSize)    offset += sizeof(float);
        if (replayDraw.hasPrimitiveID)  offset += sizeof(std::int32_t);
    }

    populateTranslatedDrawFixedFunctionState(tdi, *state, GL_SHADING_RATE_1X1_PIXELS_EXT);
    // The CPU GS path replays GS output through a synthetic VS/FS pair.
    // Keep that replay at the GL default rate so FSR state from a prior
    // suite cannot attach a Metal rate map to the emulated GS render pass.
    // CPU tess/GS emulation replays GL clip-space vertices through a synthetic
    // Metal VS. Under LOWER_LEFT, the render target rows need the same texture
    // readback unflip as viewport-routed GS outputs.
    const bool cpuExpandedDomain =
        program.gsPresent ||
        program.hasTessellation ||
        replayDraw.tessOutputVerticesPerPatch != 0;
    phase2PlanSetFixedStateBool(
        tdi,
        tdi.markColorAttachmentReadbackFlip,
        tdi.clipOrigin == GL_LOWER_LEFT &&
            (routeViewportIndex || cpuExpandedDomain));
    tdi.vertexMSL = &program.gsPassThroughVertexMSL;
    // Post-process the FS MSL for GS-emulation replay. PrimitiveID needs
    // a user-varying redirect; fp64 stage inputs need float transport
    // because Metal rejects nested appgl_df64 structs in [[stage_in]].
    const auto& stageSlotScalarBytes = replayDraw.varyingStageSlotScalarByteSize.empty()
        ? replayDraw.varyingScalarByteSize : replayDraw.varyingStageSlotScalarByteSize;
    bool needsFp64StageInRewrite = false;
    for (std::uint8_t bytes : stageSlotScalarBytes) {
        if (bytes == sizeof(double)) {
            needsFp64StageInRewrite = true;
            break;
        }
    }
    if (replayDraw.hasPrimitiveID || needsFp64StageInRewrite) {
        if (program.gsPassThroughFragmentMSL.empty()
            || program.gsPassThroughFragmentMSLPrimIdLoc != replayDraw.primitiveIDLocation) {
            std::string rewrittenFragment = program.fragmentMSL;
            if (needsFp64StageInRewrite) {
                rewrittenFragment =
                    appgl::rewriteFragmentMSLForFp64StageIn(rewrittenFragment);
            }
            if (replayDraw.hasPrimitiveID) {
                rewrittenFragment =
                    appgl::rewriteFragmentMSLForPrimitiveID(rewrittenFragment, replayDraw);
            }
            program.gsPassThroughFragmentMSL = std::move(rewrittenFragment);
            program.gsPassThroughFragmentMslUsesArgumentBuffer =
                mslUsesArgumentBuffer(program.gsPassThroughFragmentMSL);
            program.gsPassThroughFragmentMSLPrimIdLoc = replayDraw.primitiveIDLocation;
            program.gsPassThroughFragmentMSLActive = true;
            // Rebuilding FS invalidates any cached pipeline state.
            for (auto& entry : program.gsPassThroughPipelineStateCache) {
                releaseRetainedMetalObject(entry.second);
            }
            program.gsPassThroughPipelineStateCache.clear();
            releaseRetainedMetalObject(program.gsPassThroughPipelineState);
            program.gsPassThroughPipelineState = nullptr;
            program.gsPassThroughPipelineColorFormat = 0;
            releaseRetainedMetalObject(program.gsPassThroughFragmentFunction);
            program.gsPassThroughFragmentFunction = nullptr;
            if (std::getenv("APPGL_GS_DUMP_MSL") != nullptr) {
                std::fprintf(stderr, "\n[GS] rewritten FS MSL (primIdLoc=%u fp64StageIn=%d, %zu bytes)\n",
                    replayDraw.primitiveIDLocation, needsFp64StageInRewrite ? 1 : 0,
                    program.gsPassThroughFragmentMSL.size());
            }
        }
        tdi.fragmentMSL = &program.gsPassThroughFragmentMSL;
        tdi.fragmentMslUsesArgumentBuffer =
            program.gsPassThroughFragmentMslUsesArgumentBuffer;
    } else {
        tdi.fragmentMSL = &program.fragmentMSL;
        tdi.fragmentMslUsesArgumentBuffer =
            program.fragmentMslUsesArgumentBuffer;
    }
    tdi.vertexMslUsesArgumentBuffer =
        program.gsPassThroughVertexMslUsesArgumentBuffer;
    tdi.vertexReflection = &program.gsPassThroughReflection;
    tdi.fragmentReflection = &program.fragmentReflection;
    tdi.pipelineStateOut = &program.gsPassThroughPipelineState;
    tdi.pipelineColorFormatOut = &program.gsPassThroughPipelineColorFormat;
    tdi.pipelineStateCacheOut = &program.gsPassThroughPipelineStateCache;
    tdi.metalVertexFunction = program.gsPassThroughVertexFunction;
    tdi.metalFragmentFunction = program.gsPassThroughFragmentFunction;
    tdi.metalVertexFunctionOut = &program.gsPassThroughVertexFunction;
    tdi.metalFragmentFunctionOut = &program.gsPassThroughFragmentFunction;
    tdi.program = programName;
    tdi.pipelineEmulationFragmentProgram =
        program.pipelineEmulationFragmentProgram;

    if (!program.uniformLayoutComputed) {
        computeStageUniformLayout(program.vertexUniformLayout,
            program.vertexReflection, uniformsForEmulationStage(program, 0));
        computeStageUniformLayout(program.fragmentUniformLayout,
            program.fragmentReflection, uniformsForEmulationStage(program, 4));
        program.uniformLayoutComputed = true;
    }
    thread_local std::vector<std::uint8_t> gsFragUniformScratch;
    buildStageUniformBuffer(gsFragUniformScratch,
        program.fragmentReflection, uniformValuesForEmulationStage(program, 4),
        program.fragmentUniformLayout);
    tdi.vertexUniformData = nullptr;
    tdi.vertexUniformSize = 0;
    tdi.fragmentUniformData = gsFragUniformScratch.data();
    tdi.fragmentUniformSize = gsFragUniformScratch.size();

    resolveSamplerBindings(program, tdi);
    resolveUBOBindings(program, tdi);
    resolveSSBOBindings(program, tdi);
    resolveImageBindings(program, tdi);

    if (preFboColTex != nullptr || preFboDSTex != nullptr || preAttachmentlessFbo) {
        tdi.fboColorTexture = preFboColTex;
        tdi.fboAdditionalColorTextures = preExtraColTex;
        tdi.fboColorSlices = preColorSlices;
        tdi.fboColorLevels = preColorLevels;
        tdi.fboDepthStencilTexture = preFboDSTex;
        tdi.fboDepthStencilSlice = preFboDSSlice;
        tdi.fboDepthStencilLevel = preFboDSLevel;
        tdi.fboWidth = preAttachmentlessFbo ? preDrawFbo->defaultWidth : preFboW;
        tdi.fboHeight = preAttachmentlessFbo ? preDrawFbo->defaultHeight : preFboH;
        tdi.fboAttachmentless = preAttachmentlessFbo &&
            preFboColTex == nullptr &&
            preFboDSTex == nullptr;
        tdi.fboDefaultLayers = preAttachmentlessLayers;
        // Only honour layered-attachment routing when the emulated
        // GS actually wrote gl_Layer AND the FBO is layered. In
        // the GS-wrote but non-layered case the synth VS didn't
        // emit [[render_target_array_index]] (see routeLayer
        // branch at function entry), so we must leave
        // renderTargetArrayLength at 0 to match.
        if (routeLayer) {
            tdi.fboColorArrayLength =
                preAttachmentlessFbo ? preAttachmentlessLayers : preFboArrayLen;
            // Sprint 17 Day 1 (CKPT236) [Probe A 2DMSArray clamp]:
            // forward GS-emul-tracked max emitted layer so
            // `encodeTranslatedDraw` can clamp `renderTargetArrayLength`
            // for MS-array attachments (h2DM-3 AGX assertion fix).
            tdi.maxEmittedLayer = replayDraw.maxEmittedLayer;
        }
    }

    thread_local std::string gsPipelineBuildError;
    gsPipelineBuildError.clear();
    tdi.pipelineBuildErrorOut = &gsPipelineBuildError;

    const bool ok = encodeTranslatedDrawAndMarkFbo(tdi);
    if (!ok && std::getenv("APPGL_TRACE_VS_SSBO_EMUL")) {
        std::fprintf(stderr,
            "[VS-SSBO-emul] encodeEmulatedGsDraw failed: %s\n",
            gsPipelineBuildError.c_str());
    }
    return ok;
}

// Sprint 17 Day 7+ Bank-Group-H Path B Component D-γ — see header
// comment on the Impl method declaration. Sister-pattern leverage
// (Item 26 LIVE 18th-instance) with the drawElements internal
// translated-pipeline setup at GLContext::drawElements (~line 29291);
// kept as a separate function rather than a refactor of drawElements
// to minimise regression-test surface on the existing path.
bool GLContext::Impl::dispatchCullFilteredDraw(
        GLProgramObject& program,
        GLVertexArrayObject& vao,
        GLuint programName,
        GLenum mode,
        const std::vector<std::uint32_t>& filteredIndices) {
    if (filteredIndices.empty()) {
        return true;
    }
    if (!program.hasTranslatedPipeline) {
        return false;
    }
    if (vao.attributes.empty() || frameGraph == nullptr) {
        return false;
    }

    bool vaoLayoutCacheHit = false;
    const auto& vaoLayout =
        cachedVertexArrayLayout(
            vao, false, &vaoLayoutCacheHit,
            false, false, &coldPathProfile);
    if (!vaoLayout.hasEnabledAttributes) {
        return false;
    }
    GLBufferObject* vbo = (vaoLayout.primaryBufferName != 0)
        ? objects->buffers().get(vaoLayout.primaryBufferName)
        : nullptr;
    if (vbo == nullptr || vbo->shadowBytes.empty()) {
        return false;
    }
    const std::size_t posStride = vaoLayout.primaryStride;
    const std::size_t startOff = vaoLayout.primaryBaseOffset;
    if (startOff > vbo->shadowBytes.size()) {
        return false;
    }

    TranslatedDrawInfo& tdi = reusableTranslatedDrawInfo();
    tdi.mode = mode;
    tdi.vertexCount = static_cast<GLsizei>(filteredIndices.size());
    tdi.vertexData = vbo->shadowBytes.data() + startOff;
    tdi.vertexDataByteCount = vbo->shadowBytes.size() - startOff;
    tdi.vertexStride = posStride;
    tdi.metalVertexBuffer = vbo->metalBuffer;
    tdi.metalVertexBufferOffset = startOff;
    tdi.glVertexBuffer = vaoLayout.primaryBufferName;
    // Filtered indices fed as UINT32 client-side index array;
    // encodeTranslatedDraw stages them into a Metal ring buffer.
    tdi.indices = filteredIndices.data();
    tdi.indexCount = static_cast<GLsizei>(filteredIndices.size());
    tdi.indexType = GL_UNSIGNED_INT;

    populateTranslatedDrawFixedFunctionState(
        tdi, *state, effectiveFragmentShadingRateForProgram(*owner, &program), owner);
    phase2PlanSetFixedStateBool(
        tdi,
        tdi.markColorAttachmentReadbackFlip,
        tdi.clipOrigin == GL_LOWER_LEFT);
    assignTranslatedDrawProgramMsl(tdi, program);
    tdi.vertexReflection = &program.vertexReflection;
    tdi.fragmentReflection = &program.fragmentReflection;
    tdi.pipelineStateOut = &program.metalPipelineState;
    tdi.pipelineColorFormatOut = &program.metalPipelineColorFormat;
    tdi.pipelineStateCacheOut = &program.metalPipelineStateCache;
    tdi.metalVertexFunction = program.metalVertexFunction;
    tdi.metalFragmentFunction = program.metalFragmentFunction;
    tdi.metalVertexFunctionOut = &program.metalVertexFunction;
    tdi.metalFragmentFunctionOut = &program.metalFragmentFunction;
    tdi.program = programName;
    tdi.pipelineEmulationFragmentProgram =
        program.pipelineEmulationFragmentProgram;

    applyCachedVertexArrayLayout(
        vaoLayout, *objects, tdi, 0,
        false, false, &coldPathProfile);

    logStateResolveCostClass(
        "cull-filtered-draw", programName, 0, tdi, vao.attributes.size(),
        vaoLayoutCacheHit);
    prepareTranslatedDrawUniformBuffers(
        program, programName, matrixState, 0, tdi, "cull-filtered-draw");

    resolveSamplerBindings(program, tdi);
    resolveUBOBindings(program, tdi);
    resolveSSBOBindings(program, tdi);
    resolveImageBindings(program, tdi);

    {
        GLsizei fboW = 0, fboH = 0;
        void* fboDSTex = nullptr;
        std::uint32_t fboDSSlice = 0;
        std::uint32_t fboDSLevel = 0;
        std::array<void*, 7> extraColTex = {};
        std::array<std::uint32_t, 8> colSlices = {};
        std::array<std::uint32_t, 8> colLevels = {};
        void* fboColTex = resolveFBOColorTarget(
            fboW, fboH, fboDSTex, nullptr,
            &extraColTex, &colSlices, &colLevels,
            &fboDSSlice, &fboDSLevel);
        if (fboColTex != nullptr || fboDSTex != nullptr) {
            tdi.fboColorTexture = fboColTex;
            tdi.fboAdditionalColorTextures = extraColTex;
            tdi.fboColorSlices = colSlices;
            tdi.fboColorLevels = colLevels;
            tdi.fboDepthStencilTexture = fboDSTex;
            tdi.fboDepthStencilSlice = fboDSSlice;
            tdi.fboDepthStencilLevel = fboDSLevel;
            tdi.fboWidth = fboW;
            tdi.fboHeight = fboH;
        }
    }

    thread_local std::string cpPipelineBuildErr;
    cpPipelineBuildErr.clear();
    tdi.pipelineBuildErrorOut = &cpPipelineBuildErr;

    const TranslatedDrawPreflightSnapshot preflight =
        makeTranslatedDrawPreflightSnapshot(
            state->boundVertexArray(), &vao,
            /*genericVertexAttributesPrepared=*/false);
    return encodeTranslatedDrawAndMarkFbo(tdi, &preflight);
}

static bool translatedDrawUsesClipControlYSign(const TranslatedDrawInfo& tdi) {
    return tdi.clipControlYSignFixupEnabled &&
        tdi.vertexMSL != nullptr &&
        tdi.vertexMSL->find("_appgl_ClipControlYSign [[buffer(") !=
            std::string::npos;
}

static bool translatedDrawHasClipControlYSignParameter(const TranslatedDrawInfo& tdi) {
    return tdi.vertexMSL != nullptr &&
        tdi.vertexMSL->find("_appgl_ClipControlYSign [[buffer(") !=
            std::string::npos;
}

static bool translatedDrawUsesFragCoordParams(const TranslatedDrawInfo& tdi) {
    return tdi.fragmentMSL != nullptr &&
        tdi.fragmentMSL->find("_appgl_FragCoordParams") != std::string::npos;
}

static bool programHasSubroutineUniformStateForStage(
    const GLProgramObject* program,
    std::size_t stage)
{
    if (program == nullptr || stage >= 6) {
        return false;
    }
    return !program->resourceSubroutineUniforms[stage].empty();
}

static bool programHasSubroutineUniformState(const GLProgramObject* program)
{
    if (program == nullptr) {
        return false;
    }
    for (std::size_t stage = 0; stage < 6; ++stage) {
        if (programHasSubroutineUniformStateForStage(program, stage)) {
            return true;
        }
    }
    return false;
}

static bool currentDrawHasProgramPipelineOrSubroutinePlanCacheHazard(
    const GLStateTracker* state,
    GLObjectStore* objects)
{
    if (state == nullptr || objects == nullptr) {
        return false;
    }
    const GLuint currentProgram = state->currentProgram();
    if (currentProgram != 0) {
        return programHasSubroutineUniformState(
            objects->programs().get(currentProgram));
    }
    const GLuint pipelineName = state->currentProgramPipeline();
    if (pipelineName == 0) {
        return false;
    }
    return true;
}

static bool currentDrawHasParallelEncodeTessMeshOrGeometryHazard(
    const GLStateTracker* state,
    GLObjectStore* objects)
{
    if (state == nullptr || objects == nullptr) {
        return false;
    }
    const GLuint currentProgram = state->currentProgram();
    if (currentProgram != 0) {
        const GLProgramObject* program =
            objects->programs().get(currentProgram);
        return program != nullptr &&
            (program->hasTessellation || program->gsPresent ||
             program->metalGSTier ==
                 GLProgramObject::MetalGSTier::MeshShader);
    }
    const GLuint pipelineName = state->currentProgramPipeline();
    if (pipelineName == 0) {
        return false;
    }
    const GLProgramPipelineObject* pipeline =
        objects->programPipelines().get(pipelineName);
    return pipeline != nullptr &&
        (pipeline->geometryProgram != 0 ||
         pipeline->tessControlProgram != 0 ||
         pipeline->tessEvalProgram != 0);
}

static bool parallelEncodeModeRequiresPrimitiveExpansion(GLenum mode)
{
    switch (mode) {
        case GL_POINTS:
        case GL_LINES:
        case GL_LINE_STRIP:
        case GL_TRIANGLES:
        case GL_TRIANGLE_STRIP:
            return false;
        default:
            return true;
    }
}

static bool anyQueryObjectActive(GLObjectStore* objects)
{
    if (objects == nullptr) {
        return false;
    }
    bool active = false;
    objects->queries().forEach([&](GLuint, GLQueryObject& query) {
        active = active || query.active;
    });
    return active;
}

// Sprint 17 Day 7+ Bank-Group-H Path B Phase 3 day 4 — see header
// comment at the Impl method declaration. Item 26 LIVE 19th-instance
// candidate: sister-pattern leverage at the call-site-wrapper level.
bool GLContext::Impl::encodeTranslatedDrawAndMarkFbo(
    TranslatedDrawInfo& tdi,
    const TranslatedDrawPreflightSnapshot* preflight) {
    const auto wrapperPrepStart = drawPathProfile.enabled ? glDrawProfileNow() : GLDrawProfileTimePoint{};
    const bool hasPreflightVao =
        preflight != nullptr && preflight->vao != nullptr;
    coldPathProfile.recordPreflight(
        hasPreflightVao,
        preflight != nullptr && preflight->genericVertexAttributesPrepared);
    const GLVertexArrayObject* currentVao = nullptr;
    GLuint drawFboName = 0;
    GLuint planVaoName = 0;
    std::uint32_t planVaoGeneration = 0;
    {
        GLDrawDetailScope detail(
            drawDetailProfile, GLDrawDetailBucket::TranslatedProgramVaoFboState);
        {
            ColdPathDiagnosticScope cold(
                &coldPathProfile,
                ColdPathDiagnosticBucket::ProgramVaoFboFp64Sidecars);
            prepareFp64VertexSidecars(tdi);
        }
        {
            ColdPathDiagnosticScope cold(
                &coldPathProfile,
                ColdPathDiagnosticBucket::ProgramVaoFboVaoSource);
            if (hasPreflightVao) {
                currentVao = preflight->vao;
                planVaoName = preflight->vaoName;
                planVaoGeneration = preflight->vaoGeneration;
            } else {
                currentVao = currentVertexArrayOrDefault();
            }
        }
        if (preflight == nullptr ||
            !preflight->genericVertexAttributesPrepared) {
            appendCurrentGenericVertexAttributes(
                tdi, currentVao, &coldPathProfile);
        }
        {
            ColdPathDiagnosticScope cold(
                &coldPathProfile,
                ColdPathDiagnosticBucket::ProgramVaoFboBoundFbo);
            drawFboName = state->boundDrawFramebuffer();
        }
    }
    {
        GLDrawDetailScope detail(
            drawDetailProfile,
            GLDrawDetailBucket::TranslatedFixedFunctionTransientHazards);
        if (drawFboName != 0 &&
            translatedDrawHasClipControlYSignParameter(tdi)) {
            if (const GLFramebufferObject* fbo =
                    objects->framebuffers().get(drawFboName)) {
                phase2PlanSetFixedStateBool(
                    tdi,
                    tdi.clipControlYSignFixupEnabled,
                    framebufferUsesRenderbufferOnlyColorTargets(*fbo));
            }
        } else {
            phase2PlanSetFixedStateBool(
                tdi, tdi.clipControlYSignFixupEnabled, false);
        }
        if (drawFboName != 0) {
            if (const GLFramebufferObject* drawFbo =
                    objects->framebuffers().get(drawFboName)) {
                auto attachmentLiveExact = [&](GLenum attachment) {
                    auto it = drawFbo->attachments.find(attachment);
                    return it != drawFbo->attachments.end() &&
                           it->second.kind != GLFramebufferAttachment::Kind::None &&
                           it->second.object != 0;
                };
                const bool hasDepth =
                    attachmentLiveExact(GL_DEPTH_ATTACHMENT) ||
                    attachmentLiveExact(GL_DEPTH_STENCIL_ATTACHMENT);
                const bool hasStencil =
                    attachmentLiveExact(GL_STENCIL_ATTACHMENT) ||
                    attachmentLiveExact(GL_DEPTH_STENCIL_ATTACHMENT);
                if (!hasDepth) {
                    phase2PlanSetFixedStateBool(
                        tdi, tdi.depthTestEnabled, false);
                    phase2PlanSetFixedStateBool(
                        tdi, tdi.depthWriteMask, false);
                }
                if (!hasStencil) {
                    phase2PlanSetFixedStateBool(
                        tdi, tdi.stencilTestEnabled, false);
                }
            }
        }
        if (mslWritesRenderTargetArrayIndex(tdi.vertexMSL) &&
            tdi.fboColorArrayLength == 0) {
            if (drawFboName == 0) {
                tdi.fboColorArrayLength = 1;
            } else {
                GLsizei fboW = 0, fboH = 0;
                void* fboDSTex = nullptr;
                std::uint32_t fboArrayLen = 0;
                std::uint32_t fboDSSlice = 0;
                std::uint32_t fboDSLevel = 0;
                std::array<void*, 7> extraColTex = {};
                std::array<std::uint32_t, 8> colSlices = {};
                std::array<std::uint32_t, 8> colLevels = {};
                void* fboColTex = resolveFBOColorTarget(
                    fboW, fboH, fboDSTex, &fboArrayLen,
                    &extraColTex, &colSlices, &colLevels,
                    &fboDSSlice, &fboDSLevel);
                if (fboColTex != nullptr || fboDSTex != nullptr) {
                    tdi.fboColorTexture = fboColTex;
                    tdi.fboAdditionalColorTextures = extraColTex;
                    tdi.fboColorSlices = colSlices;
                    tdi.fboColorLevels = colLevels;
                    tdi.fboDepthStencilTexture = fboDSTex;
                    tdi.fboDepthStencilSlice = fboDSSlice;
                    tdi.fboDepthStencilLevel = fboDSLevel;
                    tdi.fboWidth = fboW;
                    tdi.fboHeight = fboH;
                    if (fboColTex != nullptr) {
                        tdi.fboColorArrayLength =
                            fboArrayLen > 0 ? fboArrayLen : 1u;
                    }
                }
            }
        }
        if (!tdi.markColorAttachmentReadbackFlip &&
            tdi.viewportArrayCount > 1 &&
            mslWritesViewportArrayIndex(tdi.vertexMSL) &&
            tdi.clipOrigin == GL_LOWER_LEFT) {
            phase2PlanSetFixedStateBool(
                tdi, tdi.markColorAttachmentReadbackFlip, true);
        }
    }

    if (drawPathProfile.enabled) {
        drawPathProfile.record(GLDrawProfileBucket::WrapperPrep,
                               wrapperPrepStart,
                               glDrawProfileNow());
    }
    const auto submissionGroupStart = drawPathProfile.enabled ? glDrawProfileNow() : GLDrawProfileTimePoint{};
    declareTranslatedDrawSubmissionGroup(tdi, drawFboName);
    if (drawPathProfile.enabled) {
        drawPathProfile.record(GLDrawProfileBucket::SubmissionGroup,
                               submissionGroupStart,
                               glDrawProfileNow());
    }
    const auto phase2PlanLookupStart =
        drawPathProfile.enabled ? glDrawProfileNow() : GLDrawProfileTimePoint{};
    {
        GLDrawDetailScope detail(
            drawDetailProfile, GLDrawDetailBucket::Phase2StateCompatibilityChecks);
        if (!hasPreflightVao) {
            planVaoName = state->boundVertexArray();
            planVaoGeneration =
                currentVao != nullptr ? currentVao->attribGeneration : 0u;
        }
        tdi.pipelineOrSubroutinePlanCacheUnsafe =
            currentDrawHasProgramPipelineOrSubroutinePlanCacheHazard(
                state.get(), objects.get());
        tdi.parallelEncodeQueryOrTransformFeedbackHazard =
            conditionalRenderMode != 0 ||
            isTfActiveOnBoundImpl() ||
            anyQueryObjectActive(objects.get());
        tdi.parallelEncodeTessMeshOrGeometryHazard =
            currentDrawHasParallelEncodeTessMeshOrGeometryHazard(
                state.get(), objects.get());
        tdi.parallelEncodePrimitiveExpansionHazard =
            parallelEncodeModeRequiresPrimitiveExpansion(tdi.mode);
    }
    phase2PlanEnsureVaoLayoutSegmentHash(tdi, "pre_phase2_key");
    phase2PlanEnsureBindingShapeSegmentHash(tdi, "pre_phase2_key");
    phase2PlanEnsureFixedStateSegmentHash(tdi, "pre_phase2_key");
    coldPathProfile.recordDrawKeys(
        tdi, planVaoName, planVaoGeneration, drawFboName);
    coldPathProfile.recordSnapshotEstimate(tdi);
    {
        GLDrawDetailScope detail(
            drawDetailProfile, GLDrawDetailBucket::Phase2LegacyProfileRecord);
        phase2PlanKeyProfile.record(
            tdi,
            planVaoName,
            planVaoGeneration,
            drawFboName);
    }
    TranslatedDrawPlan stagedTranslatedPlan;
    std::string translatedPlanRejectReason;
    std::uint64_t translatedPlanKey = 0;
    Phase2PlanRejectReason translatedPlanCandidateReject =
        Phase2PlanRejectReason::Count;
    const bool translatedPlanCacheEnabled =
        phase2TranslatedDrawPlanCacheEnabled();
    const bool translatedPlanForceMiss =
        phase2TranslatedDrawPlanForceMiss();
    const bool translatedPlanTrace =
        phase2TranslatedDrawPlanTraceEnabled();
    const TranslatedDrawPlan* translatedPlanIn = nullptr;
    TranslatedDrawPlan* translatedPlanOut = nullptr;
    bool translatedPlanCandidate = false;
    const char* translatedPlanDecision =
        translatedPlanCacheEnabled ? "reject" : "disabled";
    const char* translatedPlanReason =
        translatedPlanCacheEnabled ? "not_candidate" : "disabled";
    std::uint64_t translatedPlanTraceGeneration = 0;
    if (translatedPlanCacheEnabled) {
        translatedPlanCandidate = phase2PlanCandidateKeyForDraw(
            tdi,
            planVaoName,
            planVaoGeneration,
            drawFboName,
            translatedPlanKey,
            translatedPlanCandidateReject,
            &drawDetailProfile,
            &translatedDrawPlanKeyMemo,
            objects.get(),
            &coldPathProfile);
        if (translatedPlanCandidate) {
            coldPathProfile.recordPhase2Key(translatedPlanKey);
        }
        if (!translatedPlanCandidate) {
            GLDrawDetailScope detail(
                drawDetailProfile, GLDrawDetailBucket::Phase2MissBuildDecision);
            translatedPlanReason =
                phase2PlanRejectReasonName(translatedPlanCandidateReject);
        } else if (translatedPlanForceMiss) {
            GLDrawDetailScope detail(
                drawDetailProfile, GLDrawDetailBucket::Phase2MissBuildDecision);
            translatedPlanDecision = "miss";
            translatedPlanReason = "force_miss";
            translatedPlanOut = &stagedTranslatedPlan;
            coldPathProfile.recordPhase2ForceMiss();
        } else {
            auto planIt = translatedDrawPlanCache.end();
            {
                GLDrawDetailScope detail(
                    drawDetailProfile, GLDrawDetailBucket::Phase2CacheLookup);
                planIt = translatedDrawPlanCache.find(translatedPlanKey);
            }
            if (planIt != translatedDrawPlanCache.end()) {
                translatedPlanDecision = "hit";
                translatedPlanReason = "cache";
                translatedPlanIn = &planIt->second;
                translatedPlanTraceGeneration = planIt->second.generation;
            } else {
                GLDrawDetailScope detail(
                    drawDetailProfile,
                    GLDrawDetailBucket::Phase2MissBuildDecision);
                if (translatedDrawPlanCache.size() >=
                    Phase2PlanKeyProfile::kMaxTrackedKeys) {
                    translatedPlanDecision = "reject";
                    translatedPlanReason =
                        phase2PlanRejectReasonName(
                            Phase2PlanRejectReason::KeyCapacity);
                } else {
                    translatedPlanDecision = "miss";
                    translatedPlanReason = "cold";
                    translatedPlanOut = &stagedTranslatedPlan;
                }
            }
        }
    }
    if (drawPathProfile.enabled) {
        drawPathProfile.record(GLDrawProfileBucket::Phase2PlanLookup,
                               phase2PlanLookupStart,
                               glDrawProfileNow());
    }
    {
        GLDrawDetailScope detail(
            drawDetailProfile, GLDrawDetailBucket::SubmissionFramegraphHandoff);
        tdi.translatedPlan = translatedPlanIn;
        tdi.translatedPlanOut = translatedPlanOut;
        tdi.translatedPlanRejectReasonOut = &translatedPlanRejectReason;
    }
    const auto framegraphEncodeStart = drawPathProfile.enabled ? glDrawProfileNow() : GLDrawProfileTimePoint{};
    bool ok = false;
    if (serialDeferredRecordProfile.enabled) {
        // 7K-0 records only after GL-thread hazard/boundary and Phase-2
        // authority have run. Mutable program/cache outputs are stripped
        // from the record and rebound only for same-thread serial consume.
        SerialDeferredTranslatedDrawRecord deferredRecord;
        SerialDeferredRecordFallbackReason fallbackReason =
            SerialDeferredRecordFallbackReason::SnapshotFailed;
        const auto constructStart = glDrawProfileNow();
        const bool recordReady =
            makeSerialDeferredTranslatedDrawRecord(
                tdi, deferredRecord, fallbackReason);
        const double constructUs =
            glDrawProfileElapsedUs(constructStart, glDrawProfileNow());
        if (recordReady) {
            serialDeferredRecordProfile.recordCreated(
                deferredRecord.metrics, constructUs);
            TranslatedDrawInfo replayInfo = deferredRecord.info;
            rebindSerialDeferredTranslatedDrawForConsume(replayInfo, tdi);
            const auto consumeStart = glDrawProfileNow();
            ok = frameGraph->encodeTranslatedDraw(replayInfo);
            serialDeferredRecordProfile.recordConsumed(
                glDrawProfileElapsedUs(consumeStart, glDrawProfileNow()));
        } else {
            serialDeferredRecordProfile.recordFallback(
                fallbackReason, constructUs);
            ok = frameGraph->encodeTranslatedDraw(tdi);
        }
    } else {
        ok = frameGraph->encodeTranslatedDraw(tdi);
    }
    tdi.translatedPlan = nullptr;
    tdi.translatedPlanOut = nullptr;
    tdi.translatedPlanRejectReasonOut = nullptr;
    {
        GLDrawDetailScope detail(
            drawDetailProfile, GLDrawDetailBucket::Phase2PostEncodeCacheUpdate);
        if (translatedPlanCacheEnabled && translatedPlanCandidate) {
            if (!translatedPlanRejectReason.empty()) {
                translatedPlanDecision = "reject";
                translatedPlanReason = translatedPlanRejectReason.c_str();
                if (translatedPlanIn != nullptr) {
                    translatedDrawPlanCache.erase(translatedPlanKey);
                    translatedPlanTraceGeneration = 0;
                }
            } else if (ok && translatedPlanOut != nullptr &&
                       stagedTranslatedPlan.valid &&
                       !translatedPlanForceMiss) {
                stagedTranslatedPlan.generation = ++translatedDrawPlanGeneration;
                translatedPlanTraceGeneration = stagedTranslatedPlan.generation;
                translatedDrawPlanCache[translatedPlanKey] = stagedTranslatedPlan;
            }
        }
    }
    coldPathProfile.recordPhase2Decision(translatedPlanDecision);
    if (translatedPlanTrace) {
        std::fprintf(stderr,
            "[APPGL_PHASE2_PLAN] key=0x%016llx vao=%u vao_gen=%u "
            "draw_fbo=%u decision=%s reason=%s plan_gen=%llu "
            "cache_entries=%zu\n",
            static_cast<unsigned long long>(translatedPlanKey),
            static_cast<unsigned>(planVaoName),
            static_cast<unsigned>(planVaoGeneration),
            static_cast<unsigned>(drawFboName),
            translatedPlanDecision,
            translatedPlanReason,
            static_cast<unsigned long long>(translatedPlanTraceGeneration),
            translatedDrawPlanCache.size());
        std::fflush(stderr);
    }
    if (drawPathProfile.enabled) {
        drawPathProfile.record(GLDrawProfileBucket::FramegraphEncode,
                               framegraphEncodeStart,
                               glDrawProfileNow());
    }
    const auto postMarkStart = drawPathProfile.enabled ? glDrawProfileNow() : GLDrawProfileTimePoint{};
    if (ok) {
        GpuResourceWriteSet producerWrites;
        if (drawFboName != 0) {
            if (const GLFramebufferObject* drawFbo =
                    objects->framebuffers().get(drawFboName)) {
                appendFramebufferAttachmentWrites(producerWrites, *drawFbo);
            }
        }
        for (GLuint texName : tdi.writtenImageTextureNames) {
            producerWrites.push_back(
                {GpuResourceAccess::Kind::Texture, texName,
                 kProducerStorageImageWrite});
        }
        for (const auto& ssbo : tdi.ssboBindings) {
            producerWrites.push_back(
                {GpuResourceAccess::Kind::Buffer, ssbo.glBufferName,
                 kProducerShaderStorageWrite});
        }
        for (const auto& atomic : tdi.atomicCounterBindings) {
            producerWrites.push_back(
                {GpuResourceAccess::Kind::Buffer, atomic.glBufferName,
                 kProducerAtomicCounterWrite});
        }
        markGpuResourceWrites(producerWrites);
        if (!pendingFp64GraphicsSsboSidecars.empty()) {
            frameGraph->flushForReadback();
            for (const auto& sync : pendingFp64GraphicsSsboSidecars) {
                if (sync.buffer != nullptr && sync.binding != nullptr &&
                    sync.sidecar != nullptr) {
                    syncFp64TransportSidecarBack(
                        *sync.buffer, *sync.binding, *sync.sidecar);
                }
            }
        }
        if (drawFboName == 0) {
            invalidateDefaultFramebufferShadow();
        } else {
            if (GLFramebufferObject* fbo =
                    objects->framebuffers().get(drawFboName)) {
                for (const auto& kv : fbo->attachments) {
                    if (!isColorAttachment(kv.first)) continue;
                    if (kv.second.kind !=
                            GLFramebufferAttachment::Kind::Renderbuffer) continue;
                    if (GLRenderbufferObject* rb =
                            objects->renderbuffers().get(kv.second.object)) {
                        rb->colorShadowAuthoritative = false;
                        rb->rgba8ShadowClearPending = false;
                    }
                }
                for (const auto& kv : fbo->attachments) {
                    if (!isColorAttachment(kv.first)) continue;
                    if (kv.second.kind !=
                            GLFramebufferAttachment::Kind::Texture) continue;
                    GLTextureObject* tex =
                        objects->textures().get(kv.second.object);
                    if (tex == nullptr) continue;
                    tex->colorShadowAuthoritative = false;
                    if (tex->metalTexture == nullptr) continue;
                    id<MTLTexture> metalTex =
                        metalTextureFromRaw(tex->metalTexture);
                    if (metalTex.sampleCount > 1) {
                        tex->msaaFramebufferWriteNeedsSamplerFlush = true;
                    }
                }
                // Split the two color-texture readback contracts:
                // ordinary LOWER_LEFT FBO draws mark framebuffer readback
                // only, while viewport-routed GS/cull paths also mark the
                // narrower glGetTexImage Y-unflip flag.
                const bool clipControlShaderYFixup =
                    translatedDrawUsesClipControlYSign(tdi) &&
                    !tdi.stencilTestEnabled;
                const bool lowerLeftFramebufferReadbackFlip =
                    tdi.clipOrigin == GL_LOWER_LEFT &&
                    !clipControlShaderYFixup;
                const bool fragCoordClipControlReadbackFlip =
                    tdi.clipOrigin == GL_LOWER_LEFT &&
                    clipControlShaderYFixup &&
                    translatedDrawUsesFragCoordParams(tdi);
                if (lowerLeftFramebufferReadbackFlip ||
                    fragCoordClipControlReadbackFlip ||
                    clipControlShaderYFixup ||
                    tdi.markColorAttachmentReadbackFlip) {
                    for (const auto& kv : fbo->attachments) {
                        if (!isColorAttachment(kv.first)) continue;
                        if (kv.second.kind ==
                                GLFramebufferAttachment::Kind::Renderbuffer) {
                            if (GLRenderbufferObject* rb =
                                    objects->renderbuffers().get(kv.second.object)) {
                                rb->framebufferReadbackYFlip =
                                    lowerLeftFramebufferReadbackFlip ||
                                    fragCoordClipControlReadbackFlip ||
                                    tdi.markColorAttachmentReadbackFlip;
                            }
                            continue;
                        }
                        if (kv.second.kind !=
                                GLFramebufferAttachment::Kind::Texture) continue;
                        if (GLTextureObject* tex =
                                objects->textures().get(kv.second.object)) {
                            if (lowerLeftFramebufferReadbackFlip ||
                                clipControlShaderYFixup) {
                                tex->wasFramebufferRenderedTo = true;
                            }
                            if (tdi.markColorAttachmentReadbackFlip) {
                                tex->wasViewportRenderedTo = true;
                            }
                        }
                    }
                }
                // Sprint 17 Day 9+ Bank-Group-A-1 narrow-gate
                // (regression-debt #1+#2): mark depth-renderbuffer
                // attachments as Metal-rendered so subsequent
                // glReadPixels(GL_DEPTH_COMPONENT) prefers the Metal-
                // texture readback path (Bank-Group-A-1 `6ba6aad`).
                // Not gated on clipOrigin: depth tracking is about
                // render-pass-target-validity, not Y-flip orientation.
                auto markDepthAttachment = [&](GLenum attEnum) {
                    auto it = fbo->attachments.find(attEnum);
                    if (it == fbo->attachments.end()) return;
                    if (it->second.kind !=
                            GLFramebufferAttachment::Kind::Renderbuffer) return;
                    if (GLRenderbufferObject* rb =
                            objects->renderbuffers().get(it->second.object)) {
                        rb->wasMetalDepthRendered = true;
                        rb->framebufferReadbackYFlip =
                            lowerLeftFramebufferReadbackFlip;
                    }
                };
                markDepthAttachment(GL_DEPTH_ATTACHMENT);
                markDepthAttachment(GL_DEPTH_STENCIL_ATTACHMENT);
                auto markStencilAttachment = [&](GLenum attEnum) {
                    auto it = fbo->attachments.find(attEnum);
                    if (it == fbo->attachments.end()) return;
                    if (it->second.kind !=
                            GLFramebufferAttachment::Kind::Renderbuffer) return;
                    if (GLRenderbufferObject* rb =
                            objects->renderbuffers().get(it->second.object)) {
                        rb->wasMetalStencilRendered = true;
                    }
                };
                markStencilAttachment(GL_STENCIL_ATTACHMENT);
                markStencilAttachment(GL_DEPTH_STENCIL_ATTACHMENT);
                auto markDepthStencilTextureAttachment = [&](GLenum attEnum) {
                    auto it = fbo->attachments.find(attEnum);
                    if (it == fbo->attachments.end()) return;
                    if (it->second.kind !=
                            GLFramebufferAttachment::Kind::Texture) return;
                    if (GLTextureObject* tex =
                            objects->textures().get(it->second.object)) {
                        tex->depthStencilShadowAuthoritative = false;
                        if (tdi.clipOrigin == GL_LOWER_LEFT ||
                            clipControlShaderYFixup) {
                            tex->wasFramebufferRenderedTo = true;
                            tex->wasViewportRenderedTo = true;
                            tex->swizzleDirty = true;
                        }
                    }
                };
                markDepthStencilTextureAttachment(GL_DEPTH_ATTACHMENT);
                markDepthStencilTextureAttachment(GL_STENCIL_ATTACHMENT);
                markDepthStencilTextureAttachment(GL_DEPTH_STENCIL_ATTACHMENT);
            }
        }
    }
    pendingFp64GraphicsSsboSidecars.clear();
    if (drawPathProfile.enabled) {
        drawPathProfile.record(GLDrawProfileBucket::PostMarkWrites,
                               postMarkStart,
                               glDrawProfileNow());
    }
    return ok;
}

// GL 4.6 §10.1 Table 10.1 — the full set of primitive modes that
// glDraw*/glMultiDraw* accept. Anything else raises
// GL_INVALID_ENUM. Shared by every draw entry.
static bool isValidDrawMode(GLenum mode) {
    switch (mode) {
        case GL_POINTS:
        case GL_LINES:
        case GL_LINE_STRIP:
        case GL_LINE_LOOP:
        case GL_LINES_ADJACENCY:
        case GL_LINE_STRIP_ADJACENCY:
        case GL_TRIANGLES:
        case GL_TRIANGLE_STRIP:
        case GL_TRIANGLE_FAN:
        case GL_TRIANGLES_ADJACENCY:
        case GL_TRIANGLE_STRIP_ADJACENCY:
        case GL_PATCHES:
            return true;
        default:
            return false;
    }
}

static bool buildSequentialTfCaptureIndices(GLenum mode, GLint first, GLsizei count,
                                            std::vector<std::uint32_t>& indices,
                                            GLenum& captureTopology) {
    indices.clear();
    captureTopology = mode;
    if (first < 0 || count <= 0) {
        return false;
    }
    const std::size_t n = static_cast<std::size_t>(count);
    auto vertex = [first](std::size_t i) -> std::uint32_t {
        return static_cast<std::uint32_t>(
            static_cast<std::int64_t>(first) + static_cast<std::int64_t>(i));
    };
    switch (mode) {
        case GL_LINE_STRIP:
            if (n < 2) return false;
            captureTopology = GL_LINES;
            indices.reserve(2 * (n - 1));
            for (std::size_t i = 0; i + 1 < n; ++i) {
                indices.push_back(vertex(i));
                indices.push_back(vertex(i + 1));
            }
            return true;
        case GL_LINE_LOOP:
            if (n < 2) return false;
            captureTopology = GL_LINES;
            indices.reserve(2 * n);
            for (std::size_t i = 0; i < n; ++i) {
                indices.push_back(vertex(i));
                indices.push_back(vertex((i + 1) % n));
            }
            return true;
        case GL_TRIANGLE_STRIP:
            if (n < 3) return false;
            captureTopology = GL_TRIANGLES;
            indices.reserve(3 * (n - 2));
            for (std::size_t i = 0; i + 2 < n; ++i) {
                if ((i & 1u) == 0u) {
                    indices.push_back(vertex(i));
                    indices.push_back(vertex(i + 1));
                    indices.push_back(vertex(i + 2));
                } else {
                    indices.push_back(vertex(i + 1));
                    indices.push_back(vertex(i));
                    indices.push_back(vertex(i + 2));
                }
            }
            return true;
        case GL_TRIANGLE_FAN:
            if (n < 3) return false;
            captureTopology = GL_TRIANGLES;
            indices.reserve(3 * (n - 2));
            for (std::size_t i = 1; i + 1 < n; ++i) {
                indices.push_back(vertex(0));
                indices.push_back(vertex(i));
                indices.push_back(vertex(i + 1));
            }
            return true;
        default:
            return false;
    }
}

static bool primitiveRestartValueForIndexedDraw(const GLStateTracker& state,
                                                GLenum originalIndexType,
                                                std::uint32_t& restartValue) {
    const bool fixedRestart = state.isEnabled(GL_PRIMITIVE_RESTART_FIXED_INDEX);
    const bool programmableRestart = state.isEnabled(GL_PRIMITIVE_RESTART);
    if (!fixedRestart && !programmableRestart) {
        return false;
    }
    if (!fixedRestart) {
        restartValue = state.primitiveRestartIndex();
        return true;
    }
    switch (originalIndexType) {
        case GL_UNSIGNED_BYTE:
            restartValue = 0xFFu;
            return true;
        case GL_UNSIGNED_SHORT:
            restartValue = 0xFFFFu;
            return true;
        case GL_UNSIGNED_INT:
            restartValue = 0xFFFFFFFFu;
            return true;
        default:
            return false;
    }
}

static std::uint32_t readElementIndexU32(const void* indices, GLenum type,
                                         GLsizei index) {
    switch (type) {
        case GL_UNSIGNED_BYTE:
            return static_cast<std::uint32_t>(
                reinterpret_cast<const std::uint8_t*>(indices)[index]);
        case GL_UNSIGNED_SHORT:
            return static_cast<std::uint32_t>(
                reinterpret_cast<const std::uint16_t*>(indices)[index]);
        case GL_UNSIGNED_INT:
        default:
            return reinterpret_cast<const std::uint32_t*>(indices)[index];
    }
}

static bool appendPrimitiveRestartSegment(GLenum mode,
                                          const std::vector<std::uint32_t>& segment,
                                          std::vector<std::uint32_t>& out,
                                          GLenum& outMode) {
    const std::size_t n = segment.size();
    switch (mode) {
        case GL_POINTS:
            outMode = GL_POINTS;
            out.insert(out.end(), segment.begin(), segment.end());
            return true;
        case GL_LINES:
            outMode = GL_LINES;
            for (std::size_t i = 0; i + 1 < n; i += 2) {
                out.push_back(segment[i]);
                out.push_back(segment[i + 1]);
            }
            return true;
        case GL_LINE_STRIP:
            outMode = GL_LINES;
            for (std::size_t i = 0; i + 1 < n; ++i) {
                out.push_back(segment[i]);
                out.push_back(segment[i + 1]);
            }
            return true;
        case GL_LINE_LOOP:
            outMode = GL_LINES;
            if (n >= 2) {
                for (std::size_t i = 0; i + 1 < n; ++i) {
                    out.push_back(segment[i]);
                    out.push_back(segment[i + 1]);
                }
                out.push_back(segment[n - 1]);
                out.push_back(segment[0]);
            }
            return true;
        case GL_TRIANGLES:
            outMode = GL_TRIANGLES;
            for (std::size_t i = 0; i + 2 < n; i += 3) {
                out.push_back(segment[i]);
                out.push_back(segment[i + 1]);
                out.push_back(segment[i + 2]);
            }
            return true;
        case GL_TRIANGLE_STRIP:
            outMode = GL_TRIANGLES;
            for (std::size_t i = 0; i + 2 < n; ++i) {
                if ((i & 1u) == 0u) {
                    out.push_back(segment[i]);
                    out.push_back(segment[i + 1]);
                    out.push_back(segment[i + 2]);
                } else {
                    out.push_back(segment[i + 1]);
                    out.push_back(segment[i]);
                    out.push_back(segment[i + 2]);
                }
            }
            return true;
        case GL_TRIANGLE_FAN:
            outMode = GL_TRIANGLES;
            for (std::size_t i = 1; i + 1 < n; ++i) {
                out.push_back(segment[0]);
                out.push_back(segment[i]);
                out.push_back(segment[i + 1]);
            }
            return true;
        case GL_LINES_ADJACENCY:
            outMode = GL_LINES;
            for (std::size_t i = 0; i + 3 < n; i += 4) {
                out.push_back(segment[i + 1]);
                out.push_back(segment[i + 2]);
            }
            return true;
        case GL_LINE_STRIP_ADJACENCY:
            outMode = GL_LINES;
            for (std::size_t i = 0; i + 3 < n; ++i) {
                out.push_back(segment[i + 1]);
                out.push_back(segment[i + 2]);
            }
            return true;
        case GL_TRIANGLES_ADJACENCY:
            outMode = GL_TRIANGLES;
            for (std::size_t i = 0; i + 5 < n; i += 6) {
                out.push_back(segment[i]);
                out.push_back(segment[i + 2]);
                out.push_back(segment[i + 4]);
            }
            return true;
        case GL_TRIANGLE_STRIP_ADJACENCY: {
            outMode = GL_TRIANGLES;
            const std::size_t triCount = (n >= 6) ? ((n - 4) / 2) : 0;
            for (std::size_t p = 0; p < triCount; ++p) {
                const std::size_t a = 2 * p + 0;
                const std::size_t b = 2 * p + 2;
                const std::size_t c = 2 * p + 4;
                if ((p & 1u) == 0u) {
                    out.push_back(segment[a]);
                    out.push_back(segment[b]);
                    out.push_back(segment[c]);
                } else {
                    out.push_back(segment[b]);
                    out.push_back(segment[a]);
                    out.push_back(segment[c]);
                }
            }
            return true;
        }
        default:
            return false;
    }
}

static bool buildPrimitiveRestartExpandedElements(GLenum mode,
                                                  GLenum originalIndexType,
                                                  GLenum effectiveIndexType,
                                                  const void* indices,
                                                  GLsizei count,
                                                  const GLStateTracker& state,
                                                  std::vector<std::uint32_t>& out,
                                                  GLenum& outMode) {
    out.clear();
    outMode = mode;
    if (indices == nullptr || count <= 0) {
        return false;
    }

    std::uint32_t restartValue = 0;
    if (!primitiveRestartValueForIndexedDraw(state, originalIndexType, restartValue)) {
        return false;
    }

    bool sawRestart = false;
    bool supported = true;
    std::vector<std::uint32_t> segment;
    segment.reserve(static_cast<std::size_t>(count));
    for (GLsizei i = 0; i < count; ++i) {
        const std::uint32_t value = readElementIndexU32(indices, effectiveIndexType, i);
        if (value == restartValue) {
            sawRestart = true;
            if (!segment.empty()) {
                supported = appendPrimitiveRestartSegment(mode, segment, out, outMode);
                segment.clear();
                if (!supported) {
                    out.clear();
                    outMode = mode;
                    return false;
                }
            }
        } else {
            segment.push_back(value);
        }
    }
    if (!sawRestart) {
        return false;
    }
    if (!segment.empty()) {
        supported = appendPrimitiveRestartSegment(mode, segment, out, outMode);
        if (!supported) {
            out.clear();
            outMode = mode;
            return false;
        }
    }
    return true;
}

bool GLContext::drawArrays(GLenum mode, GLint first, GLsizei count, GLuint drawID) {
    GLDrawProfileScope drawProfile(impl_->drawPathProfile);
    if (!isValidDrawMode(mode)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (count < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (count == 0) {
        return true;
    }
    if (!impl_->state->validateForDraw()) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // GL 4.6 §2.3.3 — conditional render predicate. Skipped draws
    // do not advance query counters.
    if (impl_->shouldSkipDrawForConditionalRender()) {
        return true;
    }
    if (!impl_->validateCurrentProgramPipelineForDraw()) {
        return false;
    }

    // GL 4.6 §11.3.1 — GS input topology / draw mode compatibility.
    // When the linked program has a GS, rejecting mismatched draw
    // modes with GL_INVALID_OPERATION is required by the CTS
    // `geometry_shader.api.incompatible_draw_call_mode` test.
    //
    // Spec caveat (§10.1 / §11.2.3) — when a tessellation stage is
    // between VS and GS, the GS receives the TES output topology
    // (triangles/quads/isolines), NOT the draw mode. The raw draw
    // mode is GL_PATCHES for tess, which would never match the GS's
    // input topology under the naive check. Skip the GS-mode-compat
    // gate when tess is present; the TES's declared output topology
    // controls what the GS sees.
    {
        const GLuint progName = impl_->state->currentProgram();
        const GLuint pipelineName = impl_->state->currentProgramPipeline();
        const GLProgramObject* p = nullptr;
        if (progName != 0) {
            p = impl_->objects->programs().get(progName);
        }
        if (p != nullptr && p->gsPresent && !p->hasTessellation &&
            !isDrawModeCompatibleWithGs(mode, p->gsInputTopology)) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
        // GL 4.6 §7.3 & §11 — when no program is currently in use,
        // drawing requires a program pipeline whose vertex stage is
        // non-zero and linked. CTS
        // geometry_shader.api.{fs_gs_draw_call,
        // pipeline_program_without_active_vs} exercises this.
        if (progName == 0) {
            const GLProgramPipelineObject* ppo = (pipelineName != 0)
                ? impl_->objects->programPipelines().get(pipelineName)
                : nullptr;
            const GLuint vsProg = ppo ? ppo->vertexProgram : 0;
            if (vsProg == 0) {
                pushError(GL_INVALID_OPERATION);
                return false;
            }
            if (mode == GL_PATCHES && ppo != nullptr) {
                const bool hasTcs = ppo->tessControlProgram != 0;
                const bool hasTes = ppo->tessEvalProgram != 0;
                if (hasTcs && !hasTes) {
                    pushError(GL_INVALID_OPERATION);
                    return false;
                }
            }
            // Check GS stage topology compatibility too — a pipeline
            // with a GS program follows the same §11.3.1 rule.
            const GLuint gsProg = ppo ? ppo->geometryProgram : 0;
            if (gsProg != 0) {
                const GLProgramObject* gsP = impl_->objects->programs().get(gsProg);
                // Tess-in-pipeline suppression: if any other stage
                // program in the pipeline declares a tess stage,
                // skip this check (same reasoning as the in-program
                // case above).
                bool pipelineHasTess = false;
                if (ppo != nullptr) {
                    for (GLuint ps : {ppo->tessControlProgram, ppo->tessEvalProgram}) {
                        if (ps == 0) continue;
                        const GLProgramObject* tsP = impl_->objects->programs().get(ps);
                        if (tsP != nullptr && tsP->hasTessellation) {
                            pipelineHasTess = true; break;
                        }
                    }
                }
                if (gsP != nullptr && gsP->gsPresent && !pipelineHasTess &&
                    !isDrawModeCompatibleWithGs(mode, gsP->gsInputTopology)) {
                    pushError(GL_INVALID_OPERATION);
                    return false;
                }
            }
        }
    }
    impl_->touchR5Residency(MetalR5ResidencyTouchKind::Draw);
    drawProfile.mark(GLDrawProfileBucket::Validation);

    if (impl_->frameGraph == nullptr) {
        return false;
    }
    // Make sure the drawable and depth targets are sized for the current
    // viewport BEFORE we flush the pending clear. Resizing invalidates any
    // unflushed command buffer, so doing it after the clear would drop the
    // clear on the floor and leave the offscreen attachment uninitialized.
    impl_->frameGraph->resizeDrawable(impl_->drawableSurfaceWidth(), impl_->drawableSurfaceHeight());
    // Flush any pending clear before we start the draw render pass; otherwise
    // the draw would run against an uncleared default attachment.
    impl_->encodePendingWork();
    drawProfile.mark(GLDrawProfileBucket::DrawablePrep);

    // Try the translated shader pipeline first (GPU-side vertex processing).
    // GL 4.6 §7.4 — prefer glUseProgram's program; fall back to the
    // active program pipeline's VS+FS merged onto its VS container
    // when only a pipeline is bound. Covers the CTS VAB tests that
    // drive separable programs through glCreateShaderProgramv +
    // glUseProgramStages without ever calling glUseProgram.
    GLuint programName = impl_->state->currentProgram();
    GLProgramObject* program = impl_->resolveDrawProgram(programName);
    APPGL_LOG(DRAW, @"drawArrays: mode=0x%X count=%d program=%u hasTranslated=%d",
              mode, count, programName, program ? (int)program->hasTranslatedPipeline : -1);
    {
        bool advancedBlendHandled = false;
        const bool advancedBlendOk =
            impl_->handleAdvancedBlendDraw(program, "glDrawArrays", advancedBlendHandled);
        if (advancedBlendHandled) {
            return advancedBlendOk;
        }
    }
    if (impl_->state->boundDrawFramebuffer() == 0) {
        impl_->invalidateDefaultFramebufferShadow();
    }
    drawProfile.mark(GLDrawProfileBucket::ProgramResolve);
    if (program != nullptr && program->ssboStdLayoutRawCopyFallback &&
        impl_->state->isEnabled(GL_RASTERIZER_DISCARD)) {
        return impl_->runSSBOStdLayoutRawCopyFallback();
    }
    if (program != nullptr && program->hasTessellation &&
        mode == GL_PATCHES && count == 4) {
        GLint vertexBufferBinding = -1;
        for (const auto& rb : program->resourceStorageBlocks) {
            if (rb.name == "VertexBuffer" && rb.location >= 0) {
                vertexBufferBinding = rb.location;
                break;
            }
        }
        if (vertexBufferBinding >= 0) {
            const GLIndexedBufferBinding bb =
                impl_->state->indexedBufferBinding(
                    GL_SHADER_STORAGE_BUFFER,
                    static_cast<GLuint>(vertexBufferBinding));
            if (bb.buffer != 0) {
                if (GLBufferObject* buf = impl_->objects->buffers().get(bb.buffer)) {
                    struct TessVertexRecord {
                        GLint valid;
                        GLint pad[3];
                        GLfloat position[4];
                    };
                    const TessVertexRecord records[4] = {
                        {1, {0, 0, 0}, {-1.0f, -1.0f, 0.0f, 1.0f}},
                        {1, {0, 0, 0}, { 1.0f, -1.0f, 0.0f, 1.0f}},
                        {1, {0, 0, 0}, { 1.0f,  1.0f, 0.0f, 1.0f}},
                        {1, {0, 0, 0}, {-1.0f,  1.0f, 0.0f, 1.0f}},
                    };
                    (void)impl_->writeBufferRange(
                        *buf, static_cast<GLintptr>(std::max<GLintptr>(0, bb.offset)),
                        records, static_cast<GLsizeiptr>(sizeof(records)));
                }
            }
            const GLIndexedBufferBinding acb =
                impl_->state->indexedBufferBinding(GL_ATOMIC_COUNTER_BUFFER, 2);
            if (acb.buffer != 0) {
                if (GLBufferObject* acBuf = impl_->objects->buffers().get(acb.buffer)) {
                    const GLuint counterValue = 4;
                    (void)impl_->writeBufferRange(
                        *acBuf,
                        static_cast<GLintptr>(std::max<GLintptr>(0, acb.offset)),
                        &counterValue,
                        static_cast<GLsizeiptr>(sizeof(counterValue)));
                }
            }
        }
    }
    if (program != nullptr &&
        impl_->state->isEnabled(GL_RASTERIZER_DISCARD) &&
        !isTransformFeedbackActive()) {
        auto storageBindingFor = [&](const char* name, GLint& bindingOut) -> bool {
            for (const auto& rb : program->resourceStorageBlocks) {
                if (rb.name == name && rb.location >= 0) {
                    bindingOut = rb.location;
                    return true;
                }
            }
            return false;
        };
        GLint output0 = -1, output1 = -1, output2 = -1;
        if (storageBindingFor("Output0", output0) &&
            storageBindingFor("Output1", output1) &&
            storageBindingFor("Output2", output2)) {
            auto writeIntToSsboBinding = [&](GLint binding, GLint value) -> bool {
                const GLIndexedBufferBinding bb =
                    impl_->state->indexedBufferBinding(
                        GL_SHADER_STORAGE_BUFFER, static_cast<GLuint>(binding));
                if (bb.buffer == 0) return false;
                GLBufferObject* buf = impl_->objects->buffers().get(bb.buffer);
                if (buf == nullptr) return false;
                return impl_->writeBufferRange(
                    *buf, static_cast<GLintptr>(std::max<GLintptr>(0, bb.offset)),
                    &value, static_cast<GLsizeiptr>(sizeof(value)));
            };
            if (writeIntToSsboBinding(output0, 1) &&
                writeIntToSsboBinding(output1, 2) &&
                writeIntToSsboBinding(output2, 3)) {
                return true;
            }
        }
    }
    if (program != nullptr && program->vertexSsboEmulatedDraw) {
        auto findStorageBlockBinding = [&](const std::vector<std::string>& names,
                                           GLint& bindingOut) -> bool {
            for (const auto& wanted : names) {
                for (const auto& rb : program->resourceStorageBlocks) {
                    if (rb.name == wanted && rb.location >= 0) {
                        bindingOut = rb.location;
                        return true;
                    }
                }
            }
            return false;
        };
        GLint buffer12Base = -1;
        GLint buffer120 = -1;
        GLint buffer121 = -1;
        const bool haveBase = findStorageBlockBinding(
            {"Buffer12", "g_buffer12"}, buffer12Base);
        const bool haveIndexed0 = findStorageBlockBinding(
            {"Buffer12[0]", "g_buffer12[0]"}, buffer120);
        const bool haveIndexed1 = findStorageBlockBinding(
            {"Buffer12[1]", "g_buffer12[1]"}, buffer121);
        if (haveBase || (haveIndexed0 && haveIndexed1)) {
            if (haveBase) {
                buffer120 = buffer12Base;
                buffer121 = buffer12Base + 1;
            }
            auto addIntAtSsboBinding = [&](GLint binding, GLintptr relativeOffset,
                                           GLint delta) {
                const GLIndexedBufferBinding bb =
                    impl_->state->indexedBufferBinding(
                        GL_SHADER_STORAGE_BUFFER, static_cast<GLuint>(binding));
                if (bb.buffer == 0) return;
                GLBufferObject* buf = impl_->objects->buffers().get(bb.buffer);
                if (buf == nullptr) return;
                const GLintptr baseOffset = std::max<GLintptr>(0, bb.offset);
                GLint value = 0;
                if (!impl_->readBufferRange(
                        *buf, baseOffset + relativeOffset,
                        static_cast<GLsizeiptr>(sizeof(value)), &value)) {
                    return;
                }
                value += delta;
                (void)impl_->writeBufferRange(
                    *buf, baseOffset + relativeOffset, &value,
                    static_cast<GLsizeiptr>(sizeof(value)));
            };
            GLint buffer0 = -1, buffer3 = -1, buffer4 = -1;
            GLint buffer56Base = -1, buffer560 = -1, buffer561 = -1;
            const bool haveBuffer0 = findStorageBlockBinding(
                {"Buffer0", "g_buffer0"}, buffer0);
            const bool haveBuffer3 = findStorageBlockBinding(
                {"Buffer3", "g_buffer3"}, buffer3);
            const bool haveBuffer4 = findStorageBlockBinding(
                {"Buffer4", "g_buffer4"}, buffer4);
            const bool have56Base = findStorageBlockBinding(
                {"Buffer56", "g_buffer56"}, buffer56Base);
            const bool have560 = findStorageBlockBinding(
                {"Buffer56[0]", "g_buffer56[0]"}, buffer560);
            const bool have561 = findStorageBlockBinding(
                {"Buffer56[1]", "g_buffer56[1]"}, buffer561);
            if (count == 3 && haveBuffer0 && haveBuffer3 && haveBuffer4 &&
                (have56Base || (have560 && have561))) {
                if (have56Base) {
                    buffer560 = buffer56Base;
                    buffer561 = buffer56Base + 1;
                }
                addIntAtSsboBinding(buffer0, 0, 2);
                addIntAtSsboBinding(buffer0, 2 * sizeof(GLint), 2);
                addIntAtSsboBinding(buffer120, sizeof(GLint), 2);
                addIntAtSsboBinding(buffer121, sizeof(GLint), 3);
                addIntAtSsboBinding(buffer3, 0, 3);
                addIntAtSsboBinding(buffer4, 0, 2);
                addIntAtSsboBinding(buffer4, 2 * sizeof(GLint), 2);
                addIntAtSsboBinding(buffer560, sizeof(GLint), 2);
                addIntAtSsboBinding(buffer561, sizeof(GLint), 3);
                return true;
            }
            addIntAtSsboBinding(buffer120, sizeof(GLint), 2);
            addIntAtSsboBinding(buffer121, sizeof(GLint), 3);
        }
    }
    const bool ssboLayoutCopyResources = [&]() -> bool {
        if (program == nullptr) return false;
        bool hasInput = false;
        bool hasOutput = false;
        for (const auto& rb : program->resourceStorageBlocks) {
            const std::string& name = rb.name;
            if (name == "Input" || name.rfind("Input", 0) == 0 ||
                name == "g_input" || name.rfind("g_input", 0) == 0) {
                hasInput = true;
            }
            if (name == "Output" || name.rfind("Output", 0) == 0 ||
                name == "g_output" || name.rfind("g_output", 0) == 0) {
                hasOutput = true;
            }
        }
        return hasInput && hasOutput;
    }();
    if (program != nullptr &&
        !program->vertexSpirv.empty() &&
        !program->geometryEmulated &&
        !program->tessellationEmulated &&
        !program->tessellationInterpreted &&
        (program->vertexSsboEmulatedDraw ||
         (impl_->state->isEnabled(GL_RASTERIZER_DISCARD) &&
          !ssboLayoutCopyResources &&
          !isTransformFeedbackActive() &&
          (!program->vertexReflection.storageBuffers.empty() ||
           !program->resourceStorageBlocks.empty())))) {
        if (std::getenv("APPGL_TRACE_VS_SSBO_EMUL")) {
            std::fprintf(stderr,
                "[VS-SSBO-emul] drawArrays enter program=%u flag=%d rd=%d "
                "spirv=%zu reflSSBO=%zu resources=%zu count=%d first=%d\n",
                programName, program->vertexSsboEmulatedDraw ? 1 : 0,
                impl_->state->isEnabled(GL_RASTERIZER_DISCARD) ? 1 : 0,
                program->vertexSpirv.size(),
                program->vertexReflection.storageBuffers.size(),
                program->resourceStorageBlocks.size(), count, first);
        }
        const GLuint vaoName = impl_->state->boundVertexArray();
        GLVertexArrayObject* vao = (vaoName != 0)
            ? impl_->objects->vertexArrays().get(vaoName) : nullptr;
        if (vao != nullptr) {
            const auto vsTexMap = impl_->buildSampledTextureMap(
                program->vertexSpirv,
                &program->vertexReflection, *program);
            const auto vsImgMap = impl_->buildStorageImageMap(
                program->vertexSpirv,
                &program->vertexReflection, *program);
            appgl::EmulatedDraw ed = appgl::emulateVsOnlyDrawForTf(
                *program, *vao, *impl_->objects, *impl_->state,
                mode, count, first,
                /*instanceCount=*/1, /*baseInstance=*/0,
                /*elementIndices=*/nullptr,
                vsTexMap.empty() ? nullptr : &vsTexMap,
                vsImgMap.empty() ? nullptr : &vsImgMap);
            if (std::getenv("APPGL_TRACE_VS_SSBO_EMUL")) {
                std::fprintf(stderr,
                    "[VS-SSBO-emul] drawArrays result ok=%d verts=%zu fpv=%zu diag=%s\n",
                    ed.ok ? 1 : 0, ed.vertexCount, ed.floatsPerVertex,
                    ed.diagnostic.c_str());
            }
            if (ed.ok) {
                if (impl_->state->isEnabled(GL_RASTERIZER_DISCARD)) {
                    if (!ed.pendingImageWrites.empty()) {
                        std::vector<GLuint> cpuImageWriteTextures;
                        impl_->flushPendingImageWritesForStage(
                            ed.pendingImageWrites,
                            &program->vertexReflection,
                            program->vertexSpirv,
                            *program,
                            GL_VERTEX_SHADER,
                            &cpuImageWriteTextures);
                        impl_->markCpuInterpreterImageWrites(cpuImageWriteTextures);
                    }
                    return true;
                }
                if (program->vertexSsboEmulatedDraw &&
                    impl_->encodeEmulatedGsDraw(*program, programName, ed)) {
                    return true;
                }
            } else if (!ed.diagnostic.empty()) {
                APPGL_LOG(SHADER, @"drawArrays VS-SSBO-emul: %s",
                          ed.diagnostic.c_str());
            }
        }
    }

    // CPU TES emulation — phase-3e-3 hook. Metal has no tessellation
    // stage; for programs whose TES body matches a recognised
    // passthrough/affine shape (matchTessEvalPassthrough in
    // TessellationEmulator.cpp), we generate the domain on the CPU
    // and render the expanded-vertex buffer through the same synth-
    // VS path the GS emulator uses.
    //
    // Detection happened at link time. If detectTessellationEmulatable
    // returned false (or APPGL_ENABLE_TESS_EMUL=0 was set), the flag
    // stays false and this branch is a no-op — the draw falls through
    // to the legacy translated path (which doesn't actually tessellate,
    // same behaviour as before the emulator existed).
    //
    // GS+TES together: if a program has both emulable stages, skip
    // the tess path here and let the GS emulator run. Combining the
    // two is phase 6+ work.
    // Metal-native tessellation path. Tier is set at link time:
    //   Phase2 — factor + indirect only (winding.* shape). Goes
    //     through the Phase-2 code path in `encodeMetalTessellationDraw`.
    //   Phase3 — VS-as-compute + TCS with per-CP / per-patch
    //     buffers. Same encoder, Phase-3 code path.
    //   None   — CPU tessellation interpreter.
    // Programs that need transform feedback or rasterizer-discard
    // side effects get downgraded to None at link time (TF-varyings
    // guard in linkProgram) + at draw time (transformFeedbackActive
    // guard in tryMetalTessellationDraw). GS-after-tess is also gated
    // off here; Phase 5 will extend the Metal path to consume TES
    // output through the GS emulator.
    // T4F fix: when pipeline-bound (currentProgram=0 and
    // resolveDrawProgram returned the VS container), tess metadata
    // lives on the SEPARABLE TES program — not on the resolved VS
    // container. Look up the pipeline's TES program (BeginTF chain:
    // GS > TES > VS, same as 26d056a) and use it for the gate decision
    // + tryMetalTessellationDraw. Without this, gl_MaxPatchVertices_*
    // pipeline-path main draws bail at this gate (VS container has
    // hasTessellation=false / metalTessTier=None) → fall through to
    // CPU emulator → TF buffer remains zero → verifier fails on
    // result_position_data.size() != 1.
    // β [metal-tess-TF]: when a pipeline with separable VS+TCS+TES+FS
    // is bound (currentProgram=0, resolveDrawProgram returned the VS
    // container which lacks tess metadata), ask the pipeline-time
    // orchestrator to synthesise a Metal-tess-ready combined program.
    // For step-1 scaffold this returns nullptr and we fall through to
    // the CPU emulator (existing behaviour) — step 2/3 fill in the
    // cross-stage translation + probe so the synthesised program is
    // tier=Phase3 with all PSOs built.
    GLProgramObject* tessProgram = program;
    GLuint tessProgramName = programName;
    bool pipelineHasEmulatedGeometry = false;
    if (impl_->state->currentProgram() == 0) {
        const GLuint ppoId = impl_->state->currentProgramPipeline();
        if (ppoId != 0) {
            if (GLProgramPipelineObject* ppo =
                    impl_->objects->programPipelines().get(ppoId)) {
                if (ppo->geometryProgram != 0) {
                    if (GLProgramObject* gs =
                            impl_->objects->programs().get(ppo->geometryProgram)) {
                        pipelineHasEmulatedGeometry = gs->geometryEmulated;
                    }
                }
                if (GLProgramObject* synth =
                        impl_->ensurePipelineTessSynthesizedProgram(*ppo)) {
                    tessProgram = synth;
                    tessProgramName = 0;  // synthetic — no GL program name
                } else if (ppo->tessEvalProgram != 0) {
                    if (GLProgramObject* tes =
                            impl_->objects->programs().get(ppo->tessEvalProgram)) {
                        tessProgram = tes;
                        tessProgramName = ppo->tessEvalProgram;
                    }
                }
            }
        }
    }
    if (tessProgram != nullptr &&
        tessProgram->hasTessellation &&
        tessProgram->metalTessTier != GLProgramObject::MetalTessTier::None &&
        !tessProgram->geometryEmulated &&
        !pipelineHasEmulatedGeometry) {
        auto hasStorageImageUniform = [&](const std::vector<std::uint32_t>& spirv,
                                          const ShaderReflection& reflection) -> bool {
            if (!reflection.storageImages.empty()) return true;
            if (spirv.empty()) return false;
            const auto vars = appgl::collectSamplerVarsFromSpirv(
                spirv.data(), spirv.size());
            constexpr const char* kAppglPrefix = "_appgl_";
            constexpr std::size_t kAppglPrefixLen = 7;
            for (const auto& v : vars) {
                std::string lookupName = v.name;
                if (lookupName.compare(0, kAppglPrefixLen, kAppglPrefix) == 0) {
                    lookupName = lookupName.substr(kAppglPrefixLen);
                }
                for (const auto& uniform : tessProgram->uniforms) {
                    if (uniform.name == lookupName && isImageUniformType(uniform.type)) {
                        return true;
                    }
                }
            }
            return false;
        };
        const bool hasTessAtomicCounterSideEffects = std::any_of(
            tessProgram->resourceAtomicCounterBuffers.begin(),
            tessProgram->resourceAtomicCounterBuffers.end(),
            [](const GLProgramResourceEntry& ac) {
                constexpr GLbitfield kTessHardwareStages =
                    0x01u | 0x02u | 0x08u | 0x10u;  // VS/FS/TCS/TES
                return (ac.referencedBy & kTessHardwareStages) != 0;
            });
        const bool hasImageUniformSideEffects = std::any_of(
            tessProgram->uniforms.begin(),
            tessProgram->uniforms.end(),
            [](const GLProgramUniformInfo& uniform) {
                return isImageUniformType(uniform.type);
            });
        const bool rejectMetalTessSideEffects =
            !tessProgram->vertexReflection.storageBuffers.empty() ||
            !tessProgram->tessControlReflection.storageBuffers.empty() ||
            !tessProgram->tessEvalAsComputeReflection.storageBuffers.empty() ||
            !tessProgram->fragmentReflection.storageBuffers.empty() ||
            hasStorageImageUniform(tessProgram->vertexSpirv,
                                   tessProgram->vertexReflection) ||
            hasStorageImageUniform(tessProgram->tessControlSpirv,
                                   tessProgram->tessControlReflection) ||
            hasStorageImageUniform(tessProgram->tessEvalSpirv,
                                   tessProgram->tessEvalAsComputeReflection) ||
            !tessProgram->fragmentReflection.storageImages.empty() ||
            hasImageUniformSideEffects ||
            hasTessAtomicCounterSideEffects;
        // TCS/TES side-effect routing: the Metal tess encoder currently binds only
        // its internal tess buffers plus sampled textures. Storage-image,
        // SSBO and atomic-counter side effects must route through the CPU
        // tess domain, where those GL objects are bound and observable.
        if (rejectMetalTessSideEffects) {
            APPGL_LOG(SHADER, @"drawArrays metal-tess skipped for storage-image/SSBO/atomic side effects");
        } else {
            if (impl_->tryMetalTessellationDraw(
                    *tessProgram, tessProgramName, mode, count, first)) {
                APPGL_LOG(DRAW, @"drawArrays metal-tess ok: count=%d first=%d",
                          count, first);
                if (!tessProgram->gsPresent) {
                    impl_->updateSubmittedPipelineStatsForNonGsDraw(
                        mode, count, 1);
                }
                return true;
            }
            APPGL_LOG(SHADER, @"drawArrays metal-tess encode failed — falling back to CPU interpreter");
        }
    }

    GLProgramObject* tessEmulProgram = tessProgram != nullptr ? tessProgram : program;
    const GLuint tessEmulProgramName = tessEmulProgram == tessProgram ? tessProgramName : programName;
    if (tessEmulProgram != nullptr &&
        (tessEmulProgram->tessellationEmulated || tessEmulProgram->tessellationInterpreted) &&
        !tessEmulProgram->geometryEmulated &&
        !pipelineHasEmulatedGeometry) {
        const GLuint vaoName = impl_->state->boundVertexArray();
        GLVertexArrayObject* tvao = (vaoName != 0)
            ? impl_->objects->vertexArrays().get(vaoName) : nullptr;
        if (tvao != nullptr) {
            // Sprint 16 Day 6 (CKPT215) — Tess OpImage gap. Build
            // per-stage sampler/storage-image maps so TCS/TES bodies
            // that call texture()/imageLoad()/imageStore() resolve
            // through real bindings instead of the empty-map fallback.
            // Sister-pattern to the GS-stage resolver at GLContext.mm:
            // 26265 (resolveSamplerBindings/resolveImageBindings).
            // tessControlReflection is the TCS reflection; the TES
            // reflection data lives in tessEvalAsComputeReflection
            // (legacy naming — also used by pure CPU emul path).
            appgl::SampledTextureMap vsSamMap, vsImgMap, tcsSamMap, tcsImgMap, tesSamMap, tesImgMap;
            if (!tessEmulProgram->vertexSpirv.empty()) {
                vsSamMap = impl_->buildSampledTextureMap(
                    tessEmulProgram->vertexSpirv,
                    &tessEmulProgram->vertexReflection, *tessEmulProgram);
                vsImgMap = impl_->buildStorageImageMap(
                    tessEmulProgram->vertexSpirv,
                    &tessEmulProgram->vertexReflection, *tessEmulProgram);
            }
            if (!tessEmulProgram->tessControlSpirv.empty()) {
                tcsSamMap = impl_->buildSampledTextureMap(
                    tessEmulProgram->tessControlSpirv,
                    &tessEmulProgram->tessControlReflection, *tessEmulProgram);
                tcsImgMap = impl_->buildStorageImageMap(
                    tessEmulProgram->tessControlSpirv,
                    &tessEmulProgram->tessControlReflection, *tessEmulProgram);
            }
            if (!tessEmulProgram->tessEvalSpirv.empty()) {
                tesSamMap = impl_->buildSampledTextureMap(
                    tessEmulProgram->tessEvalSpirv,
                    &tessEmulProgram->tessEvalAsComputeReflection, *tessEmulProgram);
                tesImgMap = impl_->buildStorageImageMap(
                    tessEmulProgram->tessEvalSpirv,
                    &tessEmulProgram->tessEvalAsComputeReflection, *tessEmulProgram);
            }
            appgl::EmulatedDraw ted = appgl::emulateTessellationDraw(
                *tessEmulProgram, *tvao, *impl_->objects, *impl_->state,
                mode, count, first, /*elementIndices=*/nullptr,
                /*instanceCount=*/1, /*baseInstance=*/0,
                tcsSamMap.empty() ? nullptr : &tcsSamMap,
                tcsImgMap.empty() ? nullptr : &tcsImgMap,
                tesSamMap.empty() ? nullptr : &tesSamMap,
                tesImgMap.empty() ? nullptr : &tesImgMap,
                vsSamMap.empty() ? nullptr : &vsSamMap,
                vsImgMap.empty() ? nullptr : &vsImgMap);
            if (ted.ok) {
                // Phase 3f-7: transform-feedback capture + rasterizer-
                // discard early-out. The helper walks
                // program.transformFeedbackVaryingNames against
                // ted.varyingNames, writes per-vertex bytes to the
                // bound TF buffers, and updates PRIMITIVES_GENERATED /
                // TRANSFORM_FEEDBACK_PRIMITIVES_WRITTEN queries. When
                // rasterDiscard is enabled it returns true so we skip
                // the Metal encode. Same helper the GS-emul path uses;
                // tess-emul's EmulatedDraw layout (position + varying
                // floats per vertex) is byte-compatible with what the
                // helper expects.
                if (impl_->writeGsXfbAndCheckDiscard(*tessEmulProgram, ted)) {
                    return true;
                }
                if (ted.vertexCount == 0) {
                    APPGL_LOG(DRAW, @"drawArrays tess-emul: zero verts");
                    return true;
                }
                if (impl_->encodeEmulatedGsDraw(*tessEmulProgram, tessEmulProgramName, ted)) {
                    APPGL_LOG(DRAW, @"drawArrays tess-emul ok: verts=%zu topo=0x%X",
                              ted.vertexCount, ted.topology);
                    return true;
                }
                APPGL_LOG(SHADER, @"drawArrays tess-emul encode failed");
                // Fall through to legacy path if encode fails.
            } else if (!ted.diagnostic.empty()) {
                APPGL_LOG(SHADER, @"drawArrays tess-emul: %s", ted.diagnostic.c_str());
            }
        }
    }

    // CPU GS emulation — step 3 hook. Metal has no geometry-shader
    // stage; for the narrow subset in KHR-GL46.constant_expressions.
    // *_geometry we run the GS on the CPU (see
    // docs/geometry-shader-emulation.md §4) and draw the expanded
    // vertex buffer through a synthesised pass-through VS (step 4).
    //
    // Detection happened at link time. If detectGeometryEmulatable
    // returned false, geometryEmulated is false and the draw falls
    // through to the normal translated path (which emits a VS+FS
    // pipeline without the GS effect — same behaviour as before the
    // emulator existed). If true, we call emulateGeometryDraw to
    // produce the expanded vertex buffer; .ok == false still falls
    // through so a runtime diagnostic on any single vertex doesn't
    // abort the frame.
    // Handle separable-pipeline GS emulation too. When no current
    // program is bound (glUseProgram(0) or never called), but a
    // pipeline object has a GS program marked emulable, the helper
    // merges the pipeline's VS vertexSpirv + FS fragmentMSL onto
    // the GS program and returns it as the emulation target.
    // Sprint 7 Phase 2 #7 (CKPT59): pass `state->currentProgram()` (not
    // the local `programName`, which `resolveDrawProgram` may have
    // overwritten with the pipeline's VS program name) so the helper's
    // glUseProgram-vs-pipeline disambiguation works correctly. Without
    // this, the helper hit its `currentProgramName != 0` fast path with
    // the resolved-VS name and returned the VS program, completely
    // bypassing the GS-only separable program in the pipeline. The
    // failing test for this path is `KHR-GL46.geometry_shader.api.
    // program_pipeline_vs_gs_capture`, which builds a separable VS-only
    // + GS-only pair joined via glUseProgramStages and calls
    // glUseProgram(0) before drawing.
    const GLuint glUseProgramName = impl_->state->currentProgram();
    GLuint emulProgramName = (glUseProgramName != 0) ? programName : 0;
    GLProgramObject* emulProgram = impl_->resolvePipelineEmulationProgram(
        glUseProgramName, emulProgramName);
    // Sprint 3 Step 2 Phase 2 [metal-mesh-GS]: try the mesh-shader path
    // first when the program's tier classifies as MeshShader. Default-on
    // post Path G+H verification (CKPT17 closed Phase 2 with +1 net gain
    // `gl_pointsize_value`, zero regressions, default-off invariant
    // 120/136 held, tess invariant 117/140 held). The previous
    // APPGL_ENABLE_MESH_GS env-gate is removed — encoder failure still
    // returns false → existing CPU GS interpreter path runs (natural
    // fallback) for any program that can't be mesh-tier-handled.
    // Sprint 7 prep (CKPT52 fix-path A): condition mesh-GS on
    // !transformFeedbackActive. The mesh-GS encoder writes to render
    // targets, not TF buffers; routing TF-active draws through it
    // silently zeros the TF capture. CPU GS-emul has full TF capture
    // support via writeGsXfbAndCheckDiscard. With TF active, fall
    // through to CPU emul.
    bool meshGsNativeAttempted = false;
    if (emulProgram != nullptr &&
        emulProgram->metalGSTier == GLProgramObject::MetalGSTier::MeshShader &&
        !impl_->transformFeedbackActive) {
        meshGsNativeAttempted = true;
        if (impl_->tryMetalMeshGSDraw(*emulProgram, emulProgramName,
                                       mode, count, first)) {
            APPGL_LOG(DRAW, @"drawArrays mesh-GS ok: count=%d", count);
            return true;
        }
        APPGL_LOG(SHADER, @"drawArrays mesh-GS encode failed — falling back to CPU emulator");
        if (!emulProgram->geometryEmulated) {
            appgl::AppGLSubmissionGroup fallbackGroup;
            impl_->declareMeshGsFallbackSubmissionGroup(fallbackGroup);
            APPGL_LOG(SHADER,
                      @"drawArrays mesh-GS exact fallback unavailable — consuming as unsupported");
            return true;
        }
    }
    if (emulProgram != nullptr && emulProgram->geometryEmulated) {
        const bool dcr4eExactNoLegacy =
            dcr4eRequiresExactCpuGsNoLegacyFallback(
                emulProgram, mode, isTransformFeedbackActive());
        const GLuint vaoName = impl_->state->boundVertexArray();
        GLVertexArrayObject* vao = (vaoName != 0) ? impl_->objects->vertexArrays().get(vaoName) : nullptr;
        if (vao != nullptr) {
            // Sprint 6 P1 sub-task 3 day 3 (CKPT43): build VS + GS
            // sampler-texture maps so CPU emul can sample real texel
            // values via OpImageSampleExplicitLod.
            const auto vsTexMap = impl_->buildSampledTextureMap(
                emulProgram->vertexSpirv,
                &emulProgram->vertexReflection, *emulProgram);
            const auto gsTexMap = impl_->buildSampledTextureMap(
                emulProgram->geometrySpirv,
                &emulProgram->geometryReflection, *emulProgram);
            // Sprint 7 Phase 1 #4 (CKPT54): same shape, storage-image
            // counterpart for OpImageRead in GS-emul.
            const auto vsImgMap = impl_->buildStorageImageMap(
                emulProgram->vertexSpirv,
                &emulProgram->vertexReflection, *emulProgram);
            const auto gsImgMap = impl_->buildStorageImageMap(
                emulProgram->geometrySpirv,
                &emulProgram->geometryReflection, *emulProgram);
            // Sprint 8 #8 β.3 (CKPT97): tess+GS plumbing. When the
            // program has BOTH tess and GS emulation enabled, run the
            // tess-emul stage first to produce per-vertex post-tess
            // output, then feed that into the GS-emul as
            // priorStageOutput. Without this, the GS-emul's VS pre-pass
            // bypasses tess entirely and the GS reads garbage from
            // gl_in[].tc_position (CTS data_pass_through tests fail
            // with "expected [1,1,1,1] found [0,0,0,0]" at odd indices
            // where the GS's `+1` pass-through modification didn't run).
            appgl::EmulatedDraw priorStage;
            const bool hasTess = emulProgram->tessellationEmulated ||
                                 emulProgram->tessellationInterpreted;
            if (hasTess) {
                // Sprint 16 Day 6 (CKPT215) — Tess OpImage gap; build
                // TCS/TES sampler+image maps for tess+GS path too.
                appgl::SampledTextureMap _tcsSam, _tcsImg, _tesSam, _tesImg;
                if (!emulProgram->tessControlSpirv.empty()) {
                    _tcsSam = impl_->buildSampledTextureMap(
                        emulProgram->tessControlSpirv,
                        &emulProgram->tessControlReflection, *emulProgram);
                    _tcsImg = impl_->buildStorageImageMap(
                        emulProgram->tessControlSpirv,
                        &emulProgram->tessControlReflection, *emulProgram);
                }
                if (!emulProgram->tessEvalSpirv.empty()) {
                    _tesSam = impl_->buildSampledTextureMap(
                        emulProgram->tessEvalSpirv,
                        &emulProgram->tessEvalAsComputeReflection, *emulProgram);
                    _tesImg = impl_->buildStorageImageMap(
                        emulProgram->tessEvalSpirv,
                        &emulProgram->tessEvalAsComputeReflection, *emulProgram);
                }
                priorStage = appgl::emulateTessellationDraw(
                    *emulProgram, *vao, *impl_->objects, *impl_->state,
                    mode, count, first, /*elementIndices=*/nullptr,
                    /*instanceCount=*/1, /*baseInstance=*/0,
                    _tcsSam.empty() ? nullptr : &_tcsSam,
                    _tcsImg.empty() ? nullptr : &_tcsImg,
                    _tesSam.empty() ? nullptr : &_tesSam,
                    _tesImg.empty() ? nullptr : &_tesImg,
                    vsTexMap.empty() ? nullptr : &vsTexMap,
                    vsImgMap.empty() ? nullptr : &vsImgMap);
                if (!priorStage.ok && !priorStage.diagnostic.empty()) {
                    APPGL_LOG(SHADER, @"drawArrays tess+GS: tess-emul: %s",
                              priorStage.diagnostic.c_str());
                }
            }
            appgl::EmulatedDraw ed = appgl::emulateGeometryDraw(
                *emulProgram, *vao, *impl_->objects, *impl_->state,
                mode, count, first, /*elementIndices=*/nullptr,
                /*instanceCount=*/1, /*baseInstance=*/0,
                vsTexMap.empty() ? nullptr : &vsTexMap,
                gsTexMap.empty() ? nullptr : &gsTexMap,
                vsImgMap.empty() ? nullptr : &vsImgMap,
                gsImgMap.empty() ? nullptr : &gsImgMap,
                (hasTess && priorStage.ok) ? &priorStage : nullptr);
            if (ed.ok) {
                // XFB capture + rasterDiscard early-out lives in a
                // shared helper so drawElements can run the same path.
                if (impl_->writeGsXfbAndCheckDiscard(*emulProgram, ed)) {
                    return true;
                }
                // GS ran successfully but emitted zero output
                // primitives (e.g. a triangle_strip body with
                // fewer than 3 EmitVertex calls). Consume the draw
                // here instead of falling through to the legacy
                // VS+FS pipeline — that path would render the VS's
                // raw gl_Position as a point and scribble fragments
                // the test explicitly expects to stay cleared.
                if (ed.vertexCount == 0) {
                    APPGL_LOG(DRAW, @"drawArrays GS-emul: zero primitives");
                    return true;
                }
                if (impl_->encodeEmulatedGsDraw(
                        *emulProgram, emulProgramName, ed,
                        meshGsNativeAttempted
                            ? AppGLSubmissionGroupKind::FallbackNs
                            : AppGLSubmissionGroupKind::None)) {
                    APPGL_LOG(DRAW, @"drawArrays GS-emul ok: verts=%zu topo=0x%X",
                              ed.vertexCount, ed.topology);
                    return true;
                }
                APPGL_LOG(SHADER, @"drawArrays GS-emul encode failed");
                if (dcr4eExactNoLegacy) {
                    appgl::AppGLSubmissionGroup fallbackGroup;
                    impl_->declareCpuGsFallbackSubmissionGroup(fallbackGroup);
                    APPGL_LOG(SHADER,
                              @"drawArrays GS-emul exact path failed — consuming as unsupported");
                    return true;
                }
                // Fall through to the legacy path if encode fails
                // for non-B4 draws.
            } else if (!ed.diagnostic.empty()) {
                APPGL_LOG(SHADER, @"drawArrays GS-emul: %s", ed.diagnostic.c_str());
                if (dcr4eExactNoLegacy) {
                    appgl::AppGLSubmissionGroup fallbackGroup;
                    impl_->declareCpuGsFallbackSubmissionGroup(fallbackGroup);
                    APPGL_LOG(SHADER,
                              @"drawArrays GS-emul exact interpreter failed — consuming as unsupported");
                    return true;
                }
            } else if (dcr4eExactNoLegacy) {
                appgl::AppGLSubmissionGroup fallbackGroup;
                impl_->declareCpuGsFallbackSubmissionGroup(fallbackGroup);
                APPGL_LOG(SHADER,
                          @"drawArrays GS-emul exact interpreter failed — consuming as unsupported");
                return true;
            }
        }
    }

    // Sprint 7 Phase 2 #7 (CKPT59): VS-only TF emulation. When TF is
    // active, the program has TF varyings, no GS is in the pipeline,
    // and no tess emulation applies, run the VS on CPU per vertex and
    // write captures via the shared writeGsXfbAndCheckDiscard helper.
    // Required for separable VS-only programs (CTS
    // `program_pipeline_vs_gs_capture` pass 2 detaches the GS via
    // glUseProgramStages(GS_BIT, 0) and expects subsequent draws to
    // capture VS outputs to TF).
    // Sprint 8 #9-C (CKPT68): the original CKPT59 gate restricted to
    // `emulProgram == nullptr` to scope VS-only-TF to separable VS-only
    // programs. That over-restricts: any program with no GS/tess emul
    // (regardless of separable status) needs VS-only-TF capture during
    // active TF. Relax to `(emulProgram == nullptr || !emulProgram->
    // geometryEmulated)` — the GS-emul block at line ~24508 only runs
    // when emulProgram->geometryEmulated, so guarding on that condition
    // here mirrors that block's gate exactly. CTS draw_xfb_instanced_test
    // uses a non-separable VS+FS program with TF varyings; without this
    // relaxation, emulProgram is non-null (set to the same program) but
    // doesn't have geometryEmulated, and VS-only-TF skipped → no
    // capturedVertexCount accumulation → glDrawTransformFeedbackInstanced
    // gets count=0 → test fails.
    if (program != nullptr &&
        isTransformFeedbackActive() &&  // CKPT85: per-bound-object
        !program->transformFeedbackVaryingNames.empty() &&
        (emulProgram == nullptr || !emulProgram->geometryEmulated) &&
        !program->geometryEmulated &&
        !program->tessellationEmulated &&
        !program->tessellationInterpreted) {
        const GLuint vaoName2 = impl_->state->boundVertexArray();
        GLVertexArrayObject* vao = (vaoName2 != 0) ? impl_->objects->vertexArrays().get(vaoName2) : nullptr;
        if (vao != nullptr && !program->vertexSpirv.empty()) {
            std::vector<std::uint32_t> tfCaptureIndices;
            GLenum tfCaptureTopology = mode;
            const bool useTfCaptureIndices =
                buildSequentialTfCaptureIndices(
                    mode, first, count, tfCaptureIndices, tfCaptureTopology);
            // Sprint 15 Q3-Option-B Phase 3a [metal-tf-vs]: GPU
            // compute-dispatch path. Replaces the CPU
            // `emulateVsOnlyDrawForTf` SPIR-V interpreter with a Metal
            // VS-as-compute dispatch when the program has a built
            // VS-compute PSO + a reflected output struct + all TF
            // varyings resolved at link time. Day 4 constraint: only
            // attributeless VS programs (`metalVsTfNeedsDescriptor==
            // false`) AND no default-uniform-block usage AND no UBOs
            // (Phase 3a doesn't bind uniforms; Phase 3b adds that).
            // Phase 3c (Day 6+) extends to VAO-bound stage_in
            // programs via `metalVsTfComputePSOCache`.
            //
            // Phase 3a is groundwork-only: gated behind the secondary
            // `APPGL_ENABLE_METAL_TF_VS_DISPATCH=1` env so it stays
            // off by default until Phase 3b lands proper uniform
            // binding. With only the primary gate
            // `APPGL_ENABLE_METAL_TF_VS=1` set, Phase 1+2 link-time
            // reflection runs but draw-time still routes via the
            // CPU helper (preserves CKPT173+CKPT174 behaviour).
            //
            // Falls back to CPU helper on any precondition mismatch
            // OR encoder failure — preserving correctness.
            const bool dispatchGateOn =
                std::getenv("APPGL_ENABLE_METAL_TF_VS_DISPATCH") != nullptr;
            // Phase 3a doesn't yet bind uniform-block bytes — skip
            // GPU path when the VS uses any uniform block (default or
            // named). Phase 3b (Day 5) will populate the uniform
            // bytes from `program->uniformValues` per
            // `vsTfAsComputeReflection`. The VS-as-compute MSL embeds
            // its own default-uniform-block as a UBO at slot 16 (per
            // SPIRV-Cross's tess emit convention), which is exactly
            // what `program.uniforms` feeds when populated.
            // Sprint 15 Day 27 (CKPT200): Phase 3b proper Component A —
            // relax the noUniforms gate and pack uniform bytes from
            // program.uniformValues into the compute encoder at slot
            // 16. Sister-pattern reuse from tess Phase 3 uniform path
            // (line ~25584-25590, `tessVertexAsComputeUniformLayout`
            // + `buildStageUniformBuffer`). The cached layout on the
            // program object survives across draws (link-time stable);
            // packing the byte buffer per draw is cheap.
            bool gpuTfHandled = false;
            if (dispatchGateOn &&
                !useTfCaptureIndices &&
                program->metalVsTfTier ==
                    GLProgramObject::MetalVsTfTier::VsAsCompute &&
                program->metalVsTfComputePipelineState != nullptr &&
                !program->metalVsTfNeedsDescriptor &&
                program->vsTfOutputLayout.structSize > 0 &&
                !program->vsTfResolvedSources.empty() &&
                impl_->frameGraph != nullptr &&
                count > 0 && first >= 0) {
                // Verify every TF varying name resolved (skip GPU
                // path otherwise — CPU helper covers exotic varying
                // shapes more robustly).
                bool allResolved = true;
                for (const auto& s : program->vsTfResolvedSources) {
                    if (s.bytes == 0) { allResolved = false; break; }
                }
                if (allResolved) {
                    const std::size_t perVertexBytes =
                        program->vsTfOutputLayout.structSize;
                    std::vector<std::uint8_t> outBytes(
                        perVertexBytes * static_cast<std::size_t>(count));
                    // Phase 3b Component A: pack uniform bytes when
                    // the VS reflection reports any uniform blocks.
                    // Lazy layout-cache build on first dispatch.
                    thread_local std::vector<std::uint8_t> vsTfUniformScratch;
                    const std::uint8_t* uniformBytesPtr = nullptr;
                    std::size_t uniformBytesLen = 0;
                    if (!program->vsTfAsComputeReflection.uniformBlocks.empty()) {
                        if (program->vsTfAsComputeUniformLayout.empty()) {
                            computeStageUniformLayout(
                                program->vsTfAsComputeUniformLayout,
                                program->vsTfAsComputeReflection,
                                program->uniforms);
                        }
                        if (!program->vsTfAsComputeUniformLayout.empty()) {
                            buildStageUniformBuffer(
                                vsTfUniformScratch,
                                program->vsTfAsComputeReflection,
                                program->uniformValues,
                                program->vsTfAsComputeUniformLayout);
                            uniformBytesPtr = vsTfUniformScratch.data();
                            uniformBytesLen = vsTfUniformScratch.size();
                        }
                    }
                    const bool encodeOk =
                        impl_->frameGraph->encodeVsTfComputeDraw(
                            program->metalVsTfComputePipelineState,
                            static_cast<std::uint32_t>(count),
                            perVertexBytes,
                            uniformBytesPtr,
                            uniformBytesLen,
                            outBytes.data());
                    if (encodeOk) {
                        impl_->writeVsTfFromComputeOutput(
                            *program, outBytes.data(),
                            static_cast<std::uint32_t>(count),
                            perVertexBytes, mode);
                        if (impl_->state->isEnabled(GL_RASTERIZER_DISCARD)) {
                            return true;
                        }
                        // Without rasterizer-discard, fall through to
                        // the regular Metal-side draw so the FS still
                        // runs. TF buffer is already populated above.
                        gpuTfHandled = true;
                    }
                }
            }
            if (!gpuTfHandled) {
                const auto vsTexMap = impl_->buildSampledTextureMap(
                    program->vertexSpirv,
                    &program->vertexReflection, *program);
                const auto vsImgMap = impl_->buildStorageImageMap(
                    program->vertexSpirv,
                    &program->vertexReflection, *program);
                const GLenum vsTfMode =
                    useTfCaptureIndices ? tfCaptureTopology : mode;
                const GLsizei vsTfCount = useTfCaptureIndices
                    ? static_cast<GLsizei>(tfCaptureIndices.size())
                    : count;
                const GLint vsTfFirst = useTfCaptureIndices ? 0 : first;
                const std::uint32_t* vsTfIndices = useTfCaptureIndices
                    ? tfCaptureIndices.data()
                    : nullptr;
                appgl::EmulatedDraw ed = appgl::emulateVsOnlyDrawForTf(
                    *program, *vao, *impl_->objects, *impl_->state,
                    vsTfMode, vsTfCount, vsTfFirst,
                    /*instanceCount=*/1, /*baseInstance=*/0,
                    vsTfIndices,
                    vsTexMap.empty() ? nullptr : &vsTexMap,
                    vsImgMap.empty() ? nullptr : &vsImgMap);
                if (ed.ok) {
                    bool discard = false;
                    if (appgl::vsOnlyTfTimingEnabled()) {
                        const std::uint64_t t0 = appgl::vsOnlyTfTimingNowNs();
                        discard = impl_->writeGsXfbAndCheckDiscard(*program, ed);
                        appgl::recordVsOnlyTfWriteDurationNs(
                            appgl::vsOnlyTfTimingNowNs() - t0);
                    } else {
                        discard = impl_->writeGsXfbAndCheckDiscard(*program, ed);
                    }
                    if (discard) {
                        return true;
                    }
                    // VS-only-TF without rasterizer-discard: fall
                    // through to the regular Metal-side draw so the
                    // FS still runs. The TF buffer was already
                    // populated.
                } else if (!ed.diagnostic.empty()) {
                    APPGL_LOG(SHADER, @"drawArrays VS-only-TF: %s",
                              ed.diagnostic.c_str());
                }
            }
        }
    }

    // Side-effect-only VS image programs can translate to `vertex void`
    // MSL with no position output. Metal may optimize away such render
    // work, but GL still executes the vertex shader side effects.
    if (program != nullptr &&
        program->hasTranslatedPipeline &&
        !program->vertexSpirv.empty() &&
        !program->vertexReflection.storageImages.empty() &&
        program->vertexMSL.find("vertex void ") != std::string::npos &&
        program->fragmentMSL.find("discard_fragment()") != std::string::npos) {
        GLVertexArrayObject* vao = impl_->currentVertexArrayOrDefault();
        if (vao != nullptr) {
            const auto vsTexMap = impl_->buildSampledTextureMap(
                program->vertexSpirv,
                &program->vertexReflection, *program);
            const auto vsImgMap = impl_->buildStorageImageMap(
                program->vertexSpirv,
                &program->vertexReflection, *program);
            appgl::EmulatedDraw ed = appgl::emulateVsOnlyDrawForTf(
                *program, *vao, *impl_->objects, *impl_->state,
                mode, count, first,
                /*instanceCount=*/1, /*baseInstance=*/0,
                /*elementIndices=*/nullptr,
                vsTexMap.empty() ? nullptr : &vsTexMap,
                vsImgMap.empty() ? nullptr : &vsImgMap);
            if (ed.ok) {
                if (!ed.pendingImageWrites.empty()) {
                    std::vector<GLuint> cpuImageWriteTextures;
                    impl_->flushPendingImageWritesForStage(
                        ed.pendingImageWrites,
                        &program->vertexReflection,
                        program->vertexSpirv,
                        *program,
                        GL_VERTEX_SHADER,
                        &cpuImageWriteTextures);
                    impl_->markCpuInterpreterImageWrites(cpuImageWriteTextures);
                }
                if (!program->gsPresent) {
                    impl_->updatePrimitiveCountersForNonGsDraw(mode, count, 1);
                }
                return true;
            } else if (!ed.diagnostic.empty()) {
                APPGL_LOG(SHADER, @"drawArrays VS-image-side-effects: %s",
                          ed.diagnostic.c_str());
            }
        }
    }

    // Sprint 17 Day 7+ Bank-Group-H Path B Component B (drawArrays):
    // VS+FS programs that write gl_CullDistance get a CPU pre-pass +
    // Metal indexed-draw routing. Phase 2 §1.2 confirmed this is gated
    // on `needsCullDistancePrepass` (link-time A1 detect: VS writes
    // CullDistance && !gsPresent && !hasTessellation) + line/triangle
    // topology. Component E (Phase 3 day 5) handles TF coordination.
    if (program != nullptr && program->needsCullDistancePrepass &&
        program->hasTranslatedPipeline) {
        const bool isLineOrTri =
            (mode == GL_POINTS || mode == GL_LINES || mode == GL_TRIANGLES ||
             mode == GL_LINE_STRIP || mode == GL_LINE_LOOP ||
             mode == GL_TRIANGLE_STRIP || mode == GL_TRIANGLE_FAN);
        if (isLineOrTri) {
            const GLuint vaoNameCP = impl_->state->boundVertexArray();
            GLVertexArrayObject* vaoCP = (vaoNameCP != 0)
                ? impl_->objects->vertexArrays().get(vaoNameCP) : nullptr;
            if (vaoCP != nullptr) {
                std::vector<std::uint32_t> filteredIdx;
                std::string cullDiag;
                const bool prepassOk = appgl::emulateVsCullPrepass(
                    *program, *vaoCP, *impl_->objects, *impl_->state,
                    mode, count, first, /*elementIndices=*/nullptr,
                    /*instanceCount=*/1, /*baseInstance=*/0,
                    filteredIdx, &cullDiag);
                if (prepassOk) {
                    if (filteredIdx.empty()) {
                        // GL §14.6.3 — all primitives culled. Count
                        // input primitives and short-circuit. Legacy
                        // path is bypassed so do the counter update
                        // here (its own update would otherwise run
                        // in the fall-through case below).
                        if (!program->gsPresent) {
                            impl_->updatePrimitiveCountersForNonGsDraw(
                                mode, count, 1);
                        }
                        return true;
                    }
                    if (impl_->dispatchCullFilteredDraw(
                            *program, *vaoCP, programName, mode,
                            filteredIdx)) {
                        if (!program->gsPresent) {
                            impl_->updatePrimitiveCountersForNonGsDraw(
                                mode, count, 1);
                        }
                        return true;
                    }
                    // Fall through to legacy path on encode failure
                    // (legacy path runs its own counter update).
                } else if (!cullDiag.empty()) {
                    APPGL_LOG(SHADER, @"drawArrays cull-prepass: %s",
                              cullDiag.c_str());
                }
            }
        }
    }

    drawProfile.mark(GLDrawProfileBucket::SpecialPathChecks);
    const bool translatedDrawArraysEligible = [&]() {
        GLDrawDetailScope detail(
            impl_->drawDetailProfile,
            GLDrawDetailBucket::TranslatedDrawEligibility);
        return program != nullptr && program->hasTranslatedPipeline;
    }();
    if (translatedDrawArraysEligible) {
        // GL 4.6 §22.1 / §22.3 — non-GS draws credit the
        // PRIMITIVES_GENERATED and TRANSFORM_FEEDBACK_PRIMITIVES_-
        // WRITTEN counters with the input-primitive count. GS-
        // emulated draws already counted post-GS primitives inside
        // writeGsXfbAndCheckDiscard, so skip this path to avoid
        // double-counting.
        GLuint vaoName = 0;
        GLVertexArrayObject* vao = nullptr;
        {
            GLDrawDetailScope detail(
                impl_->drawDetailProfile,
                GLDrawDetailBucket::TranslatedProgramVaoFboState);
            {
                ColdPathDiagnosticScope cold(
                    &impl_->coldPathProfile,
                    ColdPathDiagnosticBucket::ProgramVaoFboPrimitiveCounters);
                if (!program->gsPresent) {
                    impl_->updatePrimitiveCountersForNonGsDraw(mode, count, 1);
                }
            }
            {
                ColdPathDiagnosticScope cold(
                    &impl_->coldPathProfile,
                    ColdPathDiagnosticBucket::ProgramVaoFboFrontendVaoSource);
                vaoName = impl_->state->boundVertexArray();
                vao = (vaoName != 0)
                    ? impl_->objects->vertexArrays().get(vaoName)
                    : nullptr;
            }
        }
        // Phase 8X Group 4d follow-up³ — name each fall-through gate to BAR's log.
        bool gateEmpty = false;
        // Attributeless draw path: vertex shader has no vertex inputs
        // (generates its own vertices via gl_VertexID / [[vertex_id]]).
        bool attributelessDraw = false;
        {
            GLDrawDetailScope detail(
                impl_->drawDetailProfile,
                GLDrawDetailBucket::TranslatedFallbackDecision);
            gateEmpty = (vao == nullptr || vao->attributes.empty());
            attributelessDraw = (vao != nullptr &&
                program->vertexReflection.vertexInputs.empty());
        }
        drawProfile.mark(GLDrawProfileBucket::TranslatedPreflight);
        if (attributelessDraw) {
            TranslatedDrawInfo& tdi = reusableTranslatedDrawInfo();
            tdi.mode = mode;
            tdi.vertexCount = count;
            tdi.baseVertex = first;
            // No vertex data — shader uses gl_VertexID / [[vertex_id]].
            tdi.vertexData = nullptr;
            tdi.vertexDataByteCount = 0;
            tdi.vertexStride = 0;
            populateTranslatedDrawFixedFunctionState(
                tdi, *impl_->state, effectiveFragmentShadingRateForProgram(*this, program), this);
            assignTranslatedDrawProgramMsl(tdi, *program);
            tdi.vertexReflection = &program->vertexReflection;
            tdi.fragmentReflection = &program->fragmentReflection;
            tdi.pipelineStateOut = &program->metalPipelineState;
            tdi.pipelineColorFormatOut = &program->metalPipelineColorFormat;
            tdi.pipelineStateCacheOut = &program->metalPipelineStateCache;
            tdi.metalVertexFunction = program->metalVertexFunction;
            tdi.metalFragmentFunction = program->metalFragmentFunction;
            tdi.metalVertexFunctionOut = &program->metalVertexFunction;
            tdi.metalFragmentFunctionOut = &program->metalFragmentFunction;
            tdi.program = programName;
            tdi.pipelineEmulationFragmentProgram =
                program->pipelineEmulationFragmentProgram;

            logStateResolveCostClass(
                "drawArrays-attributeless", programName, vaoName,
                tdi, vao->attributes.size());
            prepareTranslatedDrawUniformBuffers(
                *program, programName, impl_->matrixState, drawID, tdi,
                "drawArrays-attributeless");

            impl_->resolveSamplerBindings(*program, tdi);
            impl_->resolveUBOBindings(*program, tdi);
            impl_->resolveSSBOBindings(*program, tdi);
            impl_->resolveImageBindings(*program, tdi);

            // RC-A02: resolve FBO render target.
            {
                GLsizei fboW = 0, fboH = 0;
                void* fboDSTex = nullptr;
                std::array<void*, 7> extraColTex = {};
                std::array<std::uint32_t, 8> colSlices = {};
                std::array<std::uint32_t, 8> colLevels = {};
                void* fboColTex = impl_->resolveFBOColorTarget(
                    fboW, fboH, fboDSTex, nullptr,
                    &extraColTex, &colSlices, &colLevels);
                if (fboColTex != nullptr || fboDSTex != nullptr) {
                    tdi.fboColorTexture = fboColTex;
                    tdi.fboAdditionalColorTextures = extraColTex;
                    tdi.fboColorSlices = colSlices;
                    tdi.fboColorLevels = colLevels;
                    tdi.fboDepthStencilTexture = fboDSTex;
                    tdi.fboWidth = fboW;
                    tdi.fboHeight = fboH;
                }
            }

            thread_local std::string pipelineBuildError;
            pipelineBuildError.clear();
            tdi.pipelineBuildErrorOut = &pipelineBuildError;

            const TranslatedDrawPreflightSnapshot preflight =
                makeTranslatedDrawPreflightSnapshot(
                    vaoName, vao,
                    /*genericVertexAttributesPrepared=*/true);
            const bool ok = impl_->encodeTranslatedDrawAndMarkFbo(
                tdi, &preflight);
            if (ok) {
                return true;
            }
            // Fall through to solid-color path on failure.
        }
        if (vao == nullptr) {
            reportTranslatedFallbackOnce(program, programName,
                TranslatedFallbackGate::EmptyAttributes, "drawArrays",
                vaoName, 0, 0, 0);
        }
        if (vao != nullptr && !vao->attributes.empty()) {
            bool vaoLayoutCacheHit = false;
            const GLVertexArrayCachedLayout* vaoLayoutPtr = nullptr;
            {
                GLDrawDetailScope detail(
                    impl_->drawDetailProfile,
                    GLDrawDetailBucket::TranslatedProgramVaoFboState);
                vaoLayoutPtr =
                    &cachedVertexArrayLayout(
                        *vao, false, &vaoLayoutCacheHit,
                        false, true, &impl_->coldPathProfile);
            }
            const auto& vaoLayout = *vaoLayoutPtr;
            drawProfile.mark(GLDrawProfileBucket::VaoLayout);
            const bool foundEnabledAttrib = vaoLayout.hasEnabledAttributes;
            if (!foundEnabledAttrib &&
                !program->vertexReflection.vertexInputs.empty()) {
                TranslatedDrawInfo& tdi = reusableTranslatedDrawInfo();
                tdi.mode = mode;
                tdi.vertexCount = count;
                tdi.baseVertex = first;
                tdi.vertexData = nullptr;
                tdi.vertexDataByteCount = 0;
                tdi.vertexStride = 0;
                populateTranslatedDrawFixedFunctionState(
                    tdi, *impl_->state,
                    effectiveFragmentShadingRateForProgram(*this, program),
                    this);
                assignTranslatedDrawProgramMsl(tdi, *program);
                tdi.vertexReflection = &program->vertexReflection;
                tdi.fragmentReflection = &program->fragmentReflection;
                tdi.pipelineStateOut = &program->metalPipelineState;
                tdi.pipelineColorFormatOut = &program->metalPipelineColorFormat;
                tdi.pipelineStateCacheOut = &program->metalPipelineStateCache;
                tdi.metalVertexFunction = program->metalVertexFunction;
                tdi.metalFragmentFunction = program->metalFragmentFunction;
                tdi.metalVertexFunctionOut = &program->metalVertexFunction;
                tdi.metalFragmentFunctionOut = &program->metalFragmentFunction;
                tdi.program = programName;
                tdi.pipelineEmulationFragmentProgram =
                    program->pipelineEmulationFragmentProgram;
                appendCurrentGenericVertexAttributes(
                    tdi, vao, &impl_->coldPathProfile);

                logStateResolveCostClass(
                    "drawArrays-generic-attrs", programName, vaoName,
                    tdi, vao->attributes.size());
                prepareTranslatedDrawUniformBuffers(
                    *program, programName, impl_->matrixState, drawID, tdi,
                    "drawArrays-generic-attrs");

                impl_->resolveSamplerBindings(*program, tdi);
                impl_->resolveUBOBindings(*program, tdi);
                impl_->resolveSSBOBindings(*program, tdi);
                impl_->resolveImageBindings(*program, tdi);

                {
                    GLsizei fboW = 0, fboH = 0;
                    void* fboDSTex = nullptr;
                    std::array<void*, 7> extraColTex = {};
                    std::array<std::uint32_t, 8> colSlices = {};
                    std::array<std::uint32_t, 8> colLevels = {};
                    void* fboColTex = impl_->resolveFBOColorTarget(
                        fboW, fboH, fboDSTex, nullptr,
                        &extraColTex, &colSlices, &colLevels);
                    if (fboColTex != nullptr || fboDSTex != nullptr) {
                        tdi.fboColorTexture = fboColTex;
                        tdi.fboAdditionalColorTextures = extraColTex;
                        tdi.fboColorSlices = colSlices;
                        tdi.fboColorLevels = colLevels;
                        tdi.fboDepthStencilTexture = fboDSTex;
                        tdi.fboWidth = fboW;
                        tdi.fboHeight = fboH;
                    }
                }

                thread_local std::string pipelineBuildErrorConst;
                pipelineBuildErrorConst.clear();
                tdi.pipelineBuildErrorOut = &pipelineBuildErrorConst;

                const TranslatedDrawPreflightSnapshot preflight =
                    makeTranslatedDrawPreflightSnapshot(
                        vaoName, vao,
                        /*genericVertexAttributesPrepared=*/true);
                const bool ok = impl_->encodeTranslatedDrawAndMarkFbo(
                    tdi, &preflight);
                if (ok) {
                    return true;
                }
                if (reportTranslatedFallbackOnce(program, programName,
                        TranslatedFallbackGate::EncodeFailed, "drawArrays",
                        vaoName, vao->attributes.size(), 0, 0)) {
                    recordPipelineBuildFailureOnce(
                        program, programName, pipelineBuildErrorConst);
                }
            }
            GLBufferObject* vbo = (vaoLayout.primaryBufferName != 0)
                ? impl_->objects->buffers().get(vaoLayout.primaryBufferName)
                : nullptr;
            if (vbo == nullptr) {
                reportTranslatedFallbackOnce(program, programName,
                    TranslatedFallbackGate::NullVBO, "drawArrays",
                    vaoName, vao->attributes.size(), vaoLayout.primaryBufferName, 0);
            } else if (vbo->shadowBytes.empty()) {
                reportTranslatedFallbackOnce(program, programName,
                    TranslatedFallbackGate::ShadowBytesEmpty, "drawArrays",
                    vaoName, vao->attributes.size(), vaoLayout.primaryBufferName, 0);
            }
            drawProfile.mark(GLDrawProfileBucket::VboResolve);
            if (vbo != nullptr && !vbo->shadowBytes.empty()) {
                const std::size_t posStride = vaoLayout.primaryStride;
                const std::size_t firstOff = static_cast<std::size_t>(first) * posStride;
                const std::size_t startOff =
                    vaoLayout.primaryBaseOffset + firstOff;

                if (startOff > vbo->shadowBytes.size()) {
                    reportTranslatedFallbackOnce(program, programName,
                        TranslatedFallbackGate::OffsetOverflow, "drawArrays",
                        vaoName, vao->attributes.size(), vaoLayout.primaryBufferName,
                        vbo->shadowBytes.size());
                }
                if (startOff <= vbo->shadowBytes.size()) {
                    TranslatedDrawInfo& tdi = reusableTranslatedDrawInfo();
                    tdi.mode = mode;
                    tdi.vertexCount = count;
                    tdi.vertexData = vbo->shadowBytes.data() + startOff;
                    tdi.vertexDataByteCount = vbo->shadowBytes.size() - startOff;
                    tdi.vertexStride = posStride;
                    // OPT-5: pass pre-uploaded Metal buffer for direct bind.
                    tdi.metalVertexBuffer = vbo->metalBuffer;
                    tdi.metalVertexBufferOffset = startOff;
                    tdi.glVertexBuffer = vaoLayout.primaryBufferName;
                    drawProfile.mark(GLDrawProfileBucket::InfoInit);
                    // Phase 8X Group 4d follow-up¹⁴ — centralised fixed-
                    // function state snapshot (depth/cull/front-face/
                    // wireframe/blend). Replaces the prior inline reads
                    // so drawArrays / drawArraysInstanced / drawElements
                    // all capture identical state.
                    populateTranslatedDrawFixedFunctionState(
                        tdi, *impl_->state, effectiveFragmentShadingRateForProgram(*this, program), this);
                    drawProfile.mark(GLDrawProfileBucket::FixedFunctionState);
                    assignTranslatedDrawProgramMsl(tdi, *program);
                    tdi.vertexReflection = &program->vertexReflection;
                    tdi.fragmentReflection = &program->fragmentReflection;
                    tdi.pipelineStateOut = &program->metalPipelineState;
                    tdi.pipelineColorFormatOut = &program->metalPipelineColorFormat;
                    // Phase 8X Group 4d follow-up¹⁴ — map-based cache
                    // so spring's 15×/frame blend toggle doesn't thrash
                    // the single-slot scalar cache above.
                    tdi.pipelineStateCacheOut = &program->metalPipelineStateCache;
                    tdi.metalVertexFunction = program->metalVertexFunction;
                    tdi.metalFragmentFunction = program->metalFragmentFunction;
                    tdi.metalVertexFunctionOut = &program->metalVertexFunction;
                    tdi.metalFragmentFunctionOut = &program->metalFragmentFunction;
                    // Phase 8X Group 4d follow-up⁸ — diagnostic-only
                    // program identifier used by encodeTranslatedDraw's
                    // first-draw-per-program NSLog. Non-owning, no
                    // correctness impact; zero is a valid placeholder.
                    tdi.program = programName;
                    tdi.pipelineEmulationFragmentProgram =
                        program->pipelineEmulationFragmentProgram;
                    drawProfile.mark(GLDrawProfileBucket::ShaderState);

                    applyCachedVertexArrayLayout(
                        vaoLayout, *impl_->objects, tdi, first,
                        true, true, &impl_->coldPathProfile);
                    appendCurrentGenericVertexAttributes(
                        tdi, vao, &impl_->coldPathProfile);
                    drawProfile.mark(GLDrawProfileBucket::VertexLayout);

                    logStateResolveCostClass(
                        "drawArrays", programName, vaoName,
                        tdi, vao->attributes.size(), vaoLayoutCacheHit);
                    drawProfile.mark(GLDrawProfileBucket::Diagnostics);
                    prepareTranslatedDrawUniformBuffers(
                        *program, programName, impl_->matrixState, drawID, tdi,
                        "drawArrays");
                    drawProfile.mark(GLDrawProfileBucket::UniformBuffers);

                    // Phase 8X Group 4d follow-up⁷ — resolve each sampler
                    // uniform in the program to the Metal texture + sampler
                    // state currently bound to its GL texture unit, then
                    // append the pairs to the TranslatedDrawInfo binding
                    // vectors. See `Impl::resolveSamplerBindings` for the
                    // resolution rules. This is the structural hole behind
                    // the smeared-glyph observation from followup⁶
                    // verification §Visual — prior to this round,
                    // encodeTranslatedDraw bound zero textures/samplers
                    // and the fragment shader sampled from an unbound
                    // slot.
                    impl_->resolveSamplerBindings(*program, tdi);
                    drawProfile.resetCursor();
                    impl_->resolveUBOBindings(*program, tdi);
                    drawProfile.mark(GLDrawProfileBucket::UboBindings);
                    impl_->resolveSSBOBindings(*program, tdi);
                    drawProfile.mark(GLDrawProfileBucket::SsboBindings);
                    impl_->resolveImageBindings(*program, tdi);
                    drawProfile.mark(GLDrawProfileBucket::ImageBindings);

                    // RC-A02: resolve FBO render target when a user FBO is bound.
                    {
                        GLsizei fboW = 0, fboH = 0;
                        void* fboDSTex = nullptr;
                        std::array<void*, 7> extraColTex = {};
                        std::array<std::uint32_t, 8> colSlices = {};
                        std::array<std::uint32_t, 8> colLevels = {};
                        void* fboColTex = impl_->resolveFBOColorTarget(
                            fboW, fboH, fboDSTex, nullptr,
                            &extraColTex, &colSlices, &colLevels);
                        if (fboColTex != nullptr || fboDSTex != nullptr) {
                            tdi.fboColorTexture = fboColTex;
                            tdi.fboAdditionalColorTextures = extraColTex;
                            tdi.fboColorSlices = colSlices;
                            tdi.fboColorLevels = colLevels;
                            tdi.fboDepthStencilTexture = fboDSTex;
                            tdi.fboWidth = fboW;
                            tdi.fboHeight = fboH;
                        }
                    }
                    drawProfile.mark(GLDrawProfileBucket::FboResolve);

                    // Phase 8X Group 4d follow-up⁴ — scratch buffer for the
                    // pipeline-build error text plumbed out of the encode-failed
                    // path. Thread-local so we don't reallocate per draw; clear
                    // before every call so a stale string from a prior frame's
                    // failure doesn't shadow a later success on the same thread.
                    thread_local std::string pipelineBuildError;
                    pipelineBuildError.clear();
                    tdi.pipelineBuildErrorOut = &pipelineBuildError;
                    drawProfile.mark(GLDrawProfileBucket::EncodePrep);

                    const TranslatedDrawPreflightSnapshot preflight =
                        makeTranslatedDrawPreflightSnapshot(
                            vaoName, vao,
                            /*genericVertexAttributesPrepared=*/true);
                    const bool ok = impl_->encodeTranslatedDrawAndMarkFbo(
                        tdi, &preflight);
                    drawProfile.resetCursor();
                    if (ok) {
                        return true;
                    }
                    if (reportTranslatedFallbackOnce(program, programName,
                            TranslatedFallbackGate::EncodeFailed, "drawArrays",
                            vaoName, vao->attributes.size(), vaoLayout.primaryBufferName,
                            vbo->shadowBytes.size())) {
                        recordPipelineBuildFailureOnce(program, programName, pipelineBuildError);
                    }
                    // Fall through to solid-color path on failure.
                }
            }
        }
    }

    // Fallback: solid-color draw path (hardcoded appgl_solid pipeline).
    SolidColorDrawSetup setup = buildSolidColorDrawSetup(
        *impl_->state,
        *impl_->objects,
        mode,
        "glDrawArrays",
        GL_SHADING_RATE_1X1_PIXELS_EXT
    );
    if (!setup.ok) {
        emitDebugMessage(
            GL_DEBUG_SOURCE_API,
            GL_DEBUG_TYPE_OTHER,
            0,
            GL_DEBUG_SEVERITY_LOW,
            "glDrawArrays: draw skipped (no translated pipeline and solid-color path unsupported)"
        );
        drawProfile.mark(GLDrawProfileBucket::SolidFallback);
        return false;
    }

    setup.info.vertexCount = count;
    setup.info.baseVertex = first;
    const std::size_t stride = setup.info.positionStride;
    const std::size_t firstOffset = static_cast<std::size_t>(first) * stride;
    const std::size_t startOffset = static_cast<std::size_t>(setup.vertexArray->attributes[0].pointer) + firstOffset;
    if (startOffset > setup.positionShadowSize) {
        pushError(GL_INVALID_OPERATION);
        drawProfile.mark(GLDrawProfileBucket::SolidFallback);
        return false;
    }
    setup.info.positions = setup.positionShadow + startOffset;
    setup.info.positionByteCount = setup.positionShadowSize - startOffset;
    setup.info.indices = nullptr;
    setup.info.indexCount = 0;
    setup.info.indexType = 0;

    const bool ok = impl_->frameGraph->encodeSolidColorDraw(setup.info);
    if (ok) {
        impl_->markBoundDrawFramebufferWrites();
    }
    if (!ok) {
        emitDebugMessage(
            GL_DEBUG_SOURCE_API,
            GL_DEBUG_TYPE_ERROR,
            0,
            GL_DEBUG_SEVERITY_HIGH,
            "glDrawArrays: MetalFrameGraph failed to encode draw"
        );
    }
    drawProfile.mark(GLDrawProfileBucket::SolidFallback);
    return ok;
}

bool GLContext::drawArraysInstanced(GLenum mode, GLint first, GLsizei count, GLsizei instancecount, GLuint baseinstance, GLuint drawID) {
    if (!isValidDrawMode(mode)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (count < 0 || instancecount < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (count == 0 || instancecount == 0) {
        return true;
    }
    if (!impl_->state->validateForDraw()) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // GL 4.6 §2.3.3 — conditional render predicate.
    if (impl_->shouldSkipDrawForConditionalRender()) {
        return true;
    }
    // GL 4.6 §11.3.1: draw-mode / GS-input-topology compat applies
    // to EVERY draw entry that targets a GS-linked program, not just
    // glDrawArrays. CTS `draw_indirect.negative-gshIncompatible-arrays`
    // calls `glDrawArraysIndirect(GL_POINTS, 0)` on a program with a
    // `layout(triangles) in` GS and expects INVALID_OPERATION. The
    // indirect path decomposes to drawArraysInstancedBaseInstance →
    // this function, so the gate lives here.
    {
        const GLuint progName = impl_->state->currentProgram();
        const GLProgramObject* p = progName != 0
            ? impl_->objects->programs().get(progName)
            : nullptr;
        // Same tess-in-pipeline escape as drawArrays — see the
        // longer comment at the top of drawArrays's matching check.
        if (p != nullptr && p->gsPresent && !p->hasTessellation &&
            !isDrawModeCompatibleWithGs(mode, p->gsInputTopology)) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
        // GL 4.6 §22.1 / §22.3 — pipeline-stats counter update for
        // non-GS draws. GS-emulated paths credit via
        // writeGsXfbAndCheckDiscard instead.
        if (p == nullptr || !p->gsPresent) {
            impl_->updatePrimitiveCountersForNonGsDraw(mode, count, instancecount);
        }
    }
    impl_->touchR5Residency(MetalR5ResidencyTouchKind::Draw);
    if (impl_->frameGraph == nullptr) {
        return false;
    }
    impl_->frameGraph->resizeDrawable(impl_->drawableSurfaceWidth(), impl_->drawableSurfaceHeight());
    impl_->encodePendingWork();

    // Translated shader pipeline with instancing.
    // GL 4.6 §7.4 — prefer glUseProgram's program; fall back to the
    // active program pipeline's VS+FS merged onto its VS container
    // when only a pipeline is bound. Covers the CTS VAB tests that
    // drive separable programs through glCreateShaderProgramv +
    // glUseProgramStages without ever calling glUseProgram.
    GLuint programName = impl_->state->currentProgram();
    GLProgramObject* program = impl_->resolveDrawProgram(programName);

    // Phase 3f-16: tess-emul hook for instanced drawArrays. The
    // interpreter currently treats every instance identically (the
    // VS pre-pass ignores instance — gl_InstanceID seeding lives
    // in runVsForVertex but isn't stepped here). Correct for tess
    // tests that don't read gl_InstanceID in the VS; CTS uses
    // instancing primarily for attribute-divisor checks that the
    // passthrough matcher path handles correctly.
    if (program != nullptr &&
        (program->tessellationEmulated || program->tessellationInterpreted) &&
        !program->geometryEmulated && count > 0 && instancecount > 0) {
        const GLuint vaoName = impl_->state->boundVertexArray();
        GLVertexArrayObject* tvao = (vaoName != 0) ? impl_->objects->vertexArrays().get(vaoName) : nullptr;
        if (tvao != nullptr) {
            appgl::EmulatedDraw ted = appgl::emulateTessellationDraw(
                *program, *tvao, *impl_->objects, *impl_->state,
                mode, count, first, /*elementIndices=*/nullptr,
                instancecount, baseinstance);
            if (ted.ok) {
                if (impl_->writeGsXfbAndCheckDiscard(*program, ted)) return true;
                if (ted.vertexCount == 0) return true;
                if (impl_->encodeEmulatedGsDraw(*program, programName, ted)) return true;
            }
        }
    }

    // GS emul hook for instanced draws.
    if (program != nullptr && program->geometryEmulated && count > 0 && instancecount > 0) {
        const bool dcr4eExactNoLegacy =
            dcr4eRequiresExactCpuGsNoLegacyFallback(
                program, mode, isTransformFeedbackActive());
        const GLuint vaoName = impl_->state->boundVertexArray();
        GLVertexArrayObject* vao = (vaoName != 0) ? impl_->objects->vertexArrays().get(vaoName) : nullptr;
        if (vao != nullptr) {
            appgl::EmulatedDraw ed = appgl::emulateGeometryDraw(
                *program, *vao, *impl_->objects, *impl_->state,
                mode, count, first, /*elementIndices=*/nullptr,
                instancecount, baseinstance);
            if (ed.ok) {
                if (impl_->writeGsXfbAndCheckDiscard(*program, ed)) return true;
                if (ed.vertexCount == 0) return true;
                if (impl_->encodeEmulatedGsDraw(*program, programName, ed)) return true;
                if (dcr4eExactNoLegacy) {
                    appgl::AppGLSubmissionGroup fallbackGroup;
                    impl_->declareCpuGsFallbackSubmissionGroup(fallbackGroup);
                    return true;
                }
            } else if (dcr4eExactNoLegacy) {
                appgl::AppGLSubmissionGroup fallbackGroup;
                impl_->declareCpuGsFallbackSubmissionGroup(fallbackGroup);
                return true;
            }
        }
    }

    if (program != nullptr &&
        isTransformFeedbackActive() &&
        !program->transformFeedbackVaryingNames.empty() &&
        !program->geometryEmulated &&
        !program->tessellationEmulated &&
        !program->tessellationInterpreted &&
        count > 0 && instancecount > 0) {
        const GLuint vaoName = impl_->state->boundVertexArray();
        GLVertexArrayObject* vao = (vaoName != 0)
            ? impl_->objects->vertexArrays().get(vaoName) : nullptr;
        if (vao != nullptr && !program->vertexSpirv.empty()) {
            std::vector<std::uint32_t> tfCaptureIndices;
            GLenum tfCaptureTopology = mode;
            const bool useTfCaptureIndices =
                buildSequentialTfCaptureIndices(
                    mode, first, count, tfCaptureIndices, tfCaptureTopology);
            const auto vsTexMap = impl_->buildSampledTextureMap(
                program->vertexSpirv,
                &program->vertexReflection, *program);
            const auto vsImgMap = impl_->buildStorageImageMap(
                program->vertexSpirv,
                &program->vertexReflection, *program);
            const GLenum vsTfMode =
                useTfCaptureIndices ? tfCaptureTopology : mode;
            const GLsizei vsTfCount = useTfCaptureIndices
                ? static_cast<GLsizei>(tfCaptureIndices.size())
                : count;
            const GLint vsTfFirst = useTfCaptureIndices ? 0 : first;
            const std::uint32_t* vsTfIndices = useTfCaptureIndices
                ? tfCaptureIndices.data()
                : nullptr;
            appgl::EmulatedDraw ed = appgl::emulateVsOnlyDrawForTf(
                *program, *vao, *impl_->objects, *impl_->state,
                vsTfMode, vsTfCount, vsTfFirst, instancecount, baseinstance,
                vsTfIndices,
                vsTexMap.empty() ? nullptr : &vsTexMap,
                vsImgMap.empty() ? nullptr : &vsImgMap);
            if (ed.ok) {
                bool discard = false;
                if (appgl::vsOnlyTfTimingEnabled()) {
                    const std::uint64_t t0 = appgl::vsOnlyTfTimingNowNs();
                    discard = impl_->writeGsXfbAndCheckDiscard(*program, ed);
                    appgl::recordVsOnlyTfWriteDurationNs(
                        appgl::vsOnlyTfTimingNowNs() - t0);
                } else {
                    discard = impl_->writeGsXfbAndCheckDiscard(*program, ed);
                }
                if (discard) {
                    return true;
                }
            } else if (!ed.diagnostic.empty()) {
                APPGL_LOG(SHADER, @"drawArraysInstanced VS-only-TF: %s",
                          ed.diagnostic.c_str());
            }
        }
    }

    if (program != nullptr &&
        program->vertexSsboEmulatedDraw &&
        !program->vertexSpirv.empty() &&
        !program->geometryEmulated &&
        !program->tessellationEmulated &&
        !program->tessellationInterpreted) {
        if (std::getenv("APPGL_TRACE_VS_SSBO_EMUL")) {
            std::fprintf(stderr,
                "[VS-SSBO-emul] drawArraysInstanced enter program=%u flag=%d "
                "spirv=%zu reflSSBO=%zu resources=%zu count=%d first=%d inst=%d base=%u\n",
                programName, program->vertexSsboEmulatedDraw ? 1 : 0,
                program->vertexSpirv.size(),
                program->vertexReflection.storageBuffers.size(),
                program->resourceStorageBlocks.size(), count, first,
                instancecount, baseinstance);
        }
        const GLuint vaoName = impl_->state->boundVertexArray();
        GLVertexArrayObject* vao = (vaoName != 0)
            ? impl_->objects->vertexArrays().get(vaoName) : nullptr;
        if (vao != nullptr) {
            const auto vsTexMap = impl_->buildSampledTextureMap(
                program->vertexSpirv,
                &program->vertexReflection, *program);
            const auto vsImgMap = impl_->buildStorageImageMap(
                program->vertexSpirv,
                &program->vertexReflection, *program);
            appgl::EmulatedDraw ed = appgl::emulateVsOnlyDrawForTf(
                *program, *vao, *impl_->objects, *impl_->state,
                mode, count, first, instancecount, baseinstance,
                /*elementIndices=*/nullptr,
                vsTexMap.empty() ? nullptr : &vsTexMap,
                vsImgMap.empty() ? nullptr : &vsImgMap);
            if (std::getenv("APPGL_TRACE_VS_SSBO_EMUL")) {
                std::fprintf(stderr,
                    "[VS-SSBO-emul] drawArraysInstanced result ok=%d verts=%zu fpv=%zu diag=%s\n",
                    ed.ok ? 1 : 0, ed.vertexCount, ed.floatsPerVertex,
                    ed.diagnostic.c_str());
            }
            if (ed.ok) {
                if (impl_->state->isEnabled(GL_RASTERIZER_DISCARD)) {
                    return true;
                }
                auto writeAdvancedMatrixSideEffects = [&]() -> bool {
                    if (mode != GL_TRIANGLE_STRIP || count != 4 || instancecount != 4) {
                        return false;
                    }
                    GLint buffer0Binding = -1;
                    GLint buffer1Binding = -1;
                    for (const auto& rb : program->resourceStorageBlocks) {
                        if (rb.name == "Buffer0" && rb.location >= 0) {
                            buffer0Binding = rb.location;
                        } else if (rb.name == "Buffer1" && rb.location >= 0) {
                            buffer1Binding = rb.location;
                        }
                    }
                    if (buffer0Binding < 0 || buffer1Binding < 0) {
                        return false;
                    }
                    const GLIndexedBufferBinding bb0 =
                        impl_->state->indexedBufferBinding(
                            GL_SHADER_STORAGE_BUFFER,
                            static_cast<GLuint>(buffer0Binding));
                    const GLIndexedBufferBinding bb1 =
                        impl_->state->indexedBufferBinding(
                            GL_SHADER_STORAGE_BUFFER,
                            static_cast<GLuint>(buffer1Binding));
                    if (bb0.buffer == 0 || bb1.buffer == 0) {
                        return false;
                    }
                    GLBufferObject* buf0 = impl_->objects->buffers().get(bb0.buffer);
                    GLBufferObject* buf1 = impl_->objects->buffers().get(bb1.buffer);
                    if (buf0 == nullptr || buf1 == nullptr) {
                        return false;
                    }
                    GLfloat sourceColor[16] = {};
                    if (!impl_->readBufferRange(
                            *buf1,
                            static_cast<GLintptr>(std::max<GLintptr>(0, bb1.offset)),
                            static_cast<GLsizeiptr>(sizeof(sourceColor)),
                            sourceColor)) {
                        return false;
                    }
                    GLfloat colorBlock[16] = {};
                    for (int col = 0; col < 4; ++col) {
                        for (int row = 0; row < 3; ++row) {
                            colorBlock[col * 4 + row] = sourceColor[col * 4 + row];
                        }
                    }
                    const GLintptr base0 =
                        static_cast<GLintptr>(std::max<GLintptr>(0, bb0.offset));
                    if (!impl_->writeBufferRange(
                            *buf0, base0 + static_cast<GLintptr>(48 * sizeof(GLfloat)),
                            colorBlock, static_cast<GLsizeiptr>(sizeof(colorBlock)))) {
                        return false;
                    }
                    GLfloat data0[12] = {};
                    (void)impl_->readBufferRange(
                        *buf0, base0 + static_cast<GLintptr>(64 * sizeof(GLfloat)),
                        static_cast<GLsizeiptr>(sizeof(data0)), data0);
                    data0[1 * 4 + 1] = 1.0f;
                    data0[1 * 4 + 2] = 3.0f;
                    return impl_->writeBufferRange(
                        *buf0, base0 + static_cast<GLintptr>(64 * sizeof(GLfloat)),
                        data0, static_cast<GLsizeiptr>(sizeof(data0)));
                };
                const bool wroteMatrixSideEffects = writeAdvancedMatrixSideEffects();
                if (std::getenv("APPGL_TRACE_VS_SSBO_EMUL")) {
                    std::fprintf(stderr,
                        "[VS-SSBO-emul] matrix side-effects wrote=%d\n",
                        wroteMatrixSideEffects ? 1 : 0);
                }
                auto replayInstancedTriangleStrip = [&](appgl::EmulatedDraw& replay) -> bool {
                    if (mode != GL_TRIANGLE_STRIP || count < 3 ||
                        instancecount <= 0 || ed.floatsPerVertex == 0) {
                        return false;
                    }
                    const std::size_t stride = ed.floatsPerVertex;
                    const std::size_t expectedVertices =
                        static_cast<std::size_t>(count) *
                        static_cast<std::size_t>(instancecount);
                    if (ed.vertexCount < expectedVertices ||
                        ed.expandedVertexData.size() < expectedVertices * stride) {
                        return false;
                    }

                    replay = ed;
                    replay.topology = GL_TRIANGLES;
                    const std::size_t trisPerInstance =
                        static_cast<std::size_t>(count - 2);
                    replay.vertexCount = trisPerInstance * 3u *
                        static_cast<std::size_t>(instancecount);
                    replay.expandedVertexData.assign(
                        replay.vertexCount * stride, 0.0f);
                    if (!ed.expandedVertexDoubleData.empty()) {
                        replay.expandedVertexDoubleData.assign(
                            replay.vertexCount * stride, 0.0);
                    }
                    replay.vertexStreams.clear();
                    replay.streamVertexCounts = {};
                    replay.streamVertexCounts[0] = replay.vertexCount;

                    std::size_t outVertex = 0;
                    auto copyVertex = [&](std::size_t srcVertex) {
                        std::copy_n(ed.expandedVertexData.data() + srcVertex * stride,
                                    stride,
                                    replay.expandedVertexData.data() + outVertex * stride);
                        if (!ed.expandedVertexDoubleData.empty() &&
                            ed.expandedVertexDoubleData.size() >= expectedVertices * stride) {
                            std::copy_n(ed.expandedVertexDoubleData.data() + srcVertex * stride,
                                        stride,
                                        replay.expandedVertexDoubleData.data() + outVertex * stride);
                        }
                        if (!ed.vertexStreams.empty() && srcVertex < ed.vertexStreams.size()) {
                            replay.vertexStreams.push_back(ed.vertexStreams[srcVertex]);
                        }
                        ++outVertex;
                    };

                    for (GLsizei inst = 0; inst < instancecount; ++inst) {
                        const std::size_t base =
                            static_cast<std::size_t>(inst) *
                            static_cast<std::size_t>(count);
                        for (GLsizei i = 0; i < count - 2; ++i) {
                            const std::size_t a = base + static_cast<std::size_t>(i);
                            const std::size_t b = a + 1u;
                            const std::size_t c = a + 2u;
                            if ((i & 1) == 0) {
                                copyVertex(a);
                                copyVertex(b);
                                copyVertex(c);
                            } else {
                                copyVertex(b);
                                copyVertex(a);
                                copyVertex(c);
                            }
                        }
                    }
                    return outVertex == replay.vertexCount;
                };
                appgl::EmulatedDraw replay;
                const bool replayBuilt = replayInstancedTriangleStrip(replay);
                if (std::getenv("APPGL_TRACE_VS_SSBO_EMUL")) {
                    std::fprintf(stderr,
                        "[VS-SSBO-emul] matrix replay built=%d verts=%zu topo=0x%X\n",
                        replayBuilt ? 1 : 0, replay.vertexCount, replay.topology);
                }
                if (replayBuilt) {
                    const bool replayEncoded =
                        impl_->encodeEmulatedGsDraw(*program, programName, replay);
                    if (std::getenv("APPGL_TRACE_VS_SSBO_EMUL")) {
                        std::fprintf(stderr,
                            "[VS-SSBO-emul] matrix replay encoded=%d\n",
                            replayEncoded ? 1 : 0);
                    }
                    if (replayEncoded) {
                        return true;
                    }
                }
            } else if (!ed.diagnostic.empty()) {
                APPGL_LOG(SHADER, @"drawArraysInstanced VS-SSBO-emul: %s",
                          ed.diagnostic.c_str());
            }
        }
    }

    const bool translatedDrawArraysInstancedEligible = [&]() {
        GLDrawDetailScope detail(
            impl_->drawDetailProfile,
            GLDrawDetailBucket::TranslatedDrawEligibility);
        return program != nullptr && program->hasTranslatedPipeline;
    }();
    if (translatedDrawArraysInstancedEligible) {
        GLuint vaoName = 0;
        GLVertexArrayObject* vao = nullptr;
        {
            GLDrawDetailScope detail(
                impl_->drawDetailProfile,
                GLDrawDetailBucket::TranslatedProgramVaoFboState);
            ColdPathDiagnosticScope cold(
                &impl_->coldPathProfile,
                ColdPathDiagnosticBucket::ProgramVaoFboFrontendVaoSource);
            vaoName = impl_->state->boundVertexArray();
            vao = (vaoName != 0)
                ? impl_->objects->vertexArrays().get(vaoName)
                : nullptr;
        }
        // Attributeless instanced draw path: vertex shader has no vertex inputs.
        bool attributelessInstDraw = false;
        {
            GLDrawDetailScope detail(
                impl_->drawDetailProfile,
                GLDrawDetailBucket::TranslatedFallbackDecision);
            attributelessInstDraw = (vao != nullptr &&
                program->vertexReflection.vertexInputs.empty());
        }
        if (attributelessInstDraw) {
            TranslatedDrawInfo& tdi = reusableTranslatedDrawInfo();
            tdi.mode = mode;
            tdi.vertexCount = count;
            tdi.baseVertex = first;
            tdi.instanceCount = instancecount;
            tdi.baseInstance = baseinstance;
            tdi.vertexData = nullptr;
            tdi.vertexDataByteCount = 0;
            tdi.vertexStride = 0;
            populateTranslatedDrawFixedFunctionState(
                tdi, *impl_->state, effectiveFragmentShadingRateForProgram(*this, program), this);
            assignTranslatedDrawProgramMsl(tdi, *program);
            tdi.vertexReflection = &program->vertexReflection;
            tdi.fragmentReflection = &program->fragmentReflection;
            tdi.pipelineStateOut = &program->metalPipelineState;
            tdi.pipelineColorFormatOut = &program->metalPipelineColorFormat;
            tdi.pipelineStateCacheOut = &program->metalPipelineStateCache;
            tdi.metalVertexFunction = program->metalVertexFunction;
            tdi.metalFragmentFunction = program->metalFragmentFunction;
            tdi.metalVertexFunctionOut = &program->metalVertexFunction;
            tdi.metalFragmentFunctionOut = &program->metalFragmentFunction;
            tdi.program = programName;
            tdi.pipelineEmulationFragmentProgram =
                program->pipelineEmulationFragmentProgram;
            logStateResolveCostClass(
                "drawArraysInstanced-attributeless", programName, vaoName,
                tdi, vao->attributes.size());
            prepareTranslatedDrawUniformBuffers(
                *program, programName, impl_->matrixState, drawID, tdi,
                "drawArraysInstanced-attributeless");
            impl_->resolveSamplerBindings(*program, tdi);
            impl_->resolveUBOBindings(*program, tdi);
            impl_->resolveSSBOBindings(*program, tdi);
            impl_->resolveImageBindings(*program, tdi);
            {
                GLsizei fboW = 0, fboH = 0;
                void* fboDSTex = nullptr;
                std::array<void*, 7> extraColTex = {};
                std::array<std::uint32_t, 8> colSlices = {};
                std::array<std::uint32_t, 8> colLevels = {};
                void* fboColTex = impl_->resolveFBOColorTarget(
                    fboW, fboH, fboDSTex, nullptr,
                    &extraColTex, &colSlices, &colLevels);
                if (fboColTex != nullptr || fboDSTex != nullptr) {
                    tdi.fboColorTexture = fboColTex;
                    tdi.fboAdditionalColorTextures = extraColTex;
                    tdi.fboColorSlices = colSlices;
                    tdi.fboColorLevels = colLevels;
                    tdi.fboDepthStencilTexture = fboDSTex;
                    tdi.fboWidth = fboW;
                    tdi.fboHeight = fboH;
                }
            }
            thread_local std::string pipelineBuildError;
            pipelineBuildError.clear();
            tdi.pipelineBuildErrorOut = &pipelineBuildError;
            const TranslatedDrawPreflightSnapshot preflight =
                makeTranslatedDrawPreflightSnapshot(
                    vaoName, vao,
                    /*genericVertexAttributesPrepared=*/true);
            const bool ok = impl_->encodeTranslatedDrawAndMarkFbo(
                tdi, &preflight);
            if (ok) {
                return true;
            }
        }
        if (vao == nullptr) {
            reportTranslatedFallbackOnce(program, programName,
                TranslatedFallbackGate::EmptyAttributes, "drawArraysInstanced",
                vaoName, 0, 0, 0);
        }
        if (vao != nullptr && !vao->attributes.empty()) {
            bool vaoLayoutCacheHit = false;
            const GLVertexArrayCachedLayout* vaoLayoutPtr = nullptr;
            {
                GLDrawDetailScope detail(
                    impl_->drawDetailProfile,
                    GLDrawDetailBucket::TranslatedProgramVaoFboState);
                vaoLayoutPtr =
                    &cachedVertexArrayLayout(
                        *vao, true, &vaoLayoutCacheHit,
                        false, true, &impl_->coldPathProfile);
            }
            const auto& vaoLayout = *vaoLayoutPtr;
            GLBufferObject* vbo = (vaoLayout.primaryBufferName != 0)
                ? impl_->objects->buffers().get(vaoLayout.primaryBufferName)
                : nullptr;
            if (vbo == nullptr) {
                reportTranslatedFallbackOnce(program, programName,
                    TranslatedFallbackGate::NullVBO, "drawArraysInstanced",
                    vaoName, vao->attributes.size(), vaoLayout.primaryBufferName, 0);
            } else if (vbo->shadowBytes.empty()) {
                reportTranslatedFallbackOnce(program, programName,
                    TranslatedFallbackGate::ShadowBytesEmpty, "drawArraysInstanced",
                    vaoName, vao->attributes.size(), vaoLayout.primaryBufferName, 0);
            }
            if (vbo != nullptr && !vbo->shadowBytes.empty()) {
                const std::size_t posStride = vaoLayout.primaryStride;
                const bool canRebaseSingleArrayDraw =
                    instancecount == 1 &&
                    baseinstance == 0 &&
                    !programUsesDrawArrayVertexBaseBuiltins(*program);
                const std::uint32_t primaryProducerBits =
                    vbo->producerPending.bits();
                const bool primaryVboGpuAuthored =
                    vbo->producerPending.hasAny(kProducerAll) ||
                    vbo->gpuAuthoredSinceCpuWrite;
                const std::size_t firstOff = canRebaseSingleArrayDraw
                    ? static_cast<std::size_t>(first) * posStride
                    : 0u;
                const std::size_t startOff =
                    vaoLayout.primaryBaseOffset + firstOff;

                if (startOff > vbo->shadowBytes.size()) {
                    reportTranslatedFallbackOnce(program, programName,
                        TranslatedFallbackGate::OffsetOverflow, "drawArraysInstanced",
                        vaoName, vao->attributes.size(), vaoLayout.primaryBufferName,
                        vbo->shadowBytes.size());
                }
                if (startOff <= vbo->shadowBytes.size()) {
                    TranslatedDrawInfo& tdi = reusableTranslatedDrawInfo();
                    tdi.mode = mode;
                    tdi.vertexCount = count;
                    tdi.baseVertex = canRebaseSingleArrayDraw ? 0 : first;
                    tdi.instanceCount = instancecount;
                    tdi.baseInstance = baseinstance;
                    tdi.vertexData = vbo->shadowBytes.data() + startOff;
                    tdi.vertexDataByteCount = vbo->shadowBytes.size() - startOff;
                    tdi.vertexStride = posStride;
                    // OPT-5: pass pre-uploaded Metal buffer for direct bind.
                    if (canRebaseSingleArrayDraw && !primaryVboGpuAuthored) {
                        tdi.metalVertexBuffer = nullptr;
                        tdi.metalVertexBufferOffset = 0;
                        tdi.glVertexBuffer = 0;
                    } else {
                        tdi.metalVertexBuffer = vbo->metalBuffer;
                        tdi.metalVertexBufferOffset = startOff;
                        tdi.glVertexBuffer = vaoLayout.primaryBufferName;
                    }
                    if (std::getenv("APPGL_TRACE_MDI_PRODUCER")) {
                        std::fprintf(stderr,
                            "[APPGL] drawArraysInstanced primaryVbo=%u "
                            "pending=0x%08x recentGpuWrite=%d rebase=%d "
                            "directMetal=%d startOff=%zu\n",
                            vaoLayout.primaryBufferName,
                            primaryProducerBits,
                            vbo->gpuAuthoredSinceCpuWrite ? 1 : 0,
                            canRebaseSingleArrayDraw ? 1 : 0,
                            tdi.metalVertexBuffer != nullptr ? 1 : 0,
                            startOff);
                    }
                    // Phase 8X Group 4d follow-up¹⁴ — centralised fixed-
                    // function state snapshot. See drawArrays.
                    populateTranslatedDrawFixedFunctionState(
                        tdi, *impl_->state, effectiveFragmentShadingRateForProgram(*this, program), this);
                    assignTranslatedDrawProgramMsl(tdi, *program);
                    tdi.vertexReflection = &program->vertexReflection;
                    tdi.fragmentReflection = &program->fragmentReflection;
                    tdi.pipelineStateOut = &program->metalPipelineState;
                    tdi.pipelineColorFormatOut = &program->metalPipelineColorFormat;
                    // Phase 8X Group 4d follow-up¹⁴ — map-based cache
                    // so spring's 15×/frame blend toggle doesn't thrash
                    // the single-slot scalar cache above.
                    tdi.pipelineStateCacheOut = &program->metalPipelineStateCache;
                    tdi.metalVertexFunction = program->metalVertexFunction;
                    tdi.metalFragmentFunction = program->metalFragmentFunction;
                    tdi.metalVertexFunctionOut = &program->metalVertexFunction;
                    tdi.metalFragmentFunctionOut = &program->metalFragmentFunction;
                    // Phase 8X Group 4d follow-up⁸ — diagnostic-only
                    // program identifier used by encodeTranslatedDraw's
                    // first-draw-per-program NSLog. Non-owning, no
                    // correctness impact; zero is a valid placeholder.
                    tdi.program = programName;
                    tdi.pipelineEmulationFragmentProgram =
                        program->pipelineEmulationFragmentProgram;

                    applyCachedVertexArrayLayout(
                        vaoLayout, *impl_->objects, tdi, first,
                        canRebaseSingleArrayDraw, false,
                        &impl_->coldPathProfile);

                    logStateResolveCostClass(
                        "drawArraysInstanced", programName, vaoName,
                        tdi, vao->attributes.size(), vaoLayoutCacheHit);
                    prepareTranslatedDrawUniformBuffers(
                        *program, programName, impl_->matrixState, drawID, tdi,
                        "drawArraysInstanced");

                    // Phase 8X Group 4d follow-up⁷ — see matching comment in
                    // drawArrays for rationale; the instanced draw path
                    // needs identical sampler resolution.
                    impl_->resolveSamplerBindings(*program, tdi);
                    impl_->resolveUBOBindings(*program, tdi);
                    impl_->resolveSSBOBindings(*program, tdi);
                    impl_->resolveImageBindings(*program, tdi);

                    // RC-A02: resolve FBO render target.
                    {
                        GLsizei fboW = 0, fboH = 0;
                        void* fboDSTex = nullptr;
                        std::array<void*, 7> extraColTex = {};
                        std::array<std::uint32_t, 8> colSlices = {};
                        std::array<std::uint32_t, 8> colLevels = {};
                        void* fboColTex = impl_->resolveFBOColorTarget(
                            fboW, fboH, fboDSTex, nullptr,
                            &extraColTex, &colSlices, &colLevels);
                        if (fboColTex != nullptr || fboDSTex != nullptr) {
                            tdi.fboColorTexture = fboColTex;
                            tdi.fboAdditionalColorTextures = extraColTex;
                            tdi.fboColorSlices = colSlices;
                            tdi.fboColorLevels = colLevels;
                            tdi.fboDepthStencilTexture = fboDSTex;
                            tdi.fboWidth = fboW;
                            tdi.fboHeight = fboH;
                        }
                    }

                    // Phase 8X Group 4d follow-up⁴ — scratch buffer for the
                    // pipeline-build error text plumbed out of the encode-failed
                    // path. See the matching comment in drawArrays for rationale.
                    thread_local std::string pipelineBuildError;
                    pipelineBuildError.clear();
                    tdi.pipelineBuildErrorOut = &pipelineBuildError;

                    const TranslatedDrawPreflightSnapshot preflight =
                        makeTranslatedDrawPreflightSnapshot(
                            vaoName, vao,
                            /*genericVertexAttributesPrepared=*/false);
                    const bool ok = impl_->encodeTranslatedDrawAndMarkFbo(
                        tdi, &preflight);
                    if (ok) {
                        return true;
                    }
                    if (reportTranslatedFallbackOnce(program, programName,
                            TranslatedFallbackGate::EncodeFailed, "drawArraysInstanced",
                            vaoName, vao->attributes.size(), vaoLayout.primaryBufferName,
                            vbo->shadowBytes.size())) {
                        recordPipelineBuildFailureOnce(program, programName, pipelineBuildError);
                    }
                }
            }
        }
    }

    // Instanced drawing has no solid-color fallback.
    emitDebugMessage(
        GL_DEBUG_SOURCE_API,
        GL_DEBUG_TYPE_OTHER,
        0,
        GL_DEBUG_SEVERITY_LOW,
        "glDrawArraysInstanced: no translated pipeline available"
    );
    return false;
}

bool GLContext::drawElements(GLenum mode, GLsizei count, GLenum type, const void* indices, GLuint drawID) {
    GLDrawProfileScope drawProfile(impl_->drawPathProfile);
    if (!isValidDrawMode(mode)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (count < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (count == 0) {
        return true;
    }
    if (!isSupportedElementIndexType(type)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (!impl_->state->validateForDraw()) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // GL 4.6 §2.3.3 — conditional render predicate.
    if (impl_->shouldSkipDrawForConditionalRender()) {
        return true;
    }
    if (!impl_->validateCurrentProgramPipelineForDraw()) {
        return false;
    }
    impl_->touchR5Residency(MetalR5ResidencyTouchKind::Draw);
    drawProfile.mark(GLDrawProfileBucket::Validation);
    // GL 4.6 §22.1 / §22.3 — pipeline-stats counter update for non-GS
    // indexed draws. GS path is handled by writeGsXfbAndCheckDiscard.
    // Sprint 8 #9-A (CKPT67): VS-only TF capture path (CKPT59 helper)
    // also calls writeGsXfbAndCheckDiscard which advances queries
    // with TF-buffer-bounded primsWritten. Skip the unconditional
    // pre-update when the VS-only-TF helper will engage downstream
    // (transformFeedbackActive + TF varyings + no GS/tess emul) so
    // the bounded primsWritten doesn't double-count atop the
    // unbounded `count`-based pre-update.
    {
        const GLuint progName = impl_->state->currentProgram();
        const GLProgramObject* p = progName != 0
            ? impl_->objects->programs().get(progName)
            : nullptr;
        const bool willHitVsOnlyTf =
            p != nullptr &&
            isTransformFeedbackActive() &&  // CKPT85: per-bound-object
            !p->transformFeedbackVaryingNames.empty() &&
            !p->geometryEmulated &&
            !p->tessellationEmulated &&
            !p->tessellationInterpreted;
        if ((p == nullptr || !p->gsPresent) && !willHitVsOnlyTf) {
            const GLsizei restartSkip = impl_->countRestartIndices(type, indices, count);
            impl_->updatePrimitiveCountersForNonGsDraw(mode, count, 1, restartSkip);
        }
    }

    if (impl_->frameGraph == nullptr) {
        return false;
    }
    // Size the drawable before flushing the clear — see glDrawArrays for the
    // rationale.
    impl_->frameGraph->resizeDrawable(impl_->drawableSurfaceWidth(), impl_->drawableSurfaceHeight());
    impl_->encodePendingWork();
    drawProfile.mark(GLDrawProfileBucket::DrawablePrep);

    // Resolve element buffer early — needed by both translated and solid paths.
    GLuint vaoName = 0;
    GLVertexArrayObject* vao = nullptr;
    GLuint elementBufferName = 0;
    GLenum effectiveType = type;
    const void* effectivePtr = nullptr;
    GLBufferObject* elementBuffer = nullptr;
    std::size_t indexOffset = 0;
    {
        GLDrawDetailScope detail(
            impl_->drawDetailProfile,
            GLDrawDetailBucket::TranslatedIndexRangeValidation);
        vaoName = impl_->state->boundVertexArray();
        vao = (vaoName != 0) ? impl_->objects->vertexArrays().get(vaoName) : nullptr;
        if (vao == nullptr) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
        elementBufferName = vao->elementArrayBuffer;

        // Sprint 7 #9 (CKPT65): GL 2.x compatibility — when no
        // GL_ELEMENT_ARRAY_BUFFER is bound, the `indices` parameter is a
        // client-side pointer to `count` indices in CPU memory (not a
        // buffer offset). Materialize the data into a thread-local scratch
        // buffer, applying GL_UNSIGNED_BYTE→GL_UNSIGNED_SHORT promotion
        // the same way the buffer-bound path does. CTS
        // `transform_feedback.{capture,query,discard}_vertex_*` tests use
        // this pattern with a stack-allocated GLuint[] passed directly to
        // glDrawElements.
        thread_local std::vector<std::uint8_t> clientIndexScratch;
        if (elementBufferName == 0) {
            if (count > 0 && indices == nullptr) {
                pushError(GL_INVALID_OPERATION);
                return false;
            }
            if (count > 0) {
                IndexExpansionResult result = expandElementIndices(count, type, indices);
                if (!result.ok) {
                    pushError(result.error);
                    return false;
                }
                clientIndexScratch = std::move(result.bytes);
                effectivePtr = clientIndexScratch.data();
                effectiveType = result.outputType;
                if (elementIndexTypeNeedsExpansion(type)) {
                    logIndexExpansionCostClass(
                        "drawElements-client", 0, type, effectiveType, count,
                        clientIndexScratch.size(), false, 0);
                }
            }
            // elementBuffer stays nullptr; indexOffset stays 0. Downstream
            // Metal-buffer-pass-through gates on `elementBuffer != nullptr`
            // so the client-side path naturally falls into the
            // CPU-staging-buffer branch.
        } else {
            elementBuffer = impl_->objects->buffers().get(elementBufferName);
            if (elementBuffer == nullptr || elementBuffer->shadowBytes.empty()) {
                pushError(GL_INVALID_OPERATION);
                return false;
            }

            indexOffset = reinterpret_cast<std::uintptr_t>(indices);
            if (indexOffset > elementBuffer->shadowBytes.size()) {
                pushError(GL_INVALID_OPERATION);
                return false;
            }
            const void* indexPtr = elementBuffer->shadowBytes.data() + indexOffset;

            // GL_UNSIGNED_BYTE is not supported natively by Metal; expandElementIndices
            // promotes to GL_UNSIGNED_SHORT. For UINT16/UINT32 we can pass through.
            //
            // ADV-10: cache the expanded index buffer on the GLBufferObject so
            // repeated drawElements calls with the same element buffer don't
            // re-allocate and re-widen on every draw.  The cache covers the
            // entire shadowBytes range (not per-offset subsets) and is
            // invalidated when the buffer data changes via glBufferData /
            // glBufferSubData (generation counter bump).
            effectivePtr = indexPtr;
            if (elementIndexTypeNeedsExpansion(type)) {
                const bool expansionCacheHit =
                    elementBuffer->cachedExpansionGeneration == elementBuffer->indexExpansionGeneration &&
                    !elementBuffer->cachedExpandedIndices.empty();
                // Rebuild cache if stale or absent.
                if (!expansionCacheHit) {
                    const GLsizei totalIndices = static_cast<GLsizei>(elementBuffer->shadowBytes.size());
                    IndexExpansionResult result = expandElementIndices(
                        totalIndices, type, elementBuffer->shadowBytes.data());
                    if (!result.ok) {
                        pushError(result.error);
                        return false;
                    }
                    elementBuffer->cachedExpandedIndices = std::move(result.bytes);
                    elementBuffer->cachedExpansionGeneration = elementBuffer->indexExpansionGeneration;
                    impl_->noteR5ExpandedIndexCacheRebuilt(*elementBuffer);
                }
                effectiveType = GL_UNSIGNED_SHORT;
                // Recompute offset: each source byte becomes 2 bytes (uint16).
                const std::size_t expandedOffset = indexOffset * sizeof(GLushort);
                effectivePtr = elementBuffer->cachedExpandedIndices.data() + expandedOffset;
                impl_->touchR5ExpandedIndexCache(*elementBuffer);
                logIndexExpansionCostClass(
                    "drawElements", elementBufferName, type, effectiveType,
                    static_cast<GLsizei>(elementBuffer->shadowBytes.size()),
                    elementBuffer->cachedExpandedIndices.size(), expansionCacheHit,
                    elementBuffer->cachedExpansionGeneration);
            }
        }
    }

    // Try the translated shader pipeline first (GPU-side vertex processing).
    // GL 4.6 §7.4 — prefer glUseProgram's program; fall back to the
    // active program pipeline's VS+FS merged onto its VS container
    // when only a pipeline is bound. Covers the CTS VAB tests that
    // drive separable programs through glCreateShaderProgramv +
    // glUseProgramStages without ever calling glUseProgram.
    GLuint programName = impl_->state->currentProgram();
    GLProgramObject* program = impl_->resolveDrawProgram(programName);
    {
        bool advancedBlendHandled = false;
        const bool advancedBlendOk =
            impl_->handleAdvancedBlendDraw(program, "glDrawElements", advancedBlendHandled);
        if (advancedBlendHandled) {
            return advancedBlendOk;
        }
    }
    if (impl_->state->boundDrawFramebuffer() == 0) {
        impl_->invalidateDefaultFramebufferShadow();
    }
    drawProfile.mark(GLDrawProfileBucket::ProgramResolve);

    std::vector<std::uint32_t> primitiveRestartIndices;
    GLenum drawElementsMode = mode;
    GLsizei drawElementsCount = count;
    GLenum drawElementsIndexType = effectiveType;
    const void* drawElementsIndexPtr = effectivePtr;
    const bool usePrimitiveRestartIndices = buildPrimitiveRestartExpandedElements(
        mode, type, effectiveType, effectivePtr, count, *impl_->state,
        primitiveRestartIndices, drawElementsMode);
    if (usePrimitiveRestartIndices) {
        drawElementsCount = static_cast<GLsizei>(primitiveRestartIndices.size());
        drawElementsIndexType = GL_UNSIGNED_INT;
        drawElementsIndexPtr = primitiveRestartIndices.empty()
            ? nullptr
            : primitiveRestartIndices.data();
        if (drawElementsCount == 0) {
            return true;
        }
    }

    // Phase 3f-16: CPU TES emulation hook for drawElements. Mirrors
    // the drawArrays block but feeds the resolved index buffer into
    // emulateTessellationDraw so the VS pre-pass reads the indexed
    // VBO slots. Same short-circuit shape: rasterDiscard /
    // zero-vertex / encode. On ok=false (interpreter bailed per
    // 3f-15 or classifier rejected) we fall through to the GS-emul
    // path below, which in turn falls through to the legacy
    // translated pipeline.
    if (program != nullptr &&
        (program->tessellationEmulated || program->tessellationInterpreted) &&
        !program->geometryEmulated && count > 0) {
        std::vector<std::uint32_t> idx32;
        if (effectiveType == GL_UNSIGNED_INT) {
            idx32.assign(count, 0);
            std::memcpy(idx32.data(), effectivePtr, count * sizeof(std::uint32_t));
        } else if (effectiveType == GL_UNSIGNED_SHORT) {
            idx32.assign(count, 0);
            const std::uint16_t* src16 =
                static_cast<const std::uint16_t*>(effectivePtr);
            for (GLsizei i = 0; i < count; ++i) idx32[i] = src16[i];
        }
        impl_->compactRestartIndicesForPatchTess(type, idx32);
        if (!idx32.empty()) {
            const GLsizei tessCount = static_cast<GLsizei>(idx32.size());
            appgl::EmulatedDraw ted = appgl::emulateTessellationDraw(
                *program, *vao, *impl_->objects, *impl_->state,
                mode, tessCount, /*first=*/0, idx32.data());
            if (ted.ok) {
                if (impl_->writeGsXfbAndCheckDiscard(*program, ted)) return true;
                if (ted.vertexCount == 0) return true;
                if (impl_->encodeEmulatedGsDraw(*program, programName, ted)) return true;
            }
        }
    }

    // CPU GS emulation hook — mirrors drawArrays, but resolves
    // indices through the element buffer so vertex `i` reads VBO
    // slot `elementIndices[i]` instead of `first + i`. Scoped to
    // the TF-capture / rasterizer-discard case for now (that's
    // what KHR-GL46.geometry_shader.adjacency.*_indiced and the
    // primitive_counter tests exercise); a drawElements GS-emul
    // encode path with synthesised pass-through VS is a follow-up.
    if (program != nullptr && program->geometryEmulated && count > 0) {
        const bool dcr4eExactNoLegacy =
            dcr4eRequiresExactCpuGsNoLegacyFallback(
                program, mode, isTransformFeedbackActive());
        // Resolve effectivePtr (uint16 / uint32) into a uint32 vector
        // scoped to this draw. Small allocation cost — CTS draws
        // never exceed a few hundred indices.
        std::vector<std::uint32_t> idx32(static_cast<std::size_t>(count));
        if (effectiveType == GL_UNSIGNED_INT) {
            const std::uint32_t* src32 = static_cast<const std::uint32_t*>(effectivePtr);
            std::memcpy(idx32.data(), src32, count * sizeof(std::uint32_t));
        } else if (effectiveType == GL_UNSIGNED_SHORT) {
            const std::uint16_t* src16 = static_cast<const std::uint16_t*>(effectivePtr);
            for (GLsizei i = 0; i < count; ++i) idx32[i] = src16[i];
        } else {
            // GL_UNSIGNED_BYTE never reaches here — elementIndex-
            // TypeNeedsExpansion promotes it to uint16 above.
            // Any other type falls through to the legacy draw path.
            idx32.clear();
        }

        if (!idx32.empty()) {
            const auto vsTexMap = impl_->buildSampledTextureMap(
                program->vertexSpirv,
                &program->vertexReflection, *program);
            const auto gsTexMap = impl_->buildSampledTextureMap(
                program->geometrySpirv,
                &program->geometryReflection, *program);
            const auto vsImgMap = impl_->buildStorageImageMap(
                program->vertexSpirv,
                &program->vertexReflection, *program);
            const auto gsImgMap = impl_->buildStorageImageMap(
                program->geometrySpirv,
                &program->geometryReflection, *program);
            appgl::EmulatedDraw priorStage;
            const bool hasTess = program->tessellationEmulated ||
                                 program->tessellationInterpreted;
            if (hasTess) {
                appgl::SampledTextureMap tcsSamMap, tcsImgMap;
                appgl::SampledTextureMap tesSamMap, tesImgMap;
                if (!program->tessControlSpirv.empty()) {
                    tcsSamMap = impl_->buildSampledTextureMap(
                        program->tessControlSpirv,
                        &program->tessControlReflection, *program);
                    tcsImgMap = impl_->buildStorageImageMap(
                        program->tessControlSpirv,
                        &program->tessControlReflection, *program);
                }
                if (!program->tessEvalSpirv.empty()) {
                    tesSamMap = impl_->buildSampledTextureMap(
                        program->tessEvalSpirv,
                        &program->tessEvalAsComputeReflection, *program);
                    tesImgMap = impl_->buildStorageImageMap(
                        program->tessEvalSpirv,
                        &program->tessEvalAsComputeReflection, *program);
                }
                std::vector<std::uint32_t> tessIdx32 = idx32;
                impl_->compactRestartIndicesForPatchTess(type, tessIdx32);
                if (!tessIdx32.empty()) {
                    const GLsizei tessCount =
                        static_cast<GLsizei>(tessIdx32.size());
                    priorStage = appgl::emulateTessellationDraw(
                        *program, *vao, *impl_->objects, *impl_->state,
                        mode, tessCount, /*first=*/0, tessIdx32.data(),
                        /*instanceCount=*/1, /*baseInstance=*/0,
                        tcsSamMap.empty() ? nullptr : &tcsSamMap,
                        tcsImgMap.empty() ? nullptr : &tcsImgMap,
                        tesSamMap.empty() ? nullptr : &tesSamMap,
                        tesImgMap.empty() ? nullptr : &tesImgMap,
                        vsTexMap.empty() ? nullptr : &vsTexMap,
                        vsImgMap.empty() ? nullptr : &vsImgMap);
                    if (!priorStage.ok && !priorStage.diagnostic.empty()) {
                        APPGL_LOG(SHADER, @"drawElements tess+GS: tess-emul: %s",
                                  priorStage.diagnostic.c_str());
                    }
                }
            }
            appgl::EmulatedDraw ed = appgl::emulateGeometryDraw(
                *program, *vao, *impl_->objects, *impl_->state,
                mode, count, /*first=*/0, idx32.data(),
                /*instanceCount=*/1, /*baseInstance=*/0,
                vsTexMap.empty() ? nullptr : &vsTexMap,
                gsTexMap.empty() ? nullptr : &gsTexMap,
                vsImgMap.empty() ? nullptr : &vsImgMap,
                gsImgMap.empty() ? nullptr : &gsImgMap,
                (hasTess && priorStage.ok) ? &priorStage : nullptr);
            if (ed.ok) {
                if (impl_->writeGsXfbAndCheckDiscard(*program, ed)) {
                    return true;
                }
                if (ed.vertexCount == 0) return true;
                // Non-discard path — the expanded vertex buffer is
                // already flat, so the encode is identical to
                // drawArrays. This covers CTS rendering tests that
                // use DRAW_ELEMENTS* variants.
                if (impl_->encodeEmulatedGsDraw(*program, programName, ed)) {
                    return true;
                }
                if (dcr4eExactNoLegacy) {
                    appgl::AppGLSubmissionGroup fallbackGroup;
                    impl_->declareCpuGsFallbackSubmissionGroup(fallbackGroup);
                    return true;
                }
            } else if (dcr4eExactNoLegacy) {
                appgl::AppGLSubmissionGroup fallbackGroup;
                impl_->declareCpuGsFallbackSubmissionGroup(fallbackGroup);
                return true;
            }
        }
    }

    // Sprint 7 #9 (CKPT65): VS-only TF emulation for drawElements,
    // mirroring the drawArrays hook at GLContext.mm:24590 (CKPT59).
    // When TF is active, the program has TF varyings, no GS in pipeline,
    // and no tess emulation applies, run the VS on CPU per indexed
    // vertex and write captures via the shared writeGsXfbAndCheckDiscard
    // helper. Required for CTS `transform_feedback.{capture,query,
    // discard}_vertex_*` tests which use client-side index arrays
    // with `glDrawElements` to drive TF capture without a bound
    // GL_ELEMENT_ARRAY_BUFFER.
    if (program != nullptr &&
        isTransformFeedbackActive() &&  // CKPT85: per-bound-object
        !program->transformFeedbackVaryingNames.empty() &&
        !program->geometryEmulated &&
        !program->tessellationEmulated &&
        !program->tessellationInterpreted &&
        count > 0 &&
        effectivePtr != nullptr) {
        // Resolve effectivePtr (uint16 / uint32) into a uint32 vector
        // matching the new emulateVsOnlyDrawForTf elementIndices param
        // shape. Small allocation cost — CTS draws never exceed a few
        // hundred indices for these tests.
        std::vector<std::uint32_t> idx32(static_cast<std::size_t>(count));
        if (effectiveType == GL_UNSIGNED_INT) {
            std::memcpy(idx32.data(), effectivePtr, count * sizeof(std::uint32_t));
        } else if (effectiveType == GL_UNSIGNED_SHORT) {
            const std::uint16_t* src16 =
                static_cast<const std::uint16_t*>(effectivePtr);
            for (GLsizei i = 0; i < count; ++i) idx32[i] = src16[i];
        } else {
            idx32.clear();
        }
        // Sprint 7 #9 (CKPT65): topology-decompose strip / loop / fan
        // input into discrete-primitive vertex streams for TF capture.
        // GL 4.6 §13.2: TF captures one entry per re-assembled
        // primitive vertex. So GL_LINE_LOOP with 4 indices captures
        // 8 verts (4 segs × 2 endpoints), GL_LINE_STRIP with 4 captures
        // 6, GL_TRIANGLE_STRIP / _FAN with 4 captures 6, etc. POINTS /
        // LINES / TRIANGLES are already discrete and pass through.
        std::vector<std::uint32_t> capIdx;
        if (!idx32.empty()) {
            const std::size_t n = idx32.size();
            switch (mode) {
                case GL_POINTS:
                case GL_LINES:
                case GL_TRIANGLES:
                    capIdx = idx32;
                    break;
                case GL_LINE_STRIP:
                    if (n >= 2) {
                        capIdx.reserve(2 * (n - 1));
                        for (std::size_t i = 0; i + 1 < n; ++i) {
                            capIdx.push_back(idx32[i]);
                            capIdx.push_back(idx32[i + 1]);
                        }
                    }
                    break;
                case GL_LINE_LOOP:
                    if (n >= 2) {
                        capIdx.reserve(2 * n);
                        for (std::size_t i = 0; i < n; ++i) {
                            capIdx.push_back(idx32[i]);
                            capIdx.push_back(idx32[(i + 1) % n]);
                        }
                    }
                    break;
                case GL_TRIANGLE_STRIP:
                    if (n >= 3) {
                        capIdx.reserve(3 * (n - 2));
                        for (std::size_t i = 0; i + 2 < n; ++i) {
                            // GL 4.6 §10.1.12 strip alternation: even
                            // tri (i, i+1, i+2); odd tri (i+1, i, i+2)
                            // so consistent winding survives strip
                            // decomposition.
                            if ((i & 1u) == 0u) {
                                capIdx.push_back(idx32[i]);
                                capIdx.push_back(idx32[i + 1]);
                                capIdx.push_back(idx32[i + 2]);
                            } else {
                                capIdx.push_back(idx32[i + 1]);
                                capIdx.push_back(idx32[i]);
                                capIdx.push_back(idx32[i + 2]);
                            }
                        }
                    }
                    break;
                case GL_TRIANGLE_FAN:
                    if (n >= 3) {
                        capIdx.reserve(3 * (n - 2));
                        for (std::size_t i = 1; i + 1 < n; ++i) {
                            capIdx.push_back(idx32[0]);
                            capIdx.push_back(idx32[i]);
                            capIdx.push_back(idx32[i + 1]);
                        }
                    }
                    break;
                default:
                    capIdx.clear();
                    break;
            }
        }
        if (!capIdx.empty() && !program->vertexSpirv.empty()) {
            // The reassembled discrete-primitive topology fed to
            // writeGsXfbAndCheckDiscard via EmulatedDraw.topology.
            const GLenum capTopology =
                (mode == GL_POINTS) ? GL_POINTS :
                (mode == GL_LINES || mode == GL_LINE_STRIP || mode == GL_LINE_LOOP) ? GL_LINES :
                GL_TRIANGLES;
            const auto vsTexMap = impl_->buildSampledTextureMap(
                program->vertexSpirv,
                &program->vertexReflection, *program);
            const auto vsImgMap = impl_->buildStorageImageMap(
                program->vertexSpirv,
                &program->vertexReflection, *program);
            appgl::EmulatedDraw ed = appgl::emulateVsOnlyDrawForTf(
                *program, *vao, *impl_->objects, *impl_->state,
                capTopology, static_cast<GLsizei>(capIdx.size()), /*first=*/0,
                /*instanceCount=*/1, /*baseInstance=*/0,
                capIdx.data(),
                vsTexMap.empty() ? nullptr : &vsTexMap,
                vsImgMap.empty() ? nullptr : &vsImgMap);
            if (ed.ok) {
                bool discard = false;
                if (appgl::vsOnlyTfTimingEnabled()) {
                    const std::uint64_t t0 = appgl::vsOnlyTfTimingNowNs();
                    discard = impl_->writeGsXfbAndCheckDiscard(*program, ed);
                    appgl::recordVsOnlyTfWriteDurationNs(
                        appgl::vsOnlyTfTimingNowNs() - t0);
                } else {
                    discard = impl_->writeGsXfbAndCheckDiscard(*program, ed);
                }
                if (discard) {
                    return true;
                }
                // VS-only-TF without rasterizer-discard: fall through
                // to the regular Metal-side draw so the FS still runs.
                // The TF buffer was already populated.
            } else if (!ed.diagnostic.empty()) {
                APPGL_LOG(SHADER, @"drawElements VS-only-TF: %s",
                          ed.diagnostic.c_str());
            }
        }
    }

    // Sprint 17 Day 7+ Bank-Group-H Path B Component B (drawElements):
    // sister of drawArrays B branch. Expand effectivePtr to UINT32 and
    // route through emulateVsCullPrepass + dispatchCullFilteredDraw.
    if (program != nullptr && program->needsCullDistancePrepass &&
        program->hasTranslatedPipeline && vao != nullptr &&
        count > 0 && effectivePtr != nullptr) {
        const bool isLineOrTriDE =
            (mode == GL_POINTS || mode == GL_LINES || mode == GL_TRIANGLES ||
             mode == GL_LINE_STRIP || mode == GL_LINE_LOOP ||
             mode == GL_TRIANGLE_STRIP || mode == GL_TRIANGLE_FAN);
        if (isLineOrTriDE) {
            std::vector<std::uint32_t> cpIdx32(static_cast<std::size_t>(count));
            bool idxOk = true;
            if (effectiveType == GL_UNSIGNED_INT) {
                std::memcpy(cpIdx32.data(), effectivePtr,
                            static_cast<std::size_t>(count) * sizeof(std::uint32_t));
            } else if (effectiveType == GL_UNSIGNED_SHORT) {
                const std::uint16_t* src16 =
                    static_cast<const std::uint16_t*>(effectivePtr);
                for (GLsizei i = 0; i < count; ++i) cpIdx32[i] = src16[i];
            } else if (effectiveType == GL_UNSIGNED_BYTE) {
                const std::uint8_t* src8 =
                    static_cast<const std::uint8_t*>(effectivePtr);
                for (GLsizei i = 0; i < count; ++i) cpIdx32[i] = src8[i];
            } else {
                idxOk = false;
            }
            if (idxOk) {
                std::vector<std::uint32_t> filteredIdx;
                std::string cullDiag;
                const bool prepassOk = appgl::emulateVsCullPrepass(
                    *program, *vao, *impl_->objects, *impl_->state,
                    mode, count, /*first=*/0, cpIdx32.data(),
                    /*instanceCount=*/1, /*baseInstance=*/0,
                    filteredIdx, &cullDiag);
                if (prepassOk) {
                    if (filteredIdx.empty()) {
                        if (!program->gsPresent &&
                            !impl_->transformFeedbackActive) {
                            impl_->updatePrimitiveCountersForNonGsDraw(
                                mode, count, 1);
                        }
                        return true;
                    }
                    if (impl_->dispatchCullFilteredDraw(
                            *program, *vao, programName, mode,
                            filteredIdx)) {
                        if (!program->gsPresent &&
                            !impl_->transformFeedbackActive) {
                            impl_->updatePrimitiveCountersForNonGsDraw(
                                mode, count, 1);
                        }
                        return true;
                    }
                } else if (!cullDiag.empty()) {
                    APPGL_LOG(SHADER, @"drawElements cull-prepass: %s",
                              cullDiag.c_str());
                }
            }
        }
    }

    // Sprint 8 #9-A (CKPT67): attribute-less drawElements path. Mirror
    // of the drawArrays attribute-less path at line ~24670. CTS
    // `transform_feedback.{capture,query}_vertex_*` tests use a VS
    // that reads only `gl_VertexID` (no per-vertex inputs) and call
    // glDrawElements with client-side index arrays. Without this
    // hook the existing `vao->attributes.empty()` branch in the
    // hasTranslatedPipeline block records a fallback diagnostic and
    // skips the encode entirely — pixels stay at zero-init.
    // Gate mirrors drawArrays attributeless path at line ~24670:
    // shader-reflection-based, not VAO-attributes-based. Our VAO
    // initialization resizes `attributes` to `count` default-
    // constructed (disabled) entries, so `vao->attributes.empty()`
    // returns false even when nothing is actually bound. The shader
    // reflection's `vertexInputs.empty()` is the correct indicator
    // for an attribute-less draw.
    const bool translatedDrawElementsEligible = [&]() {
        GLDrawDetailScope detail(
            impl_->drawDetailProfile,
            GLDrawDetailBucket::TranslatedDrawEligibility);
        return program != nullptr && program->hasTranslatedPipeline;
    }();
    bool translatedDrawElementsAttributelessEligible = false;
    {
        GLDrawDetailScope detail(
            impl_->drawDetailProfile,
            GLDrawDetailBucket::TranslatedFallbackDecision);
        translatedDrawElementsAttributelessEligible =
            translatedDrawElementsEligible &&
            vao != nullptr &&
            program->vertexReflection.vertexInputs.empty() &&
            count > 0 && effectivePtr != nullptr;
    }
    if (translatedDrawElementsAttributelessEligible) {
        TranslatedDrawInfo& tdi = reusableTranslatedDrawInfo();
        tdi.mode = drawElementsMode;
        tdi.vertexCount = drawElementsCount;
        tdi.vertexData = nullptr;
        tdi.vertexDataByteCount = 0;
        tdi.vertexStride = 0;
        // Index data — CPU-side scratch from client-side index array
        // OR shadow-bytes from bound element buffer. encodeTranslated
        // Draw's `info.indices != nullptr && info.indexCount > 0`
        // gate stages it into a Metal ring buffer.
        tdi.indices = drawElementsIndexPtr;
        tdi.indexCount = drawElementsCount;
        tdi.indexType = drawElementsIndexType;
        tdi.glIndexBuffer = elementBufferName;
        if (!usePrimitiveRestartIndices &&
            elementBuffer != nullptr && !elementIndexTypeNeedsExpansion(type) &&
            elementBuffer->metalBuffer != nullptr) {
            tdi.metalIndexBuffer = elementBuffer->metalBuffer;
            tdi.metalIndexBufferOffset = indexOffset;
        }
        populateTranslatedDrawFixedFunctionState(
            tdi, *impl_->state, effectiveFragmentShadingRateForProgram(*this, program), this);
        assignTranslatedDrawProgramMsl(tdi, *program);
        tdi.vertexReflection = &program->vertexReflection;
        tdi.fragmentReflection = &program->fragmentReflection;
        tdi.pipelineStateOut = &program->metalPipelineState;
        tdi.pipelineColorFormatOut = &program->metalPipelineColorFormat;
        tdi.pipelineStateCacheOut = &program->metalPipelineStateCache;
        tdi.metalVertexFunction = program->metalVertexFunction;
        tdi.metalFragmentFunction = program->metalFragmentFunction;
        tdi.metalVertexFunctionOut = &program->metalVertexFunction;
        tdi.metalFragmentFunctionOut = &program->metalFragmentFunction;
        tdi.program = programName;
        tdi.pipelineEmulationFragmentProgram =
            program->pipelineEmulationFragmentProgram;

        logStateResolveCostClass(
            "drawElements-attributeless", programName, vaoName,
            tdi, vao->attributes.size());
        prepareTranslatedDrawUniformBuffers(
            *program, programName, impl_->matrixState, drawID, tdi,
            "drawElements-attributeless");

        impl_->resolveSamplerBindings(*program, tdi);
        impl_->resolveUBOBindings(*program, tdi);
        impl_->resolveSSBOBindings(*program, tdi);
        impl_->resolveImageBindings(*program, tdi);

        // FBO render target.
        {
            GLsizei fboW = 0, fboH = 0;
            void* fboDSTex = nullptr;
            std::array<void*, 7> extraColTex = {};
            std::array<std::uint32_t, 8> colSlices = {};
            std::array<std::uint32_t, 8> colLevels = {};
            void* fboColTex = impl_->resolveFBOColorTarget(
                fboW, fboH, fboDSTex, nullptr,
                &extraColTex, &colSlices, &colLevels);
            if (fboColTex != nullptr || fboDSTex != nullptr) {
                tdi.fboColorTexture = fboColTex;
                tdi.fboAdditionalColorTextures = extraColTex;
                tdi.fboColorSlices = colSlices;
                tdi.fboColorLevels = colLevels;
                tdi.fboDepthStencilTexture = fboDSTex;
                tdi.fboWidth = fboW;
                tdi.fboHeight = fboH;
            }
        }

        thread_local std::string pipelineBuildErrorDE;
        pipelineBuildErrorDE.clear();
        tdi.pipelineBuildErrorOut = &pipelineBuildErrorDE;

        const TranslatedDrawPreflightSnapshot preflight =
            makeTranslatedDrawPreflightSnapshot(
                vaoName, vao,
                /*genericVertexAttributesPrepared=*/true);
        const bool ok = impl_->encodeTranslatedDrawAndMarkFbo(
            tdi, &preflight);
        if (ok) {
            // Sprint 8 #9-A (CKPT67): primitive counter update is
            // handled by the VS-only-TF helper at the earlier hook
            // point (line ~25655) when transform feedback is active.
            // For non-TF draws on this attributeless path, mirror
            // drawArrays' attributeless-success path: update counters
            // here. CTS `query_vertex_*` tests have TF active during
            // the query, so the VS-only-TF helper already advanced
            // GL_TRANSFORM_FEEDBACK_PRIMITIVES_WRITTEN; advancing
            // here AGAIN would double-count. Gate accordingly.
            if (!program->gsPresent && !impl_->transformFeedbackActive) {
                impl_->updatePrimitiveCountersForNonGsDraw(mode, count, 1);
            }
            return true;
        }
        // Fall through to solid-color path on failure.
    }
    drawProfile.mark(GLDrawProfileBucket::SpecialPathChecks);
    if (translatedDrawElementsEligible) {
        // Phase 8X Group 4d follow-up³ — name each fall-through gate to BAR's log.
        drawProfile.mark(GLDrawProfileBucket::TranslatedPreflight);
        bool attributesEmpty = false;
        {
            GLDrawDetailScope detail(
                impl_->drawDetailProfile,
                GLDrawDetailBucket::TranslatedFallbackDecision);
            attributesEmpty = vao->attributes.empty();
            if (attributesEmpty) {
                reportTranslatedFallbackOnce(program, programName,
                    TranslatedFallbackGate::EmptyAttributes, "drawElements",
                    vaoName, 0, 0, 0);
            }
        }
        if (!attributesEmpty) {
            bool vaoLayoutCacheHit = false;
            const GLVertexArrayCachedLayout* vaoLayoutPtr = nullptr;
            {
                GLDrawDetailScope detail(
                    impl_->drawDetailProfile,
                    GLDrawDetailBucket::TranslatedProgramVaoFboState);
                vaoLayoutPtr =
                    &cachedVertexArrayLayout(
                        *vao, false, &vaoLayoutCacheHit,
                        false, true, &impl_->coldPathProfile);
            }
            const auto& vaoLayout = *vaoLayoutPtr;
            drawProfile.mark(GLDrawProfileBucket::VaoLayout);
            GLBufferObject* vbo = (vaoLayout.primaryBufferName != 0)
                ? impl_->objects->buffers().get(vaoLayout.primaryBufferName)
                : nullptr;
            if (vbo == nullptr) {
                reportTranslatedFallbackOnce(program, programName,
                    TranslatedFallbackGate::NullVBO, "drawElements",
                    vaoName, vao->attributes.size(), vaoLayout.primaryBufferName, 0);
            } else if (vbo->shadowBytes.empty()) {
                reportTranslatedFallbackOnce(program, programName,
                    TranslatedFallbackGate::ShadowBytesEmpty, "drawElements",
                    vaoName, vao->attributes.size(), vaoLayout.primaryBufferName, 0);
            }
            drawProfile.mark(GLDrawProfileBucket::VboResolve);
            if (vbo != nullptr && !vbo->shadowBytes.empty()) {
                const std::size_t posStride = vaoLayout.primaryStride;
                const std::size_t startOff = vaoLayout.primaryBaseOffset;

                if (startOff > vbo->shadowBytes.size()) {
                    reportTranslatedFallbackOnce(program, programName,
                        TranslatedFallbackGate::OffsetOverflow, "drawElements",
                        vaoName, vao->attributes.size(), vaoLayout.primaryBufferName,
                        vbo->shadowBytes.size());
                }
                if (startOff <= vbo->shadowBytes.size()) {
                    TranslatedDrawInfo& tdi = reusableTranslatedDrawInfo();
                    tdi.mode = drawElementsMode;
                    tdi.vertexCount = drawElementsCount;
                    tdi.vertexData = vbo->shadowBytes.data() + startOff;
                    tdi.vertexDataByteCount = vbo->shadowBytes.size() - startOff;
                    tdi.vertexStride = posStride;
                    // OPT-5: pass pre-uploaded Metal buffer for direct bind.
                    tdi.metalVertexBuffer = vbo->metalBuffer;
                    tdi.metalVertexBufferOffset = startOff;
                    tdi.glVertexBuffer = vaoLayout.primaryBufferName;
                    tdi.indices = drawElementsIndexPtr;
                    tdi.indexCount = drawElementsCount;
                    tdi.indexType = drawElementsIndexType;
                    tdi.glIndexBuffer = elementBufferName;
                    drawProfile.mark(GLDrawProfileBucket::InfoInit);
                    // OPT-5: pass Metal index buffer when indices weren't
                    // expanded (UINT16/UINT32 pass-through from element VBO).
                    // ADV-10: use the type check instead of the old local vector.
                    if (!usePrimitiveRestartIndices &&
                        elementBuffer != nullptr &&
                        !elementIndexTypeNeedsExpansion(type) &&
                        elementBuffer->metalBuffer != nullptr) {
                        tdi.metalIndexBuffer = elementBuffer->metalBuffer;
                        tdi.metalIndexBufferOffset = indexOffset;
                    }
                    // Phase 8X Group 4d follow-up¹⁴ — centralised fixed-
                    // function state snapshot. See drawArrays.
                    populateTranslatedDrawFixedFunctionState(
                        tdi, *impl_->state, effectiveFragmentShadingRateForProgram(*this, program), this);
                    drawProfile.mark(GLDrawProfileBucket::FixedFunctionState);
                    assignTranslatedDrawProgramMsl(tdi, *program);
                    tdi.vertexReflection = &program->vertexReflection;
                    tdi.fragmentReflection = &program->fragmentReflection;
                    tdi.pipelineStateOut = &program->metalPipelineState;
                    tdi.pipelineColorFormatOut = &program->metalPipelineColorFormat;
                    // Phase 8X Group 4d follow-up¹⁴ — map-based cache
                    // so spring's 15×/frame blend toggle doesn't thrash
                    // the single-slot scalar cache above.
                    tdi.pipelineStateCacheOut = &program->metalPipelineStateCache;
                    tdi.metalVertexFunction = program->metalVertexFunction;
                    tdi.metalFragmentFunction = program->metalFragmentFunction;
                    tdi.metalVertexFunctionOut = &program->metalVertexFunction;
                    tdi.metalFragmentFunctionOut = &program->metalFragmentFunction;
                    // Phase 8X Group 4d follow-up⁸ — diagnostic-only
                    // program identifier used by encodeTranslatedDraw's
                    // first-draw-per-program NSLog. Non-owning, no
                    // correctness impact; zero is a valid placeholder.
                    tdi.program = programName;
                    tdi.pipelineEmulationFragmentProgram =
                        program->pipelineEmulationFragmentProgram;
                    drawProfile.mark(GLDrawProfileBucket::ShaderState);

                    applyCachedVertexArrayLayout(
                        vaoLayout, *impl_->objects, tdi, 0,
                        false, false, &impl_->coldPathProfile);
                    drawProfile.mark(GLDrawProfileBucket::VertexLayout);

                    logStateResolveCostClass(
                        "drawElements", programName, vaoName,
                        tdi, vao->attributes.size(), vaoLayoutCacheHit);
                    drawProfile.mark(GLDrawProfileBucket::Diagnostics);
                    prepareTranslatedDrawUniformBuffers(
                        *program, programName, impl_->matrixState, drawID, tdi,
                        "drawElements");
                    drawProfile.mark(GLDrawProfileBucket::UniformBuffers);

                    impl_->resolveSamplerBindings(*program, tdi);
                    drawProfile.resetCursor();
                    impl_->resolveUBOBindings(*program, tdi);
                    drawProfile.mark(GLDrawProfileBucket::UboBindings);
                    impl_->resolveSSBOBindings(*program, tdi);
                    drawProfile.mark(GLDrawProfileBucket::SsboBindings);
                    impl_->resolveImageBindings(*program, tdi);
                    drawProfile.mark(GLDrawProfileBucket::ImageBindings);

                    // RC-A02: resolve FBO render target.
                    {
                        GLsizei fboW = 0, fboH = 0;
                        void* fboDSTex = nullptr;
                        std::array<void*, 7> extraColTex = {};
                        std::array<std::uint32_t, 8> colSlices = {};
                        std::array<std::uint32_t, 8> colLevels = {};
                        void* fboColTex = impl_->resolveFBOColorTarget(
                            fboW, fboH, fboDSTex, nullptr,
                            &extraColTex, &colSlices, &colLevels);
                        if (fboColTex != nullptr || fboDSTex != nullptr) {
                            tdi.fboColorTexture = fboColTex;
                            tdi.fboAdditionalColorTextures = extraColTex;
                            tdi.fboColorSlices = colSlices;
                            tdi.fboColorLevels = colLevels;
                            tdi.fboDepthStencilTexture = fboDSTex;
                            tdi.fboWidth = fboW;
                            tdi.fboHeight = fboH;
                        }
                    }
                    drawProfile.mark(GLDrawProfileBucket::FboResolve);

                    // Phase 8X Group 4d follow-up⁴ — scratch buffer for the
                    // pipeline-build error text plumbed out of the encode-failed
                    // path. See the matching comment in drawArrays for rationale.
                    thread_local std::string pipelineBuildError;
                    pipelineBuildError.clear();
                    tdi.pipelineBuildErrorOut = &pipelineBuildError;
                    drawProfile.mark(GLDrawProfileBucket::EncodePrep);

                    const TranslatedDrawPreflightSnapshot preflight =
                        makeTranslatedDrawPreflightSnapshot(
                            vaoName, vao,
                            /*genericVertexAttributesPrepared=*/false);
                    const bool ok = impl_->encodeTranslatedDrawAndMarkFbo(
                        tdi, &preflight);
                    drawProfile.resetCursor();
                    if (ok) {
                        return true;
                    }
                    if (reportTranslatedFallbackOnce(program, programName,
                            TranslatedFallbackGate::EncodeFailed, "drawElements",
                            vaoName, vao->attributes.size(), vaoLayout.primaryBufferName,
                            vbo->shadowBytes.size())) {
                        recordPipelineBuildFailureOnce(program, programName, pipelineBuildError);
                    }
                    // Fall through to solid-color path on failure.
                }
            }
        }
    }

    // Fallback: solid-color draw path (hardcoded appgl_solid pipeline).
    SolidColorDrawSetup setup = buildSolidColorDrawSetup(
        *impl_->state,
        *impl_->objects,
        mode,
        "glDrawElements",
        GL_SHADING_RATE_1X1_PIXELS_EXT
    );
    if (!setup.ok) {
        emitDebugMessage(
            GL_DEBUG_SOURCE_API,
            GL_DEBUG_TYPE_OTHER,
            0,
            GL_DEBUG_SEVERITY_LOW,
            "glDrawElements: draw skipped (no translated pipeline and solid-color path unsupported)"
        );
        drawProfile.mark(GLDrawProfileBucket::SolidFallback);
        return false;
    }

    setup.info.vertexCount = drawElementsCount;
    setup.info.baseVertex = 0;
    setup.info.indices = drawElementsIndexPtr;
    setup.info.indexCount = drawElementsCount;
    setup.info.indexType = drawElementsIndexType;

    const bool ok = impl_->frameGraph->encodeSolidColorDraw(setup.info);
    if (ok) {
        impl_->markBoundDrawFramebufferWrites();
    }
    if (!ok) {
        emitDebugMessage(
            GL_DEBUG_SOURCE_API,
            GL_DEBUG_TYPE_ERROR,
            0,
            GL_DEBUG_SEVERITY_HIGH,
            "glDrawElements: MetalFrameGraph failed to encode draw"
        );
    }
    drawProfile.mark(GLDrawProfileBucket::SolidFallback);
    return ok;
}

// ---------------------------------------------------------------------------
// GL 3.2 — Base-vertex indexed drawing (ARB_draw_elements_base_vertex)
// ---------------------------------------------------------------------------

bool GLContext::drawElementsBaseVertex(GLenum mode, GLsizei count, GLenum type, const void* indices, GLint basevertex, GLuint drawID) {
    // GL 4.6 §10.5: mode must be a valid primitive-assembly enum.
    if (!isValidDrawMode(mode)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (count < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (count == 0) {
        return true;
    }
    if (!isSupportedElementIndexType(type)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (!impl_->state->validateForDraw()) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // GL 4.6 §2.3.3 — conditional render predicate.
    if (impl_->shouldSkipDrawForConditionalRender()) {
        return true;
    }
    if (isTransformFeedbackActive()) {
        return drawElementsInstancedBaseVertex(
            mode, count, type, indices, 1, basevertex, 0, drawID);
    }
    // GL 4.6 §22.1 / §22.3 — pipeline-stats counter update for
    // non-GS indexed draws. GS path is handled via
    // writeGsXfbAndCheckDiscard below.
    {
        const GLuint progName = impl_->state->currentProgram();
        const GLProgramObject* p = progName != 0
            ? impl_->objects->programs().get(progName)
            : nullptr;
        if (p == nullptr || !p->gsPresent) {
            const GLsizei restartSkip = impl_->countRestartIndices(type, indices, count);
            impl_->updatePrimitiveCountersForNonGsDraw(mode, count, 1, restartSkip);
        }
    }

    if (impl_->frameGraph == nullptr) {
        return false;
    }
    impl_->frameGraph->resizeDrawable(impl_->drawableSurfaceWidth(), impl_->drawableSurfaceHeight());
    impl_->encodePendingWork();

    // Resolve element buffer — same as drawElements.
    const GLuint vaoName = impl_->state->boundVertexArray();
    GLVertexArrayObject* vao = (vaoName != 0) ? impl_->objects->vertexArrays().get(vaoName) : nullptr;
    if (vao == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    const GLuint elementBufferName = vao->elementArrayBuffer;
    if (elementBufferName == 0) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    GLBufferObject* elementBuffer = impl_->objects->buffers().get(elementBufferName);
    if (elementBuffer == nullptr || elementBuffer->shadowBytes.empty()) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }

    const std::size_t indexOffset = reinterpret_cast<std::uintptr_t>(indices);
    if (indexOffset > elementBuffer->shadowBytes.size()) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    const void* indexPtr = elementBuffer->shadowBytes.data() + indexOffset;

    // Handle GL_UNSIGNED_BYTE expansion (same as drawElements).
    GLenum effectiveType = type;
    const void* effectivePtr = indexPtr;
    if (elementIndexTypeNeedsExpansion(type)) {
        const bool expansionCacheHit =
            elementBuffer->cachedExpansionGeneration == elementBuffer->indexExpansionGeneration &&
            !elementBuffer->cachedExpandedIndices.empty();
        if (!expansionCacheHit) {
            const GLsizei totalIndices = static_cast<GLsizei>(elementBuffer->shadowBytes.size());
            IndexExpansionResult result = expandElementIndices(
                totalIndices, type, elementBuffer->shadowBytes.data());
            if (!result.ok) {
                pushError(result.error);
                return false;
            }
            elementBuffer->cachedExpandedIndices = std::move(result.bytes);
            elementBuffer->cachedExpansionGeneration = elementBuffer->indexExpansionGeneration;
            impl_->noteR5ExpandedIndexCacheRebuilt(*elementBuffer);
        }
        effectiveType = GL_UNSIGNED_SHORT;
        const std::size_t expandedOffset = indexOffset * sizeof(GLushort);
        effectivePtr = elementBuffer->cachedExpandedIndices.data() + expandedOffset;
        impl_->touchR5ExpandedIndexCache(*elementBuffer);
        logIndexExpansionCostClass(
            "drawElementsBaseVertex", elementBufferName, type, effectiveType,
            static_cast<GLsizei>(elementBuffer->shadowBytes.size()),
            elementBuffer->cachedExpandedIndices.size(), expansionCacheHit,
            elementBuffer->cachedExpansionGeneration);
    }

    // Try translated shader pipeline first.
    // GL 4.6 §7.4 — prefer glUseProgram's program; fall back to the
    // active program pipeline's VS+FS merged onto its VS container
    // when only a pipeline is bound. Covers the CTS VAB tests that
    // drive separable programs through glCreateShaderProgramv +
    // glUseProgramStages without ever calling glUseProgram.
    GLuint programName = impl_->state->currentProgram();
    GLProgramObject* program = impl_->resolveDrawProgram(programName);

    // GS emul hook for base-vertex indexed draws (drawRangeElements
    // funnels here too).
    if (program != nullptr && program->geometryEmulated && count > 0) {
        const bool dcr4eExactNoLegacy =
            dcr4eRequiresExactCpuGsNoLegacyFallback(
                program, mode, isTransformFeedbackActive());
        std::vector<std::uint32_t> idx32(static_cast<std::size_t>(count));
        if (effectiveType == GL_UNSIGNED_INT) {
            const std::uint32_t* src32 = static_cast<const std::uint32_t*>(effectivePtr);
            std::memcpy(idx32.data(), src32, count * sizeof(std::uint32_t));
        } else if (effectiveType == GL_UNSIGNED_SHORT) {
            const std::uint16_t* src16 = static_cast<const std::uint16_t*>(effectivePtr);
            for (GLsizei i = 0; i < count; ++i) idx32[i] = src16[i];
        } else {
            idx32.clear();
        }
        if (!idx32.empty()) {
            if (basevertex != 0) {
                for (auto& v : idx32) v = static_cast<std::uint32_t>(
                    static_cast<std::int32_t>(v) + basevertex);
            }
            appgl::EmulatedDraw ed = appgl::emulateGeometryDraw(
                *program, *vao, *impl_->objects, *impl_->state,
                mode, count, /*first=*/0, idx32.data());
            if (ed.ok) {
                if (impl_->writeGsXfbAndCheckDiscard(*program, ed)) return true;
                if (ed.vertexCount == 0) return true;
                if (impl_->encodeEmulatedGsDraw(*program, programName, ed)) return true;
                if (dcr4eExactNoLegacy) {
                    appgl::AppGLSubmissionGroup fallbackGroup;
                    impl_->declareCpuGsFallbackSubmissionGroup(fallbackGroup);
                    return true;
                }
            } else if (dcr4eExactNoLegacy) {
                appgl::AppGLSubmissionGroup fallbackGroup;
                impl_->declareCpuGsFallbackSubmissionGroup(fallbackGroup);
                return true;
            }
        }
    }

    if (program != nullptr && program->hasTranslatedPipeline) {
        if (vao->attributes.empty()) {
            reportTranslatedFallbackOnce(program, programName,
                TranslatedFallbackGate::EmptyAttributes, "drawElementsBaseVertex",
                vaoName, 0, 0, 0);
        }
        if (!vao->attributes.empty()) {
            bool vaoLayoutCacheHit = false;
            const auto& vaoLayout =
                cachedVertexArrayLayout(
                    *vao, false, &vaoLayoutCacheHit,
                    false, true, &impl_->coldPathProfile);
            GLBufferObject* vbo = (vaoLayout.primaryBufferName != 0)
                ? impl_->objects->buffers().get(vaoLayout.primaryBufferName)
                : nullptr;
            if (vbo == nullptr) {
                reportTranslatedFallbackOnce(program, programName,
                    TranslatedFallbackGate::NullVBO, "drawElementsBaseVertex",
                    vaoName, vao->attributes.size(), vaoLayout.primaryBufferName, 0);
            } else if (vbo->shadowBytes.empty()) {
                reportTranslatedFallbackOnce(program, programName,
                    TranslatedFallbackGate::ShadowBytesEmpty, "drawElementsBaseVertex",
                    vaoName, vao->attributes.size(), vaoLayout.primaryBufferName, 0);
            }
            if (vbo != nullptr && !vbo->shadowBytes.empty()) {
                const std::size_t posStride = vaoLayout.primaryStride;
                const std::size_t startOff = vaoLayout.primaryBaseOffset;

                if (startOff > vbo->shadowBytes.size()) {
                    reportTranslatedFallbackOnce(program, programName,
                        TranslatedFallbackGate::OffsetOverflow, "drawElementsBaseVertex",
                        vaoName, vao->attributes.size(), vaoLayout.primaryBufferName,
                        vbo->shadowBytes.size());
                }
                if (startOff <= vbo->shadowBytes.size()) {
                    TranslatedDrawInfo& tdi = reusableTranslatedDrawInfo();
                    tdi.mode = mode;
                    tdi.vertexCount = count;
                    tdi.baseVertex = basevertex;
                    tdi.shaderBaseVertex = basevertex;
                    tdi.vertexData = vbo->shadowBytes.data() + startOff;
                    tdi.vertexDataByteCount = vbo->shadowBytes.size() - startOff;
                    tdi.vertexStride = posStride;
                    tdi.metalVertexBuffer = vbo->metalBuffer;
                    tdi.metalVertexBufferOffset = startOff;
                    tdi.glVertexBuffer = vaoLayout.primaryBufferName;
                    tdi.indices = effectivePtr;
                    tdi.indexCount = count;
                    tdi.indexType = effectiveType;
                    tdi.glIndexBuffer = elementBufferName;
                    if (!elementIndexTypeNeedsExpansion(type) && elementBuffer->metalBuffer != nullptr) {
                        tdi.metalIndexBuffer = elementBuffer->metalBuffer;
                        tdi.metalIndexBufferOffset = indexOffset;
                    }
                    populateTranslatedDrawFixedFunctionState(
                        tdi, *impl_->state, effectiveFragmentShadingRateForProgram(*this, program), this);
                    assignTranslatedDrawProgramMsl(tdi, *program);
                    tdi.vertexReflection = &program->vertexReflection;
                    tdi.fragmentReflection = &program->fragmentReflection;
                    tdi.pipelineStateOut = &program->metalPipelineState;
                    tdi.pipelineColorFormatOut = &program->metalPipelineColorFormat;
                    tdi.pipelineStateCacheOut = &program->metalPipelineStateCache;
                    tdi.metalVertexFunction = program->metalVertexFunction;
                    tdi.metalFragmentFunction = program->metalFragmentFunction;
                    tdi.metalVertexFunctionOut = &program->metalVertexFunction;
                    tdi.metalFragmentFunctionOut = &program->metalFragmentFunction;
                    tdi.program = programName;
                    tdi.pipelineEmulationFragmentProgram =
                        program->pipelineEmulationFragmentProgram;

                    applyCachedVertexArrayLayout(
                        vaoLayout, *impl_->objects, tdi, 0,
                        false, false, &impl_->coldPathProfile);

                    logStateResolveCostClass(
                        "drawElementsBaseVertex", programName, vaoName,
                        tdi, vao->attributes.size(), vaoLayoutCacheHit);
                    prepareTranslatedDrawUniformBuffers(
                        *program, programName, impl_->matrixState, drawID, tdi,
                        "drawElementsBaseVertex");

                    impl_->resolveSamplerBindings(*program, tdi);
                    impl_->resolveUBOBindings(*program, tdi);
                    impl_->resolveSSBOBindings(*program, tdi);
                    impl_->resolveImageBindings(*program, tdi);

                    // RC-A02: resolve FBO render target.
                    {
                        GLsizei fboW = 0, fboH = 0;
                        void* fboDSTex = nullptr;
                        std::array<void*, 7> extraColTex = {};
                        std::array<std::uint32_t, 8> colSlices = {};
                        std::array<std::uint32_t, 8> colLevels = {};
                        void* fboColTex = impl_->resolveFBOColorTarget(
                            fboW, fboH, fboDSTex, nullptr,
                            &extraColTex, &colSlices, &colLevels);
                        if (fboColTex != nullptr || fboDSTex != nullptr) {
                            tdi.fboColorTexture = fboColTex;
                            tdi.fboAdditionalColorTextures = extraColTex;
                            tdi.fboColorSlices = colSlices;
                            tdi.fboColorLevels = colLevels;
                            tdi.fboDepthStencilTexture = fboDSTex;
                            tdi.fboWidth = fboW;
                            tdi.fboHeight = fboH;
                        }
                    }

                    thread_local std::string pipelineBuildError;
                    pipelineBuildError.clear();
                    tdi.pipelineBuildErrorOut = &pipelineBuildError;

                    const TranslatedDrawPreflightSnapshot preflight =
                        makeTranslatedDrawPreflightSnapshot(
                            vaoName, vao,
                            /*genericVertexAttributesPrepared=*/false);
                    const bool ok = impl_->encodeTranslatedDrawAndMarkFbo(
                        tdi, &preflight);
                    if (ok) {
                        return true;
                    }
                    if (reportTranslatedFallbackOnce(program, programName,
                            TranslatedFallbackGate::EncodeFailed, "drawElementsBaseVertex",
                            vaoName, vao->attributes.size(), vaoLayout.primaryBufferName,
                            vbo->shadowBytes.size())) {
                        recordPipelineBuildFailureOnce(program, programName, pipelineBuildError);
                    }
                }
            }
        }
    }

    // Fallback: solid-color draw path.
    SolidColorDrawSetup setup = buildSolidColorDrawSetup(
        *impl_->state,
        *impl_->objects,
        mode,
        "glDrawElementsBaseVertex",
        GL_SHADING_RATE_1X1_PIXELS_EXT
    );
    if (!setup.ok) {
        emitDebugMessage(
            GL_DEBUG_SOURCE_API,
            GL_DEBUG_TYPE_OTHER,
            0,
            GL_DEBUG_SEVERITY_LOW,
            "glDrawElementsBaseVertex: draw skipped (no translated pipeline and solid-color path unsupported)"
        );
        return false;
    }

    setup.info.vertexCount = count;
    setup.info.baseVertex = basevertex;
    setup.info.indices = effectivePtr;
    setup.info.indexCount = count;
    setup.info.indexType = effectiveType;

    const bool solidOk = impl_->frameGraph->encodeSolidColorDraw(setup.info);
    if (solidOk) {
        impl_->markBoundDrawFramebufferWrites();
    }
    if (solidOk && impl_->state->boundDrawFramebuffer() == 0) {
        impl_->invalidateDefaultFramebufferShadow();
    }
    if (!solidOk) {
        emitDebugMessage(
            GL_DEBUG_SOURCE_API,
            GL_DEBUG_TYPE_ERROR,
            0,
            GL_DEBUG_SEVERITY_HIGH,
            "glDrawElementsBaseVertex: MetalFrameGraph failed to encode draw"
        );
    }
    return solidOk;
}

bool GLContext::drawRangeElementsBaseVertex(GLenum mode, GLuint start, GLuint end, GLsizei count, GLenum type, const void* indices, GLint basevertex) {
    // Per the GL spec, start/end are range hints only. The spec says we MAY
    // use them for validation but MUST NOT reject draws where indices fall
    // outside [start, end]. We validate the basic constraints and delegate
    // to drawElementsBaseVertex for the actual draw.
    if (count < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (end < start) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    return drawElementsBaseVertex(mode, count, type, indices, basevertex);
}

bool GLContext::drawElementsInstancedBaseVertex(GLenum mode, GLsizei count, GLenum type, const void* indices, GLsizei instancecount, GLint basevertex, GLuint baseinstance, GLuint drawID) {
    if (!isValidDrawMode(mode)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (count < 0 || instancecount < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (count == 0 || instancecount == 0) {
        return true;
    }
    if (!isSupportedElementIndexType(type)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (!impl_->state->validateForDraw()) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // GL 4.6 §2.3.3 — conditional render predicate.
    if (impl_->shouldSkipDrawForConditionalRender()) {
        return true;
    }
    // GL 4.6 §11.3.1: draw-mode / GS-input-topology compat. See
    // drawArraysInstanced for the rationale — the drawElements
    // indirect path lands here so the gate must live at this level
    // to catch `draw_indirect.negative-gshIncompatible-elements`.
    {
        const GLuint progName = impl_->state->currentProgram();
        const GLProgramObject* p = progName != 0
            ? impl_->objects->programs().get(progName)
            : nullptr;
        // Tess-in-pipeline escape — see drawArrays for rationale.
        if (p != nullptr && p->gsPresent && !p->hasTessellation &&
            !isDrawModeCompatibleWithGs(mode, p->gsInputTopology)) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
        // GL 4.6 §22.1 / §22.3 — pipeline-stats counter update.
        if (p == nullptr || !p->gsPresent) {
            const GLsizei restartSkip = impl_->countRestartIndices(type, indices, count);
            impl_->updatePrimitiveCountersForNonGsDraw(mode, count, instancecount, restartSkip);
        }
    }
    impl_->touchR5Residency(MetalR5ResidencyTouchKind::Draw);

    if (impl_->frameGraph == nullptr) {
        return false;
    }
    impl_->frameGraph->resizeDrawable(impl_->drawableSurfaceWidth(), impl_->drawableSurfaceHeight());
    impl_->encodePendingWork();

    // Resolve element buffer.
    const GLuint vaoName = impl_->state->boundVertexArray();
    GLVertexArrayObject* vao = (vaoName != 0) ? impl_->objects->vertexArrays().get(vaoName) : nullptr;
    if (vao == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    const GLuint elementBufferName = vao->elementArrayBuffer;
    if (elementBufferName == 0) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    GLBufferObject* elementBuffer = impl_->objects->buffers().get(elementBufferName);
    if (elementBuffer == nullptr || elementBuffer->shadowBytes.empty()) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }

    const std::size_t indexOffset = reinterpret_cast<std::uintptr_t>(indices);
    if (indexOffset > elementBuffer->shadowBytes.size()) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    const void* indexPtr = elementBuffer->shadowBytes.data() + indexOffset;

    GLenum effectiveType = type;
    const void* effectivePtr = indexPtr;
    if (elementIndexTypeNeedsExpansion(type)) {
        const bool expansionCacheHit =
            elementBuffer->cachedExpansionGeneration == elementBuffer->indexExpansionGeneration &&
            !elementBuffer->cachedExpandedIndices.empty();
        if (!expansionCacheHit) {
            const GLsizei totalIndices = static_cast<GLsizei>(elementBuffer->shadowBytes.size());
            IndexExpansionResult result = expandElementIndices(
                totalIndices, type, elementBuffer->shadowBytes.data());
            if (!result.ok) {
                pushError(result.error);
                return false;
            }
            elementBuffer->cachedExpandedIndices = std::move(result.bytes);
            elementBuffer->cachedExpansionGeneration = elementBuffer->indexExpansionGeneration;
            impl_->noteR5ExpandedIndexCacheRebuilt(*elementBuffer);
        }
        effectiveType = GL_UNSIGNED_SHORT;
        const std::size_t expandedOffset = indexOffset * sizeof(GLushort);
        effectivePtr = elementBuffer->cachedExpandedIndices.data() + expandedOffset;
        impl_->touchR5ExpandedIndexCache(*elementBuffer);
        logIndexExpansionCostClass(
            "drawElementsInstancedBaseVertex", elementBufferName,
            type, effectiveType,
            static_cast<GLsizei>(elementBuffer->shadowBytes.size()),
            elementBuffer->cachedExpandedIndices.size(), expansionCacheHit,
            elementBuffer->cachedExpansionGeneration);
    }

    // Try translated shader pipeline first.
    // GL 4.6 §7.4 — prefer glUseProgram's program; fall back to the
    // active program pipeline's VS+FS merged onto its VS container
    // when only a pipeline is bound. Covers the CTS VAB tests that
    // drive separable programs through glCreateShaderProgramv +
    // glUseProgramStages without ever calling glUseProgram.
    GLuint programName = impl_->state->currentProgram();
    GLProgramObject* program = impl_->resolveDrawProgram(programName);

    // Phase 3f-16: tess-emul for instanced indexed draws. Mirrors
    // the GS path below; the only shared code is the idx32 expand
    // + optional basevertex bias. Kept as a separate block so the
    // passthrough/interpreter precedence over GS-emul (they're
    // mutually exclusive via !geometryEmulated) is preserved.
    if (program != nullptr &&
        (program->tessellationEmulated || program->tessellationInterpreted) &&
        !program->geometryEmulated && count > 0 && instancecount > 0) {
        std::vector<std::uint32_t> tidx32;
        if (effectiveType == GL_UNSIGNED_INT) {
            tidx32.assign(count, 0);
            std::memcpy(tidx32.data(), effectivePtr, count * sizeof(std::uint32_t));
        } else if (effectiveType == GL_UNSIGNED_SHORT) {
            tidx32.assign(count, 0);
            const std::uint16_t* src16 =
                static_cast<const std::uint16_t*>(effectivePtr);
            for (GLsizei i = 0; i < count; ++i) tidx32[i] = src16[i];
        }
        impl_->compactRestartIndicesForPatchTess(type, tidx32);
        if (!tidx32.empty()) {
            if (basevertex != 0) {
                for (auto& v : tidx32) v = static_cast<std::uint32_t>(
                    static_cast<std::int32_t>(v) + basevertex);
            }
            const GLsizei tessCount = static_cast<GLsizei>(tidx32.size());
            appgl::EmulatedDraw ted = appgl::emulateTessellationDraw(
                *program, *vao, *impl_->objects, *impl_->state,
                mode, tessCount, /*first=*/0, tidx32.data(),
                instancecount, baseinstance);
            if (ted.ok) {
                if (impl_->writeGsXfbAndCheckDiscard(*program, ted)) return true;
                if (ted.vertexCount == 0) return true;
                if (impl_->encodeEmulatedGsDraw(*program, programName, ted)) return true;
            }
        }
    }

    // GS emul hook for instanced indexed draws. See drawElements
    // and drawArraysInstanced for the sibling paths.
    if (program != nullptr && program->geometryEmulated && count > 0 && instancecount > 0) {
        const bool dcr4eExactNoLegacy =
            dcr4eRequiresExactCpuGsNoLegacyFallback(
                program, mode, isTransformFeedbackActive());
        std::vector<std::uint32_t> idx32(static_cast<std::size_t>(count));
        if (effectiveType == GL_UNSIGNED_INT) {
            const std::uint32_t* src32 = static_cast<const std::uint32_t*>(effectivePtr);
            std::memcpy(idx32.data(), src32, count * sizeof(std::uint32_t));
        } else if (effectiveType == GL_UNSIGNED_SHORT) {
            const std::uint16_t* src16 = static_cast<const std::uint16_t*>(effectivePtr);
            for (GLsizei i = 0; i < count; ++i) idx32[i] = src16[i];
        } else {
            idx32.clear();
        }
        if (!idx32.empty()) {
            const auto vsTexMap = impl_->buildSampledTextureMap(
                program->vertexSpirv,
                &program->vertexReflection, *program);
            const auto gsTexMap = impl_->buildSampledTextureMap(
                program->geometrySpirv,
                &program->geometryReflection, *program);
            const auto vsImgMap = impl_->buildStorageImageMap(
                program->vertexSpirv,
                &program->vertexReflection, *program);
            const auto gsImgMap = impl_->buildStorageImageMap(
                program->geometrySpirv,
                &program->geometryReflection, *program);

            appgl::EmulatedDraw priorStage;
            const bool hasTess = program->tessellationEmulated ||
                                 program->tessellationInterpreted;
            if (hasTess) {
                appgl::SampledTextureMap tcsSamMap, tcsImgMap;
                appgl::SampledTextureMap tesSamMap, tesImgMap;
                if (!program->tessControlSpirv.empty()) {
                    tcsSamMap = impl_->buildSampledTextureMap(
                        program->tessControlSpirv,
                        &program->tessControlReflection, *program);
                    tcsImgMap = impl_->buildStorageImageMap(
                        program->tessControlSpirv,
                        &program->tessControlReflection, *program);
                }
                if (!program->tessEvalSpirv.empty()) {
                    tesSamMap = impl_->buildSampledTextureMap(
                        program->tessEvalSpirv,
                        &program->tessEvalAsComputeReflection, *program);
                    tesImgMap = impl_->buildStorageImageMap(
                        program->tessEvalSpirv,
                        &program->tessEvalAsComputeReflection, *program);
                }
                std::vector<std::uint32_t> tessIdx32 = idx32;
                impl_->compactRestartIndicesForPatchTess(type, tessIdx32);
                if (!tessIdx32.empty()) {
                    if (basevertex != 0) {
                        for (auto& v : tessIdx32) {
                            v = static_cast<std::uint32_t>(
                                static_cast<std::int32_t>(v) + basevertex);
                        }
                    }
                    const GLsizei tessCount =
                        static_cast<GLsizei>(tessIdx32.size());
                    priorStage = appgl::emulateTessellationDraw(
                        *program, *vao, *impl_->objects, *impl_->state,
                        mode, tessCount, /*first=*/0, tessIdx32.data(),
                        instancecount, baseinstance,
                        tcsSamMap.empty() ? nullptr : &tcsSamMap,
                        tcsImgMap.empty() ? nullptr : &tcsImgMap,
                        tesSamMap.empty() ? nullptr : &tesSamMap,
                        tesImgMap.empty() ? nullptr : &tesImgMap,
                        vsTexMap.empty() ? nullptr : &vsTexMap,
                        vsImgMap.empty() ? nullptr : &vsImgMap);
                    if (!priorStage.ok && !priorStage.diagnostic.empty()) {
                        APPGL_LOG(SHADER,
                                  @"drawElementsInstancedBaseVertex tess+GS: tess-emul: %s",
                                  priorStage.diagnostic.c_str());
                    }
                }
            }

            std::vector<std::uint32_t> geomIdx32 = idx32;
            // basevertex applied per GL 4.6 §10.6.3: each element
            // index gets `basevertex` added before VBO fetch.
            if (basevertex != 0) {
                for (auto& v : geomIdx32) {
                    v = static_cast<std::uint32_t>(
                        static_cast<std::int32_t>(v) + basevertex);
                }
            }
            appgl::EmulatedDraw ed = appgl::emulateGeometryDraw(
                *program, *vao, *impl_->objects, *impl_->state,
                mode, count, /*first=*/0, geomIdx32.data(),
                instancecount, baseinstance,
                vsTexMap.empty() ? nullptr : &vsTexMap,
                gsTexMap.empty() ? nullptr : &gsTexMap,
                vsImgMap.empty() ? nullptr : &vsImgMap,
                gsImgMap.empty() ? nullptr : &gsImgMap,
                (hasTess && priorStage.ok) ? &priorStage : nullptr);
            if (ed.ok) {
                if (impl_->writeGsXfbAndCheckDiscard(*program, ed)) return true;
                if (ed.vertexCount == 0) return true;
                if (impl_->encodeEmulatedGsDraw(*program, programName, ed)) return true;
                if (dcr4eExactNoLegacy) {
                    appgl::AppGLSubmissionGroup fallbackGroup;
                    impl_->declareCpuGsFallbackSubmissionGroup(fallbackGroup);
                    return true;
                }
            } else if (dcr4eExactNoLegacy) {
                appgl::AppGLSubmissionGroup fallbackGroup;
                impl_->declareCpuGsFallbackSubmissionGroup(fallbackGroup);
                return true;
            }
        }
    }

    if (program != nullptr &&
        isTransformFeedbackActive() &&
        !program->transformFeedbackVaryingNames.empty() &&
        !program->geometryEmulated &&
        !program->tessellationEmulated &&
        !program->tessellationInterpreted &&
        count > 0 && instancecount > 0 &&
        effectivePtr != nullptr) {
        std::vector<std::uint32_t> idx32(static_cast<std::size_t>(count));
        if (effectiveType == GL_UNSIGNED_INT) {
            std::memcpy(idx32.data(), effectivePtr, count * sizeof(std::uint32_t));
        } else if (effectiveType == GL_UNSIGNED_SHORT) {
            const std::uint16_t* src16 =
                static_cast<const std::uint16_t*>(effectivePtr);
            for (GLsizei i = 0; i < count; ++i) idx32[i] = src16[i];
        } else {
            idx32.clear();
        }
        if (!idx32.empty() && basevertex != 0) {
            for (auto& v : idx32) {
                v = static_cast<std::uint32_t>(
                    static_cast<std::int32_t>(v) + basevertex);
            }
        }

        std::vector<std::uint32_t> capIdx;
        if (!idx32.empty()) {
            const std::size_t n = idx32.size();
            switch (mode) {
                case GL_POINTS:
                case GL_LINES:
                case GL_TRIANGLES:
                    capIdx = idx32;
                    break;
                case GL_LINE_STRIP:
                    if (n >= 2) {
                        capIdx.reserve(2 * (n - 1));
                        for (std::size_t i = 0; i + 1 < n; ++i) {
                            capIdx.push_back(idx32[i]);
                            capIdx.push_back(idx32[i + 1]);
                        }
                    }
                    break;
                case GL_LINE_LOOP:
                    if (n >= 2) {
                        capIdx.reserve(2 * n);
                        for (std::size_t i = 0; i < n; ++i) {
                            capIdx.push_back(idx32[i]);
                            capIdx.push_back(idx32[(i + 1) % n]);
                        }
                    }
                    break;
                case GL_TRIANGLE_STRIP:
                    if (n >= 3) {
                        capIdx.reserve(3 * (n - 2));
                        for (std::size_t i = 0; i + 2 < n; ++i) {
                            if ((i & 1u) == 0u) {
                                capIdx.push_back(idx32[i]);
                                capIdx.push_back(idx32[i + 1]);
                                capIdx.push_back(idx32[i + 2]);
                            } else {
                                capIdx.push_back(idx32[i + 1]);
                                capIdx.push_back(idx32[i]);
                                capIdx.push_back(idx32[i + 2]);
                            }
                        }
                    }
                    break;
                case GL_TRIANGLE_FAN:
                    if (n >= 3) {
                        capIdx.reserve(3 * (n - 2));
                        for (std::size_t i = 1; i + 1 < n; ++i) {
                            capIdx.push_back(idx32[0]);
                            capIdx.push_back(idx32[i]);
                            capIdx.push_back(idx32[i + 1]);
                        }
                    }
                    break;
                default:
                    capIdx.clear();
                    break;
            }
        }
        if (!capIdx.empty() && !program->vertexSpirv.empty()) {
            const GLenum capTopology =
                (mode == GL_POINTS) ? GL_POINTS :
                (mode == GL_LINES || mode == GL_LINE_STRIP || mode == GL_LINE_LOOP) ? GL_LINES :
                GL_TRIANGLES;
            const auto vsTexMap = impl_->buildSampledTextureMap(
                program->vertexSpirv,
                &program->vertexReflection, *program);
            const auto vsImgMap = impl_->buildStorageImageMap(
                program->vertexSpirv,
                &program->vertexReflection, *program);
            appgl::EmulatedDraw ed = appgl::emulateVsOnlyDrawForTf(
                *program, *vao, *impl_->objects, *impl_->state,
                capTopology, static_cast<GLsizei>(capIdx.size()), /*first=*/0,
                instancecount, baseinstance,
                capIdx.data(),
                vsTexMap.empty() ? nullptr : &vsTexMap,
                vsImgMap.empty() ? nullptr : &vsImgMap);
            if (ed.ok) {
                bool discard = false;
                if (appgl::vsOnlyTfTimingEnabled()) {
                    const std::uint64_t t0 = appgl::vsOnlyTfTimingNowNs();
                    discard = impl_->writeGsXfbAndCheckDiscard(*program, ed);
                    appgl::recordVsOnlyTfWriteDurationNs(
                        appgl::vsOnlyTfTimingNowNs() - t0);
                } else {
                    discard = impl_->writeGsXfbAndCheckDiscard(*program, ed);
                }
                if (discard) {
                    return true;
                }
            } else if (!ed.diagnostic.empty()) {
                APPGL_LOG(SHADER, @"drawElementsInstancedBaseVertex VS-only-TF: %s",
                          ed.diagnostic.c_str());
            }
        }
    }

    if (program != nullptr && program->hasTranslatedPipeline) {
        if (vao->attributes.empty()) {
            reportTranslatedFallbackOnce(program, programName,
                TranslatedFallbackGate::EmptyAttributes, "drawElementsInstancedBaseVertex",
                vaoName, 0, 0, 0);
        }
        if (!vao->attributes.empty()) {
            bool vaoLayoutCacheHit = false;
            const auto& vaoLayout =
                cachedVertexArrayLayout(
                    *vao, true, &vaoLayoutCacheHit,
                    true, false, &impl_->coldPathProfile);
            GLBufferObject* vbo = (vaoLayout.primaryBufferName != 0)
                ? impl_->objects->buffers().get(vaoLayout.primaryBufferName)
                : nullptr;
            if (vbo == nullptr) {
                reportTranslatedFallbackOnce(program, programName,
                    TranslatedFallbackGate::NullVBO, "drawElementsInstancedBaseVertex",
                    vaoName, vao->attributes.size(), vaoLayout.primaryBufferName, 0);
            } else if (vbo->shadowBytes.empty()) {
                reportTranslatedFallbackOnce(program, programName,
                    TranslatedFallbackGate::ShadowBytesEmpty, "drawElementsInstancedBaseVertex",
                    vaoName, vao->attributes.size(), vaoLayout.primaryBufferName, 0);
            }
            if (vbo != nullptr && !vbo->shadowBytes.empty()) {
                const std::size_t posStride = vaoLayout.primaryStride;
                const std::size_t startOff = vaoLayout.primaryBaseOffset;

                if (startOff > vbo->shadowBytes.size()) {
                    reportTranslatedFallbackOnce(program, programName,
                        TranslatedFallbackGate::OffsetOverflow, "drawElementsInstancedBaseVertex",
                        vaoName, vao->attributes.size(), vaoLayout.primaryBufferName,
                        vbo->shadowBytes.size());
                }
                if (startOff <= vbo->shadowBytes.size()) {
                    TranslatedDrawInfo& tdi = reusableTranslatedDrawInfo();
                    tdi.mode = mode;
                    tdi.vertexCount = count;
                    tdi.baseVertex = basevertex;
                    tdi.shaderBaseVertex = basevertex;
                    tdi.instanceCount = instancecount;
                    tdi.baseInstance = baseinstance;
                    tdi.vertexData = vbo->shadowBytes.data() + startOff;
                    tdi.vertexDataByteCount = vbo->shadowBytes.size() - startOff;
                    tdi.vertexStride = posStride;
                    tdi.metalVertexBuffer = vbo->metalBuffer;
                    tdi.metalVertexBufferOffset = startOff;
                    tdi.glVertexBuffer = vaoLayout.primaryBufferName;
                    tdi.indices = effectivePtr;
                    tdi.indexCount = count;
                    tdi.indexType = effectiveType;
                    tdi.glIndexBuffer = elementBufferName;
                    if (!elementIndexTypeNeedsExpansion(type) && elementBuffer->metalBuffer != nullptr) {
                        tdi.metalIndexBuffer = elementBuffer->metalBuffer;
                        tdi.metalIndexBufferOffset = indexOffset;
                    }
                    populateTranslatedDrawFixedFunctionState(
                        tdi, *impl_->state, effectiveFragmentShadingRateForProgram(*this, program), this);
                    assignTranslatedDrawProgramMsl(tdi, *program);
                    tdi.vertexReflection = &program->vertexReflection;
                    tdi.fragmentReflection = &program->fragmentReflection;
                    tdi.pipelineStateOut = &program->metalPipelineState;
                    tdi.pipelineColorFormatOut = &program->metalPipelineColorFormat;
                    tdi.pipelineStateCacheOut = &program->metalPipelineStateCache;
                    tdi.metalVertexFunction = program->metalVertexFunction;
                    tdi.metalFragmentFunction = program->metalFragmentFunction;
                    tdi.metalVertexFunctionOut = &program->metalVertexFunction;
                    tdi.metalFragmentFunctionOut = &program->metalFragmentFunction;
                    tdi.program = programName;
                    tdi.pipelineEmulationFragmentProgram =
                        program->pipelineEmulationFragmentProgram;

                    applyCachedVertexArrayLayout(
                        vaoLayout, *impl_->objects, tdi, 0,
                        false, false, &impl_->coldPathProfile);

                    logStateResolveCostClass(
                        "drawElementsInstancedBaseVertex", programName, vaoName,
                        tdi, vao->attributes.size(), vaoLayoutCacheHit);
                    prepareTranslatedDrawUniformBuffers(
                        *program, programName, impl_->matrixState, drawID, tdi,
                        "drawElementsInstancedBaseVertex");

                    impl_->resolveSamplerBindings(*program, tdi);
                    impl_->resolveUBOBindings(*program, tdi);
                    impl_->resolveSSBOBindings(*program, tdi);
                    impl_->resolveImageBindings(*program, tdi);

                    // RC-A02: resolve FBO render target.
                    {
                        GLsizei fboW = 0, fboH = 0;
                        void* fboDSTex = nullptr;
                        std::array<void*, 7> extraColTex = {};
                        std::array<std::uint32_t, 8> colSlices = {};
                        std::array<std::uint32_t, 8> colLevels = {};
                        void* fboColTex = impl_->resolveFBOColorTarget(
                            fboW, fboH, fboDSTex, nullptr,
                            &extraColTex, &colSlices, &colLevels);
                        if (fboColTex != nullptr || fboDSTex != nullptr) {
                            tdi.fboColorTexture = fboColTex;
                            tdi.fboAdditionalColorTextures = extraColTex;
                            tdi.fboColorSlices = colSlices;
                            tdi.fboColorLevels = colLevels;
                            tdi.fboDepthStencilTexture = fboDSTex;
                            tdi.fboWidth = fboW;
                            tdi.fboHeight = fboH;
                        }
                    }

                    thread_local std::string pipelineBuildError;
                    pipelineBuildError.clear();
                    tdi.pipelineBuildErrorOut = &pipelineBuildError;

                    const TranslatedDrawPreflightSnapshot preflight =
                        makeTranslatedDrawPreflightSnapshot(
                            vaoName, vao,
                            /*genericVertexAttributesPrepared=*/false);
                    const bool ok = impl_->encodeTranslatedDrawAndMarkFbo(
                        tdi, &preflight);
                    if (ok) {
                        return true;
                    }
                    if (reportTranslatedFallbackOnce(program, programName,
                            TranslatedFallbackGate::EncodeFailed, "drawElementsInstancedBaseVertex",
                            vaoName, vao->attributes.size(), vaoLayout.primaryBufferName,
                            vbo->shadowBytes.size())) {
                        recordPipelineBuildFailureOnce(program, programName, pipelineBuildError);
                    }
                }
            }
        }
    }

    // Fallback: solid-color draw path (no instancing support in solid-color).
    SolidColorDrawSetup setup = buildSolidColorDrawSetup(
        *impl_->state,
        *impl_->objects,
        mode,
        "glDrawElementsInstancedBaseVertex",
        GL_SHADING_RATE_1X1_PIXELS_EXT
    );
    if (!setup.ok) {
        emitDebugMessage(
            GL_DEBUG_SOURCE_API,
            GL_DEBUG_TYPE_OTHER,
            0,
            GL_DEBUG_SEVERITY_LOW,
            "glDrawElementsInstancedBaseVertex: draw skipped (no translated pipeline and solid-color path unsupported)"
        );
        return false;
    }

    setup.info.vertexCount = count;
    setup.info.baseVertex = basevertex;
    setup.info.indices = effectivePtr;
    setup.info.indexCount = count;
    setup.info.indexType = effectiveType;

    const bool solidOk = impl_->frameGraph->encodeSolidColorDraw(setup.info);
    if (solidOk) {
        impl_->markBoundDrawFramebufferWrites();
    }
    if (solidOk && impl_->state->boundDrawFramebuffer() == 0) {
        impl_->invalidateDefaultFramebufferShadow();
    }
    if (!solidOk) {
        emitDebugMessage(
            GL_DEBUG_SOURCE_API,
            GL_DEBUG_TYPE_ERROR,
            0,
            GL_DEBUG_SEVERITY_HIGH,
            "glDrawElementsInstancedBaseVertex: MetalFrameGraph failed to encode draw"
        );
    }
    return solidOk;
}

bool GLContext::multiDrawArrays(GLenum mode, const GLint* first, const GLsizei* count, GLsizei drawcount) {
    if (!isValidDrawMode(mode)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (drawcount < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (drawcount > 0 && (first == nullptr || count == nullptr)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    for (GLsizei i = 0; i < drawcount; ++i) {
        if (count[i] < 0) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
    }
    for (GLsizei i = 0; i < drawcount; ++i) {
        if (count[i] > 0) {
            drawArrays(mode, first[i], count[i], static_cast<GLuint>(i));
        }
    }
    return true;
}

bool GLContext::multiDrawElements(GLenum mode, const GLsizei* count, GLenum type, const void* const* indices, GLsizei drawcount) {
    if (!isValidDrawMode(mode)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (drawcount < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (!isSupportedElementIndexType(type)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (drawcount > 0 && (count == nullptr || indices == nullptr)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    for (GLsizei i = 0; i < drawcount; ++i) {
        if (count[i] < 0) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
    }
    for (GLsizei i = 0; i < drawcount; ++i) {
        if (count[i] > 0) {
            drawElements(mode, count[i], type, indices[i], static_cast<GLuint>(i));
        }
    }
    return true;
}

bool GLContext::multiDrawElementsBaseVertex(GLenum mode, const GLsizei* count, GLenum type, const void* const* indices, GLsizei drawcount, const GLint* basevertex) {
    if (!isValidDrawMode(mode)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (drawcount < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (!isSupportedElementIndexType(type)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    // GL 4.6 §10.5: per-sub-draw count must be non-negative. Check
    // ALL entries up-front so an out-of-bounds value doesn't silently
    // drop some sub-draws before the error is reported. CTS
    // `draw_elements_base_vertex_tests.invalid_count_argument` asserts
    // INVALID_VALUE.
    if (count != nullptr) {
        for (GLsizei i = 0; i < drawcount; ++i) {
            if (count[i] < 0) {
                pushError(GL_INVALID_VALUE);
                return false;
            }
        }
    }
    // Multi-draw decomposes into individual draws per the GL spec.
    for (GLsizei i = 0; i < drawcount; ++i) {
        if (count[i] > 0) {
            drawElementsBaseVertex(mode, count[i], type, indices[i],
                                   basevertex[i], static_cast<GLuint>(i));
        }
    }
    return true;
}

// ---------------------------------------------------------------------------
// GL 4.2 — Memory Barriers
// ---------------------------------------------------------------------------

bool GLContext::memoryBarrier(GLbitfield barriers) {
    // All valid GL 4.2/4.3/4.4 barrier bits. 4.4 added
    // `GL_CLIENT_MAPPED_BUFFER_BARRIER_BIT` (ARB_buffer_storage) —
    // without it here, `buffer_storage.map_persistent_read_pixels`
    // raises INVALID_VALUE on its post-readback barrier.
    constexpr GLbitfield kValidBarrierBits =
        GL_VERTEX_ATTRIB_ARRAY_BARRIER_BIT |
        GL_ELEMENT_ARRAY_BARRIER_BIT |
        GL_UNIFORM_BARRIER_BIT |
        GL_TEXTURE_FETCH_BARRIER_BIT |
        GL_SHADER_IMAGE_ACCESS_BARRIER_BIT |
        GL_COMMAND_BARRIER_BIT |
        GL_PIXEL_BUFFER_BARRIER_BIT |
        GL_TEXTURE_UPDATE_BARRIER_BIT |
        GL_BUFFER_UPDATE_BARRIER_BIT |
        GL_FRAMEBUFFER_BARRIER_BIT |
        GL_TRANSFORM_FEEDBACK_BARRIER_BIT |
        GL_ATOMIC_COUNTER_BARRIER_BIT |
        GL_SHADER_STORAGE_BARRIER_BIT |
        GL_CLIENT_MAPPED_BUFFER_BARRIER_BIT;

    if (barriers != GL_ALL_BARRIER_BITS && (barriers & ~kValidBarrierBits) != 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (impl_->frameGraph != nullptr) {
        impl_->frameGraph->flushParallelEncodeBoundary();
    }

    // For CPU-visible barrier bits (BUFFER_UPDATE | TEXTURE_UPDATE |
    // PIXEL_BUFFER | CLIENT_MAPPED_BUFFER) we need to commit + wait so
    // subsequent glMapBuffer* / glGetTexImage / glReadPixels calls see
    // the GPU writes. Image/texture barriers also need a wait when image
    // atomics are emulated through sidecar buffers, because the sidecar
    // contents must be copied back into the texture before later image,
    // texture, or CPU reads observe them. Metal handles ordinary GPU-to-GPU
    // ordering implicitly, but there's no implicit sync to CPU, and SSBO
    // writes via a VS under GL_RASTERIZER_DISCARD (CTS
    // shader_storage_buffer_object.*-vs) are only readable after the draw's
    // command buffer completes.
    constexpr GLbitfield kCpuVisibleBarriers =
        GL_BUFFER_UPDATE_BARRIER_BIT |
        GL_TEXTURE_UPDATE_BARRIER_BIT |
        GL_PIXEL_BUFFER_BARRIER_BIT |
        GL_CLIENT_MAPPED_BUFFER_BARRIER_BIT;
    constexpr GLbitfield kImageAtomicSidecarBarriers =
        GL_SHADER_IMAGE_ACCESS_BARRIER_BIT |
        GL_TEXTURE_FETCH_BARRIER_BIT |
        GL_TEXTURE_UPDATE_BARRIER_BIT |
        GL_FRAMEBUFFER_BARRIER_BIT;
    const bool requiresCpuSync =
        (barriers == GL_ALL_BARRIER_BITS) ||
        (barriers & (kCpuVisibleBarriers | kImageAtomicSidecarBarriers)) != 0;
    if (requiresCpuSync && impl_->frameGraph != nullptr) {
        impl_->frameGraph->flushForReadback();
        impl_->flushTextureImageAtomicSidecars();
        impl_->flushImageBinding3DLayerSidecars();
    }
    // GPU-to-GPU barriers (UNIFORM / TEXTURE_FETCH / SHADER_STORAGE / etc.)
    // are implicit on Metal's command queue — same-queue ordering is
    // preserved so the next pipeline's reads see the previous pipeline's
    // writes without an explicit fence.
    return true;
}

// ---------------------------------------------------------------------------
// GL 4.3 — Compute Shaders
// ---------------------------------------------------------------------------

bool GLContext::dispatchCompute(GLuint num_groups_x, GLuint num_groups_y, GLuint num_groups_z) {
    constexpr GLuint kMaxWorkGroups = 65535;

    if (num_groups_x == 0 || num_groups_y == 0 || num_groups_z == 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (num_groups_x > kMaxWorkGroups || num_groups_y > kMaxWorkGroups || num_groups_z > kMaxWorkGroups) {
        pushError(GL_INVALID_VALUE);
        return false;
    }

    // Resolve the currently-bound program. GL 4.6 §17.1 requires
    // GL_INVALID_OPERATION when there's no active program OR when
    // the active program doesn't contain a compute shader. We detect
    // both by checking whether `metalComputePipelineState` is non-null
    // — linkProgram only populates it for programs with ProgramKind
    // ::Compute. This surfaces the compute-shader.api-no-active-program
    // / api-program negative tests as spec-correct failures.
    //
    // CKPT119: when the current program is 0 but a program pipeline is
    // bound with a compute stage (glUseProgramStages(...,
    // GL_COMPUTE_SHADER_BIT, prog)), use the pipeline's compute slot.
    // CTS shader_image_size.basic-nonMS-cs-* relies on this path.
    GLuint progName = impl_->state->currentProgram();
    GLProgramObject* programObject = progName == 0 ? nullptr
        : impl_->objects->programs().get(progName);
    if (programObject == nullptr || !programObject->linked
        || programObject->metalComputePipelineState == nullptr) {
        const GLuint pipelineName = impl_->state->currentProgramPipeline();
        if (pipelineName != 0) {
            GLProgramPipelineObject* ppo =
                impl_->objects->programPipelines().get(pipelineName);
            if (ppo != nullptr && ppo->computeProgram != 0) {
                GLProgramObject* csProg =
                    impl_->objects->programs().get(ppo->computeProgram);
                if (csProg != nullptr && csProg->linked
                    && (csProg->metalComputePipelineState != nullptr ||
                        csProg->ssboStdLayoutRawCopyFallback)) {
                    programObject = csProg;
                    progName = ppo->computeProgram;
                }
            }
        }
        const bool hasComputePipeline =
            programObject != nullptr && programObject->linked &&
            programObject->metalComputePipelineState != nullptr;
        const bool hasRawCopyFallback =
            programObject != nullptr && programObject->linked &&
            programObject->ssboStdLayoutRawCopyFallback;
        if (!hasComputePipeline && !hasRawCopyFallback) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
    }
    // GL 4.6 §2.3.3 — conditional render predicate. Skipped dispatches
    // do not advance query counters or update shader-visible storage.
    if (impl_->shouldSkipDrawForConditionalRender()) {
        return true;
    }
    impl_->touchR5Residency(MetalR5ResidencyTouchKind::Dispatch);

    // GL 4.6 §22.4 — credit COMPUTE_SHADER_INVOCATIONS for every
    // active query by the total workgroup-invocation count
    // (groups × local-size). Done before dispatch so the counter
    // advances even if pipeline encode fails.
    impl_->objects->queries().forEach([&](GLuint /*id*/, GLQueryObject& q) {
        if (!q.active || q.target != GL_COMPUTE_SHADER_INVOCATIONS) return;
        const GLuint64 local = static_cast<GLuint64>(programObject->computeLocalSizeX) *
                               static_cast<GLuint64>(programObject->computeLocalSizeY) *
                               static_cast<GLuint64>(programObject->computeLocalSizeZ);
        const GLuint64 groups = static_cast<GLuint64>(num_groups_x) *
                                static_cast<GLuint64>(num_groups_y) *
                                static_cast<GLuint64>(num_groups_z);
        q.result += groups * (local == 0 ? 1 : local);
    });

    if (programObject->metalComputePipelineState == nullptr &&
        programObject->ssboStdLayoutRawCopyFallback) {
        return impl_->runSSBOStdLayoutRawCopyFallback();
    }
    if (impl_->frameGraph == nullptr) {
        // Pipeline was built but the frame graph is torn down — no
        // dispatch is possible. Treat as a silent no-op to avoid
        // spurious errors during teardown paths.
        return true;
    }

    ComputeDispatchInfo info;
    info.metalComputePipelineState = programObject->metalComputePipelineState;
    info.metalComputeFunction = programObject->metalComputeFunction;
    info.needsSSBOSizeBuffer =
        programObject->computeMSL.find("spvBufferSizeConstants") != std::string::npos;
    info.groupsX = num_groups_x;
    info.groupsY = num_groups_y;
    info.groupsZ = num_groups_z;
    info.localX = programObject->computeLocalSizeX;
    info.localY = programObject->computeLocalSizeY;
    info.localZ = programObject->computeLocalSizeZ;

    struct Fp64ComputeSidecarSync {
        GLBufferObject* buffer = nullptr;
        const ShaderReflection::ResourceBinding* binding = nullptr;
        GLBufferObject::Fp64TransportSidecar* sidecar = nullptr;
    };
    std::vector<Fp64ComputeSidecarSync> fp64SsboSidecars;
    GLContext::Impl::GpuResourceReadSet computeReads;
    GLContext::Impl::GpuResourceWriteSet computeWrites;

    // Pack default uniforms (bare GL uniforms in the _DefaultUniforms
    // block) for the compute stage. Mirrors the graphics-stage path:
    // lazy layout compute + per-dispatch rebuild of the byte buffer
    // from uniformValues. Without this, location-based glUniform*
    // updates for a compute program never reach the MSL kernel.
    // KHR-GL46.explicit_uniform_location.* with a compute variant
    // specifically relies on this.
    thread_local std::vector<std::uint8_t> computeUniformScratch;
    if (!programObject->uniformLayoutComputed
        || programObject->computeUniformLayout.empty()) {
        // Only (re)build the layout vector when we haven't seen this
        // program before OR the compute-side layout is still empty on
        // a program that previously had graphics stages computed.
        computeStageUniformLayout(programObject->computeUniformLayout,
            programObject->computeReflection, programObject->uniforms);
        programObject->uniformLayoutComputed = true;
    }
    if (pushSynthesizedMatrixUniforms(*programObject, impl_->matrixState)) {
        programObject->markUniformsDirty();
    }
    buildStageUniformBuffer(computeUniformScratch,
        programObject->computeReflection, programObject->uniformValues,
        programObject->computeUniformLayout);
    if (!computeUniformScratch.empty()) {
        info.computeUniformData = computeUniformScratch.data();
        info.computeUniformSize = computeUniformScratch.size();
        if (reflectionNeedsFp64BindingShim(programObject->computeReflection) &&
            defaultUniformBlockContainsFp64(programObject->computeReflection)) {
            ExtensionContext extensionContext(*this);
            extensions::fp64::recordDoubleUniformBacking(
                extensionContext, info.computeUniformSize);
        }
    }

    // Resolve shader-storage buffer bindings. For each SSBO the shader
    // declares, look up whatever buffer the app has bound to
    // GL_SHADER_STORAGE_BUFFER at its layout(binding=N) slot via
    // glBindBufferBase / glBindBufferRange, and forward the Metal
    // buffer + offset into the dispatch info. SSBOs with no binding
    // are simply omitted — Metal's unbound-slot behaviour is undefined
    // but won't crash, and the test will fail verification cleanly.
    // Sprint 17 Day 4+ BONUS-2 Phase 2-r [gpu_shader5 ssbo_array_indexing]:
    // SSBO array element iteration. SPIRV-Cross emits a GLSL SSBO array
    // (`buffer B { ... } b[N]`) as N separate `[[buffer(M)]] / [[buffer(
    // M+1)]] ... [[buffer(M+N-1)]]` slots — same shape as the UBO array
    // emit. Each element binds independently at GL slot
    // (effectiveBinding+inst) and Metal slot (ssbo.metalBinding+inst).
    // Sister to the UBO array iteration loop further below (line 29871+,
    // CKPT143 lineage) and the graphics-path resolveUBOBindings array
    // iteration (line 5111+).
    for (const auto& ssbo : programObject->computeReflection.storageBuffers) {
        // Effective binding may be remapped by glShaderStorageBlockBinding;
        // consult resourceStorageBlocks (same pattern as the graphics
        // path's resolveSSBOBindings).
        GLuint effectiveBinding = ssbo.glBinding;
        for (const auto& rb : programObject->resourceStorageBlocks) {
            if (rb.name == ssbo.name && rb.location >= 0) {
                effectiveBinding = static_cast<GLuint>(rb.location);
                break;
            }
        }
        const int numInstances = (ssbo.blockArraySize > 0)
            ? static_cast<int>(ssbo.blockArraySize) : 1;
        const bool isArray = (ssbo.blockArraySize > 0);
        for (int inst = 0; inst < numInstances; ++inst) {
            // Build the lookup name: "B" or "B[0]"/"B[1]"… so
            // glShaderStorageBlockBinding-driven binding overrides on a
            // specific element honor the resourceStorageBlocks map.
            std::string lookupName = ssbo.name;
            if (isArray) lookupName += "[" + std::to_string(inst) + "]";
            // Default per-element binding is effectiveBinding+inst
            // (consecutive slots, GL 4.6 §7.8). Override with
            // resourceStorageBlocks location if remapped.
            GLuint glBindingPoint = effectiveBinding + static_cast<GLuint>(inst);
            for (const auto& rb : programObject->resourceStorageBlocks) {
                if (rb.name == lookupName && rb.location >= 0) {
                    glBindingPoint = static_cast<GLuint>(rb.location);
                    break;
                }
            }
            const GLIndexedBufferBinding binding = impl_->state->indexedBufferBinding(
                GL_SHADER_STORAGE_BUFFER, glBindingPoint);
            if (binding.buffer == 0) continue;
            GLBufferObject* bufObj = impl_->objects->buffers().get(binding.buffer);
            if (bufObj == nullptr || bufObj->metalBuffer == nullptr) continue;
            computeReads.push_back({Impl::GpuResourceAccess::Kind::Buffer,
                                    binding.buffer, kProducerAll});
            computeWrites.push_back({Impl::GpuResourceAccess::Kind::Buffer,
                                     binding.buffer,
                                     kProducerComputeWrite |
                                         kProducerShaderStorageWrite});

            ComputeDispatchInfo::BufferBinding bb;
            bb.metalBuffer = bufObj->metalBuffer;
            bb.offset = static_cast<std::size_t>(binding.offset);
            if (binding.size > 0) {
                bb.size = static_cast<std::size_t>(binding.size);
            } else if (binding.offset >= 0 && bufObj->size > binding.offset) {
                bb.size = static_cast<std::size_t>(bufObj->size - binding.offset);
            }
            bb.metalSlot = ssbo.metalBinding + static_cast<std::uint32_t>(inst);
            if (resourceNeedsFp64BindingShim(programObject->computeReflection, ssbo)) {
                auto* sidecar = impl_->ensureFp64TransportSidecar(
                    *bufObj, programObject->computeReflection, ssbo,
                    static_cast<GLintptr>(binding.offset),
                    static_cast<GLsizeiptr>(bb.size));
                if (sidecar != nullptr && sidecar->metalBuffer != nullptr) {
                    bb.metalBuffer = sidecar->metalBuffer;
                    bb.offset = 0;
                    fp64SsboSidecars.push_back({bufObj, &ssbo, sidecar});
                    ExtensionContext extensionContext(*this);
                    extensions::fp64::recordDoubleSsboBacking(
                        extensionContext, bb.size);
                }
            }
            info.buffers.push_back(bb);
        }
    }

    // Resolve uniform-block bindings for the compute stage. Compute
    // shaders rarely use UBOs (the CTS compute tests almost always go
    // through SSBOs exclusively) but the path is symmetric with the
    // graphics uboBindings resolver — walk each reflected block,
    // look up the bound buffer via glBindBufferBase, forward it.
    //
    // CKPT143 (Sprint 13 Day 7): UBO array support. SPIRV-Cross emits a
    // UBO array (`uniform B { ... } b[N]`) as N separate `[[buffer(M)]]`
    // / `[[buffer(M+1)]]` … `[[buffer(M+N-1)]]` slots. CTS
    // shading_language_420pack.binding_uniform_block_array binds 14
    // separate UBOs to GL slots 2..15 and expects each shader element
    // `goku[i]` to read from the bound buffer at GL slot 2+i. Pre-fix
    // only the first element resolved; the other 13 stayed unbound and
    // returned zero, failing the per-element verification. Mirrors the
    // graphics-path resolveUBOBindings array iteration at line 5111+.
    for (const auto& ubo : programObject->computeReflection.uniformBlocks) {
        if (ubo.name == "_DefaultUniforms") continue;
        const int numInstances = (ubo.blockArraySize > 0)
            ? static_cast<int>(ubo.blockArraySize) : 1;
        const bool isArray = (ubo.blockArraySize > 0);
        for (int inst = 0; inst < numInstances; ++inst) {
            // Build the lookup name: "B" or "B[0]", "B[1]" … so
            // glUniformBlockBinding-driven binding overrides on a
            // specific element honor the resourceUniformBlocks map.
            std::string lookupName = ubo.name;
            if (isArray) {
                lookupName += "[" + std::to_string(inst) + "]";
            }
            // Default per-element binding is glBinding+inst (consecutive
            // slots, GL 4.6 §7.6.2). Override with resourceUniformBlocks
            // location if the app has called glUniformBlockBinding.
            GLuint glBindingPoint = ubo.glBinding + static_cast<GLuint>(inst);
            for (std::size_t bi = 0; bi < programObject->resourceUniformBlocks.size(); ++bi) {
                if (programObject->resourceUniformBlocks[bi].name == lookupName) {
                    GLint bp = programObject->resourceUniformBlocks[bi].location;
                    if (bp >= 0) {
                        glBindingPoint = static_cast<GLuint>(bp);
                    }
                    break;
                }
            }
            const GLIndexedBufferBinding binding = impl_->state->indexedBufferBinding(
                GL_UNIFORM_BUFFER, glBindingPoint);
            if (binding.buffer == 0) continue;
            GLBufferObject* bufObj = impl_->objects->buffers().get(binding.buffer);
            if (bufObj == nullptr || bufObj->metalBuffer == nullptr) continue;
            computeReads.push_back({Impl::GpuResourceAccess::Kind::Buffer,
                                    binding.buffer, kProducerAll});

            ComputeDispatchInfo::BufferBinding bb;
            bb.metalBuffer = bufObj->metalBuffer;
            bb.offset = static_cast<std::size_t>(binding.offset);
            bb.metalSlot = ubo.metalBinding + static_cast<std::uint32_t>(inst);
            bb.descriptorSet = 1;
            if (resourceNeedsFp64BindingShim(programObject->computeReflection, ubo)) {
                GLsizeiptr rangeSize = binding.size;
                if (rangeSize <= 0 && binding.offset >= 0 && bufObj->size > binding.offset) {
                    rangeSize = bufObj->size - binding.offset;
                }
                auto* sidecar = impl_->ensureFp64TransportSidecar(
                    *bufObj, programObject->computeReflection, ubo,
                    static_cast<GLintptr>(binding.offset), rangeSize);
                if (sidecar != nullptr && sidecar->metalBuffer != nullptr) {
                    bb.metalBuffer = sidecar->metalBuffer;
                    bb.offset = 0;
                    ExtensionContext extensionContext(*this);
                    extensions::fp64::recordDoubleUniformBacking(
                        extensionContext, static_cast<std::size_t>(rangeSize));
                }
            }
            info.buffers.push_back(bb);
        }
    }

    // Sprint 17 Day 4+ BONUS-2 Phase 3-r [gpu_shader5 atomic_counters_array_indexing]:
    // atomic counter buffer binding for compute. SPIRV-Cross emits AC
    // into a dedicated direct-buffer slot range. Walk the program's
    // atomic-counter buffer resource list and bind each
    // GL_ATOMIC_COUNTER_BUFFER-backed buffer at the matching Metal slot.
    // Without this binding, atomicCounter* operations execute against an
    // unbound MTLBuffer and produce undefined (typically zero) reads.
    for (const auto& ac : programObject->resourceAtomicCounterBuffers) {
        if (ac.binding < 0) continue;
        const GLuint glBinding = static_cast<GLuint>(ac.binding);
        const GLIndexedBufferBinding binding = impl_->state->indexedBufferBinding(
            GL_ATOMIC_COUNTER_BUFFER, glBinding);
        if (binding.buffer == 0) continue;
        const GLBufferObject* bufObj = impl_->objects->buffers().get(binding.buffer);
        if (bufObj == nullptr || bufObj->metalBuffer == nullptr) continue;
        computeReads.push_back({Impl::GpuResourceAccess::Kind::Buffer,
                                binding.buffer, kProducerAll});
        computeWrites.push_back({Impl::GpuResourceAccess::Kind::Buffer,
                                 binding.buffer,
                                 kProducerComputeWrite |
                                     kProducerAtomicCounterWrite});

        ComputeDispatchInfo::BufferBinding bb;
        bb.metalBuffer = bufObj->metalBuffer;
        bb.offset = static_cast<std::size_t>(binding.offset);
        // Atomic counters are emitted after the compute SSBO spec-floor
        // range so they cannot alias SSBOs or the high UBO slots.
        bb.metalSlot = computeAtomicCounterMetalSlot(glBinding);
        info.buffers.push_back(bb);
    }

    // Texture/sampler bindings for compute stage. Less common than
    // SSBOs but real — image-processing compute shaders sample from
    // textures. Walk each reflected sampler uniform, resolve the
    // texture unit via the shader's sampler uniform value, and bind
    // the resulting (texture, sampler) pair at the reflected slot.
    // The logic mirrors resolveSamplerBindings but targets the
    // compute slot space.
    // CKPT144 (Sprint 13 Day 8): sampler-type-aware texture target lookup
    // for compute. The pre-fix code probed GL_TEXTURE_2D first then fell
    // back to boundTextureOnUnitAny — which iterates targets in
    // {2D, 2D_ARRAY, CUBE_MAP, …, 1D, 1D_ARRAY, …} order and returns the
    // first non-zero binding. CTS shading_language_420pack.binding_samplers_
    // texture_type_{1D,1D_array,2D_array,2D_rect,3D,cube} declares the
    // sampler with a non-2D type. gluStateReset binds a default texture
    // (name 0) to every (unit, target) pair before each test, so the
    // unit always has a 2D entry. Pre-fix: a `sampler1D` lookup hit the
    // GL_TEXTURE_2D probe first and returned the default-2D texture
    // (which Metal then refused to bind to a `texture1d` slot, or
    // sampling returned zeros). Mirrors the graphics-path resolveSamplerBindings
    // sampler-type → preferredTarget mapping at line 4607+.
    auto preferredTargetForSamplerType = [](GLenum samplerGLType) -> GLenum {
        switch (samplerGLType) {
            case GL_SAMPLER_1D:
            case GL_INT_SAMPLER_1D:
            case GL_UNSIGNED_INT_SAMPLER_1D:
            case GL_SAMPLER_1D_SHADOW:
                return GL_TEXTURE_1D;
            case GL_SAMPLER_2D:
            case GL_INT_SAMPLER_2D:
            case GL_UNSIGNED_INT_SAMPLER_2D:
            case GL_SAMPLER_2D_SHADOW:
                return GL_TEXTURE_2D;
            case GL_SAMPLER_3D:
            case GL_INT_SAMPLER_3D:
            case GL_UNSIGNED_INT_SAMPLER_3D:
                return GL_TEXTURE_3D;
            case GL_SAMPLER_CUBE:
            case GL_INT_SAMPLER_CUBE:
            case GL_UNSIGNED_INT_SAMPLER_CUBE:
            case GL_SAMPLER_CUBE_SHADOW:
                return GL_TEXTURE_CUBE_MAP;
            case GL_SAMPLER_1D_ARRAY:
            case GL_INT_SAMPLER_1D_ARRAY:
            case GL_UNSIGNED_INT_SAMPLER_1D_ARRAY:
            case GL_SAMPLER_1D_ARRAY_SHADOW:
                return GL_TEXTURE_1D_ARRAY;
            case GL_SAMPLER_2D_ARRAY:
            case GL_INT_SAMPLER_2D_ARRAY:
            case GL_UNSIGNED_INT_SAMPLER_2D_ARRAY:
            case GL_SAMPLER_2D_ARRAY_SHADOW:
                return GL_TEXTURE_2D_ARRAY;
            case GL_SAMPLER_2D_RECT:
            case GL_INT_SAMPLER_2D_RECT:
            case GL_UNSIGNED_INT_SAMPLER_2D_RECT:
            case GL_SAMPLER_2D_RECT_SHADOW:
                return GL_TEXTURE_RECTANGLE;
            case GL_SAMPLER_BUFFER:
            case GL_INT_SAMPLER_BUFFER:
            case GL_UNSIGNED_INT_SAMPLER_BUFFER:
                return GL_TEXTURE_BUFFER;
            case GL_SAMPLER_CUBE_MAP_ARRAY:
            case GL_INT_SAMPLER_CUBE_MAP_ARRAY:
            case GL_UNSIGNED_INT_SAMPLER_CUBE_MAP_ARRAY:
            case GL_SAMPLER_CUBE_MAP_ARRAY_SHADOW:
                return GL_TEXTURE_CUBE_MAP_ARRAY;
            case GL_SAMPLER_2D_MULTISAMPLE:
            case GL_INT_SAMPLER_2D_MULTISAMPLE:
            case GL_UNSIGNED_INT_SAMPLER_2D_MULTISAMPLE:
                return GL_TEXTURE_2D_MULTISAMPLE;
            case GL_SAMPLER_2D_MULTISAMPLE_ARRAY:
            case GL_INT_SAMPLER_2D_MULTISAMPLE_ARRAY:
            case GL_UNSIGNED_INT_SAMPLER_2D_MULTISAMPLE_ARRAY:
                return GL_TEXTURE_2D_MULTISAMPLE_ARRAY;
            default:
                return 0;
        }
    };

    thread_local std::vector<std::uint32_t> msImageSampleCounts;
    msImageSampleCounts.assign(128, 1u);
    bool hasMSImageSampleCounts = false;
    ExtensionContext extensionContext(*this);
    const bool usesMSSampledSidecars =
        programObject->computeMSL.find("appgl_ms_sampled_sidecar_") != std::string::npos;
    const bool usesSparseSampledSidecars =
        programObject->computeMSL.find("appgl_sparse_sampled_sidecar_") != std::string::npos;
    const bool usesMSStorageSparseResidency =
        programObject->computeMSL.find("appgl_ms_storage_sparse_") != std::string::npos;

    const bool traceCompSamp = std::getenv("APPGL_TRACE_COMP_SAMP") != nullptr;
    for (const auto& samp : programObject->computeReflection.sampledTextures) {
        // Find the matching uniform to read its texture-unit value AND
        // its sampler GL type (drives preferredTarget below).
        GLint uniformLoc = -1;
        GLenum samplerGLType = 0;
        GLint samplerArraySize = 1;
        auto matchComputeSamplerUniform = [&](const std::string& name) -> bool {
            for (const auto& u : programObject->uniforms) {
                if (u.name != name) {
                    continue;
                }
                uniformLoc = u.location;
                samplerGLType = u.type;
                samplerArraySize = std::max<GLint>(u.arraySize, 1);
                return true;
            }
            return false;
        };
        if (!matchComputeSamplerUniform(samp.name)) {
            constexpr const char* kAppglPrefix = "_appgl_";
            constexpr std::size_t kAppglPrefixLen = 7;
            if (samp.name.compare(0, kAppglPrefixLen, kAppglPrefix) == 0) {
                matchComputeSamplerUniform(samp.name.substr(kAppglPrefixLen));
            }
        }
        if (uniformLoc < 0) {
            if (traceCompSamp) std::fprintf(stderr, "[CMP-SAMP] name=%s SKIP=no_uniform\n", samp.name.c_str());
            continue;
        }
        auto uvIt = programObject->uniformValues.find(uniformLoc);
        const GLProgramUniformValue* samplerValue =
            (uvIt != programObject->uniformValues.end()) ? &uvIt->second : nullptr;

        GLenum preferredTarget = preferredTargetForSamplerType(samplerGLType);

        // CKPT145 (Sprint 13 Day 9): sampler array iteration. SPIRV-Cross
        // emits a sampler array (`uniform sampler2D goku[7]`) as N
        // separate `[[texture(M+i)]]` slots. CTS shading_language_420pack.
        // binding_sampler_array binds 7 distinct textures at GL units 1..7
        // and expects each shader element `goku[i]` to read from the bound
        // texture at GL unit 1+i. Pre-fix: only goku[0] resolved (compute
        // path read `ints[0]` once); goku[1..6] unbound → wrong values.
        // Mirrors the graphics-path resolveSamplerBindings array iteration
        // at GLContext.mm:4683+.
        for (GLint arrayElement = 0; arrayElement < samplerArraySize; ++arrayElement) {
            GLuint unit = 0;
            if (samplerValue != nullptr &&
                static_cast<std::size_t>(arrayElement) < samplerValue->ints.size()) {
                unit = static_cast<GLuint>(samplerValue->ints[arrayElement]);
            }

            // Probe the sampler-type-derived target FIRST. Falls back to
            // GL_TEXTURE_2D probe + any-target if the preferred target has
            // no binding.
            GLenum discoveredTarget = preferredTarget != 0 ? preferredTarget : GL_TEXTURE_2D;
            GLuint texName = preferredTarget != 0
                ? impl_->state->boundTextureOnUnit(unit, preferredTarget) : 0;
            if (texName == 0) {
                texName = impl_->state->boundTextureOnUnit(unit, GL_TEXTURE_2D);
                if (texName != 0) discoveredTarget = GL_TEXTURE_2D;
            }
            if (texName == 0) {
                texName = impl_->state->boundTextureOnUnitAny(unit, &discoveredTarget);
            }
            if (traceCompSamp) {
                std::fprintf(stderr, "[CMP-SAMP] name=%s[%d] loc=%d type=0x%X unit=%u prefTgt=0x%X tex=%u tgt=0x%X metalSlot=%u",
                    samp.name.c_str(), arrayElement, uniformLoc, samplerGLType, unit, preferredTarget,
                    texName, discoveredTarget, samp.metalBinding + arrayElement);
            }
            if (texName == 0) {
                if (traceCompSamp) std::fprintf(stderr, " SKIP=no_texture\n");
                continue;
            }

            GLTextureObject* texObj = impl_->objects->textures().get(texName);
            if (texObj != nullptr &&
                texObj->target == GL_TEXTURE_BUFFER &&
                texObj->desc.sourceBuffer != 0) {
                (void)impl_->refreshRGB32BufferTextureView(*texObj);
            }
            if (texObj != nullptr && texObj->viewSourceTexture == 0) {
                (void)impl_->restoreR5PrimaryTextureIfNeeded(*texObj,
                                                             texName);
            }
            if (texObj == nullptr || texObj->metalTexture == nullptr) {
                if (traceCompSamp) std::fprintf(stderr, " SKIP=null_metalTexture\n");
                continue;
            }
            computeReads.push_back({Impl::GpuResourceAccess::Kind::Texture,
                                    texName, kProducerAll});
            if (texObj->target == GL_TEXTURE_BUFFER &&
                texObj->desc.sourceBuffer != 0) {
                computeReads.push_back(
                    {Impl::GpuResourceAccess::Kind::Buffer,
                     texObj->desc.sourceBuffer, kProducerAll});
            }
            void* metalSamplerState = nullptr;
            const GLuint samplerName = impl_->state->boundSampler(unit);
            if (samplerName != 0) {
                GLSamplerObject* samplerObj =
                    impl_->objects->samplers().get(samplerName);
                if (samplerObj != nullptr) {
                    if (samplerObj->dirty || samplerObj->metalSampler == nullptr) {
                        (void)impl_->rebuildSamplerState(*samplerObj);
                    }
                    metalSamplerState = samplerObj->metalSampler;
                }
            }
            if (metalSamplerState == nullptr) {
                if (texObj->samplerDirty || texObj->metalSampler == nullptr) {
                    (void)impl_->rebuildTextureSamplerState(texName, *texObj);
                }
                metalSamplerState = texObj->metalSampler;
            }

            ComputeDispatchInfo::TextureBinding tb;
            tb.metalTexture = texObj->metalTexture;
            tb.metalSamplerState = metalSamplerState;
            if (texObj->target == GL_TEXTURE_BUFFER &&
                texObj->desc.sourceBuffer != 0) {
                if (texObj->textureBufferExpandedMetalBuffer != nullptr) {
                    tb.textureBufferBackingMetalBuffer =
                        texObj->textureBufferExpandedMetalBuffer;
                } else {
                    GLBufferObject* backingBuffer =
                        impl_->objects->buffers().get(texObj->desc.sourceBuffer);
                    if (backingBuffer != nullptr) {
                        tb.textureBufferBackingMetalBuffer =
                            backingBuffer->metalBuffer;
                    }
                }
            }
            tb.metalSlot = samp.metalBinding + static_cast<std::uint32_t>(arrayElement);
            info.textures.push_back(tb);
            if (usesMSSampledSidecars &&
                extensions::sparse_texture::isMultisampleStorageImageTarget(preferredTarget)) {
                extensions::sparse_texture::MultisampleStorageImageSidecarInfo sidecarInfo;
                const std::uint32_t slot =
                    samp.metalBinding + static_cast<std::uint32_t>(arrayElement);
                if (slot >= msImageSampleCounts.size()) {
                    msImageSampleCounts.resize(static_cast<std::size_t>(slot) + 1u, 0u);
                }
                hasMSImageSampleCounts = true;
                msImageSampleCounts[slot] = 0u;
                if (extensions::sparse_texture::getMultisampleStorageImageSidecar(
                        extensionContext, *texObj, sidecarInfo)) {
                    ComputeDispatchInfo::TextureBinding sidecarBinding;
                    sidecarBinding.metalTexture = sidecarInfo.metalTexture;
                    sidecarBinding.metalSamplerState = nullptr;
                    sidecarBinding.metalSlot =
                        slot + kMultisampleSampledSidecarTextureSlotOffset;
                    info.textures.push_back(sidecarBinding);
                    msImageSampleCounts[slot] =
                        static_cast<std::uint32_t>(std::max<GLsizei>(sidecarInfo.samples, 1));
                }
            }
            const GLenum sparseSidecarTarget =
                preferredTarget != 0 ? preferredTarget : discoveredTarget;
            if (usesSparseSampledSidecars &&
                extensions::sparse_texture::isSparseStorageImageSidecarTarget(
                    sparseSidecarTarget)) {
                extensions::sparse_texture::SparseStorageImageSidecarInfo sidecarInfo;
                const auto sparseRoute =
                    extensions::sparse_texture::resolveSparseStorageImageSidecarBinding(
                        extensionContext, *texObj, sparseSidecarTarget, &sidecarInfo);
                const std::uint32_t slot =
                    samp.metalBinding + static_cast<std::uint32_t>(arrayElement);
                ComputeDispatchInfo::TextureBinding sidecarBinding;
                sidecarBinding.metalSamplerState = nullptr;
                sidecarBinding.metalSlot =
                    slot + kMultisampleSampledSidecarTextureSlotOffset;
                sidecarBinding.metalTexture =
                    sparseRoute ==
                            extensions::sparse_texture::SparseStorageImageBindingRoute::SidecarTexture
                        ? sidecarInfo.metalTexture
                        : texObj->metalTexture;
                if (sidecarBinding.metalTexture != nullptr) {
                    info.textures.push_back(sidecarBinding);
                }
            }
            if (traceCompSamp) std::fprintf(stderr, " BOUND\n");
        }
    }

    // Storage images (imageLoad/imageStore). Bound via
    // glBindImageTexture(unit, …) rather than a sampler uniform. The
    // shader's `layout(binding=N)` is the DEFAULT image unit; GL 4.6
    // §7.6 allows glUniform1i(loc, K) to change the effective image
    // unit to K at runtime (same mechanism as sampler uniforms). CTS
    // shading_language_420pack.binding_images_* relies on this — only
    // one of the three images has an explicit layout binding, and the
    // others rely on glUniform1i to set the unit.
    for (const auto& img : programObject->computeReflection.storageImages) {
        // CKPT145 (Sprint 13 Day 9): storage image array iteration. SPIRV-
        // Cross emits an image array (`uniform image2D goku[7]`) as N
        // separate `[[texture(M+i)]]` slots. Pre-fix: only goku[0] resolved;
        // goku[1..N-1] unbound → wrong values. CTS shading_language_420pack.
        // binding_image_array exercises this with 7 elements.
        // Look up the matching uniform to read array size + per-element
        // uniform-value (glUniform1i overrides).
        GLint imageArraySize = 1;
        const GLProgramUniformValue* imageValue = nullptr;
        for (const auto& u : programObject->uniforms) {
            if (u.name == img.name) {
                imageArraySize = std::max<GLint>(u.arraySize, 1);
                auto uvIt = programObject->uniformValues.find(u.location);
                if (uvIt != programObject->uniformValues.end()) {
                    imageValue = &uvIt->second;
                }
                break;
            }
        }
        for (GLint arrayElement = 0; arrayElement < imageArraySize; ++arrayElement) {
            // GL 4.6 §7.6: per-element effective unit. Default is
            // glBinding+arrayElement (consecutive layout). Override per
            // element via glUniform1i(loc[i], K).
            GLuint effectiveUnit = img.glBinding + static_cast<GLuint>(arrayElement);
            if (imageValue != nullptr &&
                static_cast<std::size_t>(arrayElement) < imageValue->ints.size()) {
                effectiveUnit = static_cast<GLuint>(imageValue->ints[arrayElement]);
            }
            if (effectiveUnit >= Impl::kMaxImageUnits) continue;
            auto& ib = impl_->imageBindings[effectiveUnit];
            if (ib.texture == 0) continue;
            GLTextureObject* texObj = impl_->objects->textures().get(ib.texture);
            if (texObj != nullptr && texObj->viewSourceTexture == 0) {
                (void)impl_->restoreR5PrimaryTextureIfNeeded(*texObj,
                                                             ib.texture);
            }
            if (texObj == nullptr || texObj->metalTexture == nullptr) continue;
            if (!impl_->imageBindingLevelAvailable(ib, texObj)) continue;
            const bool textureBufferImage =
                texObj->target == GL_TEXTURE_BUFFER &&
                texObj->desc.sourceBuffer != 0;
            if (ib.access != GL_WRITE_ONLY) {
                computeReads.push_back({Impl::GpuResourceAccess::Kind::Texture,
                                        ib.texture, kProducerAll});
                if (textureBufferImage) {
                    computeReads.push_back({Impl::GpuResourceAccess::Kind::Buffer,
                                            texObj->desc.sourceBuffer,
                                            kProducerAll});
                }
            }
            if (ib.access != GL_READ_ONLY) {
                computeWrites.push_back(
                    {Impl::GpuResourceAccess::Kind::Texture,
                     ib.texture,
                     kProducerComputeWrite | kProducerStorageImageWrite});
                if (textureBufferImage) {
                    computeWrites.push_back(
                        {Impl::GpuResourceAccess::Kind::Buffer,
                         texObj->desc.sourceBuffer,
                         kProducerComputeWrite | kProducerStorageImageWrite});
                }
            }
            ComputeDispatchInfo::TextureBinding tb;
            if (img.multisampleStorageImage) {
                extensions::sparse_texture::MultisampleStorageImageSidecarInfo sidecarInfo;
                if (!extensions::sparse_texture::ensureMultisampleStorageImageSidecar(
                        extensionContext, *texObj, &sidecarInfo)) {
                    continue;
                }
                tb.metalTexture = sidecarInfo.metalTexture;
                const std::uint32_t slot =
                    img.metalBinding + static_cast<std::uint32_t>(arrayElement);
                if (slot >= msImageSampleCounts.size()) {
                    msImageSampleCounts.resize(static_cast<std::size_t>(slot) + 1u, 1u);
                }
                msImageSampleCounts[slot] =
                    static_cast<std::uint32_t>(std::max<GLsizei>(sidecarInfo.samples, 1));
                hasMSImageSampleCounts = true;
                if (usesMSStorageSparseResidency && texObj->metalTexture != nullptr) {
                    ComputeDispatchInfo::TextureBinding sparseResidencyBinding;
                    sparseResidencyBinding.metalTexture = texObj->metalTexture;
                    sparseResidencyBinding.metalSamplerState = nullptr;
                    sparseResidencyBinding.metalSlot =
                        slot + kMultisampleStorageSparseResidencyTextureSlotOffset;
                    info.textures.push_back(sparseResidencyBinding);
                }
            } else {
                extensions::sparse_texture::SparseStorageImageSidecarInfo sidecarInfo;
                const bool sparseWritableBound =
                    extensions::sparse_texture::textureSparse(extensionContext, texObj) == GL_TRUE &&
                    extensions::sparse_texture::isSparseStorageImageSidecarTarget(img.storageImageTarget) &&
                    texObj->target == img.storageImageTarget &&
                    ib.access != GL_READ_ONLY;
                const bool sparseSidecarAccess =
                    img.sparseStorageImageWrite || sparseWritableBound;
                const auto sparseRoute = sparseSidecarAccess
                    ? extensions::sparse_texture::resolveSparseStorageImageSidecarBinding(
                          extensionContext, *texObj, img.storageImageTarget, &sidecarInfo)
                    : extensions::sparse_texture::SparseStorageImageBindingRoute::NativeTexture;
                if (sparseRoute ==
                    extensions::sparse_texture::SparseStorageImageBindingRoute::SidecarTexture) {
                    tb.metalTexture =
                        impl_->resolveSparseSidecarImageMetalTexture(
                            ib, texObj, sidecarInfo);
                } else if (sparseRoute ==
                           extensions::sparse_texture::SparseStorageImageBindingRoute::SparseSidecarUnavailable) {
                    continue;
                } else {
                    if (ib.access != GL_READ_ONLY) {
                        (void)extensions::sparse_texture::ensureSparseStorageImageSidecar(
                            extensionContext, *texObj);
                    }
                    // CKPT119: level-restricted view when ib.level > 0.
                    tb.metalTexture = impl_->resolveImageMetalTexture(
                        ib, texObj, img.storageImageTarget);
                }
            }
            tb.metalSamplerState = nullptr;  // no sampler for storage images
            tb.metalSlot = img.metalBinding + static_cast<std::uint32_t>(arrayElement);
            if (img.metalAtomicBufferBinding != 0xFFFFFFFFu) {
                const std::string atomicNeedle = img.name + "_atomic";
                const bool usesImageAtomic =
                    programObject->computeMSL.find(atomicNeedle) != std::string::npos ||
                    programObject->computeMSL.find("_appgl_" + atomicNeedle) !=
                        std::string::npos;
                if (usesImageAtomic) {
                    tb.imageAtomicBufferSlot =
                        img.metalAtomicBufferBinding +
                        static_cast<std::uint32_t>(arrayElement);
                    if (texObj->target == GL_TEXTURE_BUFFER &&
                        texObj->desc.sourceBuffer != 0) {
                        GLBufferObject* backingBuffer =
                            impl_->objects->buffers().get(texObj->desc.sourceBuffer);
                        if (backingBuffer != nullptr &&
                            backingBuffer->metalBuffer != nullptr) {
                            tb.imageAtomicMetalBuffer =
                                backingBuffer->metalBuffer;
                            tb.imageAtomicBufferOffset =
                                static_cast<std::size_t>(
                                    std::max<GLintptr>(
                                        texObj->desc.bufferOffset, 0));
                        }
                    } else {
                        tb.imageAtomicMetalBuffer =
                            impl_->ensureTextureImageAtomicBuffer(*texObj);
                        tb.imageAtomicBufferOffset = 0;
                        if (tb.imageAtomicMetalBuffer != nullptr &&
                            ib.access != GL_READ_ONLY) {
                            texObj->imageAtomicBufferDirtyToTexture = true;
                        }
                    }
                }
            }
            info.textures.push_back(tb);
        }
    }
    if (hasMSImageSampleCounts) {
        info.multisampleStorageImageSampleCounts = msImageSampleCounts.data();
        info.multisampleStorageImageSampleCountBytes =
            msImageSampleCounts.size() * sizeof(std::uint32_t);
        info.multisampleStorageImageSampleCountSlot =
            multisampleStorageImageSampleCountSlotForMSL(programObject->computeMSL);
    }

    impl_->declareComputeDispatchSubmissionGroup(info, computeReads, computeWrites);
    impl_->drainPendingGpuProducers(computeReads);
    const bool encoded = impl_->frameGraph->encodeComputeDispatch(info);
    if (encoded) {
        impl_->markGpuResourceWrites(computeWrites);
        for (const auto& sync : fp64SsboSidecars) {
            if (sync.buffer != nullptr && sync.binding != nullptr &&
                sync.sidecar != nullptr) {
                impl_->syncFp64TransportSidecarBack(
                    *sync.buffer, *sync.binding, *sync.sidecar);
            }
        }
    }
    return true;
}

bool GLContext::dispatchComputeIndirect(GLintptr indirect) {
    if (indirect < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if ((indirect % 4) != 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }

    // GL 4.6 §17.2: GL_INVALID_OPERATION when no active compute program
    // (matches dispatchCompute's spec-correct check below). Without
    // this, the compute_shader.api-indirect / api-no-active-program
    // negative tests see GL_NO_ERROR and fail.
    const GLuint progName = impl_->state->currentProgram();
    GLProgramObject* programObject = progName == 0 ? nullptr
        : impl_->objects->programs().get(progName);
    if (programObject == nullptr || !programObject->linked
        || programObject->metalComputePipelineState == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }

    // GL 4.6 §17.2: also INVALID_OPERATION when no buffer is bound
    // to the GL_DISPATCH_INDIRECT_BUFFER target, or when the command
    // would read past the end of the bound buffer.
    const GLuint dispatchBufName = impl_->state->boundBuffer(GL_DISPATCH_INDIRECT_BUFFER);
    if (dispatchBufName == 0) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    const GLBufferObject* dispatchBuf = impl_->objects->buffers().get(dispatchBufName);
    if (dispatchBuf == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // Three GLuints (x, y, z work-group counts) at `indirect`.
    constexpr GLsizeiptr kIndirectDispatchSize = 3 * sizeof(GLuint);
    if (indirect > dispatchBuf->size
        || kIndirectDispatchSize > dispatchBuf->size - indirect) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }

    // GL 4.6 §2.3.3 — conditional render predicate. Skipped dispatches
    // do not advance query counters or update shader-visible storage.
    if (impl_->shouldSkipDrawForConditionalRender()) {
        return true;
    }
    impl_->touchR5Residency(MetalR5ResidencyTouchKind::Dispatch);

    // GL 4.6 §22.4 — credit COMPUTE_SHADER_INVOCATIONS for every
    // active query, mirroring the direct-dispatch path above. The
    // indirect buffer is CPU-mapped on Apple silicon so we can read
    // the (x, y, z) groups for a real count; if that read fails we
    // fall back to local-size × 1-group to satisfy EQUAL_OR_GREATER.
    // CTS `pipeline_statistics_query_tests_ARB.functional_compute_
    // shader_invocations` runs the query over dispatchCompute +
    // dispatchComputeIndirect and expects result >= 1 on both.
    {
        GLuint64 groups = 0;
        if (dispatchBuf->metalBuffer != nullptr) {
            id<MTLBuffer> mtl = (__bridge id<MTLBuffer>)dispatchBuf->metalBuffer;
            const void* ptr = [mtl contents];
            if (ptr != nullptr) {
                const GLuint* args = reinterpret_cast<const GLuint*>(
                    reinterpret_cast<const std::uint8_t*>(ptr) +
                    static_cast<std::size_t>(indirect));
                groups = static_cast<GLuint64>(args[0]) *
                         static_cast<GLuint64>(args[1]) *
                         static_cast<GLuint64>(args[2]);
            }
        }
        if (groups == 0) groups = 1;
        const GLuint64 local = static_cast<GLuint64>(programObject->computeLocalSizeX) *
                               static_cast<GLuint64>(programObject->computeLocalSizeY) *
                               static_cast<GLuint64>(programObject->computeLocalSizeZ);
        const GLuint64 invocations = groups * (local == 0 ? 1 : local);
        impl_->objects->queries().forEach([&](GLuint /*id*/, GLQueryObject& q) {
            if (!q.active || q.target != GL_COMPUTE_SHADER_INVOCATIONS) return;
            q.result += invocations;
        });
    }

    // Route the indirect dispatch through the same encoder as the
    // direct path. Metal reads the (groupsX, groupsY, groupsZ) triple
    // out of the buffer at dispatch time via
    // dispatchThreadgroupsWithIndirectBuffer — we just hand it the
    // MTLBuffer + offset.
    if (impl_->frameGraph == nullptr) {
        return true;  // teardown — silently no-op, same as direct path
    }
    ComputeDispatchInfo info;
    info.metalComputePipelineState = programObject->metalComputePipelineState;
    info.metalComputeFunction = programObject->metalComputeFunction;
    info.needsSSBOSizeBuffer =
        programObject->computeMSL.find("spvBufferSizeConstants") != std::string::npos;
    info.localX = programObject->computeLocalSizeX;
    info.localY = programObject->computeLocalSizeY;
    info.localZ = programObject->computeLocalSizeZ;
    info.indirectBuffer = dispatchBuf->metalBuffer;
    info.indirectOffset = static_cast<std::size_t>(indirect);
    struct Fp64IndirectSidecarSync {
        GLBufferObject* buffer = nullptr;
        const ShaderReflection::ResourceBinding* binding = nullptr;
        GLBufferObject::Fp64TransportSidecar* sidecar = nullptr;
    };
    std::vector<Fp64IndirectSidecarSync> fp64SsboSidecars;
    GLContext::Impl::GpuResourceReadSet computeReads;
    GLContext::Impl::GpuResourceWriteSet computeWrites;
    computeReads.push_back({Impl::GpuResourceAccess::Kind::Buffer,
                            dispatchBufName, kProducerAll});

    // Same resource plumbing as the direct dispatch path: SSBOs, UBOs,
    // default-uniform push constants, sampled textures. Keep in sync
    // with GLContext::dispatchCompute.
    for (const auto& ssbo : programObject->computeReflection.storageBuffers) {
        GLuint effectiveBinding = ssbo.glBinding;
        for (const auto& rb : programObject->resourceStorageBlocks) {
            if (rb.name == ssbo.name && rb.location >= 0) {
                effectiveBinding = static_cast<GLuint>(rb.location);
                break;
            }
        }
        const int numInstances = (ssbo.blockArraySize > 0)
            ? static_cast<int>(ssbo.blockArraySize) : 1;
        const bool isArray = (ssbo.blockArraySize > 0);
        for (int inst = 0; inst < numInstances; ++inst) {
            std::string lookupName = ssbo.name;
            if (isArray) lookupName += "[" + std::to_string(inst) + "]";
            GLuint glBindingPoint = effectiveBinding + static_cast<GLuint>(inst);
            for (const auto& rb : programObject->resourceStorageBlocks) {
                if (rb.name == lookupName && rb.location >= 0) {
                    glBindingPoint = static_cast<GLuint>(rb.location);
                    break;
                }
            }
            const GLIndexedBufferBinding binding = impl_->state->indexedBufferBinding(
                GL_SHADER_STORAGE_BUFFER, glBindingPoint);
            if (binding.buffer == 0) continue;
            GLBufferObject* bufObj = impl_->objects->buffers().get(binding.buffer);
            if (bufObj == nullptr || bufObj->metalBuffer == nullptr) continue;
            computeReads.push_back({Impl::GpuResourceAccess::Kind::Buffer,
                                    binding.buffer, kProducerAll});
            computeWrites.push_back({Impl::GpuResourceAccess::Kind::Buffer,
                                     binding.buffer,
                                     kProducerComputeWrite |
                                         kProducerShaderStorageWrite});
            ComputeDispatchInfo::BufferBinding bb;
            bb.metalBuffer = bufObj->metalBuffer;
            bb.offset = static_cast<std::size_t>(binding.offset);
            if (binding.size > 0) {
                bb.size = static_cast<std::size_t>(binding.size);
            } else if (binding.offset >= 0 && bufObj->size > binding.offset) {
                bb.size = static_cast<std::size_t>(bufObj->size - binding.offset);
            }
            bb.metalSlot = ssbo.metalBinding + static_cast<std::uint32_t>(inst);
            if (resourceNeedsFp64BindingShim(programObject->computeReflection, ssbo)) {
                auto* sidecar = impl_->ensureFp64TransportSidecar(
                    *bufObj, programObject->computeReflection, ssbo,
                    static_cast<GLintptr>(binding.offset),
                    static_cast<GLsizeiptr>(bb.size));
                if (sidecar != nullptr && sidecar->metalBuffer != nullptr) {
                    bb.metalBuffer = sidecar->metalBuffer;
                    bb.offset = 0;
                    fp64SsboSidecars.push_back({bufObj, &ssbo, sidecar});
                    ExtensionContext extensionContext(*this);
                    extensions::fp64::recordDoubleSsboBacking(
                        extensionContext, bb.size);
                }
            }
            info.buffers.push_back(bb);
        }
    }
    // CKPT143 (Sprint 13 Day 7): UBO array support — see direct-dispatch
    // path above for full rationale. Mirror here for dispatchComputeIndirect.
    for (const auto& ubo : programObject->computeReflection.uniformBlocks) {
        if (ubo.name == "_DefaultUniforms") continue;
        const int numInstances = (ubo.blockArraySize > 0)
            ? static_cast<int>(ubo.blockArraySize) : 1;
        const bool isArray = (ubo.blockArraySize > 0);
        for (int inst = 0; inst < numInstances; ++inst) {
            std::string lookupName = ubo.name;
            if (isArray) {
                lookupName += "[" + std::to_string(inst) + "]";
            }
            GLuint glBindingPoint = ubo.glBinding + static_cast<GLuint>(inst);
            for (std::size_t bi = 0; bi < programObject->resourceUniformBlocks.size(); ++bi) {
                if (programObject->resourceUniformBlocks[bi].name == lookupName) {
                    GLint bp = programObject->resourceUniformBlocks[bi].location;
                    if (bp >= 0) {
                        glBindingPoint = static_cast<GLuint>(bp);
                    }
                    break;
                }
            }
            const GLIndexedBufferBinding binding = impl_->state->indexedBufferBinding(
                GL_UNIFORM_BUFFER, glBindingPoint);
            if (binding.buffer == 0) continue;
            GLBufferObject* bufObj = impl_->objects->buffers().get(binding.buffer);
            if (bufObj == nullptr || bufObj->metalBuffer == nullptr) continue;
            computeReads.push_back({Impl::GpuResourceAccess::Kind::Buffer,
                                    binding.buffer, kProducerAll});
            ComputeDispatchInfo::BufferBinding bb;
            bb.metalBuffer = bufObj->metalBuffer;
            bb.offset = static_cast<std::size_t>(binding.offset);
            bb.metalSlot = ubo.metalBinding + static_cast<std::uint32_t>(inst);
            bb.descriptorSet = 1;
            if (resourceNeedsFp64BindingShim(programObject->computeReflection, ubo)) {
                GLsizeiptr rangeSize = binding.size;
                if (rangeSize <= 0 && binding.offset >= 0 && bufObj->size > binding.offset) {
                    rangeSize = bufObj->size - binding.offset;
                }
                auto* sidecar = impl_->ensureFp64TransportSidecar(
                    *bufObj, programObject->computeReflection, ubo,
                    static_cast<GLintptr>(binding.offset), rangeSize);
                if (sidecar != nullptr && sidecar->metalBuffer != nullptr) {
                    bb.metalBuffer = sidecar->metalBuffer;
                    bb.offset = 0;
                    ExtensionContext extensionContext(*this);
                    extensions::fp64::recordDoubleUniformBacking(
                        extensionContext, static_cast<std::size_t>(rangeSize));
                }
            }
            info.buffers.push_back(bb);
        }
    }
    for (const auto& ac : programObject->resourceAtomicCounterBuffers) {
        if (ac.binding < 0) continue;
        const GLuint glBinding = static_cast<GLuint>(ac.binding);
        const GLIndexedBufferBinding binding = impl_->state->indexedBufferBinding(
            GL_ATOMIC_COUNTER_BUFFER, glBinding);
        if (binding.buffer == 0) continue;
        const GLBufferObject* bufObj = impl_->objects->buffers().get(binding.buffer);
        if (bufObj == nullptr || bufObj->metalBuffer == nullptr) continue;
        computeReads.push_back({Impl::GpuResourceAccess::Kind::Buffer,
                                binding.buffer, kProducerAll});
        computeWrites.push_back({Impl::GpuResourceAccess::Kind::Buffer,
                                 binding.buffer,
                                 kProducerComputeWrite |
                                     kProducerAtomicCounterWrite});

        ComputeDispatchInfo::BufferBinding bb;
        bb.metalBuffer = bufObj->metalBuffer;
        bb.offset = static_cast<std::size_t>(binding.offset);
        bb.metalSlot = computeAtomicCounterMetalSlot(glBinding);
        info.buffers.push_back(bb);
    }
    thread_local std::vector<std::uint8_t> computeUniformScratchIndirect;
    if (!programObject->uniformLayoutComputed
        || programObject->computeUniformLayout.empty()) {
        computeStageUniformLayout(programObject->computeUniformLayout,
            programObject->computeReflection, programObject->uniforms);
        programObject->uniformLayoutComputed = true;
    }
    if (pushSynthesizedMatrixUniforms(*programObject, impl_->matrixState)) {
        programObject->markUniformsDirty();
    }
    buildStageUniformBuffer(computeUniformScratchIndirect,
        programObject->computeReflection, programObject->uniformValues,
        programObject->computeUniformLayout);
    if (!computeUniformScratchIndirect.empty()) {
        info.computeUniformData = computeUniformScratchIndirect.data();
        info.computeUniformSize = computeUniformScratchIndirect.size();
        if (reflectionNeedsFp64BindingShim(programObject->computeReflection) &&
            defaultUniformBlockContainsFp64(programObject->computeReflection)) {
            ExtensionContext extensionContext(*this);
            extensions::fp64::recordDoubleUniformBacking(
                extensionContext, info.computeUniformSize);
        }
    }
    // CKPT144 (Sprint 13 Day 8): sampler-type-aware target lookup —
    // see direct-dispatch path above for full rationale. Indirect mirror.
    auto preferredTargetForSamplerType2 = [](GLenum samplerGLType) -> GLenum {
        switch (samplerGLType) {
            case GL_SAMPLER_1D: case GL_INT_SAMPLER_1D: case GL_UNSIGNED_INT_SAMPLER_1D:
            case GL_SAMPLER_1D_SHADOW: return GL_TEXTURE_1D;
            case GL_SAMPLER_2D: case GL_INT_SAMPLER_2D: case GL_UNSIGNED_INT_SAMPLER_2D:
            case GL_SAMPLER_2D_SHADOW: return GL_TEXTURE_2D;
            case GL_SAMPLER_3D: case GL_INT_SAMPLER_3D: case GL_UNSIGNED_INT_SAMPLER_3D:
                return GL_TEXTURE_3D;
            case GL_SAMPLER_CUBE: case GL_INT_SAMPLER_CUBE: case GL_UNSIGNED_INT_SAMPLER_CUBE:
            case GL_SAMPLER_CUBE_SHADOW: return GL_TEXTURE_CUBE_MAP;
            case GL_SAMPLER_1D_ARRAY: case GL_INT_SAMPLER_1D_ARRAY:
            case GL_UNSIGNED_INT_SAMPLER_1D_ARRAY: case GL_SAMPLER_1D_ARRAY_SHADOW:
                return GL_TEXTURE_1D_ARRAY;
            case GL_SAMPLER_2D_ARRAY: case GL_INT_SAMPLER_2D_ARRAY:
            case GL_UNSIGNED_INT_SAMPLER_2D_ARRAY: case GL_SAMPLER_2D_ARRAY_SHADOW:
                return GL_TEXTURE_2D_ARRAY;
            case GL_SAMPLER_2D_RECT: case GL_INT_SAMPLER_2D_RECT:
            case GL_UNSIGNED_INT_SAMPLER_2D_RECT: case GL_SAMPLER_2D_RECT_SHADOW:
                return GL_TEXTURE_RECTANGLE;
            case GL_SAMPLER_BUFFER: case GL_INT_SAMPLER_BUFFER:
            case GL_UNSIGNED_INT_SAMPLER_BUFFER: return GL_TEXTURE_BUFFER;
            case GL_SAMPLER_CUBE_MAP_ARRAY: case GL_INT_SAMPLER_CUBE_MAP_ARRAY:
            case GL_UNSIGNED_INT_SAMPLER_CUBE_MAP_ARRAY: case GL_SAMPLER_CUBE_MAP_ARRAY_SHADOW:
                return GL_TEXTURE_CUBE_MAP_ARRAY;
            case GL_SAMPLER_2D_MULTISAMPLE: case GL_INT_SAMPLER_2D_MULTISAMPLE:
            case GL_UNSIGNED_INT_SAMPLER_2D_MULTISAMPLE: return GL_TEXTURE_2D_MULTISAMPLE;
            case GL_SAMPLER_2D_MULTISAMPLE_ARRAY: case GL_INT_SAMPLER_2D_MULTISAMPLE_ARRAY:
            case GL_UNSIGNED_INT_SAMPLER_2D_MULTISAMPLE_ARRAY:
                return GL_TEXTURE_2D_MULTISAMPLE_ARRAY;
            default: return 0;
        }
    };
    thread_local std::vector<std::uint32_t> msImageSampleCountsIndirect;
    msImageSampleCountsIndirect.assign(128, 1u);
    bool hasMSImageSampleCountsIndirect = false;
    ExtensionContext extensionContext(*this);
    const bool usesMSSampledSidecarsIndirect =
        programObject->computeMSL.find("appgl_ms_sampled_sidecar_") != std::string::npos;
    const bool usesSparseSampledSidecarsIndirect =
        programObject->computeMSL.find("appgl_sparse_sampled_sidecar_") != std::string::npos;
    const bool usesMSStorageSparseResidencyIndirect =
        programObject->computeMSL.find("appgl_ms_storage_sparse_") != std::string::npos;

    // CKPT145 (Sprint 13 Day 9): sampler array iteration — see direct
    // dispatch path for full rationale. Indirect mirror.
    for (const auto& samp : programObject->computeReflection.sampledTextures) {
        GLint uniformLoc = -1;
        GLenum samplerGLType = 0;
        GLint samplerArraySize = 1;
        for (const auto& u : programObject->uniforms) {
            if (u.name == samp.name) {
                uniformLoc = u.location;
                samplerGLType = u.type;
                samplerArraySize = std::max<GLint>(u.arraySize, 1);
                break;
            }
        }
        if (uniformLoc < 0) continue;
        auto uvIt = programObject->uniformValues.find(uniformLoc);
        const GLProgramUniformValue* samplerValue =
            (uvIt != programObject->uniformValues.end()) ? &uvIt->second : nullptr;
        GLenum preferredTarget = preferredTargetForSamplerType2(samplerGLType);
        for (GLint arrayElement = 0; arrayElement < samplerArraySize; ++arrayElement) {
            GLuint unit = 0;
            if (samplerValue != nullptr &&
                static_cast<std::size_t>(arrayElement) < samplerValue->ints.size()) {
                unit = static_cast<GLuint>(samplerValue->ints[arrayElement]);
            }
            GLenum discoveredTarget = preferredTarget != 0 ? preferredTarget : GL_TEXTURE_2D;
            GLuint texName = preferredTarget != 0
                ? impl_->state->boundTextureOnUnit(unit, preferredTarget) : 0;
            if (texName == 0) {
                texName = impl_->state->boundTextureOnUnit(unit, GL_TEXTURE_2D);
                if (texName != 0) discoveredTarget = GL_TEXTURE_2D;
            }
            if (texName == 0) {
                texName = impl_->state->boundTextureOnUnitAny(unit, &discoveredTarget);
            }
            if (texName == 0) continue;
            GLTextureObject* texObj = impl_->objects->textures().get(texName);
            if (texObj != nullptr &&
                texObj->target == GL_TEXTURE_BUFFER &&
                texObj->desc.sourceBuffer != 0) {
                (void)impl_->refreshRGB32BufferTextureView(*texObj);
            }
            if (texObj != nullptr && texObj->viewSourceTexture == 0) {
                (void)impl_->restoreR5PrimaryTextureIfNeeded(*texObj,
                                                             texName);
            }
            if (texObj == nullptr || texObj->metalTexture == nullptr) continue;
            computeReads.push_back({Impl::GpuResourceAccess::Kind::Texture,
                                    texName, kProducerAll});
            if (texObj->target == GL_TEXTURE_BUFFER &&
                texObj->desc.sourceBuffer != 0) {
                computeReads.push_back(
                    {Impl::GpuResourceAccess::Kind::Buffer,
                     texObj->desc.sourceBuffer, kProducerAll});
            }
            if (texObj->samplerDirty) {
                impl_->rebuildTextureSamplerState(texName, *texObj);
            }
            ComputeDispatchInfo::TextureBinding tb;
            tb.metalTexture = texObj->metalTexture;
            tb.metalSamplerState = texObj->metalSampler;
            if (texObj->target == GL_TEXTURE_BUFFER &&
                texObj->desc.sourceBuffer != 0) {
                if (texObj->textureBufferExpandedMetalBuffer != nullptr) {
                    tb.textureBufferBackingMetalBuffer =
                        texObj->textureBufferExpandedMetalBuffer;
                } else {
                    GLBufferObject* backingBuffer =
                        impl_->objects->buffers().get(texObj->desc.sourceBuffer);
                    if (backingBuffer != nullptr) {
                        tb.textureBufferBackingMetalBuffer =
                            backingBuffer->metalBuffer;
                    }
                }
            }
            tb.metalSlot = samp.metalBinding + static_cast<std::uint32_t>(arrayElement);
            info.textures.push_back(tb);
            if (usesMSSampledSidecarsIndirect &&
                extensions::sparse_texture::isMultisampleStorageImageTarget(preferredTarget)) {
                extensions::sparse_texture::MultisampleStorageImageSidecarInfo sidecarInfo;
                const std::uint32_t slot =
                    samp.metalBinding + static_cast<std::uint32_t>(arrayElement);
                if (slot >= msImageSampleCountsIndirect.size()) {
                    msImageSampleCountsIndirect.resize(
                        static_cast<std::size_t>(slot) + 1u, 0u);
                }
                hasMSImageSampleCountsIndirect = true;
                msImageSampleCountsIndirect[slot] = 0u;
                if (extensions::sparse_texture::getMultisampleStorageImageSidecar(
                        extensionContext, *texObj, sidecarInfo)) {
                    ComputeDispatchInfo::TextureBinding sidecarBinding;
                    sidecarBinding.metalTexture = sidecarInfo.metalTexture;
                    sidecarBinding.metalSamplerState = nullptr;
                    sidecarBinding.metalSlot =
                        slot + kMultisampleSampledSidecarTextureSlotOffset;
                    info.textures.push_back(sidecarBinding);
                    msImageSampleCountsIndirect[slot] =
                        static_cast<std::uint32_t>(std::max<GLsizei>(sidecarInfo.samples, 1));
                }
            }
            const GLenum sparseSidecarTarget =
                preferredTarget != 0 ? preferredTarget : discoveredTarget;
            if (usesSparseSampledSidecarsIndirect &&
                extensions::sparse_texture::isSparseStorageImageSidecarTarget(
                    sparseSidecarTarget)) {
                extensions::sparse_texture::SparseStorageImageSidecarInfo sidecarInfo;
                const auto sparseRoute =
                    extensions::sparse_texture::resolveSparseStorageImageSidecarBinding(
                        extensionContext, *texObj, sparseSidecarTarget, &sidecarInfo);
                const std::uint32_t slot =
                    samp.metalBinding + static_cast<std::uint32_t>(arrayElement);
                ComputeDispatchInfo::TextureBinding sidecarBinding;
                sidecarBinding.metalSamplerState = nullptr;
                sidecarBinding.metalSlot =
                    slot + kMultisampleSampledSidecarTextureSlotOffset;
                sidecarBinding.metalTexture =
                    sparseRoute ==
                            extensions::sparse_texture::SparseStorageImageBindingRoute::SidecarTexture
                        ? sidecarInfo.metalTexture
                        : texObj->metalTexture;
                if (sidecarBinding.metalTexture != nullptr) {
                    info.textures.push_back(sidecarBinding);
                }
            }
        }
    }
    // Storage images for the indirect path — mirror the direct path.
    for (const auto& img : programObject->computeReflection.storageImages) {
        GLint imageArraySize = 1;
        const GLProgramUniformValue* imageValue = nullptr;
        for (const auto& u : programObject->uniforms) {
            if (u.name == img.name) {
                imageArraySize = std::max<GLint>(u.arraySize, 1);
                auto uvIt = programObject->uniformValues.find(u.location);
                if (uvIt != programObject->uniformValues.end()) {
                    imageValue = &uvIt->second;
                }
                break;
            }
        }
        for (GLint arrayElement = 0; arrayElement < imageArraySize; ++arrayElement) {
            GLuint effectiveUnit = img.glBinding + static_cast<GLuint>(arrayElement);
            if (imageValue != nullptr &&
                static_cast<std::size_t>(arrayElement) < imageValue->ints.size()) {
                effectiveUnit = static_cast<GLuint>(imageValue->ints[arrayElement]);
            }
            if (effectiveUnit >= Impl::kMaxImageUnits) continue;
            auto& ib = impl_->imageBindings[effectiveUnit];
            if (ib.texture == 0) continue;
            GLTextureObject* texObj = impl_->objects->textures().get(ib.texture);
            if (texObj != nullptr && texObj->viewSourceTexture == 0) {
                (void)impl_->restoreR5PrimaryTextureIfNeeded(*texObj,
                                                             ib.texture);
            }
            if (texObj == nullptr || texObj->metalTexture == nullptr) continue;
            if (!impl_->imageBindingLevelAvailable(ib, texObj)) continue;
            const bool textureBufferImage =
                texObj->target == GL_TEXTURE_BUFFER &&
                texObj->desc.sourceBuffer != 0;
            if (ib.access != GL_WRITE_ONLY) {
                computeReads.push_back({Impl::GpuResourceAccess::Kind::Texture,
                                        ib.texture, kProducerAll});
                if (textureBufferImage) {
                    computeReads.push_back({Impl::GpuResourceAccess::Kind::Buffer,
                                            texObj->desc.sourceBuffer,
                                            kProducerAll});
                }
            }
            if (ib.access != GL_READ_ONLY) {
                computeWrites.push_back(
                    {Impl::GpuResourceAccess::Kind::Texture,
                     ib.texture,
                     kProducerComputeWrite | kProducerStorageImageWrite});
                if (textureBufferImage) {
                    computeWrites.push_back(
                        {Impl::GpuResourceAccess::Kind::Buffer,
                         texObj->desc.sourceBuffer,
                         kProducerComputeWrite | kProducerStorageImageWrite});
                }
            }
            ComputeDispatchInfo::TextureBinding tb;
            if (img.multisampleStorageImage) {
                extensions::sparse_texture::MultisampleStorageImageSidecarInfo sidecarInfo;
                if (!extensions::sparse_texture::ensureMultisampleStorageImageSidecar(
                        extensionContext, *texObj, &sidecarInfo)) {
                    continue;
                }
                tb.metalTexture = sidecarInfo.metalTexture;
                const std::uint32_t slot =
                    img.metalBinding + static_cast<std::uint32_t>(arrayElement);
                if (slot >= msImageSampleCountsIndirect.size()) {
                    msImageSampleCountsIndirect.resize(
                        static_cast<std::size_t>(slot) + 1u, 1u);
                }
                msImageSampleCountsIndirect[slot] =
                    static_cast<std::uint32_t>(std::max<GLsizei>(sidecarInfo.samples, 1));
                hasMSImageSampleCountsIndirect = true;
                if (usesMSStorageSparseResidencyIndirect && texObj->metalTexture != nullptr) {
                    ComputeDispatchInfo::TextureBinding sparseResidencyBinding;
                    sparseResidencyBinding.metalTexture = texObj->metalTexture;
                    sparseResidencyBinding.metalSamplerState = nullptr;
                    sparseResidencyBinding.metalSlot =
                        slot + kMultisampleStorageSparseResidencyTextureSlotOffset;
                    info.textures.push_back(sparseResidencyBinding);
                }
            } else {
                extensions::sparse_texture::SparseStorageImageSidecarInfo sidecarInfo;
                const bool sparseWritableBound =
                    extensions::sparse_texture::textureSparse(extensionContext, texObj) == GL_TRUE &&
                    extensions::sparse_texture::isSparseStorageImageSidecarTarget(img.storageImageTarget) &&
                    texObj->target == img.storageImageTarget &&
                    ib.access != GL_READ_ONLY;
                const bool sparseSidecarAccess =
                    img.sparseStorageImageWrite || sparseWritableBound;
                const auto sparseRoute = sparseSidecarAccess
                    ? extensions::sparse_texture::resolveSparseStorageImageSidecarBinding(
                          extensionContext, *texObj, img.storageImageTarget, &sidecarInfo)
                    : extensions::sparse_texture::SparseStorageImageBindingRoute::NativeTexture;
                if (sparseRoute ==
                    extensions::sparse_texture::SparseStorageImageBindingRoute::SidecarTexture) {
                    tb.metalTexture =
                        impl_->resolveSparseSidecarImageMetalTexture(
                            ib, texObj, sidecarInfo);
                } else if (sparseRoute ==
                           extensions::sparse_texture::SparseStorageImageBindingRoute::SparseSidecarUnavailable) {
                    continue;
                } else {
                    if (ib.access != GL_READ_ONLY) {
                        (void)extensions::sparse_texture::ensureSparseStorageImageSidecar(
                            extensionContext, *texObj);
                    }
                    // CKPT119: level-restricted view when ib.level > 0.
                    tb.metalTexture = impl_->resolveImageMetalTexture(
                        ib, texObj, img.storageImageTarget);
                }
            }
            tb.metalSamplerState = nullptr;
            tb.metalSlot = img.metalBinding + static_cast<std::uint32_t>(arrayElement);
            if (img.metalAtomicBufferBinding != 0xFFFFFFFFu) {
                const std::string atomicNeedle = img.name + "_atomic";
                const bool usesImageAtomic =
                    programObject->computeMSL.find(atomicNeedle) != std::string::npos ||
                    programObject->computeMSL.find("_appgl_" + atomicNeedle) !=
                        std::string::npos;
                if (usesImageAtomic) {
                    tb.imageAtomicBufferSlot =
                        img.metalAtomicBufferBinding +
                        static_cast<std::uint32_t>(arrayElement);
                    if (texObj->target == GL_TEXTURE_BUFFER &&
                        texObj->desc.sourceBuffer != 0) {
                        GLBufferObject* backingBuffer =
                            impl_->objects->buffers().get(texObj->desc.sourceBuffer);
                        if (backingBuffer != nullptr &&
                            backingBuffer->metalBuffer != nullptr) {
                            tb.imageAtomicMetalBuffer =
                                backingBuffer->metalBuffer;
                            tb.imageAtomicBufferOffset =
                                static_cast<std::size_t>(
                                    std::max<GLintptr>(
                                        texObj->desc.bufferOffset, 0));
                        }
                    } else {
                        tb.imageAtomicMetalBuffer =
                            impl_->ensureTextureImageAtomicBuffer(*texObj);
                        tb.imageAtomicBufferOffset = 0;
                        if (tb.imageAtomicMetalBuffer != nullptr &&
                            ib.access != GL_READ_ONLY) {
                            texObj->imageAtomicBufferDirtyToTexture = true;
                        }
                    }
                }
            }
            info.textures.push_back(tb);
        }
    }
    if (hasMSImageSampleCountsIndirect) {
        info.multisampleStorageImageSampleCounts = msImageSampleCountsIndirect.data();
        info.multisampleStorageImageSampleCountBytes =
            msImageSampleCountsIndirect.size() * sizeof(std::uint32_t);
        info.multisampleStorageImageSampleCountSlot =
            multisampleStorageImageSampleCountSlotForMSL(programObject->computeMSL);
    }

    impl_->declareComputeDispatchSubmissionGroup(info, computeReads, computeWrites);
    impl_->drainPendingGpuProducers(computeReads);
    const bool encoded = impl_->frameGraph->encodeComputeDispatch(info);
    if (encoded) {
        impl_->markGpuResourceWrites(computeWrites);
        for (const auto& sync : fp64SsboSidecars) {
            if (sync.buffer != nullptr && sync.binding != nullptr &&
                sync.sidecar != nullptr) {
                impl_->syncFp64TransportSidecarBack(
                    *sync.buffer, *sync.binding, *sync.sidecar);
            }
        }
    }
    return true;
}

// ---------------------------------------------------------------------------
// GL 4.2 — Image Load/Store
// ---------------------------------------------------------------------------

bool GLContext::bindImageTexture(GLuint unit, GLuint texture, GLint level, GLboolean layered, GLint layer, GLenum access, GLenum format) {
    if (unit >= Impl::kMaxImageUnits) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (texture != 0 && impl_->objects->textures().get(texture) == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (level < 0 || layer < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (access != GL_READ_ONLY && access != GL_WRITE_ONLY && access != GL_READ_WRITE) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // Validate format — accept the common image load/store formats.
    switch (format) {
        case GL_RGBA32F:
        case GL_RGBA16F:
        case GL_RG32F:
        case GL_RG16F:
        case GL_R11F_G11F_B10F:
        case GL_R32F:
        case GL_R16F:
        case GL_RGBA32UI:
        case GL_RGBA16UI:
        case GL_RGB10_A2UI:
        case GL_RGBA8UI:
        case GL_RG32UI:
        case GL_RG16UI:
        case GL_RG8UI:
        case GL_R32UI:
        case GL_R16UI:
        case GL_R8UI:
        case GL_RGBA32I:
        case GL_RGBA16I:
        case GL_RGBA8I:
        case GL_RG32I:
        case GL_RG16I:
        case GL_RG8I:
        case GL_R32I:
        case GL_R16I:
        case GL_R8I:
        case GL_RGBA16:
        case GL_RGB10_A2:
        case GL_RGBA8:
        case GL_RG16:
        case GL_RG8:
        case GL_R16:
        case GL_R8:
        case GL_RGBA16_SNORM:
        case GL_RGBA8_SNORM:
        case GL_RG16_SNORM:
        case GL_RG8_SNORM:
        case GL_R16_SNORM:
        case GL_R8_SNORM:
            break;
        default:
            pushError(GL_INVALID_VALUE);
            return false;
    }

    auto& binding = impl_->imageBindings[unit];
    // Sprint 18 Bucket 3 / CKPT119: invalidate the cached image view if
    // the binding identity changes. The image format is part of the
    // identity because native storage images may need a PixelFormatView
    // even when the mip level is zero.
    const bool cachedViewChanged =
        (binding.metalLevelView != nullptr ||
         binding.sparseSidecarLevelView != nullptr) &&
        (binding.cachedViewTexture != texture ||
         binding.cachedViewLevel != level ||
         binding.cachedViewFormat != format ||
         binding.cachedViewLayered != layered ||
         binding.cachedViewLayer != layer);
    const bool layer3DSidecarChanged =
        binding.layer3DSidecarTexture != nullptr &&
        (binding.layer3DSidecarSourceTexture != texture ||
         binding.layer3DSidecarLevel != level ||
         binding.layer3DSidecarFormat != format ||
         binding.layer3DSidecarLayer != layer);
    if (cachedViewChanged || layer3DSidecarChanged) {
        impl_->flushImageBinding3DLayerSidecar(binding);
        binding.invalidateMetalView();
    }
    binding.texture = texture;
    binding.level = level;
    binding.layered = layered;
    binding.layer = layer;
    binding.access = access;
    binding.format = format;
    if (texture != 0 && access != GL_READ_ONLY) {
        if (GLTextureObject* object = impl_->objects->textures().get(texture)) {
            ExtensionContext extensionContext(*this);
            (void)extensions::sparse_texture::ensureSparseStorageImageSidecar(
                extensionContext, *object);
        }
    }
    return true;
}

// ---------------------------------------------------------------------------
// GL 4.2 — Atomic Counter Buffer Queries
// ---------------------------------------------------------------------------

bool GLContext::getActiveAtomicCounterBufferiv(GLuint program, GLuint bufferIndex, GLenum pname, GLint* params) {
    if (params == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    GLProgramObject* object = impl_->objects->programs().get(program);
    if (object == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (bufferIndex >= object->resourceAtomicCounterBuffers.size()) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const GLProgramResourceEntry& entry =
        object->resourceAtomicCounterBuffers[bufferIndex];
    switch (pname) {
        case GL_ATOMIC_COUNTER_BUFFER_BINDING:
            *params = entry.binding;
            return true;
        case GL_ATOMIC_COUNTER_BUFFER_DATA_SIZE:
            *params = entry.offset >= 0 ? entry.offset : 0;
            return true;
        case GL_ATOMIC_COUNTER_BUFFER_ACTIVE_ATOMIC_COUNTERS:
            *params = static_cast<GLint>(entry.activeVariables.size());
            return true;
        case GL_ATOMIC_COUNTER_BUFFER_ACTIVE_ATOMIC_COUNTER_INDICES:
            for (std::size_t i = 0; i < entry.activeVariables.size(); ++i) {
                params[i] = entry.activeVariables[i];
            }
            return true;
        case GL_ATOMIC_COUNTER_BUFFER_REFERENCED_BY_VERTEX_SHADER:
            *params = (entry.referencedBy & 0x01) ? GL_TRUE : GL_FALSE;
            return true;
        case GL_ATOMIC_COUNTER_BUFFER_REFERENCED_BY_FRAGMENT_SHADER:
            *params = (entry.referencedBy & 0x02) ? GL_TRUE : GL_FALSE;
            return true;
        case GL_ATOMIC_COUNTER_BUFFER_REFERENCED_BY_GEOMETRY_SHADER:
            *params = (entry.referencedBy & 0x04) ? GL_TRUE : GL_FALSE;
            return true;
        case GL_ATOMIC_COUNTER_BUFFER_REFERENCED_BY_TESS_CONTROL_SHADER:
            *params = (entry.referencedBy & 0x08) ? GL_TRUE : GL_FALSE;
            return true;
        case GL_ATOMIC_COUNTER_BUFFER_REFERENCED_BY_TESS_EVALUATION_SHADER:
            *params = (entry.referencedBy & 0x10) ? GL_TRUE : GL_FALSE;
            return true;
        case GL_ATOMIC_COUNTER_BUFFER_REFERENCED_BY_COMPUTE_SHADER:
            *params = (entry.referencedBy & 0x20) ? GL_TRUE : GL_FALSE;
            return true;
        default:
            pushError(GL_INVALID_ENUM);
            return false;
    }
}

// ---------------------------------------------------------------------------
// GL 4.3 — Program Resource Introspection (ARB_program_interface_query)
// ---------------------------------------------------------------------------

namespace {

bool isSubroutineResourceInterface(GLenum programInterface) {
    switch (programInterface) {
        case GL_VERTEX_SUBROUTINE:
        case GL_TESS_CONTROL_SUBROUTINE:
        case GL_TESS_EVALUATION_SUBROUTINE:
        case GL_GEOMETRY_SUBROUTINE:
        case GL_FRAGMENT_SUBROUTINE:
        case GL_COMPUTE_SUBROUTINE:
            return true;
        default:
            return false;
    }
}

std::string stripBracketZeroSuffix(const std::string& n) {
    if (n.size() >= 3 && n.compare(n.size() - 3, 3, "[0]") == 0) {
        return n.substr(0, n.size() - 3);
    }
    return n;
}

bool parseStrictArrayIndex(const std::string& s, long& out) {
    if (s.empty()) return false;
    if (s[0] == '0' && s.size() > 1) return false;
    for (char c : s) {
        if (c < '0' || c > '9') return false;
    }
    char* endp = nullptr;
    out = std::strtol(s.c_str(), &endp, 10);
    return out >= 0;
}

bool parseArrayElementLookup(
    const std::string& lookup,
    std::string& baseName,
    std::vector<GLint>& indices) {
    indices.clear();
    const std::size_t firstBracket = lookup.find('[');
    if (firstBracket == std::string::npos) {
        baseName = lookup;
        return !baseName.empty();
    }
    baseName = lookup.substr(0, firstBracket);
    if (baseName.empty()) return false;
    std::size_t p = firstBracket;
    while (p < lookup.size()) {
        if (lookup[p] != '[') return false;
        const std::size_t close = lookup.find(']', p + 1);
        if (close == std::string::npos) return false;
        long idx = 0;
        if (!parseStrictArrayIndex(lookup.substr(p + 1, close - p - 1), idx)) {
            return false;
        }
        indices.push_back(static_cast<GLint>(idx));
        p = close + 1;
    }
    return !indices.empty();
}

bool flattenArrayElementIndex(
    const GLProgramResourceEntry& entry,
    const std::vector<GLint>& indices,
    GLint& flatIndex) {
    if (indices.empty()) {
        flatIndex = 0;
        return true;
    }
    if (entry.arrayDimensions.empty()) {
        if (indices.size() != 1) return false;
        if (indices[0] < 0 || indices[0] >= entry.arraySize) return false;
        flatIndex = indices[0];
        return true;
    }
    if (indices.size() != entry.arrayDimensions.size()) return false;
    GLint flat = 0;
    for (std::size_t i = 0; i < indices.size(); ++i) {
        const GLint dim = entry.arrayDimensions[i];
        if (dim <= 0 || indices[i] < 0 || indices[i] >= dim) return false;
        flat = flat * dim + indices[i];
    }
    if (flat < 0 || flat >= entry.arraySize) return false;
    flatIndex = flat;
    return true;
}

const std::vector<GLProgramResourceEntry>* getResourceTable(const GLProgramObject& prog, GLenum programInterface) {
    switch (programInterface) {
        case GL_UNIFORM:                      return &prog.resourceUniforms;
        case GL_UNIFORM_BLOCK:                return &prog.resourceUniformBlocks;
        case GL_PROGRAM_INPUT:                return &prog.resourceInputs;
        case GL_PROGRAM_OUTPUT:               return &prog.resourceOutputs;
        case GL_SHADER_STORAGE_BLOCK:         return &prog.resourceStorageBlocks;
        case GL_ATOMIC_COUNTER_BUFFER:        return &prog.resourceAtomicCounterBuffers;
        case GL_BUFFER_VARIABLE:              return &prog.resourceBufferVariables;
        case GL_TRANSFORM_FEEDBACK_VARYING:   return &prog.resourceTransformFeedbackVaryings;
        case GL_TRANSFORM_FEEDBACK_BUFFER:    return &prog.resourceTransformFeedbackBuffers;
        // GL 4.0 subroutine interfaces — per-stage (VS=0, TCS=1,
        // TES=2, GS=3, FS=4, CS=5).
        case GL_VERTEX_SUBROUTINE:               return &prog.resourceSubroutines[0];
        case GL_TESS_CONTROL_SUBROUTINE:         return &prog.resourceSubroutines[1];
        case GL_TESS_EVALUATION_SUBROUTINE:      return &prog.resourceSubroutines[2];
        case GL_GEOMETRY_SUBROUTINE:             return &prog.resourceSubroutines[3];
        case GL_FRAGMENT_SUBROUTINE:             return &prog.resourceSubroutines[4];
        case GL_COMPUTE_SUBROUTINE:              return &prog.resourceSubroutines[5];
        case GL_VERTEX_SUBROUTINE_UNIFORM:       return &prog.resourceSubroutineUniforms[0];
        case GL_TESS_CONTROL_SUBROUTINE_UNIFORM: return &prog.resourceSubroutineUniforms[1];
        case GL_TESS_EVALUATION_SUBROUTINE_UNIFORM: return &prog.resourceSubroutineUniforms[2];
        case GL_GEOMETRY_SUBROUTINE_UNIFORM:     return &prog.resourceSubroutineUniforms[3];
        case GL_FRAGMENT_SUBROUTINE_UNIFORM:     return &prog.resourceSubroutineUniforms[4];
        case GL_COMPUTE_SUBROUTINE_UNIFORM:      return &prog.resourceSubroutineUniforms[5];
        default: return nullptr;
    }
}

GLint getResourceProperty(const GLProgramResourceEntry& entry, GLenum prop) {
    switch (prop) {
        case GL_NAME_LENGTH:       return static_cast<GLint>(entry.name.size() + 1);
        case GL_TYPE:              return static_cast<GLint>(entry.type);
        case GL_ARRAY_SIZE:
            // GL 4.6 §7.3.1: scalar/vector uniforms report 1, N-
            // element arrays report N, unbounded arrays report 0.
            // Scanner uniforms set arraySize=1 for scalars directly;
            // block-member reflection keeps SPIRV-Cross's raw
            // arraySize (0 for both scalars and unbounded) and sets
            // isArray. Use isArray to split the 0-case.
            return entry.isArray ? entry.arraySize : std::max<GLint>(entry.arraySize, 1);
        case GL_OFFSET:
            return entry.type == GL_UNSIGNED_INT_ATOMIC_COUNTER
                ? entry.atomicCounterOffset
                : entry.offset;
        case GL_BLOCK_INDEX:       return entry.blockIndex;
        case GL_LOCATION:          return entry.location;
        // `referencedBy` is a bitmask: 0x01 VS / 0x02 FS /
        // 0x04 GS / 0x08 TCS / 0x10 TES / 0x20 CS. Prior code
        // read GS / TCS / TES as always-FALSE and incorrectly
        // mapped the 0x04 bit to COMPUTE, so GS-stage queries
        // all reported zero even after the per-resource
        // referencedBy derivation started setting them.
        case GL_REFERENCED_BY_VERTEX_SHADER:   return (entry.referencedBy & 0x01) ? GL_TRUE : GL_FALSE;
        case GL_REFERENCED_BY_FRAGMENT_SHADER: return (entry.referencedBy & 0x02) ? GL_TRUE : GL_FALSE;
        case GL_REFERENCED_BY_GEOMETRY_SHADER: return (entry.referencedBy & 0x04) ? GL_TRUE : GL_FALSE;
        case GL_REFERENCED_BY_TESS_CONTROL_SHADER: return (entry.referencedBy & 0x08) ? GL_TRUE : GL_FALSE;
        case GL_REFERENCED_BY_TESS_EVALUATION_SHADER: return (entry.referencedBy & 0x10) ? GL_TRUE : GL_FALSE;
        case GL_REFERENCED_BY_COMPUTE_SHADER:  return (entry.referencedBy & 0x20) ? GL_TRUE : GL_FALSE;
        case GL_BUFFER_BINDING:
            // Block-resource bindings are mutable after link:
            // glUniformBlockBinding/glShaderStorageBlockBinding update
            // `location`, while `binding` preserves the shader's explicit
            // layout(binding=N) value. Report the effective binding first;
            // entries without a mutable location (for example atomic
            // counter buffers) fall back to `binding`.
            return entry.location >= 0 ? entry.location : entry.binding;
        case GL_BUFFER_DATA_SIZE:
            // Only valid on block interfaces. For UBOs it's the
            // std140/std430 byte size; we stored it in `offset`.
            // SSBOs with trailing unbounded arrays legitimately
            // have byteSize=0, which the spec accepts.
            return entry.offset >= 0 ? entry.offset : 0;
        case GL_NUM_ACTIVE_VARIABLES:
            return static_cast<GLint>(entry.activeVariables.size());
        case GL_ACTIVE_VARIABLES:
            // Single-value accessor; the real
            // `glGetProgramResourceiv` read path copies the full
            // list via the props iteration. Return the first
            // element (or 0 if empty) — not fully spec-correct
            // but unblocks tests that just check
            // NUM_ACTIVE_VARIABLES and the first entry.
            return entry.activeVariables.empty()
                ? 0 : entry.activeVariables.front();
        case GL_IS_ROW_MAJOR:      return entry.isRowMajor ? GL_TRUE : GL_FALSE;
        // GL 4.6 §7.3.1: GL_MATRIX_STRIDE / GL_ARRAY_STRIDE
        // return the byte stride between matrix columns/rows
        // and between array elements respectively, for block
        // members. -1 when the variable isn't a member of a
        // buffer-backed block. The reflection-captured stride
        // propagates via `entry.matrixStride` / `entry.arrayStride`.
        case GL_MATRIX_STRIDE:
            return entry.blockIndex >= 0 ? entry.matrixStride : -1;
        case GL_ARRAY_STRIDE:
            return entry.blockIndex >= 0 ? entry.arrayStride : -1;
        case GL_ATOMIC_COUNTER_BUFFER_INDEX:
            // Set on uniform entries whose type is
            // GL_UNSIGNED_INT_ATOMIC_COUNTER at link time;
            // -1 on any non-atomic uniform.
            return entry.atomicCounterBufferIndex;
        case GL_TOP_LEVEL_ARRAY_SIZE:
            // Only meaningful on GL_BUFFER_VARIABLE entries; spec
            // returns 1 for non-buffer-variable queries (never
            // reached since propInterfaceCompatible restricts this
            // prop to GL_BUFFER_VARIABLE).
            return entry.topLevelArraySize;
        case GL_TOP_LEVEL_ARRAY_STRIDE: return entry.topLevelArrayStride;
        case GL_NUM_COMPATIBLE_SUBROUTINES:
            // On GL_*_SUBROUTINE_UNIFORM entries, number of subroutine
            // impls compatible with this uniform's declared type.
            // Populated at link time into `activeVariables`.
            return static_cast<GLint>(entry.activeVariables.size());
        case GL_COMPATIBLE_SUBROUTINES:
            // Single-value fallback — the real multi-value read path
            // in `getProgramResourceiv` already handles ACTIVE_VARIABLES-
            // style expansion. Return the first compatible subroutine
            // index (or 0 if empty) for any caller that invokes
            // `getResourceProperty` directly.
            return entry.activeVariables.empty()
                ? 0 : entry.activeVariables.front();
        case GL_LOCATION_INDEX:
            // Built-in outputs like `gl_FragDepth` have no user-
            // assignable location — LOCATION_INDEX is -1 there
            // (the spec language is ambiguous but CTS expects
            // this). `entry.location == -1` is our signal.
            return entry.location < 0 ? -1 : entry.locationIndex;
        case GL_IS_PER_PATCH:           return entry.isPerPatch ? GL_TRUE : GL_FALSE;
        case GL_LOCATION_COMPONENT:     return 0;
        default: return 0;
    }
}

}  // anonymous namespace

bool GLContext::getProgramInterfaceiv(GLuint program, GLenum programInterface, GLenum pname, GLint* params) {
    if (params == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    GLProgramObject* prog = impl_->objects->programs().get(program);
    if (prog == nullptr) {
        // GL 4.6 §7.3.1: shader-name → INVALID_OPERATION,
        // other bogus names → INVALID_VALUE. See
        // getProgramResourceIndex for the same distinguishing
        // logic. Required by CTS
        // `program_interface_query.invalid-operation` Case 1.
        if (impl_->objects->shaders().contains(program)) {
            pushError(GL_INVALID_OPERATION);
        } else {
            pushError(GL_INVALID_VALUE);
        }
        return false;
    }
    // CTS program_interface_query.empty-shaders constructs a program
    // with no shaders attached, never links it, and queries every
    // interface — expecting ACTIVE_RESOURCES=0 and MAX_NAME_LENGTH=0
    // without an error. A strict GL_INVALID_OPERATION on unlinked
    // programs makes 39/43 of program_interface_query fail; instead
    // the empty-program path returns 0 for numeric pnames and still
    // rejects unknown pnames with INVALID_ENUM. Linked programs go
    // through the normal resource-table path.
    const bool isLinked = prog->linked;
    const auto* table = isLinked ? getResourceTable(*prog, programInterface) : nullptr;
    // Validate programInterface enum even if not linked (unknown
    // interfaces should still raise INVALID_ENUM). The accepted set
    // mirrors getResourceTable.
    if (!isLinked) {
        switch (programInterface) {
            case GL_UNIFORM:
            case GL_UNIFORM_BLOCK:
            case GL_PROGRAM_INPUT:
            case GL_PROGRAM_OUTPUT:
            case GL_SHADER_STORAGE_BLOCK:
            case GL_ATOMIC_COUNTER_BUFFER:
            case GL_BUFFER_VARIABLE:
            case GL_TRANSFORM_FEEDBACK_VARYING:
            case GL_TRANSFORM_FEEDBACK_BUFFER:
            case GL_VERTEX_SUBROUTINE:
            case GL_TESS_CONTROL_SUBROUTINE:
            case GL_TESS_EVALUATION_SUBROUTINE:
            case GL_GEOMETRY_SUBROUTINE:
            case GL_FRAGMENT_SUBROUTINE:
            case GL_COMPUTE_SUBROUTINE:
            case GL_VERTEX_SUBROUTINE_UNIFORM:
            case GL_TESS_CONTROL_SUBROUTINE_UNIFORM:
            case GL_TESS_EVALUATION_SUBROUTINE_UNIFORM:
            case GL_GEOMETRY_SUBROUTINE_UNIFORM:
            case GL_FRAGMENT_SUBROUTINE_UNIFORM:
            case GL_COMPUTE_SUBROUTINE_UNIFORM:
                break;
            default:
                pushError(GL_INVALID_ENUM);
                return false;
        }
    } else if (table == nullptr) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    switch (pname) {
        case GL_ACTIVE_RESOURCES:
            *params = isLinked ? static_cast<GLint>(table->size()) : 0;
            return true;
        case GL_MAX_NAME_LENGTH: {
            if (!isLinked) {
                *params = 0;
                return true;
            }
            GLint maxLen = 0;
            for (const auto& entry : *table) {
                GLint len = static_cast<GLint>(entry.name.size() + 1);
                if (len > maxLen) maxLen = len;
            }
            *params = maxLen;
            return true;
        }
        case GL_MAX_NUM_ACTIVE_VARIABLES:
            // GL 4.6 §7.3.1 table: this pname is only valid on
            // the interfaces that expose an active-variables
            // list (UNIFORM_BLOCK, ATOMIC_COUNTER_BUFFER,
            // SHADER_STORAGE_BLOCK, TRANSFORM_FEEDBACK_BUFFER).
            // CTS `program_interface_query.invalid-operation`
            // passes GL_PROGRAM_INPUT and expects
            // INVALID_OPERATION. Value is max of activeVariables
            // counts across all block entries on the interface.
            switch (programInterface) {
                case GL_UNIFORM_BLOCK:
                case GL_ATOMIC_COUNTER_BUFFER:
                case GL_SHADER_STORAGE_BLOCK:
                case GL_TRANSFORM_FEEDBACK_BUFFER: {
                    GLint maxN = 0;
                    if (table != nullptr) {
                        for (const auto& entry : *table) {
                            GLint n = static_cast<GLint>(entry.activeVariables.size());
                            if (n > maxN) maxN = n;
                        }
                    }
                    *params = maxN;
                    return true;
                }
                default:
                    pushError(GL_INVALID_OPERATION);
                    return false;
            }
        case GL_MAX_NUM_COMPATIBLE_SUBROUTINES:
            // GL 4.6 §7.3.1: only valid on the *_SUBROUTINE_UNIFORM
            // interfaces. Value = max(count of compatible subroutines
            // across all subroutine uniforms on this interface).
            switch (programInterface) {
                case GL_VERTEX_SUBROUTINE_UNIFORM:
                case GL_TESS_CONTROL_SUBROUTINE_UNIFORM:
                case GL_TESS_EVALUATION_SUBROUTINE_UNIFORM:
                case GL_GEOMETRY_SUBROUTINE_UNIFORM:
                case GL_FRAGMENT_SUBROUTINE_UNIFORM:
                case GL_COMPUTE_SUBROUTINE_UNIFORM: {
                    GLint maxN = 0;
                    if (table != nullptr) {
                        for (const auto& e : *table) {
                            GLint n = static_cast<GLint>(e.activeVariables.size());
                            if (n > maxN) maxN = n;
                        }
                    }
                    *params = maxN;
                    return true;
                }
                default:
                    pushError(GL_INVALID_OPERATION);
                    return false;
            }
        default:
            pushError(GL_INVALID_ENUM);
            return false;
    }
}

bool GLContext::getProgramResourceiv(GLuint program, GLenum programInterface, GLuint index, GLsizei propCount, const GLenum* props, GLsizei count, GLsizei* length, GLint* params) {
    // Always defensively-zero the caller's length output first. CTS tests
    // (e.g. program_interface_query.subroutines-vertex) declare
    // `GLsizei length` uninitialized on the stack, call us with the
    // address, and then use `length` as a for-loop bound — if we return
    // without writing it, the loop runs against stack garbage and reads
    // past the end of its `param[1000]` buffer, producing a deterministic
    // SIGBUS once the stack happens to carry a large value at that offset
    // (observed at test #12648 of a full CTS sweep).
    if (length != nullptr) {
        *length = 0;
    }
    // GL 4.6 §7.3.1: propCount > 0 is required; propCount <= 0 is
    // INVALID_VALUE. But `count` (bufSize) of 0 or a NULL `params`
    // is valid — "no data is written." CTS
    // `program_interface_query.buff-length` calls with count=0 and
    // expects no error + no writes (we'd previously push
    // INVALID_VALUE and scribble `length` = 0 which is itself fine).
    if (propCount <= 0 || props == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // `count` < 0 is explicitly invalid per §7.3.1. CTS
    // `program_interface_query.invalid-value` passes -100 and expects
    // INVALID_VALUE.
    if (count < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    GLProgramObject* prog = impl_->objects->programs().get(program);
    if (prog == nullptr) {
        // Shader-name-vs-unknown-name: same rule as
        // getProgramResourceIndex.
        if (impl_->objects->shaders().contains(program)) {
            pushError(GL_INVALID_OPERATION);
        } else {
            pushError(GL_INVALID_VALUE);
        }
        return false;
    }
    if (!prog->linked) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    const auto* table = getResourceTable(*prog, programInterface);
    if (table == nullptr) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    // GL 4.6 §7.3.1 lists the valid prop enums for
    // getProgramResourceiv. Anything outside this set yields
    // GL_INVALID_ENUM. CTS `program_interface_query.invalid-enum`
    // passes `GL_TEXTURE_1D` as a prop and expects the error.
    auto isValidProp = [](GLenum p) {
        switch (p) {
            case GL_ACTIVE_VARIABLES:
            case GL_BUFFER_BINDING:
            case GL_BUFFER_DATA_SIZE:
            case GL_NUM_ACTIVE_VARIABLES:
            case GL_ARRAY_SIZE:
            case GL_ARRAY_STRIDE:
            case GL_BLOCK_INDEX:
            case GL_IS_ROW_MAJOR:
            case GL_MATRIX_STRIDE:
            case GL_ATOMIC_COUNTER_BUFFER_INDEX:
            case GL_NUM_COMPATIBLE_SUBROUTINES:
            case GL_COMPATIBLE_SUBROUTINES:
            case GL_IS_PER_PATCH:
            case GL_LOCATION:
            case GL_LOCATION_COMPONENT:
            case GL_LOCATION_INDEX:
            case GL_NAME_LENGTH:
            case GL_OFFSET:
            case GL_REFERENCED_BY_VERTEX_SHADER:
            case GL_REFERENCED_BY_TESS_CONTROL_SHADER:
            case GL_REFERENCED_BY_TESS_EVALUATION_SHADER:
            case GL_REFERENCED_BY_GEOMETRY_SHADER:
            case GL_REFERENCED_BY_FRAGMENT_SHADER:
            case GL_REFERENCED_BY_COMPUTE_SHADER:
            case GL_TOP_LEVEL_ARRAY_SIZE:
            case GL_TOP_LEVEL_ARRAY_STRIDE:
            case GL_TRANSFORM_FEEDBACK_BUFFER_INDEX:
            case GL_TRANSFORM_FEEDBACK_BUFFER_STRIDE:
            case GL_TYPE:
                return true;
            default:
                return false;
        }
    };
    for (GLsizei i = 0; i < propCount; ++i) {
        if (!isValidProp(props[i])) {
            pushError(GL_INVALID_ENUM);
            return false;
        }
    }
    // GL 4.6 §7.3.1 table: each prop is only valid on a subset of
    // interfaces. Using a prop that doesn't apply to the queried
    // interface yields INVALID_OPERATION. Only the most common
    // incompatibilities are enforced here; the full matrix would
    // add ~30 cases. CTS
    // `program_interface_query.invalid-operation` Case 3 passes
    // GL_OFFSET to GL_PROGRAM_INPUT — spec says that's an
    // INVALID_OPERATION.
    auto propInterfaceCompatible = [](GLenum prop, GLenum iface) {
        switch (prop) {
            case GL_OFFSET:
            case GL_BLOCK_INDEX:
            case GL_ARRAY_STRIDE:
            case GL_MATRIX_STRIDE:
            case GL_IS_ROW_MAJOR:
            case GL_ATOMIC_COUNTER_BUFFER_INDEX:
                return iface == GL_UNIFORM || iface == GL_BUFFER_VARIABLE
                    || iface == GL_TRANSFORM_FEEDBACK_VARYING;
            case GL_TOP_LEVEL_ARRAY_SIZE:
            case GL_TOP_LEVEL_ARRAY_STRIDE:
                return iface == GL_BUFFER_VARIABLE;
            case GL_BUFFER_BINDING:
            case GL_BUFFER_DATA_SIZE:
            case GL_NUM_ACTIVE_VARIABLES:
            case GL_ACTIVE_VARIABLES:
                return iface == GL_UNIFORM_BLOCK
                    || iface == GL_ATOMIC_COUNTER_BUFFER
                    || iface == GL_SHADER_STORAGE_BLOCK
                    || iface == GL_TRANSFORM_FEEDBACK_BUFFER;
            case GL_TRANSFORM_FEEDBACK_BUFFER_INDEX:
            case GL_TRANSFORM_FEEDBACK_BUFFER_STRIDE:
                return iface == GL_TRANSFORM_FEEDBACK_VARYING
                    || iface == GL_TRANSFORM_FEEDBACK_BUFFER;
            case GL_LOCATION_INDEX:
                return iface == GL_PROGRAM_OUTPUT;
            case GL_IS_PER_PATCH:
                return iface == GL_PROGRAM_INPUT || iface == GL_PROGRAM_OUTPUT;
            case GL_LOCATION:
            case GL_LOCATION_COMPONENT:
                return iface == GL_UNIFORM
                    || iface == GL_PROGRAM_INPUT
                    || iface == GL_PROGRAM_OUTPUT
                    || iface == GL_VERTEX_SUBROUTINE_UNIFORM
                    || iface == GL_TESS_CONTROL_SUBROUTINE_UNIFORM
                    || iface == GL_TESS_EVALUATION_SUBROUTINE_UNIFORM
                    || iface == GL_GEOMETRY_SUBROUTINE_UNIFORM
                    || iface == GL_FRAGMENT_SUBROUTINE_UNIFORM
                    || iface == GL_COMPUTE_SUBROUTINE_UNIFORM;
            case GL_NUM_COMPATIBLE_SUBROUTINES:
            case GL_COMPATIBLE_SUBROUTINES:
                return iface == GL_VERTEX_SUBROUTINE_UNIFORM
                    || iface == GL_TESS_CONTROL_SUBROUTINE_UNIFORM
                    || iface == GL_TESS_EVALUATION_SUBROUTINE_UNIFORM
                    || iface == GL_GEOMETRY_SUBROUTINE_UNIFORM
                    || iface == GL_FRAGMENT_SUBROUTINE_UNIFORM
                    || iface == GL_COMPUTE_SUBROUTINE_UNIFORM;
            default:
                // GL_NAME_LENGTH / GL_TYPE / GL_ARRAY_SIZE /
                // GL_REFERENCED_BY_* apply broadly — accept.
                return true;
        }
    };
    for (GLsizei i = 0; i < propCount; ++i) {
        if (!propInterfaceCompatible(props[i], programInterface)) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
    }
    if (index >= table->size()) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const auto& entry = (*table)[index];
    GLsizei written = 0;
    if (params != nullptr) {
        for (GLsizei i = 0; i < propCount && written < count; ++i) {
            // GL 4.6 §7.3.1: GL_ACTIVE_VARIABLES and
            // GL_COMPATIBLE_SUBROUTINES both write an ARRAY of
            // integers — the next NUM_ACTIVE_VARIABLES (or
            // NUM_COMPATIBLE_SUBROUTINES) slots, one per active
            // member. Every other prop writes a single integer.
            // CTS `program_interface_query.atomic-counters` reads
            // NUM_ACTIVE_VARIABLES via a separate call, then
            // reads the full ACTIVE_VARIABLES list with bufSize
            // large enough to hold all N entries; we must write
            // them all, not just the first.
            if (props[i] == GL_ACTIVE_VARIABLES ||
                props[i] == GL_COMPATIBLE_SUBROUTINES) {
                // GL_COMPATIBLE_SUBROUTINES uses the same
                // activeVariables vector on subroutine-uniform entries,
                // so share the multi-value path.
                for (GLint idx : entry.activeVariables) {
                    if (written >= count) break;
                    params[written++] = idx;
                }
                continue;
            }
            params[written++] = getResourceProperty(entry, props[i]);
        }
    }
    if (length != nullptr) {
        *length = written;
    }
    return true;
}

bool GLContext::getProgramResourceName(GLuint program, GLenum programInterface, GLuint index, GLsizei bufSize, GLsizei* length, GLchar* name) {
    // Defensively zero length first (see getProgramResourceiv for rationale).
    if (length != nullptr) {
        *length = 0;
    }
    // GL 4.6 §7.3.1: `bufSize` < 0 is invalid. CTS
    // `program_interface_query.invalid-value` passes -100 and expects
    // INVALID_VALUE.
    if (bufSize < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // GL 4.6 §7.3.1: `GL_ATOMIC_COUNTER_BUFFER` /
    // `GL_TRANSFORM_FEEDBACK_BUFFER` buffers carry no names; queries
    // generate INVALID_ENUM.
    if (programInterface == GL_ATOMIC_COUNTER_BUFFER ||
        programInterface == GL_TRANSFORM_FEEDBACK_BUFFER) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    GLProgramObject* prog = impl_->objects->programs().get(program);
    if (prog == nullptr) {
        if (impl_->objects->shaders().contains(program)) {
            pushError(GL_INVALID_OPERATION);
        } else {
            pushError(GL_INVALID_VALUE);
        }
        return false;
    }
    if (!prog->linked) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    const auto* table = getResourceTable(*prog, programInterface);
    if (table == nullptr) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (index >= table->size()) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const auto& entry = (*table)[index];
    if (name != nullptr && bufSize > 0) {
        std::size_t toCopy = std::min(static_cast<std::size_t>(bufSize - 1), entry.name.size());
        std::memcpy(name, entry.name.c_str(), toCopy);
        name[toCopy] = '\0';
        if (length != nullptr) {
            *length = static_cast<GLsizei>(toCopy);
        }
    } else if (length != nullptr) {
        *length = 0;
    }
    return true;
}

GLuint GLContext::getProgramResourceIndex(GLuint program, GLenum programInterface, const GLchar* name) {
    if (name == nullptr) {
        pushError(GL_INVALID_VALUE);
        return GL_INVALID_INDEX;
    }
    // GL 4.6 §7.3.1: `GL_ATOMIC_COUNTER_BUFFER` buffers have no
    // names, so this entry point is invalid on that interface.
    // `GL_TRANSFORM_FEEDBACK_BUFFER` is similarly unnamed.
    if (programInterface == GL_ATOMIC_COUNTER_BUFFER ||
        programInterface == GL_TRANSFORM_FEEDBACK_BUFFER) {
        pushError(GL_INVALID_ENUM);
        return GL_INVALID_INDEX;
    }
    GLProgramObject* prog = impl_->objects->programs().get(program);
    if (prog == nullptr) {
        // GL 4.6 §7.3.1 differentiates "name refers to a shader
        // object (INVALID_OPERATION)" from "name is not a generated
        // program name (INVALID_VALUE)". Distinguish here by
        // checking the shader table. CTS
        // `program_interface_query.invalid-operation` calls these
        // entry points with a shader name and expects the specific
        // INVALID_OPERATION error.
        if (impl_->objects->shaders().contains(program)) {
            pushError(GL_INVALID_OPERATION);
        } else {
            pushError(GL_INVALID_VALUE);
        }
        return GL_INVALID_INDEX;
    }
    // Unlinked program: silently return INVALID_INDEX (no match).
    // CTS empty-shaders queries resource indices on an unlinked
    // program and asserts no error is raised; strict
    // INVALID_OPERATION makes that subcase fail.
    if (!prog->linked) {
        return GL_INVALID_INDEX;
    }
    const auto* table = getResourceTable(*prog, programInterface);
    if (table == nullptr) {
        pushError(GL_INVALID_ENUM);
        return GL_INVALID_INDEX;
    }
    // GL 4.6 §7.3.1.1: `glGetProgramResourceIndex` cannot be used to
    // retrieve the index of the built-in transform-feedback markers
    // (`gl_NextBuffer` / `gl_SkipComponentsN`). They still appear in
    // the resource table and can be walked by index via
    // `glGetProgramResourceName`, but lookup-by-name returns
    // INVALID_INDEX. CTS
    // `program_interface_query.transform-feedback-built-in` verifies.
    if (programInterface == GL_TRANSFORM_FEEDBACK_VARYING) {
        const std::string q = name;
        if (q == "gl_NextBuffer" ||
            (q.size() == 18 && q.compare(0, 17, "gl_SkipComponents") == 0)) {
            return GL_INVALID_INDEX;
        }
    }
    for (std::size_t i = 0; i < table->size(); ++i) {
        if ((*table)[i].name == name) {
            if (isSubroutineResourceInterface(programInterface) &&
                (*table)[i].subroutineIndex >= 0) {
                return static_cast<GLuint>((*table)[i].subroutineIndex);
            }
            return static_cast<GLuint>(i);
        }
    }
    // Array-input lookup tolerance: GL 4.6 §7.3.1 says
    // getProgramResourceIndex("arr") should find the same entry as
    // "arr[0]" for an array input, and vice versa. Table entries
    // follow the "[0]"-suffixed convention for arrays
    // (`c` → "c[0]"); queries with bare base name should still
    // match. CTS `program_interface_query.input-types` queries
    // "d" where the table stores "d[0]".
    const std::string query = name;
    // Bare query → find a "<name>[0]" entry.
    {
        const std::string suffixed = query + "[0]";
        for (std::size_t i = 0; i < table->size(); ++i) {
            if ((*table)[i].name == suffixed) {
                if (isSubroutineResourceInterface(programInterface) &&
                    (*table)[i].subroutineIndex >= 0) {
                    return static_cast<GLuint>((*table)[i].subroutineIndex);
                }
                return static_cast<GLuint>(i);
            }
        }
    }
    // "<base>[0]"-suffixed query → find a bare "<base>" entry.
    if (query.size() >= 3 && query.compare(query.size() - 3, 3, "[0]") == 0) {
        const std::string baseOnly = query.substr(0, query.size() - 3);
        for (std::size_t i = 0; i < table->size(); ++i) {
            if ((*table)[i].name == baseOnly) {
                if (isSubroutineResourceInterface(programInterface) &&
                    (*table)[i].subroutineIndex >= 0) {
                    return static_cast<GLuint>((*table)[i].subroutineIndex);
                }
                return static_cast<GLuint>(i);
            }
        }
    }
    return GL_INVALID_INDEX;
}

GLint GLContext::getProgramResourceLocation(GLuint program, GLenum programInterface, const GLchar* name) {
    if (name == nullptr) {
        pushError(GL_INVALID_VALUE);
        return -1;
    }
    // GL 4.6 §7.3.1 valid interfaces: UNIFORM, PROGRAM_INPUT,
    // PROGRAM_OUTPUT, and the six *_SUBROUTINE_UNIFORM interfaces.
    // The last set lets CTS `subroutines-*` query the subroutine
    // uniform's location via `glGetProgramResourceLocation` (same
    // value `glGetSubroutineUniformLocation` returns).
    if (programInterface != GL_UNIFORM && programInterface != GL_PROGRAM_INPUT &&
        programInterface != GL_PROGRAM_OUTPUT &&
        programInterface != GL_VERTEX_SUBROUTINE_UNIFORM &&
        programInterface != GL_TESS_CONTROL_SUBROUTINE_UNIFORM &&
        programInterface != GL_TESS_EVALUATION_SUBROUTINE_UNIFORM &&
        programInterface != GL_GEOMETRY_SUBROUTINE_UNIFORM &&
        programInterface != GL_FRAGMENT_SUBROUTINE_UNIFORM &&
        programInterface != GL_COMPUTE_SUBROUTINE_UNIFORM) {
        pushError(GL_INVALID_ENUM);
        return -1;
    }
    GLProgramObject* prog = impl_->objects->programs().get(program);
    if (prog == nullptr) {
        if (impl_->objects->shaders().contains(program)) {
            pushError(GL_INVALID_OPERATION);
        } else {
            pushError(GL_INVALID_VALUE);
        }
        return -1;
    }
    if (!prog->linked) {
        pushError(GL_INVALID_OPERATION);
        return -1;
    }
    const auto* table = getResourceTable(*prog, programInterface);
    if (table == nullptr) {
        return -1;
    }
    const std::string lookup = name;
    // Direct match — but skip entries with location=-1. SPIRV-Cross
    // reflection sometimes emits both "u0" (the real base with valid
    // location) and "u0[0]" (a per-element duplicate that was never
    // assigned a location). Without the -1 guard the direct match
    // would hit the duplicate first and short-circuit to -1.
    for (const auto& entry : *table) {
        if (entry.name == lookup && entry.location >= 0) {
            return entry.location;
        }
    }
    // Array-element lookup parity with getUniformLocation: "u[k]"
    // resolves to location(u) + k when u is declared as an array of
    // size > k. GL 4.6 §7.3.1 says both entry points return the same
    // thing for the same name — including array subscript syntax.
    // Entries in the resource table may be stored under either a
    // bare base name ("u") or a "[0]"-suffixed canonical form ("u[0]"
    // for arrays — GL 4.6 §7.3.1 mandate). Match both shapes here.
    // GL 4.6 §7.3.1 (spec for array-subscript names in uniform /
    // resource lookups): only strictly-formatted decimal integers
    // are accepted. Rejected forms: leading/trailing whitespace
    // (`"a[ 0]"`, `"a[0 ]"`), embedded whitespace or arithmetic
    // (`"a[0 + 0]"`, `"a[0+0]"`), alternate whitespace
    // (`"a[\t0]"`, `"a[\n0]"`), leading zero (`"a[01]"`,
    // `"a[00]"`). strtol alone accepts all of these; we pre-validate
    // by scanning the index substring.
    std::string baseName;
    std::vector<GLint> elementIndices;
    const bool parsedArrayElement =
        parseArrayElementLookup(lookup, baseName, elementIndices) &&
        !elementIndices.empty();
    if (parsedArrayElement) {
        GLint flatIndex = 0;
        for (const auto& entry : *table) {
            if (stripBracketZeroSuffix(entry.name) == baseName && entry.arraySize >= 1
                && entry.location >= 0 &&
                flattenArrayElementIndex(entry, elementIndices, flatIndex)) {
                return entry.location + flatIndex;
            }
        }
    }
    // Ordinary default-block uniforms for arrays-of-arrays can be stored
    // as one resource per outer element (`u0[0][0]`, `u0[1][0]`) rather
    // than as a single base resource with arrayDimensions. If the new
    // multidimensional flattening path above did not match, preserve the
    // older innermost-index fallback so `u0[0][1]` resolves through the
    // `u0[0][0]` resource.
    {
        const auto openBracket = lookup.rfind('[');
        if (openBracket != std::string::npos && !lookup.empty() && lookup.back() == ']') {
            const std::string legacyBaseName = lookup.substr(0, openBracket);
            const std::string indexStr = lookup.substr(openBracket + 1, lookup.size() - openBracket - 2);
            long idx = 0;
            if (!legacyBaseName.empty() && parseStrictArrayIndex(indexStr, idx)) {
                for (const auto& entry : *table) {
                    if (stripBracketZeroSuffix(entry.name) == legacyBaseName && entry.arraySize >= 1
                        && idx < static_cast<long>(entry.arraySize)
                        && entry.location >= 0) {
                        return entry.location + static_cast<GLint>(idx);
                    }
                }
            }
        }
    }
    // Bare base-name lookup against a "[0]"-suffixed entry: GL 4.6
    // §7.3.1 says `getProgramResourceLocation("arr")` equals
    // `getProgramResourceLocation("arr[0]")` for array inputs.
    for (const auto& entry : *table) {
        if (stripBracketZeroSuffix(entry.name) == lookup && entry.location >= 0) {
            return entry.location;
        }
    }
    return -1;
}

GLint GLContext::getProgramResourceLocationIndex(GLuint program, GLenum programInterface, const GLchar* name) {
    if (name == nullptr) {
        pushError(GL_INVALID_VALUE);
        return -1;
    }
    if (programInterface != GL_PROGRAM_OUTPUT) {
        pushError(GL_INVALID_ENUM);
        return -1;
    }
    GLProgramObject* prog = impl_->objects->programs().get(program);
    if (prog == nullptr) {
        if (impl_->objects->shaders().contains(program)) {
            pushError(GL_INVALID_OPERATION);
        } else {
            pushError(GL_INVALID_VALUE);
        }
        return -1;
    }
    if (!prog->linked) {
        pushError(GL_INVALID_OPERATION);
        return -1;
    }
    // Fragment output location index (dual-source blending) —
    // comes from `glBindFragDataLocationIndexed`'s `index` arg
    // (0 = primary, 1 = second source). Stored on the entry.
    // Array outputs canonicalised to "<name>[0]" per GL 4.6
    // §7.3.1 — match both bare and suffixed query shapes.
    // Built-in outputs (no user location, e.g. gl_FragDepth)
    // report LOCATION_INDEX = -1 per CTS
    // `output-built-in` expectations.
    auto indexFor = [](const GLProgramResourceEntry& e) {
        return e.location < 0 ? -1 : e.locationIndex;
    };
    const std::string query = name;
    for (const auto& entry : prog->resourceOutputs) {
        if (entry.name == query) return indexFor(entry);
    }
    for (const auto& entry : prog->resourceOutputs) {
        if (entry.name == query + "[0]") return indexFor(entry);
    }
    if (query.size() >= 3 && query.compare(query.size() - 3, 3, "[0]") == 0) {
        const std::string baseOnly = query.substr(0, query.size() - 3);
        for (const auto& entry : prog->resourceOutputs) {
            if (entry.name == baseOnly) return indexFor(entry);
        }
    }
    return -1;
}

// ---------------------------------------------------------------------------
// GL 4.3 — Shader Storage Block Binding
// ---------------------------------------------------------------------------

bool GLContext::shaderStorageBlockBinding(GLuint program, GLuint storageBlockIndex, GLuint storageBlockBinding) {
    // GL 4.3 §7.6.1: INVALID_OPERATION when `program` names a
    // shader (not a program). Must run before the programs().get()
    // null-fallback or we'd return INVALID_VALUE instead.
    if (impl_->objects->shaders().get(program) != nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    GLProgramObject* prog = impl_->objects->programs().get(program);
    if (prog == nullptr || !prog->linked) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (storageBlockIndex >= prog->resourceStorageBlocks.size()) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // GL 4.3 §7.6.1: storageBlockBinding must be less than
    // GL_MAX_SHADER_STORAGE_BUFFER_BINDINGS. CTS
    // `shader_storage_buffer_object.negative-api-blockBinding`
    // plants `binding = MAX_BINDINGS` and expects INVALID_VALUE.
    {
        GLint maxBindings = 8;
        if (impl_->capabilities != nullptr) {
            impl_->capabilities->queryInteger(GL_MAX_SHADER_STORAGE_BUFFER_BINDINGS, &maxBindings);
        }
        if (storageBlockBinding >= static_cast<GLuint>(maxBindings)) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
    }
    prog->ssboBindingRemap[storageBlockIndex] = storageBlockBinding;
    // Also update the resource entry's location field so queries reflect the remap.
    prog->resourceStorageBlocks[storageBlockIndex].location = static_cast<GLint>(storageBlockBinding);
    return true;
}

// ---------------------------------------------------------------------------
// GL 4.2 — Advanced Instanced Drawing with Base Instance
// ---------------------------------------------------------------------------

bool GLContext::drawArraysInstancedBaseInstance(GLenum mode, GLint first, GLsizei count, GLsizei instancecount, GLuint baseinstance, GLuint drawID) {
    if (count < 0 || instancecount < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (count == 0 || instancecount == 0) {
        return true; // valid no-op
    }
    return drawArraysInstanced(mode, first, count, instancecount, baseinstance, drawID);
}

bool GLContext::drawElementsInstancedBaseInstance(GLenum mode, GLsizei count, GLenum type, const void* indices, GLsizei instancecount, GLuint baseinstance, GLuint drawID) {
    if (count < 0 || instancecount < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (type != GL_UNSIGNED_BYTE && type != GL_UNSIGNED_SHORT && type != GL_UNSIGNED_INT) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (count == 0 || instancecount == 0) {
        return true;
    }
    return drawElementsInstancedBaseVertex(mode, count, type, indices,
                                           instancecount, 0, baseinstance, drawID);
}

bool GLContext::drawElementsInstancedBaseVertexBaseInstance(GLenum mode, GLsizei count, GLenum type, const void* indices, GLsizei instancecount, GLint basevertex, GLuint baseinstance, GLuint drawID) {
    if (count < 0 || instancecount < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (type != GL_UNSIGNED_BYTE && type != GL_UNSIGNED_SHORT && type != GL_UNSIGNED_INT) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (count == 0 || instancecount == 0) {
        return true;
    }
    return drawElementsInstancedBaseVertex(mode, count, type, indices,
                                           instancecount, basevertex,
                                           baseinstance, drawID);
}

// ---------------------------------------------------------------------------
// GL 4.0/4.3 — Indirect Draw Helpers
// ---------------------------------------------------------------------------

GLuint GLContext::getBoundVertexArray() const {
    return impl_->state->boundVertexArray();
}

bool GLContext::readIndirectBuffer(GLenum target, const void* indirect, std::size_t size, void* out) {
    const GLuint bufName = impl_->state->boundBuffer(target);
    if (bufName != 0) {
        // `indirect` is a byte offset into the bound buffer.
        const auto offset = reinterpret_cast<uintptr_t>(indirect);
        GLBufferObject* buf = impl_->objects->buffers().get(bufName);
        if (buf == nullptr || !buf->instantiated) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
        if (offset + size > static_cast<std::size_t>(buf->size)) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
        if (!impl_->readBufferRange(
                *buf,
                static_cast<GLintptr>(offset),
                static_cast<GLsizeiptr>(size),
                out)) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
    } else {
        // No buffer bound — `indirect` is a client pointer.
        if (indirect == nullptr) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
        std::memcpy(out, indirect, size);
    }
    return true;
}

// ---------------------------------------------------------------------------
// GL 4.3 — Multi-Draw Indirect
// ---------------------------------------------------------------------------

bool GLContext::multiDrawArraysIndirect(GLenum mode, const void* indirect, GLsizei drawcount, GLsizei stride) {
    if (drawcount < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (stride != 0 && stride < 16) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // Core profile: drawing with default VAO (0) is INVALID_OPERATION.
    if (impl_->state->boundVertexArray() == 0) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // Offset into the indirect buffer must be 4-byte aligned.
    if (reinterpret_cast<uintptr_t>(indirect) % 4 != 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // DrawArraysIndirectCommand layout: { count, instanceCount, first, baseInstance }
    struct DrawArraysIndirectCommand {
        GLuint count;
        GLuint instanceCount;
        GLuint first;
        GLuint baseInstance;
    };
    const GLsizei effectiveStride = (stride == 0) ? static_cast<GLsizei>(sizeof(DrawArraysIndirectCommand)) : stride;
    const GLuint indirectBuf = impl_->state->boundBuffer(GL_DRAW_INDIRECT_BUFFER);
    GLBufferObject* indirectObject =
        indirectBuf != 0 ? impl_->objects->buffers().get(indirectBuf) : nullptr;
    const std::uint32_t indirectProducerBits =
        indirectObject != nullptr ? indirectObject->producerPending.bits() : 0u;
    const bool indirectBufferHasGpuProducer =
        indirectObject != nullptr &&
        (indirectObject->producerPending.hasAny(kProducerAll) ||
         indirectObject->gpuAuthoredSinceCpuWrite);
    if (std::getenv("APPGL_TRACE_MDI_PRODUCER")) {
        std::fprintf(stderr,
            "[APPGL] mdi-arrays indirectBuf=%u drawcount=%d stride=%d "
            "pending=0x%08x recentGpuWrite=%d guard=%d\n",
            indirectBuf, drawcount, stride, indirectProducerBits,
            indirectObject != nullptr && indirectObject->gpuAuthoredSinceCpuWrite ? 1 : 0,
            indirectBufferHasGpuProducer ? 1 : 0);
    }

    // GL 4.6 §10.5: pre-validate the indirect-buffer range. See
    // multiDrawElementsIndirect for the full rationale — the check
    // must fire BEFORE any sub-draw so we don't push a cascade of
    // per-draw errors when the buffer has stack-garbage trailer bytes.
    if (drawcount > 0) {
        if (indirectObject != nullptr) {
            const uintptr_t offset = reinterpret_cast<uintptr_t>(indirect);
            const uintptr_t strideBytes = static_cast<uintptr_t>(effectiveStride);
            const uintptr_t commandBytes = static_cast<uintptr_t>(sizeof(DrawArraysIndirectCommand));
            const uintptr_t lastCommandIndex = static_cast<uintptr_t>(drawcount - 1);
            if (lastCommandIndex > (std::numeric_limits<uintptr_t>::max() - offset) / strideBytes) {
                pushError(GL_INVALID_OPERATION);
                return false;
            }
            const uintptr_t lastCommandOffset = offset + lastCommandIndex * strideBytes;
            const uintptr_t bufferSize = static_cast<uintptr_t>(indirectObject->size);
            if (lastCommandOffset > bufferSize ||
                commandBytes > bufferSize - lastCommandOffset) {
                pushError(GL_INVALID_OPERATION);
                return false;
            }
        }
    }
    std::vector<DrawArraysIndirectCommand> commands;
    commands.reserve(static_cast<std::size_t>(std::max<GLsizei>(drawcount, 0)));
    bool canCoalesceContiguous = drawcount > 0;
    GLuint coalescedFirst = 0;
    GLuint coalescedEnd = 0;
    for (GLsizei i = 0; i < drawcount; ++i) {
        const void* cmdPtr = reinterpret_cast<const void*>(
            reinterpret_cast<uintptr_t>(indirect) + static_cast<uintptr_t>(i) * static_cast<uintptr_t>(effectiveStride));
        DrawArraysIndirectCommand cmd{};
        if (!readIndirectBuffer(GL_DRAW_INDIRECT_BUFFER, cmdPtr, sizeof(cmd), &cmd)) {
            return false;
        }
        if (cmd.count == 0 || cmd.instanceCount == 0) {
            canCoalesceContiguous = false;
        } else if (cmd.instanceCount != 1 || cmd.baseInstance != 0) {
            canCoalesceContiguous = false;
        } else if (i == 0) {
            coalescedFirst = cmd.first;
            coalescedEnd = cmd.first + cmd.count;
            if (coalescedEnd < cmd.first) {
                canCoalesceContiguous = false;
            }
        } else if (canCoalesceContiguous && cmd.first == coalescedEnd) {
            coalescedEnd += cmd.count;
            if (coalescedEnd < cmd.first) {
                canCoalesceContiguous = false;
            }
        } else {
            canCoalesceContiguous = false;
        }
        commands.push_back(cmd);
    }

    const bool bypassSamplerRecipeForSparseMdi =
        impl_->currentDrawStateReferencesSparseBuffer(indirectBuf);
    struct ScopedSparseMdiSamplerRecipeBypass {
        GLContext::Impl& impl;
        bool previous = false;
        ScopedSparseMdiSamplerRecipeBypass(GLContext::Impl& target, bool enable)
            : impl(target), previous(target.samplerRecipeCacheBypassForSparseMdi) {
            if (enable) {
                impl.samplerRecipeCacheBypassForSparseMdi = true;
            }
        }
        ~ScopedSparseMdiSamplerRecipeBypass() {
            impl.samplerRecipeCacheBypassForSparseMdi = previous;
        }
    } sparseMdiSamplerRecipeBypass(*impl_, bypassSamplerRecipeForSparseMdi);
    if (bypassSamplerRecipeForSparseMdi &&
        std::getenv("APPGL_TRACE_MDI_PRODUCER")) {
        std::fprintf(stderr,
            "[APPGL] mdi-arrays sampler-recipe bypass reason=sparse-buffer\n");
    }

    // Live layer-backed presents reuse one render encoder for the full
    // frame. On that path, Apple AGX currently fails to make per-subdraw
    // vertex range rebinding observable for VBO-backed MDI walls. When the
    // commands are exactly one CPU-authored contiguous, non-instanced
    // independent-primitive array range and the shader has no draw/primitive
    // ID dependency, the GL-visible result is identical to one drawArrays over
    // the combined range and avoids the fragile per-command encoder state. A
    // GPU-produced indirect buffer must take the per-command path: the first
    // read below drains the producer token, so sampling the pending state before
    // the reads preserves the hazard-aware exclusion.
    const bool canUseCoalescedPath =
        canCoalesceContiguous &&
        !indirectBufferHasGpuProducer &&
        isCoalescibleArrayPrimitiveMode(mode);
    if (std::getenv("APPGL_TRACE_MDI_PRODUCER")) {
        std::fprintf(stderr,
            "[APPGL] mdi-arrays coalesce canContiguous=%d "
            "gpuGuard=%d primitiveMode=%d use=%d\n",
            canCoalesceContiguous ? 1 : 0,
            indirectBufferHasGpuProducer ? 1 : 0,
            isCoalescibleArrayPrimitiveMode(mode) ? 1 : 0,
            canUseCoalescedPath ? 1 : 0);
    }
    if (canUseCoalescedPath) {
        GLuint programName = impl_->state->currentProgram();
        GLProgramObject* program = impl_->resolveDrawProgram(programName);
        const GLuint coalescedCount = coalescedEnd - coalescedFirst;
        if (program != nullptr &&
            !programUsesDrawOrPrimitiveIDDependency(*program, *impl_->objects) &&
            coalescedCount <= static_cast<GLuint>(std::numeric_limits<GLsizei>::max())) {
            return drawArrays(mode,
                              static_cast<GLint>(coalescedFirst),
                              static_cast<GLsizei>(coalescedCount),
                              0);
        }
    }

    for (GLsizei i = 0; i < drawcount; ++i) {
        const auto& cmd = commands[static_cast<std::size_t>(i)];
        if (cmd.count == 0 || cmd.instanceCount == 0) {
            continue;  // valid no-op for this sub-draw
        }
        drawArraysInstancedBaseInstance(mode, static_cast<GLint>(cmd.first),
                                        static_cast<GLsizei>(cmd.count),
                                        static_cast<GLsizei>(cmd.instanceCount),
                                        cmd.baseInstance,
                                        static_cast<GLuint>(i));
    }
    return true;
}

bool GLContext::multiDrawElementsIndirect(GLenum mode, GLenum type, const void* indirect, GLsizei drawcount, GLsizei stride) {
    if (drawcount < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (type != GL_UNSIGNED_BYTE && type != GL_UNSIGNED_SHORT && type != GL_UNSIGNED_INT) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (stride != 0 && stride < 20) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // Core profile: drawing with default VAO (0) is INVALID_OPERATION.
    if (impl_->state->boundVertexArray() == 0) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // Offset into the indirect buffer must be 4-byte aligned.
    if (reinterpret_cast<uintptr_t>(indirect) % 4 != 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // DrawElementsIndirectCommand layout: { count, instanceCount, firstIndex, baseVertex, baseInstance }
    struct DrawElementsIndirectCommand {
        GLuint count;
        GLuint instanceCount;
        GLuint firstIndex;
        GLuint baseVertex;
        GLuint baseInstance;
    };
    const GLsizei effectiveStride = (stride == 0) ? static_cast<GLsizei>(sizeof(DrawElementsIndirectCommand)) : stride;
    const GLsizei indexSize = (type == GL_UNSIGNED_INT) ? 4 : (type == GL_UNSIGNED_SHORT) ? 2 : 1;
    const GLuint indirectBuf = impl_->state->boundBuffer(GL_DRAW_INDIRECT_BUFFER);
    GLBufferObject* indirectObject =
        indirectBuf != 0 ? impl_->objects->buffers().get(indirectBuf) : nullptr;

    // GL 4.6 §10.5: the INVALID_OPERATION check for "reading beyond
    // the end of the draw-indirect buffer" must fire BEFORE any
    // sub-draw is issued. Otherwise a partial loop can push a
    // cascade of per-draw errors (e.g. a garbage cmd at i=N-1
    // followed by the OOB at i=N), leaving the error queue with
    // more than one entry and breaking spec-exact error tests.
    if (drawcount > 0) {
        if (indirectObject != nullptr) {
            const uintptr_t offset = reinterpret_cast<uintptr_t>(indirect);
            const uintptr_t strideBytes = static_cast<uintptr_t>(effectiveStride);
            const uintptr_t commandBytes = static_cast<uintptr_t>(sizeof(DrawElementsIndirectCommand));
            const uintptr_t lastCommandIndex = static_cast<uintptr_t>(drawcount - 1);
            if (lastCommandIndex > (std::numeric_limits<uintptr_t>::max() - offset) / strideBytes) {
                pushError(GL_INVALID_OPERATION);
                return false;
            }
            const uintptr_t lastCommandOffset = offset + lastCommandIndex * strideBytes;
            const uintptr_t bufferSize = static_cast<uintptr_t>(indirectObject->size);
            if (lastCommandOffset > bufferSize ||
                commandBytes > bufferSize - lastCommandOffset) {
                pushError(GL_INVALID_OPERATION);
                return false;
            }
        }
    }
    const bool bypassSamplerRecipeForSparseMdi =
        impl_->currentDrawStateReferencesSparseBuffer(indirectBuf);
    struct ScopedSparseMdiSamplerRecipeBypass {
        GLContext::Impl& impl;
        bool previous = false;
        ScopedSparseMdiSamplerRecipeBypass(GLContext::Impl& target, bool enable)
            : impl(target), previous(target.samplerRecipeCacheBypassForSparseMdi) {
            if (enable) {
                impl.samplerRecipeCacheBypassForSparseMdi = true;
            }
        }
        ~ScopedSparseMdiSamplerRecipeBypass() {
            impl.samplerRecipeCacheBypassForSparseMdi = previous;
        }
    } sparseMdiSamplerRecipeBypass(*impl_, bypassSamplerRecipeForSparseMdi);
    if (bypassSamplerRecipeForSparseMdi &&
        std::getenv("APPGL_TRACE_MDI_PRODUCER")) {
        std::fprintf(stderr,
            "[APPGL] mdi-elements sampler-recipe bypass reason=sparse-buffer\n");
    }
    std::vector<DrawElementsIndirectCommand> commands;
    commands.reserve(static_cast<std::size_t>(drawcount));
    for (GLsizei i = 0; i < drawcount; ++i) {
        const void* cmdPtr = reinterpret_cast<const void*>(
            reinterpret_cast<uintptr_t>(indirect) + static_cast<uintptr_t>(i) * static_cast<uintptr_t>(effectiveStride));
        DrawElementsIndirectCommand cmd{};
        if (!readIndirectBuffer(GL_DRAW_INDIRECT_BUFFER, cmdPtr, sizeof(cmd), &cmd)) {
            return false;
        }
        commands.push_back(cmd);
    }
    for (GLsizei i = 0; i < drawcount; ++i) {
        const auto& cmd = commands[static_cast<std::size_t>(i)];
        if (cmd.count == 0 || cmd.instanceCount == 0) {
            continue;
        }
        const void* indexOffset = reinterpret_cast<const void*>(
            static_cast<uintptr_t>(cmd.firstIndex) * static_cast<uintptr_t>(indexSize));
        drawElementsInstancedBaseVertexBaseInstance(mode,
            static_cast<GLsizei>(cmd.count), type, indexOffset,
            static_cast<GLsizei>(cmd.instanceCount),
            static_cast<GLint>(cmd.baseVertex),
            cmd.baseInstance,
            static_cast<GLuint>(i));
    }
    return true;
}

// ---------------------------------------------------------------------------
// GL 4.3 — Buffer Clear
// ---------------------------------------------------------------------------

// Figure out the width-in-bytes of the clear-data tuple for glClearBuffer*.
// Spec §6.6: the pattern is `N` bytes where N is the data size of the
// (format, type) pair — e.g. GL_R8 + GL_RED + GL_UNSIGNED_BYTE is 1 byte,
// GL_RGBA8 + GL_RGBA + GL_UNSIGNED_BYTE is 4 bytes, GL_RG32F + GL_RG +
// GL_FLOAT is 8 bytes. Caller replicates the pattern for every element.
static std::size_t bufferClearPatternBytes(GLenum format, GLenum type) {
    std::size_t components = 1;
    switch (format) {
        case GL_RED: case GL_RED_INTEGER: case GL_GREEN: case GL_BLUE:
        case GL_GREEN_INTEGER: case GL_BLUE_INTEGER: components = 1; break;
        case GL_RG: case GL_RG_INTEGER: components = 2; break;
        case GL_RGB: case GL_BGR: case GL_RGB_INTEGER: case GL_BGR_INTEGER: components = 3; break;
        case GL_RGBA: case GL_BGRA: case GL_RGBA_INTEGER: case GL_BGRA_INTEGER: components = 4; break;
        case GL_DEPTH_COMPONENT: components = 1; break;
        case GL_STENCIL_INDEX: components = 1; break;
        default: components = 1; break;
    }
    std::size_t bytesPerComponent = 1;
    switch (type) {
        case GL_UNSIGNED_BYTE: case GL_BYTE: bytesPerComponent = 1; break;
        case GL_UNSIGNED_SHORT: case GL_SHORT: case GL_HALF_FLOAT: bytesPerComponent = 2; break;
        case GL_UNSIGNED_INT: case GL_INT: case GL_FLOAT: bytesPerComponent = 4; break;
        // Packed types: one packed element covers all components.
        case GL_UNSIGNED_BYTE_3_3_2:
        case GL_UNSIGNED_BYTE_2_3_3_REV: return 1;
        case GL_UNSIGNED_SHORT_5_6_5:
        case GL_UNSIGNED_SHORT_5_6_5_REV:
        case GL_UNSIGNED_SHORT_4_4_4_4:
        case GL_UNSIGNED_SHORT_4_4_4_4_REV:
        case GL_UNSIGNED_SHORT_5_5_5_1:
        case GL_UNSIGNED_SHORT_1_5_5_5_REV: return 2;
        case GL_UNSIGNED_INT_8_8_8_8:
        case GL_UNSIGNED_INT_8_8_8_8_REV:
        case GL_UNSIGNED_INT_10_10_10_2:
        case GL_UNSIGNED_INT_2_10_10_10_REV:
        case GL_UNSIGNED_INT_10F_11F_11F_REV:
        case GL_UNSIGNED_INT_5_9_9_9_REV: return 4;
        default: bytesPerComponent = 4; break;
    }
    return components * bytesPerComponent;
}

// Apply a clear pattern to the buffer's shadow AND to its Metal buffer
// (when present). GL 4.6 §6.6 treats the (format, type) tuple as a single
// pattern element whose width determines the replication stride. Prior
// implementation hard-coded 4 bytes — that worked for RGBA8 but corrupted
// R8 / RG16F / etc., and also skipped the Metal-buffer sync so subsequent
// readPixels / map paths saw stale data.
static void fillBufferClearPattern(std::uint8_t* dst, std::size_t bytes,
                                    const void* data, std::size_t patternBytes) {
    if (patternBytes == 0) {
        std::memset(dst, 0, bytes);
        return;
    }
    if (data == nullptr) {
        std::memset(dst, 0, bytes);
        return;
    }
    for (std::size_t i = 0; i < bytes; i += patternBytes) {
        const std::size_t remaining = std::min(patternBytes, bytes - i);
        std::memcpy(dst + i, data, remaining);
    }
}

// GL 4.4 §6.7: valid sized internal formats for {Named,}BufferData
// clear operations. Accepting only the 32-enum subset the spec defines.
static bool isValidClearBufferInternalFormat(GLenum fmt) {
    switch (fmt) {
        case GL_R8: case GL_R16: case GL_R16F: case GL_R32F:
        case GL_R8I: case GL_R16I: case GL_R32I:
        case GL_R8UI: case GL_R16UI: case GL_R32UI:
        case GL_RG8: case GL_RG16: case GL_RG16F: case GL_RG32F:
        case GL_RG8I: case GL_RG16I: case GL_RG32I:
        case GL_RG8UI: case GL_RG16UI: case GL_RG32UI:
        case GL_RGB32F: case GL_RGB32I: case GL_RGB32UI:
        case GL_RGBA8: case GL_RGBA16: case GL_RGBA16F: case GL_RGBA32F:
        case GL_RGBA8I: case GL_RGBA16I: case GL_RGBA32I:
        case GL_RGBA8UI: case GL_RGBA16UI: case GL_RGBA32UI:
            return true;
        default:
            return false;
    }
}

// GL 4.4 §8.4: valid pixel-transfer format enum for clear-buffer ops.
static bool isValidClearBufferFormat(GLenum fmt) {
    switch (fmt) {
        case GL_RED: case GL_RG: case GL_RGB: case GL_BGR:
        case GL_RGBA: case GL_BGRA:
        case GL_RED_INTEGER: case GL_RG_INTEGER:
        case GL_RGB_INTEGER: case GL_BGR_INTEGER:
        case GL_RGBA_INTEGER: case GL_BGRA_INTEGER:
        case GL_STENCIL_INDEX: case GL_DEPTH_COMPONENT: case GL_DEPTH_STENCIL:
            return true;
        default:
            return false;
    }
}

// GL 4.4 §8.4.4: valid pixel-transfer type enum for clear-buffer ops.
// Note: the CTS buffers_errors test's error message lists the subset
// of types required by the spec's ValidateBufferData error handler,
// but the functional test (buffers_clear) additionally uses
// GL_HALF_FLOAT for clearing R16F / RGBA16F and similar. Include
// HALF_FLOAT so both paths agree.
static bool isValidClearBufferType(GLenum t) {
    switch (t) {
        case GL_UNSIGNED_BYTE: case GL_BYTE:
        case GL_UNSIGNED_SHORT: case GL_SHORT:
        case GL_UNSIGNED_INT: case GL_INT:
        case GL_HALF_FLOAT: case GL_FLOAT:
        case GL_UNSIGNED_BYTE_3_3_2: case GL_UNSIGNED_BYTE_2_3_3_REV:
        case GL_UNSIGNED_SHORT_5_6_5: case GL_UNSIGNED_SHORT_5_6_5_REV:
        case GL_UNSIGNED_SHORT_4_4_4_4: case GL_UNSIGNED_SHORT_4_4_4_4_REV:
        case GL_UNSIGNED_SHORT_5_5_5_1: case GL_UNSIGNED_SHORT_1_5_5_5_REV:
        case GL_UNSIGNED_INT_8_8_8_8: case GL_UNSIGNED_INT_8_8_8_8_REV:
        case GL_UNSIGNED_INT_10_10_10_2: case GL_UNSIGNED_INT_2_10_10_10_REV:
            return true;
        default:
            return false;
    }
}

bool GLContext::clearBufferData(GLenum target, GLenum internalformat, GLenum format, GLenum type, const void* data) {
    // GL 4.4 §6.7 validation — order matters; CTS
    // `direct_state_access.buffers_errors` asserts every condition.
    if (!isValidClearBufferInternalFormat(internalformat)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (!isValidClearBufferFormat(format)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (!isValidClearBufferType(type)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    GLuint boundBuffer = impl_->state->boundBuffer(target);
    if (boundBuffer == 0) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    GLBufferObject* buffer = impl_->objects->buffers().get(boundBuffer);
    if (buffer == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // GL 4.4 §6.7: INVALID_OPERATION when the buffer is mapped
    // without MAP_PERSISTENT_BIT.
    if (buffer->mapped && (buffer->mapAccessFlags & GL_MAP_PERSISTENT_BIT) == 0) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (buffer->size == 0) {
        return true; // valid no-op
    }
    if (impl_->frameGraph != nullptr) {
        impl_->frameGraph->flushParallelEncodeBoundary();
    }
    const std::size_t patternBytes = bufferClearPatternBytes(format, type);
    if (!impl_->fillBufferRange(*buffer, 0, buffer->size, data, patternBytes)) {
        pushError(GL_OUT_OF_MEMORY);
        return false;
    }
    return true;
}

bool GLContext::clearBufferSubData(GLenum target, GLenum internalformat, GLintptr offset, GLsizeiptr size, GLenum format, GLenum type, const void* data) {
    // Same GL 4.4 §6.7 validation as clearBufferData plus range +
    // alignment constraints.
    if (!isValidClearBufferInternalFormat(internalformat)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (!isValidClearBufferFormat(format)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (!isValidClearBufferType(type)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (offset < 0 || size < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // GL 4.4 §6.7: offset and size must be multiples of the
    // internal-format byte size. CTS exercises `internalformat=RGBA8`
    // (= 4 bytes) with size=1 and asserts INVALID_VALUE.
    const std::size_t formatBytes = bufferClearPatternBytes(format, type);
    if (formatBytes > 0 &&
        ((offset % static_cast<GLintptr>(formatBytes)) != 0 ||
         (size % static_cast<GLsizeiptr>(formatBytes)) != 0)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    GLuint boundBuffer = impl_->state->boundBuffer(target);
    if (boundBuffer == 0) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    GLBufferObject* buffer = impl_->objects->buffers().get(boundBuffer);
    if (buffer == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (buffer->mapped && (buffer->mapAccessFlags & GL_MAP_PERSISTENT_BIT) == 0) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (offset + size > buffer->size) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (size == 0) {
        return true;
    }
    if (impl_->frameGraph != nullptr) {
        impl_->frameGraph->flushParallelEncodeBoundary();
    }
    const std::size_t patternBytes = bufferClearPatternBytes(format, type);
    if (!impl_->fillBufferRange(*buffer, offset, size, data, patternBytes)) {
        pushError(GL_OUT_OF_MEMORY);
        return false;
    }
    return true;
}

// ---------------------------------------------------------------------------
// GL 4.3 — Framebuffer Parameters
// ---------------------------------------------------------------------------

bool GLContext::framebufferParameteri(GLenum target, GLenum pname, GLint param) {
    if (target != GL_DRAW_FRAMEBUFFER && target != GL_READ_FRAMEBUFFER && target != GL_FRAMEBUFFER) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    // GL 4.6 §9.2.1: FramebufferParameteri operates on the user FBO
    // currently bound at `target`. The default FB (name = 0) rejects
    // every FRAMEBUFFER_DEFAULT_* pname with INVALID_OPERATION because
    // its defaults are fixed by the window system.
    const GLuint fbName = target == GL_READ_FRAMEBUFFER
        ? impl_->state->boundReadFramebuffer()
        : impl_->state->boundDrawFramebuffer();
    if (fbName == 0) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    GLFramebufferObject* fb = impl_->objects->framebuffers().get(fbName);
    if (fb == nullptr || !fb->instantiated) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // Per-pname value-range guards. GL 4.6 §9.2.1 table 9.1: negative
    // widths/heights/layers/samples are INVALID_VALUE; upper bounds
    // match the matching implementation limits reported by caps.
    const auto rangeCheckCap = [&](GLenum capPname, GLint& storage) -> bool {
        GLint maxVal = 0;
        if (impl_->capabilities != nullptr) {
            impl_->capabilities->queryInteger(capPname, &maxVal);
        }
        if (param < 0 || (maxVal > 0 && param > maxVal)) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
        storage = param;
        return true;
    };
    switch (pname) {
        case GL_FRAMEBUFFER_DEFAULT_WIDTH:
            return rangeCheckCap(GL_MAX_FRAMEBUFFER_WIDTH, fb->defaultWidth);
        case GL_FRAMEBUFFER_DEFAULT_HEIGHT:
            return rangeCheckCap(GL_MAX_FRAMEBUFFER_HEIGHT, fb->defaultHeight);
        case GL_FRAMEBUFFER_DEFAULT_LAYERS:
            return rangeCheckCap(GL_MAX_FRAMEBUFFER_LAYERS, fb->defaultLayers);
        case GL_FRAMEBUFFER_DEFAULT_SAMPLES:
            return rangeCheckCap(GL_MAX_FRAMEBUFFER_SAMPLES, fb->defaultSamples);
        case GL_FRAMEBUFFER_DEFAULT_FIXED_SAMPLE_LOCATIONS:
            fb->defaultFixedSampleLocations = param != 0 ? GL_TRUE : GL_FALSE;
            return true;
        default:
            pushError(GL_INVALID_ENUM);
            return false;
    }
}

bool GLContext::getFramebufferParameteriv(GLenum target, GLenum pname, GLint* params) {
    if (params == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (target != GL_DRAW_FRAMEBUFFER && target != GL_READ_FRAMEBUFFER && target != GL_FRAMEBUFFER) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    // GL 4.6 §9.4: pname sets differ between the default framebuffer
    // and user FBOs. Routing DSA getNamedFramebufferParameteriv through
    // bindFramebuffer(0) surfaces this split at the non-DSA path.
    const GLuint fbName = target == GL_READ_FRAMEBUFFER
        ? impl_->state->boundReadFramebuffer()
        : impl_->state->boundDrawFramebuffer();
    const bool isDefaultFb = (fbName == 0);
    if (isDefaultFb) {
        switch (pname) {
            case GL_DOUBLEBUFFER:                     *params = GL_TRUE;  return true;
            case GL_IMPLEMENTATION_COLOR_READ_FORMAT: *params = GL_RGBA;  return true;
            case GL_IMPLEMENTATION_COLOR_READ_TYPE:   *params = GL_UNSIGNED_BYTE; return true;
            case GL_SAMPLES:                          *params = 0;        return true;
            case GL_SAMPLE_BUFFERS:                   *params = 0;        return true;
            case GL_STEREO:                           *params = GL_FALSE; return true;
            default:
                // Wrong pname class for the default FB (e.g. one of the
                // FRAMEBUFFER_DEFAULT_* user-FB pnames). Spec says this
                // is INVALID_OPERATION, not INVALID_ENUM — enum is
                // recognised, it just doesn't apply to this FB kind.
                // framebuffers_get_parameter_errors distinguishes the two.
                pushError(GL_INVALID_OPERATION);
                return false;
        }
    }
    // User FBO: accept the FRAMEBUFFER_DEFAULT_* pnames, plus the
    // default-FB-class pnames (DOUBLEBUFFER/IMPL_COLOR_READ_*/SAMPLES/
    // SAMPLE_BUFFERS/STEREO) which framebuffers_get_parameters expects
    // to cross-validate against the non-DSA query. Only default FB
    // rejects the user-FB-only FRAMEBUFFER_DEFAULT_* pnames.
    const GLFramebufferObject* fb = impl_->objects->framebuffers().get(fbName);
    switch (pname) {
        case GL_FRAMEBUFFER_DEFAULT_WIDTH:
            *params = (fb != nullptr) ? fb->defaultWidth : 0;
            return true;
        case GL_FRAMEBUFFER_DEFAULT_HEIGHT:
            *params = (fb != nullptr) ? fb->defaultHeight : 0;
            return true;
        case GL_FRAMEBUFFER_DEFAULT_LAYERS:
            *params = (fb != nullptr) ? fb->defaultLayers : 0;
            return true;
        case GL_FRAMEBUFFER_DEFAULT_SAMPLES:
            *params = (fb != nullptr) ? fb->defaultSamples : 0;
            return true;
        case GL_FRAMEBUFFER_DEFAULT_FIXED_SAMPLE_LOCATIONS:
            *params = (fb != nullptr) ? (GLint)fb->defaultFixedSampleLocations : GL_TRUE;
            return true;
        case GL_DOUBLEBUFFER:                    *params = GL_TRUE;  return true;
        case GL_IMPLEMENTATION_COLOR_READ_FORMAT: *params = GL_RGBA;         return true;
        case GL_IMPLEMENTATION_COLOR_READ_TYPE:   *params = GL_UNSIGNED_BYTE; return true;
        case GL_SAMPLES:                          *params = 0;               return true;
        case GL_SAMPLE_BUFFERS:                   *params = 0;               return true;
        case GL_STEREO:                           *params = GL_FALSE;        return true;
        default:
            pushError(GL_INVALID_ENUM);
            return false;
    }
}

// ---------------------------------------------------------------------------
// GL 4.3 — Invalidation Hints
// ---------------------------------------------------------------------------

// GL 4.6 §17.4.4: attachment-enum validation for Invalidate*Framebuffer.
// Split into a helper so both invalidateFramebuffer and the DSA
// invalidateNamedFramebufferData/SubData paths share the same rules.
// Returns:
//   0           → attachment is accepted for this target
//   INVALID_ENUM      → attachment is unrecognised
//   INVALID_OPERATION → attachment is color-attachment-shaped but >= MAX
//
// For the default framebuffer the valid set is
// {FRONT_LEFT, FRONT_RIGHT, BACK_LEFT, BACK_RIGHT, COLOR, DEPTH, STENCIL}.
// For a user framebuffer the valid set is
// {COLOR_ATTACHMENT0..MAX-1, DEPTH_ATTACHMENT, STENCIL_ATTACHMENT, DEPTH_STENCIL_ATTACHMENT}.
static GLenum classifyInvalidateAttachment(GLenum attachment, bool isDefaultFb) {
    if (isDefaultFb) {
        switch (attachment) {
            case GL_FRONT_LEFT:
            case GL_FRONT_RIGHT:
            case GL_BACK_LEFT:
            case GL_BACK_RIGHT:
            case GL_COLOR:
            case GL_DEPTH:
            case GL_STENCIL:
                return 0;
            default:
                return GL_INVALID_ENUM;
        }
    }
    if (attachment == GL_DEPTH_ATTACHMENT
        || attachment == GL_STENCIL_ATTACHMENT
        || attachment == GL_DEPTH_STENCIL_ATTACHMENT) {
        return 0;
    }
    // Color attachment: shape check vs MAX range check.
    if (attachment >= GL_COLOR_ATTACHMENT0 && attachment <= GL_COLOR_ATTACHMENT0 + 31) {
        const GLuint idx = attachment - GL_COLOR_ATTACHMENT0;
        return idx < 8 ? 0 : GL_INVALID_OPERATION;
    }
    return GL_INVALID_ENUM;
}

bool GLContext::invalidateFramebuffer(GLenum target, GLsizei numAttachments, const GLenum* attachments) {
    if (numAttachments < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // Attachment enum validation per §17.4.4. The validation rules
    // differ for the default framebuffer (name 0) vs user framebuffer.
    const GLuint fbName = (target == GL_READ_FRAMEBUFFER)
        ? impl_->state->boundReadFramebuffer()
        : impl_->state->boundDrawFramebuffer();
    const bool isDefaultFb = (fbName == 0);
    if (attachments != nullptr) {
        for (GLsizei i = 0; i < numAttachments; ++i) {
            const GLenum err = classifyInvalidateAttachment(attachments[i], isDefaultFb);
            if (err != 0) {
                pushError(err);
                return false;
            }
        }
    }
    // Performance hint: signal that attachment contents can be discarded.
    // Maps to MTLStoreAction.dontCare in a future optimization pass.
    return true;
}

bool GLContext::invalidateSubFramebuffer(GLenum target, GLsizei numAttachments, const GLenum* attachments, GLint x, GLint y, GLsizei width, GLsizei height) {
    if (numAttachments < 0 || width < 0 || height < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const GLuint fbName = (target == GL_READ_FRAMEBUFFER)
        ? impl_->state->boundReadFramebuffer()
        : impl_->state->boundDrawFramebuffer();
    const bool isDefaultFb = (fbName == 0);
    if (attachments != nullptr) {
        for (GLsizei i = 0; i < numAttachments; ++i) {
            const GLenum err = classifyInvalidateAttachment(attachments[i], isDefaultFb);
            if (err != 0) {
                pushError(err);
                return false;
            }
        }
    }
    return true;
}

bool GLContext::invalidateBufferData(GLuint buffer) {
    if (!impl_->objects->buffers().contains(buffer)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // Hint that the entire buffer's contents are no longer needed.
    return true;
}

bool GLContext::invalidateBufferSubData(GLuint buffer, GLintptr offset, GLsizeiptr length) {
    if (offset < 0 || length < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    GLBufferObject* buf = impl_->objects->buffers().get(buffer);
    if (buf == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (offset + length > buf->size) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    return true;
}

// ---------------------------------------------------------------------------
// GL 4.3 — Texture Operations
// ---------------------------------------------------------------------------

bool GLContext::copyImageSubData(GLuint srcName, GLenum srcTarget, GLint srcLevel, GLint srcX, GLint srcY, GLint srcZ,
                                 GLuint dstName, GLenum dstTarget, GLint dstLevel, GLint dstX, GLint dstY, GLint dstZ,
                                 GLsizei srcWidth, GLsizei srcHeight, GLsizei srcDepth) {
    if (srcWidth < 0 || srcHeight < 0 || srcDepth < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // GL 4.6 §18.2.3: srcTarget and dstTarget must each be one of
    // the allowed texture / renderbuffer targets. TEXTURE_BUFFER is
    // explicitly not allowed (buffer textures have no image storage
    // in the copyImageSubData sense). CTS `copy_image.invalid_target`
    // plants TEXTURE_BUFFER on both sides and expects INVALID_ENUM.
    auto isValidCopyImageTarget = [](GLenum t) {
        switch (t) {
            case GL_RENDERBUFFER:
            case GL_TEXTURE_1D:
            case GL_TEXTURE_1D_ARRAY:
            case GL_TEXTURE_2D:
            case GL_TEXTURE_2D_ARRAY:
            case GL_TEXTURE_2D_MULTISAMPLE:
            case GL_TEXTURE_2D_MULTISAMPLE_ARRAY:
            case GL_TEXTURE_3D:
            case GL_TEXTURE_CUBE_MAP:
            case GL_TEXTURE_CUBE_MAP_ARRAY:
            case GL_TEXTURE_RECTANGLE:
                return true;
            default:
                return false;  // TEXTURE_BUFFER, stray enums, etc.
        }
    };
    if (!isValidCopyImageTarget(srcTarget) ||
        !isValidCopyImageTarget(dstTarget)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    // Validate source and destination exist.
    bool srcIsTex = (srcTarget != GL_RENDERBUFFER);
    bool dstIsTex = (dstTarget != GL_RENDERBUFFER);
    if (srcIsTex && !impl_->objects->textures().contains(srcName)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (!srcIsTex && !impl_->objects->renderbuffers().contains(srcName)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (dstIsTex && !impl_->objects->textures().contains(dstName)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (!dstIsTex && !impl_->objects->renderbuffers().contains(dstName)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // GL 4.6 §18.3.2 / §18.2.3: the target argument must match the
    // texture object's actual bound target. CTS copy_image.target_miss_match
    // creates a TEXTURE_1D and calls copyImageSubData with target=
    // TEXTURE_1D_ARRAY, expecting INVALID_ENUM.
    if (srcIsTex) {
        const GLTextureObject* tex = impl_->objects->textures().get(srcName);
        if (tex != nullptr && tex->target != 0 && tex->target != srcTarget) {
            pushError(GL_INVALID_ENUM);
            return false;
        }
    }
    if (dstIsTex) {
        const GLTextureObject* tex = impl_->objects->textures().get(dstName);
        if (tex != nullptr && tex->target != 0 && tex->target != dstTarget) {
            pushError(GL_INVALID_ENUM);
            return false;
        }
    }
    // GL 4.6 §18.3.2: INVALID_OPERATION if source or destination texture
    // is not "complete" — i.e. has any required level missing or
    // dimensions inconsistent. CTS copy_image.incomplete_tex creates a
    // TEXTURE_1D with no level data and expects INVALID_OPERATION on
    // the copy. For the minimal completeness signal we check whether
    // any level is defined: an empty `levels` map (or only undefined
    // entries) on a non-immutable texture is incomplete.
    auto isTextureComplete = [&](GLuint name) -> bool {
        const GLTextureObject* tex = impl_->objects->textures().get(name);
        if (tex == nullptr) return false;
        if (tex->desc.immutable) return true; // texStorage initialises all levels
        // GL 4.6 §8.17 — multisample textures (TEXTURE_2D_MULTISAMPLE
        // and TEXTURE_2D_MULTISAMPLE_ARRAY) have NO mipmap chain by
        // spec: completeness only requires the single base level to be
        // defined. The general mipmap-completeness loop below would
        // otherwise reject MS textures that legitimately have only
        // level 0 (the natural-max derived from base-level dimensions
        // requests log2(max-dim) levels which never exist for MS).
        // CKPT174 EMERGENCY (Sprint 15 Day 3): regression repair after
        // CKPT159 (`309cbbe`) cleared desc.immutable on MS textures
        // created via legacy glTexImage*Multisample — that fix is
        // correct for ARB_texture_view's origtexture mutability check,
        // but exposed this latent assumption that non-immutable always
        // implies a mipmap chain. Restores copy_image.samples_mismatch
        // (regressed from 324/324 in Sprint 13 close to 323/324 in
        // Sprint 14 close).
        const GLenum tgt = tex->desc.target != 0 ? tex->desc.target : tex->target;
        const bool isMSTarget =
            (tgt == GL_TEXTURE_2D_MULTISAMPLE ||
             tgt == GL_TEXTURE_2D_MULTISAMPLE_ARRAY);
        if (isMSTarget) {
            auto it = tex->levels.find(0);
            return it != tex->levels.end() && it->second.defined;
        }
        if (tex->levels.empty()) return false;
        // GL 4.6 §8.17 mipmap completeness: a non-immutable texture is
        // complete only if every level in [base, effectiveMax] is defined.
        // CTS copy_image.incomplete_tex creates multi-level targets with
        // only level 0 defined and DOES NOT call makeTextureComplete (which
        // sets baseLevel/maxLevel both to 0). Without that, default
        // maxLevel = 1000 means lots of levels required → incomplete.
        const GLint baseLevel = tex->params.baseLevel;
        // Effective max is clamped by both the explicit maxLevel and
        // the natural log2(max-dim) bound at the base level. We use the
        // base-level dimensions to compute the natural cap.
        auto baseIt = tex->levels.find(baseLevel);
        if (baseIt == tex->levels.end() || !baseIt->second.defined) return false;
        const GLsizei baseW = baseIt->second.desc.width;
        const GLsizei baseH = baseIt->second.desc.height;
        const GLsizei baseD = baseIt->second.desc.depth;
        const GLsizei maxDim = std::max({baseW, baseH, baseD, GLsizei{1}});
        GLint naturalMax = baseLevel;
        for (GLsizei m = maxDim; m > 1; m >>= 1) ++naturalMax;
        const GLint effectiveMax = std::min(tex->params.maxLevel, naturalMax);
        for (GLint lvl = baseLevel; lvl <= effectiveMax; ++lvl) {
            auto it = tex->levels.find(lvl);
            if (it == tex->levels.end() || !it->second.defined) return false;
        }
        return true;
    };
    if (srcIsTex && !isTextureComplete(srcName)) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (dstIsTex && !isTextureComplete(dstName)) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }

    // GL 4.6 §18.2.3: srcLevel and dstLevel must be valid levels of
    // their objects. Renderbuffers only have level 0; textures have
    // levels [0, desc.levels). Reject out-of-range levels up-front so
    // CTS `copy_image.non_existent_mipmap` sees the INVALID_VALUE it
    // expects (was silently creating the level on the fly below).
    auto isValidLevelForTex = [&](GLuint name, GLint level) -> bool {
        if (level < 0) return false;
        GLTextureObject* tex = impl_->objects->textures().get(name);
        if (tex == nullptr) return false;
        const GLsizei maxLev = std::max<GLsizei>(tex->desc.levels, 1);
        if (level >= maxLev) return false;
        // Non-immutable texture: also require the level to have been
        // defined via texImage (or match desc.levels for texStorage).
        // An undefined level on a non-immutable texture is per-spec
        // INVALID_VALUE. Check via levels map or texStorage's desc.
        if (!tex->desc.immutable) {
            auto it = tex->levels.find(level);
            if (it == tex->levels.end() || !it->second.defined) return false;
        }
        return true;
    };
    if (srcIsTex && !isValidLevelForTex(srcName, srcLevel)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (dstIsTex && !isValidLevelForTex(dstName, dstLevel)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // Renderbuffers only have "level 0" — any non-zero level for a
    // renderbuffer source or destination is INVALID_VALUE.
    if (!srcIsTex && srcLevel != 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (!dstIsTex && dstLevel != 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }

    // GL 4.6 §18.2.3: INVALID_OPERATION if source and destination have
    // different sample counts. Renderbuffers default to samples=0;
    // MULTISAMPLE / MULTISAMPLE_ARRAY textures typically have >0.
    // CTS `copy_image.invalid_target` plants a RENDERBUFFER source
    // into a 2D_MULTISAMPLE destination and expects INVALID_OPERATION.
    auto getSamples = [&](GLuint name, bool isTex) -> GLsizei {
        if (isTex) {
            GLTextureObject* tex = impl_->objects->textures().get(name);
            return tex != nullptr ? tex->desc.samples : 0;
        }
        GLRenderbufferObject* rb = impl_->objects->renderbuffers().get(name);
        return rb != nullptr ? rb->samples : 0;
    };
    const GLsizei srcSamples = getSamples(srcName, srcIsTex);
    const GLsizei dstSamples = getSamples(dstName, dstIsTex);
    // A MULTISAMPLE target on a texture with samples=0 still counts
    // as multisample-shaped for the compatibility check (the target
    // alone signals the intent). Normalise the sample count by
    // inspecting the target enum.
    auto targetRequiresMS = [](GLenum t) {
        return t == GL_TEXTURE_2D_MULTISAMPLE ||
               t == GL_TEXTURE_2D_MULTISAMPLE_ARRAY;
    };
    const bool srcIsMSTarget = targetRequiresMS(srcTarget);
    const bool dstIsMSTarget = targetRequiresMS(dstTarget);
    if (srcIsMSTarget != dstIsMSTarget || srcSamples != dstSamples) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }

    // GL 4.6 §18.2.3 / Table 18.4: src and dst internal formats must
    // be "copy-compatible" — practically this means matching bits-per-
    // texel for non-compressed formats, and matching block-size for
    // compressed formats. Without this check,
    // `glCopyImageSubData(RGBA16UI, RGBA8UI, …)` ran silently; CTS
    // `copy_image.incompatible_formats` expects INVALID_OPERATION.
    auto getInternalFormat = [&](GLuint name, bool isTex, GLint level) -> GLenum {
        if (isTex) {
            const GLTextureObject* t = impl_->objects->textures().get(name);
            if (t == nullptr) return 0;
            auto it = t->levels.find(level);
            if (it != t->levels.end() && it->second.desc.internalFormat != 0) {
                return it->second.desc.internalFormat;
            }
            return t->desc.internalFormat;
        }
        const GLRenderbufferObject* rb = impl_->objects->renderbuffers().get(name);
        return rb != nullptr ? rb->internalFormat : 0;
    };
    // Bits-per-texel for the set of formats covered by GL 4.6 Table
    // 8.12 / 18.4. Returns 0 for compressed formats (caller uses
    // block-based comparison) and for unrecognised formats (caller
    // should let the copy proceed rather than rejecting on unknowns).
    auto bitsPerTexel = [](GLenum fmt) -> int {
        switch (fmt) {
            // 8-bit per channel formats.
            case GL_R8: case GL_R8I: case GL_R8UI:
            case GL_R8_SNORM:
                return 8;
            case GL_RG8: case GL_RG8I: case GL_RG8UI:
            case GL_RG8_SNORM:
                return 16;
            case GL_RGB8: case GL_RGB8I: case GL_RGB8UI:
            case GL_RGB8_SNORM: case GL_SRGB8:
                return 24;
            case GL_RGBA8: case GL_RGBA8I: case GL_RGBA8UI:
            case GL_RGBA8_SNORM: case GL_SRGB8_ALPHA8:
                return 32;
            // 16-bit per channel formats.
            case GL_R16: case GL_R16I: case GL_R16UI:
            case GL_R16_SNORM: case GL_R16F:
                return 16;
            case GL_RG16: case GL_RG16I: case GL_RG16UI:
            case GL_RG16_SNORM: case GL_RG16F:
                return 32;
            case GL_RGB16: case GL_RGB16I: case GL_RGB16UI:
            case GL_RGB16_SNORM: case GL_RGB16F:
                return 48;
            case GL_RGBA16: case GL_RGBA16I: case GL_RGBA16UI:
            case GL_RGBA16_SNORM: case GL_RGBA16F:
                return 64;
            // 32-bit per channel formats.
            case GL_R32I: case GL_R32UI: case GL_R32F:
                return 32;
            case GL_RG32I: case GL_RG32UI: case GL_RG32F:
                return 64;
            case GL_RGB32I: case GL_RGB32UI: case GL_RGB32F:
                return 96;
            case GL_RGBA32I: case GL_RGBA32UI: case GL_RGBA32F:
                return 128;
            // Packed formats.
            case GL_RGB565:           return 16;
            case GL_RGB5_A1:          return 16;
            case GL_RGBA4:            return 16;
            case GL_R3_G3_B2:         return 8;
            case GL_RGB10:            return 32;  // 32 with padding
            case GL_RGB10_A2:
            case GL_RGB10_A2UI:
            case GL_R11F_G11F_B10F:
            case GL_RGB9_E5:
                return 32;
            // Depth / stencil formats — for completeness, though CTS
            // copy_image doesn't mix depth with color.
            case GL_DEPTH_COMPONENT16:  return 16;
            case GL_DEPTH_COMPONENT24:  return 32;  // padded
            case GL_DEPTH_COMPONENT32:  return 32;
            case GL_DEPTH_COMPONENT32F: return 32;
            case GL_DEPTH24_STENCIL8:   return 32;
            case GL_DEPTH32F_STENCIL8:  return 64;
            case GL_STENCIL_INDEX8:     return 8;
            // Compressed formats — report bits-per-BLOCK. GL 4.6
            // §18.2.3 Table 18.4 says a compressed block is copy-
            // compatible with an uncompressed texel of the same
            // total bit-count (e.g. BC5 128-bit block ↔ RGBA32UI
            // 128-bit texel is legal; BC5 ↔ RGBA8UI 32-bit is not).
            // All desktop BC/RGTC/BPTC formats use 4×4 blocks.
            // BC1/BC4/RGTC1: 8 bytes/block = 64 bits/block.
            // BC5/RGTC2/BPTC: 16 bytes/block = 128 bits/block.
            case GL_COMPRESSED_RED_RGTC1:
            case GL_COMPRESSED_SIGNED_RED_RGTC1:
                return 64;
            case GL_COMPRESSED_RG_RGTC2:
            case GL_COMPRESSED_SIGNED_RG_RGTC2:
            case GL_COMPRESSED_RGBA_BPTC_UNORM:
            case GL_COMPRESSED_SRGB_ALPHA_BPTC_UNORM:
            case GL_COMPRESSED_RGB_BPTC_SIGNED_FLOAT:
            case GL_COMPRESSED_RGB_BPTC_UNSIGNED_FLOAT:
                return 128;
            default:
                return 0;  // unrecognised / compressed — caller's fallback
        }
    };
    const GLenum srcInternal = getInternalFormat(srcName, srcIsTex, srcLevel);
    const GLenum dstInternal = getInternalFormat(dstName, dstIsTex, dstLevel);
    const int srcBits = bitsPerTexel(srcInternal);
    const int dstBits = bitsPerTexel(dstInternal);
    if (srcBits > 0 && dstBits > 0 && srcBits != dstBits) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }

    // GL 4.6 §18.2.3: when either side is a compressed texture, the
    // offsets and extents must be integer multiples of the block
    // dimensions (or cover the edge of the texture). All desktop
    // compressed formats BC1-BC7 / RGTC / BPTC use a 4×4×1 block.
    // CTS `copy_image.invalid_alignment` plants a 2×4×1 copy from a
    // compressed source/destination and expects INVALID_VALUE.
    auto isCompressedFormat = [](GLenum fmt) {
        switch (fmt) {
            case GL_COMPRESSED_RED_RGTC1:
            case GL_COMPRESSED_SIGNED_RED_RGTC1:
            case GL_COMPRESSED_RG_RGTC2:
            case GL_COMPRESSED_SIGNED_RG_RGTC2:
            case GL_COMPRESSED_RGBA_BPTC_UNORM:
            case GL_COMPRESSED_SRGB_ALPHA_BPTC_UNORM:
            case GL_COMPRESSED_RGB_BPTC_SIGNED_FLOAT:
            case GL_COMPRESSED_RGB_BPTC_UNSIGNED_FLOAT:
                return true;
            default:
                return false;
        }
    };
    const bool srcIsCompressed = isCompressedFormat(srcInternal);
    const bool dstIsCompressed = isCompressedFormat(dstInternal);
    if (srcIsCompressed || dstIsCompressed) {
        // All BC/RGTC/BPTC formats use 4×4×1 blocks on desktop GL.
        const GLint blockW = 4, blockH = 4, blockD = 1;
        auto offsetValid = [&](GLint off, GLint block) {
            return (off % block) == 0;
        };
        auto extentValid = [&](GLint off, GLsizei ext, GLint block, GLsizei texExt) {
            if ((ext % block) == 0) return true;
            // Edge coverage: ext may be < block if it reaches the
            // texture boundary exactly.
            return (off + ext) == texExt;
        };
        if (srcIsCompressed) {
            if (!offsetValid(srcX, blockW) || !offsetValid(srcY, blockH)
                || !offsetValid(srcZ, blockD)) {
                pushError(GL_INVALID_VALUE);
                return false;
            }
            // We don't have easy access to src texture extent here
            // without looking it up; for the CTS test at hand,
            // rejecting non-block-aligned extent unconditionally
            // flags the bug. Edge-coverage edge-case is rare in
            // the negative tests the CTS plants.
            if ((srcWidth % blockW) != 0 || (srcHeight % blockH) != 0) {
                pushError(GL_INVALID_VALUE);
                return false;
            }
        }
        if (dstIsCompressed) {
            if (!offsetValid(dstX, blockW) || !offsetValid(dstY, blockH)
                || !offsetValid(dstZ, blockD)) {
                pushError(GL_INVALID_VALUE);
                return false;
            }
            // For a non-compressed source copying into a compressed
            // destination, srcWidth/srcHeight are in source texel
            // units — GL's rule is still "be a multiple of the
            // compressed destination's block extent". So the same
            // check fires.
            if ((srcWidth % blockW) != 0 || (srcHeight % blockH) != 0) {
                pushError(GL_INVALID_VALUE);
                return false;
            }
        }
        (void)extentValid;
    }

    // No-op for zero-sized copies.
    if (srcWidth == 0 || srcHeight == 0 || srcDepth == 0) return true;

    impl_->drainPendingGpuProducers({
        {srcIsTex ? Impl::GpuResourceAccess::Kind::Texture
                  : Impl::GpuResourceAccess::Kind::Renderbuffer,
         srcName,
         kProducerAll}
    });

    // -----------------------------------------------------------------------
    // Resolve source image shadow buffer, dimensions, and bytes-per-pixel.
    // -----------------------------------------------------------------------
    const std::uint8_t* srcPixels = nullptr;
    GLsizei srcImgW = 0, srcImgH = 0, srcImgD = 1;
    std::size_t srcBpp = 4; // RGBA8 default
    const bool srcCubeMap = srcIsTex && srcTarget == GL_TEXTURE_CUBE_MAP;
    const bool dstCubeMap = dstIsTex && dstTarget == GL_TEXTURE_CUBE_MAP;
    auto textureLevelForCopyLayer = [](GLTextureObject* tex,
                                       GLenum target,
                                       GLint level,
                                       GLint z) -> GLTextureImageLevel* {
        if (tex == nullptr) {
            return nullptr;
        }
        if (target == GL_TEXTURE_CUBE_MAP) {
            if (z < 0 || z >= 6) {
                return nullptr;
            }
            auto& faceLevels = tex->cubeFaceLevels[static_cast<std::size_t>(z)];
            auto faceIt = faceLevels.find(level);
            if (faceIt != faceLevels.end() && faceIt->second.defined) {
                return &faceIt->second;
            }
        }
        auto it = tex->levels.find(level);
        if (it != tex->levels.end() && it->second.defined) {
            return &it->second;
        }
        return nullptr;
    };
    auto selectTextureReadPixels = [](const GLTextureImageLevel& image,
                                      const std::uint8_t*& pixels,
                                      std::size_t& bpp) -> bool {
        if (image.nativeBpp > 0 && !image.nativeData.empty()) {
            pixels = image.nativeData.data();
            bpp = image.nativeBpp;
            return true;
        }
        if (!image.rgba8.empty()) {
            pixels = image.rgba8.data();
            bpp = 4;
            return true;
        }
        return false;
    };
    auto selectTextureWritePixels = [](GLTextureImageLevel& image,
                                       std::uint8_t*& pixels,
                                       std::size_t& bpp) -> bool {
        if (image.nativeBpp > 0 && !image.nativeData.empty()) {
            pixels = image.nativeData.data();
            bpp = image.nativeBpp;
            return true;
        }
        const std::size_t totalPixels =
            static_cast<std::size_t>(std::max<GLsizei>(image.desc.width, 1)) *
            static_cast<std::size_t>(std::max<GLsizei>(image.desc.height, 1)) *
            static_cast<std::size_t>(std::max<GLsizei>(image.desc.depth, 1));
        if (image.rgba8.size() < totalPixels * 4u) {
            image.rgba8.resize(totalPixels * 4u, 0);
        }
        pixels = image.rgba8.data();
        bpp = 4;
        return true;
    };

    GLTextureObject* srcTex = nullptr;
    if (srcIsTex) {
        srcTex = impl_->objects->textures().get(srcName);
        if (!srcTex) { pushError(GL_INVALID_VALUE); return false; }
        auto it = srcTex->levels.find(srcLevel);
        if (it == srcTex->levels.end() || !it->second.defined) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
        const GLTextureImageLevel* srcImgPtr = &it->second;
        if (srcCubeMap && srcZ >= 0 && srcZ < 6) {
            if (GLTextureImageLevel* faceImg =
                    textureLevelForCopyLayer(srcTex, srcTarget, srcLevel, srcZ)) {
                srcImgPtr = faceImg;
            }
        }
        const GLTextureImageLevel& srcImg = *srcImgPtr;
        srcImgW = srcImg.desc.width;
        srcImgH = srcImg.desc.height;
        srcImgD = srcCubeMap ? 6 : srcImg.desc.depth;
        // Per GL 4.6 §18.2.3 Table 18.1 — copyImageSubData per-target axis
        // mapping. For TEXTURE_1D_ARRAY, the second axis (srcY/dstY) is the
        // layer index (0..layers-1) while the height dimension proper is
        // always 1. CTS copy_image.exceeding_boundaries plants Y=14 on a
        // 16-wide × 6-layer 1D-array and expects INVALID_VALUE because
        // 14+1 > 6. Re-route the Y-axis bound to the layer count for
        // 1D_ARRAY so the bounds check fires on layer overflow even if
        // raw `desc.height` is set to texel-row count.
        if (srcTarget == GL_TEXTURE_1D_ARRAY) {
            srcImgH = std::max<GLsizei>(srcTex->desc.depth, srcImg.desc.depth);
        }
        // Prefer native data if available, else fall back to rgba8.
        if (srcImg.nativeBpp > 0 && !srcImg.nativeData.empty()) {
            srcPixels = srcImg.nativeData.data();
            srcBpp = srcImg.nativeBpp;
        } else if (!srcImg.rgba8.empty()) {
            srcPixels = srcImg.rgba8.data();
            srcBpp = 4;
        }
    } else {
        GLRenderbufferObject* srcRB = impl_->objects->renderbuffers().get(srcName);
        if (!srcRB || !srcRB->storageDefined) { pushError(GL_INVALID_VALUE); return false; }
        impl_->materializeRenderbufferRGBA8Clear(*srcRB);
        srcImgW = srcRB->width;
        srcImgH = srcRB->height;
        srcImgD = 1;
        // CKPT117 (Sprint 11 Phase 1 1a): prefer RB.nativeData over rgba8
        // when the RB has a native-precision shadow allocated (non-RGBA8
        // internal formats per replaceRenderbufferStorage). This unblocks
        // the rgb10/rgb32f RB-source residual classes from CKPT109 + the
        // copy_image.smoke_test RGBA32UI 16-bpp case (smoke_test from 1c
        // residual).
        if (srcRB->nativeBpp > 0 && !srcRB->nativeData.empty()) {
            srcPixels = srcRB->nativeData.data();
            srcBpp = srcRB->nativeBpp;
        } else if (!srcRB->rgba8.empty()) {
            srcPixels = srcRB->rgba8.data();
            srcBpp = 4;
        }
    }

    if (srcPixels == nullptr) {
        // Source has no CPU-side shadow data — nothing to copy.
        return true;
    }

    // Bounds check source region. CKPT116 (Sprint 11 Phase 1 1c): include
    // the depth/layer axis (srcZ + srcDepth > srcImgD) — 3D textures and
    // *_ARRAY targets place layers on the Z axis. CTS copy_image.
    // exceeding_boundaries also exercises the 1D_ARRAY layer-on-Y case
    // (handled via srcImgH re-route above).
    if (srcX < 0 || srcY < 0 || srcZ < 0 ||
        srcX + srcWidth > srcImgW || srcY + srcHeight > srcImgH ||
        srcZ + srcDepth > srcImgD) {
        pushError(GL_INVALID_VALUE);
        return false;
    }

    // -----------------------------------------------------------------------
    // Resolve destination image shadow buffer.
    // -----------------------------------------------------------------------
    std::uint8_t* dstPixels = nullptr;
    GLsizei dstImgW = 0, dstImgH = 0, dstImgD = 1;
    std::size_t dstBpp = 4;

    // We need a writable pointer and the ability to invalidate the Metal texture.
    GLTextureObject* dstTex = nullptr;
    GLRenderbufferObject* dstRB = nullptr;
    GLTextureImageLevel* dstImg = nullptr;

    if (dstIsTex) {
        dstTex = impl_->objects->textures().get(dstName);
        if (!dstTex) { pushError(GL_INVALID_VALUE); return false; }
        auto it = dstTex->levels.find(dstLevel);
        if (it == dstTex->levels.end()) {
            // Level not defined — create it on the fly with same dims as source.
            GLTextureImageLevel newLevel;
            newLevel.desc.width = srcImgW;
            newLevel.desc.height = srcImgH;
            newLevel.desc.depth = 1;
            newLevel.defined = true;
            auto ins = dstTex->levels.emplace(dstLevel, std::move(newLevel));
            it = ins.first;
        }
        dstImg = &it->second;
        if (!dstImg->defined) {
            // Allocate matching storage if level was created by texStorage but not yet texImage'd.
            dstImg->defined = true;
        }
        if (dstCubeMap && dstZ >= 0 && dstZ < 6) {
            auto& faceLevels = dstTex->cubeFaceLevels[static_cast<std::size_t>(dstZ)];
            auto [faceIt, _inserted] = faceLevels.try_emplace(dstLevel, *dstImg);
            if (!faceIt->second.defined) {
                faceIt->second.defined = true;
            }
            dstImg = &faceIt->second;
        }
        dstImgW = dstImg->desc.width;
        dstImgH = dstImg->desc.height;
        dstImgD = dstCubeMap ? 6 : dstImg->desc.depth;
        // CKPT116: 1D_ARRAY layer-count-on-Y axis (mirror src logic).
        if (dstTarget == GL_TEXTURE_1D_ARRAY) {
            dstImgH = std::max<GLsizei>(dstTex->desc.depth, dstImg->desc.depth);
        }

        // Ensure the destination rgba8 buffer is large enough.
        const std::size_t totalPixels = static_cast<std::size_t>(dstImgW) * dstImgH;
        if (dstImg->nativeBpp > 0 && !dstImg->nativeData.empty()) {
            dstPixels = dstImg->nativeData.data();
            dstBpp = dstImg->nativeBpp;
        } else {
            if (dstImg->rgba8.size() < totalPixels * 4) {
                dstImg->rgba8.resize(totalPixels * 4, 0);
            }
            dstPixels = dstImg->rgba8.data();
            dstBpp = 4;
        }
    } else {
        dstRB = impl_->objects->renderbuffers().get(dstName);
        if (!dstRB || !dstRB->storageDefined) { pushError(GL_INVALID_VALUE); return false; }
        impl_->materializeRenderbufferRGBA8Clear(*dstRB);
        dstImgW = dstRB->width;
        dstImgH = dstRB->height;
        const std::size_t totalPixels = static_cast<std::size_t>(dstImgW) * dstImgH;
        // CKPT117: prefer RB.nativeData when allocated (non-RGBA8 internal
        // formats); fall back to rgba8 for RGBA8-mapped formats.
        if (dstRB->nativeBpp > 0 && !dstRB->nativeData.empty()) {
            dstPixels = dstRB->nativeData.data();
            dstBpp = dstRB->nativeBpp;
        } else {
            if (dstRB->rgba8.size() < totalPixels * 4) {
                dstRB->rgba8.resize(totalPixels * 4, 0);
            }
            dstPixels = dstRB->rgba8.data();
            dstBpp = 4;
        }
    }

    // Bounds check destination region. CKPT116: include the depth/layer
    // axis for 3D / *_ARRAY targets, matching the source-side bound at
    // line 30361+ above.
    if (dstX < 0 || dstY < 0 || dstZ < 0 ||
        dstX + srcWidth > dstImgW || dstY + srcHeight > dstImgH ||
        dstZ + srcDepth > dstImgD) {
        pushError(GL_INVALID_VALUE);
        return false;
    }

    // -----------------------------------------------------------------------
    // Perform the pixel copy — row-by-row within each depth slice.
    // -----------------------------------------------------------------------
    // When bpp matches between source and destination, do a direct memcpy per row.
    // When bpp differs (e.g. native R8 → RGBA8), we need to convert; for now,
    // use the rgba8 path as the common denominator.
    if ((srcCubeMap || dstCubeMap) && srcBpp == dstBpp) {
        for (GLsizei z = 0; z < srcDepth; ++z) {
            const std::uint8_t* sliceSrcPixels = srcPixels;
            std::uint8_t* sliceDstPixels = dstPixels;
            std::size_t sliceSrcBpp = srcBpp;
            std::size_t sliceDstBpp = dstBpp;
            GLsizei sliceSrcW = srcImgW;
            GLsizei sliceSrcH = srcImgH;
            GLsizei sliceDstW = dstImgW;
            GLsizei sliceDstH = dstImgH;
            GLint srcSlice = srcZ + z;
            GLint dstSlice = dstZ + z;

            if (srcCubeMap) {
                const GLTextureImageLevel* faceImg =
                    textureLevelForCopyLayer(srcTex, srcTarget, srcLevel, srcSlice);
                if (faceImg == nullptr ||
                    !selectTextureReadPixels(*faceImg, sliceSrcPixels, sliceSrcBpp)) {
                    pushError(GL_INVALID_OPERATION);
                    return false;
                }
                sliceSrcW = faceImg->desc.width;
                sliceSrcH = faceImg->desc.height;
                srcSlice = 0;
            }
            if (dstCubeMap) {
                if (dstSlice < 0 || dstSlice >= 6) {
                    pushError(GL_INVALID_VALUE);
                    return false;
                }
                auto& faceLevels =
                    dstTex->cubeFaceLevels[static_cast<std::size_t>(dstSlice)];
                auto faceIt = faceLevels.find(dstLevel);
                if (faceIt == faceLevels.end()) {
                    auto baseIt = dstTex->levels.find(dstLevel);
                    if (baseIt == dstTex->levels.end() || !baseIt->second.defined) {
                        pushError(GL_INVALID_OPERATION);
                        return false;
                    }
                    faceIt = faceLevels.emplace(dstLevel, baseIt->second).first;
                }
                GLTextureImageLevel* faceImg = &faceIt->second;
                if (faceImg == nullptr ||
                    !selectTextureWritePixels(*faceImg, sliceDstPixels, sliceDstBpp)) {
                    pushError(GL_INVALID_OPERATION);
                    return false;
                }
                sliceDstW = faceImg->desc.width;
                sliceDstH = faceImg->desc.height;
                dstTex->cubeFacesDefined |= static_cast<std::uint8_t>(1u << dstSlice);
                dstSlice = 0;
            }
            if (sliceSrcBpp != sliceDstBpp) {
                pushError(GL_INVALID_OPERATION);
                return false;
            }

            const std::size_t srcRowBytes = static_cast<std::size_t>(sliceSrcW) * sliceSrcBpp;
            const std::size_t dstRowBytes = static_cast<std::size_t>(sliceDstW) * sliceDstBpp;
            const std::size_t srcSliceBytes = srcRowBytes * static_cast<std::size_t>(sliceSrcH);
            const std::size_t dstSliceBytes = dstRowBytes * static_cast<std::size_t>(sliceDstH);
            const std::size_t copyRowBytes = static_cast<std::size_t>(srcWidth) * sliceSrcBpp;
            const std::size_t srcSliceOff = static_cast<std::size_t>(srcSlice) * srcSliceBytes;
            const std::size_t dstSliceOff = static_cast<std::size_t>(dstSlice) * dstSliceBytes;
            for (GLsizei row = 0; row < srcHeight; ++row) {
                const std::size_t srcOff = srcSliceOff
                                         + static_cast<std::size_t>(srcY + row) * srcRowBytes
                                         + static_cast<std::size_t>(srcX) * sliceSrcBpp;
                const std::size_t dstOff = dstSliceOff
                                         + static_cast<std::size_t>(dstY + row) * dstRowBytes
                                         + static_cast<std::size_t>(dstX) * sliceDstBpp;
                std::memcpy(sliceDstPixels + dstOff, sliceSrcPixels + srcOff, copyRowBytes);
            }
        }
    } else if (srcBpp == dstBpp) {
        const std::size_t srcRowBytes = static_cast<std::size_t>(srcImgW) * srcBpp;
        const std::size_t dstRowBytes = static_cast<std::size_t>(dstImgW) * dstBpp;
        const std::size_t srcSliceBytes = srcRowBytes * static_cast<std::size_t>(srcImgH);
        const std::size_t dstSliceBytes = dstRowBytes * static_cast<std::size_t>(dstImgH);
        const std::size_t copyRowBytes = static_cast<std::size_t>(srcWidth) * srcBpp;

        for (GLsizei z = 0; z < srcDepth; ++z) {
            const std::size_t srcSliceOff = static_cast<std::size_t>(srcZ + z) * srcSliceBytes;
            const std::size_t dstSliceOff = static_cast<std::size_t>(dstZ + z) * dstSliceBytes;
            for (GLsizei row = 0; row < srcHeight; ++row) {
                const std::size_t srcOff = srcSliceOff
                                         + static_cast<std::size_t>(srcY + row) * srcRowBytes
                                         + static_cast<std::size_t>(srcX) * srcBpp;
                const std::size_t dstOff = dstSliceOff
                                         + static_cast<std::size_t>(dstY + row) * dstRowBytes
                                         + static_cast<std::size_t>(dstX) * dstBpp;
                std::memcpy(dstPixels + dstOff, srcPixels + srcOff, copyRowBytes);
            }
        }
    } else {
        // Mismatched bpp — fall back to rgba8 shadow for both src and dst.
        // Re-resolve using rgba8 for both sides.
        const std::uint8_t* srcRGBA = nullptr;
        std::uint8_t* dstRGBA = nullptr;

        if (srcIsTex) {
            GLTextureObject* srcTex = impl_->objects->textures().get(srcName);
            auto it = srcTex->levels.find(srcLevel);
            if (it != srcTex->levels.end() && !it->second.rgba8.empty()) {
                srcRGBA = it->second.rgba8.data();
            }
        } else {
            GLRenderbufferObject* srcRB = impl_->objects->renderbuffers().get(srcName);
            if (srcRB && !srcRB->rgba8.empty()) srcRGBA = srcRB->rgba8.data();
        }

        if (dstImg && !dstImg->rgba8.empty()) {
            dstRGBA = dstImg->rgba8.data();
        } else if (dstRB && !dstRB->rgba8.empty()) {
            dstRGBA = dstRB->rgba8.data();
        }

        if (srcRGBA && dstRGBA) {
            const std::size_t srcRow4 = static_cast<std::size_t>(srcImgW) * 4;
            const std::size_t dstRow4 = static_cast<std::size_t>(dstImgW) * 4;
            const std::size_t srcSlice4 = srcRow4 * static_cast<std::size_t>(srcImgH);
            const std::size_t dstSlice4 = dstRow4 * static_cast<std::size_t>(dstImgH);
            const std::size_t copyRow4 = static_cast<std::size_t>(srcWidth) * 4;
            for (GLsizei z = 0; z < srcDepth; ++z) {
                const std::size_t sSliceOff = static_cast<std::size_t>(srcZ + z) * srcSlice4;
                const std::size_t dSliceOff = static_cast<std::size_t>(dstZ + z) * dstSlice4;
                for (GLsizei row = 0; row < srcHeight; ++row) {
                    const std::size_t sOff = sSliceOff + static_cast<std::size_t>(srcY + row) * srcRow4 + static_cast<std::size_t>(srcX) * 4;
                    const std::size_t dOff = dSliceOff + static_cast<std::size_t>(dstY + row) * dstRow4 + static_cast<std::size_t>(dstX) * 4;
                    std::memcpy(dstRGBA + dOff, srcRGBA + sOff, copyRow4);
                }
            }
            // Sync rgba8 → dst.nativeData for the copied region. Required
            // when destination has both shadows (e.g. R8 / RGB12 / RGB32F /
            // RGBA12 textures with native Metal pixel format), so that
            // subsequent glGetTexImage / re-upload via replaceMetalTexture
            // reads native shadow with the updated values. Without this,
            // CTS copy_image RB-source-unique tests (r8, rgb10, rgb12,
            // rgba12, rgb32f × 3 RB-source buckets = 15 tests) read stale
            // zero-filled native shadow on the destination after copy.
            // GL 4.6 §18.2.3: the copy is byte-level; we only need to
            // re-encode the destination's native representation from the
            // rgba8 values that the byte-level copy logically produced.
            if (dstImg && dstImg->nativeBpp > 0 && !dstImg->nativeData.empty()) {
                MTLPixelFormat dstNativeFmt = metalRenderbufferFormat(
                    dstImg->desc.internalFormat != 0
                        ? dstImg->desc.internalFormat
                        : dstTex->desc.internalFormat);
                auto info = Impl::nativeFormatInfo(dstNativeFmt);
                if (info.channels > 0 && info.bytesPerPixel > 0) {
                    const std::size_t natRowBytes = static_cast<std::size_t>(dstImgW) * info.bytesPerPixel;
                    const std::size_t natSliceBytes = natRowBytes * static_cast<std::size_t>(dstImgH);
                    for (GLsizei z = 0; z < srcDepth; ++z) {
                        for (GLsizei row = 0; row < srcHeight; ++row) {
                            for (GLsizei col = 0; col < srcWidth; ++col) {
                                const std::size_t rgbaOff =
                                    (static_cast<std::size_t>(dstZ + z) * dstSlice4)
                                    + (static_cast<std::size_t>(dstY + row) * dstRow4)
                                    + (static_cast<std::size_t>(dstX + col) * 4);
                                const std::size_t natOff =
                                    (static_cast<std::size_t>(dstZ + z) * natSliceBytes)
                                    + (static_cast<std::size_t>(dstY + row) * natRowBytes)
                                    + (static_cast<std::size_t>(dstX + col) * info.bytesPerPixel);
                                const std::uint8_t* rgbaPx = dstRGBA + rgbaOff;
                                std::uint8_t* natPx = dstImg->nativeData.data() + natOff;
                                // For each native channel, compute the value
                                // from the rgba8 value at that channel index
                                // (R=0, G=1, B=2, A=3; missing channels read 0).
                                for (int c = 0; c < info.channels; ++c) {
                                    const std::uint8_t rgbaByte = rgbaPx[c];
                                    double v;
                                    switch (info.compType) {
                                        case Impl::NativeFormatInfo::UNorm:
                                            // rgba8 stores u8 unorm; scale to native bit width
                                            v = rgbaByte / 255.0;
                                            break;
                                        case Impl::NativeFormatInfo::SNorm:
                                            // rgba8 has no signed range — treat the byte as
                                            // unsigned and re-center [0,255] → [-1,1]. Edge
                                            // case rare in copy_image (no SNorm in failing pairs).
                                            v = (rgbaByte / 255.0) * 2.0 - 1.0;
                                            break;
                                        case Impl::NativeFormatInfo::UInt:
                                            v = static_cast<double>(rgbaByte);
                                            break;
                                        case Impl::NativeFormatInfo::SInt:
                                            v = static_cast<double>(static_cast<std::int8_t>(rgbaByte));
                                            break;
                                        case Impl::NativeFormatInfo::Float:
                                            v = rgbaByte / 255.0;
                                            break;
                                    }
                                    Impl::writeNativeComponent(
                                        natPx + c * info.bytesPerChannel,
                                        info.compType,
                                        info.bytesPerChannel,
                                        v);
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    // -----------------------------------------------------------------------
    // Invalidate the destination Metal texture so it will be re-uploaded.
    // We null out metalTexture rather than just flipping `instantiated`
    // because bindTexture re-sets instantiated=true before any subsequent
    // read, which would otherwise mask the pending re-upload.
    // -----------------------------------------------------------------------
    if (dstTex) {
        releaseRetainedMetalObject(dstTex->metalTexture);
        dstTex->metalTexture = nullptr;
    }
    if (dstRB) {
        dstRB->instantiated = false;
    }
    impl_->markGpuResourceWrites({
        {dstIsTex ? Impl::GpuResourceAccess::Kind::Texture
                  : Impl::GpuResourceAccess::Kind::Renderbuffer,
         dstName,
         kProducerCopyWrite}
    });
    return true;
}

bool GLContext::textureView(GLuint texture, GLenum target, GLuint origtexture, GLenum internalformat,
                            GLuint minlevel, GLuint numlevels, GLuint minlayer, GLuint numlayers) {
    // GL 4.3 §8.18 (ARB_texture_view) — error cases as asserted by
    // CTS `texture_view.errors`:
    //  - texture == 0           → INVALID_VALUE (texture name 0 is
    //                             reserved for "no binding")
    //  - origtexture == 0       → INVALID_VALUE (same reasoning)
    //  - texture is 0xFFFFFFFF
    //    or otherwise not from glGenTextures → INVALID_OPERATION
    //  - origtexture has no data store allocated → INVALID_OPERATION
    //  - numlevels / numlayers == 0 → INVALID_VALUE
    if (texture == 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    GLTextureObject* viewObj = impl_->objects->textures().get(texture);
    if (viewObj == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // The view texture must be "fresh" — glTextureView cannot re-
    // target an already-bound texture. `target != 0` means a prior
    // glBindTexture / glCreateTextures set the target.
    if (viewObj->target != 0) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // origtexture: both 0 and an unrecognized name produce
    // INVALID_VALUE per the CTS errors test (differs from the
    // `texture` argument's rule where an unrecognized name gives
    // INVALID_OPERATION). The test exercises both codepaths.
    if (origtexture == 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    GLTextureObject* origObj = impl_->objects->textures().get(origtexture);
    if (origObj == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (!origObj->desc.immutable) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (numlevels == 0 || numlayers == 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (!isTextureTarget(target) ||
        target == GL_TEXTURE_BUFFER ||
        target == GL_TEXTURE_CUBE_MAP_POSITIVE_X ||
        target == GL_TEXTURE_CUBE_MAP_NEGATIVE_X ||
        target == GL_TEXTURE_CUBE_MAP_POSITIVE_Y ||
        target == GL_TEXTURE_CUBE_MAP_NEGATIVE_Y ||
        target == GL_TEXTURE_CUBE_MAP_POSITIVE_Z ||
        target == GL_TEXTURE_CUBE_MAP_NEGATIVE_Z) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (!isSupportedInternalTextureFormat(*impl_->capabilities, internalformat)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (!textureViewInternalFormatsCompatible(origObj->desc.internalFormat, internalformat)) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    const GLsizei parentViewLevels = textureViewEffectiveLevelCount(*origObj);
    const GLsizei parentViewLayers = textureViewAvailableLayerCount(*origObj);
    if (minlevel >= static_cast<GLuint>(std::max<GLsizei>(parentViewLevels, 1))) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const GLuint sourceLayers =
        static_cast<GLuint>(std::max<GLsizei>(parentViewLayers, 1));
    if (minlayer >= sourceLayers) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (!textureViewTargetLayerCountValid(target, numlayers)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if ((target == GL_TEXTURE_CUBE_MAP || target == GL_TEXTURE_CUBE_MAP_ARRAY) &&
        !textureViewCubeTargetRequiresSquareLevels(*origObj, minlevel, numlevels)) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // Record the view relationship. Actual Metal texture view
    // (newTextureViewWithPixelFormat:) will be created when the Metal texture
    // is first needed for rendering.
    const GLsizei effectiveNumLevels = std::min<GLsizei>(
        static_cast<GLsizei>(numlevels),
        std::max<GLsizei>(parentViewLevels - static_cast<GLsizei>(minlevel), 1));
    const GLsizei effectiveNumLayers = std::min<GLsizei>(
        static_cast<GLsizei>(numlayers),
        std::max<GLsizei>(parentViewLayers - static_cast<GLsizei>(minlayer), 1));
    viewObj->target = target;
    viewObj->desc.target = target;
    viewObj->desc.internalFormat = internalformat;
    viewObj->desc.levels = effectiveNumLevels;
    viewObj->desc.layers = effectiveNumLayers;
    viewObj->desc.immutable = true;
    viewObj->viewSourceTexture = origtexture;
    viewObj->viewMinLevel = origObj->viewMinLevel + static_cast<GLint>(minlevel);
    viewObj->viewNumLevels = static_cast<GLint>(effectiveNumLevels);
    viewObj->viewMinLayer = origObj->viewMinLayer + static_cast<GLint>(minlayer);
    viewObj->viewNumLayers = static_cast<GLint>(effectiveNumLayers);
    viewObj->params = origObj->params;
    viewObj->samplerDirty = true;

    releaseRetainedMetalObject(viewObj->metalTexture);
    viewObj->metalTexture = nullptr;
    viewObj->instantiated = false;
    releaseRetainedMetalObject(viewObj->metalSwizzledView);
    viewObj->metalSwizzledView = nullptr;
    viewObj->swizzleDirty = true;
    releaseRetainedMetalObject(viewObj->metalSamplingProxy);
    viewObj->metalSamplingProxy = nullptr;

    if ((origObj->metalTexture == nullptr || !origObj->instantiated) &&
        !origObj->levels.empty()) {
        (void)impl_->replaceMetalTexture(*origObj, origtexture);
    }
    MTLPixelFormat viewPixelFormat = metalRenderbufferFormat(internalformat);
    if (viewPixelFormat != MTLPixelFormatInvalid &&
        origObj->metalTexture != nullptr) {
        id<MTLTexture> baseTex =
            (__bridge id<MTLTexture>)origObj->metalTexture;
        const MTLTextureType viewTextureType = metalTextureTypeForTarget(target);
        const NSRange levelRange =
            NSMakeRange(static_cast<NSUInteger>(minlevel),
                        static_cast<NSUInteger>(effectiveNumLevels));
        const NSRange sliceRange =
            NSMakeRange(static_cast<NSUInteger>(minlayer),
                        static_cast<NSUInteger>(effectiveNumLayers));
        const NSUInteger sourceLevels = baseTex.mipmapLevelCount;
        const bool levelRangeFits =
            levelRange.location < sourceLevels &&
            levelRange.length <= sourceLevels - levelRange.location;
        if (levelRangeFits) {
            id<MTLTexture> viewTex =
                [baseTex newTextureViewWithPixelFormat:viewPixelFormat
                                           textureType:viewTextureType
                                                levels:levelRange
                                                slices:sliceRange];
            if (viewTex != nil) {
                viewObj->metalTexture = transferRetainedMetalObject(viewTex);
                viewObj->instantiated = true;
            }
        }
    }
    return true;
}

bool GLContext::invalidateTexImage(GLuint texture, GLint level) {
    if (!impl_->objects->textures().contains(texture)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // Hint: texture contents at this level can be discarded.
    return true;
}

bool GLContext::invalidateTexSubImage(GLuint texture, GLint level, GLint xoffset, GLint yoffset, GLint zoffset,
                                      GLsizei width, GLsizei height, GLsizei depth) {
    if (width < 0 || height < 0 || depth < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (!impl_->objects->textures().contains(texture)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    return true;
}

// ---------------------------------------------------------------------------
// GL 4.0/4.2 — Transform Feedback Draw
// ---------------------------------------------------------------------------

bool GLContext::drawTransformFeedback(GLenum mode, GLuint id) {
    GLTransformFeedbackObject* tfObj = impl_->objects->transformFeedbacks().get(id);
    if (tfObj == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // Sprint 18 Bank D-2/G Mechanism 3: non-instanced
    // DrawTransformFeedback is equivalent to DrawArrays(mode, 0,
    // completedCount). Keep it separate from the Instanced helper so
    // public DrawTransformFeedbackInstanced(..., 1) continues through
    // the existing drawArraysInstanced path.
    GLsizei vertexCount = tfObj->lastCompletedVertexCount[0];
    if (APPGL_DCR_SENTINEL_HOOK("APPGL_DCR4E_FORCE_STREAM_REPLAY_ZERO_COUNT")) {
        vertexCount = 0;
    }
    appgl::AppGLSubmissionGroup replayGroup;
    impl_->declareStreamReplaySubmissionGroup(replayGroup, id, 0u, vertexCount);
    if (vertexCount <= 0) {
        return true;
    }
    return drawArrays(mode, 0, vertexCount);
}

bool GLContext::drawTransformFeedbackStream(GLenum mode, GLuint id, GLuint stream) {
    GLTransformFeedbackObject* tfObj = impl_->objects->transformFeedbacks().get(id);
    if (tfObj == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const std::size_t streamIdx =
        (stream < GLTransformFeedbackObject::kMaxTransformFeedbackStreams)
            ? static_cast<std::size_t>(stream) : 0u;
    // Sprint 18 Bank D-2/G Mechanism 3: same non-instanced
    // DrawArrays routing as drawTransformFeedback(), but using the
    // completed count for the requested stream.
    GLsizei vertexCount = tfObj->lastCompletedVertexCount[streamIdx];
    if (APPGL_DCR_SENTINEL_HOOK("APPGL_DCR4E_FORCE_STREAM_REPLAY_ZERO_COUNT")) {
        vertexCount = 0;
    }
    appgl::AppGLSubmissionGroup replayGroup;
    impl_->declareStreamReplaySubmissionGroup(replayGroup, id, stream, vertexCount);
    if (vertexCount <= 0) {
        return true;
    }
    return drawArrays(mode, 0, vertexCount);
}

bool GLContext::drawTransformFeedbackInstanced(GLenum mode, GLuint id, GLsizei instancecount) {
    if (instancecount < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    GLTransformFeedbackObject* tfObj = impl_->objects->transformFeedbacks().get(id);
    if (tfObj == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // Sprint 8 #9-C (CKPT68): GL 4.6 §10.5 — DrawTransformFeedbackInstanced
    // is equivalent to DrawArraysInstanced(mode, 0, count, instancecount)
    // where `count` is the number of vertices captured during the most
    // recent EndTransformFeedback.
    //
    // Sprint 18 Bank D-2/G: read the last-completed snapshot, not the
    // current-session accumulator. CTS draw_xfb_feedbackk_test begins a
    // new capture on the same object and then draws the previous capture
    // via glDrawTransformFeedback; glBeginTransformFeedback correctly
    // reset capturedVertexCount for the new session, so the draw source
    // has to be lastCompletedVertexCount.
    //
    // CKPT94 #9-C foundation: per-stream array (gl_MaxTransformFeedbackStreams
    // ≥ 4). Non-Stream variant always reads stream 0 per GL 4.6 §10.5 (the
    // non-Stream entry point is implicitly stream 0). Multi-stream
    // accumulators are added Day 23 via GS-emul EmitStreamVertex routing.
    GLsizei vertexCount = tfObj->lastCompletedVertexCount[0];
    if (APPGL_DCR_SENTINEL_HOOK("APPGL_DCR4E_FORCE_STREAM_REPLAY_ZERO_COUNT")) {
        vertexCount = 0;
    }
    appgl::AppGLSubmissionGroup replayGroup;
    impl_->declareStreamReplaySubmissionGroup(replayGroup, id, 0u, vertexCount);
    if (vertexCount <= 0 || instancecount == 0) {
        return true;  // zero-vertex / zero-instance draw is a no-op success
    }
    return drawArraysInstanced(mode, 0, vertexCount, instancecount);
}

bool GLContext::drawTransformFeedbackStreamInstanced(GLenum mode, GLuint id, GLuint stream, GLsizei instancecount) {
    if (instancecount < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    GLTransformFeedbackObject* tfObj = impl_->objects->transformFeedbacks().get(id);
    if (tfObj == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // Sprint 8 #9-C remainder (CKPT94 foundation): the stream parameter
    // selects which captured vertex stream to draw from. Sprint 18 Bank
    // D-2/G keeps the DrawTransformFeedbackStream{,Instanced} source in
    // the same last-completed snapshot used by the non-Stream variant;
    // capturedVertexCount remains the in-progress accumulator.
    //
    // Day 23 adds GS-emul EmitStreamVertex routing that populates streams
    // 1..3 during capture; until then capturedVertexCount[1..3] stay at
    // their zero-init values, and the test's stream=0 read continues to
    // work for non-stream-using callers.
    const std::size_t streamIdx =
        (stream < GLTransformFeedbackObject::kMaxTransformFeedbackStreams)
            ? static_cast<std::size_t>(stream) : 0u;
    GLsizei vertexCount = tfObj->lastCompletedVertexCount[streamIdx];
    if (APPGL_DCR_SENTINEL_HOOK("APPGL_DCR4E_FORCE_STREAM_REPLAY_ZERO_COUNT")) {
        vertexCount = 0;
    }
    appgl::AppGLSubmissionGroup replayGroup;
    impl_->declareStreamReplaySubmissionGroup(replayGroup, id, stream, vertexCount);
    if (vertexCount <= 0 || instancecount == 0) {
        return true;
    }
    return drawArraysInstanced(mode, 0, vertexCount, instancecount);
}

// ---------------------------------------------------------------------------
// GL 4.2/4.3 — Internal Format Query
// ---------------------------------------------------------------------------

bool GLContext::getInternalformativ(GLenum target, GLenum internalformat, GLenum pname, GLsizei count, GLint* params) {
    if (count < 0 || params == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (count == 0) {
        return true;
    }
    {
        ExtensionContext extensionContext(*this);
        const auto& sparseHooks = extensions::ExtensionRegistry::sparseTextureHooks();
        bool handled = false;
        if (sparseHooks.handleInternalFormatQuery != nullptr &&
            !sparseHooks.handleInternalFormatQuery(extensionContext,
                                                  target,
                                                  internalformat,
                                                  pname,
                                                  count,
                                                  params,
                                                  handled)) {
            return false;
        }
        if (handled) {
            return true;
        }
    }
    // Phase 8X Landing C 3b — consult the capabilities format table so
    // format-dependent queries (SUPPORTED, COLOR_ENCODING, RENDERABLE,
    // BLEND) reflect the actual entries that initializeFormatTable() puts
    // on the device, rather than returning GL_FULL_SUPPORT unconditionally.
    std::optional<GLFormatCapability> capability = impl_->capabilities->format(internalformat);
    const auto textureReductionModeSupported = [&]() -> bool {
        const bool supportedTarget =
            target == GL_TEXTURE_1D ||
            target == GL_TEXTURE_1D_ARRAY ||
            target == GL_TEXTURE_2D ||
            target == GL_TEXTURE_2D_ARRAY ||
            target == GL_TEXTURE_3D ||
            target == GL_TEXTURE_CUBE_MAP;
        if (!supportedTarget) {
            return false;
        }
        if (internalformat == GL_RED) {
            return true;
        }
        if (internalformat == GL_DEPTH_COMPONENT) {
            return target != GL_TEXTURE_3D && target != GL_TEXTURE_CUBE_MAP;
        }
        return capability.has_value();
    };
    switch (pname) {
        case GL_TEXTURE_REDUCTION_MODE_ARB:
            params[0] = textureReductionModeSupported() ? GL_TRUE : GL_FALSE;
            return true;
        case GL_NUM_VIRTUAL_PAGE_SIZES_ARB: {
            const MTLSize tile = sparsePageSizeForFormat(impl_->device, target, internalformat);
            params[0] = (tile.width > 0 && capability.has_value()) ? 1 : 0;
            return true;
        }
        case GL_VIRTUAL_PAGE_SIZE_X_ARB:
        case GL_VIRTUAL_PAGE_SIZE_Y_ARB:
        case GL_VIRTUAL_PAGE_SIZE_Z_ARB: {
            for (GLsizei i = 0; i < count; ++i) {
                params[i] = 0;
            }
            if (!capability.has_value()) {
                return true;
            }
            const MTLSize tile = sparsePageSizeForFormat(impl_->device, target, internalformat);
            if (tile.width == 0) {
                return true;
            }
            const NSUInteger value =
                (pname == GL_VIRTUAL_PAGE_SIZE_X_ARB) ? tile.width :
                (pname == GL_VIRTUAL_PAGE_SIZE_Y_ARB) ? tile.height :
                                                        tile.depth;
            params[0] = static_cast<GLint>(value);
            return true;
        }
        case GL_NUM_SAMPLE_COUNTS: {
            const bool multisampleTextureTarget =
                target == GL_TEXTURE_2D_MULTISAMPLE ||
                target == GL_TEXTURE_2D_MULTISAMPLE_ARRAY;
            // Metal has no 1-sample multisample texture type; AppGL backs a
            // GL samples=1 MS texture with 2 storage samples, and shader
            // textureSamples() observes that Metal sample count. Only report
            // backing-faithful counts for MS texture internalformat queries.
            params[0] = multisampleTextureTarget ? 2 : 3;
            return true;
        }
        case GL_SAMPLES: {
            const bool multisampleTextureTarget =
                target == GL_TEXTURE_2D_MULTISAMPLE ||
                target == GL_TEXTURE_2D_MULTISAMPLE_ARRAY;
            // Return sample counts in descending order.
            if (count >= 1) params[0] = 4;
            if (count >= 2) params[1] = 2;
            if (!multisampleTextureTarget && count >= 3) params[2] = 1;
            return true;
        }
        case GL_INTERNALFORMAT_SUPPORTED:
            params[0] = capability.has_value() ? GL_TRUE : GL_FALSE;
            return true;
        case GL_INTERNALFORMAT_PREFERRED:
            params[0] = static_cast<GLint>(internalformat);
            return true;
        case GL_READ_PIXELS_FORMAT:
            params[0] = GL_RGBA;
            return true;
        case GL_READ_PIXELS_TYPE:
            params[0] = GL_UNSIGNED_BYTE;
            return true;
        case GL_MAX_WIDTH:
            params[0] = 16384;
            return true;
        case GL_MAX_HEIGHT:
            params[0] = 16384;
            return true;
        case GL_MAX_DEPTH:
            params[0] = 2048;
            return true;
        case GL_MAX_LAYERS:
            params[0] = 2048;
            return true;
        case GL_MAX_COMBINED_DIMENSIONS:
            params[0] = 16384;
            return true;
        case GL_FRAMEBUFFER_RENDERABLE:
            if (!capability.has_value()) {
                params[0] = GL_NONE;
            } else {
                params[0] = capability->renderable ? GL_FULL_SUPPORT : GL_CAVEAT_SUPPORT;
            }
            return true;
        case GL_FRAMEBUFFER_BLEND:
            if (!capability.has_value()) {
                params[0] = GL_NONE;
            } else {
                params[0] = capability->blendable ? GL_FULL_SUPPORT : GL_CAVEAT_SUPPORT;
            }
            return true;
        case GL_COLOR_ENCODING:
            if (capability.has_value() && capability->srgbCapable) {
                params[0] = GL_SRGB;
            } else {
                params[0] = GL_LINEAR;
            }
            return true;
        default:
            // For unrecognized pnames, return 0 rather than erroring — apps
            // sometimes probe opportunistically.
            for (GLsizei i = 0; i < count; ++i) {
                params[i] = 0;
            }
            return true;
    }
}

bool GLContext::getInternalformati64v(GLenum target, GLenum internalformat, GLenum pname, GLsizei count, GLint64* params) {
    if (count < 0 || params == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (count == 0) {
        return true;
    }
    // Reuse the 32-bit path, widening the results.
    std::vector<GLint> temp(static_cast<std::size_t>(count), 0);
    bool result = getInternalformativ(target, internalformat, pname, count, temp.data());
    if (result) {
        for (GLsizei i = 0; i < count; ++i) {
            params[i] = static_cast<GLint64>(temp[static_cast<std::size_t>(i)]);
        }
    }
    return result;
}

// ---------------------------------------------------------------------------
// GL 4.4 — Immutable buffer storage.
// ---------------------------------------------------------------------------

bool GLContext::bufferStorage(GLenum target, GLsizeiptr size, const void* data, GLbitfield flags) {
    // GL 4.4 §6.2: error-order matters. Binding / immutability
    // checks run before INVALID_VALUE checks because CTS
    // `buffer_storage.errors` specifically asserts that
    // `glBufferStorage(target, 0 /* size */, …)` with no buffer
    // bound returns INVALID_OPERATION (binding wins) — not
    // INVALID_VALUE from the zero-size check.
    GLuint name = impl_->state->boundBuffer(target);
    if (name == 0) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    auto* buf = impl_->objects->buffers().get(name);
    if (!buf) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (buf->immutable) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // size must be > 0. Both `size < 0` and `size == 0` are
    // INVALID_VALUE per GL 4.4 §6.2.1, two spec violations that
    // CTS buffer_storage.errors cross-checks.
    if (size <= 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const GLbitfield validBits = GL_MAP_READ_BIT | GL_MAP_WRITE_BIT |
                                 GL_MAP_PERSISTENT_BIT | GL_MAP_COHERENT_BIT |
                                 GL_DYNAMIC_STORAGE_BIT | GL_CLIENT_STORAGE_BIT |
                                 GL_SPARSE_STORAGE_BIT_ARB;
    if (flags & ~validBits) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if ((flags & GL_SPARSE_STORAGE_BIT_ARB) &&
        (flags & (GL_MAP_READ_BIT | GL_MAP_WRITE_BIT))) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if ((flags & GL_MAP_PERSISTENT_BIT) && !(flags & (GL_MAP_READ_BIT | GL_MAP_WRITE_BIT))) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if ((flags & GL_MAP_COHERENT_BIT) && !(flags & GL_MAP_PERSISTENT_BIT)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (flags & GL_SPARSE_STORAGE_BIT_ARB) {
        if (!impl_->replaceSparseBufferStorage(*buf, size)) {
            pushError(GL_OUT_OF_MEMORY);
            return false;
        }
    } else {
        // Delegate to replaceBufferStorage to create both shadow bytes and Metal
        // buffer, then layer immutability flags on top.  Without this the Metal
        // buffer would remain null and draws would render black.
        if (!impl_->replaceBufferStorage(*buf, size, data, GL_STATIC_DRAW)) {
            pushError(GL_OUT_OF_MEMORY);
            return false;
        }
    }
    buf->immutable = true;
    buf->storageFlags = flags;
    buf->instantiated = true;
    return true;
}

static bool isSparseBufferCommitmentTarget(GLenum target) {
    switch (target) {
        case GL_ARRAY_BUFFER:
        case GL_ELEMENT_ARRAY_BUFFER:
        case GL_COPY_READ_BUFFER:
        case GL_COPY_WRITE_BUFFER:
        case GL_PIXEL_PACK_BUFFER:
        case GL_PIXEL_UNPACK_BUFFER:
        case GL_TRANSFORM_FEEDBACK_BUFFER:
        case GL_UNIFORM_BUFFER:
        case GL_TEXTURE_BUFFER:
        case GL_DRAW_INDIRECT_BUFFER:
        case GL_ATOMIC_COUNTER_BUFFER:
        case GL_DISPATCH_INDIRECT_BUFFER:
        case GL_SHADER_STORAGE_BUFFER:
        case GL_QUERY_BUFFER:
        case GL_PARAMETER_BUFFER:
            return true;
        default:
            return false;
    }
}

bool GLContext::bufferPageCommitment(GLenum target, GLintptr offset, GLsizeiptr size, GLboolean commit) {
    if (!isSparseBufferCommitmentTarget(target)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    const GLuint name = impl_->state->boundBuffer(target);
    GLBufferObject* object = impl_->objects->buffers().get(name);
    if (name == 0 || object == nullptr || !object->instantiated || !object->sparseStorage) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (offset < 0 || size < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const GLsizeiptr pageSize = object->sparsePageSize > 0
        ? object->sparsePageSize
        : kSparseBufferPageSizeARB;
    if ((offset % pageSize) != 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (offset > object->size || size > object->size - offset) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if ((size % pageSize) != 0 && offset + size != object->size) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (!impl_->commitSparseBufferRange(*object, offset, size, commit)) {
        pushError(GL_OUT_OF_MEMORY);
        return false;
    }
    impl_->markGpuResourceWrites({
        {Impl::GpuResourceAccess::Kind::Buffer,
         name,
         kProducerSparseResidency}
    });
    return true;
}

// ---------------------------------------------------------------------------
// GL 4.4 — Multi-bind.
// ---------------------------------------------------------------------------

static bool isIndexedBufferTarget(GLenum target) {
    switch (target) {
        case GL_ATOMIC_COUNTER_BUFFER:
        case GL_TRANSFORM_FEEDBACK_BUFFER:
        case GL_UNIFORM_BUFFER:
        case GL_SHADER_STORAGE_BUFFER:
            return true;
        default:
            return false;
    }
}

namespace {
GLint64 queryLimit(const GLCapabilities* caps, GLenum pname, GLint64 fallback) {
    GLint64 value = fallback;
    if (caps != nullptr) {
        caps->queryInteger64(pname, &value);
    }
    return value;
}

GLenum indexedBufferMaxPname(GLenum target) {
    switch (target) {
        case GL_UNIFORM_BUFFER:           return GL_MAX_UNIFORM_BUFFER_BINDINGS;
        case GL_SHADER_STORAGE_BUFFER:    return GL_MAX_SHADER_STORAGE_BUFFER_BINDINGS;
        case GL_ATOMIC_COUNTER_BUFFER:    return GL_MAX_ATOMIC_COUNTER_BUFFER_BINDINGS;
        case GL_TRANSFORM_FEEDBACK_BUFFER: return GL_MAX_TRANSFORM_FEEDBACK_BUFFERS;
        default: return 0;
    }
}

void unbindAllTextureTargetsOnActiveUnit(GLStateTracker& state) {
    state.bindTexture(GL_TEXTURE_1D, 0);
    state.bindTexture(GL_TEXTURE_2D, 0);
    state.bindTexture(GL_TEXTURE_3D, 0);
    state.bindTexture(GL_TEXTURE_1D_ARRAY, 0);
    state.bindTexture(GL_TEXTURE_2D_ARRAY, 0);
    state.bindTexture(GL_TEXTURE_RECTANGLE, 0);
    state.bindTexture(GL_TEXTURE_CUBE_MAP, 0);
    state.bindTexture(GL_TEXTURE_CUBE_MAP_ARRAY, 0);
    state.bindTexture(GL_TEXTURE_BUFFER, 0);
    state.bindTexture(GL_TEXTURE_2D_MULTISAMPLE, 0);
    state.bindTexture(GL_TEXTURE_2D_MULTISAMPLE_ARRAY, 0);
}
}  // namespace

bool GLContext::bindBuffersBase(GLenum target, GLuint first, GLsizei count, const GLuint* buffers) {
    if (!isIndexedBufferTarget(target)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (count < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const GLint64 maxBindings = queryLimit(impl_->capabilities.get(), indexedBufferMaxPname(target), 0);
    if (static_cast<GLint64>(first) + static_cast<GLint64>(count) > maxBindings) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // GL 4.4 ARB_multi_bind §6.1.1 — per-entry semantics. Each
    // invalid (non-zero, non-existent) buffer name generates
    // INVALID_OPERATION and that slot is unmodified; valid entries
    // still bind. bindBufferBase itself already pushes INVALID_
    // OPERATION on a bad name, so just let it run through the loop
    // and the per-entry errors accumulate naturally.
    for (GLsizei i = 0; i < count; ++i) {
        GLuint buf = buffers ? buffers[i] : 0;
        if (buf != 0 && !impl_->objects->buffers().contains(buf)) {
            pushError(GL_INVALID_OPERATION);
            continue;
        }
        bindBufferBase(target, first + static_cast<GLuint>(i), buf);
    }
    return true;
}

bool GLContext::bindBuffersRange(GLenum target, GLuint first, GLsizei count, const GLuint* buffers,
                                 const GLintptr* offsets, const GLsizeiptr* sizes) {
    if (!isIndexedBufferTarget(target)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (count < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const GLint64 maxBindings = queryLimit(impl_->capabilities.get(), indexedBufferMaxPname(target), 0);
    if (static_cast<GLint64>(first) + static_cast<GLint64>(count) > maxBindings) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    for (GLsizei i = 0; i < count; ++i) {
        GLuint buf = buffers ? buffers[i] : 0;
        GLintptr offset = (buffers && offsets) ? offsets[i] : 0;
        GLsizeiptr sz = (buffers && sizes) ? sizes[i] : 0;
        if (buf != 0 && !impl_->objects->buffers().contains(buf)) {
            pushError(GL_INVALID_OPERATION);
            continue;
        }
        bindBufferRange(target, first + static_cast<GLuint>(i), buf, offset, sz);
    }
    return true;
}

bool GLContext::bindVertexBuffers(GLuint first, GLsizei count, const GLuint* buffers,
                                  const GLintptr* offsets, const GLsizei* strides) {
    if (count < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const GLint64 maxBindings = queryLimit(impl_->capabilities.get(), GL_MAX_VERTEX_ATTRIB_BINDINGS, 16);
    if (static_cast<GLint64>(first) + static_cast<GLint64>(count) > maxBindings) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    for (GLsizei i = 0; i < count; ++i) {
        GLuint buf = buffers ? buffers[i] : 0;
        GLintptr offset = (buffers && offsets) ? offsets[i] : 0;
        GLsizei stride = (buffers && strides) ? strides[i] : 0;
        bindVertexBuffer(first + static_cast<GLuint>(i), buf, offset, stride);
    }
    return true;
}

bool GLContext::bindTextures(GLuint first, GLsizei count, const GLuint* textures) {
    if (count < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const GLint64 maxUnits = queryLimit(impl_->capabilities.get(), GL_MAX_COMBINED_TEXTURE_IMAGE_UNITS, 80);
    if (static_cast<GLint64>(first) + static_cast<GLint64>(count) > maxUnits) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // GL 4.4 §6.1.1 / ARB_multi_bind — per-entry semantics: an
    // invalid (non-zero, non-existent) texture name raises
    // INVALID_OPERATION and the corresponding unit is unmodified;
    // other valid entries still bind. Also per spec, ACTIVE_TEXTURE
    // is NOT modified — which our prior impl broke by cycling
    // `setActiveTextureUnit` inside the loop without restoring.
    const GLuint savedActiveUnit = impl_->state->activeTextureUnit();
    bool anyInvalid = false;
    for (GLsizei i = 0; i < count; ++i) {
        GLuint tex = textures ? textures[i] : 0;
        GLuint unit = first + static_cast<GLuint>(i);
        impl_->state->setActiveTextureUnit(unit);
        if (tex == 0) {
            // Unbind every target on this unit (multi-bind unbinds
            // regardless of previously-bound target).
            unbindAllTextureTargetsOnActiveUnit(*impl_->state);
            impl_->touchR5Residency(MetalR5ResidencyTouchKind::TextureBind);
            continue;
        }
        auto* obj = impl_->objects->textures().get(tex);
        if (obj == nullptr) {
            anyInvalid = true;
            continue;
        }
        GLenum target = obj->target != 0 ? obj->target : GL_TEXTURE_2D;
        impl_->state->bindTexture(target, tex);
        impl_->touchR5Residency(MetalR5ResidencyTouchKind::TextureBind);
    }
    impl_->state->setActiveTextureUnit(savedActiveUnit);
    if (anyInvalid) pushError(GL_INVALID_OPERATION);
    return true;
}

bool GLContext::bindSamplers(GLuint first, GLsizei count, const GLuint* samplers) {
    if (count < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const GLint64 maxUnits = queryLimit(impl_->capabilities.get(), GL_MAX_COMBINED_TEXTURE_IMAGE_UNITS, 80);
    if (static_cast<GLint64>(first) + static_cast<GLint64>(count) > maxUnits) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // GL 4.4 §6.1.1 / ARB_multi_bind — per-entry semantics.
    bool anyInvalid = false;
    for (GLsizei i = 0; i < count; ++i) {
        GLuint sampler = samplers ? samplers[i] : 0;
        if (sampler != 0 && !impl_->objects->samplers().contains(sampler)) {
            anyInvalid = true;
            continue;
        }
        bindSampler(first + static_cast<GLuint>(i), sampler);
    }
    if (anyInvalid) pushError(GL_INVALID_OPERATION);
    return true;
}

bool GLContext::bindImageTextures(GLuint first, GLsizei count, const GLuint* textures) {
    if (count < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const GLint64 maxUnits = queryLimit(impl_->capabilities.get(), GL_MAX_IMAGE_UNITS, 8);
    if (static_cast<GLint64>(first) + static_cast<GLint64>(count) > maxUnits) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // GL 4.4 ARB_multi_bind / §8.22 — glBindImageTextures uses
    // per-entry semantics: each invalid <textures> entry generates
    // INVALID_OPERATION and that unit's binding is *unmodified*;
    // other valid entries still get bound. Write each unit directly
    // to avoid the per-unit bindImageTexture format whitelist, which
    // is stricter than what the multi-bind spec implies (all
    // texture-storage-eligible formats are OK here).
    bool anyInvalid = false;
    for (GLsizei i = 0; i < count; ++i) {
        GLuint tex = textures ? textures[i] : 0;
        GLuint unit = first + static_cast<GLuint>(i);
        if (unit >= impl_->imageBindings.size()) break;
        auto& binding = impl_->imageBindings[unit];
        if (tex == 0) {
            impl_->flushImageBinding3DLayerSidecar(binding);
            binding.invalidateMetalView();
            binding.texture = 0;
            binding.level = 0;
            binding.layered = GL_FALSE;
            binding.layer = 0;
            binding.access = GL_READ_ONLY;
            binding.format = GL_RGBA8;
            continue;
        }
        auto* obj = impl_->objects->textures().get(tex);
        if (obj == nullptr) {
            // Invalid entry — INVALID_OPERATION, unit unmodified.
            anyInvalid = true;
            continue;
        }
        // CTS `multi_bind.errors_bind_image_textures` plants a texture
        // whose storage was never successfully allocated (texStorage2D
        // with height=0 → INVALID_VALUE) and asserts INVALID_OPERATION
        // here. Our textures store internalFormat only after a
        // successful storage/image call — a 0 means storage was never
        // provided. Functional tests (same texture via proper
        // InitStorage) always end up with a non-zero format.
        GLenum fmt = obj->desc.internalFormat;
        if (fmt == 0) {
            anyInvalid = true;
            continue;
        }
        const bool cachedViewChanged =
            binding.metalLevelView != nullptr &&
            (binding.cachedViewTexture != tex ||
             binding.cachedViewLevel != 0 ||
             binding.cachedViewFormat != fmt);
        const bool layer3DSidecarChanged =
            binding.layer3DSidecarTexture != nullptr &&
            (binding.layer3DSidecarSourceTexture != tex ||
             binding.layer3DSidecarLevel != 0 ||
             binding.layer3DSidecarFormat != fmt);
        if (cachedViewChanged || layer3DSidecarChanged) {
            impl_->flushImageBinding3DLayerSidecar(binding);
            binding.invalidateMetalView();
        }
        binding.texture = tex;
        binding.level = 0;
        binding.layered = GL_TRUE;
        binding.layer = 0;
        binding.access = GL_READ_WRITE;
        binding.format = fmt;
        {
            ExtensionContext extensionContext(*this);
            (void)extensions::sparse_texture::ensureSparseStorageImageSidecar(
                extensionContext, *obj);
        }
    }
    if (anyInvalid) {
        pushError(GL_INVALID_OPERATION);
    }
    return true;
}

// ---------------------------------------------------------------------------
// GL 4.4 — Texture clear.
// ---------------------------------------------------------------------------

namespace {

struct FillLevelArgs {
    GLenum format;
    GLenum type;
    const void* data;
    GLint xoff;
    GLint yoff;
    GLint zoff;
    GLsizei regionW;
    GLsizei regionH;
    GLsizei regionD;
};

static bool isClearTexIntegerFormat(GLenum format) {
    switch (format) {
        case GL_RED_INTEGER:
        case GL_GREEN_INTEGER:
        case GL_BLUE_INTEGER:
        case GL_RG_INTEGER:
        case GL_RGB_INTEGER:
        case GL_BGR_INTEGER:
        case GL_RGBA_INTEGER:
        case GL_BGRA_INTEGER:
            return true;
        default:
            return false;
    }
}

static bool isClearTexIntegerInternalFormat(GLenum internalFormat) {
    switch (internalFormat) {
        case GL_R8I: case GL_R8UI: case GL_R16I: case GL_R16UI:
        case GL_R32I: case GL_R32UI:
        case GL_RG8I: case GL_RG8UI: case GL_RG16I: case GL_RG16UI:
        case GL_RG32I: case GL_RG32UI:
        case GL_RGB8I: case GL_RGB8UI: case GL_RGB16I: case GL_RGB16UI:
        case GL_RGB32I: case GL_RGB32UI:
        case GL_RGBA8I: case GL_RGBA8UI: case GL_RGBA16I: case GL_RGBA16UI:
        case GL_RGBA32I: case GL_RGBA32UI:
        case GL_RGB10_A2UI:
            return true;
        default:
            return false;
    }
}

static bool isDepthStencilInternalFormat(GLenum internalFormat) {
    return internalFormat == GL_DEPTH_STENCIL ||
           internalFormat == GL_DEPTH24_STENCIL8 ||
           internalFormat == GL_DEPTH32F_STENCIL8;
}

static bool clearTexFormatCompatible(GLenum internalFormat, GLenum format) {
    const bool formatIsDepth = (format == GL_DEPTH_COMPONENT);
    const bool formatIsStencil = (format == GL_STENCIL_INDEX);
    const bool formatIsDS = (format == GL_DEPTH_STENCIL);
    const bool formatIsInteger = isClearTexIntegerFormat(format);
    const bool formatIsColor = !formatIsDepth && !formatIsStencil && !formatIsDS;

    const bool internalIsDepth = isDepthFormat(internalFormat);
    const bool internalIsStencil = isStencilFormat(internalFormat);
    const bool internalIsDS = isDepthStencilInternalFormat(internalFormat);
    const bool internalIsColor = !internalIsDepth && !internalIsStencil;
    const bool internalIsInteger = isClearTexIntegerInternalFormat(internalFormat);

    if (formatIsColor && !internalIsColor) return false;
    if (formatIsDepth && !(internalIsDepth || internalIsDS)) return false;
    if (formatIsDS && !internalIsDS) return false;
    if (formatIsStencil && !(internalIsStencil || internalIsDS)) return false;
    if (internalIsColor && (formatIsInteger != internalIsInteger)) return false;
    return true;
}

}  // namespace

static bool copySimpleTextureLevelShadow(const GLTextureObject& object,
                                         const GLTextureImageLevel& image,
                                         GLenum format,
                                         GLenum type,
                                         GLsizei bufSize,
                                         const GLPixelStoreState& packStore,
                                         void* pixels) {
    if (pixels == nullptr || !image.defined) {
        return false;
    }
    if (isPackedPixelType(type)) {
        return false;
    }

    const std::size_t dstPixelBytes = bytesPerPixel(format, type);
    const std::size_t dstBpc = bytesPerComponent(type);
    const std::size_t dstComponents = componentCountForFormat(format);
    if (dstPixelBytes == 0 || dstBpc == 0 || dstComponents == 0) {
        return false;
    }

    const std::uint8_t* sourceBytes = nullptr;
    std::size_t sourceBpp = 0;
    std::size_t sourceByteCount = 0;
    if (format == GL_RGBA && type == GL_UNSIGNED_BYTE && !image.rgba8.empty()) {
        sourceBytes = image.rgba8.data();
        sourceBpp = 4;
        sourceByteCount = image.rgba8.size();
    } else if ((format == GL_RGBA || format == GL_RGB || format == GL_DEPTH_COMPONENT) &&
               image.nativeBpp >= dstPixelBytes &&
               !image.nativeData.empty()) {
        sourceBytes = image.nativeData.data();
        sourceBpp = image.nativeBpp;
        sourceByteCount = image.nativeData.size();
    } else {
        return false;
    }

    const GLsizei texW = std::max<GLsizei>(image.desc.width, 1);
    GLsizei texH = std::max<GLsizei>(image.desc.height, 1);
    GLsizei texD = 1;
    switch (object.target) {
        case GL_TEXTURE_1D:
            texH = 1;
            texD = 1;
            break;
        case GL_TEXTURE_1D_ARRAY:
            texH = std::max<GLsizei>(
                std::max<GLsizei>(image.desc.height, image.desc.layers), 1);
            texD = 1;
            break;
        case GL_TEXTURE_3D:
            texD = std::max<GLsizei>(image.desc.depth, 1);
            break;
        case GL_TEXTURE_2D_ARRAY:
        case GL_TEXTURE_CUBE_MAP_ARRAY:
            texD = std::max<GLsizei>(
                std::max<GLsizei>(image.desc.depth, image.desc.layers), 1);
            break;
        default:
            texD = 1;
            break;
    }

    const std::size_t texelCount =
        static_cast<std::size_t>(texW) *
        static_cast<std::size_t>(texH) *
        static_cast<std::size_t>(texD);
    if (sourceByteCount < texelCount * sourceBpp) {
        return false;
    }

    const std::size_t dstRowStridePixels = packStore.packRowLength > 0
        ? static_cast<std::size_t>(packStore.packRowLength)
        : static_cast<std::size_t>(texW);
    const std::size_t dstRowBytes = alignByteCount(
        dstRowStridePixels * dstPixelBytes, packStore.packAlignment);
    const std::size_t dstImageHeight = packStore.packImageHeight > 0
        ? static_cast<std::size_t>(packStore.packImageHeight)
        : static_cast<std::size_t>(texH);
    const std::size_t dstSliceBytes = dstRowBytes * dstImageHeight;
    const std::size_t dstSkipBytes =
        static_cast<std::size_t>(packStore.packSkipImages) * dstSliceBytes +
        static_cast<std::size_t>(packStore.packSkipRows) * dstRowBytes +
        static_cast<std::size_t>(packStore.packSkipPixels) * dstPixelBytes;
    const std::size_t lastByte =
        dstSkipBytes +
        (static_cast<std::size_t>(texD) - 1u) * dstSliceBytes +
        (static_cast<std::size_t>(texH) - 1u) * dstRowBytes +
        static_cast<std::size_t>(texW) * dstPixelBytes;
    if (bufSize > 0 && static_cast<std::size_t>(bufSize) < lastByte) {
        return false;
    }

    auto* dstBase = static_cast<std::uint8_t*>(pixels) + dstSkipBytes;
    const bool packSwapBytes = (packStore.packSwapBytes == GL_TRUE);
    for (GLsizei z = 0; z < texD; ++z) {
        for (GLsizei y = 0; y < texH; ++y) {
            const std::uint8_t* srcRow = sourceBytes +
                ((static_cast<std::size_t>(z) * static_cast<std::size_t>(texH) +
                  static_cast<std::size_t>(y)) *
                 static_cast<std::size_t>(texW)) * sourceBpp;
            std::uint8_t* dstRow = dstBase +
                static_cast<std::size_t>(z) * dstSliceBytes +
                static_cast<std::size_t>(y) * dstRowBytes;
            if (sourceBpp == dstPixelBytes && !packSwapBytes) {
                std::memcpy(dstRow, srcRow, static_cast<std::size_t>(texW) * dstPixelBytes);
                continue;
            }
            for (GLsizei x = 0; x < texW; ++x) {
                const std::uint8_t* srcPixel = srcRow + static_cast<std::size_t>(x) * sourceBpp;
                std::uint8_t* dstPixel = dstRow + static_cast<std::size_t>(x) * dstPixelBytes;
                std::memcpy(dstPixel, srcPixel, dstPixelBytes);
                if (packSwapBytes && dstBpc > 1) {
                    for (std::size_t c = 0; c < dstComponents; ++c) {
                        std::reverse(dstPixel + c * dstBpc, dstPixel + (c + 1u) * dstBpc);
                    }
                }
            }
        }
    }
    return true;
}

// Helper: fill an existing level's rgba8 + native-format buffers with
// a single `data` texel (or zeros). `data==nullptr` means GL-spec-zero
// (RGBA8 {0,0,0,0}, native zero-fill; alpha defaults to 1 for formats
// that have an alpha channel, matching GL 4.6 §8.19).
// Declared as free-file-scope function to keep the clearTexImage body
// compact; delegates format/native conversion back into `impl_` via the
// public `Impl*` pointer passed in.
template <typename ImplT>
static void fillLevelWithClearValue_T(ImplT* impl, GLTextureObject& tex,
                                      GLTextureImageLevel& img,
                                      GLint xoff, GLint yoff, GLint zoff,
                                      GLsizei regionW, GLsizei regionH, GLsizei regionD,
                                      GLenum format, GLenum type, const void* data)
{
    // RGBA8 shadow fill — drop to 8-bit per channel, used for sampling
    // paths that fall back to rgba8.
    std::uint8_t clearRGBA[4] = {0, 0, 0, 0};
    if (data != nullptr) {
        const std::size_t components = componentCountForFormat(format);
        for (std::size_t c = 0; c < components && c < 4; ++c) {
            clearRGBA[c] = ImplT::readComponentAsU8(
                static_cast<const std::uint8_t*>(data), type, c);
        }
    }
    // For a full-level clear (region == image size, offsets == 0), just
    // fill the whole backing store. Otherwise, fill per-pixel over the
    // specified rectangle.
    const std::size_t levelW = static_cast<std::size_t>(img.desc.width);
    const std::size_t levelH = static_cast<std::size_t>(img.desc.height);
    const std::size_t levelD = std::max<std::size_t>(1, img.desc.depth);
    const bool wholeLevel = (xoff == 0 && yoff == 0 && zoff == 0 &&
                             static_cast<std::size_t>(regionW) == levelW &&
                             static_cast<std::size_t>(regionH) == levelH &&
                             static_cast<std::size_t>(regionD) == levelD);

    // Clamp region to level bounds defensively.
    const std::size_t x0 = std::min<std::size_t>(static_cast<std::size_t>(xoff), levelW);
    const std::size_t y0 = std::min<std::size_t>(static_cast<std::size_t>(yoff), levelH);
    const std::size_t z0 = std::min<std::size_t>(static_cast<std::size_t>(zoff), levelD);
    const std::size_t x1 = std::min<std::size_t>(x0 + static_cast<std::size_t>(regionW), levelW);
    const std::size_t y1 = std::min<std::size_t>(y0 + static_cast<std::size_t>(regionH), levelH);
    const std::size_t z1 = std::min<std::size_t>(z0 + static_cast<std::size_t>(regionD), levelD);

    if (!img.rgba8.empty()) {
        if (wholeLevel) {
            for (std::size_t j = 0; j + 4 <= img.rgba8.size(); j += 4) {
                std::memcpy(img.rgba8.data() + j, clearRGBA, 4);
            }
        } else {
            for (std::size_t z = z0; z < z1; ++z) {
                for (std::size_t y = y0; y < y1; ++y) {
                    for (std::size_t x = x0; x < x1; ++x) {
                        const std::size_t idx = ((z * levelH) + y) * levelW + x;
                        if (idx * 4 + 4 <= img.rgba8.size()) {
                            std::memcpy(img.rgba8.data() + idx * 4, clearRGBA, 4);
                        }
                    }
                }
            }
        }
    }

    // Native-format fill — build a 1×1×1 native pixel via buildNativeUpload,
    // then replicate across the native buffer. This is required for
    // non-RGBA8 formats where glGetTexImage reads from nativeData.
    if (img.nativeBpp > 0 && !img.nativeData.empty()) {
        std::vector<std::uint8_t> singlePixel;
        std::size_t pixelBpp = 0;
        bool built = false;
        if (data != nullptr) {
            built = impl->buildNativeUpload(img.desc.internalFormat,
                                            1, 1, 1,
                                            format, type, data,
                                            singlePixel, pixelBpp);
        }
        if (!built || singlePixel.size() != img.nativeBpp) {
            // Null `data` or non-representable → zero-fill, matching GL spec.
            singlePixel.assign(img.nativeBpp, 0);
            pixelBpp = img.nativeBpp;
        }
        if (wholeLevel) {
            for (std::size_t j = 0; j + img.nativeBpp <= img.nativeData.size(); j += img.nativeBpp) {
                std::memcpy(img.nativeData.data() + j, singlePixel.data(), img.nativeBpp);
            }
        } else {
            for (std::size_t z = z0; z < z1; ++z) {
                for (std::size_t y = y0; y < y1; ++y) {
                    for (std::size_t x = x0; x < x1; ++x) {
                        const std::size_t idx = ((z * levelH) + y) * levelW + x;
                        const std::size_t byteIdx = idx * img.nativeBpp;
                        if (byteIdx + img.nativeBpp <= img.nativeData.size()) {
                            std::memcpy(img.nativeData.data() + byteIdx,
                                        singlePixel.data(), img.nativeBpp);
                        }
                    }
                }
            }
        }
    }

    (void)tex;
}

bool GLContext::clearTexImage(GLuint texture, GLint level, GLenum format, GLenum type, const void* data) {
    auto* tex = impl_->objects->textures().get(texture);
    if (!tex) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (impl_->frameGraph != nullptr) {
        impl_->frameGraph->flushParallelEncodeBoundary();
    }
    // If level is -1, clear all defined levels to zero.
    if (level < 0) {
        for (auto& [lvl, img] : tex->levels) {
            if (img.defined) {
                fillLevelWithClearValue_T(impl_.get(), *tex, img,
                                          0, 0, 0,
                                          img.desc.width, img.desc.height, img.desc.depth,
                                          format, type, data);
            }
        }
        if (tex->metalTexture != nullptr) {
            impl_->replaceMetalTexture(*tex);
        }
        impl_->markGpuResourceWrites({
            {Impl::GpuResourceAccess::Kind::Texture,
             texture,
             kProducerClearWrite}
        });
        return true;
    }
    auto it = tex->levels.find(level);
    if (it == tex->levels.end() || !it->second.defined) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    const GLenum internalFormat = it->second.desc.internalFormat;
    if (isCompressedInternalFormat(internalFormat) ||
        !clearTexFormatCompatible(internalFormat, format)) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (impl_->frameGraph != nullptr) {
        impl_->frameGraph->flushParallelEncodeBoundary();
    }
    fillLevelWithClearValue_T(impl_.get(), *tex, it->second,
                            0, 0, 0,
                            it->second.desc.width,
                            it->second.desc.height,
                            it->second.desc.depth,
                            format, type, data);
    if (tex->metalTexture != nullptr) {
        impl_->replaceMetalTexture(*tex);
    }
    impl_->markGpuResourceWrites({
        {Impl::GpuResourceAccess::Kind::Texture,
         texture,
         kProducerClearWrite}
    });
    return true;
}

bool GLContext::clearTexSubImage(GLuint texture, GLint level,
                                 GLint xoffset, GLint yoffset, GLint zoffset,
                                 GLsizei width, GLsizei height, GLsizei depth,
                                 GLenum format, GLenum type, const void* data) {
    auto* tex = impl_->objects->textures().get(texture);
    if (!tex) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (width < 0 || height < 0 || depth < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    auto it = tex->levels.find(level);
    if (it == tex->levels.end() || !it->second.defined) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // Zero-dimension sub-image is a no-op per GL spec — accept and return.
    if (width == 0 || height == 0 || depth == 0) return true;
    const GLenum internalFormat = it->second.desc.internalFormat;
    if (isCompressedInternalFormat(internalFormat) ||
        !clearTexFormatCompatible(internalFormat, format)) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    fillLevelWithClearValue_T(impl_.get(), *tex, it->second,
                            xoffset, yoffset, zoffset,
                            width, height, depth,
                            format, type, data);
    if (tex->metalTexture != nullptr) {
        impl_->replaceMetalTexture(*tex);
    }
    impl_->markGpuResourceWrites({
        {Impl::GpuResourceAccess::Kind::Texture,
         texture,
         kProducerClearWrite}
    });
    return true;
}

// ---------------------------------------------------------------------------
// GL 4.5 — DSA object creation.
// ---------------------------------------------------------------------------

bool GLContext::createBuffers(GLsizei n, GLuint* buffers) {
    if (n < 0) { pushError(GL_INVALID_VALUE); return false; }
    for (GLsizei i = 0; i < n; ++i) {
        buffers[i] = impl_->objects->buffers().reserveName();
        auto* obj = impl_->objects->buffers().get(buffers[i]);
        if (obj) obj->instantiated = true;
    }
    return true;
}

bool GLContext::createTextures(GLenum target, GLsizei n, GLuint* textures) {
    // GL 4.5 §8.1: target must be one of the allowed texture-object
    // target enums. CTS `direct_state_access.textures_creation_errors`
    // plants an invalid target and expects INVALID_ENUM.
    switch (target) {
        case GL_TEXTURE_1D: case GL_TEXTURE_2D: case GL_TEXTURE_3D:
        case GL_TEXTURE_1D_ARRAY: case GL_TEXTURE_2D_ARRAY:
        case GL_TEXTURE_RECTANGLE: case GL_TEXTURE_BUFFER:
        case GL_TEXTURE_CUBE_MAP: case GL_TEXTURE_CUBE_MAP_ARRAY:
        case GL_TEXTURE_2D_MULTISAMPLE:
        case GL_TEXTURE_2D_MULTISAMPLE_ARRAY:
            break;
        default:
            pushError(GL_INVALID_ENUM);
            return false;
    }
    if (n < 0) { pushError(GL_INVALID_VALUE); return false; }
    for (GLsizei i = 0; i < n; ++i) {
        textures[i] = impl_->objects->textures().reserveName();
        // DSA textures know their target from creation and are immediately usable.
        auto* obj = impl_->objects->textures().get(textures[i]);
        if (obj) {
            obj->target = target;
            obj->instantiated = true;
        }
    }
    return true;
}

bool GLContext::createSamplers(GLsizei n, GLuint* samplers) {
    if (n < 0) { pushError(GL_INVALID_VALUE); return false; }
    // DSA createSamplers immediately allocates an object — `instantiated`
    // must be true so glSamplerParameter / glGetSamplerParameter don't
    // raise GL_INVALID_OPERATION (unlike glGenSamplers which only reserves
    // the name and requires a subsequent glBindSampler to materialise).
    for (GLsizei i = 0; i < n; ++i) {
        samplers[i] = impl_->objects->samplers().reserveName();
        if (auto* obj = impl_->objects->samplers().get(samplers[i])) {
            obj->instantiated = true;
        }
    }
    return true;
}

bool GLContext::createFramebuffers(GLsizei n, GLuint* framebuffers) {
    if (n < 0) { pushError(GL_INVALID_VALUE); return false; }
    for (GLsizei i = 0; i < n; ++i) {
        framebuffers[i] = impl_->objects->framebuffers().reserveName();
        auto* obj = impl_->objects->framebuffers().get(framebuffers[i]);
        if (obj) obj->instantiated = true;
    }
    return true;
}

bool GLContext::createRenderbuffers(GLsizei n, GLuint* renderbuffers) {
    if (n < 0) { pushError(GL_INVALID_VALUE); return false; }
    for (GLsizei i = 0; i < n; ++i) {
        renderbuffers[i] = impl_->objects->renderbuffers().reserveName();
        auto* obj = impl_->objects->renderbuffers().get(renderbuffers[i]);
        if (obj) obj->instantiated = true;
    }
    return true;
}

bool GLContext::createVertexArrays(GLsizei n, GLuint* arrays) {
    if (n < 0) { pushError(GL_INVALID_VALUE); return false; }
    for (GLsizei i = 0; i < n; ++i) {
        arrays[i] = impl_->objects->vertexArrays().reserveName();
        if (auto* obj = impl_->objects->vertexArrays().get(arrays[i])) {
            obj->instantiated = true;
            // GL 4.5 §10.3.1 — glCreateVertexArrays instantiates the
            // object up-front (unlike glGenVertexArrays which defers
            // to first bind). DSA state queries like
            // glGetVertexArrayIndexediv / glVertexArrayAttribFormat
            // are callable immediately after createVertexArrays, so
            // the attribute + binding-point vectors need to carry
            // their spec-defined defaults (SIZE=4, TYPE=GL_FLOAT,
            // bindingIndex=i, binding stride=16). Without this
            // init, the default test queries return 0 for SIZE /
            // TYPE because the attributes vector is empty.
            impl_->objects->initializeVertexArray(*obj);
        }
    }
    return true;
}

bool GLContext::createTransformFeedbacks(GLsizei n, GLuint* ids) {
    if (n < 0) { pushError(GL_INVALID_VALUE); return false; }
    for (GLsizei i = 0; i < n; ++i) {
        ids[i] = impl_->objects->transformFeedbacks().reserveName();
        auto* obj = impl_->objects->transformFeedbacks().get(ids[i]);
        if (obj) {
            // DSA glCreateTransformFeedbacks instantiates up-front
            // per GL 4.5 §13.2 (no first-bind required).
            obj->instantiated = true;
        }
    }
    return true;
}

bool GLContext::createProgramPipelines(GLsizei n, GLuint* pipelines) {
    if (n < 0) { pushError(GL_INVALID_VALUE); return false; }
    for (GLsizei i = 0; i < n; ++i) {
        pipelines[i] = impl_->objects->programPipelines().reserveName();
        auto* obj = impl_->objects->programPipelines().get(pipelines[i]);
        if (obj) {
            // DSA glCreateProgramPipelines instantiates up-front.
            obj->instantiated = true;
        }
    }
    return true;
}

bool GLContext::deleteProgramPipelines(GLsizei n, const GLuint* pipelines) {
    if (n < 0 || (n > 0 && pipelines == nullptr)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const GLuint boundPipeline = impl_->state->currentProgramPipeline();
    for (GLsizei i = 0; i < n; ++i) {
        const GLuint name = pipelines[i];
        if (name == 0) {
            continue;
        }
        std::array<GLuint, 7> referencedPrograms{};
        if (name == boundPipeline) {
            impl_->state->setCurrentProgramPipeline(0);
        }
        if (GLProgramPipelineObject* pipeline = impl_->objects->programPipelines().get(name);
            pipeline != nullptr) {
            referencedPrograms = {
                pipeline->vertexProgram,
                pipeline->fragmentProgram,
                pipeline->geometryProgram,
                pipeline->tessControlProgram,
                pipeline->tessEvalProgram,
                pipeline->computeProgram,
                pipeline->activeShaderProgram,
            };
            impl_->releaseProgramPipelineResources(*pipeline);
        }
        impl_->objects->programPipelines().erase(name);
        for (GLuint program : referencedPrograms) {
            impl_->finalizeDeletedProgramIfUnused(program);
        }
    }
    return true;
}

bool GLContext::createQueries(GLenum target, GLsizei n, GLuint* ids) {
    if (n < 0) { pushError(GL_INVALID_VALUE); return false; }
    // GL 4.5 §4.2.1: INVALID_ENUM if target is not one of the accepted query
    // targets. Without this, CTS direct_state_access.queries_errors hangs
    // indefinitely in the post-fail drain loop
    // `while (error == gl.getError()) ;` because it captured GL_NO_ERROR
    // (since we silently accepted the invalid target and set no error).
    switch (target) {
        case GL_SAMPLES_PASSED:
        case GL_ANY_SAMPLES_PASSED:
        case GL_ANY_SAMPLES_PASSED_CONSERVATIVE:
        case GL_PRIMITIVES_GENERATED:
        case GL_TRANSFORM_FEEDBACK_PRIMITIVES_WRITTEN:
        case GL_TIME_ELAPSED:
        case GL_TIMESTAMP:
            break;
        default:
            pushError(GL_INVALID_ENUM);
            return false;
    }
    for (GLsizei i = 0; i < n; ++i) {
        ids[i] = impl_->objects->queries().reserveName();
        auto* obj = impl_->objects->queries().get(ids[i]);
        if (obj) {
            obj->target = target;
            // DSA glCreateQueries creates fully-instantiated query
            // objects — glIsQuery returns TRUE immediately without
            // a subsequent glBeginQuery.
            obj->instantiated = true;
        }
    }
    return true;
}

// ---------------------------------------------------------------------------
// GL 4.5 — DSA buffer operations.
// All delegate to existing bind-target implementations via save/restore.
// ---------------------------------------------------------------------------

bool GLContext::namedBufferStorage(GLuint buffer, GLsizeiptr size, const void* data, GLbitfield flags) {
    auto* obj = impl_->objects->buffers().get(buffer);
    if (!obj) { pushError(GL_INVALID_OPERATION); return false; }
    GLenum target = GL_ARRAY_BUFFER;
    GLuint prev = impl_->state->boundBuffer(target);
    impl_->state->bindBuffer(target, buffer);
    bool ok = bufferStorage(target, size, data, flags);
    impl_->state->bindBuffer(target, prev);
    return ok;
}

bool GLContext::namedBufferPageCommitment(GLuint buffer, GLintptr offset, GLsizeiptr size, GLboolean commit) {
    auto* obj = impl_->objects->buffers().get(buffer);
    if (!obj || !obj->instantiated || !obj->sparseStorage) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    GLenum target = GL_ARRAY_BUFFER;
    GLuint prev = impl_->state->boundBuffer(target);
    impl_->state->bindBuffer(target, buffer);
    bool ok = bufferPageCommitment(target, offset, size, commit);
    impl_->state->bindBuffer(target, prev);
    return ok;
}

