bool GLContext::namedRenderbufferStorage(GLuint renderbuffer, GLenum internalformat, GLsizei width, GLsizei height) {
    auto* obj = impl_->objects->renderbuffers().get(renderbuffer);
    if (!obj) { pushError(GL_INVALID_OPERATION); return false; }
    GLuint prev = impl_->state->boundRenderbuffer();
    impl_->state->bindRenderbuffer(renderbuffer);
    bool ok = renderbufferStorage(GL_RENDERBUFFER, internalformat, width, height, 0);
    impl_->state->bindRenderbuffer(prev);
    return ok;
}

bool GLContext::namedRenderbufferStorageMultisample(GLuint renderbuffer, GLsizei samples, GLenum internalformat, GLsizei width, GLsizei height) {
    auto* obj = impl_->objects->renderbuffers().get(renderbuffer);
    if (!obj) { pushError(GL_INVALID_OPERATION); return false; }
    GLuint prev = impl_->state->boundRenderbuffer();
    impl_->state->bindRenderbuffer(renderbuffer);
    bool ok = renderbufferStorage(GL_RENDERBUFFER, internalformat, width, height, samples);
    impl_->state->bindRenderbuffer(prev);
    return ok;
}

bool GLContext::getNamedRenderbufferParameteriv(GLuint renderbuffer, GLenum pname, GLint* params) {
    auto* obj = impl_->objects->renderbuffers().get(renderbuffer);
    if (!obj) { pushError(GL_INVALID_OPERATION); return false; }
    GLuint prev = impl_->state->boundRenderbuffer();
    impl_->state->bindRenderbuffer(renderbuffer);
    bool ok = getRenderbufferParameterInteger(GL_RENDERBUFFER, pname, params);
    impl_->state->bindRenderbuffer(prev);
    return ok;
}

// ---------------------------------------------------------------------------
// GL 4.5 — DSA vertex array operations.
// ---------------------------------------------------------------------------

#define DSA_VAO_CHECK(vaobj) \
    auto* _vao = impl_->objects->vertexArrays().get(vaobj); \
    if (!_vao) { pushError(GL_INVALID_OPERATION); return false; }

#define DSA_VAO_WRAP(vaobj, body) \
    DSA_VAO_CHECK(vaobj) \
    GLuint _prevVAO = impl_->state->boundVertexArray(); \
    impl_->state->bindVertexArray(vaobj); \
    body \
    impl_->state->bindVertexArray(_prevVAO);

bool GLContext::vertexArrayAttribFormat(GLuint vaobj, GLuint attribindex, GLint size, GLenum type, GLboolean normalized, GLuint relativeoffset) {
    DSA_VAO_WRAP(vaobj, {
        bool ok = vertexAttribFormat(attribindex, size, type, normalized, relativeoffset);
        return ok;
    })
}

bool GLContext::vertexArrayAttribIFormat(GLuint vaobj, GLuint attribindex, GLint size, GLenum type, GLuint relativeoffset) {
    DSA_VAO_WRAP(vaobj, {
        bool ok = vertexAttribIFormat(attribindex, size, type, relativeoffset);
        return ok;
    })
}

bool GLContext::vertexArrayAttribLFormat(GLuint vaobj, GLuint attribindex, GLint size, GLenum type, GLuint relativeoffset) {
    DSA_VAO_WRAP(vaobj, {
        bool ok = vertexAttribLFormat(attribindex, size, type, relativeoffset);
        return ok;
    })
}

bool GLContext::vertexArrayAttribBinding(GLuint vaobj, GLuint attribindex, GLuint bindingindex) {
    DSA_VAO_WRAP(vaobj, {
        bool ok = vertexAttribBinding(attribindex, bindingindex);
        return ok;
    })
}

bool GLContext::vertexArrayBindingDivisor(GLuint vaobj, GLuint bindingindex, GLuint divisor) {
    DSA_VAO_WRAP(vaobj, {
        bool ok = vertexBindingDivisor(bindingindex, divisor);
        return ok;
    })
}

bool GLContext::vertexArrayVertexBuffer(GLuint vaobj, GLuint bindingindex, GLuint buffer, GLintptr offset, GLsizei stride) {
    DSA_VAO_WRAP(vaobj, {
        bool ok = bindVertexBuffer(bindingindex, buffer, offset, stride);
        return ok;
    })
}

bool GLContext::vertexArrayVertexBuffers(GLuint vaobj, GLuint first, GLsizei count, const GLuint* buffers, const GLintptr* offsets, const GLsizei* strides) {
    DSA_VAO_WRAP(vaobj, {
        bool ok = bindVertexBuffers(first, count, buffers, offsets, strides);
        return ok;
    })
}

bool GLContext::vertexArrayElementBuffer(GLuint vaobj, GLuint buffer) {
    DSA_VAO_CHECK(vaobj)
    // GL 4.5 §10.3.1: buffer must be zero or an existing buffer name.
    // CTS `direct_state_access.vertex_arrays_element_buffer_errors`
    // plants a never-generated buffer ID and asserts INVALID_OPERATION.
    if (buffer != 0 && !impl_->objects->buffers().contains(buffer)) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    _vao->elementArrayBuffer = buffer;
    return true;
}

bool GLContext::enableVertexArrayAttrib(GLuint vaobj, GLuint index) {
    DSA_VAO_WRAP(vaobj, {
        bool ok = enableVertexAttribArray(index, true);
        return ok;
    })
}

bool GLContext::disableVertexArrayAttrib(GLuint vaobj, GLuint index) {
    DSA_VAO_WRAP(vaobj, {
        bool ok = enableVertexAttribArray(index, false);
        return ok;
    })
}

bool GLContext::getVertexArrayiv(GLuint vaobj, GLenum pname, GLint* param) {
    DSA_VAO_CHECK(vaobj)
    // GL 4.5 §10.3.12: pname is restricted to
    // GL_ELEMENT_ARRAY_BUFFER_BINDING for `glGetVertexArrayiv`
    // (no other enum is accepted at the per-VAO level). CTS
    // `direct_state_access.vertex_arrays_get_vertex_array_errors`
    // plants a bogus pname and asserts INVALID_ENUM.
    if (pname != GL_ELEMENT_ARRAY_BUFFER_BINDING) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (param) {
        *param = static_cast<GLint>(_vao->elementArrayBuffer);
    }
    return true;
}

// GL 4.5 §10.3.12: accepted pnames for glGetVertexArrayIndexed{,64}iv.
static bool isValidVertexArrayIndexedPname(GLenum pname) {
    switch (pname) {
        case GL_VERTEX_ATTRIB_ARRAY_ENABLED:
        case GL_VERTEX_ATTRIB_ARRAY_SIZE:
        case GL_VERTEX_ATTRIB_ARRAY_STRIDE:
        case GL_VERTEX_ATTRIB_ARRAY_TYPE:
        case GL_VERTEX_ATTRIB_ARRAY_NORMALIZED:
        case GL_VERTEX_ATTRIB_ARRAY_INTEGER:
        case GL_VERTEX_ATTRIB_ARRAY_LONG:
        case GL_VERTEX_ATTRIB_ARRAY_DIVISOR:
        case GL_VERTEX_ATTRIB_RELATIVE_OFFSET:
            return true;
        default:
            return false;
    }
}

bool GLContext::getVertexArrayIndexediv(GLuint vaobj, GLuint index, GLenum pname, GLint* param) {
    DSA_VAO_CHECK(vaobj)
    if (!isValidVertexArrayIndexedPname(pname)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    // GL 4.5 §10.3.12: `index` is an attribute index for the
    // per-attribute pnames; GL_INVALID_VALUE if out of range.
    if (index >= _vao->attributes.size()) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (param == nullptr) return true;
    const auto& attr = _vao->attributes[index];
    switch (pname) {
        case GL_VERTEX_ATTRIB_ARRAY_ENABLED:
            *param = attr.enabled ? GL_TRUE : GL_FALSE;
            return true;
        case GL_VERTEX_ATTRIB_ARRAY_SIZE:
            *param = attr.size;
            return true;
        case GL_VERTEX_ATTRIB_ARRAY_STRIDE:
            // GL 4.6 Table 22.3 per-attribute state — independent from
            // VERTEX_BINDING_STRIDE (Table 22.4 per-binding state).
            // Returns the stride set via glVertexAttribPointer or
            // glVertexAttribIPointer, default 0. CTS
            // `vertex_arrays_get_vertex_array_indexed` asserts 0 on a
            // fresh VAO even though the binding-point stride defaults
            // to 16.
            *param = attr.stride;
            return true;
        case GL_VERTEX_ATTRIB_ARRAY_TYPE:
            *param = static_cast<GLint>(attr.type);
            return true;
        case GL_VERTEX_ATTRIB_ARRAY_NORMALIZED:
            *param = attr.normalized ? GL_TRUE : GL_FALSE;
            return true;
        case GL_VERTEX_ATTRIB_ARRAY_INTEGER:
            *param = attr.integer ? GL_TRUE : GL_FALSE;
            return true;
        case GL_VERTEX_ATTRIB_ARRAY_LONG:
            *param = attr.longData ? GL_TRUE : GL_FALSE;
            return true;
        case GL_VERTEX_ATTRIB_ARRAY_DIVISOR:
            if (attr.bindingIndex < _vao->bindingPoints.size()) {
                *param = static_cast<GLint>(_vao->bindingPoints[attr.bindingIndex].divisor);
            } else {
                *param = static_cast<GLint>(attr.divisor);
            }
            return true;
        case GL_VERTEX_ATTRIB_RELATIVE_OFFSET:
            *param = static_cast<GLint>(attr.relativeOffset);
            return true;
    }
    // Should be unreachable — isValidVertexArrayIndexedPname gated.
    *param = 0;
    return true;
}

bool GLContext::getVertexArrayIndexed64iv(GLuint vaobj, GLuint index, GLenum pname, GLint64* param) {
    DSA_VAO_CHECK(vaobj)
    // GL 4.5 §10.3.12: The 64-bit form only accepts
    // GL_VERTEX_BINDING_OFFSET — it's the 64-bit buffer offset from
    // the attribute's binding point.
    if (pname != GL_VERTEX_BINDING_OFFSET) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (index >= _vao->attributes.size()) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (param == nullptr) return true;
    const auto& attr = _vao->attributes[index];
    if (attr.bindingIndex < _vao->bindingPoints.size()) {
        *param = static_cast<GLint64>(_vao->bindingPoints[attr.bindingIndex].offset);
    } else {
        *param = 0;
    }
    return true;
}

#undef DSA_VAO_WRAP
#undef DSA_VAO_CHECK

// ---------------------------------------------------------------------------
// GL 4.5 — DSA transform feedback operations.
// ---------------------------------------------------------------------------

bool GLContext::transformFeedbackBufferBase(GLuint xfb, GLuint index, GLuint buffer) {
    auto* obj = impl_->objects->transformFeedbacks().get(xfb);
    if (!obj) { pushError(GL_INVALID_OPERATION); return false; }
    if (index >= GLTransformFeedbackObject::kMaxTfBuffers) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (buffer != 0) {
        GLBufferObject* bufferObject = impl_->objects->buffers().get(buffer);
        if (bufferObject == nullptr) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
        bufferObject->instantiated = true;
    }
    // Record the per-TF-object binding for the DSA getter queries
    // (getTransformFeedbacki_v / getTransformFeedbacki64_v).
    obj->bufferBindings[index] = {buffer, 0, 0};
    if (xfb == impl_->boundTransformFeedbackId) {
        impl_->state->bindIndexedBuffer(GL_TRANSFORM_FEEDBACK_BUFFER,
                                        index, buffer, 0, 0);
        impl_->state->bindBuffer(GL_TRANSFORM_FEEDBACK_BUFFER, buffer);
    }
    impl_->touchR5Residency(MetalR5ResidencyTouchKind::BufferBind);
    return true;
}

bool GLContext::transformFeedbackBufferRange(GLuint xfb, GLuint index, GLuint buffer, GLintptr offset, GLsizeiptr size) {
    auto* obj = impl_->objects->transformFeedbacks().get(xfb);
    if (!obj) { pushError(GL_INVALID_OPERATION); return false; }
    if (index >= GLTransformFeedbackObject::kMaxTfBuffers) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (offset < 0 || size < 0 ||
        (offset % 4) != 0 ||
        (size % 4) != 0 ||
        (buffer != 0 && size <= 0)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (buffer != 0) {
        GLBufferObject* bufferObject = impl_->objects->buffers().get(buffer);
        if (bufferObject == nullptr) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
        bufferObject->instantiated = true;
    }
    obj->bufferBindings[index] = {buffer, offset, size};
    if (xfb == impl_->boundTransformFeedbackId) {
        impl_->state->bindIndexedBuffer(GL_TRANSFORM_FEEDBACK_BUFFER,
                                        index, buffer, offset, size);
        impl_->state->bindBuffer(GL_TRANSFORM_FEEDBACK_BUFFER, buffer);
    }
    impl_->touchR5Residency(MetalR5ResidencyTouchKind::BufferBind);
    return true;
}

bool GLContext::getTransformFeedbackiv(GLuint xfb, GLenum pname, GLint* param) {
    auto* obj = impl_->objects->transformFeedbacks().get(xfb);
    if (!obj) { pushError(GL_INVALID_OPERATION); return false; }
    // GL 4.5 §13.2.4: pname restricted to the boolean state enums.
    // CTS `direct_state_access.xfb_errors` plants a bogus pname and
    // asserts INVALID_ENUM; any write to the output buffer on the
    // error path is forbidden.
    if (pname != GL_TRANSFORM_FEEDBACK_ACTIVE &&
        pname != GL_TRANSFORM_FEEDBACK_PAUSED) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (param) {
        if (pname == GL_TRANSFORM_FEEDBACK_ACTIVE) *param = obj->active ? GL_TRUE : GL_FALSE;
        else *param = obj->paused ? GL_TRUE : GL_FALSE;
    }
    return true;
}

bool GLContext::getTransformFeedbacki_v(GLuint xfb, GLenum pname, GLuint index, GLint* param) {
    auto* obj = impl_->objects->transformFeedbacks().get(xfb);
    if (!obj) { pushError(GL_INVALID_OPERATION); return false; }
    // GL 4.5 §13.2.4: indexed 32-bit query only accepts
    // TRANSFORM_FEEDBACK_BUFFER_BINDING.
    if (pname != GL_TRANSFORM_FEEDBACK_BUFFER_BINDING) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    GLint64 maxXfbBuffers = 4;
    if (impl_->capabilities != nullptr) {
        impl_->capabilities->queryInteger64(
            GL_MAX_TRANSFORM_FEEDBACK_BUFFERS, &maxXfbBuffers);
    }
    if (index >= static_cast<GLuint>(maxXfbBuffers)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (param) {
        if (index < GLTransformFeedbackObject::kMaxTfBuffers) {
            *param = static_cast<GLint>(obj->bufferBindings[index].buffer);
        } else {
            *param = 0;
        }
    }
    return true;
}

bool GLContext::getTransformFeedbacki64_v(GLuint xfb, GLenum pname, GLuint index, GLint64* param) {
    auto* obj = impl_->objects->transformFeedbacks().get(xfb);
    if (!obj) { pushError(GL_INVALID_OPERATION); return false; }
    // GL 4.5 §13.2.4: 64-bit indexed query accepts
    // TRANSFORM_FEEDBACK_BUFFER_{START, SIZE}.
    if (pname != GL_TRANSFORM_FEEDBACK_BUFFER_START &&
        pname != GL_TRANSFORM_FEEDBACK_BUFFER_SIZE) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    GLint64 maxXfbBuffers = 4;
    if (impl_->capabilities != nullptr) {
        impl_->capabilities->queryInteger64(
            GL_MAX_TRANSFORM_FEEDBACK_BUFFERS, &maxXfbBuffers);
    }
    if (index >= static_cast<GLuint>(maxXfbBuffers)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (param) {
        if (index < GLTransformFeedbackObject::kMaxTfBuffers) {
            const auto& bind = obj->bufferBindings[index];
            if (pname == GL_TRANSFORM_FEEDBACK_BUFFER_START) {
                *param = static_cast<GLint64>(bind.offset);
            } else {  // GL_TRANSFORM_FEEDBACK_BUFFER_SIZE
                *param = static_cast<GLint64>(bind.size);
            }
        } else {
            *param = 0;
        }
    }
    return true;
}

// ---------------------------------------------------------------------------
// GL 4.5 — ClipControl, robustness APIs, barriers, query buffer objects
// ---------------------------------------------------------------------------

bool GLContext::clipControl(GLenum origin, GLenum depth) {
    if (origin != GL_LOWER_LEFT && origin != GL_UPPER_LEFT) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (depth != GL_NEGATIVE_ONE_TO_ONE && depth != GL_ZERO_TO_ONE) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    impl_->state->setClipOrigin(origin);
    impl_->state->setClipDepthMode(depth);
    return true;
}

GLenum GLContext::getGraphicsResetStatus() {
    return GL_NO_ERROR;
}

bool GLContext::readnPixels(GLint x, GLint y, GLsizei width, GLsizei height,
                            GLenum format, GLenum type, GLsizei bufSize, void* data) {
    if (bufSize < 0) { pushError(GL_INVALID_VALUE); return false; }
    return readPixels(x, y, width, height, format, type, data);
}

